import jwt
from flask import Flask, request
from datetime import timedelta

app = Flask(__name__)

# Generate a token
def generate_token(user):
    # Define the token claims
    claims = {
        'sub': user.id,
        'exp': time.time() + timedelta(minutes=10).total_seconds(),
        'iat': time.time(),
        'iss': 'your-issuer',
        'aud': 'your-audience'
    }

    # Sign the token
    token = jwt.encode(claims, key='your-secret-key', algorithm='HS256')
    return token.decode('utf-8')

# Verify a token
def verify_token(token):
    try:
        decoded_token = jwt.decode(token, key='your-secret-key', algorithms=['HS256'])
        user_id = decoded_token['sub']
        return user_id
    except jwt.ExpiredSignatureError:
        return None
    except jwt.JWTClaimsError:
        return None
    except Exception as e:
        print(f'Error verifying token: {e}')
        return None

# Use the tokens for authentication
@app.route('/protected-page', methods=['GET'])
def protected_page():
    # Get the access token from the request headers
    auth_header = request.headers.get('Authorization')
    if not auth_header:
        return 'Authentication required', 401

    # Verify the token and get the user ID
    try:
        user_id = verify_token(auth_header)
        if user_id is None:
            return 'Invalid token', 403
    except Exception as e:
        print(f'Error verifying token: {e}')
        return 'Invalid token', 403

    # Get the user data from the database using the user ID
    user = get_user_by_id(user_id)
    if not user:
        return 'User not found', 404

    # Render the protected page for the user
    return render_template('protected-page.html', user=user)

