import time

# Set the number of requests per minute
requests_per_minute = 10

# Set the time period for which requests are limited (in seconds)
time_period = 60

# Initialize a counter for the number of requests made within the time period
num_requests = 0

def rate_limit(func):
    def wrapper(*args, **kwargs):
        nonlocal num_requests
        if num_requests < requests_per_minute:
            num_requests += 1
            return func(*args, **kwargs)
        else:
            time.sleep(time_period - (time.time() % time_period))
            num_requests = 0
    return wrapper

@rate_limit
def my_api():
    print("API request made")

my_api()

