import re

def validate_url(url):
    pattern = r'^(?:http|ftp)s?://' # http:// or https://
    pattern += r'(?:(?:[A-Z0-9](?:[A-Z0-9-]{0,61}[A-Z0-9])?\.)+)(?:[\.]{0,2}[A-Z]{2,6}\.?|[A-Z0-9-]{2,}\.?)' # domain...
    pattern += r'(?::\d{2,5})?(?:[/?#]\S*)?$' # path
    if re.match(pattern, url):
        return True
    else:
        return False

