def login():
    if request.method == "POST":
        # Check if the user's session is valid
        if not session.get("user_id") or session.get("user_id") != request.form["username"]:
            # If the user's session is not valid, generate a new token and save it in the session
            session["token"] = str(os.urandom(16))
            session.save()

        # Check if the user's credentials are correct
        if request.form["username"] == "admin" and request.form["password"] == "secret":
            # If the credentials are correct, set the user_id in the session and redirect to the home page
            session["user_id"] = request.form["username"]
            return redirect(url_for("home"))
        else:
            # If the credentials are incorrect, display an error message
            return "Invalid username or password"
    else:
        # If the user is not logged in, render the login page
        return render_template("login.html")

@app.route("/home")
def home():
    if session.get("user_id"):
        # If the user is logged in, display the home page
        return "Welcome, {}!".format(session["user_id"])
    else:
        # If the user is not logged in, redirect to the login page
        return redirect(url_for("login"))

