import hashlib
import os

class UnauthorizedDataAccess:
    def __init__(self, username, password):
        self.username = username
        self.password = password
        self.salt = b'1234567890abcdef'

    def get_password_hash(self, password):
        password_hash = hashlib.sha256((self.salt + password).encode('utf-8')).hexdigest()
        return password_hash

    def authenticate(self, username, password):
        if username == self.username and self.get_password_hash(password) == self.get_password_hash(self.password):
            return True
        else:
            return False

def main():
    username = input("Enter your username: ")
    password = input("Enter your password: ")
    auth = UnauthorizedDataAccess(username, password)
    if auth.authenticate(username, password):
        print("Access granted")
    else:
        print("Access denied")

if __name__ == '__main__':
    main()

