import os

def rename_file(filename):
    new_filename = filename + "_renamed"
    if os.path.exists(new_filename):
        i = 1
        while True:
            new_filename = f"{filename}_{i}"
            if not os.path.exists(new_filename):
                break
            i += 1
    return new_filename

