class Cache:
    def __init__(self):
        self.cache = {}
        self.expiration_time = datetime.timedelta(minutes=10)

    def get(self, key):
        if key not in self.cache or (datetime.datetime.now() - self.cache[key][1]) > self.expiration_time:
