import time

class CacheEvictionPolicy:
    def __init__(self, block_size):
        self.block_size = block_size
        self.cache = {}

    def get_next_block(self):
        # Implement the eviction policy here
        if len(self.cache) >= self.block_size:
            min_access_time = float('inf')
            for key in self.cache:
                if self.cache[key]['last_access_time'] < min_access_time:
                    min_access_time = self.cache[key]['last_access_time']
                    min_key = key
            del self.cache[min_key]
        return -1

