def search_by_filters(data, filters):
    # Initialize an empty list to store the results
    results = []

    # Loop through each filter and apply it to the data
    for key, value in filters.items():
        # Check if the current filter is a range filter
        if type(value) == tuple:
            # Get the min and max values of the range filter
            min_val = value[0]
            max_val = value[1]

            # Loop through each item in the data and check if it falls within the range
            for item in data:
                if min_val <= item[key] <= max_val:
                    results.append(item)
        else:
            # Check if the current filter is a string filter
            if type(value) == str:
                # Loop through each item in the data and check if it contains the string
                for item in data:
                    if value in item[key]:
                        results.append(item)
            else:
                # Check if the current filter is a list filter
                if type(value) == list:
                    # Loop through each item in the data and check if it contains any of the items in the list
                    for item in data:
                        for val in value:
                            if val in item[key]:
                                results.append(item)

    return results

