import time

class RateLimiter:
    def __init__(self, max_requests=100, time_window=60):
        self.max_requests = max_requests
        self.time_window = time_window
        self.request_count = 0
        self.last_request_time = 0

    def limit(self):
        current_time = time.time()
        if current_time - self.last_request_time < self.time_window:
            self.request_count += 1
            if self.request_count > self.max_requests:
                raise TooManyRequestsError("Too many requests")
        else:
            self.request_count = 0
            self.last_request_time = current_time

import socket

class IPBanHandler:
    def __init__(self):
        self.banned_ips = []

    def ban_ip(self, ip_address):
        if not self.is_ip_banned(ip_address):
            self.banned_ips.append(ip_address)
            print("IP address", ip_address, "has been banned")
        else:
            print("IP address", ip_address, "already banned")

    def unban_ip(self, ip_address):
        if self.is_ip_banned(ip_address):
            self.banned_ips.remove(ip_address)
            print("IP address", ip_address, "has been unbanned")
        else:
            print("IP address", ip_address, "not banned")

    def is_ip_banned(self, ip_address):
        return ip_address in self.banned_ips

