import PyPDF2

def validate_pdf(file):
    with open(file, 'rb') as f:
        pdf = PyPDF2.PdfFileReader(f)
        if pdf.is_encrypted:
            return False
        if pdf.numPages == 0:
            return False
        for page in pdf.pages:
