# Define a decorator to handle the API key for each request
def api_key_required(f):
    @wraps(f)
    def wrapper(*args, **kwargs):
        # Get the API key from the request headers
        api_key = request.headers.get("X-API-Key")

        # Check if the API key is valid for the current tenant
        if api_key != get_api_key(request.args["tenant_id"]):
            return jsonify({"error": "Invalid API key"}), 401

        # Proceed with the request handling if the API key is valid
        return f(*args, **kwargs)
    return wrapper

