import datetime

def schedule_report_generation(start_date, end_date):
    # Create a dictionary to store the scheduling information
    schedule = {}

    # Iterate through each day between the start and end dates
    for date in range(start_date, end_date + datetime.timedelta(days=1)):
        # Check if the current day is a weekday (Monday to Friday)
        if date.weekday() < 5:
            # If it is a weekday, add it to the schedule
            schedule[date] = "Report Generation"

    return schedule

def validate_report_parameters(parameters):
    # Check if the "from" and "to" parameters are valid dates
    try:
        from_date = datetime.strptime(parameters["from"], "%Y-%m-%d")
        to_date = datetime.strptime(parameters["to"], "%Y-%m-%d")
    except ValueError:
        raise ValueError("Invalid date format, should be YYYY-MM-DD")

    # Check if the "from" parameter is before the "to" parameter
    if from_date > to_date:
        raise ValueError("The 'from' date must be before the 'to' date")

    # Check if the "type" parameter is valid
    try:
        report_type = parameters["type"]
    except KeyError:
        raise KeyError("Missing required parameter: type")
    if report_type not in ["daily", "weekly", "monthly"]:
        raise ValueError("Invalid report type, should be 'daily', 'weekly' or 'monthly'")

    # Check if the "period" parameter is valid
    try:
        period = parameters["period"]
    except KeyError:
        raise KeyError("Missing required parameter: period")
    if period not in ["7d", "30d", "90d"]:
        raise ValueError("Invalid report period, should be '7d', '30d' or '90d'")

    # Return the validated parameters
    return {
        "from": from_date.strftime("%Y-%m-%d"),
        "to": to_date.strftime("%Y-%m-%d"),
        "type": report_type,
        "period": period
    }

