def validate_address(address):
    # Check if the address is a valid string
    if not isinstance(address, str):
        return False

    # Split the address into lines
    lines = address.splitlines()

    # Check if there are at least 2 lines in the address
    if len(lines) < 2:
        return False

    # Check if the first line is a valid street address
    if not validate_street_address(lines[0]):
        return False

    # Check if the second line is a valid city and state combination
    if not validate_city_state(lines[1]):
        return False

    # Check if the third line is a valid zip code
    if not validate_zip_code(lines[2]):
        return False

    return True

def validate_street_address(address):
    # Check if the street address is a valid string
    if not isinstance(address, str):
        return False

    # Check if the street address contains only letters and numbers
    if not re.match(r"^[A-Za-z0-9 ]+$", address):
        return False

    # Check if the street address has at least 2 words
    words = address.split()
    if len(words) < 2:
        return False

    # Check if the first word is a valid street name
    if not re.match(r"^[A-Za-z ]+$", words[0]):
        return False

    # Check if the second word is a valid house number
    try:
        int(words[1])
    except ValueError:
        return False

    return True

def validate_city_state(address):
    # Check if the city and state combination is a valid string
    if not isinstance(address, str):
        return False

    # Split the address into lines
    lines = address.splitlines()

    # Check if there are at least 2 lines in the address
    if len(lines) < 2:
        return False

    # Check if the first line is a valid city name
    if not re.match(r"^[A-Za-z ]+$", lines[0]):
        return False

    # Check if the second line is a valid state abbreviation
    if not re.match(r"^[A-Z]{2}$", lines[1]):
        return False

    return True

def validate_zip_code(address):
    # Check if the zip code is a valid string
    if not isinstance(address, str):
        return False

    # Split the address into lines
    lines = address.splitlines()

    # Check if there are at least 2 lines in the address
    if len(lines) < 2:
        return False

    # Check if the second line is a valid zip code
    if not re.match(r"^\d{5}$", lines[1]):
        return False

    return True

import requests
import json

class BlockchainMonitor:
    def __init__(self, node_url):
        self.node_url = node_url

    def get_blockchain_info(self):
        response = requests.get(f"{self.node_url}/api/v1/status")
        if response.ok:
            return json.loads(response.content)
        else:
            print("Failed to get blockchain info")

    def get_block_height(self):
        response = requests.get(f"{self.node_url}/api/v1/status")
        if response.ok:
            return json.loads(response.content)['blockHeight']
        else:
            print("Failed to get block height")

    def get_peer_count(self):
        response = requests.get(f"{self.node_url}/api/v1/status")
        if response.ok:
            return json.loads(response.content)['peerCount']
        else:
            print("Failed to get peer count")

if __name__ == "__main__":
    monitor = BlockchainMonitor("https://blockchain-api.com/api/v1")
    blockchain_info = monitor.get_blockchain_info()
    print(f"Blockchain Info: {blockchain_info}")
    block_height = monitor.get_block_height()
    print(f"Current Block Height: {block_height}")
    peer_count = monitor.get_peer_count()
    print(f"Number of Peers: {peer_count}")
```
This program uses the `requests` library to send HTTP requests to a blockchain API and retrieve information about the blockchain, such as the current block height and number of peers connected. The `json` library is used to parse the JSON response from the API and extract the relevant data.

The program first initializes an instance of the `BlockchainMonitor` class with a node URL. It then defines three methods: `get_blockchain_info`, `get_block_height`, and `get_peer_count`. These methods send HTTP requests to the API using the `requests.get()` method and parse the JSON response using the `json.loads()` method.

The `main` function is where the program is run. It creates an instance of the `BlockchainMonitor` class and calls each of its methods to retrieve information about the blockchain. The output is then printed to the console.

Note that this program assumes that the API endpoint at the specified URL returns JSON data in the expected format. If the API endpoint does not return the expected data, the program may not function as intended.

