class UserAccount(object):
    def __init__(self, username, password):
        self.username = username
        self.password = password
        self.attempts = 0
        self.lockout = False

    def login(self, username, password):
        if not self.lockout:
            if username == self.username and password == self.password:
                print("Login Successful.")
                self.attempts = 0  # reset attempts on successful login
                return True
            else:
                self.failed_login()
        else:
            print('Your account is currently locked out due to excessive failed attempts.')

    def failed_login(self):
        self.attempts += 1
        if self.attempts >= 3:  # lockout after 3 failed attempts
            self.lockout = True
            print('Too many failed login attempts, your account is locked out temporarily.')

