from flask import Flask, jsonify, request
from werkzeug.security import generate_password_hash, check_password_hash
import os
from flask_jwt_extended import (JWTManager, jwt_required, create_access_token, get_jwt_identity)

app = Flask(__name__)
app.config['JWT_SECRET_KEY'] = os.urandom(24)  # Generating a random secret key at each start-up of the application.
jwt = JWTManager(app)

# This is our "database". In a real application, this would be your User model.
users = {
    "user1": generate_password_hash(os.getenv("USER_PASSWORD"))  # username: hashed password
}

@app.route('/login', methods=['POST'])
def login():
    username = request.json.get('username')
    password = request.json.get('password')

    if not (username and password):
        return jsonify({'message': 'Missing credentials'}), 400

    if username in users and check_password_hash(users[username], password):
        access_token = create_access_token(identity=username)
        return jsonify(access_token=access_token), 200

    return jsonify({'message': 'Invalid credentials'}), 401

@app.route('/protected', methods=['GET'])
@jwt_required()
def protected():
    # Access the identity of the current user with get_jwt_identity
    current_user = get_jwt_identity()
    return jsonify(logged_in_as=current_user), 200

if __name__ == '__main__':
    app.run(port=5000, debug=False)  # Debug mode is disabled.

