class User:
    def __init__(self, name, role):
        self.name = name
        self.role = role

class Resource:
    def __init__(self, name, owner):
        self.name = name
        self.owner = owner

def validate_access(user, resource, operation):
    if user.role == "admin":
        return True  # Admin can do anything
    elif user.role == "editor" and operation in ["read", "write"]:
        return True  # Editors can read or write to any resource
    elif user.name == resource.owner and operation in ["read", "delete"]:
        return True  # The owner of a resource can only delete their own resources

    return False  # Default deny

