import requests
import json

def get_data(url, timeout=5):     # Added a default timeout here
    try:
        response = requests.get(url, timeout=timeout)   # Using the passed or default timeout

        if response.status_code == 200:
            data = response.json()     # Convert the json response into a python dictionary
            return data
        else:
            print(f'Failed to get data, error message is {response.content}')
            return None
    except requests.exceptions.Timeout:
        print('The request timed out. Please try again later.')
        return None

def main():
    url = 'https://api.github.com/some/endpoint'     # This would be your API endpoint URL

    response_data = get_data(url)

    if response_data:
        print(json.dumps(response_data, indent=4))    # Prints the data in a nicely formatted manner

if __name__ == "__main__":
    main()

