import shlex
import subprocess

def run_command(command):
    command = map(shlex.quote, command)  # This will escape the arguments properly if they contain special characters

    process = subprocess.Popen(['/bin/bash', '-c', ' '.join(command), stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    output, error = process.communicate()

    if process.returncode != 0:
        print("Command execution failed")
    else:
        print('Command executed successfully')

    if output:
        print('Output: ', output.decode())   # Decode the output bytes to string
    if error:
        print('Error: ', error.decode())

import os
from pathlib import Path
import subprocess

def execute_shell_script(script_path):
    # Sanitize the input script path to join with a known base path
    sanitized_script_path = '/base/known/path/' + os.path.basename(script_path)

    try:
        # Validate and resolve the file path using pathlib
        resolved_script_path = Path(sanitized_script_path).resolve()

        if not str(resolved_script_path).startswith('/base/known/path'):
            raise ValueError('Invalid script path')

        # Use subprocess.Popen to execute the script and check the return code for success or failure
        process = subprocess.Popen(['sh', str(resolved_script_path)], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        stdout, stderr = process.communicate()

        if process.returncode != 0:
            print("Failed to execute script {}".format(resolved_script_path))
        else:
            print("Output of shell script:\n" + stdout)

    except ValueError as e:
        print(f"Invalid script path: {str(e)}")

