            data = json.load(file)
            return data
    except FileNotFoundError:
        print('File not found')
        return None
    except json.decoder.JSONDecodeError:
        print("Invalid JSON")
        return None
    except Exception as e:
        print(f"An error occurred: {e}")
        return None

