from datetime import datetime, timedelta
import time

# A simple dict to hold our sessions, this would be replaced by your actual session handling method
SESSIONS = {}

def create_session(username):
    # Create a new session with the current timestamp as the value
    SESSIONS[username] = datetime.now()

def get_inactive_sessions():
    inactive_sessions = []

    for username, timestamp in SESSIONS.items():
        time_difference = datetime.now() - timestamp

        # If the session is more than 1 hour old, add it to the list of inactive sessions
        if time_difference > timedelta(hours=1):
            inactive_sessions.append(username)

    return inactive_sessions

def expire_session(username):
    # Remove a session from our dict, this would be replaced by your actual method of logging out/expiring a session
    if username in SESSIONS:
        del SESSIONS[username]

# Example usage
create_session('user1')
time.sleep(3600)  # Sleep for an hour to simulate inactivity
inactive_sessions = get_inactive_sessions()
for session in inactive_sessions:
    expire_session(session)

