def check_for_token(func):
    @wraps(func)
    def wrapped(*args, **kwargs):
        token = request.args.get('token') 
        if not token: 
            return jsonify({'message': 'Missing token'}), 403
        try: 
            data = jwt.decode(token, app.config['SECRET_KEY'], algorithms=["HS256"])
        except Exception as e:
            print(e)
            return jsonify({'message': 'Invalid token'}), 403

        return func(*args, **kwargs)
    return wrapped

@app.route('/')
@check_for_token
def index():
    return 'Hello World!'

# Validate the password before generating a JWT token to avoid hardcoding it
@app.route('/login', methods=['POST'])
def login():
    auth = request.authorization 

    if auth and auth.password == os.environ.get('FLASK_PASSWORD'):
        # Use different key for JWT token to avoid hardcoding it in the Flask app config
        jwt_key = os.environ.get('JWT_SECRET_KEY') 
        if not jwt_key:
            return jsonify({'message': 'Missing JWT key'}), 500

        token = jwt.encode({'user': auth.username, 'exp': datetime.datetime.utcnow() + datetime.timedelta(minutes=30)}, jwt_key, algorithm="HS256")

        return jsonify({'token': token})

    return make_response('Could not verify', 401, {'WWW-Authenticate': 'Basic realm="Login required!"'})

