class PrivilegeError(Exception):
    pass

class BaseUser:
    def __init__(self, user_id, username, password):
        self.user_id = user_id
        self.username = username
        self.__password = password # private attribute 

    def check_privilege(self, required_privilege):
        if required_privilege not in self.get_available_privileges():
            raise PrivilegeError("User doesn't have the required privilege.")

class User(BaseUser):
    def __init__(self, user_id, username, password):
        super().__init__(user_id, username, password)

    def get_available_privileges(self):
        return ['read', 'write'] # basic privileges

class Admin(User): 
    def __init__(self, user_id, username, password):
        super().__init__(user_id, username, password)

    def get_available_privileges(self):
        return ['read', 'write', 'edit', 'delete'] # extra privileges for admin

