class Employee(object):
    def __init__(self, name, title):
        self.name = name
        self.title = title
        print("Employee created: " + self.name)

    def get_info(self):
        return f"{self.name}, {self.title}"

class Department(object):
    def __init__(self, name):
        self.name = name
        self.employees = []
        print("Department created: " + self.name)

    def add_employee(self, employee):
        if isinstance(employee, Employee):
            self.employees.append(employee)
        else:
            raise TypeError('Invalid argument type. Expected object of type "Employee"')

class Company(object):
    def __init__(self, name):
        self.name = name
        self.departments = []
        print("Company created: " + self.name)

    def add_department(self, department):
        if isinstance(department, Department):
            self.departments.append(department)
        else:
            raise TypeError('Invalid argument type. Expected object of type "Department"')

    def get_employees(self):
        for department in self.departments:
            print("Department Name: ", department.name)
            for employee in department.employees:
                print("\t", employee.get_info())

