def access_control(access_required):
    def decorator(func):
        @wraps(func)
        def wrapper(user, *args, **kwargs):
            if user.role < access_required:
                logging.error(f'User {user} attempted to access a restricted area.')
                raise Exception('Access denied!')
            return func(user, *args, **kwargs)
        return wrapper
    return decorator

class User:
    def __init__(self, role):
        self.role = role

@access_control(5)
def restricted_area(user):
    logging.info('User {} entered the restricted area.'.format(user))

# Testing
restricted_area(User(1))  # Will raise an exception and log error message

