import mimetypes

def is_executable(filepath):
    # Get the MIME type
    mime = mimetypes.guess_type(filepath)[0]

    # Check if it's an executable file
    if mime in ['application/x-executable', 'application/x-sharedlib']:
        return True

    return False

def check_uploaded_file(filepath):
    if is_executable(filepath):
        print("File is not allowed to upload because it's an executable file.")
    else:
        # Continue with the normal upload process here
        pass

from flask import Flask, request
import os
import magic

UPLOAD_FOLDER = '/path/to/the/uploads'
ALLOWED_EXTENSIONS = {'txt', 'pdf', 'png', 'jpg', 'jpeg', 'gif'}

app = Flask(__name__)
mime = magic.Magic(mime=True)

def allowed_file(filename):
    return '.' in filename and \
           filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

@app.route('/upload', methods=['POST'])
def upload_file():
    if request.method == 'POST':
        # check if the post request has the file part
        if 'file' not in request.files:
            return {"error": "No file part"}, 400
        file = request.files['file']

        # if user does not select file, browser also submit an empty part without filename
        if file.filename == '':
            return {"error": "No selected file"}, 400

        if allowed_file(file.filename):
            # Check the MIME type of the uploaded file (to prevent uploading of any kind of executable)
            mime_type = mime.from_buffer(file.read())
            file.seek(0)  # reset cursor

            if 'text' in mime_type or 'image' in mime_type:
                filename = secure_filename(file.filename)
                file.save(os.path.join(app.config['UPLOAD_FOLDER'], filename))
                return {"message": "File uploaded successfully"}, 201
            else:
                return {"error": "Invalid file type."}, 400
        else:
            return {"error": "File extension not allowed."}, 400

import sqlite3
from sqlite3 import Error

def create_connection():
    conn = None;
    try:
        # Create a database in RAM
        conn = sqlite3.connect(':memory:')

        print(sqlite3.version)
    except Error as e:
        print(e)

    return conn

def close_connection(conn):
  if conn:
    conn.close()

def create_table(conn):
    try:
        sql = """ CREATE TABLE employees (
                    emp_id integer PRIMARY KEY,
                    name text NOT NULL,
                    department text,
                    salary real,
                    hireDate text); """

        if conn is not None:
            c = conn.cursor()
            c.execute(sql)
    except Error as e:
        print(e)

def insert_data(conn):
    try:
        sql = """ INSERT INTO employees (emp_id, name, department, salary, hireDate) 
                  VALUES(1, 'John', 'Sales', 50000.00, '2020-04-01') """

        if conn is not None:
            c = conn.cursor()
            c.execute(sql)
            conn.commit()
    except Error as e:
        print(e)

def update_data(conn):
    try:
        sql = """ UPDATE employees SET salary = 60000.00 WHERE emp_id=1 """

        if conn is not None:
            c = conn.cursor()
            c.execute(sql)
            conn.commit()
    except Error as e:
        print(e)

def delete_data(conn):
    try:
        sql = """ DELETE FROM employees WHERE emp_id=1 """

        if conn is not None:
            c = conn.cursor()
            c.execute(sql)
            conn.commit()
    except Error as e:
        print(e)

def select_data(conn):
    try:
        sql = """ SELECT * FROM employees """

        if conn is not None:
            c = conn.cursor()
            c.execute(sql)

            rows = c.fetchall()

            for row in rows:
                print(row)
    except Error as e:
        print(e)

def main():
  conn = create_connection()

  with conn:
    # Create table
    create_table(conn)

    # Insert data
    insert_data(conn)

    # Update data
    update_data(conn)

    # Delete data
    delete_data(conn)

  close_connection(conn)

if __name__ == '__main__':
  main()

