class Cache(object):
    def __init__(self, db, ttl=60*5):
        self.ttl = ttl
        self.db = db
        self.cache_dict = {}

    def get(self, key):
        current_time = time.time()
        if (key in self.cache_dict and 
            'expires' in self.cache_dict[key] and
            self.cache_dict[key]['expires'] > current_time):
             return self.cache_dict[key]['value']
         else:
             value = self.db.get_data(key)
             self.cache_dict[key] = {
                 'value': value, 
                 'expires': time.time() + self.ttl}
             return value

    def set(self, key, value):
        current_time = time.time()
        if (key in self.cache_dict and
            'expires' in self.cache_dict[key] and
            self.cache_dict[key]['value'] == value and 
            self.cache_dict[key]['expires'] > current_time):
             return
        else:
             self.db.update_data(key, value)
             self.cache_dict[key] = {
                 'value': value,
                 'expires': time.time() + self.ttl}

