class CacheMissError(Exception):
    """Raised when a requested item isn't found"""
    pass

class Cache:
    def __init__(self):
        self.cache = {}

    def get_value(self, key):
        try:
            return self.cache[key]
        except KeyError as e:
            raise CacheMissError("Requested item not found in cache.") from e

    def add_value(self, key, value):
        if key not in self.cache:
            self.cache[key] = value

import time
from threading import Thread

class CacheManager(object):
    def __init__(self, ttl=60):  # TTL in seconds
        self.cache = {}
        self.ttl = ttl

    def set_data(self, key, value):
        self.cache[key] = {"value": value, "expireAt": time.time() + self.ttl}

    def get_data(self, key):
        data = self.cache.get(key)
        if data:
            expiration = data["expireAt"]
            if time.time() < expiration:  # Data is not stale
                return data["value"]
            else:  
                del self.cache[key]  # Remove the stale key-value pair from cache
        return None

    def cleanup(self):
        """Function to periodically check and remove expired entries"""
        while True:
            time.sleep(1)  # Sleep for a second before checking again
            current_time = time.time()
            keys_to_delete = [key for key, value in self.cache.items() if current_time > value["expireAt"]]
            for key in keys_to_delete:
                del self.cache[key]

# Create an instance of CacheManager and start the cleanup thread 
cache = CacheManager(ttl=5)
Thread(target=cache.cleanup).start()

class LRUCache:
    def __init__(self, capacity):
        self.cache = {}
        self.usage_history = []
        self.capacity = capacity

    def get(self, key):
        if key in self.cache:
            self._update_usage(key)

        return self.cache.get(key, -1)

    def put(self, key, value):
        if key not in self.cache and len(self.cache) >= self.capacity:  # cache is full
            lru_item = self.usage_history[-1]
            self.cache.pop(lru_item)
            self.usage_history = self.usage_history[:-1]

        if key in self.cache:
            self._update_usage(key)

        self.cache[key] = value

    def _update_usage(self, key):
        self.usage_history.remove(key)
        self.usage_history.insert(0, key)

