import time
from datetime import datetime, timedelta

class EmailRateLimiter:
    def __init__(self, max_emails=500, period_seconds=3600):
        self.max_emails = max_emails
        self.period_seconds = period_seconds
        self.cache = {}

    def send_email(self):
        now = datetime.now()
        timestamp = time.mktime(now.timetuple()) + now.microsecond / 1E6

        # Remove old entries from cache
        for key in list(self.cache.keys()):
            if self.cache[key] < (timestamp - self.period_seconds):
                del self.cache[key]

        if len(self.cache) >= self.max_emails:
            print("Too many emails sent within a period, please wait.")
            return False

        # Add current timestamp to cache
        self.cache[timestamp] = timestamp
        print("Email Sent successfully!")
        return True

from dns import resolver, exception
import socket

def verify_email(email):
    try:
        domain = email.split('@')[1]

        # Get the SPF record for the domain
        answers = resolver.resolve(domain, 'TXT')

        for rdata in answers:
            for entry in rdata.strings:
                if "v=spf1" in entry:
                    return True  # Email is validated by SPF
    except (resolver.NoNameservers, resolver.NXDOMAIN, exception.Timeout):
        pass  # In case of DNS issues we just assume it's not a spoofed email

    return False  # If no SPF record is found or any error occurs

