def search_products(search_filters):
    # Initialize an empty list to store our results
    result = []

    # Loop through each product
    for product in products:
        # Assume the product matches all filters until proven otherwise
        is_match = True

        # Check if this product matches any of the search filters
        for key, value in search_filters.items():
            # If this filter doesn't match our product, it isn't a match
            if product[key] != value:
                is_match = False

        # If the product matched all filters, add it to our result list
        if is_match:
            result.append(product)

    return result

import time
from collections import deque

class RateLimiter:
    def __init__(self, max_requests, period):
        self.max_requests = max_requests  # maximum number of requests allowed in the period
        self.period = period   # length of the period in seconds
        self.requests = deque()   # a queue to keep track of the requests

    def allow(self):
        now = time.time()

        while len(self.requests) > 0 and self.requests[0] < now - self.period:
            self.requests.popleft()  # remove old requests that are outside the period

        if len(self.requests) >= self.max_requests:
            return False   # too many requests in a short time, drop it

        self.requests.append(now)
        return True   # request can be processed

