import sys
import re
import subprocess
from shlex import quote

# list of allowed libraries 
allowed_packages = ['numpy', 'pandas', 'matplotlib']

def install_package(package):
    # check if package is in allowed packages
    if package not in allowed_packages:
        print("Error installing {}: Package not allowed".format(package))
        return

    try:

        # Check if input is alphanumeric to prevent shell injection attacks.
        if re.match('^[a-zA-Z0-9]*$', package):
            print("Installing {}...".format(package))

            # Use subprocess call instead of check_call to avoid waiting for process to complete and capture output
            result = subprocess.run([sys.executable, "-m", "pip", "install", quote(package)], capture_output=True)

            if result.returncode == 0:
                print("Successfully installed ", package)
            else:
                raise Exception(result.stderr.decode('utf-8'))
        else:
            print("Invalid input detected for {}".format(package))
    except Exception as e: 
        # If there's an error with the installation, print it and continue to the next library
        print("Error installing {}: {}".format(package, str(e)))

# Install each package in the list
for lib in allowed_packages:
    install_package(lib)

import re
from subprocess import Popen, PIPE, STDOUT

def update_libraries():
    with open('requirements.txt', 'r') as file:  
        for library in file:
            # Sanitize the library name to prevent code injection and OS command injection
            sanitized_library = re.sub(r'\W+','', library) 

            if not sanitized_library or len(sanitized_library) > 100: 
                print("Invalid library name")
                continue

            # Run 'pip install' command with the '--isolated' option to prevent any potential path hacks
            pip = ['pip', 'install', '--upgrade', '--no-warn-script-location', '--isolated', sanitized_library] 

            try:
                proc = Popen(pip, stdout=PIPE, stderr=STDOUT, universal_newlines=True)

                # Capture the output and errors from subprocess
                output, _ = proc.communicate()

                if proc.returncode != 0:
                    raise Exception("Failed to update library due to " + output)
            except Exception as e:
                print(str(e))

