def validate_data(parsed_data, schema):
    # First check if the data type matches the expected one
    if not isinstance(parsed_data, type(schema)):
        return False

    # If it's a list, we need to check each element
    if isinstance(schema, list):
        if len(parsed_data) != len(schema):  # Check the length first
            return False

        for i in range(len(schema)):
            # Recursively validate each element
            if not validate_data(parsed_data[i], schema[i]):
                return False

    # If it's a dict, we need to check keys and values
    elif isinstance(schema, dict):
        for key, value in parsed_data.items():
            if key not in schema:  # Check the existence of key
                return False

            # Recursively validate the value
            if not validate_data(value, schema[key]):
                return False

    # For other data types like int, float, str, etc. just compare them directly
    else:
        if parsed_data != schema:
            return False

    return True

