import threading
from time import sleep, time
from collections import deque

class ThreadMonitor:
    def __init__(self):
        self.execution_times = []

    def monitor(self, fn, *args, **kwargs):
        start_time = time()
        fn(*args, **kwargs)
        end_time = time()
        execution_time = end_time - start_time
        self.execution_times.append((threading.currentThread().name, execution_time))

class MyThread(threading.Thread):
    def __init__(self, monitor: ThreadMonitor):
        super().__init__()
        self.monitor = monitor

    def run(self):
        sleep(2) # Simulate work being done
        self.monitor.monitor(self._do_work)

    def _do_work(self):
        sleep(3)  # Simulate work being done

def main():
    monitor = ThreadMonitor()

    threads = [MyThread(monitor) for _ in range(5)]

    for thread in threads:
        thread.start()

    for thread in threads:
        thread.join()

    print("Execution times:")
    for name, execution_time in monitor.execution_times:
        print(f"Thread {name}: {execution_time}s")

if __name__ == "__main__":
    main()

import socket
import threading

class Server:
    def __init__(self, host = '127.0.0.1', port = 8080):
        self.host = host
        self.port = port
        self.server = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.server.bind((self.host, self.port))
        self.server.listen()

    def handle_client(self, client):
        while True:
            data = client.recv(1024).decode('utf-8')
            if not data:
                break
            print("Received from client: ", data)

    def receive(self):
        while True:
            print('Listening for connections..')
            client, addr = self.server.accept()
            threading.Thread(target=self.handle_client, args=(client,)).start()

if __name__ == "__main__":
    server = Server()
    server.receive()

