def validate_cvv(user_input):
    if not match('^[0-9]{3,4}$', user_input):
        print("CVV is Invalid. It should be a 3 or 4 digit number.")
        return False
    else:
        return True

def validate_expiration(user_input):
    today = datetime.datetime.now()

    try:
        month, year = user_input.split("/")

        if len(year) != 2 or not 1 <= int(month) <= 12:
            raise ValueError("Expiration date is Invalid.")

        expire = datetime.datetime(int('20'+year), int(month), 1)
    except Exception as e:
        print("Expiration Date is Invalid.\nThe format should be MM/YY")
        return False

    if today > expire:
        print("Card has Expired.")
        return False

    return True

