        # Check if a user has access to a file
        return (filename in self.files and 
                (isinstance(self.files[filename], list) and username in self.files[filename] or 
                 isinstance(self.files[filename], str) and self.files[filename] == username))

    def print_accessors(self, filename):
        # Print all users that have access to a file
        if not self.check_access(filename, ''):
            print('No one has access to this file.')
        else:
            if isinstance(self.files[filename], str):
                print(f'{filename} is accessible by {self.files[filename]}.')
            else:
                print(f'{filename} is accessible by:')
                for user in self.files[filename]:
                    print(user)

    def remove_file(self, filename):
        # Remove a file from the system (and therefore revoke all accessors to it)
        if not self.check_access(filename, ''):
            print('No such file exists.')
        else:
            del self.files[filename]


# example usage:
fm = FileManager()
fm.add_file('important_document.docx', 'Alice')
fm.print_accessors('important_document.docx')  # prints "important_document.docx is accessible by Alice."

fm.add_accessor('important_document.docx', 'Bob')
fm.print_accessors('important_document.docx')  # now it should print "important_document.docx is accessible by: Alice Bob"

fm.remove_accessor('important_document.docx', 'Alice')
fm.print_accessors('important_document.docx')  # now it should print "important_document.docx is accessible by Bob."

import boto3
from botocore.exceptions import NoCredentialsError

def get_bucket_size(bucketname):
    s3 = boto3.client('s3')
    try:
        response = s3.list_objects_v2(Bucket=bucketname)
        size = 0

        # if the bucket is not empty, this will return the sum of all object sizes in bytes
        if 'Contents' in response:
            for obj in response['Contents']:
                size += obj['Size']

        print(f"The total storage used by {bucketname} is {size/1024/1024} MB") # convert bytes to MB

    except NoCredentialsError as nce:
        print("Invalid credentials, please check your AWS configuration")
    except Exception as ex:
        print(f"An error occurred: {str(ex)}")

