import time
from datetime import datetime

class TaskScheduler:
    def __init__(self):
        self.tasks = []  # List to store tasks

    class Task:
        def __init__(self, name, interval_secs, task_func):
            self.name = name
            self.interval_secs = interval_secs
            self.task_func = task_func
            self.last_run = 0  # Initialize last run time to 0 (epoch)

        def should_run(self):
            """Check if the task is due for running"""
            return time.time() - self.last_run >= self.interval_secs

    def schedule_task(self, name, interval_secs, task_func):
        """Add a new task to be scheduled"""
        self.tasks.append(self.Task(name, interval_secs, task_func))

    def run(self):
        while True:  # Run indefinitely
            for task in self.tasks:
                if task.should_run():
                    print("Running task '{}' at {}".format(task.name, datetime.now()))
                    task.last_run = time.time()
                    task.task_func()  # Run the task
            time.sleep(1)  # Sleep for a bit to prevent high CPU usage

def example_task():
    print("This is an example task.")

if __name__ == "__main__":
    scheduler = TaskScheduler()
    scheduler.schedule_task('ExampleTask', 5, example_task)
    scheduler.run()

