import time
from functools import wraps

def timer(func):
    @wraps(func)  # this makes sure our wrapper gets the same name as original func
    def wrapper_timer(*args, **kwargs):
        start_time = time.perf_counter()   #start timer
        result = func(*args, **kwargs)     #call function and get its result
        end_time = time.perf_counter()     #stop timer
        run_time = end_time - start_time   #calculate the elapsed time
        print(f"Finished {func.__name__} in {run_time:.4f} secs")  #print the result

        return result
    return wrapper_timer

# now, just decorate your function with @timer and it will automatically monitor its execution times.
@timer
def waste_some_time(num_times):
    for _ in range(num_times):
        sum([i**2 for i in range(10000)])

waste_some_time(999)

