from cryptography.fernet import Fernet
import base64, json

class EncryptionManager(object):
    def __init__(self, key=None):
        if not key:
            self.key = Fernet.generate_key()
        else:
            # Ensure the provided key is in bytes format
            if isinstance(key, str):
                key = key.encode('utf-8')
            self.key = base64.urlsafe_b64encode(key) 

        self.fernet = Fernet(self.key)

    def encrypt(self, message):
        if isinstance(message, str):
            message = message.encode('utf-8')

        ciphertext = self.fernet.encrypt(message)

        return ciphertext.decode('utf-8')   # The encrypted text in utf-8 format

    def decrypt(self, token):
        if isinstance(token, str):
            token = token.encode('utf-8')

        try:
            decrypted_text = self.fernet.decrypt(token)
            return decrypted_text.decode('utf-8')   # The decrypted text in utf-8 format
        except cryptography.fernet.InvalidToken:
            print("Key incorrect or message corrupted")

