from collections import deque
import time

class SlidingWindow:
    def __init__(self, size):
        self.queue = deque(maxlen=size)

    def add(self, value):
        timestamp = int(round(time.time() * 1000)) # get the current time in milliseconds
        self.queue.append((timestamp, value))

    def get_average(self):
        total = 0
        for _, value in self.queue:
            total += value

        return total / len(self.queue) if self.queue else 0

window = SlidingWindow(5) # create a sliding window of size 5

# simulate adding values over time
for i in range(1, 20):
    window.add(i)
    print("Average: ", window.get_average())
    if len(window.queue) == window.queue.maxlen: # if the window is full
        time.sleep(1) # wait for a second before adding next value

import time

def latency_tracker(func):
    def wrapper(*args, **kwargs):
        start = time.time()
        result = func(*args, **kwargs)
        end = time.time()

        print(f'Function {func.__name__} took {end - start} seconds to execute')
        return result
    return wrapper

@latency_tracker
def sleep_function():
    time.sleep(2) # Sleep for 2 seconds

