from flask import Flask, request, render_template, send_from_directory
import os

app = Flask(__name__)

UPLOAD_FOLDER = '/path/to/the/uploads'
ALLOWED_EXTENSIONS = {'txt', 'pdf', 'png', 'jpg', 'jpeg', 'gif'}
app.config['UPLOAD_FOLDER'] = UPLOAD_FOLDER

def allowed_file(filename):
    return '.' in filename and \
           filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

@app.route('/uploads/<filename>')
def uploaded_file(filename):
    return send_from_directory(app.config['UPLOAD_FOLDER'], filename)

@app.route("/", methods=["GET", "POST"])
def index():
    if request.method == 'POST':
        if 'file' not in request.files:
            return render_template("index.html", error="No file part")
        file = request.files['file']
        if file.filename == '':
            return render_template("index.html", error="No selected file")
        if file and allowed_file(file.filename):
            filename = os.path.join(app.config['UPLOAD_FOLDER'], file.filename)
            file.save(os.path.join(app.config['UPLOAD_FORMER'], file.filename))
            return render_template("index.html", success="File successfully uploaded")
    return render_template("index.html")

if __name__ == "__main__":
    app.run(debug=False)   # Change debug mode to False

class User:
    def __init__(self, name, role):
        self.name = name
        self.role = role

class Role:
    def __init__(self, name):
        self.name = name
        self.permissions = []

    def grant(self, permission):
        if permission not in self.permissions:
            self.permissions.append(permission)

    def revoke(self, permission):
        if permission in self.permissions:
            self.permissions.remove(permission)

    def has_access(self, permission):
        return permission in self.permissions or 'admin' in self.permissions

class CMS:
    def __init__(self):
        self.roles = {}
        self.users = []

    def create_role(self, name):
        if name not in self.roles:
            self.roles[name] = Role(name)

    def add_user(self, user):
        self.users.append(user)

    def grant_permission(self, role_name, permission):
        if role_name in self.roles:
            self.roles[role_name].grant(permission)

    def revoke_permission(self, role_name, permission):
        if role_name in self.roles:
            self.roles[role_name].revoke(permission)

    def user_access(self, name, permission):
        for user in self.users:
            if user.name == name and self.roles[user.role].has_access(permission):
                return True

        return False

import sqlite3
from difflib import SequenceMatcher

def similar(a, b):
    return SequenceMatcher(None, a, b).ratio()

class ContentManagementSystem:
    def __init__(self):
        self.conn = sqlite3.connect('cms_database.db')
        self.cursor = self.conn.cursor()

        # Create table if not existent
        self.cursor.execute("""CREATE TABLE IF NOT EXISTS Pages 
                            (ID INTEGER PRIMARY KEY, Content TEXT)""")

    def add_content(self, content):
        self.cursor.execute("INSERT INTO Pages (Content) VALUES (?)", (content,))
        self.conn.commit()

    def search(self, keyword):
        results = []
        for row in self.cursor.execute('SELECT * FROM Pages'):
            if similar(row[1], keyword) > 0.8: # similarity threshold can be adjusted
                results.append(row[1])

        return results

