class TenantResourceLimitError(Exception):
    def __init__(self, message="Tenant has exceeded its resource limit!"):
        self.message = message
        super().__init__(self.message)

def enforce_limit(func):
    def wrapper(tenant):
        if tenant.used > tenant.limit:
            raise TenantResourceLimitError()
        else:
            func(tenant)
    return wrapper

class Tenant:
    def __init__(self, limit=100):
        self.limit = limit
        self.used = 0

    @enforce_limit    
    def use_resource(self, amount):
        # some operation that uses resource
        self.used += amount

# Tenant operations
try:
    tenant1 = Tenant()
    tenant1.use_resource(20)  # usage under limit
    print("Tenant 1 used", tenant1.used, "of its", tenant1.limit)

    tenant1.use_resource(200)  # this will raise an exception
except TenantResourceLimitError as e:
    print(e)

class TenantConfigurationValidator(object):
    def __init__(self, max_users=5, required_fields=["tenant_name", "database"]):
        self.max_users = max_users
        self.required_fields = required_fields

    def validate(self, tenant_config):
        # Check if all required fields exist in the configuration
        for field in self.required_fields:
            if field not in tenant_config:
                return False, f"Missing required field: {field}"

        # Check if number of users does not exceed maximum limit
        if len(tenant_config["users"]) > self.max_users:
            return False, f"Too many users. Maximum allowed: {self.max_users}"

