import heapq

class PriorityQueue:
    def __init__(self):
        self._queue = []
        self._index = 0

    def push(self, item, priority):
        # The higher the number, the lower the priority
        heapq.heappush(self._queue, (-priority, self._index, item))
        self._index += 1

    def pop(self):
        if self._queue:
            return heapq.heappop(self._queue)[-1]
        else:
            raise Exception('Trying to pop from empty queue')

    def is_empty(self):
        return not self._queue

# Example usage of PriorityQueue 
pq = PriorityQueue()
pq.push("item1", 3) # Higher number indicates higher priority
pq.push("item2", 5)
pq.push("item3", 2)
print(pq.pop()) # Outputs: item2

import threading
from queue import Queue
import time

class ScalerThread(threading.Thread):
    def __init__(self, queue):
        threading.Thread.__init__(self)
        self.queue = queue

    def run(self):
        while True:
            if not self.queue.empty():
                item = self.queue.get()
                print(f'Scaler thread {threading.current_thread().name} processing {item}\n')

                # Simulate a long process 
                time.sleep(2)

def main():
    queue = Queue()

    for i in range(5):
        worker = ScalerThread(queue)

        # Setting threads as daemon means they will quit when the main program quits
        worker.daemon = True

        # Start the thread's activity
        worker.start()

    for i in range(1, 20):
        queue.put('Task-'+str(i))
        print('Added task', str(i))

if __name__ == '__main__':
    main()

