import os
import json
from datetime import datetime

class ModelVersioning():
    def __init__(self, base_dir="models"):
        self.base_dir = base_dir
        if not os.path.exists(self.base_dir):
            os.makedirs(self.base_dir)

    def _validate_filename(self, filename: str):
        # basic validation of file name to prevent path traversal attacks
        return all(x not in filename for x in ('..', '/'))

    def save_model(self, model, model_name):
        if self._validate_filename(model_name):
            timestamp = datetime.now().strftime('%Y%m%d%H%M%S')
            filename = f"{self.base_dir}/{model_name}_{timestamp}.json"

            with open(filename, 'w') as file:
                json.dump(model, file)
        else:
            raise ValueError("Invalid model name")

    def load_latest_model(self, model_name):
        if self._validate_filename(model_name):
            models = self._get_all_models(model_name)
            if not models:
                raise Exception("No models found.")

            latest_model = max(models.keys())
            with open(os.path.join(self.base_dir, models[latest_model]), 'r') as file:
                return json.load(file)
        else:
            raise ValueError("Invalid model name")

    def _get_all_models(self, model_name):
        all_models = {}
        for file in os.listdir(self.base_dir):
            if (file.endswith(".json")) and (file.startswith(model_name)):
                timestamp = int(file.split('.')[0].rsplit('_', 1)[-1])
                all_models[timestamp] = file
        return all_models

