    facebook = OAuth2Session(client_id, redirect_uri=redirect_uri)
    authorization_url, _ = facebook.authorization_url(authorization_base_url)

    # State is used to prevent CSRF, keep this for later.
    session['oauth_state'] = facebook._fetch_token

    return redirect(authorization_url)

# Step 2: User authorized your App
@app.route("/callback", methods=["GET"])
def callback():
    facebook = OAuth2Session(client_id, redirect_uri=redirect_uri, state=session['oauth_state'])

    # Retrieve response from the server after user authorization
    token = facebook.fetch_token(token_url, client_secret=client_secret, authorization_response=request.url)
    session['oauth_token'] = token

    return redirect(url_for('.profile'))

