import os
from getpass import getpass  # Prompt user for password without echoing

class CredentialsManager(object):
    def __init__(self):
        self.credentials = {}

    def add_credential(self, key, value=None):
        """Add a credential"""
        if value is None:  # If no value provided, ask the user for input
            value = getpass(f'Enter your {key}: ')

        self.credentials[key] = value

    def get_credential(self, key):
        """Get a credential"""
        if key in os.environ:  # Check if the credential is stored in an environment variable
            return os.getenv(key)

        elif key in self.credentials:  # Else check if it's been added using add_credential()
            return self.credentials[key]

        else:
            raise KeyError(f"No credential with the name {key} found.")

# Now, you can use this class to manage your credentials as follows:
