import requests

def convert_currency(amount, from_currency, to_currency):
    url = f"https://free.currconv.com/api/v7/convert?q={from_currency}_{to_currency}&compact=ultra&apiKey=YOUR_API_KEY"

    response = requests.get(url, timeout=5)  # set a timeout of 5 seconds
    data = response.json()

    if "results" in data:
        conversion_rate = list(data["results"].values())[0]
        converted_amount = amount * conversion_rate
        return round(converted_amount, 2)
    else:
        print("Conversion failed. Please check your input and try again.")

def main():
    amount = float(input('Enter the amount you want to convert: '))
    from_currency = input('From which currency (e.g., USD): ').upper()
    to_currency = input('To which currency (e.g., EUR): ').upper()

    result = convert_currency(amount, from_currency, to_currency)

    if result:
        print(f'{amount} {from_currency} is equal to {result} {to_currency}.')

