import locale
from babel import Locale, core

def check_format(user_input, language='en', country='US', expected_type='date'):
    if expected_type == 'number':
        try:
            locale.setlocale(locale.LC_ALL, f"{language}_{country}")
            locale.atof(user_input)  # str to float validation
            return True
        except (ValueError, locale.Error):
            pass
    elif expected_type == 'date':
        try:
            locale.setlocale(locale.LC_ALL, f"{language}_{country}")
            if not core.parse_date(user_input, Locale(language, country)):  # date validation
                return False
            else:
                return True
        except (ValueError, TypeError):
            pass
    elif expected_type == 'currency':
        try:
            locale.setlocale(locale.LC_ALL, f"{language}_{country}")
            if not core.parse_currency(user_input, Locale(language, country)):  # currency validation
                return False
            else:
                return True
        except (ValueError, TypeError):
            pass
    elif expected_type == 'time':
        try:
            locale.setlocale(locale.LC_ALL, f"{language}_{country}")
            if not core.parse_time(user_input, Locale(language, country)):  # time validation
                return False
            else:
                return True
        except (ValueError, TypeError):
            pass
    return False

import os
import gettext

def load_translation(domain, localedir):
    """Load translations."""
    # Set locale and bind gettext
    lang = os.environ.get('LANG')[:2]  # Get first two characters of LANG environment variable
    if not lang:
        return gettext.NullTranslations()

    try:
        t = gettext.translation(domain, localedir=localedir, languages=[lang])
    except FileNotFoundError:
        # Fall back to default language (English)
        t = gettext.translation(domain, localedir=localedir, languages=['en'])

    return t.gettext

