import os
import shutil
import tempfile

class BackupRestoreTest:
    def __init__(self):
        self.tmpdir = tempfile.TemporaryDirectory()
        self.backup_directory = os.path.join(self.tmpdir.name, 'backups')
        self.restored_data_directory = os.path.join(self.tmpdir.name, 'restore')

    def backup_test(self):
        # Create some test data to back up
        os.makedirs('test_dir/sub_dir', exist_ok=True)
        with open('test_dir/file1.txt', 'w') as f:
            f.write('Test data 1')

        with open('test_dir/sub_dir/file2.txt', 'w') as f:
            f.write('Test data 2')

        # Back up the test data
        shutil.copytree('test_dir', self.backup_directory)

        return os.path.exists(self.backup_directory)

    def restore_test(self):
        # Delete the original test data
        shutil.rmtree('test_dir')

        # Restore from backup
        shutil.copytree(self.backup_directory, self.restored_data_directory)

        return os.path.exists(self.restored_data_directory)

    def run_tests(self):
        print("Running tests...")

        backup = self.backup_test()
        if not backup:
            print('Backup test failed')

        restore = self.restore_test()
        if not restore:
            print('Restore test failed')

        if backup and restore:
            print('All tests passed')

if __name__ == "__main__":
    BackupRestoreTest().run_tests()

