def parse_fixed_width(file, schema):
    """
    Parse fixed-width file according to the given schema

    :param file: path to the file
    :param schema: dict in format {field_name: (start, end)} representing field boundaries 
    """
    with open(file) as f:
        for line in f:
            parsed_line = {}
            for name, coords in schema.items():
                start, end = coords
                parsed_line[name] = line[start:end].strip()  # strip to remove leading/trailing whitespace

            yield parsed_line

