import requests
import time

def send_webhook(url, data, retries=3):
    headers = {"Content-Type": "application/json"}

    for i in range(retries):
        try:
            response = requests.post(url, json=data, headers=headers, timeout=5)   # Added a timeout of 5 seconds

            if response.status_code == 200:
                print("Webhook delivery succeeded.")
                return True 

        except requests.exceptions.RequestException as e:
            print(f"Error occurred: {e}, retry in {2 ** i} seconds")

            time.sleep(2 ** i)

    print("Failed to deliver webhook after retries.")
    return False 

