from flask import Flask, request, abort
import hmac
import hashlib
import os

app = Flask(__name__)
WEBHOOK_SECRET = os.getenv('WEBHOOK_SECRET')   # Replace with your own securely stored secret

def verify_signature(request):
    signature = request.headers.get('X-Hub-Signature')

    if signature is None:
        abort(403)  # No signature provided - reject the request.

    sha_name, signature = signature.split('=')
    if sha_name != 'sha1':
        abort(501)  # Only support SHA1 signatures for now.

    mac = hmac.new(WEBHOOK_SECRET.encode(), msg=request.data, digestmod=hashlib.sha1)
    if not hmac.compare_digest(str(mac.hexdigest()), str(signature)):
        abort(403)  # Signature mismatch - reject the request.

@app.route('/webhook', methods=['POST'])
def webhook():
    verify_signature(request)   # Call the new function to handle signature verification.

