from flask import Flask, request, jsonify
import redis
import time

app = Flask(__name__)
r = redis.Redis(host='localhost', port=6379, db=0)

@app.route('/webhook', methods=['POST'])
def webhook():
    api_key = request.headers.get('X-Api-Key')    

    if not api_key:
        return jsonify({"error": "API Key missing"}), 401

    rate_limit_info = r.get(api_key)

    if rate_limit_info is None:
        r.setex(api_key, 1, int(time.time()) + 60)    
    else:
        rate_limit_info = rate_limit_info.decode()  
        count, start = map(int, rate_limit_info.split('.'))

        if time.time() - start < 120:   
            if count >= 5:    
                return jsonify({"error": "Rate limit exceeded"}), 429
        else:
            start = int(time.time())    

        r.setex(api_key, f'{count+1}.{start}', 120)   

    return jsonify({"message": "Request received"}), 200  

if __name__ == '__main__':
    app.run(debug=False)

