import time
from collections import deque
from threading import Thread

class Scheduler:
    def __init__(self):
        self.jobs = deque()

    def add_job(self, job, delay=0):
        time.sleep(delay)  # Simulate a delay for the job to be added
        print("Adding job {}".format(job))
        self.jobs.append((job, time.time()))

    def process_next_job(self):
        if not self.jobs:
            return "No jobs in queue"

        next_job = self.jobs.popleft()  # Get the next job from the left of the deque
        print("Processing job {} at time {}".format(next_job[0], next_job[1]))

    def start(self):
        while True:
            if not self.jobs:
                continue

            Thread(target=self.process_next_job).start()  # Process the job in a new thread

# Testing our scheduler
scheduler = Scheduler()
scheduler.add_job("Job1")
time.sleep(2)  # Simulate delay between adding jobs
scheduler.add_job("Job2", delay=3)
scheduler.start()

