retry_count = 3
while retry_count > 0:
    try:
        job()
        break
    except Exception as e:
        print(f"Error occurred: {str(e)}")
        if retry_count == 1:
            raise e    
        else:
            print("Retrying...")
            time.sleep(5)  
            retry_count -= 1

class ShoppingCart:
    def __init__(self):
        self.cart = {}  # Initializing an empty shopping cart (dictionary)

    def add_item(self, item, quantity=1):  
        if item not in self.cart:
            self.cart[item] = quantity
        else:
            self.cart[item] += quantity

    def remove_item(self, item, quantity=1):  # Remove specific number of items from cart
        try:
            if self.cart[item] < quantity:
                print("Error: Not enough items in the cart.")
            else:
                self.cart[item] -= quantity
                if self.cart[item] == 0:  # If no more of that item, delete it from dictionary
                    del self.cart[item]  
        except KeyError:
            print("Error: Item not found in the cart.")

    def display_cart(self):  # Display all items and their quantities currently in the cart
        if len(self.cart) == 0:
            print("Cart is empty.")
        else:
            for item, quantity in self.cart.items():
                print(f"{item}: {quantity}")  

