import os

def child():
    print('\nChild process with id: {}'.format(os.getpid()))
    os._exit(0)  # Child exits here

def parent():
    while True:
        newref = os.fork()  

        if newref == 0:  
            child()

        else:
            pid, status = os.wait()
            print('Parent process with id: {}, successfully created child process with id: {}'.format(os.getpid(), pid))

parent()

class BlockChain():
    def __init__(self):
        self.chain = []

    # add a new block to the chain
    def add_block(self, block):
        if len(self.chain) > 0 : 
            block.prev_hash = self.chain[-1].compute_hash()
        else:
            block.prev_hash = 0

        self.chain.append(block)

class Block():
    def __init__(self, data):
        self.data = data
        self.prev_hash = 0x0

    # calculate the hash of the current block
    def compute_hash(self):
        return hash((self.prev_hash, self.data))

def validate_chain(blockchain):
    for i in range(1, len(blockchain.chain)):
        _previous = blockchain.chain[i].prev_hash
        _current = blockchain.chain[i-1].compute_hash()
        if _previous != _current : 
            return False
    return True

# Testing the system
blockchain = BlockChain()
for i in range(5):
    blockchain.add_block(Block("Data "+ str(i))) # add some dummy data

print ("Is chain valid? ", validate_chain(blockchain))

