@app.route('/api/v1/login', methods=['POST'])
def login():
    username = request.json.get('username')
    password = request.json.get('password')

    # Perform authentication logic here
    if username == 'admin' and password == os.environ.get('ADMIN_PASSWORD', 'password'):  # Use environment variable or set a default
        token = jwt.create_access_token(identity=username, roles=['admin'])
    elif username == 'editor' and password == os.environ.get('EDITOR_PASSWORD', 'password'):  # Use environment variable or set a default
        token = jwt.create_access_token(identity=username, roles=['editor'])
    elif username == 'viewer' and password == os.environ.get('VIEWER_PASSWORD', 'password'):  # Use environment variable or set a default
        token = jwt.create_access_token(identity=username, roles=['viewer'])

    return jsonify({'token': token})

