    'timestamp': str,
    'payload': {
        'key1': str,
        'key2': int,
        'key3': list
    }
}

# Validate the data structure recursively
def validate_structure(data, structure):
    if isinstance(data, dict):
        for key, value in data.items():
            if key not in structure:
                return False
            if not isinstance(value, structure[key]):
                return False
            if not validate_structure(value, structure[key]):
                return False
    elif isinstance(data, list):
        for item in data:
            if not validate_structure(item, structure[0]):
                return False
    else:
        return isinstance(data, structure)

# Check if the parsed data matches the expected structure
