from threading import Lock
from queue import Queue

class ThreadSafeQueue(Queue):
    def __init__(self):
        super().__init__()
        self.lock = Lock()

    def put(self, item):
        with self.lock:
            super().put(item)

    def get(self):
        with self.lock:
            return super().get()

class ThreadSafeDict(dict):
    def __init__(self):
        super().__init__()
        self.lock = Lock()

    def __getitem__(self, key):
        with self.lock:
            return super().__getitem__(key)

    def __setitem__(self, key, value):
        with self.lock:
            super().__setitem__(key, value)

# Example usage
queue = ThreadSafeQueue()
queue.put("hello")
print(queue.get())  # Output: hello

dict = ThreadSafeDict()
dict["name"] = "John"
print(dict["name"])  # Output: John

