import threading
import queue

class Task:
    def __init__(self, priority, task_function):
        self.priority = priority
        self.task_function = task_function

class TaskQueue(queue.PriorityQueue):
    def get(self):
        return super().get()[1]

def worker(task_queue):
    while True:
        task = task_queue.get()
        task.task_function()
        task_queue.task_done()

def main():
    task_queue = TaskQueue()

    # Create worker threads
    for i in range(4):
        threading.Thread(target=worker, args=(task_queue,), daemon=True).start()

    # Add tasks to the queue
    task_queue.put(Task(1, lambda: print("Low priority task")))
    task_queue.put(Task(5, lambda: print("High priority task")))
    task_queue.put(Task(3, lambda: print("Medium priority task")))

    # Block until all tasks are done
    task_queue.join()

if __name__ == "__main__":
    main()

import datetime

class RecurringPayment:
    def __init__(self, amount, frequency, start_date):
        self.amount = amount
        self.frequency = frequency
        self.start_date = start_date
        self.next_payment_date = start_date

    def calculate_next_payment_date(self):
        if self.frequency == "daily":
            self.next_payment_date += datetime.timedelta(days=1)
        elif self.frequency == "weekly":
            self.next_payment_date += datetime.timedelta(weeks=1)
        elif self.frequency == "monthly":
            self.next_payment_date = self.next_payment_date.replace(day=self.start_date.day)
        elif self.frequency == "yearly":
            self.next_payment_date = self.next_payment_date.replace(year=self.start_date.year + 1)

    def make_payment(self):
        print(f"Payment of {self.amount} made on {datetime.date.today()}")
        self.calculate_next_payment_date()

# Example usage
payment = RecurringPayment(100, "monthly", datetime.date(2023, 4, 1))

while True:
    payment.make_payment()
    print(f"Next payment date: {payment.next_payment_date}")

import time

def retry(max_retries=3, delay=1):
    """
    Decorator for retrying failed tasks.

    Args:
        max_retries (int): Maximum number of retries.
        delay (float): Delay between retries.

    Returns:
        Callable: Decorated function.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            retries = 0
            while True:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    if retries >= max_retries:
                        raise e
                    print(f"Task failed. Retrying in {delay} seconds...")
                    time.sleep(delay)
                    retries += 1
        return wrapper
    return decorator

@retry(max_retries=3)
def unreliable_task():
    raise Exception("Task failed.")

if __name__ == "__main__":
    unreliable_task()

