from flask import Flask, jsonify, request

app = Flask(__name__)

# Sample data
users = [
    {"id": 1, "name": "John Doe", "email": "johndoe@example.com"},
    {"id": 2, "name": "Jane Doe", "email": "janedoe@example.com"},
]

@app.route("/users", methods=["GET"])
def get_users():
    return jsonify({"users": users})

@app.route("/users/<int:user_id>", methods=["GET"])
def get_user(user_id):
    user = next((user for user in users if user["id"] == user_id), None)
    if user is None:
        return jsonify({"error": "User not found"}), 404
    return jsonify({"user": user})

@app.route("/users", methods=["POST"])
def create_user():
    data = request.json
    user = {"id": len(users) + 1, **data}
    users.append(user)
    return jsonify({"user": user}), 201

@app.route("/users/<int:user_id>", methods=["PUT"])
def update_user(user_id):
    user = next((user for user in users if user["id"] == user_id), None)
    if user is None:
        return jsonify({"error": "User not found"}), 404
    data = request.json
    user.update(data)
    return jsonify({"user": user})

@app.route("/users/<int:user_id>", methods=["DELETE"])
def delete_user(user_id):
    user = next((user for user in users if user["id"] == user_id), None)
    if user is None:
        return jsonify({"error": "User not found"}), 404
    users.remove(user)
    return jsonify({"user": user})

if __name__ == "__main__":
    app.run(debug=False)  # Corrected line

import time
import logging

# Define the event processor function
def process_event(event):
    try:
        # Perform event processing logic here
        print(f"Processing event: {event}")
    except Exception as e:
        logging.error(f"Failed to process event: {event}", exc_info=True)
        raise

# Define the retry function
def retry_failed_events(failed_events):
    for event in failed_events:
        attempts = 0
        while attempts < 3:
            try:
                process_event(event)
                break
            except Exception as e:
                logging.error(f"Attempt {attempts+1}/3 failed to process event: {event}", exc_info=True)
                attempts += 1
                time.sleep(5)

# Example usage
failed_events = [
    {"event_id": 1, "data": "error"},
    {"event_id": 2, "data": "failure"},
]

retry_failed_events(failed_events)

