from functools import wraps

# Define user roles
USER_ROLES = {
    'admin': ['create_content', 'edit_content', 'delete_content', 'manage_users'],
    'editor': ['edit_content', 'delete_content'],
    'author': ['create_content'],
    'reader': []
}

# Function to check user permissions
def has_permission(feature):
    def decorator(func):
        @wraps(func)
        def wrapper(user):
            if feature in USER_ROLES[user['role']]:
                return func(user)
            else:
                raise PermissionError(f"User '{user['username']}' does not have permission to access '{feature}'.")
        return wrapper
    return decorator

# Example usage
@has_permission('create_content')
def create_content(user):
    print(f"User '{user['username']}' can create content.")

@has_permission('edit_content')
def edit_content(user):
    print(f"User '{user['username']}' can edit content.")

user = {'username': 'john', 'role': 'editor'}

create_content(user)  # Output: User 'john' can create content.
edit_content(user)    # Output: User 'john' can edit content.

try:
    delete_content(user)  # PermissionError: User 'john' does not have permission to access 'delete_content'.
except PermissionError as e:
    print(e)

from abc import ABC, abstractmethod

class User(ABC):
    @abstractmethod
    def get_tenant(self):
        pass

class Tenant(ABC):
    @abstractmethod
    def is_allowed(self, user):
        pass

class StandardUser(User):
    def __init__(self, tenant):
        self.tenant = tenant

    def get_tenant(self):
        return self.tenant

class StandardTenant(Tenant):
    def __init__(self, name):
        self.name = name

    def is_allowed(self, user):
        return user.get_tenant() == self.name

class PremiumUser(User):
    def __init__(self):
        pass

    def get_tenant(self):
        return None

class PremiumTenant(Tenant):
    def __init__(self):
        pass

    def is_allowed(self, user):
        return True

def check_access(user, tenant):
    if user.get_tenant() is None or tenant.is_allowed(user):
        return True
    else:
        return False

# Example usage
user = StandardUser(tenant="tenant1")
tenant = StandardTenant(name="tenant1")

if check_access(user, tenant):
    print("Access granted.")
else:
    print("Access denied.")

