    if action['type'] == 'recover_data':
        recover_data(action['source_path'], action['destination_path'])
    elif action['type'] == 'restore_services':
        restore_services(action['service_names'])
    elif action['type'] == 'activate_communication_plan':
        activate_communication_plan(action['message'])

print('Disaster recovery plan executed successfully.')

