import time
from functools import wraps

class TokenBucket:
    def __init__(self, capacity, fill_rate):
        """capacity: max tokens; fill_rate: refill rate in seconds"""
        self.capacity = float(capacity)
        self.fill_rate = float(fill_rate)
        self.tokens = float(capacity) # initialize tokens to the bucket capacity
        self.last_refill_time = time.monotonic()

    def get_token(self):
        """return True if a token is available, False otherwise"""
        now = time.monotonic()
        elapsed_time = now - self.last_refill_time
        self.tokens += elapsed_time * self.fill_rate # refill tokens
        self.tokens = min(self.capacity, self.tokens) # limit to capacity
        self.last_refill_time = now

        if self.tokens >= 1:
            self.tokens -= 1
            return True
        else:
            return False

def rate_limit(max_calls, period):
    """decorator function for rate limiting API calls"""
    bucket = TokenBucket(max_calls, fill_rate=1/period) # refill rate is max_calls per period

    def decorate(func):
        @wraps(func)
        def wrapped(*args, **kwargs):
            if bucket.get_token():
                return func(*args, **kwargs)
            else:
                raise Exception("Too many API calls.")
        return wrapped
    return decorate

@rate_limit(max_calls=10, period=60) # limit to 10 calls per minute
def api_call():
    print("API call executed successfully!")

