import subprocess
import shutil
import shlex

def run_with_elevated_privileges(command):
    # Check if the command is valid and exists in the system
    if not isinstance(command, list) or any(not isinstance(c, str) for c in command):
        raise ValueError("Command must be a list of strings.")

    if not shutil.which(command[0]):
        raise ValueError(f"Command '{command[0]}' does not exist.")

    # Sanitize the user input to prevent command injection
    sanitized_command = [shlex.quote(c) for c in command]
    full_command = ['sudo', '-S'] + sanitized_command
    return subprocess.run(subprocess.list2cmdline(full_command), input=b'your_password\n', check=True, shell=True)

# Example usage
try:
    result = run_with_elevated_privileges(['apt-get', 'update'])
    print("Command executed successfully") if result.returncode == 0 else print("Command failed to execute")
except Exception as e:
    print(f"An error occurred: {e}")

