       "apt update": ["apt", "update"],
       # Add other trusted admin commands as needed, make sure each command is a list of strings
   }

   def secure_admin_command(command):
       if command not in WHITELISTED_COMMANDS:
           raise ValueError("Untrusted command input")

       password = getpass.getpass("Enter your sudo password: ")
       safe_command = ['sudo', '-S'] + WHITELISTED_COMMANDS[command]
       process = subprocess.Popen(safe_command, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
       output, error = process.communicate(input=password + '\n')

       if process.returncode == 0:
           print("Command executed successfully!")
           return output.strip()
       else:
           print("Error executing command:")
           return error.strip()

   # Example usage
