# Define roles and their permissions
ROLES = {
    'admin': {'read', 'write', 'execute'},
    'user': {'read', 'execute'},
    'guest': {'read'}
}

class User:
    def __init__(self, username, role):
        self.username = username
        self.role = role

    @property
    def permissions(self):
        return ROLES[self.role]

# Define resources and their associated permissions
RESOURCES = {
    'file1': {'read', 'write'},
    'file2': {'read'}
}

def has_permission(user, resource, permission):
    # Check if the user's role allows the required permission
    return permission in user.permissions and \
           permission in RESOURCES[resource]

# Example usage:

