def safe_write(filename, content):
    """Write content to filename safely by checking if the file already exists."""
    try:
        with open(filename, 'x') as f: # 'x' mode creates a new file. If the file already exists, this will raise an error.
            f.write(content)
    except FileExistsError:
        print(f"The file {filename} already exists. Skipping write operation.")

