class ObjectPool:
    def __init__(self, size):
        self._objects = [ExpensiveObject() for _ in range(size)]
        self._available_objects = set(self._objects)

    def acquire(self):
        if not self._available_objects:
            raise Exception("No objects available")
        obj = self._available_objects.pop()
        return obj

    def release(self, obj):
        if obj in self._available_objects:
            raise Exception("Object already released")
        self._available_objects.add(obj)

class ExpensiveObject:
    # This class represents an expensive-to-create object.
    pass

