def invalidate_cache(func):
    """Decorator to invalidate cache on data update."""
    func.last_updated = None  # Last time the function's result was updated

    @wraps(func)
    def wrapper(*args, **kwargs):
        if not func.last_updated or time.time() - func.last_updated > 60:
            # If it has been more than a minute since last update, recompute and cache the result
            func.cache_clear()
            func.last_updated = time.time()
        return func(*args, **kwargs)
    return wrapper

@lru_cache(maxsize=128)
@invalidate_cache
