import time

class DataCache:
    def __init__(self):
        self.cache = {}
        self.source_data = self.get_fresh_data()  # this function fetches fresh data from source

    def get_fresh_data(self):
        """
        Fetches fresh data from the source. This is a placeholder function for demonstration purposes.
        In a real-world application, this would likely involve querying a database or an API.
        """
        return {"key1": ("value1", time.time()), "key2": ("value2", time.time())}

    def get(self, key):
        if key in self.cache:
            cached_data, timestamp = self.cache[key]
            source_data, source_timestamp = self.source_data[key]

            # If the data in source is newer than the cache, update the cache
            if source_timestamp > timestamp:
                self.cache[key] = (source_data, source_timestamp)
        else:
            self.cache[key] = self.source_data[key]

        return self.cache[key][0]

# Usage
