import time
from collections import defaultdict

class EmailRateLimiter:
    def __init__(self, max_emails=10, period=60):
        self.max_emails = max_emails
        self.period = period
        self.sent_emails = defaultdict(int)
        self.last_check = time.time()

    def can_send(self, email):
        now = time.time()
        if now > self.last_check + self.period:
            # reset the counts and update last check time
            self.sent_emails.clear()
            self.last_check = now

        return self.sent_emails[email] < self.max_emails

    def send(self, email):
        if self.can_send(email):
            # simulate sending an email
            print("Sending email to:", email)
            self.sent_emails[email] += 1
        else:
            print("Rate limit exceeded for:", email)

import smtplib
from dns import resolver, exception

def check_spf(sender, receiver):
    domain = sender.split('@')[1]
    records = resolver.query(domain, 'TXT')
    for record in records:
        if record.to_text().startswith('v=spf1'):
            return True
    return False

def validate_email(sender, receiver):
    try:
        server = smtplib.SMTP('smtp.gmail.com', 587)
        server.ehlo()
        server.starttls()
        server.login('your-email@gmail.com', 'your-password')
        if check_spf(sender, receiver):
            print("Email is valid.")
        else:
            print("SPF record not found. Email may be spoofed.")
    except Exception as e:
        print("An error occurred:", str(e))

