def search_with_pagination(query, data, page_size=5):
    results = [item for item in data if query.lower() in item.lower()]
    total_pages = len(results) // page_size + (len(results) % page_size > 0)
    current_page = 1

    while True:
        print(f'\nPage {current_page} of {total_pages}')
        for i in range((current_page-1)*page_size, min(len(results), current_page*page_size)):
            print(results[i])

        choice = input("\nEnter 'next' to see more results or 'quit' to exit: ").lower()

        if choice == 'quit':
            break
        elif choice == 'next' and current_page < total_pages:
            current_page += 1
        else:
            print("No more results.")

