import time

class SearchLimiter:
    def __init__(self, max_requests=5, interval=60):
        self.max_requests = max_requests  # Maximum number of requests allowed in a given interval
        self.interval = interval  # Time interval in seconds
        self.request_times = []  # List to keep track of the time of each request

    def allow_search(self):
        current_time = time.time()

        # Remove any requests that are older than our interval from the record
        while self.request_times and (current_time - self.request_times[0]) > self.interval:
            self.request_times.pop(0)

        if len(self.request_times) < self.max_requests:
            # If we have not reached our limit, add the current time to our list and allow the request
            self.request_times.append(current_time)
            return True
        else:
            # If we have reached our limit, deny the request
            return False

# Usage example
search_limiter = SearchLimiter()

def search(query):
    if search_limiter.allow_search():
        print("Searching for:", query)
    else:
        print("Too many requests. Please try again later.")

