import subprocess
import sys

def install_and_upgrade(package):
    allowed_packages = ['numpy', 'pandas', 'matplotlib']  # List of allowed packages
    if package in allowed_packages:
        command = [sys.executable, '-m', 'pip', 'install', '--upgrade', package]
        subprocess.check_call(command)  # Using check_call to raise an exception for non-zero return codes
    else:
        raise ValueError(f"Package '{package}' is not allowed.")

import subprocess
import shutil
import os

def check_vulnerabilities(package):
    # Validate that the package name contains only alphanumeric characters, underscores, and hyphens.
    if not package.replace('-', '').replace('_', '').isalnum():
        print("Invalid package name.")
        return

    try:
        pip_audit = shutil.which('pip-audit')
        if pip_audit is None:
            raise FileNotFoundError()

        # Use os.path.abspath to construct the command and its arguments, avoiding potential security implications associated with subprocess module.
        # Additionally, use a list for the arguments instead of string concatenation to prevent shell injection.
        result = subprocess.run([os.path.abspath(pip_audit), package], stdout=subprocess.PIPE, check=True)
        output = result.stdout.decode('utf-8')
        if 'is vulnerable' in output:
            print(f"Vulnerabilities found in {package}:\n{output}")
        else:
            print(f"No known vulnerabilities found in {package}")
    except FileNotFoundError:
        print("pip-audit is not installed. Please install it using pip.")
    except subprocess.CalledProcessError:
        print("An error occurred while checking for vulnerabilities.")

