import os
   import subprocess
   import shutil

   def update_dependencies():
       try:
           # Use shutil.which to get the absolute path of pip-compile
           pip_compile = shutil.which("pip-compile")
           if not pip_compile:
               raise Exception("'pip-compile' command not found in PATH.")

           # Run the pip-compile command with a list argument to prevent execution of untrusted input
           subprocess.check_call([pip_compile, "requirements.in"])  # os.path.abspath is not needed here as shutil.which already returns the full path

           print("Updated 'requirements.txt' successfully.")

           # Use shutil.which to get the absolute path of pip-sync
           pip_sync = shutil.which("pip-sync")
           if not pip_sync:
               raise Exception("'pip-sync' command not found in PATH.")

           # Check if there are any updates available for our dependencies using a list argument to prevent execution of untrusted input
           result = subprocess.run([pip_sync], stdout=subprocess.PIPE)  # os.path.abspath is not needed here as shutil.which already returns the full path

           if not result.stdout:
               print("All dependencies are up to date.")
           else:
               print("Updated dependencies:\n", result.stdout.decode())
       except Exception as e:
           print(f"An error occurred while updating dependencies: {e}")

   if __name__ == "__main__":
       update_dependencies()

