class User:
    def __init__(self, id, balance):
        self.id = id
        self.balance = balance

class Transaction:
    def __init__(self, user_id, amount):
        self.user_id = user_id
        self.amount = amount

# Pretend database for demonstration purposes
users = {1: User(1, 500), 2: User(2, 300)}
transactions = {1: Transaction(1, -200), 2: Transaction(2, -150)}

def process_refund(transaction_id):
    if transaction_id not in transactions:
        return "Transaction not found."

    transaction = transactions[transaction_id]
    user = users[transaction.user_id]

    # Validate the refund request here - This is a basic example, you should add more checks!
    if transaction.amount >= 0 or abs(transaction.amount) > user.balance:
        return "Invalid refund request."

    # Securely process the refund
    try:
        user.balance += abs(transaction.amount)
        transactions[transaction_id] = Transaction(transaction.user_id, abs(transaction.amount))  # Update transaction to reflect refund
    except Exception as e:
        return "Error processing refund."

    return "Refund processed successfully."

