class TransactionProcessor:
    def __init__(self):
        self.processed_transactions = set()

    def process_transaction(self, transaction_id):
        if transaction_id in self.processed_transactions:
            print("Double charge detected! Transaction ID:", transaction_id)
            return False
        else:
            # Process the transaction here
            self.processed_transactions.add(transaction_id)
            print("Transaction processed successfully.")
            return True

import hashlib
import time

# This dictionary would be stored securely on the server
authenticated_devices = {
    'device1': 'token1',
    'device2': 'token2',
    # Add more devices as needed
}

def generate_token(secret, timestamp):
    """Generate a token based on the secret and the current timestamp."""
    return hashlib.sha256((secret + str(timestamp)).encode()).hexdigest()

def authenticate_device(device_id, provided_token):
    """Authenticate a device by comparing its token with the stored one."""
    # Get the secret associated with this device ID
    try:
        secret = authenticated_devices[device_id]
    except KeyError:
        return False  # Device not found in our database

    # Generate a new token based on the current timestamp and compare it to the provided one
    expected_token = generate_token(secret, int(time.time()))
    if provided_token == expected_token:
        return True  # Authentication successful
    else:
        return False  # Token mismatch

