import time
from threading import Lock

class RateLimiter:
    def __init__(self, max_requests, period):
        self.max_requests = max_requests
        self.period = period
        self.current_requests = 0
        self.last_reset_time = time.time()
        self.lock = Lock()

    def allow_request(self):
        with self.lock:
            now = time.time()
            if now > self.last_reset_time + self.period:
                # Reset counter
                self.current_requests = 0
                self.last_reset_time = now

            if self.current_requests < self.max_requests:
                self.current_requests += 1
                return True
            else:
                return False

# Usage example:
rate_limiter = RateLimiter(5, 1) # Allow 5 requests per second

def handle_request():
    if rate_limiter.allow_request():
        print("Handling request...")
    else:
        print("Too many requests, ignoring this one.")

# Simulate 10 requests over a period of time
for _ in range(10):
    handle_request()
    time.sleep(0.1) # Wait 1/10th of a second between each request

class CloudFile:
    def __init__(self, name):
        self.name = name
        self.permissions = {
            'read': [],
            'write': []
        }

    def grant_access(self, user, permission):
        if permission not in ['read', 'write']:
            raise ValueError('Invalid Permission')
        else:
            self.permissions[permission].append(user)
            print(f'{user} has been granted {permission} access to {self.name}.')

    def revoke_access(self, user, permission):
        if user in self.permissions[permission]:
            self.permissions[permission].remove(user)
            print(f'{user}\'s {permission} access to {self.name} has been removed.')
        else:
            print(f'{user} does not have {permission} access to {self.name}.')

    def check_access(self, user, permission):
        if user in self.permissions[permission]:
            return True
        else:
            return False

file1 = CloudFile('Sample File 1')
file2 = CloudFile('Sample File 2')

# Granting access
file1.grant_access('User1', 'read')
file2.grant_access('User2', 'write')

# Revoking access
file2.revoke_access('User2', 'write')

# Checking access
print(file1.check_access('User1', 'read'))  # Returns: True
print(file2.check_access('User2', 'write'))  # Returns: False

import os
from datetime import datetime, timedelta

def delete_old_files(path, days):
    now = datetime.now()
    for f in os.listdir(path):
        file_path = os.path.join(path, f)
        if os.stat(file_path).st_mtime < (now - timedelta(days=days)).timestamp():
            if os.path.isfile(file_path):
                os.remove(file_path)

