def sync_data(device1, device2):
    # Make a copy of the data for reference during synchronization
    original_device1 = device1.copy()
    original_device2 = device2.copy()

    # Sync Device 1 to Device 2
    for key in original_device1:
        if key not in original_device2 or original_device1[key] != original_device2[key]:
            device2[key] = original_device1[key]

    # Sync Device 2 to Device 1
    for key in original_device2:
        if key not in original_device1 or original_device2[key] != original_device1[key]:
            device1[key] = original_device2[key]

