class EventQueue:
    def __init__(self):
        self.events = []

    def enqueue(self, event):
        self.events.append(event)

    def dequeue(self):
        if len(self.events) > 0:
            return self.events.pop(0)
        else:
            return 'No events in the queue'

    def display(self):
        return self.events

