    def __init__(self):
        self.contents = []

    def add_content(self, content):
        if isinstance(content, Content):
            self.contents.append(content)

    def review_content(self, index):
        if 0 <= index < len(self.contents):
            print("Content: ", self.contents[index].text)
            response = input("Approve this content? (yes/no): ")
            if response.lower() == "yes":
                self.contents[index].approved = True
        else:
            print("Invalid index.")

    def view_content(self, index):
        if 0 <= index < len(self.contents):
            print("Content: ", self.contents[index].text)
            print("Author: ", self.contents[index].author)
            print("Approved: ", "Yes" if self.contents[index].approved else "No")
        else:
            print("Invalid index.")

