workflow.add_content(content2)
workflow.review_content(0)
workflow.view_content(0)

class ContentVersioning:
    def __init__(self):
        self.versions = {}

    def create_version(self, content):
        if 'current' not in self.versions:
            version = 1
        else:
            version = self.versions['current'] + 1
        self.versions[version] = content
        self.versions['current'] = version

    def retrieve_version(self, version):
        if version in self.versions:
            return self.versions[version]
        else:
            return "Version not found"

    def get_current_version(self):
        if 'current' in self.versions:
            return self.versions['current']
        else:
            return "No versions available"

