        """Check if a tenant has access to a specific resource."""
        if tenant_id in self.tenants:
            if resource in self.tenants[tenant_id]:
                print(f"Tenant {tenant_id} has access to the resource.")
            else:
                print("Access denied!")
        else:
            print("Tenant does not exist!")

