import warnings
import time

class ResourceLimitExceeded(ResourceWarning):
    pass

class TenantSpecificResourceLimits:
    def __init__(self, tenant_id, cpu_limit=50, memory_limit=1024):
        self.tenant_id = tenant_id
        self.cpu_limit = cpu_limit  # in percentage
        self.memory_limit = memory_limit  # in MB
        self.cpu_usage = 0
        self.memory_usage = 0

    def update_resource_usage(self, cpu_usage=None, memory_usage=None):
        if cpu_usage is not None:
            self.cpu_usage = cpu_usage
        if memory_usage is not None:
            self.memory_usage = memory_usage
        self.check_limits()

    def check_limits(self):
        if self.cpu_usage > self.cpu_limit:
            warnings.warn(f"Tenant {self.tenant_id} has exceeded CPU limit", ResourceLimitExceeded)
        if self.memory_usage > self.memory_limit:
            warnings.warn(f"Tenant {self.tenant_id} has exceeded memory limit", ResourceLimitExceeded)

# Example usage
tenant1 = TenantSpecificResourceLimits("TENANT-1")

for i in range(60):  # Simulating time
    cpu_usage = i * 2  # Assuming CPU usage increases over time
    memory_usage = i * 4  # Assuming Memory usage increases over time

    tenant1.update_resource_usage(cpu_usage, memory_usage)
    time.sleep(1)  # Pause for a second to simulate real-time scenario

