    def validate(self):
        if not isinstance(self.name, str):
            raise ValueError("Name must be a string")
        if not isinstance(self.domain, str):
            raise ValueError("Domain must be a string")
        if not self.domain.endswith('.com') and not self.domain.endswith('.org'):
            raise ValueError("Domain should end with .com or .org")
        if not isinstance(self.memory_limit, int) or self.memory_limit <= 0:
            raise ValueError("Memory Limit must be a positive integer")
        if not isinstance(self.cpu_limit, int) or self.cpu_limit <= 0:
            raise ValueError("CPU Limit must be a positive integer")

