class DynamicQueues:
    def __init__(self, initial_queues):
        self.queues = [list() for _ in range(initial_queues)]

    # Add an element to the queues
    def enqueue(self, item):
        min_len = float('inf')
        min_index = -1
        for i, queue in enumerate(self.queues):
            if len(queue) < min_len:
                min_len = len(queue)
                min_index = i
        self.queues[min_index].append(item)
        # If any queue is more than twice as long as the shortest, add a new queue
        if max([len(q) for q in self.queues]) > 2 * min_len:
            self.queues.append(list())

    # Remove and return an element from the queues
    def dequeue(self):
        while True:
            for queue in self.queues:
                if len(queue) > 0:
                    return queue.pop(0)
            # If all queues are empty, remove a queue and try again
            if len(self.queues) > 1:
                self.queues.pop()
            else:
                raise IndexError("All queues are empty")

    # Return the number of queues currently in use
    def size(self):
        return len(self.queues)

