from flask import Flask, request, jsonify
import jwt  # PyJWT for creating JSON Web Tokens
from functools import wraps
from sklearn.externals import joblib
import os  # Added to access environment variables for secret key

app = Flask(__name__)

# Load the model
model = joblib.load('path_to_your_model')

# A secret key used to encode/decode JWT tokens
SECRET_KEY = os.environ.get('SECRET_KEY', 'Default_Secret_Key')  # Secret key is now retrieved from environment variables, if not available a default value is used

def token_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = None

        if 'x-access-token' in request.headers:
            token = request.headers['x-access-token']

        if not token:
            return jsonify({'message': 'Token is missing!'}), 401

        try:
            data = jwt.decode(token, SECRET_KEY)
        except:
            return jsonify({'message': 'Token is invalid!'}), 401

        return f(*args, **kwargs)
    return decorated

@app.route('/login')
def login():
    # For simplicity, we are not checking the credentials here.
    # In real-world scenarios, you would check these against a database of users.
    token = jwt.encode({'user': 'test_user'}, SECRET_KEY)
    return jsonify({'token': token.decode('UTF-8')})

@app.route('/predict', methods=['POST'])
@token_required
def predict():
    data = request.get_json()
    prediction = model.predict(data['input'])
    return jsonify({'prediction': prediction.tolist()})

if __name__ == '__main__':
    app.run(debug=False)  # Debug mode is now set to False to prevent exposing the Werkzeug debugger

import os
from datetime import datetime
import joblib # Importing joblib instead of pickle

class ModelVersioning:
    def __init__(self, model_path):
        self.model_path = model_path
        if not os.path.exists(self.model_path):
            os.makedirs(self.model_path)

    def save_model(self, model):
        timestamp = datetime.now().strftime("%Y%m%d-%H%M%S")
        versioned_file = f"{self.model_path}/model-{timestamp}.pkl"
        joblib.dump(model, versioned_file)  # Using joblib.dump instead of pickle.dump
        return versioned_file

    def load_model(self, version=None):
        if version is None:
            all_models = [f for f in os.listdir(self.model_path) if f.startswith("model-")]
            latest_model = max(all_models, key=os.path.getctime)
            model_file = f"{self.model_path}/{latest_model}"
        else:
            model_file = f"{self.model_path}/model-{version}.pkl"

        if not os.path.exists(model_file):
            raise FileNotFoundError("Model version does not exist")

        model = joblib.load(model_file)  # Using joblib.load instead of pickle.load
        return model

