import os
from getpass import getpass

class EnvironmentManager:
    def __init__(self):
        self.env = os.environ.copy()  # Make a copy of the current environment variables

    def set_variable(self, key, value=None):
        if not value:  # If no value is provided, prompt securely for input
            value = getpass(f"Enter the value for '{key}': ")
        self.env[key] = value  # Set the variable in our copy of the environment variables

    def apply_variables(self):
        os.environ = self.env  # Apply our changes to the current environment variables

    def print_variable(self, key):
        if key in self.env:
            print(f"{key}: {self.env[key]}")
        else:
            print(f"Environment variable '{key}' is not set.")

if __name__ == "__main__":
