# Define the default and fallback locales.
DEFAULT_LOCALE = 'en_US'
FALLBACK_LOCALE = 'en'

def setup_locale(language):
    """Set up the locale for the application."""
    try:
        return gettext.translation('messages', localedir='locales', languages=[language])
    except FileNotFoundError:
        return gettext.translation('messages', localedir='locales', languages=[FALLBACK_LOCALE], fallback=True)

def set_user_locale(request):
    """Determine the user's preferred locale and set it up."""
    user_language = request.headers.get('Accept-Language')
    if user_language:
        user_language, _ = locale.parse_locale(user_language)
    else:
        user_language = DEFAULT_LOCALE

    translations = setup_locale(user_language)
    return translations.gettext

# Usage in a request context (this is pseudo-code for illustrative purposes):
def handle_request(request):
    _ = set_user_locale(request)
    # Now you can use _('some text') to translate text for the user's locale, falling back to FALLBACK_LOCALE if necessary.

