        if not is_valid_input(job) or job not in jobs:
            print("Error: Invalid job name")
            continue
        backup_status = shutil.which('backup_status')
        if not backup_status or not is_exe(backup_status):
            print("Error: 'backup_status' command not found")
            continue
        result = subprocess.run([backup_status, job], stdout=subprocess.PIPE, check=True)
        print(f"Status of {job}: {result.stdout.decode('utf-8')}")
    time.sleep(60)  # Wait for a minute before checking again

