import docker

def scale_containers(image_name, number_of_instances):
    client = docker.from_env()

    # List all running containers using the specified image
    running_containers = client.containers.list(filters={'ancestor': image_name})

    current_count = len(running_containers)

    if current_count < number_of_instances:
        for _ in range(number_of_instances - current_count):
            client.containers.run(image_name, detach=True)
    elif current_count > number_of_instances:
        containers_to_stop = running_containers[:current_count - number_of_instances]
        for container in containers_to_stop:
            container.stop()
    else:
        print(f"Already have {number_of_instances} instances of {image_name}")

# Use the function to scale your app (replace 'your-app' with your actual docker image)
