from requests.exceptions import RequestException, Timeout

def process_webhook(url, data):
    try:
        response = requests.post(url, json=data, timeout=5)  # Timeout of 5 seconds
        # If the response was successful, no Exception will be raised
        response.raise_for_status()
    except (RequestException, Timeout) as err:
        print ("Oops! An Error Occured")
        print (err)
        return False
    else:
        print ("Webhook processed successfully")
        return True

def handle_failed_webhook(url, data):
    # Retry 3 times with a delay of 1 second between each retry
    for i in range(3):
        if process_webhook(url, data):
            break
        else:
            print ("Failed to process webhook. Attempting to retry... ({} out of 3)".format(i + 1))
            time.sleep(1)
    else:
        print ("Webhook processing failed after 3 attempts.")

