import time
import requests

def retry_webhook(url, payload, retries=5):
    for i in range(retries):
        try:
            response = requests.post(url, json=payload, timeout=5)  # Added timeout parameter here

            if response.status_code == 200:
                print("Webhook delivered successfully!")
                return True
            else:
                print(f"Attempt {i+1} failed with status code {response.status_code}. Retrying...")
        except requests.Timeout:
            print(f"Attempt {i+1} timed out. Retrying...")

        time.sleep(5)  # wait for 5 seconds before retrying
    print("Failed to deliver webhook after multiple attempts.")
    return False

import os
from flask import Flask, request, abort
import hmac
import hashlib

app = Flask(__name__)
SECRET_KEY = os.environ.get('WEBHOOK_SECRET_KEY')  # Retrieve the secret key from an environment variable

@app.route('/webhook', methods=['POST'])
def webhook():
    signature = request.headers.get('X-Hub-Signature')
    if not verify_signature(request.data, SECRET_KEY, signature):
        abort(403)  # or return some error message
    else:
        # process the event data here
        return 'Success'

def verify_signature(payload, secret, signature):
    sha_name, signature = signature.split('=')
    if sha_name != 'sha1':
        return False

    mac = hmac.new(secret.encode(), msg=payload, digestmod=hashlib.sha1)
    return hmac.compare_digest(str(mac.hexdigest()), str(signature))

