import time
from collections import deque
from threading import Lock, Thread

class RateLimiter(object):
    def __init__(self, capacity: int, refill_rate: float):
        self.capacity = capacity  # maximum number of tokens in the bucket
        self.refill_rate = refill_rate  # rate at which tokens are added to the bucket (tokens/second)
        self.tokens = deque()  # token bucket, each element is a timestamp when the token will be available
        self.lock = Lock()  # lock for thread-safety

    def _refill(self):
        now = time.time()
        if self.tokens and self.tokens[0] <= now:
            return  # no need to refill yet

        while len(self.tokens) < self.capacity:
            token_time = now + (len(self.tokens) / self.refill_rate)
            self.tokens.appendleft(token_time)

    def _consume(self):
        if not self.tokens:
            return False  # no tokens available
        now = time.time()
        if self.tokens[-1] <= now:
            self.tokens.pop()
            return True  # token consumed successfully
        else:
            return False  # no tokens available

    def try_consume(self) -> bool:
        with self.lock:
            self._refill()
            return self._consume()

def simulate_webhook():
    rate_limiter = RateLimiter(capacity=5, refill_rate=1)  # allow up to 5 requests per second

    def make_request(n):
        if rate_limiter.try_consume():
            print(f"Request {n} processed.")
        else:
            print(f"Request {n} rejected due to rate limiting.")

    # simulate 10 requests coming in over a period of 5 seconds
    for i in range(1, 11):
        Thread(target=make_request, args=(i,)).start()
        time.sleep(0.5)  # delay between requests

if __name__ == "__main__":
    simulate_webhook()

