class PaymentGatewayError(Exception):
    pass

class ConnectionError(PaymentGatewayError):
    def __init__(self, message="Unable to connect to the payment gateway"):
        self.message = message
        super().__init__(self.message)

class TimeoutError(PaymentGatewayError):
    def __init__(self, message="The request to the payment gateway timed out"):
        self.message = message
        super().__init__(self.message)

class InvalidTransactionError(PaymentGatewayError):
    def __init__(self, message="The transaction is invalid"):
        self.message = message
        super().__init__(self.message)

