class Account:
    def __init__(self, username):
        self.username = username
        self.password = None
        self.lockout_attempts = 0

    def authenticate(self, password):
        if self.password == password:
            return True
        else:
            self.increment_lockout_attempts()
            return False

    def increment_lockout_attempts(self):
        self.lockout_attempts += 1

    def reset_lockout(self):
        self.lockout_attempts = 0

def main():
    username = input("Enter your username: ")
    account = Account(username)

    while True:
        password = input("Enter your password: ")

        if account.authenticate(password):
            print("Login successful.")
            break
        else:
            print("Incorrect password. You have been locked out.")
            if account.lockout_attempts >= 5:
                print("You have exceeded the maximum allowed attempts. Account has been permanently disabled.")

