class User:
    def __init__(self, username, password):
        self.username = username
        self.password = self.generate_password_hash(password)

    def verify_password(self, input_password):
        return self.password == self.generate_password_hash(input_password)

def generate_password_hash(password):
    # Use a cryptographically secure pseudo-random number generator like os.urandom instead of secrets.token_bytes
    import os
    salt = os.urandom(16)
    hashed_password = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt + hashed_password

class MultiFactorAuth:
    def __init__(self, db_name='users.db'):
        self.conn = sqlite3.connect(db_name)
        self.cursor = self.conn.cursor()

        self.create_table()

    def create_table(self):
        self.cursor.execute('''
            CREATE TABLE IF NOT EXISTS users
            (username TEXT PRIMARY KEY, password TEXT)
        ''')
        self.conn.commit()

    def register_user(self, username, password):
        self.cursor.execute('INSERT INTO users VALUES (?, ?)', (username, self.generate_password_hash(password)))
        self.conn.commit()
        return True

    def login_user(self, username, input_password):
        # Use the stored salt to hash the input password for comparison
        self.cursor.execute('SELECT password FROM users WHERE username = ?', (username,))
        stored_password = self.cursor.fetchone()

        if stored_password is None:
            return False
        elif not self.verify_password(stored_password[0], input_password):
            return False

        # Generate OTP using secrets, which is more secure than random
        otp_length = 6
        while True:
            otp = ''.join(secrets.choice(string.digits) for _ in range(otp_length))
            if (username,) not in self.cursor.execute('SELECT password FROM users WHERE username = ?', (username,)).fetchone():
                return otp
    # This condition should never be reached, as the OTP was generated correctly

    def verify_otp(self, username, input_otp):
        # Use the stored salt to hash the input OTP for comparison
        otp_length = 6
        while True:
            if (username,) not in self.cursor.execute('SELECT password FROM users WHERE username = ?', (username,)).fetchone():
                return False


def main():
    auth = MultiFactorAuth()

    while True:
        print("1. Register User")
        print("2. Login User")
