from http import cookies
import base64
from flask import Flask, request, session

app = Flask(__name__)

def create_session_id():
    """
    Generate a unique session ID.
    :return: Session ID as string
    """
    return base64.b64encode(str(id()).encode('utf-8')).decode()

@app.before_request
def before_request():
    """
    Create a new session if one does not exist, or update the existing session with new data.
    """
    if 'session_id' not in session:
        session['session_id'] = create_session_id()
        print(f"New session created with ID: {session['session_id']}")

@app.after_request
def after_request(response):
    """
    Store the request ID and response status code in the session.
    :param response: Response object from the Flask framework
    :return: Response object
    """
    session['request_id'] = str(id())
    session['status_code'] = response.status_code
    return response

@app.route('/login', methods=['POST'])
def login():
    """
    Login function to set a user's username in the session.
    :return: Redirect to the home page after successful login
    """
    username = request.form.get('username')
    if username:
        session['user'] = username
        return 'Login successful. You are now logged in.'
    else:
        return 'Invalid username or password.', 401

@app.route('/logout', methods=['POST'])
def logout():
    """
    Logout function to clear the user's username from the session.
    :return: Redirect to the home page after successful logout
    """
    if 'user' in session and session['user']:
        del session['user']
    return 'Logout successful. You are now logged out.'

@app.route('/home', methods=['GET'])
def home():
    """
    Home function to display a welcome message with the user's name.
    :return: A welcome message with the user's name
    """
    if 'user' in session and session['user']:
        return f'Welcome, {session["user"]}!'
    else:
        return 'You are not logged in.'

if __name__ == '__main__':
    app.run(debug=False)

import jwt
from datetime import datetime, timedelta
from functools import wraps
import base64
import hashlib
import secrets

# Set secret key for JWT (use a secure method to generate and store this key)
def get_secret_key():
    return secrets.token_hex(16)

SECRET_KEY = get_secret_key()

def authenticate(username, password):
    # Replace with your actual user database or library
    users = {
        'admin': 'password123',
        'user': 'password456'
    }

    if username in users and hashlib.sha256(str(users[username]).encode()).hexdigest() == hashlib.sha256(password.encode()).hexdigest():
        return True
    else:
        return False

def generate_token(user_id, expires_in=300):
    payload = {
        'exp': datetime.utcnow() + timedelta(seconds=expires_in),
        'iat': datetime.utcnow(),
        'sub': user_id,
        # Removed 'user' from the payload to avoid hardcoded username
    }

    # Use a secure method to encode the token
    token = jwt.encode(payload, SECRET_KEY, algorithm='HS256')
    return token

def verify_token(token):
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=['HS256'])
        return True
    except jwt.ExpiredSignatureError:
        return False
    except jwt.InvalidTokenError:
        return False

def authenticate_decorator(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        username = input("Please enter your username: ")
        password = input("Please enter your password: ")

        if authenticate(username, password):
            token = generate_token(username)
            print(f"Welcome {username}! Here's your token: {token}")

            # Verify the token
            if verify_token(token):
                return func(*args, **kwargs)
            else:
                print("Invalid token. Please try again.")
        else:
            print("Invalid credentials. Please try again.")

    return wrapper

@authenticate_decorator
def protected_function():
    print("Hello from protected function!")

protected_function()

import re

class Permissions:
    def __init__(self):
        self.permissions = {}

    def add_permission(self, resource, permission_level):
        """Add a new permission to the system."""
        if resource in self.permissions:
            raise Exception(f"Permission level {permission_level} already exists for resource {resource}.")

        # Add the permission to the dictionary
        self.permissions[resource] = permission_level

    def update_permission(self, resource, permission_level):
        """Update an existing permission for a resource."""
        if resource not in self.permissions:
            raise Exception(f"Permission level {permission_level} does not exist for resource {resource}.")

        # Update the permission to the dictionary
        self.permissions[resource] = permission_level

    def get_permission(self, resource):
        """Get the current permission level for a resource."""
        if resource in self.permissions:
            return self.permissions[resource]
        else:
            raise Exception(f"No permission found for resource {resource}.")

    def validate_access(self, user, resource):
        """Validate access permissions for a given user and resource."""
        # Use regular expressions to check for matching patterns
        pattern = re.compile(r"\d+")

        if resource in self.permissions:
            level = self.permissions[resource]

            # If the resource exists and we have permission, return True
            if level == "admin":
                return True

            # If the user matches the pattern (e.g., has a number in their username), return True
            elif pattern.match(user):
                return True

        # Return False otherwise
        return False

# Example usage:
permissions = Permissions()

# Add some permissions for resources
permissions.add_permission("admin_access", "admin")
permissions.add_permission("read_only_data", "user")

# Validate access for a user
print(permissions.validate_access("john_doe_123", "admin_access"))  # Returns: True
print(permissions.validate_access("johndoe123", "admin_access"))   # Returns: True (because of the number in their username)
print(permissions.validate_access("johndoe", "admin_access"))     # Returns: False

# Validate access for a non-existent resource
try:
    print(permissions.validate_access("john_doe_123", "non_existent_resource"))
except Exception as e:
    print(e)  # Outputs: Permission level admin does not exist for resource non_existent_resource.

