import defusedxml.ElementTree as ET
from typing import Any

class Person:
    def __init__(self, name: str, age: int):
        self.name = name
        self.age = age

def serialize_to_xml(obj: Person) -> bytes:
    root = ET.Element('person')
    for key, value in obj.__dict__.items():
        child = ET.SubElement(root, key)
        child.text = str(value)
    return ET.tostring(root, encoding='unicode')

from defusedxml import DefusedXMLDocument

def deserialize_from_xml(xml: bytes) -> Any:
    document = DefusedXMLDocument.fromstring(xml)
    obj = {}
    for child in document.findall('.//'):
        key = child.tag
        value = child.text
        try:
            if not isinstance(value, int):
                raise ValueError(f"Invalid data type. Expected an integer, but got {str(value)}")
            obj[key] = value
        except ValueError as e:
            raise ValueError(f"Invalid data type. Expected an integer, but got {str(e)}")
    return obj

def main():
    p = Person("John Doe", 30)
    xml = serialize_to_xml(p)
    try:
        p_deserialized = deserialize_from_xml(xml)
        print(p_deserialized)
    except ValueError as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    main()

from defusedxml.ElementTree import ElementTree as ET
from defusedxml.ElementTree import fromstring as from_defusedxml

class Person:
    def __init__(self, name, age):
        self.name = name
        self.age = age

    @classmethod
    def from_xml(cls, element):
        return cls(element.attrib['name'], int(element.find('age').text))

class Address:
    def __init__(self, street, city, state, zip_code):
        self.street = street
        self.city = city
        self.state = state
        self.zip_code = zip_code

    @classmethod
    def from_xml(cls, element):
        return cls(element.attrib['street'], 
                   element.find('city').text,
                   element.find('state').text,
                   element.find('zip_code').text)

class PersonWithAddress:
    def __init__(self, person, address):
        self.person = person
        self.address = address

    @classmethod
    def from_xml(cls, root):
        person_element = root.find('.//person')
        address_element = root.find('.//address')

        if not person_element or not address_element:
            raise ValueError("Invalid XML structure")

        return cls(Person.from_xml(person_element), Address.from_xml(address_element))

