import pickle

class NetworkObject:
    def __init__(self, name, value):
        self.name = name
        self.value = value

def load_deserialized_network_object(data: bytes) -> NetworkObject:
    """
    Loads deserialized network object from the given binary data safely.

    Args:
        data (bytes): Binary data received over the network.

    Returns:
        NetworkObject: Deserialized network object, or None if deserialization failed.
    """
    try:
        # Use 'pickle.loads' with 'protocol=2' to prevent arbitrary code execution
        obj = pickle.loads(data, protocol=2)
        return NetworkObject(obj.get('name'), obj.get('value'))
    except KeyError as e:
        print(f"Error deserializing object: key {e} not found")
        raise  # Re-raise the exception instead of returning None
    except Exception as e:
        print(f"Error deserializing object: {e}")
        return None

def main():
    # Simulate receiving binary data from a network connection
    network_data = b'pickle dumped name="example" value=42'

    # Load and deserialize the network object safely
    obj = load_deserialized_network_object(network_data)

    if obj:
        print(f"Deserialized Object: {obj.name} = {obj.value}")
    else:
        print("Failed to deserialize object")

if __name__ == "__main__":
    main()

import socket
import struct
import os

# Define constants
BUF_SIZE = 1024
PACKET_SIZE = 512

class NetworkPacket:
    def __init__(self):
        self.packet_type = None
        self.payload_length = None
        self.payload_data = None

    def parse_packet(self, packet):
        # Parse packet header (assuming a simple header structure)
        self.packet_type = struct.unpack('H', packet[0:2])[0]
        self.payload_length = struct.unpack('I', packet[4:8])[0]

        # Parse payload data
        if len(packet) >= 8 + self.payload_length:
            self.payload_data = packet[8:self.payload_length+8]
        else:
            print("Insufficient data to parse packet")

# Create a socket connection
def create_socket_connection(host, port):
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    try:
        sock.connect((host, port))
        return sock
    except ConnectionRefusedError:
        print(f"Connection refused by host {host}:{port}")
        return None

# Read incoming packets from the socket connection
def read_packets(sock):
    while True:
        packet = b''
        buf_size = BUF_SIZE
        while len(packet) < PACKET_SIZE:
            chunk = sock.recv(buf_size)
            if not chunk:
                break
            packet += chunk
            buf_size = min(buf_size, len(chunk))
        return packet

# Parse incoming packets and store them in the NetworkPacket object
def parse_packets(sock, network_packet):
    while True:
        packet = read_packets(sock)
        if not packet:
            break
        print("Packet Type:", hex(network_packet.packet_type))
        print("Payload Length:", struct.unpack('I', packet[0:4])[0])
        print("Payload Data:", packet[8:])
        # Handle payload data (e.g., process it, store it in a database, etc.)

# Main function
def main():
    host = '127.0.0.1'  # Replace with your IP address
    port = 12345

    network_packet = NetworkPacket()
    sock = create_socket_connection(host, port)
    if sock:
        while True:
            parse_packets(sock, network_packet)

