import requests
import json

def send_request(url, timeout=10):
    try:
        response = requests.get(url, timeout=timeout)
        response.raise_for_status()
        return response.json()
    except requests.exceptions.HTTPError as http_err:
        print(f'HTTP Error: {http_err}')
    except requests.exceptions.ConnectionError as conn_err:
        print(f'Connection Error: {conn_err}')
    except requests.exceptions.Timeout as time_err:
        print(f'Timeout Error: {time_err}')
    except requests.exceptions.RequestException as err:
        print(f'Error: {err}')
    return None

def handle_errors(response):
    if response is not None:
        try:
            data = response
            # Validate the data here, for example:
            # Check if it's a dictionary or list
            if not isinstance(data, (dict, list)):
                raise ValueError('Invalid data type')
            # Handle any other validation errors you might have
            return data
        except Exception as e:
            print(f'Error: {e}')
    return None

def main():
    url = 'http://example.com/api/data'
    response = send_request(url)
    handled_response = handle_errors(response)
    if handled_response is not None:
        print(json.dumps(handled_response, indent=4))

if __name__ == "__main__":
    main()

from flask import Flask, request, Response
import time
from functools import wraps

app = Flask(__name__)

max_requests_per_ip = 100
time_window = 60
ip_request_counts = {}

def check_rate_limiting(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        now = int(time.time())

        ip_address = request.remote_addr

        if ip_address not in ip_request_counts:
            ip_request_counts[ip_address] = {'count': 0, 'timestamp': now}

        ip_request_counts[ip_address]['count'] += 1

        if ip_request_counts[ip_address]['count'] > max_requests_per_ip:
            if now - ip_request_counts[ip_address]['timestamp'] < time_window:
                ip_request_counts[ip_address] = {'count': 0, 'timestamp': 0}

            return "Rate limit exceeded. Please try again later.", 429

        response = f(*args, **kwargs)

        # Create a dictionary to store the count and timestamp for each IP
        ip_count_dict = {}
        if ip_address in ip_request_counts:
            ip_count_dict[ip_request_counts[ip_address]['ip']] = {'count': ip_request_counts[ip_address]['count'], 'timestamp': ip_request_counts[ip_address]['timestamp']}

        # Only update the dictionary if the rate limit is not exceeded
        if response.status_code != 429:
            ip_request_counts[ip_address] = {'count': 0, 'timestamp': now}

        return Response(response.data, status=response.status_code, headers={
            'X-RateLimit-Count': str(ip_count_dict.get(ip_address, {}).get('count', 0)),
            'X-RateLimit-Timestamp': str(int(time.time()))
        })

    return decorated_function

@app.before_request
def _():
    pass

@app.after_request
def add_headers(response):
    # Only add the headers if the rate limit is not exceeded
    if response.status_code != 429:
        response.headers['X-RateLimit-Count'] = str(ip_request_counts.get(request.remote_addr, {}).get('count', 0))
        response.headers['X-RateLimit-Timestamp'] = str(int(time.time()))

    return response

if __name__ == '__main__':
    import waitress
    app.run(host='0.0.0.0', port=8080, debug=False)

import subprocess

def execute_shell_script(script_path):
    """
    Execute a shell script using the subprocess module.

    Args:
        script_path (str): The path to the shell script file.

    Returns:
        str: The output of the executed script.
    """

    # Define the command to be executed, avoiding partial executable paths
    # Using a relative path for consistency and readability
    command = [script_path]  # directly use script_path instead of bash -c

    try:
        # Use subprocess.run with capture_output=True and text argument set to True
        # to prevent shell injection and avoid bytes encoding issues
        result = subprocess.run(command, capture_output=True, text=True)

        if result.returncode == 0:
            # return output as is since it's already a string
            return result.stdout.strip()
        else:
            raise ValueError(f"Error executing shell script: {result}")

    except FileNotFoundError as e:
        print(f"Shell script not found at {script_path}")
        raise

    except subprocess.CalledProcessError as e:
        print(f"Error executing shell script: {e}")
        raise

def main():
    # Define the path to your shell script
    script_path = 'path_to_your_script.sh'

    try:
        # Execute the shell script and get its output
        output = execute_shell_script(script_path)

        if output:
            print(output)

    except Exception as e:
        print(f"An error occurred: {e}")

if __name__ == "__main__":
    main()

