import re

def validate_phone_number(phone_number):
    # Regular expression pattern for US phone numbers
    pattern = re.compile(r'^\(?([0-9]{3})\)?[-. ]?([0-9]{3})[-. ]?([0-9]{4})$')

    # Check if the phone number matches the pattern
    if pattern.match(phone_number):
        return True
    else:
        return False

