from flask import Flask, redirect, url_for, send_from_directory
import os

app = Flask(__name__)

# Set up a directory to store custom error images
error_images_dir = 'static/error_images'

if not os.path.exists(error_images_dir):
    os.makedirs(error_images_dir)

def get_error_image_path(status_code):
    # Map status codes to corresponding error image names
    error_image_map = {
        400: 'bad_request.png',
        401: 'unauthorized.png',
        403: 'forbidden.png',
        404: 'not_found.png'
    }

    return os.path.join(error_images_dir, error_image_map.get(status_code, 'default_error.png'))

@app.errorhandler(404)
def not_found(e):
    # Display a custom 404 error page
    image_path = get_error_image_path(404)
    return send_from_directory(error_images_dir, image_path), 404

@app.errorhandler(500)
def internal_server_error(e):
    # Display a custom 500 error page
    image_path = get_error_image_path(500)
    return send_from_directory(error_images_dir, image_path), 500

if __name__ == '__main__':
    app.run(debug=False)

import logging
