import hashlib
import os
import json
import uuid

# Define a dictionary to store users and their hashed passwords
users = {}

def hash_password(password):
    """Hash the password using SHA-256"""
    return hashlib.sha256(str(password).encode()).hexdigest()

def create_user(username, password):
    """Create a new user with the given username and password."""
    hashed_password = hash_password(password)
    users[username] = {
        "hashed_password": hashed_password,
        "session_id": str(uuid.uuid4())
    }
    return users[username]

def login(username, password):
    """Check if the provided username and password match an existing user's credentials."""
    if username in users:
        stored_hashed_password = users[username]["hashed_password"]
        if hash_password(password) == stored_hashed_password:
            # Generate a new session ID
            users[username]["session_id"] = str(uuid.uuid4())
            return users[username]
    return None

def update_session(username, token):
    """Update the user's session ID with the provided token."""
    if username in users:
        users[username]["session_id"] = token
    else:
        print("User not found")

def close_session(username):
    """Close and remove a user's session."""
    if username in users:
        del users[username]

# Example usage:

user1 = create_user("user1", "password123")
print(user1)

user2 = login("user1", "password123")
print(user2)

update_session("user1", "new_session_id")
print(user2["session_id"])

close_session("user1")

try:
    print(login("user1", "wrong_password"))
except Exception as e:
    print(e)

import time
import threading

class SessionManager:
    def __init__(self):
        self.sessions = {}

    def start_session(self, user_id):
        if user_id not in self.sessions:
            self.sessions[user_id] = {'created_at': time.time()}
            return True
        else:
            print("User already exists.")
            return False

    def expire_sessions_after_inactivity(self, inactivity_timeout):
        while True:
            current_time = time.time()
            for user_id, session_data in list(self.sessions.items()):
                if (current_time - session_data['created_at']) > inactivity_timeout:
                    del self.sessions[user_id]
                    print(f"Session with ID {user_id} expired after {inactivity_timeout} seconds.")
            time.sleep(1)

def main():
    session_manager = SessionManager()

    # Start the timer thread
    threading.Thread(target=session_manager.expire_sessions_after_inactivity, args=(300,)).start()

    while True:
        user_id = input("Enter user ID to start a new session (or 'q' to quit): ")
        if user_id.lower() == 'q':
            break
        elif session_manager.start_session(user_id):
            print(f"Session with ID {user_id} started.")
        else:
            print("Failed to start session.")

if __name__ == "__main__":
    main()

import os
import base64
from flask import Flask, session, request

app = Flask(__name__)

# Generate a random secret key
def generate_secret_key():
    return os.urandom(16).hex()

# Generate a new session ID
def generate_session_id():
    # Use the generated secret key for encoding
    encoded_id = base64.b64encode(generate_secret_key() + b'\x00' + str(os.getpid())).decode('utf-8')
    return encoded_id

app.config['SECRET_KEY'] = generate_secret_key()

# In a real application, this would typically be stored in a database
users = {
    'user1': {'username': 'john', 'email': 'john@example.com'},
    'user2': {'username': 'jane', 'email': 'jane@example.com'}
}

def get_user_data(user_id):
    return users.get(user_id)

@app.route('/login', methods=['POST'])
def login():
    user_id = request.form['user_id']
    if not user_id:
        return 'Invalid user ID'

    # Generate a new session ID
    session['session_id'] = generate_session_id()
    user_data = get_user_data(user_id)

    # Add the user data to the session
    session['user_data'] = {
        'username': user_data.get('username'),
        'email': user_data.get('email')
    }

    return 'Login successful'

@app.route('/logout', methods=['GET'])
