from flask import Flask, request, jsonify
from functools import wraps

app = Flask(__name__)

# Define allowed roles
ALLOWED_ROLES = ["admin", "moderator"]

def role_required(role):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            if "role" not in request.args or request.args["role"] not in ALLOWED_ROLES:
                return jsonify({"error": "Invalid role"}), 401
            elif check_permissions(request.args["role"], func):
                return func(*args, **kwargs)
            else:
                return jsonify({"error": "Invalid role or permissions"}), 401
        def check_permissions(role, original_func):
            if role == "admin":
                return True
            elif role == "moderator":
                return False
            else:
                raise ValueError("Unknown role")
        return wrapper
    return decorator

@app.route("/admin/resource", methods=["GET"])
@role_required("admin")
def admin_resource():
    return jsonify({"message": "Admin resource accessed successfully"}), 200

@app.route("/moderator/resource", methods=["GET"])
@role_required("moderator")
def moderator_resource():
    if check_permissions(request.args["role"], lambda: True):
        return jsonify({"message": "Moderator resource accessed successfully"}), 200
    else:
        return jsonify({"error": "Invalid role or permissions"}), 401

@app.route("/public/resource", methods=["GET"])
def public_resource():
    return jsonify({"message": "Public resource accessed successfully"}), 200

if __name__ == "__main__":
    app.run(debug=False)

class User:
    def __init__(self, username, password, roles):
        self.username = username
        self.password = password
        self.roles = roles

class Role:
    def __init__(self, rolename, permissions):
        self.rolename = rolename
        self.permissions = permissions

class AccessControl:
    def __init__(self):
        self.users = {}
        self.roles = {}

    def add_user(self, username, password, roles):
        self.users[username] = User(username, password, roles)

    def add_role(self, rolename, permissions):
        self.roles[rolename] = Role(rolename, permissions)

    def authenticate(self, username, password):
        if username in self.users and self.users[username].password == password:
            return True
        return False

    def has_permission(self, username, role_name, permission):
        user_roles = [role.rolename for role in self.users[username].roles]
        if role_name in user_roles:
            return permission in [r.permissions for r in self.roles[role_name]]
        return False

# Example usage
