class User:
    def __init__(self, name, role):
        self.name = name
        self.role = role
        self.permissions = None

    def set_permissions(self, permissions):
        """Sets user permissions"""
        if not isinstance(permissions, list) or len(permissions) == 0:
            raise ValueError("Permissions must be a non-empty list")
        self.permissions = permissions


class PrivilegesValidator:
    def __init__(self):
        # Define default roles and their corresponding permissions
        self.roles = {
            "admin": ["create_user", "delete_user", "edit_user", "view_users"],
            "moderator": ["view_users", "edit_user"],
            "user": ["view_user"]
        }

    def validate_privileges(self, user):
        """Validates user privileges"""
        if not hasattr(user, 'role'):
            raise ValueError("User role is missing")

        if user.role not in self.roles:
            return f"Unknown role: {user.role}"

        for permission in user.permissions:
            if permission not in self.roles[user.role]:
                return f"Permission '{permission}' does not match role '{user.role}'"
        return "Privileges validated successfully"


def main():
    validator = PrivilegesValidator()

    # Create users
    admin = User("Admin", "admin")
    moderator = User("Moderator", "moderator")
    user1 = User("User 1", "user")

    # Set permissions for each user
    admin.set_permissions(["create_user", "delete_user"])
    moderator.set_permissions(["view_users", "edit_user"])
    user1.set_permissions(["view_user"])

    # Validate privileges
    print(validator.validate_privileges(admin))
    print(validator.validate_privileges(moderator))
    print(validator.validate_privileges(user1))


if __name__ == "__main__":
    main()

import os
import subprocess

class UserLimiter:
    def __init__(self):
        self.allowed_commands = ['ls', 'cd', 'mkdir']

    def check_privileges(self, command):
        # Check if the user has the required privileges for the command
        return command in self.allowed_commands

    def execute_command(self, command, *args):
        # Limit the execution of commands to the allowed list
        if not self.check_privileges(command):
            print(f"Command '{command}' is not allowed.")
            return False

        try:
            # Execute the command using subprocess with input filtering
            if not args and b'' in [bytes(arg, 'utf-8') for arg in args]:
                raise Exception("No untrusted input")
            result = subprocess.run([command] + [arg.encode('utf-8') for arg in args], check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            return result.returncode == 0 and result.stdout.decode('utf-8').strip() == '' and result.stderr.decode('utf-8').strip() == ''
        except Exception as e:
            print(f"Error executing command: {e}")
            return False

# Example usage:
limiter = UserLimiter()

# Allow a user to execute commands
if limiter.execute_command('ls', '-l'):
    print("Command executed successfully.")
else:
    # Limit the execution of other commands
    if limiter.execute_command('cd', '/path/to/directory'):
        print("Directory changed successfully.")
    else:
        print("Error changing directory.")

class AccessLevel:
    def __init__(self, name, parent=None):
        self.name = name
        self.parent = parent
        self.children = []

    def add_child(self, child):
        if isinstance(child, AccessLevel):
            self.children.append(child)
            child.parent = self

    def get_all_children(self):
        children = []
        if self.parent:
            children.extend(self.parent.get_all_children())
        children.append(self)
        return children


class System:
    def __init__(self):
        self.access_levels = {}

    def add_access_level(self, name, parent_name=None):
        if parent_name in self.access_levels:
            parent = self.access_levels[parent_name]
        else:
            # default parent is the root
            parent = AccessLevel('Root')
            self.access_levels['Root'] = parent

        new_level = AccessLevel(name, parent)
        self.access_levels[name] = new_level

    def get_access_level(self, name):
        return self.access_levels.get(name)


# Usage:
system = System()
system.add_access_level('Public', None)
system.add_access_level('Private', 'Public')
system.add_access_level('Admin', 'Private')

public_level = system.get_access_level('Public')
admin_level = public_level.children[0].children[0]

print(admin_level.name)  # prints: Admin
print(admin_level.parent.name)  # prints: Public
print(admin_level.parent.parent.name)  # prints: Root

