# Define a decorator that verifies permissions and raises an exception if not met.
def verify_permissions(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        # Get the current working directory.
        cwd = os.getcwd()

        # Check if the current user has permission to write to the directory.
        try:
            with open(cwd + "/test.txt", "w") as f:
                pass
        except PermissionError:
            raise Exception(f"Permission denied in directory {cwd}.")

    return wrapper

