# Define allowed file extensions
ALLOWED_EXTENSIONS = set(['txt', 'pdf', 'jpg', 'jpeg', 'png'])

def allow_file(filename):
    if not filename:
        return False
    if '.' in filename:
        ext = filename.split('.')[-1]
        if ext in ALLOWED_EXTENSIONS:
            return True
    return False

@app.route('/upload', methods=['POST'])
