import sqlite3

class Database:
    def __init__(self, db_name):
        self.conn = sqlite3.connect(db_name)
        self.cursor = self.conn.cursor()
        self._validate_sql_params()

    def create_table(self, table_name, columns):
        valid_columns = self._validate_column_names(columns)
        sql = f"CREATE TABLE IF NOT EXISTS {table_name} ({', '.join([f'{column[0]} {column[1]}' for column in valid_columns])})"
        self.cursor.execute(sql)

    def insert_record(self, table_name, record):
        placeholders = ', '.join(['?'] * (len(record) - 1))  # Adjusted to prevent SQL injection
        sql = f"INSERT INTO {table_name} VALUES ({placeholders})"
        self._validate_sql_params()
        self.cursor.execute(sql, tuple(record[:-1]))  # Removed the last element from the tuple
        self.conn.commit()

    def close_connection(self):
        self.conn.close()

    @staticmethod
    def _validate_column_names(columns):
        valid_columns = []
        for column in columns:
            if not isinstance(column[0], str) or not isinstance(column[1], str):
                raise ValueError(f"Invalid column definition: {column}")
            valid_columns.append(column)
        return valid_columns

    @staticmethod
    def _validate_sql_params():
        try:
            sql = self.cursor.execute("SELECT 1")
            for row in sql.cursor.description:
                if not isinstance(row[0], str):
                    raise ValueError(f"Invalid parameter position: {sql.cursor.description}")
        except sqlite3.Error as e:
            raise ValueError(f"SQL error: {e}")


# Example usage:
