    ]
    for record in records:
        db.insert_record('users', record)

    # Close connection
    db.close_connection()

import sqlite3

class Database:
    def __init__(self, db_name):
        self.conn = sqlite3.connect(db_name)
        self.cursor = self.conn.cursor()
        self.create_table()

    def create_table(self):
        self.cursor.execute('''
            CREATE TABLE IF NOT EXISTS users (
                id INTEGER PRIMARY KEY,
                name TEXT NOT NULL,
                age INTEGER NOT NULL
            )
        ''')
        self.conn.commit()

    def insert_data(self, name, age):
        self.cursor.execute('INSERT INTO users (name, age) VALUES (?, ?)', (name, age))
        self.conn.commit()

    def delete_record(self, criteria):
        self.cursor.execute('DELETE FROM users WHERE ?', criteria)
        self.conn.commit()
        print(f"Record(s) deleted: {self.get_deleted_count()}")

    def get_deleted_count(self):
        self.cursor.execute('SELECT COUNT(*) FROM users')
        return self.cursor.fetchone()[0]

    def display_data(self):
        self.cursor.execute('SELECT * FROM users')
        rows = self.cursor.fetchall()
        for row in rows:
            print(row)

def main():
    db_name = 'users.db'
    database = Database(db_name)

    while True:
        print("1. Insert Data")
        print("2. Delete Record")
        print("3. Display Data")
        print("4. Exit")

        choice = input("Enter your choice: ")

        if choice == "1":
            name = input("Enter Name: ")
            age = int(input("Enter Age: "))
            database.insert_data(name, age)
        elif choice == "2":
            criteria = {}
            for key in ['name', 'age']:
                val = input(f"Enter {key}: ")
                if key == 'name':
                    criteria[key] = ('%', val, '%')
                else:
                    criteria[key] = (val,)
            database.delete_record(criteria)
        elif choice == "3":
            database.display_data()
        elif choice == "4":
            break
        else:
            print("Invalid choice. Please try again.")

if __name__ == "__main__":
    main()

import os
import subprocess

def safe_execute(command):
    """
    Safely executes a command by validating input.

    Args:
        command (str): The command to execute

    Returns:
        str: The output of the command
    """
    # Validate input using a maximum length to prevent buffer overflows
    if len(command) > 1024:
        raise ValueError("Command is too long")

    try:
        # Execute the command and capture output, disabling shell injection
        return subprocess.check_output(command.encode('utf-8'), 
                                      stdout=subprocess.PIPE, 
                                      stderr=subprocess.STDOUT).decode('utf-8')
    except subprocess.CalledProcessError as e:
        print(f"Error executing command: {e}")
        return None

