            print(output)
        except ValueError as e:
            print(e)

class Node:
    def __init__(self, value):
        self.value = value
        self.next = None


class LinkedList:
    def __init__(self):
        self.head = None

    def add_node(self, node_value):
        if not self.head:
            self.head = Node(node_value)
        else:
            current = self.head
            while current.next:
                current = current.next
            current.next = Node(node_value)

    def remove_dangling_pointers(self):
        # Create a set to store visited nodes
        visited = set()

        # Start the traversal from the head
        current = self.head

        while current:
            if id(current) not in visited:
                # Mark the node as visited and add it to the set
                visited.add(id(current))

                # Move to the next node
                current = current.next

            else:
                # If a dangling pointer is found, remove it from the linked list
                current.next = None


# Usage of the program
if __name__ == "__main__":
    ll = LinkedList()

    # Add nodes to the linked list
    for i in range(5):
        ll.add_node(i)

    # Remove dangling pointers
    print("Linked List after removing dangling pointers:")
    current = ll.head
    while current:
        print(current.value, end=" -> " if current.next else "\n")
        current = current.next

    # Create a new list that contains the same values as our previous one,
    # but with some nodes removed. This should be done in such a way that it creates dangling pointers.
    ll2 = LinkedList()
    for i in range(5):
        if i % 2 == 0:
            ll2.add_node(i)

    # Remove dangling pointers
    print("Linked List after removing dangling pointers:")
    current = ll2.head
    while current:
        print(current.value, end=" -> " if current.next else "\n")
        current = current.next

import threading

class KeyValueStore:
    def __init__(self):
        self.store = {}
        self.lock = threading.Lock()

    def put(self, key, value):
        with self.lock:
            self.store[key] = value

    def get(self, key):
        with self.lock:
            return self.store.get(key)

# Example usage
store = KeyValueStore()
store.put('name', 'John Doe')
print(store.get('name'))  # Output: John Doe

import functools
from datetime import timedelta, datetime

class Cache:
    def __init__(self):
        self.cache = {}

    def get(self, key):
        if key in self.cache:
            return self.cache[key]
        else:
            raise KeyError(f"Key {key} not found")

    def set(self, key, value, timeout=None):
        if timeout is None:
            self.cache[key] = value
        else:
            expires_at = datetime.now() + timedelta(seconds=timeout)
            self.cache[key] = (value, expires_at)

def lru_cache(maxsize):
    cache = Cache()
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = str((args, kwargs))
            result = cache.get(key)
            if result:
                return result[0]
            else:
                result = func(*args, **kwargs)
                cache.set(key, result)
                return result
        return wrapper
    return decorator

# Example usage:

@lru_cache(maxsize=32)  # Cache 32 results
def expensive_function(x):
    import time
    time.sleep(2)  # Simulate an expensive computation
    return x * x

print(expensive_function(10))  # First call, takes 2 seconds
print(expensive_function(10))  # Second call, returns immediately from cache

