cache.set('example_key', 'new_value')
print(get_value('example_key'))  # Returns the new value

import time
import os

class Cache:
    def __init__(self):
        self.cache = {}

    def update_data(self, key, data):
        # Generate a timestamp to invalidate cache
        timestamp = int(time.time())

        # Check if the key exists in the cache
        if key in self.cache:
            # Invalidate cache by deleting the file
            self._delete_file(key)

            # Update the cache with new data
            self.cache[key] = {'data': data, 'timestamp': timestamp}
        else:
            self.cache[key] = {'data': data, 'timestamp': timestamp}

    def get_data(self, key):
        return self.cache.get(key)

    def _delete_file(self, filename):
        try:
            # Delete the cache file
            os.remove(filename)
        except FileNotFoundError:
            pass  # Cache file does not exist

# Example usage
cache = Cache()

# Update data and invalidate cache
cache.update_data('key1', 'Data 1')
print(cache.get_data('key1'))  # {'data': 'Data 1', 'timestamp': ...}

time.sleep(5)  # Wait for 5 seconds to simulate cache expiration

# Try getting data again; cache has been invalidated
print(cache.get_data('key1'))  # Cache not found

import os
import redis
from flask import Flask, jsonify, request

# Initialize the app and Redis client
app = Flask(__name__)
redis_client = redis.Redis(host='localhost', port=6379, db=0)

# Function to check if cache exists
def check_cache(key):
    return int(redis_client.exists(key) > 0)

# Function to store data in cache
def set_cache(key, value, time_to_live=None):
    if time_to_live is not None:
        redis_client.expire(key, time_to_live)
    return redis_client.set(key, value)

# Function to get data from cache
def get_cache(key):
    return redis_client.get(key).decode('utf-8')

# Route to handle GET requests for a specific key
@app.route('/data/<key>')
def data(key):
    if request.method == 'GET':
        if check_cache(key):
            result = get_cache(key)
            return jsonify({'result': result})
        else:
            # If cache doesn't exist, we can create it or fetch from database
            value = 'This is some default value.'
            set_cache(key, value)
            return jsonify({'result': value})

# Route to handle PUT requests for a specific key
@app.route('/data/<key>', methods=['PUT'])
def update_data(key):
    if request.method == 'PUT':
        if check_cache(key):
            # If cache already exists, we can update it or delete it
            value = 'This is an updated value.'
            set_cache(key, value)
        else:
            value = 'This is some default value.'
            set_cache(key, value)

