import os
import psutil
from tempfile import TemporaryDirectory, gettempdir

class CacheMonitor:
    def __init__(self):
        self.cache_dir = '/tmp/cache'
        self._get_total_cache_size()

    def _get_temp_dir(self):
        with TemporaryDirectory() as temp_dir:
            return temp_dir

    def get_total_cache_size(self):
        if not hasattr(self, 'temp_dir'):
            self.temp_dir = self._get_temp_dir()
            total_size = 0
            for root, dirs, files in os.walk(self.temp_dir):
                for file in files:
                    file_path = os.path.join(root, file)
                    try:
                        size = os.path.getsize(file_path)
                        total_size += size
                    except OSError:
                        pass
        return self.temp_dir

    def get_used_cache_percentage(self):
        if not hasattr(self, 'temp_dir'):
            raise ValueError("get_total_cache_size must be called after __init__")
        total_size = sum(os.path.getsize(os.path.join(self.temp_dir, file)) for file in os.listdir(self.temp_dir))
        used_size = psutil.disk_usage('/').free
        return (used_size / total_size) * 100

    def monitor_cache(self):
        while True:
            try:
                total_size = sum(os.path.getsize(os.path.join(self.cache_dir, file)) for file in os.listdir(self.cache_dir))
                used_percentage = self.get_used_cache_percentage()
            except FileNotFoundError:
                # Handle the case where cache_dir is deleted
                total_size = 0
                used_percentage = 0.0

            print(f"Total cache size: {total_size} bytes")
            print(f"Used percentage: {used_percentage}%")

            # Wait for 1 minute before checking again
            import time
            time.sleep(60)

if __name__ == "__main__":
    monitor = CacheMonitor()
    monitor.monitor_cache()

import time
from collections import OrderedDict

class Cache:
    def __init__(self, maxsize):
        self.maxsize = maxsize
        self.cache = OrderedDict()

    def get(self, key):
        if key in self.cache:
            value, timestamp = self.cache[key]
            if time.time() - timestamp < 60:  # check if the cache is stale
                return value
            else:
                del self.cache[key]
        return None

    def set(self, key, value):
        if key in self.cache:
            del self.cache[key]
        elif len(self.cache) >= self.maxsize:
            self.cache.popitem(last=False)
        self.cache[key] = (value, time.time())

# Usage
cache = Cache(5)

def example_function():
    # Simulate some work
    print("Doing some work...")
    return "Result from function"

def main():
    cache.set("key", example_function())
    result = cache.get("key")
    if result:
        print(result)
    else:
        print("Cache miss")

if __name__ == "__main__":
    main()

import psutil
import logging
import time

# Set up logging configuration
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class ServerPerformanceMonitor:
    def __init__(self):
        self.cpu_usage = None
        self.memory_usage = None
        self.disk_usage = None

    def get_cpu_usage(self):
        try:
            cpu_percent = psutil.cpu_percent()
            logging.info(f'CPU usage: {cpu_percent}%')
            return cpu_percent
        except Exception as e:
            logging.error(f'Error getting CPU usage: {str(e)}')
            return None

    def get_memory_usage(self):
        try:
            memory_percent = psutil.virtual_memory().percent
            logging.info(f'Memory usage: {memory_percent}%')
            return memory_percent
        except Exception as e:
            logging.error(f'Error getting memory usage: {str(e)}')
            return None

    def get_disk_usage(self, path='/'):
        try:
            disk_percent = psutil.disk_usage(path).percent
            logging.info(f'Disk usage: {disk_percent}%')
            return disk_percent
        except Exception as e:
            logging.error(f'Error getting disk usage: {str(e)}')
            return None

    def monitor(self):
        while True:
            cpu_percent = self.get_cpu_usage()
            memory_percent = self.get_memory_usage()
            disk_percent = self.get_disk_usage()

            if cpu_percent is not None and memory_percent is not None and disk_percent is not None:
                logging.info(f'CPU usage: {cpu_percent}%')
                logging.info(f'Memory usage: {memory_percent}%')
                logging.info(f'Disk usage: {disk_percent}%')

            time.sleep(60)  # Update every minute

if __name__ == '__main__':
    monitor = ServerPerformanceMonitor()
    monitor.monitor()

