import time
from collections import defaultdict

class EmailRateLimiter:
    def __init__(self, max_requests, time_window):
        self.max_requests = max_requests
        self.time_window = time_window
        self.request_history = defaultdict(int)
        self.last_request_time = {}

    def is_allowed(self, email):
        current_time = time.time()
        if email in self.last_request_time:
            last_request_time = self.last_request_time[email]
            time_since_last_request = current_time - last_request_time

            if time_since_last_request < self.time_window:
                return False
        return True

    def process_email(self, email):
        if not self.is_allowed(email):
            print(f"Rate limit exceeded for {email}.")
            return

        self.request_history[email] += 1
        self.last_request_time[email] = time.time()

        # Reset the counter after max_requests
        if self.request_history[email] > self.max_requests:
            self.request_history[email] = 0
            self.last_request_time[email] = current_time


# Example usage
rate_limiter = EmailRateLimiter(max_requests=10, time_window=60)  # 10 requests per minute

while True:
    email = input("Enter an email address: ")
    rate_limiter.process_email(email)
    time.sleep(1)

import smtplib
from email import policy
from email.parser import BytesParser
from email.header import decode_chars
from email.errors import MessageError, BadHeaderDataError

class EmailBounceHandler:
    def __init__(self):
        self.bounced_emails = []

    def handle_bounce(self, email_content):
        # Parse the email content using BytesParser from email library
        message = BytesParser(policy=policy.default).parsebytes(email_content)

        # Extract the 'Return-Path' and 'X-Mailer' headers to check for bounce indicators
        return_path = None
        x_mailer = None

        for part in message.walk():
            if part.get_content_type() == 'text/plain':
                try:
                    plain_text_part = part.get_payload(decode=True)
                except Exception as e:
                    print(f"Error decoding email: {e}")
                    continue

                return_path = plain_text_part.strip()
                x_mailer = None  # Not present in the email content
            elif part.get_content_type() == 'message/rfc822':
                rfc822_message = BytesParser(policy=policy.default).parsebytes(part.get_payload(decode=True))
                for child_part in rfc822_message.walk():
                    if child_part.get('Content-Type') == 'text/plain':
                        try:
                            plain_text_part = child_part.get_payload(decode=True)
                        except Exception as e:
                            print(f"Error decoding email: {e}")
                            continue

                        return_path = plain_text_part.strip()
                        x_mailer = None  # Not present in the nested email content
                    elif child_part.get('Content-Type') == 'message/rfc822':
                        rfc822_message = BytesParser(policy=policy.default).parsebytes(child_part.get_payload(decode=True))
                        for grandchild_part in rfc822_message.walk():
                            if grandchild_part.get('Content-Type') == 'text/plain':
                                try:
                                    plain_text_part = grandchild_part.get_payload(decode=True)
                                except Exception as e:
                                    print(f"Error decoding email: {e}")
                                    continue

                                return_path = plain_text_part.strip()
                                x_mailer = None  # Not present in the nested nested email content
                        break

        if not return_path or not x_mailer:
            self.bounced_emails.append({
                "email_content": email_content,
                "bounce_indicator": "Missing bounce indicator"
            })
        elif 'Return-Path' not in message:
            self.bounced_emails.append({
                "email_content": email_content,
                "bounce_indicator": "No Return-Path header found"
            })
        else:
            self.bounced_emails.append({
                "email_content": email_content,
                "bounce_indicator": f"Return-Path: {return_path}"
            })

    def print_bounced_emails(self):
        for bounce in self.bounced_emails:
            print(bounce)

# Usage
if __name__ == "__main__":
    handler = EmailBounceHandler()

    # Simulate an email bounce
    email_content = b"""Return-Path: bounce@example.com\nX-Mailer: Python script\nFrom: test@example.com
To: test@example.com
Subject: Test Email\n\nThis is a test email."""

    handler.handle_bounce(email_content)
    handler.print_bounced_emails()

import sqlite3
from sqlite3 import Error
class DataStore:
    def __init__(self, db_name):
        self.conn = None
        try:
            self.conn = sqlite3.connect(db_name)
            print(sqlite3.version)
        except Error as e:
            print(e)

    def create_table(self):
        cur = self.conn.cursor()
        cur.execute('''
            CREATE TABLE IF NOT EXISTS data
            (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT)
        ''')
        self.conn.commit()

    def add_data(self, name):
        try:
            cur = self.conn.cursor()
            cur.execute("INSERT INTO data(name) VALUES (?)", (name,))
            self.conn.commit()
            return cur.lastrowid
        except Error as e:
            print(e)

    def read_all(self):
        cur = self.conn.cursor()
        cur.execute('SELECT * FROM data')
        rows = cur.fetchall()
        return rows

    def search_data_with_pagination(self, page_number, items_per_page):
        cur = self.conn.cursor()
        start_index = (page_number - 1) * items_per_page
        end_index = start_index + items_per_page
        cur.execute('SELECT name FROM data LIMIT ? OFFSET ?', (end_index, start_index))
        rows = cur.fetchall()
        return rows

    def close_connection(self):
        if self.conn:
            self.conn.close()


def main():
    db_name = 'search.db'
    store = DataStore(db_name)
    store.create_table()

    while True:
        print("1. Add data")
        print("2. Search with pagination")
        print("3. Exit")
        choice = input("Choose an option: ")
        if choice == "1":
            name = input("Enter the name: ")
            id = store.add_data(name)
            print(f"Data added successfully with id {id}")
        elif choice == "2":
            page_number = int(input("Enter the page number: "))
            items_per_page = int(input("Enter the number of items per page: "))
            rows = store.search_data_with_pagination(page_number, items_per_page)
            for row in rows:
                print(row[0])
        elif choice == "3":
            break
        else:
            print("Invalid option")

    store.close_connection()


if __name__ == "__main__":
    main()

import functools
from collections import OrderedDict, LRUCache
import time

class Cache:
    def __init__(self, maxsize=100):
        self.maxsize = maxsize
        self.cache = OrderedDict()

    def get(self, key):
        if key in self.cache:
            result = self.cache.pop(key)
            self.cache[key] = result  # update the cache entry
            return result
        else:
            raise KeyError(f"Key {key} not found in cache")

class LRUCache(Cache):
    def __init__(self, maxsize=100):
        super().__init__(maxsize)
        self.cache = LRUCache(maxsize)

def cached(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        key = str(args) + str(kwargs)
        start_time = time.time()
        result = func(*args, **kwargs)
        end_time = time.time()
        elapsed_time = end_time - start_time
        print(f"Function {func.__name__} executed in {elapsed_time:.2f}s")
        if key not in cache.cache:
            cache.cache[key] = (result, elapsed_time)
        else:
            _, prev_elapsed_time = cache.cache.pop(key)
            result, _ = cache.cache[key]
            if result != func(*args, **kwargs):
                print(f"Cache hit, but result is outdated: {func.__name__} returned {result}, cached {result}")
                return result
            elif elapsed_time - prev_elapsed_time < 5:
                print(f"Cache hit within 5 seconds: {func.__name__} returned {result}, cached {result}")
                return result
        cache.cache[key] = (result, elapsed_time)
        return result

cache = Cache()
LRUCache = LRUCache()

def example_function(x):
    # simulate an expensive operation
    time.sleep(2)
    return x * 2

@cached
def cached_example_function(x):
    return example_function(x)

print(cached_example_function(10))
print(cached_example_function(10))  # cache hit

