import json
import yaml
import re

def validate_config(config_file, config_format):
    """
    Validates the configuration format of a file.

    Args:
        config_file (str): The path to the configuration file.
        config_format (str): The expected format of the configuration file ('json' or 'yaml').

    Returns:
        bool: True if the configuration file is valid, False otherwise.
    """
    try:
        with open(config_file, 'r') as f:
            # Check if the file exists and can be read
            content = f.read()
    except FileNotFoundError:
        print(f"Error: File '{config_file}' not found.")
        return False

    # Validate JSON format
    if config_format == 'json':
        try:
            json.loads(content)
        except ValueError:
            print(f"Error: Invalid JSON format in file '{config_file}'.")
            return False

    # Validate YAML format
    elif config_format == 'yaml':
        try:
            yaml.safe_load(content)
        except yaml.YAMLError as e:
            print(f"Error: Invalid YAML format in file '{config_file}': {e}")
            return False

    # Validate regex pattern for a generic configuration format
    else:
        # Define a basic regex pattern for a valid configuration
        pattern = r"^#.*\n.*^.*$"
        if not re.match(pattern, content):
            print(f"Error: Invalid configuration format in file '{config_file}'.")
            return False

    return True

# Example usage
if __name__ == "__main__":
    config_files = ['config.json', 'config.yaml', 'invalid_config.txt']
    for file in config_files:
        if validate_config(file, 'json'):
            print(f"Configuration file '{file}' is valid.")
        else:
            print(f"Configuration file '{file}' is invalid.")

import os
import json

# Create a dictionary to store the configuration
config = {}

def load_config(file_path):
    """
    Load the configuration from a file.

    Args:
        file_path (str): The path to the configuration file.
    """
    try:
        with open(file_path, 'r') as f:
            config.update(json.load(f))
    except FileNotFoundError:
        print("File not found.")
    except json.JSONDecodeError:
        print("Invalid JSON format.")

def save_config(file_path):
    """
    Save the configuration to a file.

    Args:
        file_path (str): The path to the configuration file.
    """
    with open(file_path, 'w') as f:
        json.dump(config, f, indent=4)

def reload_config():
    """
    Reload the configuration from the files in the current directory.
    """
    for filename in os.listdir("."):
        if filename.endswith(".json"):
            load_config(filename)

def main():
    while True:
        print("\n1. Save Configuration")
        print("2. Reload Configuration")
        print("3. Exit")
        choice = input("Choose an option: ")

        if choice == "1":
            file_path = input("Enter the file path to save: ")
            save_config(file_path)
        elif choice == "2":
            reload_config()
            config.update({"version": 1})  # Update the version
        elif choice == "3":
            break
        else:
            print("Invalid option.")

if __name__ == "__main__":
    main()

import configparser
import os

class MalformedConfigHandler:
    def __init__(self, config_file):
        self.config_file = config_file
        self.config = configparser.ConfigParser()
        try:
            self.config.read(self.config_file)
        except Exception as e:
            print(f"Error parsing the configuration file: {e}")

    def check_malformed_config(self):
        if not os.path.exists(self.config_file):
            raise FileNotFoundError("The configuration file does not exist.")

        error_count = 0
        for section in self.config.sections():
            for key, value in self.config.items(section):
                if not isinstance(value, str) or not value.strip():
                    error_count += 1
                    print(f"Malformed value found in section '{section}': {key}")

        return error_count

# Example usage:
if __name__ == "__main__":
    config_file = "config.ini"
    handler = MalformedConfigHandler(config_file)
    malformed_count = handler.check_malformed_config()

    if malformed_count > 0:
        print(f"The configuration file contains {malformed_count} malformed values.")
    else:
        print("The configuration file appears to be well-formed.")

import requests
from bs4 import BeautifulSoup

def fetch_webpage(url, timeout=5):
    try:
        # Send GET request and get response with specified timeout
        response = requests.get(url, timeout=timeout)

        # Check if request was successful
        if response.status_code == 200:
            # Get content of response
            webpage_content = response.content

            # Create a BeautifulSoup object and specify the parser
            soup = BeautifulSoup(webpage_content, 'html.parser')

            return soup
        else:
            print(f"Failed to retrieve webpage. Status code: {response.status_code}")
    except requests.Timeout as e:
        print(f"Request timed out: {e}")
    except Exception as e:
        print(f"An error occurred: {str(e)}")

def main():
    url_to_fetch = input("Enter URL of webpage you want to fetch content: ")
    fetch_webpage(url_to_fetch)

if __name__ == "__main__":
    import sys
    if len(sys.argv) > 1:
        main()

