        for server in system.servers:
            print(f"{server.name}: Load - {server.load} units")

        action = input("Enter 'r' to request load, 's' to remove load, or 'q' to quit: ")
        if action == 'q':
            break
        elif action == 'r':
            amount = int(input("Enter the amount of load to request: "))
            for client in system.servers:
                client.request(amount)
        elif action == 's':
            server_name = input("Enter the name of the server to remove load from: ")
            for server in system.servers:
                if server.name == server_name:
                    server.remove_load(int(input("Enter the amount of load to remove: ")))
                    break
        else:
            print("Invalid action. Please try again.")

if __name__ == "__main__":
    main()

import socket
import logging

# Set up logging configuration
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class IPBanHandler:
    def __init__(self, banned_ips=None):
        if banned_ips is None:
            self.banned_ips = []
        else:
            self.banned_ips = set(banned_ips)

    def ban_ip(self, ip_address):
        """Bans an IP address from accessing the website"""
        logger.info(f"IP {ip_address} has been banned")
        self.banned_ips.add(ip_address)

    def unban_ip(self, ip_address):
        """Unbans an IP address from accessing the website"""
        logger.info(f"IP {ip_address} has been unbanned")
        self.banned_ips.discard(ip_address)

    def is_banned(self, ip_address):
        """Checks if an IP address is banned from accessing the website"""
        return ip_address in self.banned_ips

def get_ip_address():
    """Gets the client's IP address using socket.gethostbyname()"""
    try:
        return socket.gethostbyname(socket.gethostname())
    except Exception as e:
        logger.error(f"Failed to get IP address: {e}")
        return None

class WebsiteBouncer:
    def __init__(self):
        self.ip_ban_handler = IPBanHandler()

    def check_access(self, ip_address):
        """Checks if an IP address is allowed access to the website"""
        if not self.ip_ban_handler.is_banned(ip_address):
            return True
        else:
            return False

# Example usage:
bouncer = WebsiteBouncer()
while True:
    ip_address = get_ip_address()
    if ip_address is None:
        logger.error("Failed to get IP address")
        continue
    if bouncer.check_access(ip_address):
        logger.info(f"Allowed access to {ip_address}")
    else:
        logger.info(f"Banned access from {ip_address} - banning IP...")
        bouncer.ip_ban_handler.ban_ip(ip_address)

import os
from datetime import datetime

class DependencyLogger:
    def __init__(self):
        self.dependency_log = {}

    def add_dependency(self, dependency_name, version):
        if dependency_name not in self.dependency_log:
            self.dependency_log[dependency_name] = []

        self.dependency_log[dependency_name].append((version, datetime.now()))

    def update_dependency(self, dependency_name, new_version):
        if dependency_name in self.dependency_log:
            for version, timestamp in self.dependency_log[dependency_name]:
                print(f"Previous version of {dependency_name}: {version} (timestamp: {timestamp})")

        self.add_dependency(dependency_name, new_version)

    def delete_dependency(self, dependency_name):
        if dependency_name in self.dependency_log:
            for version, timestamp in list(self.dependency_log[dependency_name]):
                print(f"Previous version of {dependency_name}: {version} (timestamp: {timestamp})")

        del self.dependency_log[dependency_name]

    def display_dependencies(self):
        for dependency_name, versions in self.dependency_log.items():
            print(f"Dependency {dependency_name}:")
            for i, version in enumerate(versions):
                print(f"{i+1}. Version {version} (timestamp: {(version[1]).strftime('%Y-%m-%d %H:%M:%S')})")


def main():
    logger = DependencyLogger()

    while True:
        print("Dependency Change Logger")
        print("1. Add dependency")
        print("2. Update dependency")
        print("3. Delete dependency")
        print("4. Display dependencies")
        print("5. Quit")

        choice = input("Choose an option: ")

        if choice == "1":
            dependency_name = input("Enter the name of the dependency: ")
            new_version = input("Enter the version of the dependency: ")
            logger.add_dependency(dependency_name, new_version)
        elif choice == "2":
            dependency_name = input("Enter the name of the dependency: ")
            new_version = input("Enter the updated version of the dependency: ")
            logger.update_dependency(dependency_name, new_version)
        elif choice == "3":
            dependency_name = input("Enter the name of the dependency to delete: ")
            logger.delete_dependency(dependency_name)
        elif choice == "4":
            logger.display_dependencies()
        elif choice == "5":
            break
        else:
            print("Invalid option. Please choose a valid option.")


if __name__ == "__main__":
    main()

import subprocess
from packaging import version
import os

def check_dependencies(pipfile):
    with open(pipfile, 'r') as f:
        for line in f:
            if line.startswith('extras_require'):
                break

    extra_requires = {}
    for line in f:
        if line.strip().startswith('-r'):
            dependency = line.split("'")[1].strip()
            version_info = line.split('=')[1]
            try:
                version_obj = version.Version(version_info)

                # Get the full dependency path from pip show
                full_dependency_path = subprocess.run(['pip', 'show', '--format=freeze', dependency], stdout=subprocess.PIPE, text=True).split('\nPackage information: ')[0].strip()

                # Check if the full path is a file path
                if not os.path.exists(full_dependency_path):
                    print(f"Warning: Incomplete executable path for {dependency}. Using the first match from pip show.")
                    full_dependency_path = subprocess.run(['pip', 'show', '--format=freeze', dependency], stdout=subprocess.PIPE, text=True).split('\nPackage information: ')[0].strip()

                extra_requires[dependency] = str(version_obj)
            except (ValueError, IndexError) as e:
                pass
        elif line.strip().startswith('extras'):
            break

    return extra_requires


def check_breaking_changes(extra_requires):
    latest_versions = {}
    for dependency, version in extra_requires.items():
        try:
            response = subprocess.run(['pip', 'show', dependency], stdout=subprocess.PIPE, text=True)
            if response.returncode == 0:
                package_info = response.stdout.split('\nPackage information: ')[1].strip()

                # Check for untrusted input
                if not package_info.replace('"', '').replace("'", '').isalnum():
                    print(f"Warning: Untrusted input detected for {dependency}. Skipping version check.")
                    continue

                full_dependency_path = subprocess.run(['pip', 'show', dependency], stdout=subprocess.PIPE, text=True).split('\nPackage information: ')[0].strip()

                # Check if the full path is a file path
                if not os.path.exists(full_dependency_path):
                    print(f"Warning: Incomplete executable path for {dependency}. Skipping version check.")
                    continue

                latest_versions[dependency] = package_info
        except subprocess.CalledProcessError:
            pass

    breaking_changes = {}
    for dependency, version in extra_requires.items():
        if version != latest_versions.get(dependency):
            print(f"Breaking change found for {dependency}:")
            print(f"Original version: {version}")
            print(f"Latest version: {latest_versions[dependency]}")

            # Analyze the breaking changes
            # For example, let's say we have a dependency with different versions
            # of its sub-dependencies:
            #   - Old version: '==1.0'
            #   - New version: '>=2.0,<3.0'

            # If the new version is incompatible with the old version,
            # we can consider it as breaking change.
            if latest_versions[dependency] != '*' and \
                (latest_versions[dependency].startswith('==') or latest_versions[dependency].startswith('>=')) and \
                not latest_versions[dependency].endswith('<'):
                print("Breaking change detected.")

            breaking_changes[dependency] = True
    return breaking_changes


def main():
    pipfile = 'poetry.json'  # Replace with your poetry.json file
    extra_requires = check_dependencies(pipfile)
    breaking_changes = check_breaking_changes(extra_requires)

    if breaking_changes:
        print("Breaking changes found:")
        for dependency, is_breaking_change in breaking_changes.items():
            if is_breaking_change:
                print(f"- {dependency} (breaking change detected)")
            else:
                print(f"- {dependency} (no breaking change detected)")


if __name__ == "__main__":
    main()

import setuptools

def get_insecure_libraries():
    """Returns a list of insecure libraries that can be restricted."""
    # Add your insecure libraries here. For this example, we'll use a few popular ones.
    return [
        "requests",  # https://github.com/psf/requests/blob/main/LICENSE
        "boto3",     # https://github.com/boto/boto3/blob/master/LICENSE
        "beautifulsoup4",  # https://github.com/scrapy-developers/beautifulsoup4/blob/master/LICENSE
    ]

def get_license_text(license_file):
    """Returns the license text of a library from a file."""
    try:
        with open(license_file, 'r') as f:
            return f.read()
    except FileNotFoundError:
        print("License file not found.")
        return None

def check_licenses(library, license_file=None):
    """Checks if a library has an insecure license."""
    license_text = get_license_text(license_file)
    if license_text is None:
        # If no license text is available, assume it's secure
        return False

    # Define patterns for insecure licenses. This can be extended.
    insecure_patterns = [
        r'(?:Apache|GPL)\s*\(v2\)|\bMIT\b',
    ]

    if any(pattern in license_text.lower() for pattern in insecure_patterns):
        print(f"Library {library} has an insecure license.")
        return True
    else:
        print(f"Library {library} has a secure license.")
        return False

def restrict_libraries():
    """Restricts libraries with insecure licenses."""
    insecure_libs = get_insecure_libraries()

    for lib in insecure_libs:
        check_licenses(lib)

# Restrict libraries
restrict_libraries()

import re

class Lexer:
    def __init__(self, text):
        self.text = text
        self.pos = 0

    def error(self):
        raise Exception('Invalid character')

    def advance(self):
        self.pos += 1

    def skip_whitespace(self):
        while self.pos < len(self.text) and self.text[self.pos].isspace():
            self.advance()

    def integer(self):
        result = ''
        while self.pos < len(self.text) and self.text[self.pos].isdigit():
            result += self.text[self.pos]
            self.advance()
        return int(result)

    def lex(self):
        results = []
        while self.pos < len(self.text):
            if self.text[self.pos].isspace():
                self.skip_whitespace()
            elif re.match('^[a-zA-Z_][a-zA-Z0-9_]*$', self.text[self.pos]):
                word, self.advance()
                results.append(word)
            else:
                self.error()
        return results

class Interpreter:
    def __init__(self, lexer):
        self.lexer = lexer
        self.current_token = self.lexer.lex()

    def error(self):
        raise Exception('Invalid syntax')

    def advance(self):
        token = self.lexer.current_token
        self.lexer.current_token = self.lexer.lexer.current_token[self.lexer.pos + 1:]
        return token

    def eat(self, token_type):
        if self.current_token == token_type:
            self.advance()
            return True
        else:
            self.error()
            return False

    def factor(self):
        token = self advance()
        if token == 'num':
            return self.lexer.integer()
        elif token == '(':
            self.lexer.advance()
            result = self.expr()
            self.lexer.advance()
            return result
        elif token == '+':
            self.lexer.advance()
            return self.factor() + self.factor()
        else:
            self.error()

    def term(self):
        factor = self.factor()
        while self.current_token == '*':
            self.lexer.advance()
            factor *= self.factor()
        return factor

    def expr(self):
        left = self.term()
        while self.current_token == '+':
            self.lexer.advance()
            right = self.term()
            left += right
        return left

# Test the program
if __name__ == "__main__":
    text = '5 * (3 + 4) - 2'
    interpreter = Interpreter(Lexer(text))
    result = interpreter.expr()

    print(f'{text} evaluates to {result}')

import urllib.parse

def parse_url_encoded_data(url):
    try:
        # Unpack the query string
        parsed_url = urllib.parse.urlparse(url)
        query_string = urllib.parse.unquote(parsed_url.query)

        # Parse the query string into a dictionary
        query_params = urllib.parse.parse_qs(query_string)

        return query_params

    except Exception as e:
        print(f"An error occurred: {e}")
        return None


