import socket
import threading

class ClientHandler:
    def __init__(self):
        self.clients = []
        self.lock = threading.Lock()

    def add_client(self, client_socket):
        with self.lock:
            self.clients.append(client_socket)

    def remove_client(self, client_socket):
        with self.lock:
            if client_socket in self.clients:
                self.clients.remove(client_socket)

    def broadcast_message(self, message):
        for client_socket in self.clients:
            try:
                client_socket.send(message.encode())
            except Exception as e:
                print(f"Error sending message to {client_socket.getpeername()}: {e}")

    def handle_client_disconnection(self, client_socket):
        self.remove_client(client_socket)
        print(f"Client disconnected: {client_socket.getpeername()}")

def main():
    handler = ClientHandler()
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)

    # Bind the server to a specific address and port
    server_socket.bind(("localhost", 12345))
    server_socket.listen(5)  # Allow up to 5 queued connections

    print("Server listening on port 12345...")

    while True:
        client_socket, client_address = server_socket.accept()
        print(f"New connection from {client_address}")

        # Create a new thread for the client handler
        client_handler_thread = threading.Thread(target=handler.add_client, args=(client_socket,))
        client_handler_thread.start()

if __name__ == "__main__":
    main()

import socket
import threading

class Server:
    def __init__(self, host='127.0.0.1', port=55555):
        self.host = host
        self.port = port
        self.server_socket = None
        self.clients = []

    def start(self):
        self.server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.server_socket.bind((self.host, self.port))
        self.server_socket.listen(5)
        print(f"Server listening on {self.host}:{self.port}")

        while True:
            client_socket, address = self.server_socket.accept()
            print(f"Connection established with {address}")
            self.clients.append(client_socket)

            thread = threading.Thread(target=self.handle_client, args=(client_socket,))
            thread.start()

    def handle_client(self, client_socket):
        while True:
            message = client_socket.recv(1024)
            if not message:
                break

            print(f"Received message: {message.decode('utf-8')}")
            self.broadcast(message)

    def broadcast(self, message):
        for client in self.clients:
            try:
                client.sendall(message)
            except Exception as e:
                self.remove_client(client)

    def remove_client(self, client_socket):
        if client_socket in self.clients:
            self.clients.remove(client_socket)
            print(f"Removed {client_socket.getpeername()}")
            client_socket.close()


if __name__ == "__main__":
    server = Server()
    server.start()

import asyncio
import websockets

class WebSocketParser:
    def __init__(self):
        self.messages = []

    async def handle_connection(self, websocket):
        while True:
            try:
                message = await websocket.recv()
                self.messages.append(message)
                print(f"Received message: {message}")
            except websockets.ConnectionClosed:
                break

    async def start(self):
        async with websockets.serve(self.handle_connection, "localhost", 8765):
            await asyncio.Future()  # run forever


