class BankAccount:
    def __init__(self, balance=0):
        self.balance = balance

    def deposit(self, amount):
        """Deposits a specified amount of money into the account."""
        if amount < 0:
            print("Invalid deposit amount. Please enter a positive value.")
        else:
            self.balance += amount
            print(f"Deposit successful. New balance: {self.balance}")

    def withdraw(self, amount):
        """Withdraws a specified amount of money from the account if sufficient funds are available."""
        if amount < 0:
            print("Invalid withdrawal amount. Please enter a positive value.")
        elif self.balance < amount:
            print("Insufficient funds for withdrawal. Please deposit more money or cancel transaction.")
        else:
