import re
from datetime import datetime, timedelta

class CreditCardValidator:
    def __init__(self, cvv, expiration_date):
        self.cvv = cvv
        self.expiration_date = expiration_date

    def validate_cvv(self):
        # Regular expression to match CVV pattern (last 3 digits)
        pattern = re.compile(r'^\d{3}$')
        if not pattern.match(self.cvv):
            return False
        else:
            return True

    def validate_expiration_date(self):
        try:
            expiration_date = datetime.strptime(self.expiration_date, '%Y-%m')

            # Check if expiration date is in the future
            current_date = datetime.now()
            difference = (expiration_date - current_date).days

            if difference <= 0:
                return False
            else:
                return True
        except ValueError:
            return False


def main():
    cvv = input("Enter CVV: ")
    expiration_date = input("Enter Expiration Date (YYYY-MM): ")

    validator = CreditCardValidator(cvv, expiration_date)

    if validator.validate_cvv() and validator.validate_expiration_date():
        print("CVV is valid and Expiration date is in the future.")
    else:
        print("Invalid CVV or Expiration date.")


