    main()

import socket

class IoTDevice:
    def __init__(self, host, port):
        self.host = host
        self.port = port
        self.client_socket = None

    def connect(self):
        try:
            self.client_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            self.client_socket.connect((self.host, self.port))
            print("Connected to IoT device")
        except Exception as e:
            print(f"Failed to connect: {e}")

    def receive_data(self):
        if not self.client_socket:
            print("Not connected. Please connect first.")
            return

        try:
            data = self.client_socket.recv(1024)
            if not data:
                print("No data received")
                return
            print(f"Received data: {data.decode()}")
        except Exception as e:
            print(f"Failed to receive data: {e}")

    def disconnect(self):
        if self.client_socket:
            self.client_socket.close()
            print("Disconnected from IoT device")


def main():
    # Replace with your IoT device's IP address and port number
    host = "192.168.1.100"
    port = 8080

    # Create an instance of the IoTDevice class
    iot_device = IoTDevice(host, port)

    while True:
        print("\nOptions:")
        print("1. Connect")
        print("2. Receive data")
        print("3. Disconnect")

        choice = input("Enter your choice: ")

        if choice == "1":
            iot_device.connect()
        elif choice == "2":
            iot_device.receive_data()
        elif choice == "3":
            iot_device.disconnect()
            break
        else:
            print("Invalid choice")


if __name__ == "__main__":
    main()

import os
import hashlib
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC
from cryptography.fernet import Fernet

# Initialize default backend for SHA256 hash
default_backend = None  

# Use a secure hash algorithm (e.g., SHA-512)
algorithm = hashes.SHA512()

def firmware_hash(data, password):
    # Derive the salt from the password to prevent rainbow table attacks
    kdf = PBKDF2HMAC(
        algorithm=hashes.SHA512(),
        length=32,
        salt=None,
        iterations=100000,
        backend=default_backend
    )

    # Use a secure random number generator to generate a salt for each device
    import secrets
    salt = secrets.token_bytes(16)
    kdf.derive(salt)

    return hashlib.pbkdf2_hmac(algorithm, data, kdf, 100000).hex()

class Device:
    def __init__(self, name):
        self.name = name
        self.firmware_path = None

    def download_firmware(self, url, password=None):
        # Assuming we have a function to download the file from the URL
        return "Firmware downloaded successfully"

    def verify_firmware(self, firmware_path, expected_hash):
        with open(firmware_path, 'rb') as file:
            if os.path.exists(firmware_path) and self.firmware_hash(file.read()) == expected_hash:
                self.firmware_path = firmware_path

class FirmwareUpdater:
    def __init__(self):
        self.devices = {}

    def add_device(self, device_name, password=None):
        self.devices[device_name] = Device(device_name)

    def update_firmware(self, device_name, url, password=None):
        if device_name in self.devices:
            self.devices[device_name].download_firmware(url, password)
            print("Firmware updated successfully")
        else:
            print("Device not found")

    def verify_firmware_status(self, device_name):
        if device_name in self.devices:
            firmware_path = os.path.join("/path/to/firmware/", self.devices[device_name].name + ".bin")
            expected_hash = firmware_hash(b'', self.devices[device_name].name)
            self.devices[device_name].verify_firmware(firmware_path, expected_hash)
            if self.devices[device_name].firmware_path is not None:
                print("Firmware verification successful")
            else:
                print("Firmware path unknown")
        else:
            print("Device not found")

    def install_firmware(self, device_name):
        if device_name in self.devices:
            print("Installing firmware...")
            # Assuming we have a function to install the firmware
            firmware_path = os.path.join("/path/to/firmware/", self.devices[device_name].name + ".bin")
            expected_hash = firmware_hash(b'', self.devices[device_name].name)
            self.devices[device_name].verify_firmware(firmware_path, expected_hash)
            print("Firmware installed successfully")
        else:
            print("Device not found")

