class CloudService:
    def __init__(self, name):
        self.name = name
        self.is_available = True

    def check_availability(self):
        if self.is_available:
            return f"{self.name} is available."
        else:
            return f"{self.name} is not available."

    def handle_outage(self):
        self.is_available = False
        print(f"Cloud service {self.name} has gone down.")

    def recover_from_outage(self):
        if not self.is_available:
            self.is_available = True
            print(f"Cloud service {self.name} has come back online.")


class CloudServiceOutageHandler:
    def __init__(self, cloud_services):
        self.cloud_services = cloud_services

    def check_all_availability(self):
        for service in self.cloud_services:
            print(service.check_availability())

    def handle_service_outage(self, service_name):
        for service in self.cloud_services:
            if service.name == service_name:
                service.handle_outage()
                return
        print("Cloud service not found.")

    def recover_from_service_outage(self, service_name):
        for service in self.cloud_services:
            if service.name == service_name:
                service.recover_from_outage()
                return
        print("Cloud service not found.")


