    print("Executing task 1")

def example_task_2():
    print("Executing task 2")
    # Simulate some long-running operation
    import time
    time.sleep(5)

def main() -> None:
    scheduler = TaskScheduler()

    scheduler.add_task(example_task_1)
    scheduler.add_task(example_task_2)

    # Execute tasks in parallel
    threading.Thread(target=scheduler.execute_tasks).start()

    # Simulate some other task execution
    threading.Thread(target=example_task_3).start()

def example_task_3() -> None:
    print("Executing task 3")

