    main()

class TaskManager:
    def __init__(self):
        self.tasks = {}

    def view_tasks(self):
        """Display all tasks."""
        print("Task List:")
        for task in self.tasks.keys():
            status = "Completed" if self.tasks[task]["completed"] else "Pending"
            print(f"{task}: {status}")

    def add_task(self, task_name):
        """Add a new task to the list."""
        task_id = len(self.tasks) + 1
        completed_status = False

        while True:
            confirmation = input(f"Are you sure you want to add '{task_name}' as a task? (yes/no): ")
            if confirmation.lower() == "yes":
                self.tasks[task_id] = {"task": task_name, "completed": completed_status}
                print(f"Task added successfully: {task_name}")
                break
            elif confirmation.lower() == "no":
                print("Adding cancelled.")
                return

    def update_task(self, task_id):
        """Update the status of a task."""
        if task_id not in self.tasks:
            print("No such task found.")
            return

        while True:
            confirmation = input(f"Are you sure you want to update the status of '{self.tasks[task_id]['task']}'? (yes/no): ")
            if confirmation.lower() == "yes":
                completed_status = input("Enter 'completed' or 'pending': ")
                self.tasks[task_id]["completed"] = True if completed_status.lower() == "completed" else False
                print(f"Task status updated successfully: {self.tasks[task_id]['task']}")
                break
            elif confirmation.lower() == "no":
                print("Updating cancelled.")
                return

    def delete_task(self, task_id):
        """Delete a task."""
        if task_id not in self.tasks:
            print("No such task found.")
            return

        confirmation = input(f"Are you sure you want to delete '{self.tasks[task_id]['task']}'? (yes/no): ")
        if confirmation.lower() == "yes":
            del self.tasks[task_id]
            print("Task deleted successfully.")
        else:
            print("Deletion cancelled.")

def main():
    task_manager = TaskManager()

    while True:
        print("\nTask Management System")
        print("1. View Tasks")
        print("2. Add New Task")
        print("3. Update Task Status")
