import datetime
from enum import Enum
from typing import Dict, List

class TaskStatus(Enum):
    IN_PROGRESS = 1
    COMPLETED = 2
    FAILED = 3

class Task:
    def __init__(self, name: str, duration_in_seconds: int):
        self.name = name
        self.duration_in_seconds = duration_in_seconds
        self.status = TaskStatus.IN_PROGRESS

    def start(self):
        self.start_time = datetime.datetime.now()

    def stop(self):
        if not self.status == TaskStatus.COMPLETED:
            raise Exception(f"Cannot stop {self.name} as it's not completed yet")
        elapsed_time = (datetime.datetime.now() - self.start_time).total_seconds()
        print(f"{self.name} completed in {elapsed_time:.2f} seconds")

    def update_status(self, status: TaskStatus):
        if self.status != TaskStatus.IN_PROGRESS:
            raise Exception("Cannot change the status of a task once it's started")
        self.status = status

def main():
    # Create tasks
    task1 = Task("Task 1", 10)
    task2 = Task("Task 2", 20)

    # Start and stop tasks
    task1.start()
    task1.update_status(TaskStatus.COMPLETED)
    task2.start()

if __name__ == "__main__":
    main()

import tkinter as tk
from datetime import date, timedelta
import sqlite3

class Task:
    def __init__(self, id, description):
        self.id = id
        self.description = description
        self.completed_date = None

class TaskManager:
    def __init__(self, db_name='tasks.db'):
        self.conn = sqlite3.connect(db_name)
        self.cursor = self.conn.cursor()
        self.cursor.execute('''
            CREATE TABLE IF NOT EXISTS tasks (
                id INTEGER PRIMARY KEY,
                description TEXT NOT NULL,
                completed_date TEXT
            )
        ''')

    def add_task(self, description):
        task_id = (self.cursor.lastrowid, description)
        self.cursor.execute('INSERT INTO tasks VALUES (?, ?)', task_id)
        self.conn.commit()
        return Task(task_id[0], description)

    def view_tasks(self):
        for row in self.cursor.execute('SELECT * FROM tasks'):
            yield Task(row[0], row[1])

    def complete_task(self, id):
        self.cursor.execute('UPDATE tasks SET completed_date=? WHERE id=?', (date.today().strftime('%Y-%m-%d'), id))
        self.conn.commit()

def main():
    task_manager = TaskManager()

    # Create GUI
    root = tk.Tk()
    root.title("Task Completion Notification System")

    def add_task():
        description = entry.get('0.0', 'end-1c')
        task = task_manager.add_task(description)
        print(f"Task added: {task.description}")

    def view_tasks():
        tasks = list(task_manager.view_tasks())
        for i, task in enumerate(tasks):
            label = tk.Label(root, text=f"{i+1}. {task.description} ({'Completed' if task.completed_date else 'Pending'})")
            label.pack()

    def complete_task():
        try:
            id = int(entry.get('0.0', 'end-1c'))
            task_manager.complete_task(id)
            print(f"Task completed: {id}")
        except ValueError:
            print("Invalid task ID")

    # GUI elements
    tk.Label(root, text="Enter task description:").pack()
    entry = tk.Text(root, height=10)
    tk.Button(root, text="Add Task", command=add_task).pack()
    tk.Button(root, text="View Tasks", command=view_tasks).pack()
    tk.Button(root, text="Complete Task", command=complete_task).pack()

    root.mainloop()

if __name__ == "__main__":
    main()

import uuid
from typing import List, Dict

class ValidationError(Exception):
    """Custom exception for validation errors."""
    pass

class ResolverError(Exception):
    """Base class for resolver errors."""
    pass

class Resolver:
    def __init__(self, name: str):
        self.name = name
        self.errors = []

    def validate(self, data: Dict) -> bool:
        try:
            # Your validation logic here
            if not isinstance(data['name'], str) or len(data['name']) < 3:
                raise ValidationError(f"Name must be a string with at least 3 characters")
            if not isinstance(data['age'], int) or data['age'] < 18:
                raise ValidationError("Age must be an integer greater than or equal to 18")
            return True
        except KeyError as e:
            raise ResolverError(f"Missing field: {e}")
        except ValueError as e:
            raise ResolverError(str(e))
        except Exception as e:
            self.errors.append(f"An unexpected error occurred: {str(e)}")
            raise ResolverError(str(e))

    def resolve(self, data: Dict) -> str:
        try:
            # Your resolvers here
            if not self.validate(data):
                raise ValidationError("Data is invalid")

            return f"{data['name']} has a valid age of {data['age']}"
        except Exception as e:
            self.errors.append(f"An unexpected error occurred: {str(e)}")
            raise ResolverError(str(e))

# Example usage
if __name__ == "__main__":
    resolver = Resolver('example_resolver')
    data = {
        'name': 'John',
        'age': 25,
    }

    try:
        print(resolver.resolve(data))
    except (ValidationError, ResolverError) as e:
        print(f"Validation error: {e}")

from flask import Flask, jsonify
