# Create a class to represent users
class User(Resource):
    def __init__(self):
        self.users = {}

    # POST /users
    def post(self):
        parser = reqparse.RequestParser()
        parser.add_argument('name', type=str, help='Name cannot be empty')
        parser.add_argument('email', type=str, help='Email cannot be empty')

        args = parser.parse_args()

        user_id = len(self.users) + 1
        self.users[user_id] = {'name': args['name'], 'email': args['email']}

        return jsonify({'user_id': user_id}), 201

    # GET /users
    def get(self):
        return list(self.users.values())

# Create a resource to handle user data
class Users(Resource):
    def __init__(self, users):
        self.users = users

    # POST /users
    def post(self):
        return User().post()

    # GET /users
    def get(self):
        return Users(self.users).get()

