import heapq

class EventQueue:
    def __init__(self):
        self.queue = []

    def add_event(self, timestamp, priority, message):
        """Add an event to the queue with its timestamp and priority."""
        # Create a tuple of (timestamp, priority, message) for sorting purposes
        event = (-priority, timestamp, message)
        heapq.heappush(self.queue, event)

    def remove_event(self):
        """Remove and return the highest-priority event from the queue."""
        if self.is_empty():
            raise ValueError("Queue is empty")
        return heapq.heappop(self.queue)[2]

    def peek_next_event(self):
        """Return the next event in the queue without removing it."""
        if self.is_empty():
            raise ValueError("Queue is empty")
        return self.queue[0][2]

    def size(self):
        """Return the number of events in the queue."""
        return len(self.queue)

    def is_empty(self):
        """Check if the queue is empty."""
        return not bool(self.queue)


def main():
    # Create an event queue
    queue = EventQueue()

    # Add some events to the queue with timestamps and priorities
    for i, message in enumerate(["Event 1", "Event 2", "Event 3"]):
        timestamp = 10 - i
        priority = 0.5 + (i / 100)
        queue.add_event(timestamp, priority, message)

    # Print the size of the queue
    print(f"Queue size: {queue.size()}")

    # Remove and print events from the queue
    for _ in range(3):
        event = queue.remove_event()
        print(f"Event: {event}")

    # Peek at the next event without removing it
    print("Next Event:", queue.peek_next_event())

    # Check if the queue is empty
    print("Is Queue Empty?", queue.is_empty())


if __name__ == "__main__":
    main()

import datetime
from collections import defaultdict

class Event:
    def __init__(self, name, date):
        self.name = name
        self.date = datetime.datetime.strptime(date, "%Y-%m-%d")

class EventManager:
    def __init__(self):
        self.events = defaultdict(list)

    def add_event(self, event):
        self.events[event.date].append(event)

    def handle_duplicate_events(self):
        for date, events in self.events.items():
            if len(events) > 1:
                print(f"Duplicate event found on {date}:")
                for i, event in enumerate(events):
                    print(f"{i+1}. {event.name}")

def main():
    manager = EventManager()

    # Adding events
    manager.add_event(Event("Event 1", "2024-01-01"))
    manager.add_event(Event("Event 2", "2024-01-02"))
    manager.add_event(Event("Event 3", "2024-01-01"))  # duplicate event
    manager.add_event(Event("Event 4", "2024-01-03"))

    # Handling duplicate events
    manager.handle_duplicate_events()

if __name__ == "__main__":
    main()

import logging
from datetime import datetime

class EventLogger:
    def __init__(self, event_log_file):
        self.event_log_file = event_log_file
        self.logger = logging.getLogger()
        self.logger.setLevel(logging.INFO)
        self.handler = logging.FileHandler(event_log_file)
        self.handler.setFormatter(logging.Formatter('%(asctime)s - %(message)s'))
        self.logger.addHandler(self.handler)

    def log_event(self, event_name, data):
        try:
            self.logger.info(f'{event_name}: {data}')
        except Exception as e:
            print(f"Error logging event: {e}")

