class Queue:
    def __init__(self):
        self.queue = []

    # Add message to the end of the queue
    def enqueue(self, message):
        self.queue.append(message)

    # Remove and return the front element from the queue
    def dequeue(self):
        if len(self.queue) < 1:
            return None
        return self.queue.pop(0)

    # Display all elements in the queue
    def display(self):
        print(self.queue)


# Example usage:
