print(q.enqueue(2))  # 2 added to queue, length is now 2
print(q.enqueue(3))  # 3 added to queue, length is now 3
print(q.dequeue())   # item 1 removed from queue, length is now 2
print(q.dequeue())   # item 2 removed from queue, length is now 1
print(q.enqueue(4))  # try adding another item. Queue overflow

import time
from collections import defaultdict

class MessageProcessorMonitor:
    def __init__(self):
        self.processed_messages = defaultdict(int)

    def process_message(self, message_id):
        if message_id in self.processed_messages:
            raise ValueError("Message ID already processed")
        self.processed_messages[message_id] += 1

    def get_processing_rate(self, interval=5):
        start_time = time.time()
        while True:
            current_time = time.time()
            if (current_time - start_time) > interval:
                rate = len(self.processed_messages)
                self.processed_messages.clear()
                return rate / interval
            time.sleep(0.1)

def main():
    # Initialize message processor monitor
    monitor = MessageProcessorMonitor()

    # Process some messages in a loop to test the monitor
    while True:
        try:
            message_id = str(i)
            print(f"Processing message {message_id}")
            monitor.process_message(message_id)
        except ValueError as e:
            print(e)
        i += 1

if __name__ == "__main__":
    main()

import time
import logging
from secrets import randbelow

# Set up logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

def process_message(message: str) -> Optional[bool]:
    # Simulate a message processing failure with 20% chance
    if randbelow(4) < 2:
        logger.error(f"Failed to process message: {message}")
        raise Exception("Message processing failed")

    logger.info(f"Processed message: {message}")
    return True

def retry_message_processing(max_retries: int = 3, backoff_factor: float = 1) -> None:
    for attempt in range(max_retries + 1):
        try:
            process_message("Test Message")
            break
        except Exception as e:
            if attempt < max_retries:
                logger.info(f"Message processing failed (Attempt {attempt + 1}/{max_retries}). Retrying in {backoff_factor} seconds...")
                time.sleep(backoff_factor)
                backoff_factor *= 2
            else:
                logger.error(f"All retries failed. Message processing exception: {e}")

if __name__ == "__main__":
    retry_message_processing()

import heapq
class PriorityQueue:
    def __init__(self):
        self.queue = []

    def enqueue(self, name, priority):
        # Create a tuple with the priority and name
        item = (priority, name)
        # Push the tuple onto the heap
        heapq.heappush(self.queue, item)

    def dequeue(self):
        if not self.is_empty():
            return heapq.heappop(self.queue)[1]
        else:
            return None

    def is_empty(self):
        return len(self.queue) == 0

# Create a new queue
q = PriorityQueue()

# Add items to the queue with different priority levels
