for item in q.queue:
    print(f"{item[0]} - {item[1]}")

# Dequeue an item from the queue
dequeued_item = q.dequeue()
if dequeued_item is not None:
    print(f"Dequeued: {dequeued_item}")
else:
    print("Queue is empty")

class ReportInputValidator:
    def __init__(self, report_type, date_range):
        self.report_type = report_type
        self.date_range = date_range

    def validate_report_type(self):
        """Validate the report type"""
        if not isinstance(self.report_type, str) or len(self.report_type.strip()) == 0:
            raise ValueError("Invalid report type")
        valid_types = ["sales", "expenses", "inventory"]
        if self.report_type.upper() not in valid_types:
            raise ValueError(f"Invalid report type. Valid types are: {', '.join(valid_types)}")

    def validate_date_range(self):
        """Validate the date range"""
        if not isinstance(self.date_range, list) or len(self.date_range) != 2:
            raise ValueError("Invalid date range format")
        start_date = self.date_range[0]
        end_date = self.date_range[1]

        # Check if dates are in YYYY-MM-DD format
        try:
            from datetime import datetime
            start_date_obj = datetime.strptime(start_date, "%Y-%m-%d").date()
            end_date_obj = datetime.strptime(end_date, "%Y-%m-%d").date()
        except ValueError:
            raise ValueError("Invalid date format. Should be YYYY-MM-DD")

        # Check if start date is before end date
        if start_date_obj > end_date_obj:
            raise ValueError("Start date should be before or equal to end date")

    def validate(self):
        """Validate the entire report input"""
        try:
            self.validate_report_type()
            self.validate_date_range()
        except ValueError as e:
            print(f"Validation error: {e}")
            return False
        print("Report input is valid")
        return True


# Example usage
if __name__ == "__main__":
    validator = ReportInputValidator("sales", ["2022-01-01", "2022-12-31"])
    if validator.validate():
        # Report input is valid, proceed with report generation
        pass
    else:
        # Report input is invalid, do not generate report
        pass

