import requests
from urllib.parse import urlencode, quote_plus
import json
import time
import os

class OAuthAuthenticator:
    def __init__(self, base_url, client_id, client_secret, token_url):
        self.base_url = base_url
        self.client_id = client_id
        self.client_secret = client_secret
        self.token_url = token_url
        # Set a reasonable timeout for requests
        self.timeout = 10

    def get_access_token(self, code, redirect_uri):
        # Get the authorization token from the API
        data = {
            "grant_type": "authorization_code",
            "code": quote_plus(code),
            "redirect_uri": quote_plus(redirect_uri)
        }
        headers = {"Content-Type": "application/json"}

        try:
            response = requests.post(self.token_url, headers=headers, data=json.dumps(data), timeout=self.timeout)
            if response.status_code == 200:
                return response.json()["access_token"]
            else:
                raise Exception(f"Failed to get access token with status code {response.status_code}")
        except requests.exceptions.Timeout as e:
            raise Exception(f"Request timed out: {e}")
        except requests.exceptions.RequestException as e:
            raise Exception(f"Request failed: {e}")

    def make_request_with_access_token(self, endpoint, method="GET", data=None):
        # Make a request to the API with the access token
        headers = {"Authorization": f"Bearer {self.get_access_token(None, None)}"}

        try:
            response = requests.request(method, self.base_url + endpoint, headers=headers, timeout=self.timeout)
            if response.status_code == 200:
                return response.json()
            elif response.status_code == 401:  
                raise Exception("Unauthorized")
            else:
                raise Exception(f"Failed to make request with status code {response.status_code}")
        except requests.exceptions.Timeout as e:
            raise Exception(f"Request timed out: {e}")
        except requests.exceptions.RequestException as e:
            raise Exception(f"Request failed: {e}")

    @staticmethod
    def load_client_secret():
        # Load the client secret from a secure environment variable or file
        client_secret = os.environ.get("CLIENT_SECRET")
        if not client_secret:
            raise ValueError("Client secret is missing")
        return client_secret

# Example usage
if __name__ == "__main__":
    # Replace these with your own client ID and secret
    base_url = "https://api.example.com"
    client_id = "your_client_id_here"

