from cryptography.fernet import Fernet
import base64
import os

class SocialMediaAPI:
    def __init__(self, api_name, api_id, api_secret):
        self.api_name = api_name
        self.api_id = api_id
        self.api_secret = api_secret

    def generate_key(self):
        # Generate a secret key for encryption
        return Fernet.generate_key()

    def encrypt_data(self, data):
        # Encrypt the API credentials using the generated key
        fernet = Fernet(self.key)
        encrypted_data = fernet.encrypt(data.encode())
        return base64.b64encode(encrypted_data).decode()

    def decrypt_data(self, data):
        # Decrypt the API credentials using the generated key
        fernet = Fernet(self.key)
        decrypted_data = fernet.decrypt(base64.b64decode(data))
        return decrypted_data.decode()

class SocialMediaAPIManager:
    def __init__(self):
        self.keys = {}

    def add_api_credentials(self, api_name, api_id, api_secret):
        # Generate a secret key for encryption
        key = SocialMediaAPI(api_name, api_id, api_secret).generate_key()
        self.keys[api_name] = {"key": key, "api_id": api_id, "api_secret": api_secret}

    def get_api_credentials(self, api_name):
        # Return the decrypted API credentials
        if api_name in self.keys:
            return self.decrypt_data(f"API Credentials for {api_name}: {self.keys[api_name]['api_id']}:{self.keys[api_name]['api_secret']}")
        else:
            return None

    def remove_api_credentials(self, api_name):
        # Remove the API credentials from storage
        if api_name in self.keys:
            del self.keys[api_name]

def main():
    # Create an instance of SocialMediaAPIManager
    manager = SocialMediaAPIManager()

    # Add some example API credentials
    manager.add_api_credentials("Facebook", "1234567890", "abcdefg")
    manager.add_api_credentials("Twitter", "9876543210", "hijklmnop")

    # Get the decrypted API credentials for Facebook
    facebook_credentials = manager.get_api_credentials("Facebook")
    print(facebook_credentials)

if __name__ == "__main__":
    main()

import os
import paramiko
from subprocess import call, check_output

class Server:
    def __init__(self, ip_address, username, password):
        self.ip_address = ip_address
        self.username = username
        self.password = password

    def deploy_os(self, os_name):
        ssh = paramiko.SSHClient()
        ssh.set_missing_host_key_policy(paramiko.AutoAddPolicyWithKey())

        # Use a list to prevent shell injection
        commands = []
        if os_name == 'Ubuntu':
            command = ["sudo", "/usr/bin/deploy-ubuntu.sh"]
        elif os_name == 'CentOS':
            command = ["sudo", "/usr/bin/deploy-centos.sh"]
        else:
            print(f"Unsupported OS: {os_name}")
            return

        try:
            ssh.connect(self.ip_address, username=self.username, key_filename=None)
            for c in command:
                check_output([c])
            stdout, stderr = ssh.exec_command(" ".join(command))
        except paramiko.SSHException as e:
            print(f"Deployment error: {e}")
            exit(1)

        if stdout.channel.read():
            print(f"Deployment error: {stdout.channel.read().decode('utf-8')}")
            exit(1)
        else:
            print("OS deployed successfully")

        ssh.close()

    def install_software(self, software_names):
        # Use a list to prevent shell injection
        commands = []
        for software in software_names:
            command = ["sudo", "apt-get", "install", software]
            try:
                stdout, stderr = ssh.exec_command(" ".join(command))
                commands.append((command, stdout, stderr))
            except paramiko.SSHException as e:
                print(f"Error installing {software}: {e}")
                exit(1)

        for command, stdout, stderr in commands:
            if stdout.channel.read():
                print(f"Error installing {command[2]}: {stdout.channel.read().decode('utf-8')}")
                exit(1)
            else:
                print(f"{command[2]} installed successfully")

    def set_security_features(self):
        try:
            ssh = paramiko.SSHClient()
            ssh.set_missing_host_key_policy(paramiko.AutoAddPolicyWithKey())
            ssh.connect(self.ip_address, username=self.username, key_filename=None)

            command = ["sudo", "firewall-cmd", "--add-port=22"]

            # Use a list to prevent shell injection
            commands = [command]
            try:
                stdout, stderr = ssh.exec_command(" ".join(commands))
                if stdout.channel.read():
                    print(f"Firewall error: {stdout.channel.read().decode('utf-8')}")
                    exit(1)
                else:
                    print("Firewall enabled")
            except paramiko.SSHException as e:
                print(f"Firewall error: {e}")
                exit(1)

        except paramiko.AuthenticationException:
            print("Authentication failed. Please provide a valid password.")
            exit(1)

# Example usage
if __name__ == "__main__":
    ip_address = "192.168.1.100"
    username = "user_name"

    server = Server(ip_address, username, 'your_password')

    os_name = 'Ubuntu'
    software_names = ['git', 'python3-pip']
    security_features = True

    if security_features:
        print("Enabling security features...")
        server.set_security_features()

    server.deploy_os(os_name)
    server.install_software(software_names)

