import logging
from typing import Dict, List

# Set up logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class DeploymentTracker:
    def __init__(self):
        self.deployment_failures: Dict[str, int] = {}
        self.deployment_history: List[Dict[str, str]] = []

    def track_deployment_failure(self, deployment_name: str):
        """Track a failed deployment"""
        if deployment_name not in self.deployment_failures:
            self.deployment_failures[deployment_name] = 0
        self.deployment_failures[deployment_name] += 1
        logger.info(f"Failed deployment: {deployment_name}")

    def report_deployment_failure(self, deployment_name: str):
        """Report a failed deployment"""
        if deployment_name not in self.deployment_failures:
            logger.error(f"No failure data available for deployment: {deployment_name}")
            return
        logger.info(f"{self.deployment_failures[deployment_name]} failures reported for deployment: {deployment_name}")

    def view_deployment_history(self):
        """View the deployment history"""
        if not self.deployment_history:
            logger.info("No deployment history available")
            return
        logger.info("\nDeployment History:")
        for i, deployment in enumerate(self.deployment_history):
            logger.info(f"Deployment {i+1}: {deployment['name']}, Status: {deployment['status']}")

    def get_deployment_status(self, deployment_name: str) -> int:
        """Get the number of failures for a deployment"""
        if deployment_name not in self.deployment_failures:
            return 0
        return self.deployment_failures[deployment_name]


def main():
    tracker = DeploymentTracker()
    while True:
        print("\n1. Track Deployment Failure")
        print("2. Report Deployment Failure")
        print("3. View Deployment History")
        print("4. Get Deployment Status")
        print("5. Exit")
        choice = input("Choose an option: ")
        if choice == "1":
            deployment_name = input("Enter deployment name: ")
            tracker.track_deployment_failure(deployment_name)
        elif choice == "2":
            deployment_name = input("Enter deployment name: ")
            tracker.report_deployment_failure(deployment_name)
        elif choice == "3":
            tracker.view_deployment_history()
        elif choice == "4":
            deployment_name = input("Enter deployment name: ")
            print(f"Number of failures: {tracker.get_deployment_status(deployment_name)}")
        elif choice == "5":
            break
        else:
            logger.error("Invalid option chosen")


