import os
import paramiko
from getpass import getpass

class RemoteBackup:
    def __init__(self, host, username, password):
        self.host = host
        self.username = username
        self.password = password

    def create_sftp_connection(self):
        ssh_client = paramiko.SSHClient()
        # Set policy to reject unknown host keys
        ssh_client.set_missing_host_key_policy(paramiko.RejectPolicy())
        try:
            ssh_client.connect(self.host, username=self.username, password=self.password)
            sftp_client = ssh_client.open_sftp()
            return sftp_client
        except Exception as e:
            print(f"Error connecting to remote server: {e}")
            exit(1)

    def upload_file(self, local_path, remote_path):
        try:
            with open(local_path, 'rb') as file:
                sftp_client = self.create_sftp_connection()
                sftp_client.put(file, remote_path)
            print(f"File uploaded successfully to {remote_path}")
        except Exception as e:
            print(f"Error uploading file: {e}")

    def backup_files(self, local_dir, remote_dir):
        for root, dirs, files in os.walk(local_dir):
            for file in files:
                local_file = os.path.join(root, file)
                remote_file = os.path.join(remote_dir, file)
                self.upload_file(local_file, remote_file)

def main():
    host = input("Enter the remote server hostname: ")
    username = input("Enter your SSH username: ")
    password = getpass("Enter your SSH password: ")

    backup = RemoteBackup(host, username, password)
    local_dir = input("Enter the directory path to backup: ")
    remote_dir = '/remote/path'  # Replace with your desired remote directory

    if not os.path.exists(local_dir):
        print(f"Local directory {local_dir} does not exist.")
        exit(1)

    try:
        backup.backup_files(local_dir, remote_dir)
    except Exception as e:
        print(f"Error backing up files: {e}")
        exit(1)

if __name__ == "__main__":
    main()

import psutil
import time
from datetime import datetime

class BackupJob:
    def __init__(self, name):
        self.name = name
        self.status = "Pending"
        self.last_update = None

    def update_status(self):
        try:
            process = psutil.Process(psutil.PID)
            if process.exists():
                status = process.status()
                if status == 0:  # Successful
                    self.status = "Success"
                elif status == -16:  # Child process terminated
                    self.status = "Error"
                else:
                    self.status = "Running"
        except Exception as e:
            print(f"Error updating status for {self.name}: {e}")
        self.last_update = datetime.now()

class BackupMonitor:
    def __init__(self):
        self.jobs = {}

    def add_job(self, name):
        self.jobs[name] = BackupJob(name)

    def update_all_jobs(self):
        for job in self.jobs.values():
            job.update_status()

def main():
    monitor = BackupMonitor()
    while True:
        monitor.update_all_jobs()
        print("\nBackup Job Status:")
        for job in monitor.jobs.values():
            if job.status == "Running":
                time.sleep(1)  # Update every second
                continue
            print(f"{job.name}: {job.status}")
        time.sleep(2)  # Update every 2 seconds

if __name__ == "__main__":
    main()

