import docker

class ContainerResourceMonitor:
    def __init__(self, host):
        self.host = host
        self.client = docker.from_env()

    def get_container_info(self, container_name):
        try:
            return self.client.containers.get(container_name).stats()
        except docker.errors.NoSuchContainer:
            print(f"Container {container_name} does not exist.")
            return None

    def monitor_resource_usage(self, container_name, interval=1.0):
        while True:
            stats = self.get_container_info(container_name)
            if stats is None:
                continue
            # Extract relevant resource usage metrics from the stats object.
            cpu_percent = stats['cpu_percent']
            memory_percent = stats['memory_percent']

            print(f"Container {container_name} Resource Usage:")
            print(f"CPU: {cpu_percent}%")
            print(f"Memory: {memory_percent}%")
            print("---------------------------")

            # Sleep for the specified interval before checking again.
            import time
            time.sleep(interval)

# Example usage:
if __name__ == "__main__":
    host = 'localhost'
    monitor = ContainerResourceMonitor(host)
    container_name = 'example_container'

    # Start monitoring the resource usage of the container.
    monitor.monitor_resource_usage(container_name)

import logging
from docker import Client as DockerClient

# Set up logging configuration
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class ContainerCrashHandler:
    def __init__(self, docker_client):
        self.docker_client = docker_client

    def check_container_status(self, container_id):
        try:
            response = self.docker_client.inspect(container=container_id)
            return response['State']['Running']
        except Exception as e:
            logger.error(f"Failed to get container status: {e}")
            return False

    def restart_container(self, container_id):
        try:
            self.docker_client.restart(container=container_id)
            logger.info(f"Container {container_id} restarted successfully")
        except Exception as e:
            logger.error(f"Failed to restart container {container_id}: {e}")

def main():
    # Initialize Docker client
    docker_client = DockerClient()

    # Create container crash handler instance
    handler = ContainerCrashHandler(docker_client)

    # Check and handle container crashes
    while True:
        container_ids = [id for id in docker_client.containers.list() if not handler.check_container_status(id)]

        if container_ids:
            logger.warning(f"Container(s) crashed: {', '.join(container_ids)}")

            # Attempt to restart crashed containers
            for container_id in container_ids:
                handler.restart_container(container_id)

            # Wait a bit before checking again
            import time
            time.sleep(300)  # 5 minutes

if __name__ == "__main__":
    main()

