import re
from pathlib import Path

class MalformedTextFile:
    def __init__(self, filename):
        self.filename = filename
        self.malformed_rows = []

    def parse_file(self):
        try:
            with open(self.filename, 'r') as file:
                rows = file.readlines()
                for row in rows:
                    # Remove leading and trailing whitespace from the row
                    row = row.strip()

                    # Check if the row is empty or contains only whitespace characters
                    if not row or re.match(r'\s+', row):
                        self.malformed_rows.append(row)
                        continue

                    # Try to split the row into columns
                    try:
                        columns = row.split(',')
                    except Exception as e:
                        print(f"Error parsing row: {e}")
                        self.malformed_rows.append(row)

                return rows  # Return the parsed file contents
        except FileNotFoundError:
            print(f"File '{self.filename}' not found.")
            return None

    def write_to_file(self, new_filename):
        try:
            with open(new_filename, 'w') as new_file:
                for row in self.malformed_rows:
                    if ',' in row:
                        # Split the row into columns and write to the file
                        columns = row.split(',')
                        new_file.write(f"{columns[0]} {columns[1]}\n")
            print(f"Malformed rows written to '{new_filename}'")
        except Exception as e:
            print(f"Error writing to file: {e}")

def main():
    filename = "malformed_text.txt"
    new_filename = "cleaned_text.txt"

    malformed_file = MalformedTextFile(filename)
    parsed_rows = malformed_file.parse_file()

    if parsed_rows:
        malformed_file.write_to_file(new_filename)

if __name__ == "__main__":
    main()

