logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class WebhookReceiver:
    def __init__(self, webhook_url):
        self.webhook_url = webhook_url

    async def handle_webhook(self, event):
        # Handle incoming events here
        logger.info(f'Received event: {event}')
        if 'type' in event and event['type'] == 'test_event':
            print('Test Event received')
        elif 'type' in event and event['type'] == 'push':
            push_data = event.get('push', None)
            if push_data:
                message_id = push_data.get('message_id', None)
                # Update your database here
                logger.info(f'Received push event with message ID: {message_id}')
        else:
            print(f'Invalid event type: {event["type"]}')

    async def receive_webhook(self):
        while True:
            try:
                event = await self.webhook_url.get()
                if 'error' in event and event['error'] == 'Connection Error':
                    logger.error('Webhook connection error')
                else:
                    await self.handle_webhook(event)
            except Exception as e:
                logger.error(f'Error receiving webhook: {e}')

