import logging
from queue import Queue
import requests
import json
import time

# Set up logging configuration
logging.basicConfig(
    format='%(asctime)s [%(levelname)s] %(message)s',
    level=logging.INFO,
    datefmt='%Y-%m-%d %H:%M:%S'
)

class WebhookLogger:
    def __init__(self, webhook_url):
        self.webhook_url = webhook_url
        self.queue = Queue()

    def log_event(self, event_data):
        # Process event data and add to queue for sending via webhook
        processed_data = json.dumps(event_data)
        logging.info(f'Queued event: {processed_data}')
        self.queue.put(processed_data)

    def send_webhook(self):
        while not self.queue.empty():
            try:
                data = self.queue.get(timeout=5)  # Retrieve from queue with timeout
                start_time = time.time()
                response = requests.post(self.webhook_url, json=data, timeout=None)
                end_time = time.time()
                response_time = end_time - start_time
                if response.status_code == 200:
                    logging.info(f'Sent event successfully: {data} (Response time: {response_time:.2f}s)')
                else:
                    logging.error(f'Failed to send event: {data} (Status code: {response.status_code}) (Response time: {response_time:.2f}s)')
            except requests.Timeout as e:
                logging.error(f'Timeout while sending event: {data}')
            except requests.RequestException as e:
                logging.error(f'Error sending event: {data} ({e})')

# Example usage
if __name__ == '__main__':
    webhook_url = 'https://example.com/webhook'
    logger = WebhookLogger(webhook_url)

    # Simulate some events to log
    for i in range(10):
        event_data = {'id': i, 'type': f'event-{i}'}
        logger.log_event(event_data)
        logger.send_webhook()

