class WebhookTrigger(Resource):
    def post(self):
        # Get the request data from the POST request body
        payload = request.get_json()

        # Process the incoming payload and respond accordingly
        response = jsonify({})
        if 'event' in payload:
            if payload['event'] == 'webhook triggered':
                response = jsonify({'message': 'Webhook trigger received successfully'})
            elif 'data' in payload:
                response = jsonify(payload)
            else:
                response = jsonify({'error': f"Invalid event: {payload['event']}"})
        elif 'data' in payload:
            response = jsonify(payload)
        else:
            response = jsonify({'error': 'Missing required request data'})

        return response

