from mutagen.mp3 import MP3
from mutagen.id3 import ID3
from mutagen.flac import FLAC
from mutagen.vorbis import Vorbis
from mutagen.oggvorbis import OggVorbis
from mutagen.wav import WAV

def get_audio_metadata(file_path):
    # Initialize audio metadata
    metadata = None

    # Check the file extension to determine which format it is
    if file_path.endswith('.mp3'):
        metadata = MP3(file_path)
    elif file_path.endswith('.flac') or file_path.endswith('.wav'):
        metadata = FLAC(file_path) if file_path.endswith('.flac') else WAV(file_path)
    elif file_path.endswith('.ogg') or file_path.endswith('.ogv'):
        metadata = OggVorbis(file_path) if file_path.endswith('.ogg') else Vorbis(file_path)
    elif file_path.endswith('.m4a'):
        metadata = ID3(file_path)

    # Extract and print the metadata
    if metadata:
        print(f"Audio File: {file_path}")

        if hasattr(metadata, 'tags'):
            print("Title:", metadata.tags.title[0].text[0])
            print("Artist:", metadata.tags.artist[0].text[0])
            print("Album:", metadata.tags.album[0].text[0])
            print("Genre:", metadata.tags.genre[0].text[0])
        else:
            # FLAC and WAV do not have title tags
            print("Title: Not available")

        if hasattr(metadata, 'disks'):
            for i, disk in enumerate(metadata.disks):
                print(f"Disk {i+1}: {disk.title.text[0]}")

        if hasattr(metadata, 'tracks'):
            for track in metadata.tracks:
                print(f"Track {track.number}: {track.title.text[0]} ({track.duration.seconds} seconds)")
    else:
        print("Error: Unable to parse audio file")

# Test the function
get_audio_metadata('test.mp3')

