import psutil
import time
from datetime import timedelta

def get_process_name(pid):
    """Get process name from PID"""
    try:
        return psutil.Process(pid).name()
    except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
        return "Unknown Process"

class CronJobDurationMonitor:
    def __init__(self, interval=10):  # in seconds
        self.interval = interval
        self.processes = {}

    def monitor(self):
        """Monitor and calculate cron job durations"""
        while True:
            for pid, proc in list(self.processes.items()):
                try:
                    if psutil.Process(pid).status() == 'Z':  # Zombie process
                        del self.processes[pid]
                        continue

                    try:
                        process_name = get_process_name(pid)
                    except Exception as e:
                        print(f"Error getting process name for PID {pid}: {str(e)}")
                        continue

                    if pid in self.processes:
                        start_time = self.processes[pid][1]['start_time']
                        duration = time.time() - start_time
                        elapsed_time = timedelta(seconds=int(duration))
                        self.processes[pid] = (process_name, elapsed_time)
                    else:
                        self.processes[pid] = (process_name, time.time())

                except Exception as e:
                    print(f"Error monitoring process {process_name} with PID {pid}: {str(e)}")

            # Wait for interval seconds before checking again
            time.sleep(self.interval)

def main():
    monitor = CronJobDurationMonitor()
    print("Cron Job Duration Monitoring Program Started")
    try:
        while True:  # Run indefinitely
            pass
    except KeyboardInterrupt:
        print("\nStopping program...")
    finally:
        print("Program stopped.")

if __name__ == "__main__":
    main()

class ShoppingCart:
    def __init__(self):
        self.cart = {}

    # Method to display the shopping cart
    def display_cart(self):
        print("Shopping Cart:")
        for item, quantity in self.cart.items():
            print(f"{item}: {quantity}")

    # Method to add an item to the shopping cart
    def add_item(self, name, price, quantity=1):
        if name in self.cart:
            self.cart[name]["quantity"] += quantity
        else:
            self.cart[name] = {"price": price, "quantity": quantity}

    # Method to remove an item from the shopping cart
    def remove_item(self, name):
        if name in self.cart:
            del self.cart[name]
        else:
            print("Item not found in cart.")

    # Method to update the quantity of an item
    def update_quantity(self, name, quantity):
        if name in self.cart:
            self.cart[name]["quantity"] = quantity
        else:
            print("Item not found in cart.")

    # Method to calculate the total cost of items in the shopping cart
    def calculate_total(self):
        total = 0
        for item, details in self.cart.items():
            total += details["price"] * details["quantity"]
        return total

