class Item:
    """Represents an item in the inventory."""

    def __init__(self, name, quantity):
        self.name = name
        self.quantity = quantity


class Inventory:
    """Manages the overall inventory."""

    def __init__(self):
        self.items = {}

    def add_item(self, name, quantity):
        """Adds a new item to the inventory."""

        if name in self.items:
            print(f"Item {name} already exists. Updating quantity.")
            self.items[name].quantity += quantity
        else:
            self.items[name] = Item(name, quantity)

    def remove_item(self, name, quantity):
        """Removes a specified quantity of an item from the inventory."""

        if name in self.items:
            if self.items[name].quantity >= quantity:
                self.items[name].quantity -= quantity
                print(f"Quantity of {name} updated to {self.items[name].quantity}.")
            else:
                print(f"Not enough {name} in stock. Only {self.items[name].quantity} available.")
        else:
            print(f"No {name} in inventory.")

    def check_quantity(self, name):
        """Checks the quantity of an item in the inventory."""

        if name in self.items:
            print(f"Quantity of {name}: {self.items[name].quantity}")
        else:
            print(f"No {name} in inventory.")


def main():
    # Create a new inventory
    inventory = Inventory()

    while True:
        print("\nInventory Management Menu:")
        print("1. Add item")
        print("2. Remove item")
        print("3. Check quantity")
        print("4. Exit")

        choice = input("Enter your choice: ")

        if choice == "1":
            name = input("Enter item name: ")
            quantity = int(input("Enter quantity: "))
            inventory.add_item(name, quantity)
        elif choice == "2":
            name = input("Enter item name: ")
            quantity = int(input("Enter quantity to remove: "))
            inventory.remove_item(name, quantity)
        elif choice == "3":
            name = input("Enter item name: ")
            inventory.check_quantity(name)
        elif choice == "4":
            break
        else:
            print("Invalid choice. Please try again.")


if __name__ == "__main__":
    main()

