import datetime

class Product:
    def __init__(self, name, quantity):
        self.name = name
        self.quantity = quantity

class StockMonitor:
    def __init__(self):
        self.products = {}

    def add_product(self, name, quantity):
        if name in self.products:
            print(f"Product {name} already exists.")
            return
        self.products[name] = Product(name, quantity)
        print(f"Product {name} added successfully.")

    def update_quantity(self, name, new_quantity):
        if name not in self.products:
            print(f"Product {name} does not exist.")
            return
        self.products[name].quantity = new_quantity
        print(f"Quantity of product {name} updated to {new_quantity}.")
        print(f"Current stock level: {self.get_stock_level(name)}")

    def remove_product(self, name):
        if name not in self.products:
            print(f"Product {name} does not exist.")
            return
        del self.products[name]
        print(f"Product {name} removed successfully.")

    def get_stock_level(self, name):
        if name not in self.products:
            print(f"Product {name} does not exist.")
            return None
        return self.products[name].quantity

    def display_products(self):
        for product in self.products.values():
            print(f"Name: {product.name}, Quantity: {product.quantity}")

def main():
    monitor = StockMonitor()

    while True:
        print("1. Add Product")
