            new_quantity = int(input("Enter new quantity: "))
            monitor.update_quantity(name, new_quantity)
        elif choice == "3":
            name = input("Enter product name: ")
            monitor.remove_product(name)
        elif choice == "4":
            name = input("Enter product name: ")
