import requests
from requests.exceptions import RequestException, ConnectionError, HTTPError
import time

class PaymentGatewayError(Exception):
    def __init__(self, message, http_status_code=None):
        self.message = message
        self.http_status_code = http_status_code

    def __str__(self):
        return f"Payment Gateway Error: {self.message} ({self.http_status_code})"


def send_payment_request(card_number, expiration_date, cvv, amount, timeout=5):
    try:
        url = "https://example.com/payment"
        headers = {"Content-Type": "application/json"}
        data = {
            "card_number": card_number,
            "expiration_date": expiration_date,
            "cvv": cvv,
            "amount": amount
        }

        response = requests.post(url, headers=headers, json=data, timeout=timeout, allow_redirects=True)

        # Check for any exceptions during request
        if response.status_code == 200:
            return True
        elif response.status_code >= 300:
            raise PaymentGatewayError(f"Redirected. Status code: {response.status_code}", response.status_code)
        else:
            raise PaymentGatewayError(f"Failed to send payment request. Status code: {response.status_code}", response.status_code)
    except RequestException as e:
        if e.response is not None and e.response.status_code >= 300:
            raise PaymentGatewayError("Request Exception", e.response.status_code) from e
        else:
            raise PaymentGatewayError("Request Exception", None) from e
    except ConnectionError as e:
        raise PaymentGatewayError("Connection Error", None) from e
    except HTTPError as e:
        raise PaymentGatewayError(f"HTTP Error - Status code: {e.response.status_code}", e.response.status_code) from e


def main():
    try:
        # Define payment parameters
        card_number = "1234567890123456"
        expiration_date = "12/2025"
        cvv = "123"
        amount = 100

        if send_payment_request(card_number, expiration_date, cvv, amount):
            print("Payment successful.")
        else:
            raise PaymentGatewayError(f"Failed to send payment request. Status code: {send_payment_request(card_number, expiration_date, cvv, amount).http_status_code}")
    except PaymentGatewayError as e:
        print(f"Payment Gateway Error: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")


if __name__ == "__main__":
    main()

import hashlib
import time

class Block:
    def __init__(self, index, previous_hash, timestamp, data, nonce=0):
        self.index = index
        self.previous_hash = previous hash
        self.timestamp = timestamp
        self.data = data
        self.nonce = nonce
        self.hash = self.calculate_hash()

    def calculate_hash(self):
        data_string = str(self.index) + self.previous_hash + str(self.timestamp) + str(self.data) + str(self.nonce)
        return hashlib.sha256(data_string.encode()).hexdigest()


class Blockchain:
    def __init__(self):
        self.chain = [self.create_genesis_block()]

    def create_genesis_block(self):
        return Block(0, "0", int(time.time()), "Genesis Block")

    def get_latest_block(self):
        return self.chain[-1]

    def add_new_block(self, data):
        new_block_index = len(self.chain)
        new_block_previous_hash = self.get_latest_block().hash
        new_block_timestamp = int(time.time())
        new_block = Block(new_block_index, new_block_previous_hash, new_block_timestamp, data)

        self.chain.append(new_block)

    def validate_chain(self):
        for i in range(1, len(self.chain)):
            current_block = self.chain[i]
            previous_block = self.chain[i - 1]

            if current_block.hash != current_block.calculate_hash():
                return False

            if current_block.previous_hash != previous_block.hash:
                return False

            if current_block.timestamp < previous_block.timestamp:
                return False

        return True


# Create a new blockchain
my_blockchain = Blockchain()

# Add some new blocks to the chain
for i in range(10):
    my_blockchain.add_new_block(f"Transaction {i}")

# Validate the blockchain
if my_blockchain.validate_chain():
    print("The blockchain is valid!")
else:
    print("The blockchain is not valid!")

import hashlib
import time

class Block:
    def __init__(self, index, previous_hash, timestamp, data):
        self.index = index
        self.previous_hash = previous_hash
        self.timestamp = timestamp
        self.data = data
        self.hash = self.calculate_hash()

    @staticmethod
    def calculate_hash(block):
        # Use SHA-256 hashing algorithm to create a unique hash for each block
        block_string = str(block.index) + block.previous_hash + str(block.timestamp) + str(block.data)
        return hashlib.sha256(block_string.encode()).hexdigest()


class Blockchain:
    def __init__(self):
        self.chain = [self.create_genesis_block()]

    def create_genesis_block(self):
        # Create the first block in the blockchain, known as the genesis block
        return Block(0, "0", int(time.time()), "Genesis Block")

    def get_latest_block(self):
        return self.chain[-1]

    def add_block(self, new_block):
        new_block.previous_hash = self.get_latest_block().hash
        new_block.hash = new_block.calculate_hash()
        self.chain.append(new_block)

    def log_transaction(self, data):
        # Create a new block to store the transaction
        new_block = Block(len(self.chain), self.get_latest_block().hash, int(time.time()), data)
        self.add_block(new_block)


# Example usage:
if __name__ == "__main__":
    blockchain = Blockchain()

    # Log some transactions
    blockchain.log_transaction("Transaction 1")
    blockchain.log_transaction("Transaction 2")
    blockchain.log_transaction("Transaction 3")

    # Print the current state of the ledger
    for block in blockchain.chain:
        print(f"Block {block.index} - Hash: {block.hash}")
        print(f"Timestamp: {block.timestamp}")
        print(f"Data: {block.data}")
        print("-------------------")

