from flask import Flask, render_template, request, redirect, url_for, flash
from flask_mail import Mail, Message
import secrets
import os
from datetime import timedelta
import bcrypt

app = Flask(__name__)
app.secret_key = os.urandom(24)

# Configure Flask-Mail
app.config['MAIL_SERVER'] = 'smtp.example.com'
app.config['MAIL_PORT'] = 587
app.config['MAIL_USERNAME'] = 'your_email@example.com'
app.config['MAIL_PASSWORD'] = os.environ.get('MAIL_PASSWORD')  # Fixed: Use environment variable instead of hardcoded password
app.config['MAIL_DEFAULT_SENDER'] = 'your_email@example.com'
app.config['PERMANENT_SESSIONS'] = False
mail = Mail(app)

# In-memory storage (replace with database in production)
users = {
    'user@example.com': {
        'password': bcrypt.hashpw(b'old_password', bcrypt.gensalt()).decode('utf-8'),
        'confirmed': True
    }
}

@app.route('/reset_password', methods=['GET', 'POST'])
def reset_password():
    if request.method == 'POST':
        email = request.form.get('email')
        user = users.get(email)

        if not user or not user.get('confirmed'):
            flash('User not found or account not confirmed.')
            return redirect(url_for('reset_password'))

        # Generate reset token
        token = secrets.token_urlsafe(32)
        users[email]['reset_token'] = token

        # Send reset email
        reset_url = url_for('reset_password_confirm', token=token, _external=True)
        msg = Message('Password Reset', recipients=[email])
        msg.body = f'Click the link to reset your password: {reset_url}'
        mail.send(msg)

        flash('Reset link sent to your email.')
        return redirect(url_for('login'))

    return render_template('reset_password.html')

@app.route('/reset_password_confirm/<token>', methods=['GET', 'POST'])
def reset_password_confirm(token):
    if request.method == 'POST':
        new_password = request.form.get('new_password')
        user_email = None

        for email, user_data in users.items():
            if user_data.get('reset_token') == token:
                user_email = email
                break

        if not user_email:
            flash('Invalid or expired token.')
            return redirect(url_for('reset_password'))

        # Update password and clear token
        users[user_email]['password'] = bcrypt.hashpw(new_password.encode('utf-8'), bcrypt.gensalt()).decode('utf-8')
        del users[user_email]['reset_token']
        flash('Password successfully updated.')
        return redirect(url_for('login'))

    return render_template('reset_password_confirm.html', token=token)

if __name__ == '__main__':
    app.run(debug=False, ssl_context='adhoc')  # Use HTTPS in production

import hashlib
import secrets
import time
import pyotp
import qrcode
from datetime import datetime, timedelta

class MFASystem:
    def __init__(self):
        self.users = {}  # In-memory storage for demonstration

    def register_user(self, username, password):
        """Register a new user with a password and generate a TOTP secret."""
        # Generate TOTP secret (16 bytes = 128 bits)
        totp_secret = secrets.token_urlsafe(16).encode('ascii')

        # Store hashed password and TOTP secret
        hashed_password = hashlib.sha256(password.encode()).hexdigest()
        self.users[username] = {
            'password': hashed_password,
            'totp_secret': totp_secret
        }

        return totp_secret.decode('ascii')

    def generate_totp(self, username, totp_secret):
        """Generate current TOTP code for a user."""
        totp = pyotp.HOTP(totp_secret)
        return totp.at(self._get_counter())

    def _get_counter(self, username):
        """Get and increment TOTP counter (for demo purposes)."""
        if username not in self.users:
            return 0
        if not hasattr(self, '_counter'):
            self._counter = {}
        if username not in self._counter:
            self._counter[username] = 0
        counter = self._counter[username]
        self._counter[ = counter + 1
        return counter

    def authenticate(self, username, password, totp_code):
        """Authenticate user with password and TOTP code."""
        if username not in self.users:
            return False

        # Verify password
        hashed_password = self.users[username]['password']
        if hashlib.sha256(password.encode()).hexdigest() != hashed_password:
            return False

        # Verify TOTP
        totp_secret = self.users[username]['totp_secret']
        totp = pyotp.HOTP(totp_secret)
        return totp.verify(totp_code, self._get_counter(username))

class MFAManager:
    def __init__(self):
        self.mfa_system = MFASystem()

    def register(self, username, password):
        """Register a new user and generate QR code for TOTP setup."""
        totp_secret = self.mfa_system.register_user(username, password)
        return self._generate_qr(totp_secret, username)

    def _generate_qr(self, totp_secret, username):
        """Generate QR code for TOTP setup."""
        # Generate QR code URL (standard format)
        issuer = "MyApp"
        qr_data = f"otpauth://totp/{username}?secret={totp_secret}&issuer={issuer}"
        qr = qrcode.QRCode(
            version=1,
            error_correction=qrcode.constants.ERROR_CORRECT_L,
            box_size=10,
            border=4,
        )
        qr.add_data(qr_data)
        qr.make_fitted()
        img = qr.make_image(fill_color="black", back_color="white")
        img.save(f"{username}_mfa_qr.png")
        return qr_data

    def login(self, username, password, totp_code):
        """Authenticate user with MFA."""
        return self.mfa_system.authenticate(username, password, totp_code)

# Example usage
if __name__ == "__main__":
    mfa_manager = MFAManager()

    # Registration
    print("=== Registration ===")
    username = input("Enter username: ")
    password = input("Enter password: ")
    totp_secret = mfa_manager.register(username, password)
    print("Registration successful! Scan this QR code with your authenticator app:")
    print(mfa_manager._generate_qr(totp_secret, username))

    # Login
    print("\n=== Login ===")
    username = input("Username: ")
    password = input("Password: ")
    totp_code = input("TOTP Code: ")

    if mfa_manager.login(username, password, totp_code):
        print("Authentication successful!")
    else:
        print("Authentication failed. Invalid credentials or TOTP code.")

