class User:
    def __init__(self, roles):
        self.roles = roles

class Resource:
    def __init__(self, name, permission_name):
        self.name = name
        self.permission_name = permission_name

# Dictionary mapping permission names to required roles
PERMISSIONS = {
    'read': {'admin', 'user'},
    'write': {'admin'},
    'delete': {'admin'}
}

def can_access(user, resource):
    required_roles = PERMISSIONS.get(resource.permission_name, set())
    user_roles = user.roles
    return required_roles.intersection(user_roles)

# Example usage
if __name__ == "__main__":
    # Define users
    admin_user = User({'admin'})
    regular_user = User({'user'})

    # Define resources
    doc_resource = Resource('document.txt', 'read')
    edit_resource = Resource('edit.txt', 'write')
    del_resource = Resource('delete.txt', 'delete')

    # Check access permissions
    print(can_access(admin_user, doc_resource))   # Output: True
    print(can_access(regular_user, doc_resource)) # Output: True
    print(can_access(regular_user, edit_resource))# Output: False
    print(can_access(admin_user, del_resource))   # Output: True

import defusedxml.ElementTree as ET

def serialize_to_xml(obj, root_tag='root'):
    root = ET.Element(root_tag)
    convert_to_xml(obj, root)
    return ET.tostring(root, encoding='unicode')

def convert_to_xml(obj, parent):
    if obj is None:
        elem = ET.Element('None')
        elem.text = 'None'
        parent.append(elem)
    elif isinstance(obj, (int, float, bool, str)):
        elem = ET.Element('value')
        elem.text = str(obj)
        parent.append(elem)
    elif isinstance(obj, (list, tuple)):
        for item in obj:
            item_elem = ET.Element('item')
            convert_to_xml(item, item_elem)
            parent.append(item_elem)
    elif isinstance(obj, dict):
        for key, value in obj.items():
            key_elem = ET.Element(key)
            convert_to_xml(value, key_elem)
            parent.append(key_elem)
    else:
        if hasattr(obj, '__dict__'):
            d = obj.__dict__
            for key, value in d.items():
                elem = ET.Element(key)
                convert_to_xml(value, elem)
                parent.append(elem)
        else:
            elem = ET.Element(str(type(obj)))
            elem.text = str(obj)
            parent.append(elem)

