from flask import Flask, jsonify, request

app = Flask(__name__)

# In-memory storage
books = [
    {"id": 1, "title": "Python Programming", "author": "Eric Matthes"},
    {"id": 2, "title": "Flask Web Development", "author": "Miguel Grinberg"}
]

def find_book(book_id):
    return next((book for book in books if book["id"] == book_id), None)

# Get all books
@app.route('/books', methods=['GET'])
def get_books():
    return jsonify(books)

# Get single book
@app.route('/books/<int:book_id>', methods=['GET'])
def get_book(book_id):
    book = find_book(book_id)
    if book:
        return jsonify(book)
    return jsonify({"error": "Book not found"}), 404

# Create new book
@app.route('/books', methods=['POST'])
def create_book():
    if not request.json or 'title' not in request.json or 'author' not in request.json:
        return jsonify({"error": "Bad request"}), 400
    new_book = {
        "id": len(books) + 1,
        "title": request.json['title'],
        "author": request.json['author']
    }
    books.append(new_book)
    return jsonify(new_book), 201

# Update book
@app.route('/books/<int:book_id>', methods=['PUT'])
def update_book(book_id):
    book = find_book(book_id)
    if not book:
        return jsonify({"error": "Book not found"}), 404
    if not request.json:
        return jsonify({"error": "Bad request"}), 400
    book['title'] = request.json.get('title', book['title'])
    book['author'] = request.json.get('author', book['author'])
    return jsonify(book)

# Delete book
@app.route('/books/<int:book_id>', methods=['DELETE'])
def delete_book(book_id):
    global books
    book = find_book(book_id)
    if not book:
        return jsonify({"error": "Book not found"}), 404
    books = [b for b in books if b["id"] != book_id]
    return jsonify({"result": "Book deleted"})

if __name__ == '__main__':
    app.run(debug=False)

import os
from functools import wraps
from flask import Flask, request, jsonify

app = Flask(__name__)

# Configuration (in real apps, use environment variables or a config file)
API_KEY = "test-key"
SECRET_TOKEN = os.environ['AUTH_SECRET_TOKEN']

# Authentication Handler Interface
class AuthHandler:
    def validate(self, credentials):
        raise NotImplementedError

# Basic Auth Handler
class BasicAuthHandler(AuthHandler):
    def __init__(self, username, password):
        self.username = username
        self.password = password

    def validate(self, credentials):
        return credentials == (self.username, self.password)

# API Key Auth Handler
class ApiKeyAuthHandler(AuthHandler):
    def __init__(self, api_key):
        self.api_key = api_key

    def validate(self, credentials):
        return credentials == self.api_key

# Bearer Token Auth Handler
class BearerTokenAuthHandler(AuthHandler):
    def __init__(self, token):
        self.token = token

    def validate(self, credentials):
        return credentials == self.token

# Authorization Decorator
def authorize(auth_type, **kwargs):
    def decorator(f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            auth_handler = None
            credentials = None

            # Determine auth method
            if auth_type == 'basic':
                if 'username' not in kwargs or 'password' not in kwargs:
                    return jsonify({"error": "Missing username or password"}), 401
                auth_handler = BasicAuthHandler(kwargs['username'], kwargs['password'])
                credentials = (kwargs['username'], kwargs['password'])
            elif auth_type == 'api_key':
                if 'api_key' not in kwargs:
                    return jsonify({"error": "Missing API key"}), 401
                auth_handler = ApiKeyAuthHandler(kwargs['api_key'])
                credentials = kwargs['api_key']
            elif auth_type == 'bearer':
                if 'token' not in kwargs:
                    return jsonify({"error": "Missing bearer token"}), 401
                auth_handler = BearerTokenAuthHandler(kwargs['token'])
                credentials = kwargs['token']
            else:
                return jsonify({"error": "Unsupported auth type"}), 400

            # Validate credentials
            if not auth_handler.validate(credentials):
                return jsonify({"error": "Invalid credentials"}), 403

            return f(*args, **kwargs)
        return decorated_function
    return decorator

# Example Endpoint with Basic Auth
@app.route('/basic')
@authorize(auth_type='basic', username='admin', password=os.environ['AUTH_BASIC_PASSWORD'])
def basic_protected():
    return jsonify({"message": "Basic Auth successful!"})

# Example Endpoint with API Key Auth
@app.route('/api-key')
@authorize(auth_type='api_key', api_key=API_KEY)
def api_key_protected():
    return jsonify({"message": "API Key Auth successful!"})

# Example Endpoint with Bearer Token
@app.route('/bearer')
@authorize(auth_type='bearer', token=SECRET_TOKEN)
def bearer_protected():
    return jsonify({"message": "Bearer Token Auth successful!"})

if __name__ == '__main__':
    app.run(ssl_context='adhoc')  # Run with HTTPS for secure transport

import re
from typing import Optional, Dict, List

def validate_name(name: str) -> Optional[str]:
    """Validate name format and length."""
    if not isinstance(name, str):
        return "Name must be a string."
    if len(name) < 2:
        return "Name must be at least 2 characters long."
    return None

def validate_email(email: str) -> Optional[str]:
    """Validate email format using regex."""
    if not isinstance(email, str):
        return "Email must be a string."
    if not re.match(r"[^@]+@[^@]+\.[^@]+", email):
        return "Invalid email format."
    return None

def validate_password(password: str, confirm: str) -> Optional[str]:
    """Validate password complexity and match with confirmation."""
    if password != confirm:
        return "Passwords do not match."

    if len(password) < 8:
        return "Password must be at least 8 characters long."

    if not re.search(r"[A-Z]", password):
        return "Password must contain at least one uppercase letter."

    if not re.search(r"[0-9]", password):
        return "Password must contain at least one digit."

    return None

def validate_form(
    name: str,
    email: str,
    password: str,
    confirm_password: str
) -> Dict[str, List[str]]:
    """Validate all form fields and return error messages."""
    errors = {
        'name': [],
        'email': [],
        'password': [],
        'confirm_password': []
    }

    # Validate name
    name_error = validate_name(name)
    if name_error:
        errors['name'].append(name_error)

    # Validate email
    email_error = validate_email(email)
    if email_error:
        errors['email'].append(email_error)

    # Validate password and confirmation
    password_error = validate_password(password, confirm_password)
    if password_error:
        errors['password'].append(password_error)
        errors['confirm_password'].append("Password does not match.")

    return errors

def main():
    # Example usage
    name = input("Enter your name: ")
    email = input("Enter your email: ")
    password = input("Enter your password: ")
    confirm_password = input("Confirm your password: ")

    form_errors = validate_form(
        name=name,
        email=email,
        password=password,
        confirm_password=confirm_password
    )

    if form_errors:
        print("Validation errors:")
        for field, error_list in form_errors.items():
            for error in error_list:
                print(f"  {field}: {error}")
    else:
        print("Form submitted successfully!")

if __name__ == "__main__":
    main()

