import re

def validate_phone_number(phone):
    cleaned = re.sub(r'[^\d]', '', phone)
    if len(cleaned) == 10:
        return True
    elif len(cleaned) == 11 and cleaned[0] == '1':
        return True
    else:
        return False

def is_valid_date(date_str):
    parts = date_str.split('-')
    if len(parts) != 3:
        return None
    try:
        year = int(parts[0])
        month = int(parts[1])
        day = int(parts[2])
    except ValueError:
        return None
    if year < 1000 or year > 9999:
        return None
    if month < 1 or month > 12:
        return None
    if day < 1 or day > 31:
        return None
    return 'date'

def is_valid_time(time_str):
    parts = time_str.split(':')
    if len(parts) != 3:
        return None
    try:
        hour = int(parts[0])
        minute = int(parts[1])
        second = int(parts[2])
    except ValueError:
        return None
    if hour < 0 or hour > 23:
        return None
    if minute < 0 or minute > 59:
        return None
    if second < 0 or second > 59:
        return None
    return 'time'

def validate_datetime_format(datetime_str):
    date_result = is_valid_date(datetime_str)
    if date_result is not None:
        return date_result
    time_result = is_valid_time(datetime_str)
    return time_result

