import time
from functools import wraps

def retry(retries=3, delay=1, exception=(Exception,), log=None):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            count = 0
            while count < retries:
                try:
                    return func(*args, **kwargs)
                except exception as e:
                    count += 1
                    if log:
                        log.error(f"Retry {count}/{retries} for {func.__name__}: {str(e)}")
                    time.sleep(delay)
                    continue
            try:
                return func(*args, **kwargs)
            except exception as e:
                if log:
                    log.error(f"{func.__name__} failed after {retries} retries: {str(e)}")
                raise e
        return wrapper
    return decorator

