import logging
from contextlib import contextmanager
import psycopg2  # Example using PostgreSQL; replace with your DB library

# Configure logging
logging.basicConfig(
    filename='db_errors.log',
    level=logging.ERROR,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Database connection parameters (replace with your own)
DB_CONFIG = {
    'dbname': 'your_db',
    'user': 'your_user',
    'password': 'your_password',
    'host': 'localhost',
    'port': 5432
}

@contextmanager
def db_connection():
    """Context manager for handling database connections."""
    conn = None
    try:
        conn = psycopg2.connect(**DB_CONFIG)
        yield conn
    except Exception as e:
        logging.error(f"Database connection failed: {str(e)}")
        raise
    finally:
        if conn:
            conn.close()

@contextmanager
def transaction(connection):
    """Context manager for handling database transactions."""
    try:
        connection.autocommit = False
        yield connection
    except Exception as e:
        connection.rollback()
        logging.error(f"Transaction failed: {str(e)}")
        raise
    else:
        try:
            connection.commit()
        except Exception:
            connection.rollback()
            logging.error("Commit failed")
            raise
    finally:
        connection.autocommit = True

@contextmanager
def db_cursor():
    """Context manager to handle database operations with logging."""
    with db_connection() as conn:
        with conn.cursor() as cur:
            try:
                yield cur
            except Exception as e:
                # Log the specific query that failed
                if cur.query is not None:
                    query_hex = cur.query.decode('utf-8') if isinstance(cur.query, bytes) else cur.query
                    logging.error(f"Failed query (hex): {query_hex}")
                logging.error(f"Database error: {str(e)}")

# Example usage
