import requests
from functools import wraps
from requests.exceptions import Timeout, ConnectTimeoutError, RequestException

def api_with_fallback(primary_url, fallback_url):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            try:
                response = requests.get(primary_url, timeout=5)
                response.raise_for_status()  # Raise exception for HTTP errors
                return response.json()
            except (Timeout, ConnectTimeoutError) as e:
                print(f"Primary API failed: {e}. Falling back to secondary API.")
                try:
                    fallback_response = requests.get(fallback_url, timeout=5)
                    fallback_response.raise_for_status()
                    return fallback_response.json()
                except RequestException as e2:
                    print(f"Fallback API also failed: {e2}")
                    raise Exception("Both primary and fallback APIs failed.")
            except RequestException as e:
                print(f"Primary API error: {e}")
                raise
            except Exception as e:
                print(f"Unexpected error: {e}")
                raise
        return wrapper
    return decorator

# Example usage
if __name__ == "__main__":
    @api_with_fallback('https://primary-api.example.com/data', 'https://fallback-api.example.com/data')
    def fetch_data():
        pass  # The actual data fetching is handled by the decorator

    try:
        data = fetch_data()
        print("Data fetched successfully:", data)
    except Exception as e:
        print("Error:", e)

