import socket
import threading
import json

HOST = 'localhost'
PORT = 5000
clients = {}
sessions = {}  # Store session data keyed by session_id

def handle_client(conn, addr):
    print(f"Connected by {addr}")
    try:
        while True:
            data = conn.recv(1024).decode('utf-8')
            if not data:
                break
            message = json.loads(data)
            session_id = message.get('session_id')
            action = message.get('action')

            if session_id and session_id not in sessions:
                sessions[session_id] = {'client': conn, 'addr': addr}
                print(f"New session started by {addr} with ID {session_id}")

            if action == 'login':
                username = message.get('username')
                if username:
                    sessions[session_id]['username'] = username
                    print(f"User {username} logged in from {addr}")
                    conn.send(json.dumps({'status': 'success'}).encode('utf-8'))
                else:
                    conn.send(json.dumps({'status': 'error', 'message': 'Username required'}).encode('utf-8'))
            elif action == 'logout':
                del sessions[session_id]
                print(f"User {username} logged out from {addr}")
                conn.send(json.dumps({'status': 'success'}).encode('utf-8'))
            else:
                conn.send(json.dumps({'status': 'error', 'message': 'Invalid action'}).encode('utf-8'))
    except Exception as e:
        print(f"Error in client {addr}: {e}")
    finally:
        conn.close()
        if 'session_id' in locals():
            del sessions[session_id]

def start_server():
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
        s.bind((HOST, PORT))
        s.listen()
        print(f"Server listening on {HOST}:{PORT}")
        while True:
            conn, addr = s.accept()
            threading.Thread(target=handle_client, args=(conn, addr), daemon=True).start()

if __name__ == "__main__":
    start_server()

