from flask import Flask, request, jsonify
import jwt
import datetime
import os

app = Flask(__name__)

# Secret key for JWT (keep secure in production)
SECRET_KEY = os.urandom(24).decode('utf-8')

@app.route('/login', methods=['POST'])
def login():
    auth = request.json
    username = auth.get('username')
    password = auth.get('password')

    # Validate credentials (dummy check)
    # Use environment variable for password if available
    env_password = os.environ.get('ADMIN_PASSWORD')
    if not env_password:
        return jsonify({'error': 'Admin password not configured'}), 401

    if username == 'admin' and password == env_password:
        # Create JWT token
        access_token = jwt.encode({
            'user': username,
            'exp': datetime.datetime.utcnow() + datetime.timedelta(minutes=15)
        }, SECRET_KEY)
        return jsonify({'token': access_token.decode('utf-8')})
    return jsonify({'error': 'Invalid credentials'}), 401

@app.route('/protected', methods=['GET'])
def protected():
    auth_header = request.headers.get('Authorization')
    if not auth_header:
        return jsonify({'error': 'Missing token'}), 401

    # Validate and decode JWT
    try:
        token = auth_header.split(' ')[1]  # Expect format: Bearer <token>
        payload = jwt.decode(token, SECRET_KEY, algorithms=['HS256'])
    except jwt.ExpiredSignatureError:
        return jsonify({'error': 'Token expired'}), 401
    except jwt.InvalidTokenError:
        return jsonify({'error': 'Invalid token'}), 401

    return jsonify({'message': f'Hello {payload["user"]}')

if __name__ == '__main__':
