class Role:
    def __init__(self, name):
        self.name = name
        self.permissions = set()

    def assign_permission(self, permission):
        self.permissions.add(permission)

class User:
    def __init__(self, username):
        self.username = username
        self.roles = set()

    def add_role(self, role):
        self.roles.add(role)

class Resource:
    def __init__(self, name):
        self.name = name
        self.access_logs = []

    def can_access(self, user, permission):
        return any(permission in user.roles[p].permissions for p in user.roles)

    def access_recorded(self, user, action):
        self.access_logs.append((user.username, action))

class RBACSystem:
    def __init__(self):
        self.roles = {}
        self.users = {}
        self.resources = {}

    def create_role(self, role_name):
        if role_name not in self.roles:
            self.roles[role_name] = Role(role_name)

    def assign_user_role(self, username, role_name):
        if username not in self.users:
            self.users[username] = User(username)
        if role_name not in self.roles:
            self.create_role(role_name)
        self.users[username].add_role(self.roles[role_name])

    def create_resource(self, resource_name):
        if resource_name not in self.resources:
            self.resources[resource_name] = Resource(resource_name)

    def enforce_access(self, username, resource_name, action, permission):
        user = self.users.get(username)
        resource = self.resources.get(resource_name)

        if not user or not resource:
            return False

        if not resource.can_access(user, permission):
            return False

        resource.access_recorded(user, action)
        return True

# Example Usage
if __name__ == "__main__":
    rbac_system = RBACSystem()

    # Define roles and permissions
    rbac_system.create_role("admin")
    rbac_system.roles["admin"].assign_permission("manage_users")

    rbac_system.create_role("user")
    rbac_system.roles["user"].assign_permission("view_data")

    # Assign roles to users
    rbac_system.assign_user_role("alice", "admin")
    rbac_system.assign_user_role("bob", "user")

    # Create resources
    rbac_system.create_resource("users")
    rbac_system.create_resource("data")

    # Check access
    print(rbac_system.enforce_access("alice", "users", "manage", "manage_users"))  # True
    print(rbac_system.enforce_access("bob", "data", "view", "view_data"))         # True
    print(rbac_system.enforce_access("bob", "users", "manage", "manage_users"))   # False

    # View access logs
    print("\nAccess Logs:")
    for user, action in rbac_system.resources["users"].access_logs:
        print(f"{user} {action}")
    for user, action in rbac_system.resources["data"].access_logs:
        print(f"{user} {action}")

def validate_privilege(user, action):
    # Dictionary mapping user names to their privileges
    user_privileges = {
        'admin': {'read', 'write', 'execute', 'delete'},
        'user1': {'read', 'write'},
        'user2': {'execute'},
        'guest': {'read'}
    }

    # Dictionary mapping action names to required privileges
    action_privileges = {
        'delete_file': {'delete'},
        'write_file': {'write'},
        'execute_script': {'execute'},
        'view_logs': {'read'}
    }

    # Get the required privileges for the action, if it exists
    required = action_privileges.get(action)

    # If the action is not found or the user has no privileges, return False
    if not required:
        return False

    # Check if the user has all the required privileges
    return required.issubset(user_privileges.get(user, set()))

# Example usage:
user = 'admin'
action = 'delete_file'
print(validate_privilege(user, action))  # Output: True

user = 'user1'
action = 'execute_script'
print(validate_privilege(user, action))  # Output: False

class Role:
    def __init__(self, name, parent=None):
        self.name = name
        self.parent = parent
        self.permissions = set()

    def add_permission(self, permission):
        self.permissions.add(permission)

    def get_all_permissions(self):
        permissions = set(self.permissions)
        if self.parent:
            permissions.update(self.parent.get_all_permissions())
        return permissions

class AccessSystem:
    def __init__(self):
        self.roles = {}

    def create_role(self, name, parent_name=None):
        parent = None
        if parent_name:
            if parent_name not in self.roles:
                raise ValueError(f"Parent role '{parent_name}' does not exist.")
            parent = self.roles[parent_name]
        role = Role(name, parent)
        self.roles[name] = role
        return role

    def assign_permission(self, role_name, permission):
        if role_name not in self.roles:
            raise ValueError(f"Role '{role_name}' does not exist.")
        self.roles[role_name].add_permission(permission)

    def check_access(self, role_name, required_permission):
        if role_name not in self.roles:
            raise ValueError(f"Role '{role_name}' does not exist.")
        permissions = self.roles[role_name].get_all_permissions()
        return required_permission in permissions

# Example usage
if __name__ == "__main__":
    system = AccessSystem()

    # Create roles with hierarchy
    owner = system.create_role("owner")
    manager = system.create_role("manager", "owner")
    user = system.create_role("user", "manager")

    # Assign permissions
    system.assign_permission("owner", "manage_system")
    system.assign_permission("manager", "manage_team")
    system.assign_permission("user", "view_data")

    # Check access
    print(system.check_access("user", "view_data"))       # True
    print(system.check_access("manager", "manage_team"))  # True
    print(system.check_access("manager", "manage_system")) # True (inherited from owner)
    print(system.check_access("user", "manage_system"))   # False

import hashlib
import json
import os
from cryptography.fernet import Fernet

# Generate encryption key (run once)
def generate_key():
    return Fernet.generate_key()

# Encrypt data
def encrypt_data(key, data):
    cipher = Fernet(key)
    return cipher.encrypt(data.encode())

# Decrypt data
def decrypt_data(key, encrypted_data):
    cipher = Fernet(key)
    return cipher.decrypt(encrypted_data).decode()

# User Authentication System
users = {
    "admin": hashlib.sha256("admin123".encode()).hexdigest(),
    "user": hashlib.sha256("user456".encode()).hexdigest()
}

def authenticate_user(username, password):
    stored_hash = users.get(username)
    if not stored_hash:
        return False
    input_hash = hashlib.sha256(password.encode()).hexdigest()
    return input_hash == stored_hash

# Role-Based Access Control
def check_access(user_role, resource):
    access_levels = {
        "admin": ["database", "users", "config"],
        "user": ["database"]
    }
    return resource in access_levels.get(user_role, [])

# Secure Data Storage
def store_data(username, data, key):
    if not authenticate_user(username, input("Enter password: ")):
        print("Authentication failed.")
        return
    if not check_access(username, "database"):
        print("Unauthorized access attempt.")
        return
    encrypted_data = encrypt_data(key, data)
    with open("secure_data.json", "a+") as f:
        f.seek(0)
        existing_data = json.load(f) if os.path.getsize("secure_data.json") > 0 else {}
        existing_data[username] = encrypted_data.decode()
        json.dump(existing_data, f)
        f.seek(0)
        f.truncate()

def retrieve_data(username, key):
    if not authenticate_user(username, input("Enter password: ")):
        print("Authentication failed.")
        return
    try:
        with open("secure_data.json", "r") as f:
            data_dict = json.load(f)
            if username in data_dict:
                encrypted_data = data_dict[username].encode()
                data = decrypt_data(key, encrypted_data)
                print("Decrypted data:", data)
            else:
                print("No data found for this user.")
    except FileNotFoundError:
        print("No data available.")

def main():
    key = generate_key().decode()
    os.environ["ENCRYPTION_KEY"] = key  # Store securely in real apps

    while True:
        print("\n1. Store Data\n2. Retrieve Data")
        choice = input("Enter choice: ")

        if choice == "1":
            username = input("Username: ")
            data = input("Data to store: ")
            store_data(username, data, key)
        elif choice == "2":
            username = input("Username: ")
            retrieve_data(username, key)
        else:
            print("Invalid choice.")

if __name__ == "__main__":
    main()

