from flask import Flask, request, redirect, url_for, flash
import os
from werkzeug.utils import secure_filename

app = Flask(__name__)
# Use environment variable for secret key (no fallback to hardcoded)
app.secret_key = os.environ['FLASK_SECRET_KEY']  # Requires environment variable to be set

ALLOWED_EXTENSIONS = {'png', 'jpg', 'jpeg', 'gif', 'pdf', 'doc', 'docx', 'txt'}

def allowed_file(filename):
    return '.' in filename and \
           filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

@app.route('/upload', methods=['POST'])
def upload_file():
    if 'file' not in request.files:
        flash('No file part')
        return redirect(request.url)

    file = request.files['file']

    if file.filename == '':
        flash('No selected file')
        return redirect(request.url)

    if not allowed_file(file.filename):
        flash('Invalid file type. Executable files are not allowed.')
        return redirect(request.url)

    if file and allowed_file(file.filename):
        filename = secure_filename(file.filename)
        file.save(os.path.join('/path/to/uploads', filename))
        flash('File successfully uploaded')
        return redirect(url_for('upload_file'))
    else:
        flash('Invalid file extension')
        return redirect(request.url)

if __name__ == '__main__':
    debug_mode = os.environ.get('FLASK_DEBUG', 'False').lower() in ('true', '1')
    app.run(debug=debug_mode)

