import time

class TimedCache:
    def __init__(self, default_expiration=None):
        self.cache = {}
        self.default_expiration = default_expiration  # Can be in seconds or None

    def set(self, key, value, expiration=None):
        """
        Set a value in the cache with an optional expiration time.
        If expiration is not provided, default_expiration is used.
        """
        if expiration is None and self.default_expiration is not None:
            expiration = self.default_expiration
        elif expiration is None:
            expiration = None  # No expiration

        if expiration is not None:
            expiration_time = time.time() + expiration
        else:
            expiration_time = None

        self.cache[key] = (value, expiration_time)

    def get(self, key):
        """
        Retrieve a value from the cache. If the entry has expired, it is removed and None is returned.
        """
        if key not in self.cache:
            return None

        value, expiration_time = self.cache[key]

        if expiration_time is not None and time.time() > expiration_time:
            del self.cache[key]
            return None  # Indicate a miss due to expiration

        return value

    def clear(self):
        """Remove all entries from the cache."""
        self.cache.clear()

def get_cache_stats():
    try:
        with open('/proc/meminfo', 'r') as f:
            lines = f.readlines()
    except FileNotFoundError:
        raise Exception("The /proc/meminfo file was not found. This program is intended for Linux systems.")
    except Exception as e:
        raise Exception(f"An error occurred while reading /proc/meminfo: {e}")

    cache_stats = {
        'total_cache': 0,
        'page_cache': 0,
        'slab_cache': 0
    }

    for line in lines:
        parts = line.split()
        if len(parts) < 2:
            continue

        key = parts[0].strip(':')
        try:
            value = int(parts[1])
        except ValueError:
            continue

        if key == 'Cached':
            cache_stats['page_cache'] += value
            cache_stats['total_cache'] += value
        elif key == 'Slab':
            # Slab cache includes both reclaimable and unreclaimable parts
            cache_stats['slab_cache'] += value
            cache_stats['total_cache'] += value

    return cache_stats

def format_size(bytes):
    """Format bytes into a human-readable string (KB, MB, GB, etc.)."""
    if bytes == 0:
        return '0 B'
    suffixes = ['B', 'KB', 'MB', 'GB', 'TB']
    factor = 1024.0
    for i in range(len(suffixes) - 1):
        if bytes < factor * factor:
            return f"{bytes / factor:.2f} {suffixes[i+1]}"
        bytes //= factor
    return f"{bytes / factor:.2f} {suffixes[-1]}"

if __name__ == '__main__':
    try:
        stats = get_cache_stats()
        total_kb = stats['total_cache']
        page_kb = stats['page_cache']
        slab_kb = stats['slab_cache']

        print("Cache Usage Report:")
        print(f"Total Cache: {format_size(total_kb)}")
        print(f"Page Cache: {format_size(page_kb)}")
        print(f"Slab Cache: {format_size(slab_kb)}")
        print(f"Page Cache Ratio: {page_kb / total_kb * 100:.2f}%")
        print(f"Slab Cache Ratio: {slab_kb / total_kb * 100:.2f}%")

    except Exception as e:
        print(f"Error: {e}")

import datetime

def log_to_file(message):
    """Appends a formatted message with a timestamp to the log file."""
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    log_entry = f"[{timestamp}] {message}\n"

    try:
        with open("app.log", "a") as log_file:
            log_file.write(log_entry)
    except Exception as e:
        print(f"Failed to write to log file: {e}")

