import time
from datetime import datetime, timedelta

# Configuration
EMAILS_PER_WINDOW = 5
WINDOW_DURATION_SECONDS = 60
ALLOW_BURSTS = True

# Tracking dictionary: {user_id: {last_reset: timestamp, count: int}}
tracking = {}

def can_send_email(user_id):
    """Check if the user can send an email based on the current rate limit."""
    now = datetime.now()
    key = (user_id, now.date())  # Use date to group by day

    if key not in tracking:
        tracking[key] = {'last_reset': now, 'count': 0}

    # Check if window needs reset
    last_reset = tracking[key]['last_reset']
    if now - last_reset >= timedelta(seconds=WINDOW_DURATION_SECONDS):
        tracking[key]['last_reset'] = now
        tracking[key]['count'] = 0

    # Check if burst is allowed
    if ALLOW_BURSTS:
        return tracking[key]['count'] < EMAILS_PER_WINDOW
    else:
        # Without bursting, check if the window is fully utilized
        return tracking[key]['count'] < EMAILS_PER_WINDOW

def send_email(user_id):
    """Simulate sending an email and update the tracking."""
    if not can_send_email(user_id):
        raise Exception("Rate limit exceeded. Please try again later.")

    # Update tracking
    key = (user_id, datetime.now().date())
    tracking[key]['count'] += 1

    print(f"Email sent successfully by {user_id}.")

# Example usage
if __name__ == "__main__":
    user = "user123"
    try:
        for _ in range(6):
            send_email(user)
            time.sleep(10)  # Simulate time between sends
    except Exception as e:
        print(e)

import re
from email import message_from_bytes
from email.header import decode_header

def extract_bounced_recipient(raw_email):
    """Extract the original recipient's email from a bounce notification."""
    msg = message_from_bytes(raw_email)

    # Check headers first
    for header in ['Return-Path', 'X-Original-To', 'To', 'Cc']:
        if header in msg:
            header_value = msg[header].decode('utf-8', 'ignore')
            match = re.search(r'<([^>]+)>', header_value)
            if match:
                return match.group(1).lower()

    # Search the body for recipient patterns
    body = "\n".join([part.get_payload(decode=True) if part.get_payload(decode=True) else '' for part in msg.walk()])
    pattern = r'recipient:\s*([^<]+)<([^>]+)>'
    match = re.search(pattern, body, re.IGNORECASE)
    if match:
        return match.group(2).lower()

    # Fallback: Extract from Message-ID if available
    message_id = msg['Message-ID']
    if message_id:
        message_id_part = message_id.split('<')[-1].split('>')[0].lower()
        return message_id_part

    raise ValueError("Could not extract recipient from bounce email")

# Example usage:
if __name__ == "__main__":
    # Read raw bounce email from stdin or a file
    import sys
    raw_email = sys.stdin.read().encode('utf-8')

    try:
        recipient = extract_bounced_recipient(raw_email)
        print(f"Bounced recipient: {recipient}")
        # Handle the bounced email (e.g., remove from database, log, etc.)
    except Exception as e:
        print(f"Error processing bounce: {str(e)}", file=sys.stderr)

