        print(f"Added filter: {field} = {values}")

    filtered_items = []
    for item in items:
        matches = True
        for field, values in filters.items():
            if field == 'age':
                if item.get(field) is None or not any(str(item[field]) == str(val) for val in values):
                    matches = False
                    break
            else:
                if item.get(field) not in values:
                    matches = False
                    break
        if matches:
            filtered_items.append(item)

    print("\nFiltered results:")
    for item in filtered_items:
        print(item)

if __name__ == "__main__":
    search_by_filters()

