def levenshtein_distance(s1, s2):
    if len(s1) < len(s2):
        return levenshtein_distance(s2, s1)

    if len(s2) == 0:
        return len(s1)

    previous_row = range(len(s2) + 1)

    for i, c1 in enumerate(s1):
        current_row = [i + 1]
        for j, c2 in enumerate(s2):
            insertions = previous_row[j + 1] + 1
            deletions = current_row[j] + 1 if j > 0 else 1
            substitutions = previous_row[j] + (c1 != c2)
            current_row.append(min(insertions, deletions, substitutions))
        previous_row = current_row

    return previous_row[-1]

def fuzzy_search(query, string_list, threshold=3):
    results = []
    for s in string_list:
        distance = levenshtein_distance(query, s)
        if distance <= threshold:
            results.append((s, distance))
    return results

# Example usage
if __name__ == "__main__":
    strings = ["apple", "apples", "applet", "application", "ale"]
    query = "appl"
    threshold = 2
    matches = fuzzy_search(query, strings, threshold)
    print("Query:", query)
    print("Threshold:", threshold)
    print("Matches:")
    for s, dist in matches:
        print(f"{s} (Distance: {dist})")

import json
import sys

def merge_configs(default_config, user_config):
    merged = {}
    for key, default_val in default_config.items():
        if key in user_config:
            user_val = user_config[key]
            if isinstance(default_val, dict) and isinstance(user_val, dict):
                merged[key] = merge_configs(default_val, user_val)
            else:
                merged[key] = user_val
        else:
            merged[key] = default_val
    return merged

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python config_merge.py <default_config.json> <user_config.json>")
        sys.exit(1)

    try:
        with open(sys.argv[1]) as f:
            default_config = json.load(f)
    except FileNotFoundError:
        print(f"Default configuration file {sys.argv[1]} not found.")
        sys.exit(1)
    except json.JSONDecodeError:
        print(f"Error decoding default configuration file {sys.argv[1]}.")
        sys.exit(1)

    try:
        with open(sys.argv[2]) as f:
            user_config = json.load(f)
    except FileNotFoundError:
        print(f"User configuration file {sys.argv[2]} not found.")
        sys.exit(1)
    except json.JSONDecodeError:
        print(f"Error decoding user configuration file {sys.argv[2]}.")
        sys.exit(1)

    merged_config = merge_configs(default_config, user_config)
    print(json.dumps(merged_config, indent=2))

import json
