from ruamel.yaml import YAML
from configparser import ConfigParser
from io import StringIO

def validate_config(config_str, format):
    if format == 'json':
        try:
            json.loads(config_str)
            return True
        except json.JSONDecodeError:
            return False
    elif format == 'yaml':
        try:
            yaml_loader = YAML(typ='safe')
            yaml_loader.load(config_str)
            return True
        except Exception:
            return False
    elif format == 'ini':
        try:
            parser = ConfigParser()
            with StringIO(config_str) as file:
                parser.read_file(file)
            return True
        except Exception:
            return False
    else:
        return "Unsupported format"

