import requests
from bs4 import BeautifulSoup
from urllib.parse import urljoin, urlparse
from requests.exceptions import RequestException

def check_url(url, base_url):
    """Check if the URL is valid and accessible."""
    try:
        response = requests.get(url, allow_redirects=True, timeout=5)
        return response.status_code < 400, url, response.status_code
    except RequestException as e:
        return False, url, str(e)

def handle_broken_links(base_url, html_content):
    """Find and report broken links in the given HTML content."""
    soup = BeautifulSoup(html_content, 'html.parser')
    links = []

    for a_tag in soup.find_all('a', href=True):
        href = a_tag.get('href')
        absolute_url = urljoin(base_url, href)

        # Filter out non-http(s) links and fragment-only links
        parsed = urlparse(absolute_url)
        if not (parsed.scheme and parsed.netloc) or parsed.path == '#' or parsed.path.startswith('#'):
            continue

        links.append(absolute_url)

    results = []
    for link in links:
        is_valid, status = check_url(link, base_url)
        if not is_valid:
            results.append((link, status))

    return results

if __name__ == "__main__":
    import sys
    if len(sys.argv) != 2:
        print("Usage: python broken_links_checker.py <URL>")
        sys.exit(1)

    target_url = sys.argv[1]
    base_url = target_url.split('/')[0] + '//'

    try:
        response = requests.get(target_url, timeout=5)
        if response.status_code == 200:
            broken_links = handle_broken_links(base_url, response.text)
            if broken_links:
                print("Broken Links Found:")
                for link, status in broken_links:
                    print(f"URL: {link}, Status: {status}")
            else:
                print("No broken links found.")
        else:
            print(f"Failed to access the page. Status code: {response.status_code}")
    except RequestException as e:
        print(f"Error accessing the page: {e}")

import hashlib
import sys
import os

def compute_checksum(file_path, algorithm):
    """Compute the checksum of a file using the specified algorithm."""
    hash_function = hashlib.new(algorithm.lower())
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b''):
            hash_function.update(chunk)
    return hash_function.hexdigest()

def validate_checksums(downloaded_file, checksum_file):
    """Validate the checksums from the checksum file against the downloaded file."""
    with open(checksum_file, 'r') as f:
        for line in f:
            parts = line.strip().split()
            if len(parts) < 2:
                continue
            checksum = parts[0]
            filename = parts[1].strip()
            if filename != downloaded_file:
                continue
            algorithm = 'md5'  # Default algorithm
            if len(checksum) == 64:
                algorithm = 'sha512'  # SHA-512 produces 64-character hash
            elif len(checksum) == 40:
                algorithm = 'md5'  # MD5 produces 32-character hash (40 in hex)
            elif len(checksum) == 44:
                algorithm = 'sha1'  # SHA-1 produces 40-character hash (44 in hex)
            elif len(checksum) == 64:
                algorithm = 'sha256'  # SHA-256 produces 64-character hash

            computed = compute_checksum(downloaded_file, algorithm)
            if computed == checksum:
                print(f"Verification OK: {downloaded_file}")
                return True
            else:
                print(f"Verification FAILED: {downloaded_file}")
                print(f"Expected: {checksum} ({algorithm.upper()})")
                print(f"Computed: {computed} ({algorithm.upper()})")
                return False
    return False

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python checksum_validator.py <downloaded_file> <checksum_file>")
        sys.exit(1)

    downloaded_file = sys.argv[1]
    checksum_file = sys.argv[2]

    if not os.path.exists(downloaded_file):
        print(f"Error: The file '{downloaded_file}' does not exist.")
        sys.exit(1)

    if not os.path.exists(checksum_file):
        print(f"Error: The checksum file '{checksum_file}' does not exist.")
        sys.exit(1)

    validate_checksums(downloaded_file, checksum_file)

import os
import json
import time
import pkg_resources
from datetime import datetime

# Configuration
STATE_FILE = 'dependency_state.json'
LOG_FILE = 'dependency_changes.log'

def get_installed_packages():
    """Get a dictionary of installed packages and their versions."""
    return {pkg.key: pkg.version for pkg in pkg_resources.working_set}

def save_state(packages):
    """Save the current package state to a JSON file."""
    with open(STATE_FILE, 'w') as f:
        json.dump(packages, f, indent=2)

def load_state():
    """Load the previous state from the JSON file."""
    if not os.path.exists(STATE_FILE):
        return {}
    with open(STATE_FILE, 'r') as f:
        return json.load(f)

def log_changes(changes):
    """Log changes to a log file with timestamps."""
    timestamp = datetime.now().isoformat()
    log_entry = {
        'timestamp': timestamp,
        'changes': changes
    }

    with open(LOG_FILE, 'a') as f:
        f.write(f"{timestamp}\n")
        f.write(json.dumps(changes, indent=2))
        f.write("\n\n")

def main():
    # Get current installed packages
    current_packages = get_installed_packages()

    # Load previous state
    previous_state = load_state()

    # Compare states
    changes = {}

    # Check for new packages
    for pkg, version in current_packages.items():
        if pkg not in previous_state:
            changes[pkg] = {
                'added': version,
                'previous': None
            }

    # Check for removed packages
    for pkg in previous_state.keys():
        if pkg not in current_packages:
            changes[pkg] = {
                'previous': previous_state[pkg],
                'removed': None
            }

    # Check for version changes
    for pkg, current_ver in current_packages.items():
        if pkg in previous_state and previous_state[pkg] != current_ver:
            changes[pkg] = {
                'previous': previous_state[pkg],
                'current': current_ver
            }

    # Save current state
    save_state(current_packages)

    # Log changes if any
    if changes:
        log_changes(changes)
        print(f"Changes detected at {datetime.now()}")
        print(json.dumps(changes, indent=2))
    else:
        print("No changes detected.")

if __name__ == "__main__":
    main()

import importlib.metadata
import sys
from typing import Dict, List

def get_installed_version(package_name: str) -> str:
    """Retrieve the installed version of a package using importlib.metadata."""
    return importlib.metadata.version(package_name)

def check_dependencies(expected_versions: Dict[str, str]) -> bool:
    """Check if installed versions of dependencies match expected versions."""
    breaking_changes = []
    for package, expected in expected_versions.items():
        try:
            installed = get_installed_version(package)
            if installed != expected:
                breaking_changes.append(f"{package} (expected {expected}, got {installed})")
        except importlib.metadata.PackageNotFoundError:
            breaking_changes.append(f"{package} not installed")
    return breaking_changes

if __name__ == "__main__":
    # Define expected versions for dependencies (adjust as needed)
    expected_dependencies = {
        'requests': '2.25.1',
        'numpy': '1.19.2',
        'flask': '1.1.2',
    }

    changes = check_dependencies(expected_dependencies)
    if changes:
        print("Breaking changes detected:")
        for change in changes:
            print(f"  - {change}")
        print("\nPlease update the expected versions in expected_dependencies.")
        sys.exit(1)
    else:
        print("All dependencies are up to date. No breaking changes detected.")

