import concurrent.futures
import time
from typing import Callable, Any, List, Optional

class ThreadPoolManager:
    def __init__(self, max_workers: Optional[int] = None):
        self._executor = concurrent.futures.ThreadPoolExecutor(max_workers=max_workers)
        self._shutdown = False

    def submit(self, func: Callable[..., Any], *args: Any, **kwargs: Any) -> concurrent.futures.Future:
        """Submit a callable to the thread pool and return a Future object."""
        if self._shutdown:
            raise RuntimeError("ThreadPoolManager is shutdown")
        return self._executor.submit(func, *args, **kwargs)

    def shutdown(self, wait: bool = True, timeout: Optional[float] = None) -> None:
        """Shutdown the thread pool, optionally waiting for all tasks to complete."""
        if not self._shutdown:
            self._shutdown = True
            self._executor.shutdown(wait=wait, timeout=timeout)

    def __enter__(self) -> 'ThreadPoolManager':
        return self

    def __exit__(self, exc_type, exc_val, exc_tb) -> bool:
        self.shutdown()
        return False

# Example usage
def simulate_workload(n: int) -> str:
    print(f"Task {n} started")
    time.sleep(1)  # Simulate work
    return f"Task {n} completed"

def main():
    with ThreadPoolManager(max_workers=3) as executor:
        futures: List[concurrent.futures.Future] = []
        for i in range(5):
            future = executor.submit(simulate_workload, i)
            futures.append(future)

        # Retrieve results once all tasks are done
        results = [future.result() for future in concurrent.futures.as_completed(futures)]
        for res in results:
            print(res)

if __name__ == "__main__":
    main()

import threading
import time

class SafeThread(threading.Thread):
    def __init__(self, name, target, args=None, kwargs=None):
        super().__init__(name=name, target=target, args=args, kwargs=kwargs)
        self._exception = None
        self._target_name = name  # Name of the target function for reporting

    def run(self):
        try:
            super().run()
        except Exception as e:
            self._exception = e

    def get_exception(self):
        return self._exception

    def report_exception(self):
        if self._exception:
            print(f"Thread {self._target_name} encountered an exception:")
            print(f"  Type: {type(self._exception).__name__}")
            print(f"  Message: {str(self._exception)}")
            self._exception = None  # Clear the exception after reporting

# Example usage
def task_with_error():
    print("Task started")
    raise ValueError("An error occurred in the task")

def task_without_error():
    print("Task completed successfully")

threads = []
for i in range(3):
    t = SafeThread(f"Thread-{i}", target=task_with_error if i % 2 == 0 else task_without_error)
    threads.append(t)
    t.start()

# Wait for all threads to complete
time.sleep(1)  # Allow time for exceptions to be set

# Check and report exceptions
for t in threads:
    if t.is_alive():
        t.join(timeout=0.1)  # Wait briefly if still alive

    if t.get_exception():
        t.report_exception()

import socket
import select

# Server configuration
HOST = '127.0.0.1'
PORT = 12345
MAX_CLIENTS = 5  # Maximum number of clients the server can handle

def handle_client(conn, addr, clients):
    print(f"Connected by {addr}")
    try:
        while True:
            # Use select to check for readable sockets (including stdin for server control)
            readable, _, _ = select.select([conn, sys.stdin], [], [], 0.1)

            for sock in readable:
                if sock == conn:
                    # Receive data from the client
                    data = conn.recv(1024)
                    if not data:
                        break  # Client disconnected
                    message = data.decode('utf-8')
                    print(f"Received from {addr}: {message}")
                    # Broadcast the message to all clients except the sender
                    for client in clients:
                        if client != conn:
                            client.send(data)
                elif sock == sys.stdin:
                    # Handle server input for shutdown
                    if sys.stdin.readline().strip() == 'shutdown':
                        print("Shutting down server...")
                        raise KeyboardInterrupt
    except (ConnectionError, BrokenPipeError):
        print(f"Client {addr} disconnected")
    finally:
        conn.close()
        clients.remove(conn)

def main():
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server_socket.bind((HOST, PORT))
    server_socket.listen(MAX_CLIENTS)
    print(f"Server listening on {HOST}:{PORT}")

    clients = []  # List to keep track of active client connections
    try:
        while True:
            readable, _, _ = select.select([server_socket] + clients, [], [])

            for sock in readable:
                if sock == server_socket:
                    # Accept new client connection
                    conn, addr = sock.accept()
                    conn.setblocking(False)
                    clients.append(conn)
                    print(f"Accepted connection from {addr}")
                else:
                    # Handle client data or disconnection
                    handle_client(sock, addr=sock.getpeername(), clients=clients)
    except KeyboardInterrupt:
        print("\nServer is shutting down...")
    finally:
        # Close all client connections and the server socket
        for conn in clients:
            conn.close()
        server_socket.close()

if __name__ == "__main__":
    import sys
    main()

import socket
import threading

clients = []
HOST = 'localhost'
PORT = 5555

def broadcast(message):
    for client in clients:
        try:
            client.send(message)
        except:
            clients.remove(client)

def handle_client(client_socket):
    while True:
        try:
            message = client_socket.recv(1024)
            if not message:
                break
            print(f"Received: {message.decode()}")
            broadcast(message)
        except:
            clients.remove(client_socket)
            client_socket.close()
            break

def start_server():
    server = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server.bind((HOST, PORT))
    server.listen()
    print(f"Server listening on {HOST}:{PORT}")

    while True:
        client_socket, addr = server.accept()
        print(f"New connection from {addr}")
        clients.append(client_socket)
        thread = threading.Thread(target=handle_client, args=(client_socket,))
        thread.start()

if __name__ == "__main__":
    start_server()

import asyncio
import websockets
import json
from websockets.exceptions import ConnectionClosedError

async def handle_connection(websocket):
    try:
        while True:
            try:
                # Receive message
                message = await websocket.recv()

                # Parse JSON message
                data = json.loads(message)
                print(f"Received message: {data}")

                # Example: Handle different message types
                if data.get('type') == 'subscribe':
                    print(f"Subscribed to: {data.get('topic')}")
                elif data.get('type') == 'data':
                    print(f"Data received: {data.get('payload')}")
                else:
                    print(f"Unhandled message type: {data.get('type', 'unknown')}")

    except ConnectionClosedError:
        print("Connection closed by client")
        break
    except json.JSONDecodeError:
        print("Invalid JSON format received")
    except Exception as e:
        print(f"Error handling message: {str(e)}")

async def main():
    async with websockets.serve(handle_connection, "localhost", 8765):
        print("WebSocket server started on ws://localhost:8765")
        asyncio.get_event_loop().run_forever()

if __name__ == "__main__":
    asyncio.run(main())

