import re
from datetime import datetime

def validate_cvv(cvv):
    cvv = cvv.replace(" ", "")
    return re.fullmatch(r'\d{3,4}', cvv) is not None

def validate_expiration(expiry):
    expiry = expiry.replace(" ", "")
    if not re.fullmatch(r'\d{2}/\d{2}', expiry):
        return False
    month, year = expiry.split('/')
    if not (month.isdigit() and year.isdigit()):
        return False
    month_int = int(month)
    year_int = int(year)
    if month_int < 1 or month_int > 12:
        return False
    if year_int < datetime.now().year % 100:
        return False
    return True

# Example usage:
