if validate_cvv(cvv_input):
    print("CVV is valid.")
else:
    print("CVV is invalid.")

expiry_input = input("Enter Expiration Date (MM/YY): ")
if validate_expiration(expiry_input):
    print("Expiration date is valid.")
else:
    print("Expiration date is invalid.")

