import logging
import logging.config
import sqlite3
import json
from datetime import datetime
from pathlib import Path
from typing import Dict, List, Optional, Union

class IoTActivityLogger:
    def __init__(self, config_path: str = 'logging_config.json'):
        self.config_path = config_path
        self.loggers = {}
        self._load_config()
        self._setup_loggers()

    def _load_config(self):
        """Load logging configuration from JSON file"""
        try:
            with open(self.config_path, 'r') as f:
                config = json.load(f)
            logging.config.dictConfig(config)
            self.config = config
        except FileNotFoundError:
            self._setup_default_config()

    def _setup_default_config(self):
        """Set up default logging configuration"""
        default_config = {
            'version': 1,
            'formatters': {
                'standard': {
                    'format': '%(asctime)s - %(name)s - %(levelname)s - %(message)s'
                }
            },
            'handlers': {
                'file': {
                    'level': 'DEBUG',
                    'class': 'logging.FileHandler',
                    'filename': 'iot_device.log',
                    'formatter': 'standard'
                },
                'console': {
                    'level': 'INFO',
                    'class': 'logging.StreamHandler',
                    'formatter': 'standard'
                }
            },
            'loggers': {
                'iot_activity': {
                    'level': 'DEBUG',
                    'handlers': ['file', 'console'],
                    'propagate': False
                }
            }
        }
        logging.config.dictConfig(default_config)
        self.config = default_config

    def _setup_loggers(self):
        """Initialize loggers based on configuration"""
        for logger_name, handler_configs in self.config.get('handlers', {}).items():
            if logger_name.startswith('iot_'):
                logger = logging.getLogger(logger_name)
                for handler_name, handler_config in handler_configs.items():
                    if handler_name == 'console':
                        handler = logging.StreamHandler()
                        handler.setLevel(handler_config['level'])
                        formatter = logging.Formatter(handler_config['format'])
                        handler.setFormatter(formatter)
                        logger.addHandler(handler)
                    elif handler_name == 'file':
                        handler = logging.FileHandler(handler_config['filename'])
                        handler.setLevel(handler_config['level'])
                        formatter = logging.Formatter(handler_config['format'])
                        handler.setFormatter(formatter)
                        logger.addHandler(handler)
                self.loggers[logger_name] = logger

    def log_activity(
        self,
        device_id: str,
        activity_type: str,
        details: Optional[Dict] = None,
        additional_data: Optional[Union[Dict, List, str]] = None
    ):
        """Log IoT device activity with structured data"""
        # Prepare log message
        message = {
            'device_id': device_id,
            'activity_type': activity_type,
            'timestamp': datetime.now().isoformat(),
            'details': details or {}
        }

        if additional_data:
            if isinstance(additional_data, dict):
                message['additional_data'] = additional_data
            elif isinstance(additional_data, list):
                message['additional_data'] = str(additional_data)
            else:
                message['additional_data'] = str(additional_data)

        # Log using appropriate logger
        logger_name = f'iot_activity_{device_id}'
        if logger_name not in self.loggers:
            logger = logging.getLogger(logger_name)
            logger.setLevel(logging.DEBUG)
            self.loggers[logger_name] = logger

        # Log the message
        logger.info(message)

        # Save to SQLite database
        self._save_to_db(device_id, activity_type, message)

    def _save_to_db(self, device_id: str, activity_type: str, log_data: Dict):
        """Save log data to SQLite database"""
        db_path = Path(self.config['database']['path']) if 'database' in self.config else 'iot_logs.db'

        try:
            conn = sqlite3.connect(str(db_path))
            cursor = conn.cursor()

            # Create table if it doesn't exist
            cursor.execute('''
                CREATE TABLE IF NOT EXISTS device_logs (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    device_id TEXT NOT NULL,
                    activity_type TEXT NOT NULL,
                    timestamp TEXT NOT NULL,
                    details JSON,
                    additional_data TEXT
                )
            ''')

            # Insert log data
            details_json = json.dumps(log_data.get('details', {}))
            cursor.execute('''
                INSERT INTO device_logs (
                    device_id, activity_type, timestamp, details, additional_data
                ) VALUES (?, ?, ?, ?, ?)
            ''', (
                device_id,
                activity_type,
                log_data['timestamp'],
                details_json,
                json.dumps(log_data.get('additional_data', ''))
            ))

            conn.commit()
            conn.close()

        except sqlite3.Error as e:
            logging.error(f"Database error: {str(e)}")

