import time
import json
import smtplib
from datetime import datetime

# Configuration
THRESHOLDS = {
    'temperature': {'min': 20, 'max': 30},
    'humidity': {'min': 30, 'max': 70},
    'pressure': {'min': 950, 'max': 1050},
}

DEVICES = {
    'device1': {'name': 'Temperature Sensor', 'location': 'Kitchen'},
    'device2': {'name': 'Humidity Sensor', 'location': 'Bedroom'},
    'device3': {'name': 'Pressure Sensor', 'location': 'Living Room'},
}

EMAIL_CONFIG = {
    'sender': 'health-monitor@example.com',
    'receiver': 'admin@example.com',
    'password': 'your_email_password',  # Replace with your email password
}

def get_device_data():
    """Simulate fetching data from IoT devices."""
    data = {}
    for device_id, details in DEVICES.items():
        data[device_id] = {
            'name': details['name'],
            'location': details['location'],
            'temperature': 25 + 5 * (device_id[-1] == '1'),  # Simulate data based on device ID
            'humidity': 50 + 10 * (device_id[-1] == '2'),
            'pressure': 1000 + 10 * (device_id[-1] == '3'),
        }
    return data

def check_health(data):
    """Check device health against thresholds and return issues."""
    issues = []
    for device_id, values in data.items():
        for sensor, params in THRESHOLDS.items():
            value = values[sensor]
            if value < params['min'] or value > params['max']:
                issue = {
                    'device': values['name'],
                    'location': values['location'],
                    'sensor': sensor,
                    'value': value,
                    'threshold': params,
                    'timestamp': datetime.now().isoformat()
                }
                issues.append(issue)
    return issues

def send_alert(issue):
    """Send email alert for detected issues."""
    message = f"""Subject: IoT Device Alert - {issue['sensor']} Issue Detected

A {issue['sensor']} issue was detected on device '{issue['device']}' at {issue['location']}.
Value: {issue['value']}
Thresholds: {issue['threshold']}
Timestamp: {issue['timestamp']}
"""
    try:
        with smtplib.SMTP('smtp.example.com', 587) as server:  # Use your SMTP server
            server.starttls()
            server.login(EMAIL_CONFIG['sender'], EMAIL_CONFIG['password'])
            server.sendmail(
                EMAIL_CONFIG['sender'],
                EMAIL_CONFIG['receiver'],
                message
            )
        print("Alert email sent successfully.")
    except Exception as e:
        print(f"Failed to send email: {e}")

def main():
    """Main monitoring loop."""
    while True:
        device_data = get_device_data()
        issues = check_health(device_data)
        if issues:
            print(f"Detected {len(issues)} issues:")
            for issue in issues:
                print(issue)
                send_alert(issue)  # Uncomment to enable email alerts
        else:
            print("All devices are operating normally.")
        time.sleep(60)  # Check every 60 seconds

if __name__ == "__main__":
    main()

class SensorDataProcessor:
    def __init__(self):
        self.results = []

    def process_sensor_data(self, sensor_type, data):
        """
        Process sensor data based on sensor type.
        :param sensor_type: Type of sensor (e.g., 'temperature', 'humidity')
        :param data: Raw sensor data
        :return: Processed data or error message
        """
        try:
            if sensor_type == 'temperature':
                return self._process_temperature(data)
            elif sensor_type == 'humidity':
                return self._process_humidity(data)
            else:
                raise ValueError(f"Unsupported sensor type: {sensor_type}")
        except Exception as e:
            return f"Error processing {sensor_type} data: {str(e)}"

    def _process_temperature(self, data):
        """
        Process temperature data: convert from Celsius to Fahrenheit if needed.
        :param data: Temperature in Celsius
        :return: Temperature in Fahrenheit or Celsius
        """
        try:
            celsius = float(data)
            fahrenheit = (celsius * 9/5) + 32
            return f"Temperature: {celsius}°C ({fahrenheit}°F)"
        except ValueError:
            return "Invalid temperature data"

    def _process_humidity(self, data):
        """
        Process humidity data: validate percentage and provide comfort level.
        :param data: Humidity percentage
        :return: Processed humidity data with comfort level
        """
        try:
            humidity = float(data)
            if humidity < 0 or humidity > 100:
                return "Invalid humidity value (must be between 0 and 100)"
            comfort_level = 'Low' if humidity < 40 else 'Moderate' if humidity < 70 else 'High'
            return f"Humidity: {humidity}% (Comfort: {comfort_level})"
        except ValueError:
            return "Invalid humidity data"

    def store_results(self, filename):
        """
        Save processed results to a CSV file.
        :param filename: Output file name
        """
        with open(filename, 'w') as file:
            file.write("Sensor Type,Raw Data,Processed Data\n")
            for result in self.results:
                file.write(f"{result.sensor_type},{result.raw_data},{result.processed_data}\n")

