import time
from datetime import datetime, timedelta

# Dictionary to store request counts and timestamps for each device
request_trackers = {}

def rate_limiter(max_requests_per_minute=10):
    """
    Decorator function to enforce rate limiting on IoT device requests.

    Args:
        max_requests_per_minute: Maximum number of requests allowed per minute (default: 10)
    """
    def decorator(func):
        def wrapper(device_id, *args, **kwargs):
            # Check if device_id exists in the tracker
            current_time = datetime.now()
            if device_id not in request_trackers:
                request_trackers[device_id] = {
                    'count': 0,
                    'last_request': None
                }

            tracker = request_trackers[device_id]

            # If it's the first request, set the last_request to now
            if tracker['last_request'] is None:
                tracker['last_request'] = current_time
                tracker['count'] = 1
                return func(device_id, *args, **kwargs)

            # Calculate time difference from the last request
            time_diff = current_time - tracker['last_request']

            # Reset the count if more than one minute has passed
            if time_diff > timedelta(minutes=1):
                tracker['count'] = 1
                tracker['last_request'] = current_time

            # Check if the request count exceeds the limit
            if tracker['count'] >= max_requests_per_minute:
                return "Rate limit exceeded. Please try again in a few minutes."

            # Update the tracker and proceed with the request
            tracker['count'] += 1
            tracker['last_request'] = current_time
            return func(device_id, *args, **kwargs)

        return wrapper

    return decorator

import argparse

class File:
    def __init__(self, file_id, filename, owner, permissions=None):
        self.file_id = file_id
        self.filename = filename
        self.owner = owner
        self.permissions = permissions if permissions else {'read': [], 'write': [], 'execute': []}

    def add_permission(self, permission_type, user):
        if permission_type in self.permissions:
            if user not in self.permissions[permission_type]:
                self.permissions[permission_type].append(user)

    def remove_permission(self, permission_type, user):
        if permission_type in self.permissions:
            if user in self.permissions[permission_type]:
                self.permissions[permission_type].remove(user)

    def __str__(self):
        return (f"File ID: {self.file_id}\n"
                f"Filename: {self.filename}\n"
                f"Owner: {self.owner}\n"
                f"Permissions: {self.permissions}")

class AccessManager:
    def __init__(self):
        self.files = {}

    def create_file(self, file_id, filename, owner, permissions=None):
        if file_id in self.files:
            raise ValueError(f"File with ID {file_id} already exists.")
        new_file = File(file_id, filename, owner, permissions)
        self.files[file_id] = new_file
        return new_file

    def update_permission(self, file_id, permission_type, user, action):
        if file_id not in self.files:
            raise ValueError(f"File with ID {file_id} not found.")
        file = self.files[file_id]
        if action == 'add':
            file.add_permission(permission_type, user)
        elif action == 'remove':
            file.remove_permission(permission_type, user)
        else:
            raise ValueError("Action must be 'add' or 'remove'.")

    def list_files(self):
        return list(self.files.values())

    def list_permissions(self, file_id):
        if file_id not in self.files:
            raise ValueError(f"File with ID {file_id} not found.")
        return self.files[file_id].permissions

def main():
    parser = argparse.ArgumentParser(description="Cloud File Access Permissions Manager")
    subparsers = parser.add_subparsers(dest='command', help='Available commands')

    # Create command
    create_parser = subparsers.add_parser('create', help='Create a new file')
    create_parser.add_argument('--id', required=True, help='File ID')
    create_parser.add_argument('--name', required=True, help='Filename')
    create_parser.add_argument('--owner', required=True, help='Owner username')
    create_parser.add_argument('--read', nargs='+', help='Users with read access')
    create_parser.add_argument('--write', nargs='+', help='Users with write access')
    create_parser.add_argument('--execute', nargs='+', help='Users with execute access')
    create_parser.set_defaults(func='create')

    # Update permission command
    update_parser = subparsers.add_parser('update', help='Update file permissions')
    update_parser.add_argument('--id', required=True, help='File ID')
    update_parser.add_argument('--user', required=True, help='Username')
    update_parser.add_argument('--permission', choices=['read', 'write', 'execute'], required=True)
    update_parser.add_argument('--action', choices=['add', 'remove'], required=True)
    update_parser.set_defaults(func='update')

    # List files command
    list_parser = subparsers.add_parser('list', help='List all files')
    list_parser.set_defaults(func='list')

    # List permissions command
    permissions_parser = subparsers.add_parser('permissions', help='List permissions for a file')
    permissions_parser.add_argument('--id', required=True, help='File ID')
    permissions_parser.set_defaults(func='permissions')

    args = parser.parse_args()

    manager = AccessManager()

    if hasattr(args, 'func'):
        command = getattr(args, 'func')
        if command == 'create':
            try:
                permissions = {}
                if args.read:
                    permissions['read'] = args.read
                if args.write:
                    permissions['write'] = args.write
                if args.execute:
                    permissions['execute'] = args.execute
                manager.create_file(args.id, args.name, args.owner, permissions)
                print(f"File {args.name} created successfully.")
            except ValueError as e:
                print(e)

        elif command == 'update':
            try:
                manager.update_permission(args.id, args.permission, args.user, args.action)
                action = 'added' if args.action == 'add' else 'removed'
                print(f"User {args.user} {action}ed {args.permission} permission for file {args.id}.")
            except ValueError as e:
                print(e)

        elif command == 'list':
            files = manager.list_files()
            if not files:
                print("No files found.")
            else:
                for file in files:
                    print(str(file))

        elif command == 'permissions':
            try:
                permissions = manager.list_permissions(args.id)
                print(f"Permissions for file {args.id}:")
                for perm_type, users in permissions.items():
                    print(f"{perm_type.capitalize()}: {', '.join(users) if users else 'None'}")
            except ValueError as e:
                print(e)
    else:
        parser.print_help()

if __name__ == '__main__':
    main()

