import graphene

# Define Enum Type
class Genre(graphene.Enum):
    FANTASY = 'Fantasy'
    SCI_FI = 'Science Fiction'
    MYSTERY = 'Mystery'
    THRILLER = 'Thriller'
    ROMANCE = 'Romance'

# Define Object Types
class BookType(graphene.ObjectType):
    id = graphene.ID()
    title = graphene.String()
    author = graphene.String()
    publishedYear = graphene.Int()
    genre = graphene.Field(Genre)

class AuthorType(graphene.ObjectType):
    id = graphene.ID()
    name = graphene.String()
    books = graphene.List(graphene.String)

# Define Input Object Type
class BookInput(graphene.InputObjectType):
    title = graphene.String(required=True)
    author = graphene.String(required=True)
    publishedYear = graphene.Int(required=True)
    genre = graphene.Field(Genre, default_value=Genre.FANTASY)

# Define Query Types
class Query(graphene.ObjectType):
    books = graphene.List(BookType)
    author = graphene.Field(AuthorType, id=graphene.ID())

    def resolve_books(self, info):
        # Sample data - replace with your data source
        return [
            BookType(id='1', title='The Hobbit', author='J.R.R. Tolkien', publishedYear=1937, genre=Genre.FANTASY),
            BookType(id='2', title='Dune', author='Frank Herbert', publishedYear=1965, genre=Genre.SCI_FI)
        ]

    def resolve_author(self, info, id):
        # Sample data - replace with your data source
        book_data = {
            '1': BookType(id='1', title='The Hobbit', author='J.R.R. Tolkien', publishedYear=1937, genre=Genre.FANTASY),
            '2': BookType(id='2', title='Dune', author='Frank Herbert', publishedYear=1961, genre=Genre.SCI_FI)
        }
        return AuthorType(id=id, name='J.R.R. Tolkien', books=[book['title'] for book in book_data.values()])

# Define Mutation
class CreateBook(graphene.Mutation):
    book = graphene.Field(BookType)

    class Arguments:
        input = BookInput(required=True)

    def mutate(self, input):
        # Here you would typically save to a database
        new_book = BookType(
            id='3',
            title=input.title,
            author=input.author,
            publishedYear=input.publishedYear,
            genre=input.genre
        )
        return CreateBook(book=new_book)

class Mutation(graphene.ObjectType):
    create_book = CreateBook.Field()

# Create Schema
schema = graphene.Schema(query=Query, mutation=Mutation)

# Example usage
if __name__ == '__main__':
    query = '''
    query {
        books {
            id
            title
            author
            publishedYear
            genre
        }
        author(id: "1") {
            id
            name
            books
        }
    }
    '''
    result = schema.execute(query)
    print(result.data)

    mutation = '''
    mutation {
        createBook(input: {title: "Foundation", author: "Isaac Asimov", publishedYear: 1951, genre: SCI_FI}) {
            book {
                id
                title
                author
                publishedYear
                genre
            }
        }
    }
    '''
    result = schema.execute(mutation)
    print(result.data)

import logging
import sys

# Configure logging to output to the console
logging.basicConfig(level=logging.INFO, stream=sys.stdout)
logger = logging.getLogger('graphql_queries')

# Define the middleware to log queries
class QueryLoggingMiddleware:
    def resolve(self, next, root, info, **args):
        query = args.get('query') or info.operation.query
        if query:
            logger.info(f"Executing GraphQL Query: {query[:100]}..." if len(query) > 100 else f"Executing GraphQL Query: {query}")
        return next(root, info, **args)

# Example GraphQL schema and query resolver
import graphene

class Query(graphene.ObjectType):
    hello = graphene.String()

    def resolve_hello(self, info):
        return "world"

schema = graphene.Schema(query=Query, middleware=[QueryLoggingMiddleware()])

# Example GraphQL query execution
if __name__ == '__main__':
    query = '''
        query {
            hello
        }
    '''
    result = schema.execute(query)
    print(result.data)

import sqlite3
import os
from datetime import datetime

# Database setup
DB_FILE = 'offline_storage.db'

def create_connection():
    """Create a database connection to the SQLite database."""
    conn = None
    try:
        conn = sqlite3.connect(DB_FILE)
        return conn
    except sqlite3.Error as e:
        print(f"Error connecting to database: {e}")
    return conn

def initialize_database():
    """Create the 'users' table if it doesn't exist."""
    conn = create_connection()
    if conn is not None:
        try:
            cursor = conn.cursor()
            cursor.execute('''
                CREATE TABLE IF NOT EXISTS users (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL,
                    email TEXT UNIQUE NOT NULL,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                )
            ''')
            conn.commit()
        except sqlite3.Error as e:
            print(f"Database error: {e}")
        finally:
            conn.close()

def add_user(name, email):
    """Insert a new user into the database."""
    conn = create_connection()
    if conn is not None:
        try:
            cursor = conn.cursor()
            cursor.execute(
                'INSERT INTO users (name, email) VALUES (?, ?)',
                (name, email)
            )
            conn.commit()
            print(f"User {name} added successfully.")
        except sqlite3.IntegrityError:
            print(f"Error: Email {email} already exists.")
        except sqlite3.Error as e:
            print(f"Database error: {e}")
        finally:
            conn.close()

def get_all_users():
    """Retrieve all users from the database."""
    conn = create_connection()
    users = []
    if conn is not None:
        try:
            cursor = conn.cursor()
            cursor.execute('SELECT * FROM users')
            rows = cursor.fetchall()
            for row in rows:
                users.append({
                    'id': row[0],
                    'name': row[1],
                    'email': row[2],
                    'created_at': row[3]
                })
        except sqlite3.Error as e:
            print(f"Database error: {e}")
        finally:
            conn.close()
    return users

def get_user_by_email(email):
    """Retrieve a user by email."""
    conn = create_connection()
    user = None
    if conn is not None:
        try:
            cursor = conn.cursor()
            cursor.execute(
                'SELECT * FROM users WHERE email = ?',
                (email,)
            )
            row = cursor.fetchone()
            if row:
                user = {
                    'id': row[0],
                    'name': row[1],
                    'email': row[2],
                    'created_at': row[3]
                }
        except sqlite3.Error as e:
            print(f"Database error: {e}")
        finally:
            conn.close()
    return user

def update_user_email(user_id, new_email):
    """Update a user's email."""
    conn = create_connection()
    if conn is not None:
        try:
            cursor = conn.cursor()
            cursor.execute(
                'UPDATE users SET email = ? WHERE id = ?',
                (new_email, user_id)
            )
            conn.commit()
            print(f"User {user_id}'s email updated to {new_email}.")
        except sqlite3.Error as e:
            print(f"Database error: {e}")
        finally:
            conn.close()

def delete_user(user_id):
    """Delete a user from the database."""
    conn = create_connection()
    if conn is not None:
        try:
            cursor = conn.cursor()
            cursor.execute('DELETE FROM users WHERE id = ?', (user_id,))
            conn.commit()
            print(f"User {user_id} deleted.")
        except sqlite3.Error as e:
            print(f"Database error: {e}")
        finally:
            conn.close()

def main():
    """Main function to demonstrate offline data storage."""
    initialize_database()

    while True:
        print("\n--- Offline Data Storage System ---")
        print("1. Add User")
        print("2. View All Users")
        print("3. View User by Email")
        print("4. Update User Email")
        print("5. Delete User")
        print("6. Exit")

        choice = input("Enter your choice (1-6): ").strip()

        if choice == '1':
            name = input("Enter name: ").strip()
            email = input("Enter email: ").strip()
            add_user(name, email)
        elif choice == '2':
            users = get_all_users()
            print("\nAll Users:")
            for user in users:
                print(f"ID: {user['id']}, Name: {user['name']}, Email: {user['email']}, "
                      f"Created: {user['created_at']}")
        elif choice == '3':
            email = input("Enter email to search: ").strip()
            user = get_user_by_email(email)
            if user:
                print(f"\nUser found: ID={user['id']}, Name={user['name']}, "
                      f"Email={user['email']}, Created: {user['created_at']}")
            else:
                print(f"\nNo user found with email {email}.")
        elif choice == '4':
            user_id = input("Enter user ID: ").strip()
            new_email = input("Enter new email: ").strip()
            update_user_email(int(user_id), new_email)
        elif choice == '5':
            user_id = input("Enter user ID to delete: ").strip()
            delete_user(int(user_id))
        elif choice == '6':
            print("Exiting...")
            break
        else:
            print("Invalid choice. Please enter a number between 1 and 6.")

if __name__ == "__main__":
    main()

from flask import Flask, request, jsonify
from flask_limiter import Limiter
from flask_limiter.util import ReturnMiddleware
from functools import wraps
import jwt
import datetime
import os

app = Flask(__name__)

# Load API key securely (e.g., from environment variable or config)
API_KEY = os.getenv('API_KEY', 'your-api-key-here')  # Replace with secure method

# Initialize rate limiter
limiter = Limiter(app, key_func=lambda: "login", per_item=False)
limiter.add_rate_limit("login", 5, "1 minute", ReturnMiddleware())

def token_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization')
        if not token:
            return jsonify({'message': 'Token is missing!'}), 401
        try:
            data = jwt.decode(token, API_KEY, algorithms=["HS256"])
        except jwt.ExpiredSignatureError:
            return jsonify({'message': 'Token has expired!'}), 401
        except jwt.InvalidTokenError:
            return jsonify({'message': 'Invalid token!'}), 401
        return f(*args, **kwargs)
    return decorated

@app.route('/login', methods=['POST'])
@limiter.limit("5 per minute")
def login():
    data = request.get_json()
    if not data or 'api_key' not in data:
        return jsonify({'message': 'Missing API key'}), 400
    if data['api_key'] != API_KEY:
        return jsonify({'message': 'Unauthorized'}), 401
    # Generate JWT token
    token = jwt.encode({
        'user': 'mobile_client',
        'exp': datetime.datetime.utcnow() + datetime.timedelta(minutes=30)
    }, API_KEY)
    return jsonify({'token': token.decode('UTF-8')}), 200

@app.route('/protected', methods=['GET'])
@token_required
def protected():
    return jsonify({'message': 'Successfully authenticated!'})

if __name__ == '__main__':
    app.run(ssl_context='adhoc')  # Run with HTTPS for security

class EventQueue:
    def __init__(self):
        self._events = []

    def add_event(self, event):
        """Add an event to the queue."""
        self._events.append(event)

    def process_events(self, handler):
        """Process all events in the queue using the provided handler."""
        while self._events:
            event = self._events.pop(0)
            handler(event)

    def clear(self):
        """Clear all events from the queue."""
        self._events = []

    def __len__(self):
        """Return the number of events in the queue."""
        return len(self._events)

# Example usage:
if __name__ == "__main__":
    # Create an event queue
    queue = EventQueue()

    # Define event handlers
    def handle_click(event):
        print(f"Mouse click at position: {event['position']}")

    def handle_keypress(event):
        print(f"Key pressed: {event['key']}, Modifiers: {event['modifiers']}")

    # Add events to the queue
    queue.add_event({'type': 'mouse_click', 'position': (100, 200)})
    queue.add_event({'type': 'key_press', 'key': 'A', 'modifiers': ['shift']})

    # Process events
    queue.process_events(handle_click)
    queue.process_events(handle_keypress)

    # Clear the queue
    queue.clear()
    print(f"Queue size after clearing: {len(queue)}")

