import secrets
import time
import logging

def retry_event_processing(max_retries=3, initial_delay=1, max_delay=60):
    def decorator(func):
        def wrapper(*args, **kwargs):
            delay = initial_delay
            for _ in range(max_retries):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    logging.error(f"Retry failed: {e}, attempt {_ + 1} of {max_retries}")
                    if _ == max_retries - 1:
                        raise e  # Last attempt, re-raise the exception
                    delay = min(delay * 2, max_delay)  # Exponential backoff with max delay
                    time.sleep(delay)
        return wrapper
    return decorator

# Example usage
@retry_event_processing(max_retries=5, initial_delay=1, max_delay=30)
def process_event():
    if secrets.SystemRandom().random() < 0.3:  # 30% chance of failure using secure random
        raise Exception("Temporary failure")
    logging.info("Event processed successfully")

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    process_event()

class EventProcessor:
    def __init__(self):
        self.seen_events = set()

    def process_event(self, event):
        # Extract a unique identifier from the event (e.g., event_id)
        event_id = event.get('id')  # Adjust based on your event structure

        if event_id in self.seen_events:
            print(f"Duplicate event detected with ID: {event_id}. Skipping...")
            return False  # Event not processed
        else:
            self.seen_events.add(event_id)
            # Process the event (customize this part based on your requirements)
            print(f"Processing event with ID: {event_id}")
            return True  # Event processed successfully

# Example usage
if __name__ == "__main__":
