    # Simulate incoming events (replace with actual event sources)
    events = [
        {'id': 1, 'data': 'Event 1'},
        {'id': 2, 'data': 'Event 2'},
        {'id': 1, 'data': 'Another Event 1'},  # Duplicate
        {'id': 3, 'data': 'Event 3'},
    ]

    for event in events:
        processor.process_event(event)

