class ResourceManager:
    def __init__(self):
        self.usage = {}
        self.limits = {}

    def set_limit(self, tenant_id, resource, limit):
        """Set resource limit for a tenant."""
        if tenant_id not in self.limits:
            self.limits[tenant_id] = {}
        self.limits[tenant_id][resource] = limit

    def report_usage(self, tenant_id, resource, usage):
        """Report resource usage and check against limits."""
        if tenant_id not in self.usage:
            self.usage[tenant_id] = {}
        self.usage[tenant_id][resource] = usage

        limit = self.limits.get(tenant_id, {}).get(resource, float('inf'))
        if usage > limit:
            self._enforce_limit(tenant_id, resource, usage, limit)

    def _enforce_limit(self, tenant_id, resource, usage, limit):
        """Enforce the resource limit when exceeded."""
        action_taken = False
        if resource == 'cpu':
            action_taken = self._handle_cpu_limit(tenant_id, usage)
        elif resource == 'memory':
            action_taken = self._handle_memory_limit(tenant_id, usage)
        # Add other resource handling here

        if action_taken:
            print(f"Tenant {tenant_id} exceeded {resource} limit! Usage: {usage}, Limit: {limit}")

    def _handle_cpu_limit(self, tenant_id, usage):
        """Handle CPU limit violation."""
        # Reduce CPU allocation for the tenant
        print(f"Reducing CPU allocation for tenant {tenant_id}")
        return True

    def _handle_memory_limit(self, tenant_id, usage):
        """Handle memory limit violation."""
        # Free up memory for the tenant
        print(f"Freeing up memory for tenant {tenant_id}")
        return True

def main():
    # Initialize resource manager
    resource_manager = ResourceManager()

    # Define tenant limits
    resource_manager.set_limit('tenant1', 'cpu', 50)
    resource_manager.set_limit('tenant1', 'memory', 1024)
    resource_manager.set_limit('tenant2', 'cpu', 75)
    resource_manager.set_limit('tenant2', 'memory', 2048)

    # Report usage and enforce limits
    resource_manager.report_usage('tenant1', 'cpu', 60)  # Should trigger limit
    resource_manager.report_usage('tenant1', 'memory', 2048)  # Should trigger limit
    resource_manager.report_usage('tenant2', 'cpu', 40)  # Should not trigger
    resource_manager.report_usage('tenant2', 'memory', 1024)  # Should not trigger

if __name__ == "__main__":
    main()

import re
from typing import Any, Dict, List, Optional

def validate_tenant_config(config: Dict[str, Any]) -> Dict[str, List[str]]:
    errors: Dict[str, List[str]] = {
        'required_missing': [],
        'email_invalid': [],
        'data_type_error': []
    }

    # Check for required fields
    required_fields = ['tenant_id', 'name', 'email', 'plan', 'billing_cycle']
    for field in required_fields:
        if field not in config:
            errors['required_missing'].append(field)

    # Validate email format
    email_regex = r'^[\w\.-]+@[\w\.-]+\.\w+$'
    if 'email' in config and not re.match(email_regex, config['email']):
        errors['email_invalid'].append(config['email'])

    # Check data types
    type_checks = [
        ('tenant_id', str),
        ('name', str),
        ('email', str),
        ('plan', str),
        ('billing_cycle', int)
    ]
    for field, expected_type in type_checks:
        if field in config and not isinstance(config[field], expected_type):
            errors['data_type_error'].append(f"{field}: {type(config[field])}")

    return errors

# Example usage
if __name__ == "__main__":
    tenant_config = {
        'tenant_id': '12345',
        'name': 'John Doe',
        # 'email': 'invalid-email',  # Uncomment to test invalid email
        'plan': 'enterprise',
        'billing_cycle': 1
    }

    validation_errors = validate_tenant_config(tenant_config)
    if validation_errors:
        print("Validation Errors:")
        for error_type, error_list in validation_errors.items():
            print(f"{error_type}: {', '.join(error_list)}")
    else:
        print("Tenant configuration is valid.")

import time
import logging
from functools import wraps

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

def retry(max_retries=3, backoff=1.0, initial_delay=0.0):
    """
    Decorator to retry function calls with exponential backoff.

    :param max_retries: Maximum number of retry attempts (default: 3)
    :param backoff: Multiplier for the delay between retries (default: 2.0)
    :param initial_delay: Initial delay before the first retry (default: 0.0)
    """
    def decorator_retry(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            attempts = 0
            delay = initial_delay
            while attempts < max_retries:
                attempts += 1
                logger.info(f"Attempt {attempts} of {max_retries} for message {args[0]}")
                try:
                    result = func(*args, **kwargs)
                    if result is not None:
                        logger.info(f"Message {args[0]} processed successfully.")
                        return result
                    time.sleep(delay)
                    delay *= backoff
                except Exception as e:
                    logger.error(f"Message {args[0]} processing failed: {str(e)}")
                    if attempts == max_retries:
                        logger.error(f"Failed to process message {args[0]} after {max_retries} attempts.")
                        raise
                    time.sleep(delay)
                    delay *= backoff
            return result
        return wrapper
    return decorator_retry

# Example usage
@retry(max_retries=5, backoff=2.0, initial_delay=0.1)
def process_message(message_id):
    """
    Simulate message processing. Fails if message_id is 2 or 4.
    """
    if message_id in [2, 4]:
        raise Exception(f"Failed to process message {message_id}")
    elif message_id == 5:
        return None
    else:
        return f"Processed {message_id} successfully"

if __name__ == "__main__":
    # Test cases
    messages = [1, 2, 3, 4, 5, 6]
    for msg_id in messages:
        try:
            process_message(msg_id)
        except Exception as e:
            print(e)

import heapq

class PriorityQueue:
    def __init__(self):
        self.heap = []
        self.counter = 0  # To track insertion order for tie-breaking

    def enqueue(self, item, priority):
        self.counter += 1
        heapq.heappush(self.heap, (priority, self.counter, item))

    def dequeue(self):
        priority, counter, item = heapq.heappop(self.heap)
        return item

    def peek(self):
        if not self.heap:
            return None
        return self.heap[0][2]

    def is_empty(self):
        return len(self.heap) == 0

    def size(self):
        return len(self.heap)

# Example usage
if __name__ == "__main__":
    pq = PriorityQueue()
    pq.enqueue("Task 1", 3)
    pq.enqueue("Task 2", 1)
    pq.enqueue("Task 3", 2)
    pq.enqueue("Task 4", 1)

    print("Dequeued:", pq.dequeue())  # Task 2 (priority 1, earliest)
    print("Dequeued:", pq.dequeue())  # Task 4 (priority 1, next)
    print("Dequeued:", pq.dequeue())  # Task 3 (priority 2)
    print("Dequeued:", pq.dequeue())  # Task 1 (priority 3)

def generate_report(data, headers=None):
    """
    Generates a tabular report from data. If headers are not provided, attempts to extract them from the first row.

    Args:
        data (list): List of rows, each row is a dictionary or list.
        headers (list, optional): List of header names. If None, extract from data.
    """
    if not data:
        print("No data provided.")
        return

    # Determine if headers are provided or need extraction
    if headers is None:
        # Check if the first element is a dictionary
        if isinstance(data[0], dict):
            headers = list(data[0].keys())
        else:
            # Assume first element is a list and use it as headers
            headers = data[0]
            # Ensure headers are strings
            headers = [str(header) for header in headers]
    else:
        # Ensure headers are strings
        headers = [str(header) for header in headers]

    # Validate headers exist in the data
    if isinstance(data[0], dict):
        for header in headers:
            if header not in data[0]:
                print(f"Warning: Header '{header}' not found in the first row.")
                return
    else:
        for header in headers:
            if len(headers) > len(data[0]) or header not in [str(item) for item in data[0]]:
                print(f"Warning: Header '{header}' not found in the first row.")
                return

    # Prepare formatted data rows
    formatted_data = []
    for row in data:
        if isinstance(row, dict):
            formatted_row = [row.get(header, '') for header in headers]
        else:
            formatted_row = [row[i] if i < len(row) else '' for i in range(len(headers))]
        formatted_data.append(formatted_row)

    # Generate the table
    print("\n" + "=" * 80)
    print(f"| {' | '.join(headers)} |")
    print("=" * 80)
    for row in formatted_data:
        print(f"| {' | '.join(row)} |")
    print("=" * 80 + "\n")

# Example usage
if __name__ == "__main__":
    # Example 1: Data with headers provided
    data1 = [
        {'name': 'Alice', 'age': 30, 'city': 'New York'},
        {'name': 'Bob', 'age': 25, 'city': 'Chicago'},
        {'name': 'Charlie', 'age': 35, 'city': 'Los Angeles'}
    ]
    generate_report(data1, headers=['name', 'age'])

    # Example 2: Data with headers extracted from the first row
    data2 = [
        ['Product', 'Quantity', 'Price'],
        ['Widget A', 10, 5.99],
        ['Widget B', 5, 9.99],
        ['Widget C', 20, 4.99]
    ]
    generate_report(data2)

    # Example 3: Mixed data types
    data3 = [
        {'name': 'David', 'age': 40, 'city': 'San Francisco'},
        ['Eve', 33, 'Austin'],
        {'name': 'Frank', 'age': 29, 'city': 'Seattle'}
    ]
    generate_report(data3)

def validate_report_params(params):
    schema = {
        "date": {
            "required": True,
            "type": "datetime-local"
        },
        "region": {
            "required": True,
            "allowed": ["US", "CA", "UK", "DE"]
        },
        "format": {
            "required": False,
            "allowed": ["pdf", "csv", "excel"],
            "type": "string"
        },
        "min_value": {
            "required": False,
            "type": "number",
            "coerce": float
        },
        "max_value": {
            "required": False,
            "type": "number",
            "coerce": float
        }
    }

    errors = []

    for param, constraints in schema.items():
        if param not in params and constraints.get("required", False):
            errors.append(f"Missing required parameter: {param}")
            continue

        if param in params:
            value = params[param]
            if constraints.get("type") and not isinstance(value, constraints["type"]):
                errors.append(f"Parameter {param} must be of type {constraints['type']}")
            elif constraints.get("allowed") and value not in constraints["allowed"]:
                errors.append(f"Parameter {param} must be one of {constraints['allowed']}")
            elif constraints.get("type") and constraints.get("coerce"):
                try:
                    coerced_value = constraints["coerce"](value)
                    if not isinstance(coerced_value, constraints["type"]):
                        errors.append(f"Parameter {param} cannot be coerced to {constraints['type']}")
                except (ValueError, TypeError):
                    errors.append(f"Parameter {param} cannot be converted to {constraints['type']}")
            elif constraints.get("min_value") and not value >= constraints["min_value"]:
                errors.append(f"Parameter {param} must be at least {constraints['min_value']}")
            elif constraints.get("max_value") and not value <= constraints["max_value"]:
                errors.append(f"Parameter {param} must be at most {constraints['max_value']}")

    return len(errors) == 0, errors

import json
import datetime
import time

# Configuration
LOG_FILE = 'ai_inference.log'

class AIInferenceLogger:
    def __init__(self, model_name, input_data, additional_info=None):
        self.model_name = model_name
        self.input_data = input_data
        self.additional_info = additional_info or {}
        self.start_time = None
        self.end_time = None
        self.duration = None

    def start(self):
        self.start_time = time.time()
        return self

    def end(self, output_data):
        if self.start_time is None:
            raise ValueError("Start inference first.")
        self.end_time = time.time()
        self.duration = self.end_time - self.start_time
        self.log_entry(output_data)
        return self

    def log_entry(self, output_data):
        log_entry = {
            'timestamp': datetime.datetime.now().isoformat(),
            'model': self.model_name,
            'input': self._truncate_data(self.input_data),
            'output': self._truncate_data(output_data),
            'duration': self.duration,
            'additional_info': self.additional_info
        }
        self._write_to_log(log_entry)

    def _truncate_data(self, data):
        try:
            if isinstance(data, str):
                return data[:100] + '...' if len(data) > 100 else data
            return str(data)[:100] + '...' if len(str(data)) > 100 else str(data)
        except Exception as e:
            return f"Error serializing: {e}"

    def _write_to_log(self, entry):
        with open(LOG_FILE, 'a') as f:
            f.write(json.dumps(entry) + '\n')

# Example usage
if __name__ == "__main__":
    # Simulate an AI inference
    model = "image_classifier_v1"
    input_data = {"image": "base64_encoded_image_string_here"}
    additional_info = {"user_id": "user123", "priority": "high"}

    logger = AIInferenceLogger(model, input_data, additional_info)
    logger.start()

    # Simulate inference time (e.g., 0.5 seconds)
    time.sleep(0.5)

    output_data = {"label": "cat", "confidence": 0.95}
    logger.end(output_data)

    print("Inference logged successfully.")

from typing import Any, Dict, List, Optional, Tuple
import numpy as np
import pandas as pd
from PIL import Image

class InputValidator:
    def __init__(self):
        pass

    def validate_image(self, image: Image.Image, expected_shape: Optional[Tuple] = None, 
                       data_type: Optional[np.dtype] = None) -> Dict[str, Any]:
        """Validate image inputs."""
        if not isinstance(image, Image.Image):
            raise ValueError("Input must be a PIL Image object.")

        if expected_shape:
            if image.size != expected_shape[:2]:
                raise ValueError(f"Image dimensions must be {expected_shape[:2]}, got {image.size}.")

        if data_type:
            if image.mode != data_type.name:
                raise ValueError(f"Image mode must be {data_type.name}, got {image.mode}.")

        return {'success': True, 'message': 'Image validation passed'}

    def validate_tensor(self, tensor: np.ndarray, expected_shape: Optional[Tuple] = None, 
                        data_type: Optional[np.dtype] = None) -> Dict[str, Any]:
        """Validate tensor inputs."""
        if not isinstance(tensor, np.ndarray):
            raise ValueError("Input must be a NumPy array.")

        if expected_shape:
            if tensor.shape != expected_shape:
                raise ValueError(f"Tensor shape must be {expected_shape}, got {tensor.shape}.")

        if data_type:
            if tensor.dtype != data_type:
                raise ValueError(f"Tensor data type must be {data_type}, got {tensor.dtype}.")

        return {'success': True, 'message': 'Tensor validation passed'}

    def validate_dataframe(self, df: pd.DataFrame, 
                          required_columns: Optional[List[str]] = None, 
                          numeric_columns: Optional[List[str]] = None) -> Dict[str, Any]:
        """Validate DataFrame inputs."""
        if not isinstance(df, pd.DataFrame):
            raise ValueError("Input must be a pandas DataFrame.")

        if required_columns:
            missing_columns = [col for col in required_columns if col not in df.columns]
            if missing_columns:
                raise ValueError(f"Missing required columns: {missing_columns}")

        if numeric_columns:
            for col in numeric_columns:
                if col not in df.columns or not np.issubdtype(df[col].dtype, np.number):
                    raise ValueError(f"Column {col} must be numeric.")

        return {'success': True, ' (message': 'DataFrame validation passed'}

    def validate_text(self, text: str, 
                     min_length: Optional[int] = None, 
                     max_length: Optional[int] = None) -> Dict[str, Any]:
        """Validate text inputs."""
        if not isinstance(text, str):
            raise ValueError("Input must be a string.")

        if min_length and len(text) < min_length:
            raise ValueError(f"Text must be at least {min_length} characters long.")

        if max_length and len(text) > max_length:
            raise ValueError(f"Text must not exceed {max_length} characters.")

        return {'success': True, 'message': 'Text validation passed'}

# Example usage
if __name__ == "__main__":
    validator = InputValidator()

    # Validate an image
    try:
        image = Image.open("image.jpg")
        image.validate_image(expected_shape=(224, 224, 3), data_type=np.uint8)
        print("Image valid")
    except Exception as e:
        print(f"Image invalid: {e}")

    # Validate a tensor
    try:
        tensor = np.random.randn(32, 224, 224, 3).astype(np.float32)
        tensor.validate_tensor(expected_shape=(32, 224, 224, 3), data_type=np.float32)
        print("Tensor valid")
    except Exception as e:
        print(f"Tensor invalid: {e}")

    # Validate a DataFrame
    try:
        df = pd.DataFrame({'age': [25, 30], 'height': [165.0, 170.0]})
        df.validate_dataframe(required_columns=['age', 'height'], numeric_columns=['age', 'height'])
        print("DataFrame valid")
    except Exception as e:
        print(f"DataFrame invalid: {e}")

    # Validate text
    try:
        text = "Hello, world!"
        text.validate_text(min_length=5, max_length=50)
        print("Text valid")
    except Exception as e:
        print(f"Text invalid: {e}")

