# Twitter API Configuration
def fetch_twitter_data(api_key, api_secret, access_token, access_token_secret, screen_name):
    auth = tweepy.OAuthHandler(api_key, api_secret)
    auth.set_access_token(access_token, access_token_secret)
    api = tweepy.API(auth)

    try:
        user = api.get_user(screen_name)
        tweets = api.user_timeline(screen_name=screen_name, count=5)
        return {
            'user_data': {
                'name': user.name,
                'screen_name': user.screen_name,
                'followers': user.followers_count
            },
            'tweets': [tweet.text for tweet in tweets]
        }
    except Exception as e:
        print(f"Twitter Error: {str(e)}")
        return None

# Facebook API Configuration
def fetch_facebook_data(access_token, user_id):
    graph = facebook.GraphAPI(access_token)
    try:
        profile = graph.get_object(user_id)
        friends = graph.get_connections(user_id, 'friends')
        return {
            'profile_data': {
                'name': profile.get('name', ''),
                'id': profile.get('id', ''),
                'email': profile.get('email', ''),
                'gender': profile.get('gender', ''),
                'is_verified': profile.get('verified', False)
            },
            'friends': friends.get('summary', {}).get('total_count', 0)
        }
    except Exception as e:
        print(f"Facebook Error: {str(e)}")
        return None

