import os
import sys

def mask_sensitive_data(data, sensitive_keywords):
    """Mask sensitive data in a string using common patterns."""
    if not sensitive_keywords:
        return data
    masked = data
    for keyword in sensitive_keywords:
        if keyword in masked:
            masked = masked.replace(keyword, '*' * len(keyword))
    return masked

def list_env_vars():
    """List all environment variables with sensitive data masked."""
    sensitive_keywords = ['.env', 'password', 'secret', 'token', 'key', 'api']
    for key, value in os.environ.items():
        masked_value = mask_sensitive_data(value, sensitive_keywords)
        print(f"{key}: {masked_value}")

def get_env_var(var_name):
    """Retrieve a specific environment variable."""
    try:
        value = os.environ[var_name]
        print(f"{var_name}: {value}")
    except KeyError:
        print(f"Error: Variable '{var_name}' not found.")

def set_env_var(var_name, var_value):
    """Set an environment variable."""
    os.environ[var_name] = var_value
    print(f"Variable '{var_name}' set to: {var_value}")

def delete_env_var(var_name):
    """Delete an environment variable."""
    try:
        del os.environ[var_name]
        print(f"Variable '{var_name}' deleted.")
    except KeyError:
        print(f"Error: Variable '{var_name}' not found.")

def main():
    """Main function to handle user input and execute commands."""
    while True:
        print("\nEnvironment Variable Manager")
        print("1. List all environment variables")
        print("2. Get a specific environment variable")
        (3) print("3. Set an environment variable")
        print("4. Delete an environment variable")
        print("5. Exit")
        choice = input("Enter your choice (1-5): ").strip()

        if choice == '1':
            list_env_vars()
        elif choice == '2':
            var_name = input("Enter the environment variable name: ").strip()
            get_env_var(var_name)
        elif choice == '3':
            var_name = input("Enter the environment variable name: ").strip()
            var_value = input("Enter the value: ").strip()
            set_env_var(var_name, var_value)
        elif choice == '4':
            var_name = input("Enter the environment variable name: ").strip()
            delete_env_var(var_name)
        elif choice == '5':
            print("Exiting the program.")
            sys.exit(0)
        else:
            print("Invalid choice. Please enter a number between 1 and 5.")

if __name__ == "__main__":
    main()

