import os
import hmac
import hashlib
import requests
from flask import Flask, request, abort, jsonify
from functools import wraps
from ratelimiter import RateLimiter

app = Flask(__name__)

# Configuration
WEBHOOK_SECRET = os.environ.get('WEBHOOK_SECRET', 'fallback_secret')  # Use environment variable for security
RATE_LIMIT = 10  # Max requests per minute

def verify_signature(secret, payload, signature):
    """Verify webhook signature using HMAC-SHA256."""
    digester = hmac.digest(secret.encode('utf-8'), payload, 'SHA256')
    return hmac.compare_digest(digester, signature.encode('utf-8'))

def validate_payload(payload):
    """Validate payload structure."""
    try:
        data = request.get_json()
        required_fields = ['event_type', 'data']
        return all(field in data for field in required_fields)
    except Exception:
        return False

def webhook_endpoint(endpoint_func):
    """Decorator for webhook routes."""
    @wraps(endpoint_func)
    def decorated_function(*args, **kwargs):
        # Check signature
        if not request.headers.get('X-Signature'):
            abort(401, 'Missing signature header')

        payload = request.data
        signature = request.headers['X-Signature']

        if not verify_signature(WEBHOOK_SECRET, payload, signature):
            abort(401, 'Invalid signature')

        # Validate payload
        if not validate_payload(payload):
            abort(400, 'Invalid payload format')

        return endpoint_func(*args, **kwargs)

    return decorated_function

@RateLimiter(max_calls=RATE_LIMIT, period=60)
@app.route('/webhook', methods=['POST'])
@webhook_endpoint
def webhook_handler():
    """Example webhook handler."""
    data = request.get_json()
    # Process the webhook data
    return jsonify({'status': 'success', 'message': 'Webhook processed'}), 200

if __name__ == '__main__':
    app.run(ssl_context='adhoc')  # For testing with HTTPS

