import os
import re
import pwd
import sys
from datetime import datetime

def parse_crontab(file_path):
    """Parse the crontab file and return a list of cron jobs."""
    if not os.path.exists(file_path):
        print(f"Error: File {file_path} not found.")
        return []
    cron_jobs = []
    try:
        with open(file_path, 'r') as f:
            for line in f:
                line = line.strip()
                if line.startswith('#') or not line:
                    continue
                parts = line.split()
                if len(parts) < 6:
                    continue
                user = parts[0]
                command = ' '.join(parts[5:])
                cron_jobs.append({
                    'user': user,
                    'minute': parts[1],
                    'hour': parts[2],
                    'day': parts[3],
                    'month': parts[4],
                    'command': command
                })
    except Exception as e:
        print(f"Error reading crontab: {e}")
    return cron_jobs

def check_command_security(command):
    """Check if the command contains insecure patterns."""
    insecure_patterns = [
        r'\b(?:eval|system|os\.system)\b',
        r'\b(?:password|secret|token|key|env|\.env)\b',
        r'\b(?:\$\{|\`)(.*?)\`',
        r'\bcat|grep|sed|awk|find\b',
        r'\b--help\b'
    ]
    insecure = False
    for pattern in insecure_patterns:
        if re.search(pattern, command):
            insecure = True
            break
    return insecure

def check_user_privileges(user):
    """Check if the user has excessive privileges."""
    try:
        user_info = pwd.getpwnam(user)
        uid = user_info.pw_uid
        if uid == 0:
            return "User is root, which may be insecure if not necessary."
        return None
    except KeyError:
        return f"User {user} not found."

def check_command_path(command):
    """Check if the command relies on insecure PATH settings."""
    if ' ' in command:
        parts = command.split()
        if parts[0].startswith('/usr/bin/') or parts[0].startswith('/usr/local/bin/'):
            return None
        return f"Command {command} may use insecure PATH."
    return None

def check_sensitive_files(command):
    """Check if the command accesses sensitive files."""
    sensitive_files = [
        '/etc/passwd', '/etc/shadow', '/etc/sudoers',
        '/.bash_history', '/.git/config', '/.env'
    ]
    for file in sensitive_files:
        if file in command:
            return f"Command {command} accesses sensitive file {file}."
    return None

def analyze_crontab(file_path='/etc/crontab'):
    """Analyze the crontab file for security issues."""
    cron_jobs = parse_crontab(file_path)
    issues = []
    for job in cron_jobs:
        user_issue = check_user_privileges(job['user'])
        if user_issue:
            issues.append(user_issue)
        command_issue = check_command_security(job['command'])
        if command_issue:
            issues.append(f"Cron job command {job['command']} is insecure.")
        path_issue = check_command_path(job['command'])
        if path_issue:
            issues.append(path_issue)
        sensitive_issue = check_sensitive_files(job['command'])
        if sensitive_issue:
            issues.append(sensitive_issue)
    return issues

if __name__ == "__main__":
    file_path = '/etc/crontab'  # Default to system crontab
    if len(sys.argv) > 1:
        file_path = sys.argv[1]
    issues = analyze_crontab(file_path)
    if issues:
        print("Security Issues Found in Crontab:")
        for issue in issues:
            print(f"- {issue}")
    else:
        print("No security issues found in crontab.")

class ShoppingCart:
    def __init__(self):
        self.cart = {}

    def add_item(self, item_name, quantity=1):
        if item_name not in self.cart:
            self.cart[item_name] = {'price': 0.0, 'quantity': 0}
        self.cart[item_name]['quantity'] += quantity

    def remove_item(self, item_name, quantity=1):
        if item_name in self.cart:
            current_quantity = self.cart[item_name]['quantity']
            if current_quantity <= quantity:
                del self.cart[item_name]
            else:
                self.cart[item_name]['quantity'] -= quantity

    def update_item_price(self, item_name, new_price):
        if item_name in self.cart:
            self.cart[item_name]['price'] = new_price

    def calculate_total(self):
        total = 0
        for item in self.cart.values():
            total += item['price'] * item['quantity']
        return total

    def apply_discount(self, discount_percent=0.0):
        self.discount = discount_percent

    def calculate_total_with_discount(self):
        if hasattr(self, 'discount'):
            return self.calculate_total() * (1 - self.discount)
        return self.calculate_total()

    def display_cart(self):
        if not self.cart:
            print("Your cart is empty.")
            return
        print("Shopping Cart:")
        for item, details in self.cart.items():
            print(f"Item: {item}, Price: ${details['price']:.2f}, Quantity: {details['quantity']}")
        print(f"Total: ${self.calculate_total():.2f}")

# Example Usage
if __name__ == "__main__":
    cart = ShoppingCart()

    # Add items
    cart.add_item("Laptop", 999.99)
    cart.add_item("Mouse", 49.99, 2)

    # Update price
    cart.update_item_price("Mouse", 59.99)

    # Remove item
    cart.remove_item("Mouse", 1)

    # Display cart
    cart.display_cart()

    # Apply discount and display total
    cart.apply_discount(0.1)  # 10% discount
    print(f"Total with discount: ${cart.calculate_total_with_discount():.2f}")

def validate_coupon_code(code):
    if len(code) < 5 or len(code) > 20:
        return False
    if not code[0].isalpha():
        return False
    if not (any(c.isupper() for c in code)):
        return False
    if not (any(c.islower() for c in code)):
        return False
    if not (any(c.isdigit() for c in code)):
        return False
    if not (any(c in '@#$%&' for c in code)):
        return False
    return True

import datetime

class Order:
    def __init__(self, order_id):
        self.order_id = order_id
        self.items = []
        self.quantities = []
        self.total = 0.0
        self.discount = 0.0
        self.tax_rate = 0.08  # 8% tax rate

    def add_item(self, item_name, quantity, price):
        self.items.append(item_name)
        self.quantities.append(quantity)
        self.total += quantity * price

    def apply_discount(self, percentage):
        self.discount = self.total * (percentage / 100.0)

    def calculate_total(self):
        return self.total + (self.total * self.tax_rate) - self.discount

    def process_payment(self, payment_method):
        total = self.calculate_total()
        if payment_method == 'credit':
            return CreditCardPayment(total)
        elif payment_method == 'debit':
            return DebitCardPayment(total)
        elif payment_method == 'paypal':
            return PayPalPayment(total)
        elif payment_method == 'cash':
            return CashPayment(total)
        else:
            raise ValueError("Invalid payment method")

class PaymentMethod:
    def __init__(self, amount):
        self.amount = amount
        self.timestamp = datetime.datetime.now()

    def process(self):
        pass

class CreditCardPayment(PaymentMethod):
    def __init__(self, amount):
        super().__init__(amount)
        self.card_type = input("Enter card type (Visa/Mastercard): ").strip().lower()
        self.card_number = input("Enter card number: ").strip()

    def process(self):
        # Simulate payment processing
        print(f"Processing credit card ({self.card_type}, {self.card_number}) payment of ${self.amount:.2f}")
        return True

class DebitCardPayment(PaymentMethod):
    def __init__(self, amount):
        super().__init__(amount)
        self.card_type = input("Enter card type (Visa/Mastercard): ").strip().lower()
        self.card_number = input("Enter card number: ").strip()

    def process(self):
        print(f"Processing debit card ({self.card_type}, {self.card_number}) payment of ${self.amount:.2"2f}")
        return True

class PayPalPayment(PaymentMethod):
    def __init__(self, amount):
        super().__init__(amount)
        self.email = input("Enter PayPal email: ").strip()

    def process(self):
        print(f"Processing PayPal payment of ${self.amount:.2f} to {self.email}")
        return True

class CashPayment(PaymentMethod):
    def __init__(self, amount):
        super().__init__(amount)

    def process(self):
        amount_received = float(input("Enter amount received: $"))
        if amount_received >= self.amount:
            print(f"Processing cash payment of ${self.amount:.2f}")
            return True
        else:
            print("Insufficient amount. Payment failed.")
            return False

def main():
    print("=== Order and Payment Processing System ===")

    # Create order
    order_id = input("Enter order ID: ").strip()
    order = Order(order_id)

    # Add items to order
    while True:
        item_name = input("Enter item name (or 'done' to finish): ").strip()
        if item_name.lower() == 'done':
            break

        quantity = int(input("Enter quantity: "))
        price = float(input("Enter price per unit: $"))
        order.add_item(item_name, quantity, price)

    # Apply discount if applicable
    discount_choice = input("Apply discount? (yes/no): ").strip().lower()
    if discount_choice == 'yes':
        discount_percentage = float(input("Enter discount percentage (%): "))
        order.apply_discount(discount_percentage)

    # Process payment
    print(f"\nOrder Summary:")
    print(f"Order ID: {order_id}")
    print(f"Subtotal: ${order.total:.2f}")
    print(f"Discount: ${order.discount:.2f}")
    print(f"Tax: ${order.total * order.tax_rate:.2f}")
    print(f"Total: ${order.calculate_total():.2f}")

    payment_method = input("\nSelect payment method (credit/debit/paypal/cash): ").strip().lower()
    payment = order.process_payment(payment_method)

    if payment.process():
        print("\nPayment successful!")
        print(f"Transaction completed at {payment.timestamp.strftime('%Y-%m-%d %H:%M:%S')}")
    else:
        print("\nPayment failed. Please try again.")

if __name__ == "__main__":
    main()

class InventoryItem:
    def __init__(self, name, quantity, reorder_level):
        self.name = name
        self.quantity = quantity
        self.reorder_level = reorder_level

class InventorySystem:
    def __init__(self):
        self.items = {}

    def add_item(self, name, quantity, reorder_level):
        if name in self.items:
            print(f"Item '{name}' already exists. Use update_item to modify.")
            return False
        self.items[name] = InventoryItem(name, quantity, reorder_level)
        print(f"Added item: {name}")
        return True

    def update_item(self, name, quantity=None, reorder_level=None):
        if name not in self.items:
            print(f"Item '{name}' not found.")
            return False

        item = self.items[name]
        if quantity is not None:
            item.quantity = quantity
        if reorder_level is not None:
            item.reorder_level = reorder_level
        print(f"Updated item '{name}'")
        return True

    def check_inventory(self):
        print("\n=== Inventory Status ===")
        low_stock_items = []

        for name, item in self.items.items():
            status = "In Stock" if item.quantity >= item.reorder_level else "Low Stock"
            print(f"{name}: {item.quantity} units - {status}")

            if item.quantity < item.reorder_level:
                low_stock_items.append((name, item.quantity))

        if low_stock_items:
            print("\n--- Action Required ---")
            for name, quantity in low_stock_items:
                print(f"{name}: {quantity} units below reorder level")
        else:
            print("\nAll items are within acceptable stock levels")

    def restock_item(self, name, new_quantity):
        if name not in self.items:
            print(f"Item '{name}' not found.")
            return False

        self.items[name].quantity = new_quantity
        print(f"Restocked {name} to {new_quantity} units")
        return True

# Example usage
if __name__ == "__main__":
    inventory = InventorySystem()

    # Add items
    inventory.add_item("Laptop", 15, 10)
    inventory.add_item("Monitor", 8, 15)

    # Check inventory
    inventory.check_inventory()

    # Update item
    inventory.update_item("Monitor", reorder_level=5)

    # Check inventory again
    inventory.check_inventory()

    # Restock item
    inventory.restock_item("Monitor", 20)

    # Final check
    inventory.check_inventory()

import re

# List of supported countries and their respective postal code formats
COUNTRYPostalCodes = {
    'US': r'^\d{5}(-\d{4})?$',
    'CA': r'^[A-Za-z]\d{1,2}[A-Za-z][ \d][A-Za-z]{2}$',
    'UK': r'^[A-Z]{1,2}[0-9][A-Z]? [0-9][A-Z]{2}$'
}

# List of US states for validation
US_STATES = [
    'AL', 'AK', 'AZ', 'AR', 'CA', 'CO', 'CT', 'DE', 'FL', 'GA',
    'HI', 'ID', 'IL', 'IN', 'IA', 'KS', 'KY', 'LA', 'ME', 'MD',
    'MA', 'MI', 'MN', 'MS', 'MO', 'MT', 'NE', 'NV', 'NH', 'NJ',
    'NM', 'NY', 'NC', 'ND', 'OH', 'OK', 'OR', 'PA', 'RI', 'SC',
    'SD', 'TN', 'TX', 'UT', 'VT', 'VA', 'WA', 'WV', 'WI', 'WY'
]

def validate_address(address):
    errors = []

    # Check for required fields
    required_fields = ['street', 'city', 'state', 'postal_code', 'country']
    for field in required_fields:
        if field not in address:
            errors.append(f"Missing required field: {field}")

    # Validate street
    if not address['street']:
        errors.append("Street address must not be empty.")

    # Validate city
    if not address['city']:
        errors.append("City must not be empty.")

    # Validate state (case-insensitive)
    state = address['state'].upper()
    if not state:
        errors.append("State must not be empty.")
    elif state not in US_STATES:
        errors.append(f"Invalid state. Must be one of: {', '.join(US_STATES)}")

    # Validate country and postal code format
    country = address['country'].upper()
    if not country:
        errors.append("Country must not be empty.")
    elif country not in COUNTRYPostalCodes:
        errors.append(f"Unsupported country: {country}. Supported countries: {', '.join(COUNTRYPostalCodes.keys())}")
    else:
        postal_pattern = COUNTRYPostalCodes[country]
        if not re.match(postal_pattern, address['postal_code']):
            errors.append(f"Incorrect postal code format for {country}.")

    return errors

