import secrets
from enum import Enum

class PaymentError(Enum):
    INSUFFICIENT_FUNDS = "Insufficient funds on the card."
    CARD_EXPIRED = "Card has expired."
    INVALID_CARD = "Invalid card number."
    NETWORK_ISSUE = "Network connectivity problem with the payment gateway."
    AUTHENTICATION_FAILED = "Card authentication failed."
    GENERIC_FAILURE = "Payment processing failed due to an unknown error."

class PaymentGateway:
    def process_payment(self, card):
        try:
            card.validate()
            if not card.has_sufficient_balance():
                raise PaymentError.INSUFFICIENT_FUNDS
            if card.is_expired():
                raise PaymentError.CARD_EXPIRED
            if not card.is_valid():
                raise PaymentError.INVALID_CARD
            # Simulate network issues (50% chance)
            if self._simulate_network_failure():
                raise ConnectionError("Network connectivity issue.")
            # Simulate authentication failure (20% chance)
            if self._simulate_auth_failure():
                raise ValueError("Authentication failed.")
            return self._send_authorization_request(card)
        except Exception as e:
            raise self._handle_payment_error(e)

    def _send_authorization_request(self, card):
        # Simulate successful payment processing
        print("Payment authorized successfully!")
        return "PAYMENT_SUCCESS"

    def _handle_payment_error(self, error):
        error_type = type(error).__name__
        if error_type == 'PaymentError':
            return error.value
        elif error_type == 'ConnectionError':
            return PaymentError.NETWORK_ISSUE
        elif error_type == 'ValueError':
            return PaymentError.AUTHENTICATION_FAILED
        else:
            return PaymentError.GENERIC_FAILURE

    def _simulate_network_failure(self):
        return secrets.SystemRandom().randint(0, 1) == 1

    def _simulate_auth_failure(self):
        return secrets.SystemRandom().randint(0, 4) < 2

