import re
from datetime import datetime, timedelta

def validate_cvv(cvv):
    # Regular expression to match the CVV format
    cvv_regex = r"^(?:4[0-9]{12}(?:[0-9]{3})?|5[1-5][0-9]{14}|6(?:011|5[0-9]{2})[0-9]{12}|3[47][0-9]{13}|3(?:0[0-5]|[68][0-9])[0-9]{11})$"
    if re.match(cvv_regex, cvv):
        return True
    else:
        return False

def validate_expiration_date(date_str):
    try:
        # Parse the date string into a datetime object
        expiration_date = datetime.strptime(date_str, "%m/%d/%Y")

        # Check if the expiration date is in the future
        if expiration_date > datetime.now():
            return True
        else:
            return False

    except ValueError:
        return False

def validate_card_info(card_number, cvv, expiration_date):
    # Validate CVV
    cvv_valid = validate_cvv(cvv)

    # Validate expiration date
    expiration_valid = validate_expiration_date(expiration_date)

    if cvv_valid and expiration_valid:
        return True
    else:
        return False

