import threading

class ThreadSafeCounter(object):
    def __init__(self):
        self.lock = threading.Lock()
        self.counter = 0

    def increment(self):
        with self.lock:
            self.counter += 1

def worker(counter):
    for _ in range(100000):
        counter.increment()

counter = ThreadSafeCounter()
threads = []
for i in range(5):
    t = threading.Thread(target=worker, args=(counter,))
    threads.append(t)
    t.start()

for t in threads:
    t.join()

print('Final counter value is', counter.counter)

