import smtplib
from datetime import datetime, timedelta

class EmailFilter:
    def __init__(self):
        self.emails = {}  # Tracks last send time per IP and email

    def get_last_send(self, ip_address):
        return next((ts for ts in self.emails.values() if ts.ip == ip_address), None)

    def is_blocked(self, now, max_rate, threshold_minutes=1):
        # Calculate how many emails have been sent within the last 'threshold_minutes' minutes
        num_blocked_emails = 0

        for ts in self.emails.values():
            if (now - ts.timestamp).total_seconds() < threshold_minutes * 60:
                num_blocked_emails += 1

        return max_rate is not None and now - self.last_block > max_rate

    def send_event(self, now):
        pass

class EmailSender:
    def __init__(self, sender, password, threshold_minutes=1, max_rate=None):
        self.sender = sender
        self.password = password
        self.email_filter = EmailFilter()
        self.threshold_minutes = threshold_minutes
        self.max_rate = max_rate

        # Event listener for the last send time
        self.send_event_listener()

    def send_email(self, to, subject, message):
        if self.is_blocked():
            return False

        msg = smtplib.MimeMessage()
        msg['To'] = to
        msg['Subject'] = subject
        msg['From'] = self.sender
        msg.set_header('Content-Type', 'text/html')
        msg.set_header('Content-Disposition', f'inline; filename="test.html"')

        try:
            msg.set_header('X-Internet-Security-Antivirus', '1')
            msg.add_header('VirusTotal', 'http://www.virustotal.com/', {'virus': False})

            with smtplib.SMTP_SSL() as server:
                server.login(self.sender, self.password)
                server.sendmail(self.sender, to, msg.as_string())

        except (smtplib.error, smtplib.SMPLibError) as e:
            print(f"Failed to send email: {e}")

    def clear_cache(self):
        # Remove the cache entries if no errors were raised in 3 hours
        now = datetime.now()
        for ip_address in self.email_filter.emails:
            last_ts = self.email_filter.get_last_send(ip_address)
            if last_ts and (now - last_ts.timestamp) > timedelta(hours=3):
                del self.email_filter.emails[ip_address]

    def send_event_listener(self):
        # Event listener using the default SMTP server
        def on_send(event, sender, subject, rawtext, date, flag):
            now = datetime.fromtimestamp(int(date))

            if event == 'S' and not (flag == 24 or len(rawtext) > 0):
                # Only process delivery events
                self.email_filter.send_event(now)

        server = smtplib.SMTP('smtp.example.com', 587)  # Default SMTP server, replace with your settings
        server.startcgmanull()
        server.set_debuglevel(1)

        try:
            server全程连接并执行事件监听器
        except Exception as e:
            print(f"Error setting up event listener: {e}")

        server.quit()

