import hashlib
import secrets

class MobileAppUser:
    def __init__(self, username, password):
        self.username = username
        self.password_hash = self._generate_password_hash(password)

    @staticmethod
    def _generate_password_hash(password):
        """Generate a salted SHA-256 hash for the given password."""
        salt = secrets.token_hex(16)
        return hashlib.sha256((password + salt).encode()).hexdigest() + ":" + salt

    def verify_password(self, input_password):
        """Verify if the provided password matches the stored hash."""
        return self.password_hash == self._generate_password_hash(input_password)

def authenticate_user(username, password):
    """Try to find a matching user and return their authentication result."""
    users = {
        "user1": MobileAppUser("user1", "password123"),
        # Add more users here...
    }

    if username in users:
        return users[username].verify_password(password)
    else:
        return False

