import re

def validate_report_input_parameters(input_parameters):
    """
    Validates report input parameters.

    Args:
        input_parameters (dict): A dictionary containing the input parameters.

    Returns:
        bool: True if all input parameters are valid, False otherwise.
    """

    # Define a regular expression pattern to match date and phone number formats
    date_pattern = re.compile(r'^[0-9]{4}-[0-9]{2}-[0-9]{2}$')
    phone_number_pattern = re.compile(r'^\d{3}[- ]?\d{3}[- ]?\d{4}$')

    # Validate each input parameter
    for key, value in input_parameters.items():
        if key == 'date':
            # Check if the date is in the correct format
            if not date_pattern.match(value):
                return False
        elif key == 'phone_number':
            # Check if the phone number is in the correct format
            if not phone_number_pattern.match(value):
                return False
        elif key == 'numeric_value' or key == 'decimal_value':
            try:
                float(value)
            except ValueError:
                return False

    return True


