import socket
import time

def send_ping(socket):
    # Send a ping request to the server
    socket.sendall(b"PING")

def receive_pong(socket):
    # Receive the pong response from the server
    data = socket.recv(1024)
    if data == b"PONG":
        return True
    else:
        return False

def check_connection_health(socket):
    # Send a ping request to the server and receive the pong response
    send_ping(socket)
    time.sleep(1)
    return receive_pong(socket)

