import datetime
from abc import ABC, abstractmethod

class Payment(ABC):
    @abstractmethod
    def process(self, amount, payment_date=None):
        pass

class CreditCardPayment(Payment):
    def __init__(self, card_number, expiration_date, cvv, amount=0.0):
        self.card_number = card_number
        self.expiration_date = expiration_date
        self.cvv = cvv
        self.amount = amount

    def process(self, amount, payment_date=None):
        if not (payment_date or datetime.date.today()) < self.expiration_date:
            return f"Invalid date"

        # Simulate a payment processing
        print(f"Payment processed successfully. Amount: ${amount}")

class Subscription(Payment):
    def __init__(self, subscription_id, amount=0.0):
        self.subscription_id = subscription_id
        self.amount = amount

    def process(self, amount, payment_date=None):
        if not (payment_date or datetime.date.today()) < datetime.date.today() + datetime.timedelta(days=30):
            return f"Subscription renewal missed"

        # Simulate a recurring payment processing
        print(f"Recurring payment processed successfully. Amount: ${amount}")

class RecurringPaymentProcessor:
    def __init__(self, payments=None, subscriptions=None):
        self.payments = payments if payments else []
        self.subscriptions = subscriptions if subscriptions else []

    def add_payment(self, payment):
        self.payments.append(payment)

    def add_subscription(self, subscription):
        self.subscriptions.append(subscription)

    def process_recurring_payments(self, days=30):
        for subscription in self.subscriptions:
            subscription.process(self.get_amount(subscription.amount), datetime.date.today() + datetime.timedelta(days=days))

        for payment in self.payments:
            payment.process(payment.amount, datetime.date.today())

    def get_amount(self, amount):
        # Simulate a calculation of the recurring payment
        return round(amount * 1.10, 2)

# Example usage:

if __name__ == "__main__":
    # Create payments and subscriptions
    credit_card_payment = CreditCardPayment("1234-5678-9012-3456", datetime.date(2025, 3, 15), "123")
    subscription = Subscription("ABC123")

    # Process recurring payments
    processor = RecurringPaymentProcessor()
    processor.add_payment(credit_card_payment)
    processor.add_subscription(subscription)

    processor.process_recurring_payments()

import time
from functools import lru_cache, wraps

def expire(timeout):
    def deco(f):
        f.expiration = timeout
        return f
    return deco

def memoize(func=None, *, maxsize: int = 128):
    if func is None:
        return lambda func: memoize(func, maxsize=maxsize)

    @wraps(func)
    def wrapped(*args, **kwargs):
        cache_key = (args, frozenset(kwargs.items()))
        try:
            # Try to get from cache
            cached_result = cache[cache_key]
            # Check if the cache has expired
            if time.time() - cached_result['time'] > func.expiration:
                raise KeyError
            return cached_result['value']
        except KeyError:
            # Calculate new value and update in cache
            result = func(*args, **kwargs)
            cached_result = {'value': result, 'time': time.time()}
            cache[cache_key] = cached_result
            if len(cache) > maxsize:
                # Remove oldest item from cache when max size is reached
                del cache[next(iter(cache))]
            return result
    cache = {}
    wrapped.cache_info = lambda: {'hits': sum(v['count'] for v in cache.values()), 'misses': 0, 'maxsize': maxsize, 'currsize': len(cache)}
    wrapped.cache_clear = cache.clear
    return wrapped

# Decorator to add expiry time of 10 seconds
@expire(10)
# Decorator to memoize the function
@memoize()
def get_data(key):
    # Your data retrieval logic here, for example:
    print("Getting data from source...")
    return "Data for {}".format(key)

print(get_data('test'))  # Get data from source and cache it
time.sleep(5)
print(get_data('test'))  # Still using cached data as it's not expired yet
time.sleep(6)
print(get_data('test'))  # Getting data from source again as the cache has expired

import xml.etree.ElementTree as ET

class SerializeToXML(object):
    def __init__(self, obj):
        self.obj = obj

    def serialize_to_xml(self):
        root = ET.Element('root')

        if hasattr(self.obj, '__dict__'):
            for key, value in self.obj.__dict__.items():
                child = ET.SubElement(root, key)
                child.text = str(value)
        else:
            raise TypeError('Object of type %s is not serializable' % type(self.obj))

        return ET.tostring(root, encoding='unicode')

