from collections import deque
import hashlib

class Window:
    def __init__(self, size):
        self.size = size
        self.keys = deque()  # Keys hold references to value objects
        self.values = deque()  # Values are the objects themselves

    def add(self, key, value):
        if len(self.keys) >= self.size:
            # Remove the oldest key and its corresponding value
            oldest_key = self.keys.popleft()
            delattr(value[oldest_key], 'time')  # Remove time if it's part of the object

        # Add new key and value to the end, with a unique time stamp
        current_time = hash((key, str(uuid.uuid4())))  # Using uuid for uniqueness
        value keyed by current_time might not be necessary. Instead, we can simply add the new item.
        self.keys.append(key)
        self.values.append(value)

    def process(self):
        if len(self) == 0:
            return None

        # Process each item in constant time using SHA-256
        accumulator = hashlib.sha256()
        for value in self.values:
            # Update the accumulator with the hash of the current value, ensuring constant time
            # This is done by hashing within a context that doesn't allow early termination
            with accumulator.update() as h:
                h.update(value)

        return accumulator.digest()

    def __len__(self):
        return len(self.values)

    def same_as(self, other):
        if len(self) != len(other):
            return False

        # Compare each item's hash in constant time using SHA-256
        self_hash = self.process()
        other_hash = other.process()

        # Ensure both hashes are of the same length (same number of items)
        if len(self_hash) != len(other_hash):
            return False

        for s_hash, o_hash in zip(self_hash, other_hash):
            if s_hash != o_hash:
                return False
        return True

import threading
from datetime import datetime, timedelta

class Queue:
    def __init__(self):
        self.messages = []

    def append_message(self, msg):
        self.messages.append(msg)

class LogManager:
    def __init__(self, queue_instance):
        self.queue = queue_instance
        self.initial_time = None  # Will be set when first log entry is created

    def send_message(self, message):
        current_time = datetime.now()
        log_entry = {
            'message': message,
            'timestamp': current_time
        }
        self.queue.append(log_entry)

    def regular_log(self):
        interval = 60 * 1000  # One minute in milliseconds
        last_log_time = None

        while True:
            if not hasattr(self, 'initial_time') or self.initial_time is None:
                self.initial_time = datetime.now()

            current_time = datetime.now()
            if (current_time - self.initial_time).total_seconds() > 0:
                log_entry = {
                    'message': f'[Regular Log] - {current_time}',
                    'timestamp': current_time
                }
                self.queue.append(log_entry)

            # Start checking every minute after the first log
            if hasattr(self, 'initial_time'):
                last_log_time = self.initial_time
                while True:
                    sleep_time = (datetime.now() - last_log_time).total_seconds()
                    if sleep_time >= 1:  # Wait at least one minute before next check
                        break
                    threading.sleep(0.5)
                else:
                    time.sleep(60)  # Sleep for exactly one minute

# Usage example:

if __name__ == "__main__":
    logs_queue = Queue()
    logs_manager = LogManager(logs_queue)

    # Initial log at startup
