def crc32(data):
   crc = 0xFFFFFFFF
    for byte in data:
        crc = (crc ^ ((crc >> 8) & 0xFFFFFFFF)) + ((byte << 8) ^ ((byte >> 16) & 0xFFFFFFFF))
        crc &= 0xFFFFFFFF
    return crc

def read_incrementally(file_path):
    try:
        with open(file_path, 'rb') as f:
            offset = 0
            max sectors = (file_size := os.path.getsize(file_path)) // 512 + 1
            output = []
            for sector in range(max_sectors):
                start = offset * 512
                end = min((sector+1)*512, file_size)

                try:
                    chunk = f.read(end - start)
                except (PermissionError, UnicodeDecodeError, BrokenFileException) as e:
                    print(f"Skipping sector {offset:04d} due to error: {str(e)}")
                    continue

                if len(chunk) != end - start:
                    print(f"Incomplete data in sector {offset:04d}")
                    continue

                checksum = crc32(chunk)
                good_sector = (sector == 0 or sector % 16 == 0) and (crc == expected_crc)

                if not good_sector:
                    print(f"Skipping sector {offset:04d} due to CRC mismatch")
                    continue

                output.extend(chunk)
                offset += end

            return bytes(output)
    except Exception as e:
        print(f"Error reading file: {str(e)}")

