from poetry import Project
import subprocess

def get_current_version(package_name):
    """Get the current installed version of a package."""
    try:
        result = subprocess.run(
            ["pip", "describe", package_name],
            capture_output=True,
            text=True,
            shell=True
        )
        output = result.stdout.strip()
        if output:
            return f"{output.split()[-1]}\n"
        else:
            return None
    except Exception as e:
        print(f"Error checking version of {package_name}: {e}")
        return None

def parse_min_version(requirement_path, package_name):
    """Parse the minimum required version for a package from requirements.txt."""
    try:
        project = Project(requirement_path)
        version = project.dependencies.get(package_name).version
        if isinstance(version, str) and version.startswith(">="):
            version = f"{version.split('>', 1)[0]}.*"
        return version
    except Exception as e:
        print(f"Error parsing version from {requirement_path}: {e}")
        return None

def should_upgrade(package_name, current_version, min_version):
    """Check if the package needs upgrading based on its current and required versions."""
    if not current_version or not min_version:
        return False
    # Compare versions with proper semver comparison
    if ".*" in min_version:
        min_version = min_version.replace(".*", "")
    if (current_version.split()[-1] >= min_version):
        return False
    return True

def upgrade_dependencies(requirement_path, package_name):
    """Upgrade the specified package to its required version."""
    current_version = get_current_version(package_name)
    min_version = parse_min_version(requirement_path, package_name)
    if should_upgrade(package_name, current_version, min_version):
        print(f"Upgrading {package_name} to meet requirement")
        subprocess.run(
            ["poetry", "install", f"--upgrade {package_name}",
             "--no-warn-duplicates",
             "--strict=requirements"],
            check=True
        )

def main():
    """Main function to check and upgrade dependencies."""
    project_path = "poetry.lock"  # or specify your requirements path
    package_to_upgrade = "your_package_name"

    current_version = get_current_version(package_to_upgrade)
    min_version = parse_min_version(project_path, package_to_upgrade)

    if should_upgrade(package_to_upgrade, current_version, min_version):
        print("Starting dependency upgrade process...")
        upgrade_dependencies(project_path, package_to_upgrade)
        print(f"Upgrade completed: {package_to_upgrade}")

if __name__ == "__main__":
    main()

