import hashlib

class ShoppingCart:
    def __init__(self):
        self.items = {}
        self.total_cost = 0

    def add_item(self, item):
        self.items[item] = 1
        self.total_cost += item.price

    def remove_item(self, item):
        if item in self.items:
            del self.items[item]
            self.total_cost -= item.price

    def get_items(self):
        return list(self.items)

    def get_total_cost(self):
        return self.total_cost

cart = ShoppingCart()
cart.add_item("Apple", 10)
cart.add_item("Orange", 5)
print(cart.get_items()) # Output: ["Apple", "Orange"]
print(cart.get_total_cost()) # Output: 15
cart.remove_item("Apple")
print(cart.get_items()) # Output: ["Orange"]
print(cart.get_total_cost()) # Output: 5

import heapq
from queue import PriorityQueue, Queue

class PriorityQueueQueue:
    def __init__(self):
        self.queue = PriorityQueue()

    # Add an element to the queue
    def enqueue(self, item, priority):
        if isinstance(item, (list, tuple)):
            name, value = item
            self.queue.put((priority, value))
        else:
            try:
                name, value = item
            except ValueError:
                raise TypeError("Invalid input format")

            # Prioritize elements with higher values
            self.queue.put((-value, name))

    # Remove and return an element from the queue
    def dequeue(self):
        if not self.is_empty():
            priority, item = self.queue.get()
            return item, -priority  # Return priority along with item
        else:
            raise IndexError("Queue is empty")

    # Check if the queue is empty
    def is_empty(self):
        return self.queue.empty()

    # Display elements in the queue
    def display_queue(self):
        for item, priority in list(self.queue.queue):
            print(f"Priority: {abs(priority)}, Item: {item}")


# Example usage:
if __name__ == "__main__":
    pq = PriorityQueueQueue()
    pq.enqueue("Lowest Priority", 1)
    pq.enqueue((1, "Item 1"), -3)  # High priority
    pq.enqueue((2, "Item 2"), -2)   # Medium priority
    pq.enqueue(3, "Highest Priority")

    print("\nQueue Elements:")
    pq.display_queue()

    while not pq.is_empty():
        item, priority = pq.dequeue()
        print(f"\nRemoved Item: {item}, Priority: {-priority}")

import os

def write_to_file(filename, data):
