        raise ValueError("File already exists")
    with open(filename, "w") as f:
        f.write(data)

from threading import Queue, Lock
import logging
import time

class EventQueueManager:
    def __init__(self):
        self._queue = Queue()
        self._lock = Lock()
        self.logger = logging.getLogger(__name__)
        self.logger.setLevel(logging.INFO)

    def enqueue_event(self, event):
        """Enqueues an event with a timestamp."""
        try:
            with self._lock:
                now = datetime.now()
                self._queue.put((event, now))
                self.logger.debug(f"Event {event.__class__.__name__} enqueued at {now}")
        except Exception as e:
            self.logger.error(f"Failed to enqueue event: {e}")

    def dequeue_event(self):
        """Dequeues an event if available and returns it."""
        with self._lock:
            while True:
                try:
                    event, timestamp = self._queue.get_nowait()
                    return (event, timestamp)
                except queue.Empty:
                    time.sleep(1)
                    continue
                except Exception as e:
                    self.logger.error(f"Failed to dequeue event: {e}")

    @staticmethod
    def get_queue():
        """Returns the internal queue."""
        return EventQueueManager._queue

# Example usage:
if __name__ == "__main__":
    manager = EventQueueManager()
    event = "test-event"

    # Enqueue an event
    try:
        start_time = datetime.now()
        manager.enqueue_event(event)
        print(f"Enqueued: {event} at {start_time}")

        # Dequeue events until one is processed or queue is empty
        while True:
            event, timestamp = manager.dequeue_event()
            if event is not None:
                print(f"Dequeued: {event} at {timestamp}")
            else:
                break
    except Exception as e:
        print(f"Error in main: {e}")

import hashlib
import os
import getpass

class User:
    def __init__(self, username, password):
        self.username = username
        self.password_hash = self.generate_password_hash(password)

    @staticmethod
    def generate_password_hash(password):
        """Generate a SHA-256 hash of the given password."""
        return hashlib.sha256(password.encode()).hexdigest()

class AuthenticationSystem:
    def __init__(self):
        self.users = {}

    def add_user(self, username, password):
        """Add a new user to the system."""
        if username in self.users:
            print("Username already exists. Please choose another one.")
            return

        self.users[username] = User(username, password)

    def authenticate_user(self, username, password):
        """Authenticate a user and return True if valid, False otherwise."""
        if username not in self.users:
            return False

        stored_password_hash = self.users[username].password_hash
        provided_password_hash = hashlib.sha256(password.encode()).hexdigest()

        # Compare the hashes to ensure they match.
        return stored_password_hash == provided_password_hash


# Example usage:

auth_system = AuthenticationSystem()

while True:
    print("\n1. Add User")
    print("2. Authenticate User")
    print("3. Quit")

    choice = input("Choose an option: ")

    if choice == "1":
        username = input("Enter a new username: ")
        password = getpass.getpass("Enter a new password (no echoing): ")

        auth_system.add_user(username, password)
        print(f"User '{username}' added successfully.")

    elif choice == "2":
        username = input("Enter your username: ")
        password = getpass.getpass("Enter your password (no echoing): ")

        if auth_system.authenticate_user(username, password):
            print("Authentication successful.")
        else:
            print("Authentication failed. Invalid credentials.")

    elif choice == "3":
        break

    else:
        print("Invalid option. Please try again.")

