class ShoppingCart:
    def __init__(self):
        self.items = []  # List to store items in the cart

    def add_item(self, name, price):
        """Add an item to the cart."""
        self.items.append({
            'name': name,
            'price': price,
            'quantity': 1
        })

    def remove_item(self, itemId=None, itemName=None):
        """Remove an item from the cart by ID or name."""
        if not (itemId or itemName):
            return "No item specified"

        for item in self.items:
            if (item['id'] == itemId) or (item['name'] == itemName):
                self.items.remove(item)
                return f"Item {item['name']} removed from cart"

        return "Item not found"

    def calculate_total(self, tax_rate=0.05):
        """Calculate the total price of items in the cart with tax."""
        total = 0
        for item in self.items:
            total += item['price'] * item['quantity']

        # Add tax to the subtotal (optional)
        total *= (1 + tax_rate)
        return round(total, 2)

    def show_cart(self):
        """Display the contents of the cart."""
        if not self.items:
            print("Cart is empty")
            return

        for item in self.items:
            print(f"{item['name']}: {item['price']} each, quantity: {item['quantity']}")

    def get_subtotal(self):
        """Return the subtotal without tax."""
        return round(sum(item['price'] * item['quantity'] for item in self.items), 2)

    def __str__(self):
        """String representation of the cart contents."""
        if not self.items:
            return "Cart is empty"

        content = []
        for item in self.items:
            content.append(f"{item['name']}: {item['price']} each, quantity: {item['quantity']}")

        subtotal = sum(item['price'] * item['quantity'] for item in self.items)
        tax = round(subtotal * 0.05, 2)  # Adding 5% tax
        total = round((subtotal + tax), 2)

        content.append(f"\nSubtotal: ${subtotal}")
        content.append(f"Tax: ${tax}")
        content.append(f"Total: ${total}")

        return '\n'.join(content)

# Example usage:
cart = ShoppingCart()

# Adding items
cart.add_item("Apple", 1.50)
cart.add_item("Banana", 0.99)
cart.add_item("Orange", 1.25, 2)

print(cart)  # Shows the cart contents with subtotal and total including tax

# Remove an item
cart.remove_item("Apple")
print(cart)  # Updates the cart after removal

# Calculate total without tax
subtotal = cart.calculate_total(tax_rate=0)
print(f"Subtotal: ${subtotal}")

# Calculate total with tax (5%)
total_with_tax = cart.calculate_total()
print(f"Total with tax: ${total_with_tax}")

class User:
    def __init__(self, role):
        self.role = role

# Define user roles
roles = {
   "admin": ["read", "write", "delete"],
   "editor": ["read", "write"],
   "viewer": ["read"]
}

def enforce_access(action, user):
    if action in roles[user.role]:
        return True
    else:
        return False

