class TenantActivityLogger():
    def __init__(self):
        self.logs = {}  # This will hold the log for each tenant

    def log_activity(self, tenant_id, activity):
        if tenant_id not in self.logs:
            self.logs[tenant_id] = []  # Create a new list for this tenant if it doesn't exist

        self.logs[tenant_id].append(activity)  # Add the activity to the tenant's log

    def get_log(self, tenant_id):
        if tenant_id in self.logs:
            return self.logs[tenant_id]  # Return the tenant's log
        else:
            return "No activities logged for this tenant."

import json
from datetime import datetime, timedelta

def validate_content_metadata(metadata):
    # Check if metadata is None or not a dictionary
    if not isinstance(metadata, dict):
        return False

    required_keys = ["title", "description", "author", "created_at"]

    # Check if all required keys are present in the metadata
    for key in required_keys:
        if key not in metadata:
            return False

    try:
        # Validate date format of created_at field
        datetime.strptime(metadata["created_at"], "%Y-%m-%d")

        # Check if content is older than 1 year from now
        created_at = datetime.strptime(metadata["created_at"], "%Y-%m-%d")
        one_year_ago = created_at - timedelta(days=365)
        if created_at < one_year_ago:
            return False

    except ValueError:
        # Handle invalid date format for created_at field
        return False

    return True

# Example usage
metadata = {
    "title": "Example Content",
    "description": "This is an example content.",
    "author": "John Doe",
    "created_at": "2022-01-01"
}

if validate_content_metadata(metadata):
    print("Metadata is valid.")
else:
    print("Metadata is not valid.")

import socket
import time
import requests
from urllib.parse import urljoin
import logging

class Device:
    def __init__(self):
        self.name = "Device Name"
        self.ip_address = "IP Address"
        self.current_firmware_version = "Current Firmware Version"
        self.last_update_time = 0
        self.updates = []

    def update_device(self, new_version, timestamp):
        self.current_firmware_version = new_version
        self.last_update_time = timestamp
        logging.info(f"Updated firmware version {new_version} at {timestamp}")

class UpdateRequest:
    def __init__(self, request_type, timestamp, success=False):
        self.request_type = request_type
        self.timestamp = timestamp
        self.success = success

def device_firmware_update():
    device = Device()

    try:
        while True:
            time.sleep(60)  # Check for updates every minute

            # Listen for firmware update request
            with socket.socket(socket.AF_INET, socket.SOCK_RAW, 1) as s:
                s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
                s.bind(('localhost', 8080))  # Bind to a specific port

                try:
                    while True:
                        data = s.recv(1024)
                        if b'firmware_update' in data:
                            logging.info("Received firmware update request")
                            update_request = UpdateRequest('firmware', time.time())
                            device.updates.append(update_request)

                            # Fetch the update package
                            update_url = get_update_url(device.ip_address, "firmware")  # Replace with actual endpoint
                            response = requests.get(update_url, stream=True)

                            if not response.ok:
                                raise Exception(f"HTTP request failed: {response.status_code}")

                            # Download the firmware file
                            with open('new_firmware.bin', 'wb') as f:
                                for chunk in response.iter_content(chunk_size=1024):
                                    if chunk:
                                        f.write(chunk)
                                        logging.info("Downloaded firmware file")

                            # Send the firmware to the device
                            send_update_request(device, "http", "localhost", 8080)  # Replace with actual protocol and address

                        except KeyboardInterrupt:
                            break
                except Exception as e:
                    logging.error(f"Connection error: {e}")
                    break

    except Exception as e:
        logging.error(f"Device firmware update failed: {e}")

def get_update_url(ip, endpoint="firmware"):
    return f"http://{ip}/{endpoint}"

def send_update_request(device, request_type, from_address, to_socket_port):
    try:
        response = requests.post(
            get_update_url(device.ip_address, "update_request"),
            json={'request_type': request_type, 'from_address': from_address, 'to_port': to_socket_port}
        )

        if not response.ok:
            raise Exception(f"HTTP request failed: {response.status_code}")

        logging.info("Sent update request successfully")
    except Exception as e:
        logging.error(f"Failed to send update request: {e}")

def main():
    try:
        device_firmware_update()
    except KeyboardInterrupt:
        print("\nShutting down...")

if __name__ == "__main__":
    print("Firmware update server started on localhost:8080")
    main()

# Example usage:
# Manually trigger an update request from the command line:
# curl -X POST http://localhost:8080/update_request \
#     --data "{'request_type': 'firmware', 'from_address': '0.0.0.0', 'to_port': 8080}"

