import json
import os
from datetime import datetime

def generate_encryption_key(tenant_id):
    current_timestamp = int(datetime.now().timestamp())
    return f"{tenant_id}_{current_timestamp}"

def write_backup(tenant_id):
    backup_path = os.path.join("backups", f"{tenant_id}_backup.json")

    # Generate encryption key
    key = generate_encryption_key(tenant_id)

    if not os.path.exists(backup_path):
        initial_content = {
            "timestamp": int(datetime.now().timestamp())
        }
        with open(backup_path, 'w') as file:
            json.dump(initial_content, file, indent=4, ensure_ascii=False)
        return

    # Read existing content
    with open(backup_path, 'r', encoding='utf-8') as file:
        current_data = json.load(file)

    # Append new entry
    new_entry = {
        "timestamp": int(datetime.now().timestamp())
    }
    encrypted_data = {
        "encryption_key": key,
        "content": json.dumps(new_entry, indent=4, ensure_ascii=False),
        "last_updated": current_data.get("last_updated", 0)
    }

    with open(backup_path, 'a', encoding='utf-8') as file:
        encrypted_content = json.dumps(encrypted_data, indent=4, ensure_ascii=False)
        file.write(f"\n{encrypted_content}")

    return True

# Example usage
tenants = {'001': 'Tenant One', '002': 'Tenant Two'}

if __name__ == "__main__":
    for tenant_id in tenants.keys():
        success = write_backup(tenant_id)
        if not success:
            print(f"Backup for tenant {tenant_id} failed.")

import requests

def get_link(url):
    try:
        response = requests.get(url)
        if response.status_code == 200:
            return url
        else:
            raise ValueError("Broken link")
    except requests.exceptions.RequestException as e:
