import os
import subprocess
import logging
from time import sleep

def logger(filename='deployment.log'):
    """Create a file handler and a consoleHandler for logging."""
    formatter = logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s')
    file_handler = logging.FileHandler(filename, 'w')
    file_handler.setFormatter(formatter)
    file_handler.setLevel(logging.INFO)
    console_handler = logging.StreamHandler()
    console_handler.setFormatter(formatter)
    console_handler.setLevel(logging.INFO)
    logger = logging.getLogger(__name__)
    logger.addHandler(file_handler)
    logger.addHandler(console_handler)
    return logger

def check_dependencies(depfile, logger):
    """Check if required dependencies are installed and install missing ones."""
    try:
        with open(depfile) as f:
            requirements = set(line.split('==')[0] for line in f)
        current Installing dependencies...
    except FileNotFoundError:
        logger.warning(f"Required file {depfile} not found. Please ensure it exists.")
        return False

    logger.info("Checking if dependencies are installed...")
    try:
        subprocess.check_output(['pip', 'install', '--upgrade', ' wheel'])
    except Exception as e:
        logger.error(f"Error during dependency installation: {str(e)}")
        return True
    return False

def check Permissions(filename, user, logger):
    """Verify file permissions for the deployment script."""
    permfile = os.path.join(os.getcwd(), 'perms.txt')
    try:
        with open(permfile) as f:
            required_perms = set(line.strip() for line in f)
        if not all(required_perms.issubset(os.get permissions(filename))):
            logger.warning(f"Permission issue: {filename} lacks necessary permissions")
            return False
        logger.info(f"File {filename} has correct permissions.")
    except FileNotFoundError:
        logger.warning(f"No perms.txt file found. Creating one with default perms.")
        open(permfile, 'w').close()
    return True

def retryDeployment(depfile, max_retries=3):
    """Attempt deployment multiple times if initial fails."""
    for attempt in range(max_retries):
        try:
            # Replace with actual deployment command
            subprocess.run(['your-deployment-script'], check=True)
            logger.info(f"Deployment succeeded on attempt {attempt+1}")
            return True
        except Exception as e:
            if attempt < max_retries - 1:
                logger.warning(f"Attempt {attempt+1} of {max_retries} failed: {str(e)}")
                sleep(2 ** (attempt + 1))  # Exponential backoff

    logger.error("Deployment failed after all attempts.")
    return False

def validatePreReqs(filename, user, logger):
    """Check for pre-requisite files and permissions."""
    if not check_dependencies(filename, user, logger):
        return False
    required_perms = {'drwxr--r--r--'}  # Example permissions
    permfile = os.path.join(os.getcwd(), 'perms.txt')
    if os.path.exists(permfile) and os.getPermissions(filename) < required_perms:
        logger.warning(f"Insufficient permissions on {filename}")
        return False
    if not os.path.exists(filename):
        logger.error(f"{filename} does not exist. Please create it.")
        return False

def deploy(filename, user, logger):
    """Main deployment function with error handling."""
    try:
        logger.info(f"Starting deployment of file: {filename}")
        if validatePreReqs(filename, user, logger):
            result = retryDeployment(filename, max_retries=3)
            if result:
                logger.info(f"Deployment completed successfully.")
                return True
            else:
                logger.error("Deployment failed after all retries.")
                return False
        else:
            logger.error("Deployment prerequisites failed. Check perm.txt and dependencies.")
    except Exception as e:
        logger.error(f"Unexpected error during deployment: {str(e)}")

# Example usage
def main():
    if retryDeployment('requirements.txt', max_retries=3):
        print("Started deploy process...")
        deploy('script.py', 'user', logger)
    else:
        print("No deploy attempts left.")

if __name__ == "__main__":
    logger = logger()  # Initialize logger
    try:
        main()
    except KeyboardInterrupt:
        logger.info("Deployment cancelled by user.")
    finally:
        logger.info("Program completed normally")

import json

def get_safe_json(json_source=None, encoding='utf-8'):
    """
    Safely load JSON from a source, accepting either a file object or a JSON string.
    Returns the parsed dictionary.

    Args:
        json_source (Union[bytes, str, None]): The JSON data to parse. If None, reads from stdin.
        encoding (str): The encoding to use when reading bytes.

    Raises:
        ValueError: If the input is not valid JSON.
        Exception: For other unexpected errors.
    """
    if json_source is None:
        # Read from standard input
        try:
            return json.loads(input(), object_hook=str)
        except ValueError as e:
            raise ValueError(f"Invalid JSON:\n{json.dumps(e, indent=2)}") from e

    # For file-like objects or direct string
    if isinstance(json_source, bytes):
        data = json_source.decode(encoding)
    elif not isinstance(json_source, str):
        return  # Return None for unsupported types

    try:
        return json.loads(data, object_hook=str)
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON:\n{json.dumps(e, indent=2)}") from e

import PyPDF2

def extract_pdf_text(pdf_path, include_metadata=False):
    try:
        reader = PyPDF2.PdfReader(pdf_path)
        text = ''
        for page in reader.pages:
            extracted_page_text = page.extract_text()
            text += extracted_page_text + '\n'

        if include_metadata:
            media_box = reader.mediaBox
            width, height = media_box.size
            metadata_str = f"Metadata:\nNumber of pages: {len(reader.pages)}\nMedia box size (width, height): ({width}, {height})"
            text += metadata_str

        return text.strip()
    except Exception as e:
        print(f"Error extracting from PDF at path {pdf_path}: {e}")
        return None

