import sys
import subprocess
import os
import time

def main():
    try:
        # Define a function to spawn the web server
        def spawn_web_server():
            os.remove('http_server.pid')  # Remove old process if exists
            httpd = subprocess.run(['python', '-u', 'http.server'], 
                                  shell=True, check=False,
                                  text=True, universal_newlines=True)
            return httpd

        # Define a function to add tasks from child process
        def add_tasks(child):
            while True:
                try:
                    line = child.stdin.readline()
                    if not line.strip():
                        continue  # Skip empty lines
                    task = line.strip()
                    print(f"\nAdded new task: {task}")
                    return [task]
                except subprocess.CalledProcessError:
                    break
            return []

        # Main logic
        last_check = time.time()
        max_interval = 10  # seconds

        while True:
            try:
                child = spawn_web_server()
                child.stdout.close()  # Close the stdout of the child

                # Read from the child's stdin every second or when new tasks are added
                while True:
                    time.sleep(1)
                    input buffering and handling is done in add_tasks()

                last_check += max_interval

            except Exception as e:
                print(f"An error occurred: {e}")
                sys.exit(1)

    except KeyboardInterrupt:
        print("\nShutting down gracefully...")
        sys.exit(0)

if __name__ == "__main__":
    main()

