import random
import string

class KeyRotator:
    def __init__(self, num_keys=10):
        self.keys = self.generate_keys(num_keys)
        self.current_key_index = 0

    # Generate a list of random keys
    @staticmethod
    def generate_keys(num_keys):
        keys = []
        for _ in range(num_keys):
            key = ''.join(random.choices(string.ascii_uppercase + string.digits, k=16))
            keys.append(key)
        return keys

    # Rotate to the next key and return it
    def rotate_key(self):
        self.current_key_index = (self.current_key_index + 1) % len(self.keys)
        return self.keys[self.current_key_index]

from moviepy.editor import VideoFileClip
import os

# Function to transcode video files
def transcode_video(input_file, output_file):
    # Validate input file exists and is accessible
    if not os.path.isfile(input_file) or not os.access(input_file, os.R_OK):
        raise FileNotFoundError("Input file does not exist or is not readable.")

    try:
        # Load the video clip
        clip = VideoFileClip(input_file)

        # Transcode the video to new format and save it
        clip.write_videofile(output_file, codec='libx264', audio_codec='aac')
    except Exception as e:
        raise RuntimeError("An error occurred while transcoding the file.") from e

