import os
from mutagen import File

def extract_audio_metadata(directory):
    metadata = {}

    for filename in os.listdir(directory):
        file_path = os.path.join(directory, filename)

        try:
            audio_file = File(file_path)
            # Extract relevant audio information and add to metadata dict
            if hasattr(audio_file, 'title'):
                metadata[filename] = {
                    'title': audio_file.title,
                    'artist': audio_file.artist,
                    'duration': audio_file.duration,
                    'bit_rate': audio_file bitrate  # Note: bit_rate is a property, so no space before _
                }
            else:
                pass
        except Exception as e:
            print(f"Error processing file {filename}: {e}")

    return metadata

def save_to_json(metadata_data, output_file="audio_metadata.json"):
