class TaskManager:
    def __init__(self):
        self._tasks = {}

    def add_task(self, name, func):
        """Add a new task"""
        if not callable(func):
            raise TypeError('Expected a function')
        if name in self._tasks:
            raise ValueError("A task with this name already exists.")
        self._tasks[name] = func

    def execute_task(self, name, *args, **kwargs):
        """Execute the given task"""
        if name not in self._tasks:
            raise KeyError('No such task')
        return self._tasks[name](*args, **kwargs)

# Usage
manager = TaskManager()
def hello_world():
    print("Hello World!")

manager.add_task('hello', hello_world)
manager.execute_task('hello') # outputs: Hello World!

