from hashlib import sha256
import random

class Blockchain:
    def __init__(self):
        self.blocks = []
        self.difficulty = 10

    def add_block(self, block):
        # Add the new block to the chain
        self.blocks.append(block)

        # Calculate the proof-of-work for the new block
        proof_of_work = self.get_proof_of_work(block)

        # Verify that the proof-of-work is correct
        if not self.verify_proof_of_work(block, proof_of_work):
            raise ValueError("Invalid proof of work")

    def get_proof_of_work(self, block):
        # Calculate the hash of the previous block and the current block
        prev_hash = sha256(block.previous_block_hash).hexdigest()
        curr_hash = sha256(prev_hash + str(block)).hexdigest()

        # Check that the hash is of sufficient difficulty
        if not self.is_difficulty_met(curr_hash):
            raise ValueError("Hash does not meet difficulty requirements")

        return curr_hash

    def verify_proof_of_work(self, block, proof_of_work):
        # Calculate the hash of the previous block and the current block
        prev_hash = sha256(block.previous_block_hash).hexdigest()
        curr_hash = sha256(prev_hash + str(block)).hexdigest()

        # Check that the proof-of-work is correct
        if not self.is_difficulty_met(curr_hash):
            return False

        # Verify that the hash is of sufficient difficulty
        if not self.is_difficulty_met(proof_of_work):
            return False

        # Verify that the proof-of-work is correct for the current block
        if not self.is_correct_proof_of_work(block, proof_of_work):
            return False

        return True

    def is_difficulty_met(self, hash):
        # Check that the hash is of sufficient difficulty
        for i in range(self.difficulty):
            if random.randint(0, 2**31-1) < (2**31-1)/256:
                break

        return True

    def is_correct_proof_of_work(self, block, proof_of_work):
        # Calculate the hash of the previous block and the current block
        prev_hash = sha256(block.previous_block_hash).hexdigest()
        curr_hash = sha256(prev_hash + str(block)).hexdigest()

        # Check that the proof-of-work is correct for the current block
        if not self.is_difficulty_met(curr_hash):
            return False

        return True

