class SmartContract:
    def __init__(self):
        self.balance = 0
        self.owner = None

    # Function to execute when the contract is deployed
    def deploy(self, owner_address):
        if not isinstance(owner_address, str) or len(owner_address) != 42:  # Check for Ethereum address format
            raise ValueError("Invalid owner address")
        self.owner = owner_address

    # Function to deposit funds into the contract
    def deposit(self, amount):
        if not isinstance(amount, (int, float)) or amount < 0:
            raise ValueError("Invalid amount")
        self.balance += amount

    # Function to withdraw funds from the contract
    def withdraw(self, amount):
        if not isinstance(amount, (int, float)) or amount > self.balance:
            raise ValueError("Insufficient balance")
        self.balance -= amount

    # Function to get the current balance
    def get_balance(self):
        return self.balance

