class DistributedCachingSystem:
    def __init__(self):
        self.nodes: List[Node] = []
        self.storage_layers: List[StorageLayer] = []

    def add_node(self, node: Node):
        self.nodes.append(node)

    def add_storage_layer(self, storage_layer: StorageLayer):
        self.storage_layers.append(storage_layer)

    def rotate_tokens(self, period: timedelta) -> None:
        for node in self.nodes:
            tokens_to_rotate = []
            current_tokens = list(node.tokens.items())
            today = time.time()
            for token_id, token in current_tokens:
                if time.time() - token.expiration > 0:
                    new_expiration = today + period.total_seconds()
                    tokens_to_rotate.append((token_id, Token(token_id, new_expiration)))

            for token_id, token in tokens_to_rotate:
                node.tokens[token_id] = token
            logging.info(f"Token rotation completed for node {node.node_id}")

    def add_data_with_tokens(self, data: Any, key: str, headers: Dict[str, str]) -> None:
        # Check token access
        for node in self.nodes:
            if not all(self.check_access(token.token, src_ip) for (src_ip, token) in zip(node.authenticators, [token for token in node.tokens.values()])):
                logging.error(f"Data cannot be accessed by {node.node_id}")
                return

        # Replicate data across storage layers
        self.add_data_to_all_layers(data, key)

    def add_data_to_all_layers(self, data: Any, key: str) -> None:
        for layer in self.storage_layers:
            timestamp = int(time.time())
            layer.add_data(data, timestamp)
            logging.info(f"Data {key} replicated to storage layer {layer.storage_provider} at {timestamp}")

    def ensure_security(self):
        # Basic security checks
        if len([token for token in [t.token for node in self.nodes for t in node.tokens.values()]]) == 0:
            return False

        for layer in self.storage_layers:
            logging.info(f"Storage layer {layer.storage_provider} has data size: {os.path.getsize(layer.get_data('test'))}")

def main():
    # Initialize system
    distributed_caching = DistributedCachingSystem()

    # Example usage
    node1 = Node("node1", "authenticator1")
    node2 = Node("node2", "authenticator2")
    distributed_caching.add_node(node1)
    distributed_caching.add_node(node2)

