import pip
from pip._vendor.packaging import specifiers, markers

def check_license(name):
    # Get the package metadata from PyPI
    pkg = pip.get_installed_distributions(name)

    # Check if the package has an insecure license
    for license in pkg.licenses:
        if "insecure" in license or "unsafe" in license:
            return False

    return True

# Restrict third-party libraries with insecure licenses
if check_license("requests"):
    print("The requests library is installed and has a secure license")
else:
    print("The requests library is not installed or has an insecure license")

import requests
import time
from logging import warning


def webhook_retry(max_retries=3, wait_time=10,):
    """
    Decorator to retry failed webhooks up to max_retries times.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            for attempt in range(1, max_retries + 1):
                try:
                    return func(*args, **kwargs)
                except requests.exceptions.RequestException as e:
                    warning(f"Webhook request failed on attempt {attempt}. Reason: {str(e)}")
                    if attempt < max_retries:
                        time.sleep(wait_time)
            raise
        return wrapper
    return decorator

def send_example_endpoint(url):
    """
    Send example webhook endpoint.
    """
    response = requests.get(
        url,
        params={"query": "example"}
    )
    warning(f"Sent request to {url} with query 'example' and got response: {response.status_code}")
    return response


def send_endpoint(url, retry_max=3, wait_time=10):
    """
    Send example endpoint with given URL, using retry decorator.
    """
    webhook_retry(retry_max, wait_time)(send_example_endpoint, url=url)

