import os
from flask import Flask, render_template, request

app = Flask(__name__)

# Social Media APIs Configuration
social_media_urls = {
    'facebook': 'https://www.facebook.com/sharer.php?u={}',
    'twitter': 'https://twitter.com/intent/tweet?url={}&title={}',
    'linkedin': 'https://www.linkedin.com/sharing/share?url={}&title={}',
}

def get_share_url(social_media, url, title):
    """Return the share URL for a specific social media platform."""
    api_url = social_media_urls[social_media].format(url=url, title=title)
    return api_url

@app.route('/share/<string:url>/<string:title>')
def share_url(url, title):
    """Render the share page with the provided URL and title."""
    # Secure the API request by including a CSRF token
    csrf_token = os.urandom(32).hex()
    return render_template('share.html', url=url, title=title, api_url=get_share_url(request.args.get('social_media'), url, title), csrf_token=csrf_token)

@app.route('/handle-share/<string:csrf_token>')
def handle_share(csrf_token):
    """Handle the share request by validating the CSRF token."""
    # Securely verify the CSRF token
    if request.form['csrf_token'] != csrf_token:
        return 'Invalid CSRF token', 403

    # Share on social media using the provided API URL
    social_media = request.form.get('social_media')
    if social_media in ['facebook', 'twitter', 'linkedin']:
        response = requests.get(get_share_url(social_media, request.form['url'], request.form['title']))
        return 'Shared successfully!', 200

# Render the share page with a secure CSRF token
@app.route('/share/<string:url>/<string:title>/csrf')
def render_share_page(url, title):
    return render_template('share.html', url=url, title=title)

if __name__ == '__main__':
    app.run(debug=True)

