# Define your roles as constants
ADMIN = 'admin'
EDITOR = 'editor'
VIEWER = 'viewer'

class User:
    def __init__(self, name, role):
        self.name = name
        self.role = role

def authorize(valid_roles):
    """
    A decorator that only allows users with valid roles to access a function
    """
    def wrapper(func):
        def decorated(*args, **kwargs):
            user = args[0]  # assuming the user is always the first argument
            if user.role not in valid_roles:
                raise Exception("Unauthorized access")
            return func(*args, **kwargs)
        return decorated
    return wrapper

class System:
    @authorize([ADMIN])
    def create(self, user):
        print(f'User {user.name} created a new resource')

    @authorize([ADMIN, EDITOR])
    def update(self, user):
        print(f'User {user.name} updated the resource')

    @authorize([ADMIN, EDITOR, VIEWER])
    def view(self, user):
