import psutil
from datetime import datetime, timedelta

class TenantUsageMonitor:
    def __init__(self):
        self.users = {}

    def get_current_time(self):
        return datetime.now()

    def add_user(self, username, cpu_usage, memory_usage):
        self.users[username] = {"cpu_usage": cpu_usage, "memory_usage": memory_usage, "last_updated": self.get_current_time()}

    def remove_user(self, username):
        if username in self.users:
            del self.users[username]
        else:
            print("User not found")

    def update_user(self, username, cpu_usage, memory_usage):
        if username in self.users:
            self.users[username]["cpu_usage"] = cpu_usage
            self.users[username]["memory_usage"] = memory_usage
            self.users[username]["last_updated"] = self.get_current_time()
        else:
            print("User not found")

    def monitor_system_usage(self):
        while True:
            for username, user_data in self.users.items():
                current_cpu_usage = psutil.cpu_percent(interval=1)
                current_memory_usage = psutil.virtual_memory().percent
                if user_data["cpu_usage"] != current_cpu_usage or user_data["memory_usage"] != current_memory_usage:
                    user_data["last_updated"] = self.get_current_time()
                    print(f"Username: {username}, CPU Usage: {current_cpu_usage}%, Memory Usage: {current_memory_usage}%")
            time.sleep(1)

    def print_tenant_usage(self):
        for username, user_data in self.users.items():
            print(f"Username: {username}, Last Updated: {user_data['last_updated']}, CPU Usage: {user_data['cpu_usage']}%, Memory Usage: {user_data['memory_usage']}%")

# Example usage:
