import logging
import os
from datetime import timedelta

class Ticket:
    def __init__(self, username, password):
        self.username = username
        self.password = password
        self.session_id = str(os.urandom(4))  # Generate a random session ID
        self.expiration_time = None

    def is_valid(self):
        return True

    def authenticate(self):
        """Authenticate the user with this ticket."""
        if not self.is_valid():
            raise ValueError("Invalid ticket authentication")

def create_ticket(username, password):
    ticket = Ticket(username, password)
    # Set an expiration time after 2 hours
    ticket.expiration_time = int(os.times())
    delta = timedelta(hours=2)
    ticket.expiration_time += int(os.times()) + (delta.microsecond.total_seconds() * 1e6)

    return ticket


def get_ticket(get_user, allowed_log_levels):
    """Get a ticket or create and store one."""
    for user in allowed_log_levels:
        if user['username'] == get_user:
            # Check if the user is allowed to log at their level
            if any(log_level in allowed_log_levels[user]['allowed'] for log_level in [logging.DEBUG, logging.INFO]):
                return create_ticket(user['username'], user.get('password', ''))

    raise ValueError(f"User {get_user} not found or unauthorized.")


def basicConfig(ticket, get_user=None):
    """Custom logging configuration using a ticket."""
    original_basicConfig = loggingbasicConfig

    def check_ticket(func):
        """Ticket validation decorator for logging functions."""
        def wrapper(*args, **kwargs):
            if 'get_user' in kwargs:
                get_user = kwargs['get_user']

                # If no get_user function is provided, use the ticket's username
                if not get_user:
                    get_user = lambda: ticket.username

                try:
                    user = get_user()
                except:
                    raise TypeError(f"Argument missing for `get_user`: {ticket}")

                # Validate the ticket based on the user's allowed log levels
                allowed_log_levels = {}
                for log_level, users in ticket.allowed_log_levels.items():
                    if any(user['username'] == user_name for user in users):
                        allowed_log_levels[log_level] = True

                try:
                    return func(*args, **kwargs)
                finally:
                    # After logging, invalidate the ticket
                    if not ticket.is_valid():
                        raise ValueError("Invalid ticket")

            else:
                # If get_user is not provided, validate against all allowed users
                for log_level, users in ticket.allowed_log_levels.items():
                    if any(user['username'] == user_name for user in users):
                        return True

            raise AttributeError(f"'{type(func).__name__}' object has no attribute 'ticket'")

        return wrapper

    # Replace the basicConfig with our custom function
    logging_basicConfig = original_basicConfig
    try:
        if get_user is not None and callable(get_user):
            logging_basicConfig = check_ticket
    except ValueError as error:
        print(f"User {error} not found or unauthorized.")

    return logging_basicConfig


def startAccessControl(ticket, get_user=None):
    """Start access control by creating tickets for all users."""
    try:
        if ticket.is_valid():
            # Create tickets and store them in memory
            for user in ticket.allowed_log_levels:
                user_dict = next(iter(user.values()))
                create_ticket(user_dict['username'], user_dict.get('password', ''))

            return True
        else:
            raise ValueError("Ticket is expired or invalid.")

    except Exception as error:
        print(f"Error starting access control: {error}")
        return False


def log(message, level=logging.INFO):
    """Log a message only if the ticket is valid and user has permission."""
    # Ensure the ticket is created
    try:
        ticket = get_ticket(lambda: None, logging)
        get_ticket(lambda: None, logging)

    except ValueError as error:
        raise error

    if not ticket.is_valid():
        raise ValueError("Invalid ticket")

    allowed_log_levels = {}
    for log_level, users in ticket.allowed_log_levels.items():
        if any(user['username'] == user_name for user in users):
            allowed_log_levels[log_level] = True

    # Check the message level
    try:
        msg = logging.getEffectiveLevelName(level)
    except NameError:
        raise ValueError(f"Invalid log level: {level}")

    # Validate against allowed log levels
    if msg not in allowed_log_levels or not allowed_log_levels[msg]:
        raise ValueError(f"User unauthorized for {msg} level")

    try:
        # Rotate the file handler to keep 10 rotating copies
        with open(os.devnull, 'w') as f:
            f.write(msg)
        handler = logging.FileHandler('logs/' + msg + '.log')
        handler.setFormatter(logging.Formatter('%(asctime)s - %(name)s - %(levelname)-5.5s - %(message)s'))
        handler.setRotationLimit(10)

    except PermissionError:
        raise RuntimeError("Cannot write logs")

    # Write the log
    try:
        logging.getLogger(msg).addHandler(handler)
        logging.getLogger(msg).warning(message)
    finally:
        for handler in handlers:
            handler.remove()

    return True


# Example usage

allowed_users = {
    'sysadmin': [
        {'username': 'admin1', 'password': 'secret'},
        {'username': 'admin2', 'password': 'pass2'}
    ]
}

ticket = get_ticket(lambda: None, allowed_users)

try:
    ticket.is_valid()

except ValueError as error:
    print(f"Error initializing logs: {error}")
    exit(1)

accessControlEnabled = startAccessControl(ticket)

if accessControlEnabled:
    try:
        logging.info("System log started.")
        log("This is a system message.", level=logging.INFO)
        log("Another system message.", level=logging.ERROR)
    finally:
        print("Logs have been closed.")

else:
    print("Access control failed. Logs not enabled.")

