import heapq

class PriorityQueue(object):
    def __init__(self):
        self.queue = []

    def push(self, item, priority=0):
        heapq.heappush(self.queue, (priority, item))

    def pop(self):
        return heapq.heappop(self.queue)[1]

import os

# Define a dictionary to store the cache
cache = {}

# Define a function to invalidate the cache
def invalidate_cache(path):
  if path in cache:
    del cache[path]

# Define a function to update the cache
def update_cache(path, data):
  # Invalidate the cache if the file has been modified since it was last cached
  if os.path.getmtime(path) > cache.get(path, 0):
    invalidate_cache(path)
    cache[path] = data

