import datetime
from typing import Dict, List

class Activity:
    def __init__(self, user: str, activity_type: str):
        self.user = user
        self.activity_type = activity_type

class ReportGenerator:
    def __init__(self):
        self.activities: Dict[str, List[Activity]] = {}

    def log_activity(self, user: str, activity_type: str):
        """Logs an activity."""
        if user not in self.activities:
            self.activities[user] = []

        activity = Activity(user, activity_type)
        self.activities[user].append(activity)

    def generate_report(self) -> Dict[str, List[Dict]]:
        """Generates a report on all activities."""
        report: Dict[str, List[Dict]] = {}
        for user, activities in self.activities.items():
            report[user] = []
            for i, activity in enumerate(activities):
                report_value = {
                    "Activity Type": activity.activity_type,
                    "Time": datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                    "Activity #": i + 1
                }
                report[user].append(report_value)

        return report

# Example usage:
