report_generator.log_activity("User1", "Login")
report_generator.log_activity("User2", "Logout")
report_generator.log_activity("User1", "Viewed report")

report = report_generator.generate_report()

for user, activities in report.items():
    print(f"Activities by {user}:")
    for activity in activities:
        print(activity)

import json
import pickle

def deserialize_binary(data):
    try:
        # Check if it's a JSON string
        if isinstance(data, str) and len(data) > 0:
            return json.loads(data)

        # Try to decode as JSON
        data = json_bytes_to_str(data)
        result = json.loads(data)
        return result

    except json.JSONDecodeError:
        pass  # Not a valid JSON string

    try:
        # If not JSON, attempt to deserialize using pickle
        if isinstance(data, bytes):
            result = pickle.loads(data)
            return result

    except Exception as e:
        print(f"Failed to deserialize. Reason: {e}")
        return None

    return None  # On failure, return None or appropriate default

def json_bytes_to_str(binary_data):
    """Convert binary string (bytes) to str for json.loads"""
    if isinstance(binary_data, bytes):
        return binary_data.decode('utf-8')
    return binary_data

