import os
import logging

def secure_delete(file_path):
    """
    Securely deletes a file by overwriting it with random data.

    Args:
        file_path (str): The path of the file to be deleted.

    Returns:
        bool: True if the deletion was successful, False otherwise.
    """

    # Check if the input is valid
    if not isinstance(file_path, str):
        raise TypeError("File path must be a string.")

    try:
        # Get the file size
        file_size = os.path.getsize(file_path)

        # If the file is empty, we can simply delete it
        if file_size == 0:
            return os.remove(file_path)

        # Otherwise, overwrite the file with random data
        random_data = os.urandom(file_size)

        # Write the random data to the file
        with open(file_path, "wb") as f:
            f.write(random_data)

        # Delete the original file
        try:
            return os.remove(file_path)
        except OSError:
            logging.error("Failed to delete file")
            return False

    except OSError:
        logging.error("Failed to get file size or access file")
        return False

# Example usage:
if __name__ == "__main__":
    file_path = "/path/to/processed_message.txt"
    if secure_delete(file_path):
        print(f"File {file_path} deleted successfully.")
    else:
        print(f"Failed to delete file {file_path}.")

