class Tenant:
    def __init__(self, name, limit):
        self.name = name
        self.limit = limit
        self.current_usage = 0

    def use_resources(self, usage):
        if self.current_usage + usage > self.limit:
            raise Exception("Resource limit exceeded for tenant {}".format(self.name))
        else:
            self.current_usage += usage

class Resource:
    def __init__(self, name, usage):
        self.name = name
        self.usage = usage

# Create tenants and resources
tenant1 = Tenant('Tenant 1', 50)
resource1 = Resource('Resource 1', 20)

try:
    # A tenant tries to use a resource
    tenant1.use_resources(resource1.usage)
except Exception as e:
    print("Error occurred: ", str(e))

import os
from datetime import datetime
from typing import Any, Optional

class SecureEnvironmentVariables:
    def __init__(self):
        self.variables = {}

    @secure
    def get(self, var_name: str) -> Any:
        """Get an environment variable safely."""
        var_value = os.getenv(var_name)
        if var_value is None:
            raise ValueError(f"Environment variable '{var_name}' not found.")
        sanitized_var_value = self._sanitize(var_value)
        return sanitized_var_value

    @secure
    def set(self, var_name: str, var_value: Optional[str] = None) -> None:
        """Set or update an environment variable safely."""
        if var_value is None:
            os.environ[var_name] = self._sanitize(datetime.now().strftime("%Y-%m-%d"))
        else:
            sanitized_value = self._sanitize(var_value)
            os.environ[var_name] = sanitized_value

    @staticmethod
    def _sanitize(value: Optional[str]) -> str:
        """Sanitize the input value to prevent injection attacks."""
        if not isinstance(value, str):
            raise TypeError("Value must be a string.")
        return bytes(str(value), encoding='utf-8').decode('latin-1')

