def is_accessing_feature(user, feature_name):
    """
    Check if a user has access to the given CMS feature.

    Args:
        user: User object with roles and permissions
        feature_name: Name of the CMS feature

    Returns:
        bool: True if user has access, False otherwise
    """
    # Look up the CMS feature by name
    features = {feature['name']: feature for feature in FEATURES}
    if feature := features.get(feature_name):
        for role in user.roles:
            for perm in ROLES[role]['permissions']:
                if (
                    perm['action'] == 'view' or perm['action'] == 'edit'
                    and perm['feature_type'] == 'feature'
                    and perm['feature_names'].count(feature_name) > 0
                ):
                    return True
        # If no matching role found
        return False
    else:
        return False

def main():
    import sys
    from argparse import ArgumentParser

    # User input functions
    def create_user():
        username = input("Enter username: ")
        email = input("Enter email address: ")
        roles_input = input("Enter roles (comma-separated list): ").strip()
        permissions_input = input("Enter permissions (comma-separated list): ").strip()

        try:
            user = User.from_input(username, email, roles=roles_input.split(','),
                                   permissions=permissions_input.split(','))
            print(f"User {user.username} created successfully.")
            return user
        except Exception as e:
            print(f"Error creating user: {e}")
            return None

    def login(user):
        password = sys.stdin.readline().strip()
        if user.check_password(password):
            print("Welcome, user!")
            return True
        else:
            print("Invalid username or password.")
            return False

    def assign_role(user_to_assign, role_name):
        roles = {role['name']: role for role in ROLES}
        try:
            if user_to_assign.roles[-1]['name'] == role_name:
                current_roles = user_to_assign.roles[:-1]
                new_user = User.from_input(
                    **user_to_assign.dict(),
                    roles=current_roles
                )
                print(f"{new_user.username} has been assigned the {role_name} role.")
            else:
                print("You do not have permission to assign this role.")
        except Exception as e:
            print(f"Error assigning role: {e}")

    def access_feature(feature_name):
        try:
            if is_accessing_feature(current_user, feature_name):
                print(f"You have access to {feature_name}.")
                return True
            else:
                print(f"No access to {feature_name}.")
                return False
        except NameError as e:
            print(f"Feature '{feature_name}' not found: {e}")

    def exit():
        sys.exit()

    # Main execution flow
    parser = ArgumentParser(description='CMS Role-Based Access Control')
    parser.add_argument('--create-user', action='store_true',
                        help='Create a new user.')
    parser.add_argument('--login', action='store_true',
                        help='Login as an existing user.')
    parser.add_argument('--assign-role', action='store_true',
                        help='Assign a role to the current user.')
    parser.add_argument('--access-feature', type=str,
                        choices=FEATURES, default='Dashboard',
                        help='Access a specific CMS feature')
    parser.add_argument('--exit', action='store_true',
                        help='Exit the application')

    args = parser.parse_args()

    if args.create_user:
        user = create_user()
        if user:
            while True:
                print("\nMenu:")
                print("1. Create new user")
                print("2. Login as existing user")
                print("3. Assign role to current user")
                print("4. Access a CMS feature")
                print("5. Exit")
                choice = int(input())
                if choice == 1:
                    user = create_user()
                elif choice == 2:
                    login(user)
                elif choice == 3:
                    role_name = input("Enter role to assign: ").strip()
                    assign_role(user, role_name)
                else:
                    access_feature(feature_name=args.access_feature or 'Dashboard')
        else:
            print("No user created.")
    elif args.login:
        login(user)
    elif args.assign_role:
        role_name = input("Enter role name: ").strip()
        assign_role(user, role_name)
    elif args.access_feature:
        access_feature(args.access_feature)
    elif args.exit:
        exit()

if __name__ == "__main__":
    main()

import os
from cryptography.fernet import Fernet

# Generate a secret key
key = Fernet.generate_key()

# Create a Fernet cipher object
cipher = Fernet(key)

# Define API credentials
api_credentials = {
    "facebook": {"access_token": "YOUR_FACEBOOK_ACCESS_TOKEN"},
    "twitter": {"consumer_key": "YOUR_TWITTER_CONSUMER_KEY", "consumer_secret": "YOUR_TWITTER_CONSUMER_SECRET"},
}

# Encrypt API credentials
encrypted_credentials = {}
for platform, credentials in api_credentials.items():
    encrypted_credentials[platform] = {
        key: cipher.encrypt(value.encode()).decode()
        for key, value in credentials.items()
    }

# Store encrypted credentials in environment variables
for platform, credentials in encrypted_credentials.items():
    for key, value in credentials.items():
        os.environ[f"API_{platform}_{key}"] = value

# Function to decrypt API credentials
def decrypt_credentials():
    decrypted_credentials = {}
    for platform, credentials in encrypted_credentials.items():
        decrypted_credentials[platform] = {
            key: cipher.decrypt(value.encode()).decode()
            for key, value in credentials.items()
        }
    return decrypted_credentials

# Access decrypted credentials
decrypted_credentials = decrypt_credentials()
print(decrypted_credentials)

