import socket
import threading
from time import perf_counter

class SessionManager:
    def __init__(self):
        self.sessions = {}
        self.message_limit = 10  # Limit of 10 messages per second (MPS)
        self.last_message = None

    def increment_counters(self, client_id: str) -> int:
        """Increments the message count for a given client and returns how many messages were sent."""
        if client_id not in self.sessions:
            self.sessions[client_id] = {
                'message_count': 1,
                'messages_sent': {datetime.now(): 1}
            }

        # Update last_message to current time
        now = datetime.now()
        self.sessions[client_id]['messages_sent'][now] = self.sessions[client_id]['messages_sent'].get(now, 0) + 1

        if self.sessions[client_id]['message_count'] > self.message_limit:
            self._send_error_message(client_id)

        # Increment message count and return the new total
        self.sessions[client_id]['message_count'] += 1
        return self.sessions[client_id]['message_count']

    def _send_error_message(self, client_id: str):
        """Sends an HTTP error response to prevent further messages from this client."""
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            s.sendall(b'HTTP/1.0 429 Too Many Requests\r\nWebSocket (\x5Cn)\r\n\r\n')

import socket
import threading
import time

def ip_to_bytes(ip_str):
    if socket.getfamily(socket.inet_aton(ip_str)) == 'AF_INET':
        return struct.pack('!I', socket.inet_aton(ip_str))
    else:
        # Assume it's IPv6
        return struct.pack('!6', socket.inet_aton6(ip_str))

def handle_client_connection(conn, addr):
    try:
        ip_bytes = ip_to_bytes(addr[0])
        if ip_bytes in socket_dict:
            print(f"Processing request from {addr}")
            while True:
                try:
                    chunk = conn.recv(1024)
                except BrokenWindowException as e:
                    break  # End of stream
                if not chunk:
                    break
                processed_data += chunk
            response = "Processing complete. Check the result below."
            conn.sendall(response.encode())
        else:
            print(f"Skipping request from unknown IP {addr}")
    except Exception as e:
        print(f"Connection with {addr} failed: {e}")

def main():
    port = int(input("Enter the port number: "))
    rate = int(input("Enter the rate limit for processing requests: "))

    socket_dict = {}  # Maps IP bytes to list of connections
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server_socket.bind(('0.0.0.0', port))
    server_socket.listen(5)

    print(f"Server is listening on port {port}...")

    try:
        while True:
            conn, addr = server_socket.accept()
            thread = threading.Thread(target=handle_client_connection, args=(conn, addr))
            thread.start()

            # Wait for 'rate' number of connections before accepting new ones
            time.sleep(rate)
    except KeyboardInterrupt:
        print("Server shutting down...")
    except Exception as e:
        print(f"An error occurred: {e}")

if __name__ == "__main__":
    main()

import os

def validate_file(filename, allowed_types):
    _, ext = os.path.splitext(filename)
    ext_lower = ext.strip().lower()

    for mime_type in allowed_types:
        parts = mime_type.split('/')
        type_ext = parts[-1].strip().lower()
        if type_ext == ext_lower:
            return True

    return False

