import os
from PyPDF2 import PdfReader

def validate_pdf(file_path):
    # Check if file exists
    if not os.path.exists(file_path):
        return False

    # Try to open and read the PDF file
    try:
        with open(file_path, 'rb') as f:
            pdf = PdfReader(f)
            for page in range(len(pdf.pages)):
                text = pdf.pages[page].extract_text()
                if not text:
                    return False
    except Exception as e:
        print(f"An error occurred: {e}")
        return False

    # Check if the PDF contains any invalid data (non-standard fonts, etc.)
    # This is a simple check and may need to be adjusted depending on your specific requirements
    try:
        import matplotlib.font_manager as fm
        font = pdf.pages[0].get_font(f"StandardFont").get_name()
        if not font in ["Arial", "Times New Roman"]:
            return False
    except Exception as e:
        print(f"An error occurred: {e}")
        return False

    # Check if the PDF is not empty and contains at least one page with text content
    if pdf.num_pages == 0 or all(page.extract_text() for page in pdf.pages) == "":
        return False

    return True

# Example usage:
file_path = "path_to_your_pdf_file.pdf"
if validate_pdf(file_path):
    print(f"The PDF file is valid.")
else:
    print(f"The PDF file is not valid.")

