from collections import deque

def handle_queue(max_capacity, queue):
    current_length = len(queue)

    if current_length == max_capacity:
        raise OverflowError("Queue has reached its maximum capacity.")

    # Dequeue operation with check for underflow
    if queue:
        return queue.popleft()
    else:
        # Optionally handle underflow case
        pass  # or log a warning, etc.

# Example usage:

max容量 = 5

