# Enqueue elements only if there's space
try:
    if len(queue) < max容量:
        new_element = ...
        handle_queue(max容量, queue)
        queue.append(new_element)
    else:
        raise OverflowError("Queue is full; cannot add more elements.")
except OverflowError as e:
    print(f"Overflow error occurred: {e}")

# Dequeue operation with check for underflow
try:
    result = handle_queue(max容量, queue)
    print(result)
except OverflowError as e:
