import sqlite3
from sqlite3 import Error

def create_connection():
    conn = None;
    try:
        # Create a connection to the SQLite database
        conn = sqlite3.connect(':memory:')  # You could also specify a file path here
        print(f'Successful connection with sqlite version {sqlite3.version}')
    except Error as e:
        print(e)

    if conn:
        return conn
    return None

def create_table(conn):
    try:
        query = """CREATE TABLE IF NOT EXISTS prices (id INTEGER PRIMARY KEY, price REAL NOT NULL);"""
        cursor = conn.cursor()
        cursor.execute(query)
        print("Table created successfully")
    except Error as e:
        print(e)

def insert_price(conn, price):
    try:
        query = """INSERT INTO prices (price) VALUES (?);"""
        cursor = conn.cursor()
        cursor.execute(query, (price,))
        conn.commit()
        print("Price inserted successfully")
    except Error as e:
        print(e)

def fetch_price(conn):
    try:
        query = """SELECT price FROM prices ORDER BY id DESC LIMIT 1;""" # Fetch the latest price
        cursor = conn.cursor()
        cursor.execute(query)
        row = cursor.fetchone()
        if row is not None:
            return row[0]
    except Error as e:
        print(e)

def check_price(new_price):
    # Connect to the database and create table if it doesn't exist
    conn = create_connection()
    create_table(conn)

    # Fetch the latest price from the database
    old_price = fetch_price(conn)

    if old_price is None:
        insert_price(conn, new_price)  # If there's no stored price, just insert the new one
    else:
        percentage_change = abs((new_price - old_price) / ((old_price + new_price) / 2)) * 100  # Calculate % change

        if percentage_change > 10.0:  # If the price has changed by more than 10%, raise an error
            print("Price manipulation detected!")
            return False

        insert_price(conn, new_price)  # If the price change is within limits, update it

    conn.close()  # Close database connection
    return True

import inspect

def validate_kwargs(kwargs, defaults):
    """
    Validates the keyword arguments against predefined defaults and their expected types.

    Args:
        kwargs (dict): Dictionary of keyword arguments.
        defaults (dict): Dictionary defining default values for each key.

    Raises:
        ValueError: If an unexpected keyword argument is provided.
        TypeError: If a keyword's value does not match its expected type as per defaults.
    """
    # Check for unexpected keywords
    for key in kwargs:
        if inspect.iskeyword(key) or (key == '__builtins__'):
            continue  # Skip built-in functions and other reserved keywords
        if key not in defaults:
            raise ValueError(f"Unexpected keyword argument: {key}")

    # Check each default's expected type against provided value, including None checks
    for key, expected_type in defaults.items():
        actual_value = kwargs.get(key)

        if isinstance(actual_value, (str, bytes)) and not isinstance(expected_type, str):
            raise TypeError(f"String value assigned to {key} which is not a string type")

        # Ensure the provided value matches the expected type
        if actual_value is None:
            if expected_type != inspect._empty:
                # If default is inspect._empty (which represents no default), allow it only if user didn't provide one
                if key in kwargs:
                    raise TypeError(f"Cannot assign {key} when it has a default of {expected_type}")
        else:
            if not isinstance(actual_value, expected_type):
                raise TypeError(f"Expected {expected_type.__name__} for {key}, got {type(actual_value).__name__}")

    # Additional type checks for kwargs that do not have defaults (if their types are known elsewhere)
    # Note: Without function signature or more context, this is a simplified check
    for key, value in kwargs.items():
        if key in defaults:
            continue  # Type already checked against default

        if inspect.iskeyword(key) or (key == '__builtins__'):
            continue  # Skip reserved keywords

        if isinstance(value, str):
            expected_type = type(expected_type) if 'expected_type' in locals() else None
            if not expected_type and value.lower() != 'true':
                raise ValueError(f"String values for {key} are not allowed unless it's a boolean 'true'")

        # This part is simplified; actual type checking should depend on the function's signature or other known information

import threading
import queue
from typing import Dict

class SessionManager:
    def __init__(self):
        self.sessions = {}
        self.lock = threading.Lock()

    def add_session(self, session_id: str, callback) -> None:
        with self.lock:
            if session_id not in self.sessions:
                self.sessions[session_id] = []

    def start_session(self, session_id: str, callback):
        with self.lock:
            if session_id not in self.sessions:
                return False
            if len(self.sessions[session_id]) < 5: # max 5 concurrent sessions
                self.sessions[session_id].append(callback)
                return True
            return False

    def start_session_concurrently(self, session_id: str, callbacks):
        with self.lock:
            if session_id not in self.sessions:
                self.sessions[session_id] = []
            for callback in callbacks[:5]: # max 5 concurrent sessions
                self.sessions[session_id].append(callback)

    def stop_session(self, session_id: str) -> None:
        with self.lock:
            if session_id in self.sessions:
                del self.sessions[session_id]

class SessionManagerThread(threading.Thread):
    def __init__(self, manager: SessionManager, queue: queue.Queue):
        super(SessionManagerThread, self).__init__()
        self.manager = manager
        self.queue = queue

    def run(self) -> None:
        while True:
            session_id = self.queue.get()
            if session_id is None:
                break
            callback = self.manager.sessions[session_id].pop(0)
            print(f"Running {callback.__name__}")
            # Add your logic to handle the callback here
            callback()

def main():
    manager = SessionManager()

    def callback1() -> None:
        print("Callback 1")

    def callback2() -> None:
        print("Callback 2")

    def callback3() -> None:
        print("Callback 3")

    queue = queue.Queue()
    thread = SessionManagerThread(manager, queue)

    manager.add_session('session1', callback1)
    manager.add_session('session2', callback2)
    manager.add_session('session3', callback3)

    for _ in range(5):
        queue.put('session1')

    for _ in range(10):
        queue.put('session2')

    for _ in range(15):
        queue.put('session3')

    thread.start()

    # Wait until the thread finishes
    thread.join()

if __name__ == "__main__":
    main()

