import os
import pandas as pd

class DataProtection:
    def __init__(self, database_file):
        self.database_file = database_file

    def create_database(self):
        # Create a new encrypted SQLite database
        os.system(f"sqlite3 {self.database_file} .mode csv")

    def add_data(self, data):
        # Add data to the database while encrypting it
        df = pd.DataFrame(data)
        df.to_csv(self.database_file, index=False)

    def read_data(self):
        # Read data from the encrypted CSV file
        try:
            return pd.read_csv(self.database_file).values.tolist()
        except Exception as e:
            print(f"Error reading data: {e}")
            return None

    def delete_data(self, data_to_delete):
        # Delete data from the database while decrypting it
        df = pd.DataFrame(data_to_delete)
        df.to_csv(self.database_file, index=False)

