import re

def validate_shipping_address(address):
    # Regular expression for validating address format
    address_format = r"^\d{1,4} [\w\s]+,[a-zA-Z]{2} [\d{5}( -\d{4})?}"

    # Check if the address matches the regular expression pattern
    if re.match(address_format, address):
        return True
    else:
        return False

# Example usage:
address = "123 Main St, New York, NY 10001"
if validate_shipping_address(address):
    print("Valid shipping address")
else:
    print("Invalid shipping address")

class ShippingAddressValidator:
    def __init__(self):
        self.valid_states = ["AL", "AK", "AZ", "AR", "CA", "CO", "CT", "DE", "FL", "GA",
                             "HI", "ID", "IL", "IN", "IA", "KS", "KY", "LA", "ME", "MD",
                             "MA", "MI", "MN", "MS", "MO", "MT", "NE", "NV", "NH", "NJ",
                             "NM", "NY", "NC", "ND", "OH", "OK", "OR", "PA", "RI", "SC",
                             "SD", "TN", "TX", "UT", "VT", "VA", "WA", "WV", "WI", "WY"]

    def validate_state(self, state):
        return state in self.valid_states

    def validate_zip_code(self, zip_code):
        if len(zip_code) == 5:
            return True
        elif len(zip_code) == 9:
            return True
        else:
            return False

    def validate_shipping_address(self, address):
        # Split the address into lines
        lines = address.splitlines()

        # Check if the address contains a valid state and zip code
        for line in lines:
            if self.validate_state(line[-2:]):
                continue
            elif line == '':
                continue
            else:
                return False

        # Check if the last part of the address is a zip code
        for line in reversed(lines):
            if len(line) >= 5 and re.match("^\d{5}( -\d{4})?", line):
                break
        else:
            return False

        return True

# Example usage:
validator = ShippingAddressValidator()

address = "123 Main St, New York, NY 10001"
if validator.validate_shipping_address(address):
    print("Valid shipping address")
else:
    print("Invalid shipping address")

import threading

class DeadlockAvoider:
    def __init__(self, n_threads):
        self.n_threads = n_threads
        self.active_threads = set()
        self.active_locks = set()
        self.thread_order = []

    def acquire(self, lock):
        # Acquire the lock and add it to the list of active locks
        lock.acquire()
        self.active_locks.add(lock)

    def release(self, lock):
        # Release the lock and remove it from the list of active locks
        lock.release()
        self.active_locks.remove(lock)

    def get_next_thread(self):
        # Return the next thread in the list that has acquired a lock, or None if no such thread exists
        for i in range(len(self.thread_order)):
            if self.thread_order[i] in self.active_threads:
                return self.thread_order[i]
        return None

    def run(self):
        # Run the threads and avoid deadlocks by monitoring the number of active locks and threads
        for i in range(self.n_threads):
            thread = threading.Thread(target=self.run_thread, args=(i,))
            self.active_threads.add(thread)
            thread.start()
            if len(self.active_locks) > 2:
                # Detect deadlock and recover by breaking one of the involved threads or resources
                self.recover_from_deadlock()

    def run_thread(self, i):
        # Run a single thread and acquire locks as needed
        while True:
            lock = Lock()
            self.acquire(lock)
            try:
                # Do some work that requires the lock
                pass
            finally:
                self.release(lock)

    def recover_from_deadlock(self):
        # Recover from a deadlock by breaking one of the involved threads or resources
        for thread in self.active_threads:
            if not thread.is_alive():
                self.active_threads.remove(thread)
        for lock in self.active_locks:
            if lock.acquired():
                self.release(lock)

import hashlib

class Block:
    def __init__(self, previous_hash, transaction):
        self.transactions = transaction
        self.previous_hash = previous_hash
        string_to_hash = "".join(transaction) + previous_hash
        self.block_hash = hashlib.sha256(string_to_hash.encode()).hexdigest()

class Blockchain:
    def __init__(self):
        self.blocks = []

    def add_block(self, transaction):
        if len(self.blocks) == 0:
            new_block = Block("Genesis", transaction)
        else:
            previous_hash = self.blocks[-1].block_hash
            new_block = Block(previous_hash, transaction)

        self.blocks.append(new_block)

    def validate_chain(self):
        for i in range(1, len(self.blocks)):
            current = self.blocks[i].transactions
            previous = self.blocks[i-1]

            # Check if the hash of the current block is correct
            if current != previous.block_hash:
                return False

        return True

import time

class QueryBatcher:
    def __init__(self, batch_size, interval):
        self.batch_size = batch_size
        self.interval = interval
        self.queries = []
        self.start_time = None

    def add_query(self, query):
        self.queries.append(query)
        if len(self.queries) == self.batch_size:
            self.batch_queries()
            self.queries = []

    def batch_queries(self):
        if self.start_time is None:
            self.start_time = time.time()

        while time.time() - self.start_time < self.interval:
            pass

        # Send the batch of queries here
        print("Sending batch of queries:", self.queries)

# Example usage:
batcher = QueryBatcher(batch_size=10, interval=5)

for i in range(100):
    batcher.add_query(i)

# Ensure any remaining queries are sent
batcher.batch_queries()

