    """Sorts a list of dictionaries by the 'relevance' key in descending order."""

    # The sorted function returns a new sorted list from the elements of any sequence.
    # By default, it sorts in ascending order. We can use the reverse=True argument to sort in descending order.
    return sorted(results, key = lambda k: k['relevance'], reverse=True)

