def validate_webhook_signature(url, signature):
    headers = {
        'X-Forwarded-With': f'{signature}|something|extra'
    }

    try:
        response = requests.get(url, headers=headers, timeout=10)
        if response.status_code != 200:
            return None
        if len(response.text) > response_threshold:
            return None
        extracted_signature = response.text.split('|')[0]
        if extracted_signature == signature:
            return True
        else:
            return False
    except requests.exceptions.RequestException as e:
        print(f"Request failed: {str(e)}")
        return None

def get_webhook_response(url, headers, max_retries=5):
    for attempt in range(1, max_retries + 1):
        delay = (attempt - 1) * 2
        try:
            response = requests.get(
                url,
                headers=headers,
                timeout=10,
                params={'delay': delay}
            )
            if response.status_code == 200 and len(response.text) > 0:
                return True, response.text.split('|')[0]
        except requests.exceptions.RequestException as e:
            print(f"Attempt {attempt} failed: {str(e)}")
    raise Exception(f"Webhook request failed after {max_retries} attempts for URL {url}")

