import os
import re

def sanitize_cron_line(line):
    # Define allowed characters: letters, digits, :, , *, ?, space
    allowed_chars = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789:,*? ')
    sanitized = []
    for char in line:
        if char in allowed_chars or (char == '"' and len(sanitized) > 0):
            sanitized.append(char)
        elif char.isspace():
            if sanitized and sanitized[-1] != '"':
                sanitized.append(' ')
    return ''.join(sanitized)

def process_cron_line(line):
    # Remove newlines to handle multi-line cron expressions
    line = line.replace('\n', '')

    # Split into individual components based on commas, stripping whitespace from each part
    components = [comp.strip() for comp in line.split(',')]

    # Process each component with dc to evaluate safely
    try:
        result = os.system('dc -e "10dio%i"|' % (component), shell=True)
        return str(result)
    except Exception as e:
        print(f"Error evaluating cron expression: {e}")
        return None

def execute_cron_file(cron_path):
    # Read each line from the cron file
    with open(cron_path, 'r') as f:
        for line in f:
            sanitized_line = sanitize_cron_line(line.strip())
            result = process_cron_line(sanitized_line)

            if result is not None:
                print(f"Result of executing {line.strip()} is: {result}")
            else:
