import time

class WebhookRateLimiter:
    def __init__(self, max_requests_per_second):
        self.max_requests_per_second = max_requests_per_second
        self.last_request_time = 0
        self.num_requests = 0

    def check_rate(self):
        current_time = time.time()
        elapsed_time = current_time - self.last_request_time

        if elapsed_time < 1:
            return False, "Rate limit exceeded"

        self.num_requests += 1
        self.last_request_time = current_time

        if self.num_requests > self.max_requests_per_second:
            return False, "Rate limit exceeded"

        return True, None

import socket
import threading

class Server:
    def __init__(self, host='localhost', port=9999):
        self.host = host
        self.port = port
        self.server = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.clients = []
        self.lock = threading.Lock()

    def broadcast(self, message):
        with self.lock:
            for client in self.clients:
                client.send(message.encode())

    def handle_client(self, client_socket):
        while True:
            try:
                message = client_socket.recv(1024).decode()
                if message == 'quit':
                    break
                self.broadcast(message)
            except Exception as e:
                print(e)
                break

    def start(self):
        self.server.bind((self.host, self.port))
        self.server.listen()

        print(f"Server listening on {self.host}:{self.port}")

        while True:
            client_socket, address = self.server.accept()
            with self.lock:
                self.clients.append(client_socket)

            print(f"New connection from {address[0]}:{address[1]}")

            thread = threading.Thread(target=self.handle_client, args=(client_socket,))
            thread.start()

if __name__ == "__main__":
    server = Server()
    server.start()

def handle_null_pointer_exception(func):
    """
    Decorator function to handle null pointer exceptions in a Python function.

    Args:
        func: The function to decorate.

    Returns:
        A new function that wraps the decorated function and handles null pointer exceptions.
    """

    def wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except TypeError as e:
            if "null pointer" in str(e):
                print("Null pointer exception encountered.")
                return None
            else:
                raise

    return wrapper

class SmartContract:
    def __init__(self):
        self.balance = 0

    def deposit(self, amount):
        if amount > 0:
            self.balance += amount
            return True
        else:
            return False

    def withdraw(self, amount):
        if self.balance >= amount:
            self.balance -= amount
            return True
        else:
            return False

