import queue
import time
import sys

class PipelineMonitor:
    def __init__(self, pipeline_queue):
        self.pipeline_queue = pipeline_queue

    def monitor_pipeline(self):
        interval = 5  # Monitor every 5 seconds
        start_time = time.time()
        total_time = 0.0

        try:
            while True:
                elapsed_time = (time.time() - start_time) / 60
                percentage = ((time.time() - start_time) / (end_time - start_time)) * 100 if (end_time - start_time) != 0 else 0

                print(f"Pipeline state: {self.pipeline_queue.get_nowait()}")
                print(f"Time elapsed: {elapsed_time:.2f} minutes, {percentage:.1f}% complete")

                time.sleep(interval)
        except KeyboardInterrupt:
            print("\nMonitoring stopped.")
        except queue.Empty as e:
            print(f"\nQueue is empty at {e}.")
        except Exception as e:
            print(f"Error monitoring pipeline: {str(e)}")

def simulate_pipeline(start_time, end_time):
    # Simulate data flowing through the pipeline
    current_time = start_time
    while True:
        if time.time() > end_time - 10:
            break

        if not queue.Queue.empty():
            item = queue.Queue.get(queue.Queue())
            print(f"Data {item} has entered the pipeline at {current_time}")

        # Wait for some interval, simulating processing
        if current_time < end_time:
            time.sleep(random.uniform(1, 2))
        else:
            break

        current_time += random.uniform(0.5, 1)

def main():
    try:
        pipeline_queue = queue.Queue()
        monitor_thread = None

        # Create and start the monitoring thread
        monitor_thread = PipelineMonitor(pipeline_queue)
        monitor_thread_thread = threading.Thread(target=monitor_pipeline)
        monitor_thread_thread.start()

        print("Pipeline simulation starting...")
        simulate_pipeline(time.time(), time.time() + 5)

        print("\nPipeline simulation completed.\n")
        print("Monitoring pipeline performance...\n")

    except Exception as e:
        print(f"An error occurred: {str(e)}\nAborting monitoring.")

    finally:
        if monitor_thread_thread is not None and monitor_thread_thread.is_alive():
            monitor_thread_thread.join()

if __name__ == "__main__":
    main()

