transactions = {}

# Function to prevent double charging
def prevent_double_charging(transaction_id, timestamp):
    if transaction_id in transactions:
        # Check if the transaction has been made within a certain timeframe (e.g., 24 hours)
        if timestamp - transactions[transaction_id] < 86400:
            print("Double charging detected!")
            return False
    else:
        transactions[transaction_id] = timestamp
    return True

