import json
import hashlib

def calculate_hash(filename):
    """Calculate the SHA-256 hash of a file."""
    hash_sha256 = hashlib.sha256()
    with open(filename, "rb") as f:
        for chunk in iter(lambda: f.read(4096), b""):
            hash_sha256.update(chunk)
    return hash_sha256.hexdigest()

def verify_translation_file(filename, expected_hash):
    """Verify the integrity of a translation file."""
    try:
        # Load the JSON file to make sure it's valid and can be parsed
        with open(filename, "r", encoding="utf-8") as f:
            json.load(f)

        # Calculate its hash and compare it to the expected value
        file_hash = calculate_hash(filename)
        if file_hash == expected_hash:
            print("File integrity verified.")
        else:
            print("Warning! File has been modified or is corrupted.")
    except (IOError, json.JSONDecodeError):
        print("Error while processing the file.")

# Usage example:
