class AccessLevel:
    """Represents an access level with a name and set of allowed resources."""

    def __init__(self, name):
        self.name = name
        self.allowed_resources = []

    def add_resource(self, resource):
        """Adds a resource to the list of allowed resources for this level."""
        if resource not in self.allowed_resources:
            self.allowed_resources.append(resource)


class AccessControlSystem:
    """Manages access levels and their corresponding permissions."""

    def __init__(self):
        self.access_levels = {}

    def add_access_level(self, name, allowed_resources):
        """Adds a new access level with the given resources."""
        if name not in self.access_levels:
            self.access_levels[name] = AccessLevel(name)

    def grant_permission(self, user_id, resource_name, access_level):
        """Grants permission to access a specific resource for a given user and access level."""
        if access_level.name in self.access_levels:
            if resource_name in self.access_levels[access_level.name].allowed_resources:
                print(f"Permission granted to {user_id} at {access_level.name} level.")
            else:
                print(f"{resource_name} is not accessible at {access_level.name} level.")

    def revoke_permission(self, user_id, resource_name, access_level):
        """Revoke permission from accessing a specific resource for a given user and access level."""
        if access_level.name in self.access_levels:
            if resource_name in self.access_levels[access_level.name].allowed_resources:
                print(f"Permission revoked for {user_id} at {access_level.name} level.")
            else:
                print(f"{resource_name} was never accessible at {access_level.name} level.")

# Example usage
system = AccessControlSystem()

# Add access levels with resources
system.add_access_level("Admin", ["all_resources"])
system.add_access_level("Moderator", ["read_resource1", "read_resource2"])
system.add_access_level("User", ["read_resource3"])

# Grant permissions
system.grant_permission(1, "read_resource1", system.access_levels["Moderator"])
system.grant_permission(1, "read_resource3", system.access_levels["User"])

# Revoke permissions
system.revoke_permission(1, "read_resource1", system.access_levels["Moderator"])

