import threading
from typing import Any, Callable, List

class Event:
    """Represents an event in the queue."""
    def __init__(self, name: str, data: Any):
        self.name = name
        self.data = data

class PriorityQueue:
    """Manages a priority-based event queue."""
    def __init__(self):
        self.queue = []
        self.lock = threading.Lock()

    def add_event(self, event: Event, priority: int):
        """Adds an event to the queue with a specified priority."""
        with self.lock:
            self.queue.append((priority, event))
        self.queue.sort(key=lambda x: x[0], reverse=True)

    def remove_event(self) -> Event:
        """Removes and returns the highest-priority event from the queue."""
        if not self.queue:
            raise Exception("Queue is empty")
        with self.lock:
            priority, event = self.queue.pop(0)
        return event

class EventProcessor:
    """Processes events in the queue."""
    def __init__(self):
        self.queue = PriorityQueue()

    def process_events(self, callback: Callable[[Event], None]):
        """Process all events in the queue using a provided callback function."""
        while True:
            try:
                event = self.queue.remove_event()
                callback(event)
            except Exception as e:
                print(f"Error processing event: {e}")

def main():
    # Create an event processor
    processor = EventProcessor()

    # Define events and their data
    events = [
        Event("Event 1", "This is event 1"),
        Event("Event 2", "This is event 2"),
        Event("Event 3", "This is event 3")
    ]

    # Add events to the queue with different priorities
    processor.queue.add_event(events[0], 5)
    processor.queue.add_event(events[1], 3)
    processor.queue.add_event(events[2], 1)

    # Define an example callback function
    def print_event(event: Event):
        print(f"Processing event {event.name} with data: {event.data}")

    # Process events in the queue
    processor.process_events(print_event)

if __name__ == "__main__":
    main()

