def rotate_char(c, rotation):
    if c.isupper():
        return chr((ord(c) - ord('A') + rotation) % 26 + ord('A'))
    elif c.islower():
        return chr((ord(c) - ord('a') + rotation) % 26 + ord('a'))
    else:
        return c

def rotate_string(s, rotation):
    result = ""
    for char in s:
        result += rotate_char(char, rotation)
    return result

