import heapq

class PriorityQueue(object):
    def __init__(self):
        self._queue = []
        self._index = 0

    def push(self, item, priority):
        # The pair is in the format of (-priority, index, item) so that heapq can compare tuples properly.
        heapq.heappush(self._queue, (-priority, self._index, item))
        self._index += 1

    def pop(self):
        if self._queue:
            return heapq.heappop(self._queue)[-1]  # return the actual item
        else:
            raise Exception('Trying to pop from empty priority queue')

    def is_empty(self):
        return not self._queue

# Testing the PriorityQueue:
pq = PriorityQueue()
pq.push("item1", 3)
pq.push("item2", 4)
pq.push("item3", 5)

while not pq.is_empty():
    print(pq.pop())

