import json
import re

class ConfigValidator:
    def __init__(self, config_file):
        self.config_file = config_file
        self.valid_config = {
            'section1': {
                'key1': {'type': 'int', 'min_value': 0, 'max_value': 10},
                'key2': {'type': 'str', 'pattern': r'^[a-zA-Z]+$'}
            },
            'section2': {
                'key3': {'type': 'float', 'min_value': 0.0, 'max_value': 100.0}
            }
        }

    def validate_config(self):
        try:
            with open(self.config_file, 'r') as file:
                config = json.load(file)
        except FileNotFoundError:
            print(f"Error: The configuration file {self.config_file} does not exist.")
            return False
        except json.JSONDecodeError:
            print(f"Error: Unable to parse the configuration file {self.config_file}.")
            return False

        for section, keys in config.items():
            if section not in self.valid_config:
                print(f"Error: Unknown configuration section '{section}' found in file {self.config_file}.")
                return False
            for key, value in keys.items():
                required_key = f"{section}.{key}"
                if value.get('required', False):
                    if 'value' not in value or value['value'] is None:
                        print(f"Error: Missing required key-value pair '{required_key}' found in file {self.config_file}.")
                        return False

                # Validate int values
                if isinstance(value, dict) and 'type' in value and value['type'] == 'int':
                    if value.get('min_value', None) and value['value'] < value['min_value']:
                        print(f"Error: Invalid integer value '{value['value']}' found in section '{section}' of file {self.config_file}. Value should be greater than or equal to {value['min_value']}.")
                        return False
                    if value.get('max_value', None) and value['value'] > value['max_value']:
                        print(f"Error: Invalid integer value '{value['value']}' found in section '{section}' of file {self.config_file}. Value should be less than or equal to {value['max_value']}.")

                # Validate float values
                if isinstance(value, dict) and 'type' in value and value['type'] == 'float':
                    if value.get('min_value', None) and value['value'] < value['min_value']:
                        print(f"Error: Invalid floating point value '{value['value']}' found in section '{section}' of file {self.config_file}. Value should be greater than or equal to {value['min_value']}.")
                        return False
                    if value.get('max_value', None) and value['value'] > value['max_value']:
                        print(f"Error: Invalid floating point value '{value['value']}' found in section '{section}' of file {self.config_file}. Value should be less than or equal to {value['max_value']}.")

                # Validate string values
                if isinstance(value, dict) and 'type' in value and value['type'] == 'str':
                    pattern = re.compile(value.get('pattern', r'^.*$'))
                    if not pattern.match(str(value['value'])):
                        print(f"Error: Invalid string value '{value['value']}' found in section '{section}' of file {self.config_file}. Value should match the given pattern.")
                        return False

        print("Configuration validation complete.")
        return True


# Example usage
validator = ConfigValidator('config.json')
if validator.validate_config():
    print("Validation successful. Configuration is valid.")
else:
    print("Validation failed. Configuration is invalid.")

