import os
import shutil
import filecmp

def create_backup(src, dst):
    try:
        shutil.copytree(src, dst)
        print("Backup created successfully.")
    except Exception as e:
        print(f"An error occurred while creating the backup: {e}")

def restore_backup(src, dst):
    try:
        if os.path.exists(dst):
            shutil.rmtree(dst)
        shutil.copytree(src, dst)
        print("Restore completed successfully.")
    except Exception as e:
        print(f"An error occurred while restoring the backup: {e}")

def test_backup_restore(src, dst):
    create_backup(src, dst)
    restore_backup(dst, src+"_restored")
    if filecmp.dircmp(src, src+"_restored").compare() == []:
        print("Backup and Restore Test Passed.")
    else:
        print("Backup and Restore Test Failed.")

