users = {
    "user1": generate_password_hash("password1"),  # Always store hashed passwords
    "user2": generate_password_hash("password2")
}

def authenticate(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth = request.authorization
        if not auth or not auth.username in users or not check_password_hash(users[auth.username], auth.password):
            return "Authentication failed", 403
        return f(*args, **kwargs)
    return decorated

