import multiprocessing
import os

class ThreadLogger:
    def __init__(self):
        self._finish = object()  # To prevent multiple trace functions from exiting
        self._local = multiprocessing.Array('c', [os.getpid()])

    def _thread_started(self, frame, arg_self=None, arg Locals=None):
        self._finish.__enter__()
        super().__call__(frame, arg_self, arg_locals)

    def __call__(self, frame, arg_self=None, arg_locals=None):
        # Track entering the thread
        self._local[0] = id(frame)
        return object()

    def __exit__(self, type, value, traceback):
        self._finish.__exit__()

    def _finish(self, frame, type, value, traceback):
        self._finish.__exit__(frame, type, value, traceback)

    def trace(self):
        current = multiprocessing.current_process()._thread_trace
        if current is not object:
            raise RuntimeError("Cannot use this tracing method more than once")

        multiprocessing.settrace(self)
        os.getpid()

# Create an instance of the logger
logger = ThreadLogger()

# Apply the custom thread trace function globally when needed
# Example usage would be: logger.trace()

import rsa
import binascii

# Step 1: Generate an RSA key pair of 2048 bits
key = rsa.key.RSAPrime(2048)
public, private = key.split()  # Assuming 'split' is a method to get public and private keys as strings

# Step 2: Define the sign function
def sign(data):
    if isinstance(data, str):
        try:
            data_bytes = binascii.a2b_base64(data.encode())
        except (binascii.BinasciiError, ValueError, TypeError):
            raise ValueError("Invalid base64 string provided for signing")
    else:
        data_bytes = data

    # Use the private key to sign the data
    try:
        signature = private.sign(data_bytes)
    except Exception as e:
        print(f"An error occurred during signing: {e}")
        raise
    return signature

# Step 3: Define the verify function
def verify(signature, data):
    try:
        public_key = rsa.PublicKey(public)  # Create a PublicKey object from the public key string
        valid = public_key.verify(signature, data)
        if not valid:
            print("Invalid signature")
            return False
    except Exception as e:
        print(f"An error occurred during verification: {e}")
        raise
    return True

# Example usage:

if __name__ == "__main__":
    # Generate key pair (this step is done once)

    # Sign data
    message = b"This is a test message."
    signature = sign(message)
    print("Signature:", signature.hex())

    # Verify the signature
    if verify(signature, message):
        print("Signature verified successfully.")
    else:
        print("Signature verification failed.")

import re

def is_valid_filename(filename):
    # Regular expression pattern to match valid filenames
    pattern = r'^[a-zA-Z_\x7f-\xff][a-zA-Z0-9_\x5F-\x7E]{1,}[\._\\\\?]*$'

    if not filename:
        return False

    if re.match(pattern, filename):
        return True
    else:
        return False

