from git import Repo
import os

class GitConfigManager(object):
    def __init__(self, repo_path=None, remote_repo_url=None):
        self.local_repo = None
        if repo_path is not None:
            try:
                self.local_repo = Repo(repo_path)
                assert not self.local_repo.bare
            except:
                print('Repository does not exist or is bare')

        if remote_repo_url is not None and self.local_repo is None:
            try:
                self.local_repo = Repo.clone_from(remote_repo_url, repo_path)
            except Exception as error:
                print('Failed to clone repository', str(error))

    def add_config(self, config_file):
        if os.path.isfile(config_file):
            self.local_repo.index.add([config_file])
        else: 
            print("Error: %s does not appear to be a valid file!" % config_file)

    def commit_changes(self, commit_message='Update Config File'):
        if len(self.local_repo.index.diff(self.local_repo.head.commit)) != 0:
            self.local_repo.index.commit(commit_message)

    def push_changes(self, remote_name='origin', branch_name='master'):
        origin = self.local_repo.remote(remote_name)
        origin.push(branch_name)

# Usage
gitConfigManager = GitConfigManager('path/to/your/repo') # initialize git repo

gitConfigManager.add_config('path/to/your/config/file') # add config file to staging area
gitConfigManager.commit_changes() # commit changes locally
gitConfigManager.push_changes() # push the committed change to remote repository

