import pip
import requests
from requests.exceptions import RequestException

def fetch_dependencies():
    try:
        # Fetch all installed packages and their versions
        result = pip list()
        return [package.split() for package in result.split('\n') if len(package) > 0]
    except Exception as e:
        print(f"Error fetching dependencies: {e}")
        return []

def check_dependencies_for_vulnerabilities(dependencies):
    vulnerabilities_url = "https://pypi.org/tags/cve-2023-12345/JSON"

    # Fetch all known vulnerabilities
    try:
        response = requests.get(vulnerabilities_url)
        if response.status_code == 200:
            data = response.json()
            known_vulnerabilities = set(item['CVE_ID'] for item in data['tags'])
        else:
            print(f"Error fetching vulnerabilities: {response.status_code}")
            return []
    except RequestException as e:
        print(f"Request failed: {e}")
        return []

    # Check each dependency
    results = []
    for package_info in dependencies:
        if len(package_info) < 2:
            continue

        package_name = package_info[0].lower()
        version = '-'.join(package_info[1:])

        try:
            response = requests.get(f'https://pypi.org/p{i}/json', timeout=30)
            if response.status_code == 200 and response.json():
                pypi_data = response.json()
                package_vulnerabilities = [item['CVE_ID'] for item in pypi_data.get('tags', []) 
                                         if item.get('name') in package_name]

                if any(cve in known_vulnerabilities for cve in package_vulnerabilities):
                    results.append((package_name, version))
        except RequestException as e:
            print(f"Error checking {package_name} ({version}): {e}")

    return results

def main():
    dependencies = fetch_dependencies()
    vulnerabilities = check_dependencies_for_vulnerabilities(dependencies)

    if len(vulnerabilities) > 0:
        for package, version in vulnerabilities:
            print(f"Warning: Package {package} v{version} has known vulnerabilities.")

