import re

def validate_address(address):
    # Check if the address is empty or None
    if not address:
        return False

    # Check if the address is a valid email address
    if re.match(r'^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,6}$', address):
        return False

    # Check if the address is a valid postal code
    if re.match(r'^\d{5}$', address):
        return False

    # Check if the address is a valid street name and number
    if re.match(r'^[A-Za-z0-9 ]+$', address):
        return False

    # If we get to this point, the address is likely valid
    return True

