import requests

class PushNotificationHandler:
    def __init__(self, api_key):
        self.api_key = api_key

    def send_notification(self, message):
        url = f"https://api.pushnotifications.com/messages?apiKey={self.api_key}"
        data = {
            "message": message
        }
        response = requests.post(url, json=data)
        return response.json()

if __name__ == "__main__":
    handler = PushNotificationHandler("your-api-key")
    notification = handler.send_notification("Hello from Python!")
    print(notification)
