import logging
import psutil
from datetime import datetime

# Set up logging configuration
logging.basicConfig(format='%(asctime)s - %(levelname)s - %(message)s', level=logging.INFO)

class TenantMonitor:
    def __init__(self):
        self.log_file = 'tenant_usage_log.txt'
        selfTenantId = None

    def get_system_resources(self):
        resources = {}
        for proc in psutil.process_iter(['pid', 'name', 'memory_percent']):
            try:
                info = proc.info
                resources[info['pid']] = {'process_name': info['name'], 'memory_usage': info['memory_percent']}
            except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
                pass
        return resources

    def monitor_tenant(self, tenant_id):
        self.TenantId = tenant_id
        logging.info(f'Monitoring Tenant {tenant_id}...')
        system_resources = self.get_system_resources()

        while True:
            try:
                # Get current CPU usage for the tenant
                cpu_usage = psutil.cpu_percent()
                memory_usage = psutil.virtual_memory().percent

                # Log usage metrics to file and console
                logging.info(f'Tenant {tenant_id} - CPU: {cpu_usage}% | Memory: {memory_usage}%')
                with open(self.log_file, 'a') as log_file:
                    log_file.write(f'{datetime.now()} - Tenant {tenant_id} - CPU: {cpu_usage}% | Memory: {memory_usage}%\n')

            except (psutil.NoSuchProcess, psutil.AccessDenied):
                logging.error(f'Failed to get system resources for Tenant {tenant_id}')

            # Sleep for 1 second before checking again
            time.sleep(1)

    def start_monitoring(self, tenant_id):
        self.monitor_tenant(tenant_id)


# Example usage:
if __name__ == '__main__':
    monitor = TenantMonitor()
    monitor.start_monitoring('Tenant-123')

