import time
from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity):
        self.cache = OrderedDict()
        self.capacity = capacity

    def get(self, key):
        try:
            value = self.cache.pop(key)
            self.cache[key] = value  # Update LRU order
            if 'expire_time' in value and time.time() > value['expire_time']:
                del self.cache[key]
                return None   # Entry has expired
            else:
                return value['value']
        except KeyError:
            return None     # No such entry

    def set(self, key, value, timeout=None):
        if len(self.cache) >= self.capacity:
            self.cache.popitem(last=False)   # Evict LRU item when capacity is reached
        expire_time = time.time() + timeout if timeout else None
        self.cache[key] = {'value': value, 'expire_time': expire_time}

    def remove(self, key):
        try:
            del self.cache[key]
        except KeyError:
            pass     # No such entry

# Usage
cache = LRUCache(100)
cache.set('my_key', 'my_value', timeout=60)   # Expires after 60 seconds

def text_search(text, keyword):
    # Sanitize input to avoid security vulnerabilities such as command injection or regex denial of service (ReDoS)
    sanitized_keyword = keyword.replace("*", "\\*").replace(".", "\\.").replace("[", "\\[").replace("]", "\\]")

    # Perform a case insensitive search on the text using the sanitized keyword
    if sanitized_keyword in text.lower():
        return True
    else:
        return False

