import xml.etree.ElementTree as ET

class Serializer:
    def __init__(self):
        self.root = ET.Element("objects")

    def serialize_obj(self, obj, element=None):
        if element is None:
            element = ET.SubElement(self.root, "object", attrib={"class": obj.__class__.__name__})

        for key, value in vars(obj).items():
            child = ET.SubElement(element, "attribute", attrib={"name": key})
            if hasattr(value, '__dict__'):  # If the attribute is an object itself
                self.serialize_obj(value, child)
            else:
                child.text = str(value)
        return element

    def serialize(self, obj):
        root_element = self.serialize_obj(obj)
        return ET.tostring(root_element, encoding='unicode')

