import time

class RateLimiter:
    def __init__(self, limit):
        self.limit = limit
        self.tokens = 0.0
        self.last_check = time.time()

    def consume(self, tokens):
        if self.tokens < self.limit:
            now = time.time()
            # Add tokens for elapsed time since last call
            self.tokens += (now - self.last_check) * self.limit
            self.tokens = min(self.tokens, self.limit)
            self.last_check = now
        if self.tokens >= tokens:
            self.tokens -= tokens
            return True
        else:
            return False

# Use the RateLimiter for rate limiting model inference. For example, let's say our limit is 5 inferences per second
rl = RateLimiter(5)

while True:
    # consume one token for each inference
    if rl.consume(1):
        print("Inference made.")
    else:
        print("Too many inferences. Please wait...")
    time.sleep(0.2)  # Simulate delay in real-world application

