from flask import Flask, request, jsonify
from functools import wraps
from itsdangerous import TimedJSONWebSignatureSerializer as Serializer, BadSignature, SignatureExpired

app = Flask(__name__)
app.config['SECRET_KEY'] = 'your-secret-key'  # Change this to your own secret key!

# A decorator function for checking if a user is logged in
def login_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization')
        if not token:
            return jsonify({'message': 'Token is missing!'}), 403
        try:
            s = Serializer(app.config['SECRET_KEY'])
            data = s.loads(token)
        except SignatureExpired:
            return jsonify({'message': 'The token is expired!'}), 401
        except BadSignature:
            return jsonify({'message': 'The token is invalid!'}), 401
        return f(*args, **kwargs)
    return decorated

# Example API route which requires a user to be logged in
@app.route('/api/secure', methods=['GET'])
@login_required
def secure():
    # Return some secure data here...
    return jsonify({'data': 'This is some secret data!'}), 200

