import hashlib

# Define the hash function to use for password hashing
def hash_password(password):
  return hashlib.sha256(password.encode()).hexdigest()

# Define the salt to use for generating tokens
salt = b'this-is-a-salt'

# Define a function to generate a token for an IoT device
def generate_token(device_id):
  return hashlib.sha256(device_id.encode() + salt).hexdigest()

# Define a function to verify the token for an IoT device
def verify_token(device_id, token):
  expected_token = generate_token(device_id)
  return token == expected_token

from flask import Flask, jsonify, request

app = Flask(__name__)

# Sample in-memory data store (replace with a database in production)
users = [
    {"id": 1, "name": "John Doe", "email": "john@example.com"},
    {"id": 2, "name": "Jane Doe", "email": "jane@example.com"}
]

@app.route("/users", methods=["GET"])
def get_users():
    """Return a list of all users"""
    return jsonify(users)

@app.route("/users", methods=["POST"])
def create_user():
    """Create a new user"""
    data = request.get_json()
    if not data:
        return jsonify({"error": "Missing JSON in request"}), 400
    user_id = max(user["id"] for user in users) + 1
    user = {
        "id": user_id,
        "name": data["name"],
        "email": data["email"]
    }
    users.append(user)
    return jsonify(user), 201

@app.route("/users/<int:user_id>", methods=["DELETE"])
def delete_user(user_id):
    """Delete a user by ID"""
    if not isinstance(user_id, int) or user_id < 1:
        return jsonify({"error": "Invalid user ID"}), 400
    user = next((user for user in users if user["id"] == user_id), None)
    if user is None:
        return jsonify({"error": "User not found"}), 404
    users.remove(user)
    return jsonify({"message": f"User {user_id} deleted"})

if __name__ == "__main__":
    app.run(debug=True)

from flask import Flask, request, abort
app = Flask(__name__)

@app.route('/webhook', methods=['POST'])
def webhook():
    if request.method == 'POST':
        # Verify that the incoming webhook is from GitHub
        signature = request.headers.get('X-Hub-Signature')
        if not signature or not signature.startswith('sha1='):
            abort(400, 'X-Hub-Signature required')

        # Extract the digest from the header and verify it against our secret key
        digest_parts = signature.split()
        if len(digest_parts) != 2:
            abort(400, 'Invalid X-Hub-Signature format')

        # Compute the HMAC digest of the request body using our secret key
        hmac = hmac.new('your_secret_key'.encode(), msg=request.data, digestmod=hashlib.sha1)
        digest = hmac.hexdigest()

        # Compare the computed digest with the one provided in the request
        if not hmac.compare_digest(digest_parts[1], digest):
            abort(400, 'Invalid X-Hub-Signature')

        print('Received POST request data:', request.json)
        return '', 200
    else:
        abort(400, 'Invalid method')

if __name__ == '__main__':
    app.run(debug=True)

import subprocess
import json
import datetime
from threading import Thread, Lock

def process_line(line):
    columns = line.strip().split()
    current_cpu = None
    max_cpu = 100.0

    if len(columns) >= 3 and columns[2].endswith('%'):
        try:
            current_cpu = float(columns[2][:-1])
        except ValueError:
            pass

    mem_usage = None
    for i in range(4, len(columns)):
        if 'MiB' in columns[i]:
            try:
                used = columns[i-1]
                total = columns[i]
                used_value = float(used.strip('MiB').replace(',', ''))
                total_value = float(total.strip('MiB').replace(',', ''))
                mem_usage = {
                    'current': used_value,
                    'max_total': total_value
                }
                break
            except (ValueError, IndexError):
                pass

    return {
        'datetime': datetime.datetime.now().isoformat(),
        'cpu': {'current': current_cpu, 'max': max_cpu},
        'memory': mem_usage if mem_usage else None
    }

def update_log(log_lock, log_file, entry):
    lock = Lock()
    try:
        with open(log_file, 'a', newline='') as file:
            json.dump([entry], file)
    finally:
        lock.release()

def run_monitoring():
    while True:
        try:
            result = subprocess.run(
                'top -b',
                shell=True,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                check=True
            )
            combined_output = (result.stdout + '\n' + result.stderr).decode('utf-8', errors='ignore').split('\n')
        except subprocess.CalledProcessError as e:
            print(f"top command failed: {e}")
            continue

        for line in combined_output:
            if not line.strip():
                continue
            entry = process_line(line)
            if 'cpu' in entry and 'memory' in entry:
                update_log(global_lock, LOG_FILE_PATH, entry)

if __name__ == "__main__":
    global_lock = Lock()
    log_file = "system_usage.json"
    LOG_FILE_PATH = log_file

    Thread(target=run_monitoring).start()

