    base_url = 'https://api.twitter.com/1.1/account/verify_credentials.json'

    headers = {
        'Authorization': f'Bearer {access_token}'
    }
    response = requests.get(base_url, headers=headers)
    return response.status_code == 200  # returns True if status code is 200 meaning token is valid, False otherwise

def validate_instagram(access_token):
    base_url = 'https://graph.facebook.com/debug_token?'

    payload = {
        'input_token': access_token,
        'access_token': access_token
    }
    response = requests.get(base_url + urlencode(payload))
    return response.json()['data']['is_valid']  # returns True if token is valid, False otherwise

