import logging
from cryptography.fernet import Fernet
import secrets
import os

class SecureLogger:
    def __init__(self, log_file='log.txt'):
        self.log_file = log_file
        self.key = self.generate_key()
        self.cipher_suite = Fernet(self.key)

    def generate_key(self):
        return secrets.token_hex(32)

    def encrypt_log(self, log_message):
        cipher_text = self.cipher_suite.encrypt(log_message.encode('utf-8'))
        return cipher_text.decode('utf-8')

    def decrypt_log(self, encrypted_log):
        plain_text = self.cipher_suite.decrypt(encrypted_log.encode('utf-8'))
        return plain_text

    def log_report(self, report):
        # Encrypt the log message before writing it to the file
        encrypted_log = self.encrypt_log(report)

        try:
            with open(self.log_file, 'a') as file:
                file.write(f"Report at {report}\n")
                file.write(encrypted_log + "\n\n")
        except IOError as e:
            logging.error("Error writing to log file: ", str(e))

    def get_last_report(self):
        try:
            with open(self.log_file, 'r') as file:
                last_report = file.read().split('\n')
                return last_report[-1].strip()
        except IOError as e:
            logging.error("Error reading from log file: ", str(e))
            return None

# Example usage
if __name__ == "__main__":
    logger = SecureLogger()

    # Log a report
    report = "This is a sample report."
    logger.log_report(report)

    # Get the last logged report
    last_report = logger.get_last_report()
    print("Last logged report: ", last_report)

