import http.client
from urllib.parse import urlparse, urlunparse

class HttpResponse:
    def __init__(self, response_code, response_body):
        self.response_code = response_code
        self.response_body = response_body

    @staticmethod
    def from_http_client(response):
        # Parse the response status line to extract the HTTP version and status code
        line1, _, line2 = response.getheader('HTTP/1.1')
        http_version = urlparse(line1).scheme
        status_code = int(line2.split()[0])

        # Extract the HTTP headers from the response object
        headers = dict(response.getheaders())

        # Convert the HTTP headers to a dictionary with more convenient keys
        header_dict = {}
        for key, value in headers.items():
            if ' ' in key:
                key_parts = key.split(' ')
                header_key = ''
                for i, k in enumerate(key_parts):
                    header_key += (k + ':')
                    if i < len(key_parts) - 1:
                        header_key += ','
                header_dict[header_key] = value
            else:
                header_dict[key] = value

        return HttpResponse(status_code, response_body=headers)

class HttpClient:
    def __init__(self):
        self.connection = http.client.HTTPSConnection()

    def request(self, method, url, body=None, headers=None):
        if headers is None:
            headers = {}

        self.connection.request(method, url, body, **headers)
        response = self.connection.getresponse()
        return HttpResponse.from_http_client(response)

# Example usage
if __name__ == "__main__":
    client = HttpClient()

    # Make a GET request to the Google homepage
    response = client.request('GET', 'https://www.google.com')

    print(f"Status Code: {response.response_code}")
    for key, value in response.header_dict.items():
        print(f"{key}: {value}")

import socket
import select
import time

class OfflineDeviceHandler:
    def __init__(self):
        self.devices = {}

    def connect_device(self, device_name, address, port):
        try:
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.connect((address, port))
            self.devices[device_name] = sock
            print(f"Connected to {device_name}")
        except ConnectionRefusedError:
            print(f"{device_name} is offline")

    def disconnect_device(self, device_name):
        try:
            if device_name in self.devices:
                self.devices[device_name].close()
                del self.devices[device_name]
                print(f"{device_name} disconnected")
        except KeyError:
            print(f"{device_name} not found")

    def send_data_to_devices(self, data, device_names=None):
        if device_names is None:
            for device_name in self.devices:
                sock = self.devices[device_name]
                try:
                    sock.send(data)
                except ConnectionResetError:
                    self.disconnect_device(device_name)

    def receive_data_from_devices(self, timeout=10):
        readable_socks = []
        for device_name, sock in self.devices.items():
            readable_socks.append(sock)

        try:
            readable_socks, _, _ = select.select(readable_socks, [], [], timeout)
        except TimeoutError:
            print("No devices online")
            return None

        data = b''
        for sock in readable_socks:
            try:
                chunk = sock.recv(1024)
                if not chunk:
                    self.disconnect_device(device_name)
                else:
                    data += chunk
            except ConnectionResetError:
                self.disconnect_device(device_name)

        return data


# Example usage
if __name__ == "__main__":
    handler = OfflineDeviceHandler()

    # Connect devices
    handler.connect_device("device1", "127.0.0.1", 8080)
    handler.connect_device("device2", "127.0.0.1", 8081)

    while True:
        data_to_send = b"Hello, device!"
        print(f"Sending to devices: {data_to_send}")
        handler.send_data_to_devices(data_to_send, ["device1", "device2"])

        data_received = handler.receive_data_from_devices()
        if not isinstance(data_received, bytes):
            break
        print(f"Received from devices: {data_received}")

        time.sleep(5)

