import socket
import select

class ConnectionHandler:
    def __init__(self):
        self.clients = []
        self.server_socket = None

    def create_server(self, host, port):
        # Create a new server socket
        self.server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.server_socket.bind((host, port))
        self.server_socket.listen(5)

        # Add the server to the list of clients
        self.clients.append('server')

    def handle_client_disconnection(self):
        # Check if there are any active connections
        readable, writable, errored = select.select([client for client in self.clients if isinstance(client, str)], [], [])

        # Iterate through each client
        for client in readable:
            # If the client is a socket (i.e., not the server)
            if isinstance(client, str):
                try:
                    # Receive data from the client
                    data = client.recv(1024)

                    # If no data was received, disconnect the client
                    if not data:
                        self.disconnect_client(client)
                except Exception as e:
                    print(f"Error: {e}")

    def connect_to_client(self, host, port):
        # Create a new client socket
        client_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)

        try:
            # Connect to the client
            client_socket.connect((host, port))

            # Add the client to the list of clients
            self.clients.append(client_socket)
        except Exception as e:
            print(f"Error: {e}")

    def disconnect_client(self, client):
        # Remove the client from the list of clients
        if isinstance(client, str) and client == 'server':
            pass  # Do nothing for the server
        else:
            self.clients.remove(client)
            client.close()

# Example usage
if __name__ == "__main__":
    handler = ConnectionHandler()
    handler.create_server('localhost', 12345)

    while True:
        handler.handle_client_disconnection()

