    def add_tenant(self, name, email):
        if name not in self.tenants and email not in [t.email for t in self.tenants.values()]:
            tenant = Tenant(name, email)
            self.tenants[name] = tenant
            print(f"Tenant {name} added successfully.")
        else:
            print("Name or Email already exists.")

    def onboard_tenant(self, name):
        if name in self.tenants:
            self.tenants[name].onboard()
        else:
            print("Tenant not found.")

    def list_tenants(self):
        for tenant_name, tenant in self.tenants.items():
            status = "On-boarded" if tenant.onboarded else "Not On-boarded"
            print(f"{tenant_name}: {status}")

def main():
    system = TenantOnboardingSystem()

    while True:
        print("\nTenant Onboarding System")
        print("1. Add Tenant")
        print("2. Onboard Tenant")
        print("3. List Tenants")
        print("4. Exit")

        choice = input("Choose an option: ")

        if choice == "1":
            name = input("Enter tenant name: ")
            email = input("Enter tenant email: ")
            system.add_tenant(name, email)
        elif choice == "2":
            name = input("Enter tenant name to onboard: ")
            system.onboard_tenant(name)
        elif choice == "3":
            system.list_tenants()
        elif choice == "4":
            print("Exiting the system.")
            break
        else:
            print("Invalid option. Please choose a valid option.")

