import time
import requests
from requests.adapters import HTTPAdapter
from requests.exceptions import RetryError

class RateLimitExceeded(Exception):
    pass

def request_with_retry(session, method, url, **kwargs):
    try:
        response = session.request(method=method, url=url, **kwargs)
        if response.status_code == 429: # HTTP status code for rate limit exceeded
            raise RateLimitExceeded()
        return response
    except RetryError as e:
        print(f"Failed to make request after retrying: {e}")
        return None

def handle_rate_limits(api_call):
    session = requests.Session()
    # Adapter with retry mechanism for rate limit errors (HTTP status code 429)
    adapter = HTTPAdapter(max_retries=RetryPolicy())
    session.mount("http://", adapter)
    session.mount("https://", adapter)

    while True:
        try:
            return api_call(session)
        except RateLimitExceeded:
            print("Rate limit exceeded, waiting for 60 seconds...")
            time.sleep(60) # Waiting for 1 minute before making a new request

# Example of using handle_rate_limits
def make_api_request(session):
    response = request_with_retry(session, 'GET', 'https://api.example.com/data')
    return response.json() if response else None

result = handle_rate_limits(make_api_request)

import collections
import time

class QueueOverflowException(Exception):
    pass

class Queue:
    def __init__(self, max_size):
        self.max_size = max_size
        self.queue = collections.deque(maxlen=max_size)
        self.lock = time.time()

    def enqueue(self, item):
        if len(self.queue) < self.max_size:
            # acquire lock before adding element to queue
            while time.time() - self.lock > 1:
                print("Queue overflow! Sleeping for 5 seconds and retrying.")
                time.sleep(5)
                self.lock = time.time()
            self.queue.append(item)
        else:
            raise QueueOverflowException("The queue has reached its maximum size.")

    def dequeue(self):
        if not self.is_empty():
            item = self.queue.popleft()
            return item
        else:
            return None

    def is_empty(self):
        return len(self.queue) == 0

# Example usage
if __name__ == "__main__":
    queue = Queue(3)

    try:
        for i in range(5):
            queue.enqueue(i)
            print(f"Enqueued {i}")
            time.sleep(1)
    except QueueOverflowException as e:
        print(e)

