def retry_webhook(url, data, retries=3):
    for i in range(retries):
        try:
            response = requests.post(url, json=data)
            if response.status_code == 200:
                return True
            else:
                sleep(5)
        except Exception as e:
            print(f"Error {e}. Retrying in 5 seconds...")
            sleep(5)
    return False

