class PaymentGatewayError(Exception):
    """Base class for all exceptions related to payment gateway."""
    pass


class PaymentGatewayAuthenticationError(PaymentGatewayError):
    """Raised when authentication with payment gateway fails."""
    def __init__(self, message, error_code):
        self.message = message
        self.error_code = error_code
        super().__init__(message)


class PaymentGatewayAuthorizationError(PaymentGatewayError):
    """Raised when authorization with payment gateway fails."""
    def __init__(self, message, error_code):
        self.message = message
        self.error_code = error_code
        super().__init__(message)


class PaymentGatewayTransactionError(PaymentGatewayError):
    """Raised when transaction with payment gateway fails."""
    def __init__(self, message, error_code):
        self.message = message
        self.error_code = error_code
        super().__init__(message)


def process_payment(payment_gateway, amount):
    try:
        # Authenticate with payment gateway
        if not payment_gateway.authenticate():
            raise PaymentGatewayAuthenticationError("Failed to authenticate with payment gateway", "AUTHENTICATION_ERROR")

        # Authorize transaction
        if not payment_gateway.authorize(amount):
            raise PaymentGatewayAuthorizationError("Failed to authorize transaction", "AUTHORIZATION_ERROR")

        # Process transaction
        if not payment_gateway.process_transaction(amount):
            raise PaymentGatewayTransactionError("Failed to process transaction", "PROCESSING_ERROR")
    except Exception as e:
        # Handle any other exceptions
        print(f"An error occurred: {str(e)}")


