def verify_password(user, password):
    """Verify the user's password"""
    return hmac.compare_digest(hashlib.sha256(password.encode()).hexdigest(), users_data[user]["password"])

def generate_token(user):
    """Generate a token for the given user"""
    return hashlib.sha256((str(users_data[user]["token"])).encode()).hexdigest()

@app.route("/login", methods=["POST"])
def login():
    username = request.form.get("username")
    password = request.form.get("password")

    if username in users_data:
        if verify_password(username, password):
            # Generate a new token and update the user's data
            token = generate_token(username)
            users_data[username]["token"] = token
            return f"Logged in as {username}", 200
    return "Invalid credentials", 401

