    if "token" not in session:
        return "Please log in first", 403
    username = session["token"]
    # Verify the user's token (e.g., check it exists in the database)
    return f"Welcome, {username}!", 200

@app.route("/logout")
def logout():
    if "token" not in session:
        return "Please log in first", 403
    del users_data[session["token"]]
    # Clear the token from the user's data
