import os
from shutil import copyfile

class TenantBackup:
    def __init__(self, tenant_id):
        self.tenant_id = tenant_id
        self.backup_dir = f'/backups/{self.tenant_id}/'

    # Create a backup of the tenant's data
    def create_backup(self, source_path):
        if not os.path.exists(source_path):
            print("Source path does not exist.")
            return False

        if not os.path.exists(self.backup_dir):
            os.makedirs(self.backup_dir)

        backup_file = self.backup_dir + os.path.basename(source_path)
        copyfile(source_path, backup_file)

    # Retrieve a backup of the tenant's data
    def retrieve_backup(self, backup_filename, destination_path):
        source = self.backup_dir + backup_filename
        if not os.path.exists(source):
            print("Backup file does not exist.")
            return False

        copyfile(source, destination_path)

