import hashlib
import hmac
import time
from typing import Optional, Dict

class Session:
    def __init__(self):
        self.user_id: int = None  # Store the user's ID as an integer
        self.session_key: str = None  # Use a random session key for encryption
        self.expire_time: float = None  # Set the expiration time in seconds

    def generate_session_key(self) -> str:
        """Generate a new random session key"""
        return hashlib.sha256(str(time.time()).encode()).hexdigest()

    def create_session(self, user_id: int) -> Dict[str, object]:
        """Create a new session for a given user"""
        self.user_id = user_id
        self.session_key = self.generate_session_key()
        self.expire_time = time.time() + 3600  # Set the expiration time to 1 hour

        return {
            "session_key": self.session_key,
            "expire_time": self.expire_time,
        }

    def check_session(self, session_data: Dict[str, object]) -> bool:
        """Verify if a session is valid"""
        expected_session_key = hmac.new(self.user_id.to_bytes(4, 'big'), str(session_data["session_key"]).encode(), hashlib.sha256).hexdigest()
        return self.session_key == expected_session_key and time.time() < self.expire_time

    def destroy_session(self) -> None:
        """Destroy the session by resetting its keys"""
        self.user_id = None
        self.session_key = None

import bcrypt
from getpass import getpass

def create_password():
    password = getpass("Enter your password: ")
    if len(password) < 8:
        print('Password should be at least 8 characters long')
        return False
    else:
        hashed = bcrypt.hashpw(password.encode(), bcrypt.gensalt())
