import logging

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

def parse_data(data):
    """
    Parse the input data and return a dictionary with parsed values.

    Args:
        data (dict): A dictionary containing data to be parsed.

    Returns:
        dict: A dictionary with parsed values. If parsing fails, returns an error message.

    Raises:
        Exception: If any exception occurs during parsing.
    """
    try:
        # Initialize an empty dictionary to store the parsed values
        parsed_data = {}

        # Iterate over each key-value pair in the input data
        for key, value in data.items():
            # Use a try-except block to handle parsing errors
            try:
                # Check if the value is numeric and parse it as an integer or float
                if isinstance(value, (int, float)):
                    parsed_data[key] = int(value)
                elif isinstance(value, str):
                    try:
                        parsed_data[key] = float(value)
                    except ValueError:
                        logger.warning(f"Failed to parse {value} as a number. Skipping this value.")
                else:
                    # If the value is not numeric, log an error and skip it
                    logger.warning(f"Skipping non-numeric value: {value}")
            except Exception as e:
                # Log any other exceptions that occur during parsing
                logger.error(f"Error parsing {key}: {str(e)}")

        return parsed_data

    except Exception as e:
        # If an exception occurs while parsing, log the error and return a default value
        logger.error(f"Failed to parse data: {str(e)}")
        return {"error": "Failed to parse data"}

# Example usage:

data = {
    "age": 25,
    "height": "175.5",
    "weight": "65"
}

parsed_data = parse_data(data)
print(parsed_data)

# Output:
# {'age': 25, 'height': 175.5, 'weight': 65}

