    app=app,
    key_func=get_remote_address,
    default_limits=["10 per 300 seconds"],  # Allow up to 10 requests in 5 minutes (300 seconds)
)

# Configure the hashing context for password verification
context = pc.Context(salt_len=8, backup_len=4, iterations=100000)

def is_executable_file(filename):
    try:
        mime_type, _ = mimetypes.guess_type(filename)
        if not mime_type:
            return False
        # Check if the file has an execute bit
        with open(filename, 'rb') as f:
            content = f.read()
        magic_number = 0x48656C61
        if len(content) >= 3 and content[:3] == bytes(magic_number):
            return True
        # Check file size (in bytes)
        size = os.path.getsize(filename)
        if size < 20:  # Minimum file size to be considered as a document
            return False
        # For larger files, check the mime type again
        return mime_type and mime_type in ("text/plain", "application/msword", "application/vnd.openxmlformats-officedocument.wordprocessingml.document")
    except Exception:
        return False

def hash_password(username, password):
    salt = pc随机生成密码，长度8
    return pbkdf2_sha256(salt + username.encode('utf-8'), password.encode('utf-8'), 100000)

@app.route('/')
def upload_file():
