import configparser
import os
import time
from threading import Thread, Event

class DynamicConfig(object):
    def __init__(self, file_path):
        self.file_path = file_path
        self.config = configparser.ConfigParser()
        self._load_config()

        # Create a new thread for monitoring changes in the configuration file
        self.monitoring_thread = Thread(target=self._monitor_changes)
        self.monitoring_thread.daemon = True  # Set as daemon so it will terminate when the main program ends
        self.monitoring_thread.start()

    def _load_config(self):
        if os.path.exists(self.file_path):
            self.config.read(self.file_path)
        else:
            raise FileNotFoundError("Config file not found")

    def _monitor_changes(self):
        last_modification = os.path.getmtime(self.file_path)
        while True:
            time.sleep(1)  # Check for changes every second
            if os.path.getmtime(self.file_path) != last_modification:
                self._load_config()
                print("Config file changed, reloaded configurations.")
                last_modification = os.path.getmtime(self.file_path)

    def get(self, section, option):
        return self.config.get(section, option)

import time
from botocore.exceptions import EndpointConnectionError

def with_retry(func):
    def wrapper(*args, **kwargs):
        max_retries = 5
        retries = 0
        while retries < max_retries:
            try:
                return func(*args, **kwargs)
            except EndpointConnectionError as e:
                print(f"Attempt {retries+1}: Failed to connect to cloud service with error: {e}. Retrying...")
                time.sleep(2**retries)  # Exponential backoff
                retries += 1
        raise Exception("Failed to connect to cloud service after multiple attempts") from e
    return wrapper

