class ContentVersioning:
    def __init__(self):
        self.versions = {}  # This will be our data store

    def add_version(self, id, version):
        """Adds a new version to the specified content"""
        if not isinstance(id, str) or not isinstance(version, str):
            raise ValueError("Both 'id' and 'version' must be strings")
        if id in self.versions:
            self.versions[id].append(version)
        else:
            self.versions[id] = [version]

    def get_versions(self, id):
        """Returns all versions for the specified content"""
        return self.versions.get(id, [])

    def get_latest_version(self, id):
        """Returns the latest version of the specified content"""
        if id in self.versions:
            return self.versions[id][-1]
        else:
            return None

