import time
from threading import Thread

class BackupJob:
    def __init__(self, job_id):
        self.job_id = job_id
        self.status = "Not Started"

    def start(self):
        self.status = "In Progress"

        # Simulate a backup process
        for i in range(10):
            time.sleep(1)  # wait for 1 second
            print(f'Backup job {self.job_id} progress: {i*10}%')

        self.status = "Completed"

    def get_status(self):
        return self.status

class BackupMonitor:
    def __init__(self):
        self.jobs = {}

    def add_job(self, job_id):
        if job_id not in self.jobs:
            self.jobs[job_id] = BackupJob(job_id)

    def start_backup(self, job_id):
        backup_thread = Thread(target=self.jobs[job_id].start)
        backup_thread.start()

    def get_status(self, job_id):
        return self.jobs[job_id].get_status()

# Usage
monitor = BackupMonitor()
monitor.add_job("backup1")
print('Backup 1 status:', monitor.get_status("backup1"))  # prints "Not Started"
monitor.start_backup("backup1") 
time.sleep(1)  # wait for thread to start
print('Backup 1 status:', monitor.get_status("backup1"))  # prints "In Progress"

