from flask import Flask, request, abort
import hmac
import hashlib
import os

app = Flask(__name__)
SECRET_KEY = os.getenv('WEBHOOK_SECRET') # Get this from your environment variables or a secure secret storage mechanism

def verify_signature(request):
    signature = request.headers.get("X-Hub-Signature")
    if signature is None:
        return False

    sha_name, signature = signature.split('=')
    if sha_name != 'sha1':
        return False

    mac = hmac.new(bytes(SECRET_KEY, encoding='utf-8'), msg=request.data, digestmod=hashlib.sha1)

    return hmac.compare_digest(str(mac.hexdigest()), str(signature))

@app.route('/webhook', methods=['POST'])
def webhook():
    if not verify_signature(request):
        abort(403)

    # If we've gotten this far, the request is authenticated and we can proceed with our code
    data = request.get_json()  # This depends on what type of data your webhook sends

    print("Received:", data)

    return 'OK', 200

if __name__ == "__main__":
    app.run(debug=True)

