import threading

class SafeLibrary:
    def __init__(self):
        self.lock = threading.Lock()
        self.data = []

    def add(self, value):
        with self.lock:
            self.data.append(value)

    def remove(self, index):
        with self.lock:
            del self.data[index]

    def get_data(self):
        with self.lock:
            return self.data[:]

