def create_hash(password):
    """This function hashes a given password using SHA256 for secure storage."""
    return hashlib.sha256(password.encode()).hexdigest()

def onboard_tenant(cursor, tenant_name, email, password):
    # Validate input to prevent SQL injection and other attacks
    if not all(validate_input(i) for i in [tenant_name, email]):
        raise ValueError("Invalid characters in inputs.")

    hashed_password = create_hash(password)

    try:
        cursor.execute("INSERT INTO Tenants (TenantName, Email, PasswordHash) VALUES (?, ?, ?)",
                       (tenant_name, email, hashed_password))
