class Device:
    def __init__(self, device_id):
        self.id = device_id
        self.count = 0
        self.last_requests = []

    def add_request(self, timestamp):
        current_time = int(timestamp)
        delta = current_time - max(self.last_requests) if self.last_requests else current_time

        if delta > 60:
            self.count += 1
            self.last_requests.append(current_time)
            return True

        elif len(self.last_requests) < 5:  # Limiting to the last 5 requests for analysis
            self.last_requests.append(current_time)
            self.count += 1
            return False

        else:
            if (current_time - sorted(self.last_requests)[-1]) <= 60:
                return False

            elif delta > 30 and current_time - sorted(self.last_requests)[0] >= 900:  
                # Exclude the oldest request from the window calculation
                self.count += 1
                self.last_requests = sorted([current_time] + self.last_requests)

            else:
                return False

        return True

    def get_last_validated_timestamp(self):
        if len(self.last_requests) == 0:
            return None
        return max(self.last_requests)

def create_device_logger():
    return {
        'all': [],
        'over_limits': set(),
        'under_limits': {}
    }

def main():
    device_logger = create_device_logger()

    # Example usage:
    devices = {
        "device_001": Device("device_001"),
        "device_002": Device("device_002")
    }

    timestamps = [
        ("2024-10-01T12:00:01", "request_id_001", "user1", 0),
        ("2024-10-01T12:00:02", "request_id_002", "user1", 1),
        ("2024-10-01T12:00:03", "request_id_003", "user2", 1),
        # Add more timestamps as needed
    ]

    for timestamp, request_id, _, timestamp_int in timestamps:
        dt = datetime.datetime.fromisoformat(timestamp)
        ts = int(dt.timestamp())

        device = devices.get(request_id)

        if not device.add_request(ts):
            device_logger['over_limits'].add(request_id)

        # Log validations
        device_logger['all'].append({
            'timestamp': ts,
            'device': request_id,
            'status': 'allowed' if device.add_request(ts) else 'blocked'
        })

    print("All log entries:", "\n".join(map(str, device_logger['all'])))

    # To analyze over-limits devices:
    for dev_id in device_logger['over_limits']:
        logger.info(f"Device {dev_id} was over the limit and was blocked.")

    if device_logger['under_limits']:
        logger.warning("Some devices are under the configured rate limits. Consider increasing the limit.")

import os
import json
import logging
from datetime import datetime
import socket
import time
import atexit
from typing import Dict, Any, Optional

class Logger:
    def __init__(self, config_path: str):
        self.config = self._read_config(config_path)
        self.log_levels = {
            "DEBUG": ["DEBUG", "INFO"],
            "INFO": ["INFO", "WARNING"],
            "WARNING": ["WARNING"],
            "ERROR": ["ERROR", "CRITICAL", "ALERT"],
            "CRITICAL": ["CRITICAL"],
            "ALERT": ["ALERT"]
        }
        self.file_formats = {
            'DEBUG': '.debug.log',
            'INFO': '.info.log',
            'WARNING': '.warning.log',
            'ERROR': '.error.log',
            'CRITICAL': '.critical.log',
            'ALERT': '.alert.log'
        }

    def _read_config(self, config_path: str) -> Dict[str, Any]:
        with open(config_path, 'r') as f:
            return json.load(f)

    def determine_log_level(self, severity: str) -> Optional[str]:
        for level, levels in self.log_levels.items():
            if severity in levels:
                return level
        return None

    def _write_log(self, timestamp: str, message: str, log_level: str,
                  device_data: Dict[str, Any]) -> None:
        file_name = os.path.join(os.getcwd(), f"log_{self.file_formats.get(log_level)}.log")
        with open(file_name, 'a') as f:
            f.write(f"{timestamp} - {message} - {json.dumps(device_data)}\n")

    def log_device_activity(self, device_id: str, timestamp: datetime,
                            status: int, location: Optional[Dict[str, Any]] = None) -> None:
        severity = 'INFO' if status == 2 else 'WARNING'
        logger_level = self.determine_log_level(severity)
        if logger_level:
            log_severity = logger_level
            device_data = {
                'timestamp': timestamp,
                'device_id': device_id,
                'status': status,
                'location': location
            }
            log_time = datetime.now().strftime("%Y%m%d_%H%M%S")
            self._write_log(log_time, f"{log_severity}: {message}", log_severity, device_data)

    def _handle_device_config(self, device_name: str) -> Dict[str, Any]:
        config_path = os.path.join(os.getcwd(), f"device_config_{device_name}.json")
        if os.path.exists(config_path):
            with open(config_path, 'r') as f:
                return json.load(f)
        else:
            raise FileNotFoundError(f"Device configuration file not found: {config_path}")

    def start_logging(self) -> None:
        logger = logging.getLogger(__name__)
        formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
        for level_name, severity_levels in self.log_levels.items():
            handler = logging.StreamHandler()
            handler.setFormatter(formatter)
            logger.addHandler(handler)

        def close_handler() -> None:
            logger.removeHandler(handler)
        atexit.register(close_handler)

    @staticmethod
    def rotate_files() -> None:
        for log_level in Logger.file_formats.keys():
            old_log_path = os.path.join(os.getcwd(), f"log_{Logger.file_formats[log_level]}")
            new_log_path = os.path.join(os.getcwd(), f" recent_{old_log_path.split('/')[-1]}\n{os.sep}")
            if os.path.exists(old_log_path):
                try:
                    with open(new_log_path, 'wb') as f:
                        contents = f.read()
                    os.remove(old_log_path)
                except Exception as e:
                    print(f"Error rotating {log_level} log: {str(e)}")

def main() -> None:
    device_name = input("Enter Device Name: ").strip().lower()
    config_path = os.path.join(os.getcwd(), f"device_config_{device_name}.json")

    try:
        logger = Logger(config_path)
