class TenantValidator:
    def __init__(self, config):
        self.config = config

    def validate(self):
        # Check if the required keys are present in the configuration
        required_keys = ['tenantId', 'apiKey']
        for key in required_keys:
            if key not in self.config.keys():
                raise ValueError('Invalid tenant configuration: Missing {}'.format(key))

        # Check that the tenantId is a string of length 32 and apiKey is a string of length 64
        if type(self.config['tenantId']) != str or len(self.config['tenantId']) != 32:
            raise ValueError('Invalid tenant configuration: Invalid tenantId')
        if type(self.config['apiKey']) != str or len(self.config['apiKey']) != 64:
            raise ValueError('Invalid tenant configuration: Invalid apiKey')

        # Additional checks can be added here based on the specific requirements of your tenants' configurations

        return True  # If no exceptions were raised, then the config is valid

import json
import os

class Translator:
    def __init__(self, language_dir='translations/'):
        self.language_dir = language_dir
        self.translations = {}

        # Load all translations on initialization
        self._load_all()

    def _load(self, lang_code):
        file_path = os.path.join(self.lang_code + '.json')
        with open(file_path, 'r') as f:
            data = json.load(f)
        self.translations[lang_code] = data

    def _load_all(self):
        # List all files in the directory
        for file in os.listdir(self.language_dir):
            if file.endswith('.json'):
                lang_code = file[:-5]  # Remove '.json' from filename
                self._load(lang_code)

    def gettext(self, lang_code, text_id):
        try:
            return self.translations[lang_code][text_id]
        except KeyError:
            print('Translation not found for id "{}" in language {}'.format(text_id, lang_code))

from PIL import Image
from PIL.ExifTags import TAGS

def get_exif(filename):
    image = Image.open(filename)
    image.verify() # perform a security check on the image
    exifdata = image._getexif()
    if not exifdata:
        print("No EXIF data found")
        return {}
    else:
        metadata = {TAGS[k]: v for k, v in exifdata.items() if k in TAGS}
        return metadata

