class PaymentStatus:
    def __init__(self, payment_id, amount, payment_method):
        self.payment_id = payment_id
        self.amount = amount
        self.payment_method = payment_method
        self.status = "Pending"

    def update_status(self, status):
        if status == "Success":
            self.status = "Successful"
        elif status == "Failed":
            self.status = "Unsuccessful"
        else:
            print("Invalid status")

    def display_status(self):
        print(f"Payment ID: {self.payment_id}")
        print(f"Amount: ${self.amount:.2f}")
        print(f"Payment Method: {self.payment_method}")
        print(f"Status: {self.status}")


class PaymentSystem:
    def __init__(self):
        self.payments = {}

    def add_payment(self, payment_id, amount, payment_method):
        payment = PaymentStatus(payment_id, amount, payment_method)
        self.payments[payment_id] = payment

    def update_payment_status(self, payment_id, status):
        if payment_id in self.payments:
            self.payments[payment_id].update_status(status)
        else:
            print("Payment not found")

    def display_payments(self):
        for payment in self.payments.values():
            payment.display_status()
            print("------------------------")


