from pyowls import OWSService, OWSCert
from pandas import DataFrame

class SecureSensorDataProcessor:
    def __init__(self, owsservice_url, cert_file):
        self.owsservice_url = owsservice_url
        self.cert_file = cert_file
        self.service = OWSService(self.owsservice_url)
        self.certificate = OWSCert(self.cert_file)

    def process_sensor_data(self, data):
        # Validate incoming sensor data
        try:
            sensor_data = DataFrame(data)
            if not sensor_data.empty:
                # Perform necessary processing on the validated sensor data
                processed_data = sensor_data.apply(lambda x: x * 2)  # Example processing step
                return processed_data
        except Exception as e:
            print(f"Error processing sensor data: {str(e)}")

    def send_processed_data(self, processed_data):
        try:
            # Send the processed sensor data to the secure data exchange platform using OWS-Legacy-Protocol
            self.service.send_message(
                message=processed_data,
                service="sensor_data",
                subject="Secure Sensor Data"
            )
        except Exception as e:
            print(f"Error sending processed sensor data: {str(e)}")

if __name__ == "__main__":
