        # Simulate sensor data incoming
        sensor_data = [
            {"timestamp": time.time(), "temperature": 25.0},
            {"timestamp": time.time(), "humidity": 60.0}
        ]

        processed_data = processor.process_sensor_data(sensor_data)
        if processed_data is not None:
            processor.send_processed_data(processed_data)

        # Add a short delay between processing cycles
        time.sleep(1)

