import re
from html.parser import HTMLParser

class UserContentManager(HTMLParser):
    def __init__(self):
        super().__init__()
        self.clean_text = ""

    def handle_starttag(self, tag, attrs):
        if tag in ["p", "span", "div"]:
            self.clean_text += "<" + tag + ">"

    def handle_endtag(self, tag):
        if tag in ["p", "span", "div"]:
            self.clean_text += "</" + tag + ">"

    def handle_data(self, data):
        # Remove malicious code
        clean_data = re.sub(r'<script.*?>.*?</script>', '', data)
        clean_data = re.sub(r'<style.*?>.*?</style>', '', clean_data)

        # Remove unwanted HTML tags
        clean_data = re.sub(r'<[^>]*>', '', clean_data)

        self.clean_text += clean_data

def manage_user_content(user_input):
    # Create a UserContentManager object
    manager = UserContentManager()

    # Parse the user input as HTML
    manager.feed(user_input)

    # Return the clean text
    return manager.clean_text

import random

class KeyRotation:
    def __init__(self, keys):
        self.keys = keys
        self.key_index = 0

    def rotate(self):
        self.key_index += 1
        if self.key_index >= len(self.keys):
            self.key_index = 0
        return self.keys[self.key_index]

import psutil

def prevent_overlapping_tasks():
    # Get all running processes
    processes = psutil.pids()

    for process in processes:
        # Retrieve process information
        pinfo = psutil.Process(process)

        # Check if another task shares the same PID, PPID, or file
        non_overlapping = True

        try:
            for other_process in processes:
                if process != other_process:  # Skip checking against self
                    other_pinfo = psutil.Process(other_process)

                    # Check same PIDs and same directories (user space files)
                    if (
                        pinfo PID == other_pinfo PID or 
                        pinfo UserProcessID == other_pinfo UserProcessID or
                        pinfo-nicknames overlap in any file:
                    ):
                        non_overlapping = False
                        break  # No need to check further

        except Exception as e:
            print(f"Error checking process {process}: {e}")
            continue

        if not non_overlapping:
            print(f"Task with PID {pinfo.pid} overlaps with another task")
        else:
            print(f"Non-overlapping task execution with PID {pinfo.pid}")

if __name__ == "__main__":
    prevent_overlapping_tasks()

