import hashlib

def calculate_checksum(file_path):
    """Calculate the MD5 checksum of a file"""
    hasher = hashlib.md5()
    with open(file_path, 'rb') as f:
        for buf in iter(lambda: f.read(4096), b''):
            hasher.update(buf)
    return hasher.hexdigest()

def validate_checksum(file_path, checksum):
    """Validate the MD5 checksum of a file"""
    calculated_checksum = calculate_checksum(file_path)
    if calculated_checksum == checksum:
        print("Checksum is valid.")
    else:
        print("Checksum is not valid.")

# Usage
validate_checksum('/path/to/your/file', 'expected_checksum')

