class ContentVersioning:
    def __init__(self):
        self.versions = {}
        self.current_version = None

    def create(self, content):
        if self.current_version is None:
            self.current_version = 1
        else:
            self.current_version += 1
        self.versions[self.current_version] = content

    def get_version(self, version_number):
        return self.versions.get(version_number, "Version not found")

    def revert_to(self, version_number):
        if version_number in self.versions:
            self.current_version = version_number
            print("Reverted to version", version_number)
        else:
            print("Version not found")

    def get_latest_version(self):
        return self.get_version(self.current_version)

# Usage
cv = ContentVersioning()
cv.create("Initial content")
cv.create("Second iteration of the content")
print(cv.get_latest_version())  # Prints: Second iteration of the content
cv.revert_to(1)
print(cv.get_latest_version())  # Prints: Initial content

import os
import re

def validate_file_name(file_name):
    if not os.path.exists(file_name):
        raise ValueError("File does not exist")
    elif len(file_name) > 255:
        raise ValueError("File name is too long")
    elif re.search(r"[^\w\.]+", file_name):
        raise ValueError("File name contains invalid characters")
    else:
        return True

