class ProductInventory:
    def __init__(self):
        # Initialize inventory as empty dictionary
        self.inventory = {}

    def add_product(self, name, quantity):
        # Add product to inventory or update its quantity if it already exists
        if name in self.inventory:
            self.inventory[name] += quantity
        else:
            self.inventory[name] = quantity

    def remove_product(self, name, quantity):
        # Remove specified quantity of product from inventory or print error message if it doesn't exist or quantity is more than available
        if name in self.inventory:
            if self.inventory[name] >= quantity:
                self.inventory[name] -= quantity
            else:
                print("Error: Insufficient stock")
        else:
            print(f"Error: Product {name} not found in inventory.")

    def check_stock(self, name):
        # Check and return the current stock level of a product or print error message if it doesn't exist
        if name in self.inventory:
            return self.inventory[name]
        else:
            print(f"Error: Product {name} not found in inventory.")

    def display_inventory(self):
        # Display all products and their corresponding stock levels
        for product, quantity in self.inventory.items():
            print(f"Product: {product}, Quantity: {quantity}")

# Usage example:
inventory = ProductInventory()
inventory.add_product("Apple", 10)
inventory.add_product("Banana", 5)
inventory.display_inventory() # It should display: Apple - 10, Banana - 5
print(inventory.check_stock("Apple")) # It should print: 10
inventory.remove_product("Apple", 3)
print(inventory.check_stock("Apple")) # It should print: 7

import importlib.util

def is_permissive_license(license_text):
    # Define keywords for known permissive licenses
    keywords = {
        'MIT', 'BSD-3-Clause', 'LGPL', 'EPL',
        'AGPLv3', 'CeCILL-B', 'CeCILL-C', 'GPL-3.0',
        'GPL-2.1', 'Python', 'Unlicense'
    }
    if not license_text:
        return False
    normalized = license_text.lower()
    for kw in keywords:
        if kw in normalized:
            return True
    return False

# Get all installed package names and their specifications
for name, spec in importlib.util.find_specnames():
    if not spec:
        continue  # Skip if the package is not found on this platform

    license_text = getattr(spec, 'license', None)
    if is_permissive_license(license_text):
        print(f"Skipping {name}")
        continue
    else:
        try:
            __import__(name)  # Attempt to import the module
        except ImportError:
            pass  # If import fails, skip this package

print("All packages with permissive licenses were imported.")

import json
import requests
from time import sleep

def parse_incoming_json(url):
    """Parse JSON from incoming GET request."""
    try:
        response = requests.get(url, verify=True)
        response.raise_for_status()  # Raises HTTPError for bad responses

        data = json.loads(response.text)
        return data
    except json.JSONDecodeError as e:
        print(f"Error parsing JSON: {e}")
        return None
    except requests.exceptions.RequestException as e:
        print(f"Request failed: {str(e)}")
        return None

def serialize_to_json(data, filename):
    """Serialize data to JSON and write to file."""
    try:
        with open(filename, 'w') as f:
            json.dump(data, f, indent=2)
    except Exception as e:
        print(f"Error serializing data: {e}")
        raise

def main():
    while True:
        url = input("Enter the URL of the JSON request: ")
        filename = input("Enter the output filename for the JSON file: ")

        incoming_data = parse_incoming_json(url)
        if incoming_data is not None:
            print(f"Successfully parsed JSON from {url}. Data received.")
            break
        else:
            print("Failed to parse JSON. Exiting.")
            return

        try:
            sleep(0.1)  # Rate limiting for safety
            serialize_to_json(incoming_data, filename)
            print(f"JSON data serialized successfully to {filename}")
        except Exception as e:
            print(f"Error writing to file: {e}")

if __name__ == "__main__":
    main()

