from flask import Flask, render_template, request, redirect, url_for
from sqlalchemy import create_engine, Column, Integer, String
from sqlalchemy.ext.declarative import declarative_base
from sqlalchemy.orm import sessionmaker

# Create the Flask app and engine
app = Flask(__name__)
engine = create_engine('sqlite:///mydatabase.db')

# Define the User class
class User(object):
    def __init__(self, id, username, role):
        self.id = id
        self.username = username
        self.role = role

# Define the Roles table
Base = declarative_base()

class Roles(Base):
    __tablename__ = 'roles'
    id = Column(Integer, primary_key=True)
    name = Column(String)

# Create a sessionmaker using the engine
Session = sessionmaker(bind=engine)

@app.route('/')
def index():
    # Get the current user's role from the session
    user = request.args.get('user', None)
    if user is not None:
        user_role = user['role']
    else:
        return redirect(url_for('login'))

    # Query the database for the user's role
    roles = session.query(Roles).filter(Roles.id == user_role)

    # Check if the user has access to the requested page
    if not roles:
        return render_template('access_denied.html')

    # Render the page if the user has access
    return render_template('index.html', user=user, roles=roles)

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']

        # Check if the user exists and the password is correct
        user = session.query(User).filter(User.username == username, User.password == password)
        if not user:
            return redirect(url_for('login'))

        # Set the current user's role in the session
        request.session['user'] = {
            'id': user.id,
            'username': user.username,
            'role': user.role
        }

        return redirect(url_for('index'))
    else:
        return render_template('login.html')

@app.route('/logout')
def logout():
    # Remove the current user's role from the session
    request.session['user'] = None

    return redirect(url_for('index'))

import jwt  # JSON Web Tokens library for python
from datetime import datetime, timedelta

# Secret key to encode/decode tokens. Store it securely!
SECRET_KEY = "YOUR_SECRET_KEY"

def generate_token(device_id):
    """Generate a token for the given device id."""
    payload = {
        'device_id': device_id,
        # Add an expiry date for the token to enhance security.
        'exp': datetime.utcnow() + timedelta(hours=1)
    }
    return jwt.encode(payload, SECRET_KEY, algorithm='HS256')

def authenticate(token):
    """Authenticate the device using the token."""
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=['HS256'])
        return True  # Authentication succeeded!
    except jwt.ExpiredSignatureError:
        print("The token is expired.")
    except jwt.InvalidTokenError:
        print("Invalid token.")
    return False  # Authentication failed!

from flask import request
import os
import uuid
import magic  # python-magic library to check MIME types

ALLOWED_EXTENSIONS = {'txt', 'pdf', 'png', 'jpg', 'jpeg', 'gif'}
MAX_FILE_SIZE = 16 * 1024 * 1024  # 16 MB
UPLOAD_FOLDER = '/secure/file/storage/path'

def allowed_file(filename):
    return '.' in filename and \
           filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

@app.route('/upload', methods=['POST'])
def upload_file():
    if request.method == 'POST':
        file = request.files['file']
        if file and allowed_file(file.filename):
            if len(file.read()) > MAX_FILE_SIZE:
                return "File size exceeds the limit", 413

            file.seek(0)
            mime = magic.from_buffer(file.read(), mime=True)
            if mime not in ['text/plain', 'application/pdf', 'image/png', 'image/jpeg']:
                return "Invalid file type", 400

            filename = str(uuid.uuid4()) + os.path.splitext(file.filename)[1]
            file.seek(0)
            file.save(os.path.join(UPLOAD_FOLDER, filename))
            return "File uploaded successfully", 200

