def check_failed_jobs():
    try:
        # Set up SQLite database
        engine = create_engine('sqlite:///:memory:')
        Session = text("SELECT id FROM failed_jobs WHERE status = 'FAILED';")

        with engine.connect() as connection:
            result = connection.execute(Session).fetchall()
            if not result:
                return []

            failed_job_ids = [row[0] for row in result]
            return failed_job_ids

    except Exception as e:
        raise ValueError(f"Failed to check failed jobs: {e}")

def send_notification(job_id):
    try:
        # Initialize Twilio client
        sg = SendGrid(os.getenv('SENDGRID_API_KEY'))

        if not job_id:
            raise ValueError("Invalid or empty job ID.")

        msg = MessagingResponse()
        notification_message = f"Failed Job Notification\nJob ID: {job_id}\nStatus: Failed"

        # Example email template
        to = os.getenv('ADMIN_EMAIL')
        send_to = os.getenv('ADMINSEND-grid_EMAIL')

        msg.add(
            To=send_to,
            Body=f"Job failure notification for job ID {job_id}",
            MessageId=str(os.getenv('ORDER_ID')) + str(timedelta(days=1)),
            DisplayTo=os.getenv('ADMIN_DISPLAY_NAME'),
            Data={
                "message": notification_message
            },
            TemplateId="default_template",
            From=os.getenv('Twilio-from')
        )

        # Send the message
        sg.send(msg)
        print(f"Email sent to {send_to} for job ID {job_id}")
    except Exception as e:
        raise ValueError(f"Failed to send notification: {e}")

def main():
    try:
        user_details = get_user_details()
        failed_jobs = check_failed_jobs()

        if failed_jobs:
            for job_id in failed_jobs:
                send_notification(job_id)

            # Optional: Send a summary email with all failed jobs
            send_notification(", ".join(failed_jobs))

        print("Notifications sent successfully.")

    except Exception as e:
        print(f"An error occurred during notification process: {e}")

if __name__ == "__main__":
    main()

import threading
import time

class HangingThread(threading.Thread):
    def __init__(self, *args, **kwargs):
        super(HangingThread, self).__init__(*args, **kwargs)
        self._stop_event = threading.Event()

    def stop(self):
        self._stop_event.set()

    def stopped(self):
        return self._stop_event.is_set()

    def run(self):
        # Your long-running operation goes here
        while not self.stopped():
            time.sleep(1)  # Simulating a hanging task
            print("Thread is running...")

def main():
    timeout = 5  # seconds
    thread = HangingThread()
    thread.start()
    thread.join(timeout)  # Wait for at most `timeout` seconds
    if thread.is_alive():  # If the thread is still alive after `timeout` seconds, it's hanging
        print("Terminating hanging thread...")
        thread.stop()  # Ask the thread to stop (it may not respond immediately, but we're polite)
        thread.join()  # Wait for the thread to finish
    else:
        print("Thread completed successfully.")

if __name__ == "__main__":
    main()

