from functools import lru_cache, wraps
import time

# This is the decorator function to invalidate cache on data updates
def invalidate_cache(make_cache):
    @wraps(make_cache)
    def wrapper(*args, **kwargs):
        if not hasattr(wrapper, 'cache'):
            # If there is no cache attribute, call make_cache function to create one.
            wrapper.cache = make_cache()
        elif wrapper.last_updated > time.time():
            # If last updated timestamp is older than current time, refresh the cache.
            wrapper.cache = make_cache()
        return wrapper.cache[args]
    def set_timestamp(f):
        @wraps(f)
        def wrapped(*args, **kwargs):
            wrapper.last_updated = time.time() + 60 # Cache will be refreshed in every 60 seconds
            return f(*args, **kwargs)
        return wrapped
    wrapper.set_timestamp = set_timestamp
    return wrapper

@invalidate_cache
def create_expensive_dict():
    print("Creating expensive dict...")
    # This is where you'd have your expensive operation
    return {i: i*2 for i in range(10)}

# Now, the function 'create_expensive_dict()' will cache its result. If the data updates, we can set a new timestamp to invalidate the cache.

# When data is updated, call this function to set a new timestamp.
