# Set the delay between requests
DELAY_BETWEEN_REQUESTS = 0.5

def throttle(func):
    def wrapper(*args, **kwargs):
        if len(threading.enumerate()) >= MAX_CONCURRENT_REQUESTS:
            time.sleep(DELAY_BETWEEN_REQUESTS)
        return func(*args, **kwargs)
    return wrapper

