import time
import logging

def retry(max_retries=3, delay=1):
    """
    Decorator to retry a function if it fails.

    Args:
        max_retries: The maximum number of times to retry.
        delay: The delay between retries in seconds.

    Returns:
        The decorated function.
    """

    def decorator(func):
        def wrapper(*args, **kwargs):
            for i in range(max_retries):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    logging.error(f"Attempt {i+1}/{max_retries} failed with error: {e}")
                    time.sleep(delay)
            raise Exception(f"All retries failed with error: {e}")

        return wrapper

    return decorator

