class RateLimitingHandler:
    def __init__(self):
        selflimits = {}  # ID: (timestamp, count)
        self.ratelimit = {}
        self._rate_limit_task = None

    async def process_request(self, request, handler):
        if not handler:
            return web.json(request)

        limit = self.ratelimit.get(handler.id, [0])
        if not isinstance(limit, list):
            raise ValueError("Handler id is not a valid rate limiter")

        time_now = int(time.time())
        timestamp = limit[0]
        elapsed = time_now - timestamp
        if elapsed > 60:  # Limit per minute
            count = limit[1] + 1
            self.ratelimit[handler.id] = [timestamp, count]
            return None

        handler.id.limits.append((request, handler))

        try:
            result = await handler.process route(request)
        except Exception as e:
            traceback.print_exc(file=sys.stdout)
            raise
        finally:
            # Clean up the request tracking if necessary
            pass

        self.ratelimit[handler.id] = [timestamp, 0]
        return result

    async def _rate_limit_task(self):
        try:
            while True:
                await asyncio.sleep(60)  # Check every minute
                for handler_id in list(selflimits.keys()):
                    timestamp, count = selflimits[handler_id]
                    elapsed = time.time() - timestamp
                    if elapsed > 60 or count >=5: 
                        selflimits[handler_id] = [timestamp, 0]
        except asyncio.CancelledError:
            return

    def __enter__(self):
        self._rate_limit_task = threading.Thread(target=self._rate_limit_task)
        self._rate_limit_task.start()
        return self

    def __exit__(self, exc_type, exc_val, tb):
        if self._rate_limit_task:
            self._rate_limit_task.join()

