class DeploymentRollback:
    def __init__(self):
        self.deploy_stack = []

    # Simulates a new deployment, pushing the current version onto the stack
    def deploy(self, version):
        print("Deploying version", version)
        if len(self.deploy_stack) > 0:
            self.deploy_stack.append(self.deploy_stack[-1])
        else:
            self.deploy_stack.append('Initial Version')

    # Simulates a rollback, popping the latest version off the stack and returning it
    def rollback(self):
        if len(self.deploy_stack) < 2:
            print("Cannot roll back! This is the initial deployment.")
            return None
        previous_version = self.deploy_stack.pop()
        print("Rolled back to version", self.deploy_stack[-1])
        return previous_version

# Usage example:
rollback_manager = DeploymentRollback()
rollback_manager.deploy('V1.0')
rollback_manager.deploy('V2.0')
rollback_manager.rollback()  # Rolls back to V1.0

import hashlib
import time
from datetime import datetime, timedelta

class ReplayProtection:
    def __init__(self):
        self.hashes = {}

    def is_valid(self, message, timestamp):
        timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')

        if timestamp < datetime.now() - timedelta(minutes=5):
            return False  # Message is too old

        message_hash = hashlib.sha256(message.encode()).hexdigest()

        # Check if the hashes are different
        if self.hashes.get(timestamp) != message_hash:
            self.hashes[timestamp] = message_hash
            return True

        return False  # Message is a replay

replay_protection = ReplayProtection()
message = "SecretMessage"
current_time = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
if replay_protection.is_valid(message, current_time):
    print("Valid message")
else:
    print("Invalid message - possible replay attack")

