def calculate_total(cart, products):
    total = 0
    for item in cart:
        qty = cart[item]
        price_per_unit = get_price_per_unit(item, qty, products)
        total += qty * price_per_unit
    return total

def get_price_per_unit(item, qty, products):
    info = products.get(item, {})
    if 'discounts' not in info:
        return info['base_price']

    for tier in info['discounts']:
        lower_bound, upper_bound, discount_rate = tier

        # Ensure that the lower bound is correctly set
        if lower_bound is None or qty >= lower_bound:
            if upper_bound is None or qty <= upper_bound:
                return info['base_price'] * (1 - discount_rate)

    return info['base_price']

