class User(object):
    def __init__(self, name, role):
        self.name = name
        self.role = role  # can be 'admin', 'editor' or 'viewer'

class Resource(object):
    def __init__(self, name):
        self.name = name

    def is_accessible(self, user, permission):
        if user.role == 'admin':
            return True  # admin can do everything
        elif user.role == 'editor' and permission in ['read', 'write']:
            return True  # editor can read and write
        elif user.role == 'viewer' and permission == 'read':
            return True  # viewers can only read
        else:
            return False

