print(some_resource.is_accessible(admin_user, 'write'))  # True: admin can read and write

print(some_resource.is_accessible(editor_user, 'read'))  # True: editor can read
print(some_resource.is_accessible(editor_user, 'write'))  # True: editor can write

print(some_resource.is_accessible(viewer_user, 'read'))  # True: viewer can read
print(some_resource.is_accessible(viewer_user, 'write'))  # False: viewers cannot write

