from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.cache = OrderedDict()

    def get(self, key):
        if key in self.cache:
            value = self.cache.pop(key)
            self.cache[key] = value  # Move to end to mark as recently used
            return value
        else:
            return None

    def set(self, key, value):
        if key in self.cache:
            self.cache.pop(key)

        if len(self.cache) < self.capacity:
            pass  # Can add new key-value pair
        else:
            # Remove oldest item to make space for new one
            self.cache.popitem(last=False)

        self.cache[key] = value

# Example usage:
cache = LRUCache(2)  # Capacity of 2 items

cache.set('key1', 'value1')
print(cache.get('key1'))  # Output: 'value1'

cache.set('key2', 'value2')
print(cache.get('key2'))  # Output: 'value2'

# Cache misses
cache.set('key3', 'value3')
print(cache.get('key3'))  # Output: 'value3'

