from flask import Flask, request, redirect, render_template
import os
from werkzeug.utils import secure_filename
app = Flask(__name__)

# Define the allowed file types and maximum file size here
ALLOWED_EXTENSIONS = {'txt', 'pdf', 'png', 'jpg', 'jpeg', 'gif'}
MAX_CONTENT_LENGTH = 16 * 1024 * 1024  # Maximum file size is 16MB
app.config['UPLOAD_FOLDER'] = '/path/to/the/uploads'

# Function to check if the file extension is allowed
def allowed_file(filename):
    return '.' in filename and \
           filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

@app.route('/', methods=['GET', 'POST'])
def upload_file():
    if request.method == 'POST':
        # Check if the post request has the file part
        if 'file' not in request.files:
            return redirect(request.url)

        file = request.files['file']

        # If user does not select file, browser also submit an empty part without filename
        if file.filename == '':
            return redirect(request.url)

        if file and allowed_file(file.filename):
            # Make sure the file name is secure to avoid directory traversal attacks
            filename = secure_filename(file.filename)

            # Save the file in the upload folder with the new, secure filename
            file.save(os.path.join(app.config['UPLOAD_FOLDER'], filename))
            return redirect('/success')  # Redirect to a success page after successful upload
    return render_template('upload.html')  # Render an HTML template for the file upload form

def prevent_memory_leaks_in_loops():
    # Example loop with potential for memory leaks
    my_list = []
    for i in range(10000):
        my_list.append(i)

    # Manually release memory references to prevent leaks
    del my_list[:]

    # Alternatively, use a context manager to manage resources
    with open('myfile.txt', 'w') as f:
        for i in range(10000):
            f.write(str(i))

    # Use generators to avoid storing entire lists in memory
    def my_generator():
        for i in range(10000):
            yield i

    for i in my_generator():
        print(i)

# Call the function to demonstrate memory leak prevention
prevent_memory_leaks_in_loops()

def normalize(data):
    if not isinstance(data, (list, tuple)):
        return None

    try:
        floats = [float(x) for x in data]
    except ValueError:
        return None

    if len(floats) == 0:
        return []

    min_val = min(floats)
    max_val = max(floats)

    denominator = max_val - min_val
    if denominator == 0:
        return [0.0] * len(floats)
    else:
        result = [(x - min_val) / denominator for x in floats]
        return result

class Data:
    def __init__(self, name, parent=None):
        self.name = name
        self.parent = parent  # type: Query
        self.values = {}     # key: field (str), value: scalar or list
        self.conditions = []  # e.g., {'field': 'value'}

    def add_condition(self, field_name: str, condition_value):
        if field_name in self.name:
            return  # already part of the name

        if isinstance(condition_value, dict):
            for sub_field, sub_value in condition_value.items():
                new_value = {
                    **self.values,
                    f"{field_name}.{sub_field}": sub_value
                }
                self.values = {**self.values, field_name: new_value}
        else:
            self.values[field_name] = condition_value

    def __repr__(self):
        return f"Data(name={self.name}, parent={self.parent.__class__.__name__ if self.parent else 'None'})"

class Query:
    def __init__(self, name, collection, conditions=None):
        self.name = name
        self.parent = None  # type: Union[Query, None]
        self.conditions = conditions.copy() or []  # type: List[Dict[str, Any]]
        self.leaves = collection.copy() if isinstance(collection, list) else [collection]  # type: List[Data]

    def is_nested(self):
        return any(isinstance(query, Query) for query in (self.parent or {}).leaves)

    def get_parent(self):
        if not hasattr(self, 'parent'):
            parent = next((q for q in self.leaves if q.name == self.name), None)
            if parent:
                parent.parent = self
            return parent
        else:
            return self.parent

    def collect_all_leaves(self):
        leaves = []
        for leaf in self.leaves.copy():
            if leaf.parent is not None and leaf.parent.name != leaf.name:
                new_leaf = leaf.parent.get_parent()
                leaves.append(new_leaf)
            leaves.extend(leaf.collect_all_leaves() if hasattr(leaf, 'collect_all_leaves') else [])
        return leaves

    def evaluate(self):
        result = {}
        for data in self.collect_all_leaves():
            current_data = data
            while True:
                key_path = []
                current_value = current_data.values.copy()
                current_leaf = current_data
                # Check if there's a query to pass as an argument (nested query)
                args = [query.name for query in (current_leaf.parent or {}).leaves]
                has_nested_query = any([isinstance(q, Query) for q in (current_leaf.parent or {}).leaves])

                while current_leaf and isinstance(current_leaf.values, dict):
                    field, value = next(iter(current_leaf.values.items()))
                    if field.startswith(args[0]):
                        new_value = {field: value}
                        for k, v in list(new_value.keys()):
                            if not any([k.startswith(a) for a in args]):
                                del new_value[k]
                        current_value.update(new_value)
                        key_path.append(args.pop(0))
                    else:
                        if args and isinstance(value, dict):
                            current_leaf = Data(''.join(key_path + [field]), parent=current_leaf.parent or None)
                            current_leaf.add_condition(field, value)
                            break
                        elif args:
                            field = ''.join([args[-1]] + key_path) if key_path else args[-1]
                            if isinstance(value, dict):
                                new_value = {}
                                for k, v in list(value.items()):
                                    new_value[''.join([field] + [k])] = v
                                current_value.update(new_value)
                            else:
                                result.setdefault(field, []).append(current_data.values.copy())
                        else:
                            break

                if has_nested_query and args:
                    key_path.append(args.pop(0))
                else:
                    for field in list(key_path):
                        del key_path[-1]

                if not current_leaf or not isinstance(current_leaf.values, dict) or not key_path:
                    result.setdefault(''.join(key_path), []).extend([current_value])
                    break
        return {k: v.copy() for k, v in result.items()}

