import socket
import threading

class MessageBroker:
    def __init__(self, host='127.0.0.1', port=12345):
        self.host = host
        self.port = port
        self.server_socket = None
        self.clients = []

    def start_broker(self):
        self.server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.server_socket.bind((self.host, self.port))
        self.server_socket.listen(5)

        print(f"Server is listening on {self.host}:{self.port}")

        while True:
            client_socket, address = self.server_socket.accept()
            print(f"New connection from {address}")

            # Add new client to the list of clients
            self.clients.append(client_socket)
            threading.Thread(target=self.handle_client, args=(client_socket,)).start()

    def broadcast(self, message):
        for client in self.clients:
            try:
                client.send(message.encode())
            except Exception as e:
                print(f"Error sending message to client: {e}")
                self.clients.remove(client)

    def close_broker(self):
        if self.server_socket is not None:
            self.server_socket.close()
            self.clients = []

def handle_client(client_socket):
    try:
        while True:
            # Receive data from the client
            data = client_socket.recv(1024)
            if not data:
                break

            print(f"Received message: {data.decode()}")

            # Broadcast message to all connected clients
            self.broadcast(data.decode())
    except Exception as e:
        print(f"Error handling client: {e}")
        client_socket.close()
        self.clients.remove(client_socket)

def main():
    broker = MessageBroker()

    try:
        broker.start_broker()
    except KeyboardInterrupt:
        print("Server stopped")
    finally:
        broker.close_broker()

if __name__ == "__main__":
    main()

from sqlalchemy import declarative摸, event, text
from sqlalchemy.orm import sessionmaker

class QueryPerfMonitor:
    def __init__(self):
        self.engine = declarative摸()
        self.session_maker = sessionmaker(engine)
        self.start()

    def start(self):
        self.engine.connect()

        # Create a listener to monitor all queries by default unless told otherwise
        event.listen(text, 'start_query').on(
            lambda e: self._record_query(e.model),
            lambda e: self._record_query(e.model).time.time()  # timeout is set to 1 second here
        )

    def stop(self):
        if hasattr(self, '_listener'):
            self._listener.drop()
        delattr(self, '_listener')

        try:
            self.engine.dispose()
        except Exception as e:
            print(f"Error disposing engine: {e}")

    def _record_query(self, model):
        try:
            # Create a new query each time
            q = sessionmaker(bind=self.engine)(filter=False)
            q.query(model)
        finally:
            pass  # Ensure the listener is removed regardless of success or failure

    @staticmethod
    def monitor(model_class):
        return QueryPerfMonitor()

