import datetime
import time

class EventProcessor:
    def __init__(self):
        self.latency_history = []

    def process_event(self, event, expected_processing_time):
        start_time = time.time()
        # Simulate event processing (replace with actual event processing logic)
        # For demonstration purposes, assume it takes 10ms to process an event
        time.sleep(0.01)  # 10ms delay for simulation

        end_time = time.time()
        elapsed_time = (end_time - start_time)

        # Calculate latency in milliseconds
        latency_ms = (elapsed_time * 1000) - expected_processing_time

        if latency_ms > 0:
            self.latency_history.append((event, elapsed_time))
            print(f"Event '{event}' processed with latency of {latency_ms:.2f}ms")
        else:
            print(f"Event '{event}' processed immediately")

    def get_average_latency(self):
        if not self.latency_history:
            return 0
        total_latency = sum(elapsed_time for _, elapsed_time in self.latency_history)
        average_latency = (total_latency / len(self.latency_history)) * 1000
        return average_latency

def main():
    processor = EventProcessor()

    # Example events with expected processing times
    events_with_expected_processing_times = [
        {"event": "Event A", "expected_processing_time": 10},
        {"event": "Event B", "expected_processing_time": 20},
        {"event": "Event C", "expected_processing_time": 30}
    ]

    for event in events_with_expected_processing_times:
        processor.process_event(event["event"], event["expected_processing_time"])

    average_latency = processor.get_average_latency()
    print(f"Average latency: {average_latency:.2f}ms")

if __name__ == "__main__":
    main()

