class ShoppingCart:
    def __init__(self):
        self.cart = {}

    # Method to add items into the cart
    def add_item(self, item, quantity):
        if item not in self.cart:
            self.cart[item] = quantity
        else:
            self.cart[item] += quantity

    # Method to remove items from the cart
    def remove_item(self, item):
        if item in self.cart:
            del self.cart[item]
        else:
            print("The item is not in the cart")

    # Method to modify the quantity of an item in the cart
    def modify_quantity(self, item, quantity):
        if item in self.cart and quantity >= 0:
            self.cart[item] = quantity
        else:
            print("The item is not in the cart or the new quantity is invalid")

    # Method to display the current state of the shopping cart
    def view_cart(self):
        for item, quantity in self.cart.items():
            print(f"Item: {item}, Quantity: {quantity}")

import os
import yaml
from cryptography.fernet import Fernet  # For handling sensitive data


def load_config(tenant_id):
    """
    Load or create tenant configuration file and return the raw content.
    If tenant ID is not provided, raises ValueError.
    """
    if not tenant_id:
        raise ValueError("Tenant ID must be provided")

    config_dir = "config"
    config_path = f"{config_dir}/{tenant_id}.yaml"

    try:
        with open(config_path, 'r') as file:
            return yaml.safe_load(file)
    except FileNotFoundError:
        # Create empty file
        open(config_path, 'a').close()
        # Return empty dict to force re-generation of keys next time
        return {}
    except Exception as e:
        raise ValueError(f"Failed to load tenant config: {e}")


def save_config(tenant_id, data):
    """
    Save configuration changes back to the file.
    """
    config_dir = "config"
    config_path = f"{config_dir}/{tenant_id}.yaml"

    try:
        with open(config_path, 'w') as file:
            yaml.safe_dump(data, file)
    except Exception as e:
        raise ValueError(f"Failed to save tenant config: {e}")


def generate_api_keys():
    """
    Generate random API keys for public and private use.
    """
    key_size = 32
    fernet = Fernet(os.urandom(key_size))

    return {
        "public_key": fernet.key.decode('utf-8'),
        "private_key": fernet.get_fernet().decode('utf-8')
    }


def get_api_key(tenant_id, keys):
    """
    Get the API key for a specific tenant.
    """
    if not tenant_id:
        raise ValueError("Tenant ID must be provided")

    config_path = f"config/{tenant_id}.yaml"

    try:
        with open(config_path, 'r') as file:
            tenant_config = yaml.safe_load(file)

            if not all(key in tenant_config for key in keys):
                raise KeyError(f"Missing required API key: {keys}")

            return tenant_config[keys[0]]

    except FileNotFoundError:
        print(f"Tenant config not found. Generating new keys...")
        api_keys = generate_api_keys()
        save_config(tenant_id, api_keys)
        return api_keys[keys[0]]

    except Exception as e:
        raise ValueError(f"Failed to get API key for tenant {tenant_id}: {e}")


if __name__ == "__main__":
    try:
        tenant_id = input("Enter tenant ID: ").strip()
        if not tenant_id:
            print("Error: Tenant ID is required")
            exit(1)

        keys_to_get = ["public_key", "private_key"]
        api_key = get_api_key(tenant_id, keys_to_get)
        print(f"API key for tenant {tenant_id}: {api_key}")

    except ValueError as e:
        print(e)
    except Exception as e:
        print(f"An error occurred: {e}")

import xml.etree.ElementTree as ET

def parse_xml(xml_str):
    try:
        # Decode bytes if necessary
        if isinstance(xml_str, bytes):
            xml_str = xml_str.decode('utf-8', errors='ignore')

        root = ET.fromstring(xml_str)
        children = []

        for child in root.children:
            sanitized_child = ET.Element(str(child.tag))

            # Sanitize attributes to remove potentially dangerous content
            for attr_name, attribute_value in child.items():
                if not attr_name.startswith('_'):
                    sanitized_child.set(attr_name, attribute_value)

            children.append(sanitized_child)

        return children

    except Exception as e:
        print(f"Error parsing XML: {e}")
        return None

class AccessLevel():
    def __init__(self, level):
        self.level = level

    def can_view(self):
        if self.level in ['guest', 'user', 'admin']:
            return True
        else:
            return False

    def can_edit(self):
        if self.level in ['user', 'admin']:
            return True
        else:
            return False

    def can_delete(self):
        if self.level == 'admin':
            return True
        else:
            return False

    def upgrade(self):
        levels = ['guest', 'user', 'admin']
        current_index = levels.index(self.level)
        if current_index < len(levels) - 1:
            self.level = levels[current_index + 1]

    def downgrade(self):
        levels = ['guest', 'user', 'admin']
        current_index = levels.index(self.level)
        if current_index > 0:
            self.level = levels[current_index - 1]

# Example usage:
user = AccessLevel('guest')
print(user.can_view())    # Outputs: True
print(user.can_edit())    # Outputs: False
print(user.can_delete())  # Outputs: False

user.upgrade()
print(user.level)         # Outputs: 'user'

user.upgrade()
print(user.can_edit())    # Outputs: True
print(user.can_delete())  # Outputs: False

user.upgrade()
print(user.can_delete())  # Outputs: True

class Resource:
    def __init__(self, name):
        self.name = name
        self.attributes = {}

    def add_attribute(self, attribute_name, value):
        self.attributes[attribute_name] = value

    def has_permission(self, subject_attributes, permission):
        for attribute_name in subject_attributes:
            if attribute_name not in self.attributes:
                return False
            if self.attributes[attribute_name] == 'false':
                return False
        return permission in self.attributes


class Subject:
    def __init__(self, name):
        self.name = name
        self.attributes = {}

    def add_attribute(self, attribute_name, value):
        self.attributes[attribute_name] = value

    def has_permission(self, resource_attributes, permission):
        for attribute_name in resource_attributes:
            if attribute_name not in self.attributes:
                return False
            if self.attributes[attribute_name] == 'false':
                return False
        return permission in self.attributes


class ABACSystem:
    def __init__(self):
        self.resources = {}
        self.subjects = {}

    def add_resource(self, resource):
        self.resources[resource.name] = resource

    def add_subject(self, subject):
        self.subjects[subject.name] = subject

    def evaluate_access(self, subject_name, resource_name, permission):
        if subject_name not in self.subjects:
            return False
        if resource_name not in self.resources:
            return False
        subject_attributes = self.subjects[subject_name].attributes
        resource_attributes = self.resources[resource_name].attributes
        return self.resources[resource_name].has_permission(subject_attributes, permission)


# Example usage:

abac_system = ABACSystem()

resource1 = Resource('Resource 1')
resource1.add_attribute('can_view', 'true')

resource2 = Resource('Resource 2')
resource2.add_attribute('can_edit', 'false')

subject1 = Subject('Subject 1')
subject1.add_attribute('can_view', 'true')

abac_system.add_resource(resource1)
abac_system.add_resource(resource2)

abac_system.add_subject(subject1)

print(abac_system.evaluate_access('Subject 1', 'Resource 1', 'can_view'))  # Output: True
print(abac_system.evaluate_access('Subject 1', 'Resource 1', 'can_edit'))   # Output: False

import datetime

class BaseModel:
    def __init__(self):
        self.version = 1.0

    def update_version(self, new_version=None):
        if new_version is not None:
            self.version = new_version
        return f"Version updated to {self.version}"

    def get_version(self):
        return f"Current Version: {self.version}"


class Model(BaseModel):
    def __init__(self, name):
        super().__init__()
        self.name = name

    def update_model(self, new_name=None, new_version=None):
        if new_name is not None:
            self.name = new_name
        if new_version is not None:
            return BaseModel().update_version(new_version)
        else:
            raise ValueError("New version is required")

    def get_info(self):
        return f"{self.get_version()} - Model Name: {self.name}"


class ModelManager:
    def __init__(self):
        self.models = {}

    def add_model(self, model_name, model_data):
        if model_name not in self.models:
            model = Model(model_name)
            self.models[model_name] = model
        else:
            raise ValueError(f"Model with name {model_name} already exists")

    def update_model_version(self, model_name, new_version):
        if model_name in self.models:
            self.models[model_name].update_version(new_version)
        else:
            raise ValueError(f"Model with name {model_name} does not exist")

    def get_model_info(self, model_name):
        if model_name in self.models:
            return self.models[model_name].get_info()
        else:
            raise ValueError(f"Model with name {model_name} does not exist")


# Example usage
if __name__ == "__main__":
    manager = ModelManager()

    # Add a new model
    manager.add_model("User", "A simple user model")

    # Update the version of the user model
    print(manager.update_model_version("User", 2.0))

    # Get the info of the User model with updated version
    print(manager.get_model_info("User"))

