import time

class EmailRateLimiter:
    def __init__(self, max_emails_per_minute):
        self.max_emails = max_emails_per_minute
        self.last_email_sent_time = 0
        self.emails_sent_this_minute = 0

    def can_send_email(self):
        current_time = time.time()
        if (current_time - self.last_email_sent_time) >= 60:
            # Start a new minute
            self.emails_sent_this_minute = 0
            self.last_email_sent_time = current_time

        if self.emails_sent_this_minute < self.max_emails:
            return True
        else:
            return False

    def send_email(self):
        if self.can_send_email():
            # Here, put the logic to send an email
            print("Email sent successfully")
            self.emails_sent_this_minute += 1
        else:
            print("Rate limit exceeded for this minute")

import sys
import os
from plint import plint
import importlib

# Initialize the whitelist; adjust as needed
Whitelist = {
    'numpy': True,
    'pandas': True,
    'scikit-learn': True,
    # Add more packages to your whitelist here
}

def check_package_license(package_name, enforce=True):
    """Check if a package uses an SPDX-licensed library and enforce its license."""
    try:
        result = plint(f'import {package_name};', ignore exempt=True)
        if not enforce:
            return True
        # Check if the package uses an open source compatible library
        has_open_source incompatible_license = any(
            pkg.__copyright__ == ' SPDX',
            for pkg in importlib.util.find_spec(package_name).__dict__.values()
        )
        return not has_open_source_incompatible_license, result
    except Exception as e:
        print(f"Error checking {package_name}: {e}", file=sys.stderr)
        if enforce:
            raise

def enforce_penalty(package_name):
    """Enforce a penalty for using an unauthorized library."""
    penalty = PENALTY_WHITELIST.get(package_name, 0)
    if penalty > 0 and not Whitelist[package_name]:
        print(f"Penalty: {PENALTY_VALUE} for using {package_name}")
    else:
        print(f"{package_name} is allowed")

def load_dependencies():
    """Load dependencies from pipenv and check licenses against whitelist."""
    env = os.environ.get('PIPENV_ENV', 'development')
    try:
        # Load requirements.txt
        reqs_path = os.path.join(os.path.dirname(__file__), 'requirements.txt')
        with open(reqs_path, 'r') as f:
            requirements = [line.strip() for line in f.readlines()]

        # Import each dependency and check license
        for pkg_name in requirements:
            try:
                module = __import__(pkg_name)
                allowed, result = check_package_license(pkg_name)
                if not allowed:
                    enforce_penalty(pkg_name)
                print(f"{pkg_name} {result}")
            except Exception as e:
                print(f"Error loading {pkg_name}: {e}", file=sys.stderr)

def main():
    global PENALTY_WHITELIST, PENALTY_VALUE
    # Initialize environment variables for penalty enforcement
    PENALTY_WHITELIST = os.environ.get('PENALTY_WHITELIST', '')
    PENALTY_VALUE = int(os.environ.get('PENALTY_VALUE', 0))

    print("Checking dependencies against license whitelist...")
    load_dependencies()
    print("Dependencies checked successfully.")

if __name__ == '__main__':
    main()

