import shutil
import os

def secure_move(src, dst):
    # Check if source exists
    if not os.path.exists(src):
        print("The source path does not exist")
        return False

    # Check if destination directory exists, if not create it
    if not os.path.exists(dst):
        try:
            os.makedirs(dst)
        except OSError as error:
            print("Error creating destination directory: ", error)
            return False

    # Check for permissions before moving the file
    if not (os.access(src, os.R_OK) and os.access(dst, os.W_OK)):
        print("You do not have permission to move the file")
        return False

    try:
        shutil.move(src, dst)
        return True
    except IOError as e:
        print("Unable to move the file. Error:", e)
        return False

# Example usage:
source = "/path/to/source/file"
destination = "/path/to/destination/directory"

if secure_move(source, destination):
    print("File moved successfully.")
else:
    print("File move failed.")

