class TenantResourceLimiter:
    def __init__(self, tenants):
        self.tenants = tenants

    def check_cpu_limit(self, tenant_name, cpu_usage):
        tenant = next((t for t in self.tenants if t.name == tenant_name), None)
        if tenant and cpu_usage > tenant.cpu_limit:
            raise ValueError(f"CPU usage exceeded limit ({cpu_usage} > {tenant.cpu_limit})")

    def check_memory_limit(self, tenant_name, memory_usage):
        tenant = next((t for t in self.tenants if t.name == tenant_name), None)
        if tenant and memory_usage > tenant.memory_limit:
            raise ValueError(f"Memory usage exceeded limit ({memory_usage} > {tenant.memory_limit})")

    def check_storage_limit(self, tenant_name, storage_usage):
        tenant = next((t for t in self.tenants if t.name == tenant_name), None)
        if tenant and storage_usage > tenant.storage_limit:
            raise ValueError(f"Storage usage exceeded limit ({storage_usage} > {tenant.storage_limit})")


