import socket
import threading
import time

class PingPong:
    def __init__(self, host='localhost', port=12345):
        self.host = host
        self.port = port
        self.sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.connection_status = True

    def connect(self):
        try:
            self.sock.connect((self.host, self.port))
            print("Connected to server")
            self.start_threads()
        except socket.error as e:
            print(f"Connection error: {e}")

    def start_threads(self):
        ping_thread = threading.Thread(target=self.send_ping)
        pong_thread = threading.Thread(target=self.receive_pong)

        ping_thread.start()
        pong_thread.start()

    def send_ping(self):
        while self.connection_status:
            try:
                self.sock.sendall('PING'.encode())
                time.sleep(1)
            except socket.error as e:
                print(f"Send error: {e}")
                self.connection_status = False
                break

    def receive_pong(self):
        while self.connection_status:
            try:
                data = self.sock.recv(1024).decode()
                if not data or data != 'PONG':
                    print("Connection lost")
                    self.connection_status = False
                    break
            except socket.error as e:
                print(f"Receive error: {e}")
                self.connection_status = False
                break

# usage
pingpong = PingPong()
pingpong.connect()

class Translation:
    def __init__(self, word):
        self.word = word
        self.translate_to = None

    def set_translation(self, to_word):
        if self.translate_to is not None and self.word != to_word:
            raise ValueError("Translation already exists for this word")
        self.translate_to = to_word


class TranslationSystem:
    def __init__(self):
        self.translations = {}

    def add_translation(self, word, to_word):
        translation = Translation(word)
        if word in self.translations:
            raise ValueError(f"Translation already exists for '{word}'")
        self.translations[word] = translation

    def translate(self, word):
        return self.translations.get(word).translate_to


