import unicodedata

def clean_string(s):
    if isinstance(s, bytes):
        try:
            decoded = s.decode('utf-8-sig')
        except UnicodeDecodeError:
            return ''
    else:
        decoded = str(s)

    stripped = decoded.strip()
    normalized = unicodedata.normalize('NFC', stripped)
    return normalized

def calculate_total_stock(products):
    """Calculate the total number of items in stock."""
    return sum(products.values())

def track_stock_below_threshold(products, threshold=5):
    """Track products with stock below a specified threshold."""
    below_threshold = {}
    for product, quantity in products.items():
        if quantity < threshold:
            below_threshold[product] = quantity
    return below_threshold

def update_stock_count(products, product_name, delta):
    """Update the stock count for a specific product."""
    if product_name not in products:
        print(f"Error: Product '{product_name}' does not exist.")
        return

    current Stock = products[product_name]

    try:
        new_stock = current_stock + delta
        products[product_name] = new_stock

    except ValueError:
        print(f"Error: Invalid number of units to add or subtract.")
        return

def main():
    # Initialize products and stock counts
    products = {
        'Product A': 100,
        'Product B': 50,
        'Product C': 25,
        'Product D': 75,
        'Product E': 30
    }

    print("Welcome to Stock Monitor!")
    print("Enter 'exit' to quit.")

    while True:
        # Calculate and display total stock
        total = calculate_total_stock(products)
        print(f"Total stock: {total} items")

        # Check for products below stock threshold (default 5)
        below_threshold = track_stock_below_threshold(products)
        if below_threshold:
            print("\nProducts with stock below 5 units:")
            for product, quantity in below_threshold.items():
                print(f"{product}: {quantity} items")

        # Get user action
        action = input("Enter 'add' or 'remove' to update a product's stock, or 'exit': ").lower()

        if action == 'exit':
            break

        if action not in ['add', 'remove']:
            continue

        while True:
            try:
                # Get the product name
                product_name = input(f"Enter product '{product}': ").strip().upper()

                if product_name not in products:
                    print("Product not found. Please enter a valid product.")
                    continue

                delta = int(input(f"Enter number of units to add or remove: "))

                if action == 'add':
                    update_stock_count(products, product_name, delta)
                elif action == 'remove' and delta > 0:
                    update_stock_count(products, product_name, -delta)

                break
            except ValueError as e:
                print(f"Invalid input. {e}")

    print("\nGoodbye!")

if __name__ == "__main__":
    main()

import asyncio
import time

async def read_file(file_path):
    async with open(file_path, 'r') as f:
        while True:
            try:
                content = await f.read(1024)
                if not content:
                    break
            except BrokenPipeError:
                break
            except UnicodeDecodeError:
                raise
            else:
                yield content

async def process_files(files):
    file_queue = asyncio.Queue()
    for file in files:
        await file_queue.put(file)

    while True:
        try:
            file_task = await file_queue.get()
            async for content in read_file(file_task):
                time.sleep(0.1)  # Simulate task processing
                pass
        except asyncio.CancelledError:
            break

async def main():
    files = ['file1.txt', 'file2.txt', 'file3.txt']
    try:
        loop = asyncio.new_event_loop()
        await loop.run_coroutine_threadsafe(asyncio.run_coroutine(main(), loop), loop)
    except KeyboardInterrupt:
        print("Exiting gracefully.")

if __name__ == '__main__':
    main()

import datetime

class Transaction:
    def __init__(self, price, timestamp):
        self.price = price
        self.timestamp = timestamp

class PriceManipulator:
    def __init__(self):
        self.transactions = []

    def add_transaction(self, price, timestamp):
        transaction = Transaction(price, timestamp)
        self.transactions.append(transaction)

    def detect_price_manipulation(self):
        # Calculate the average price over the last 5 minutes
        current_timestamp = datetime.datetime.now()
        recent_transactions = [t for t in self.transactions if t.timestamp >= current_timestamp - datetime.timedelta(minutes=5)]

        if len(recent_transactions) > 0:
            average_price = sum(t.price for t in recent_transactions) / len(recent_transactions)
            for transaction in self.transactions:
                if abs(transaction.price - average_price) > 10:  # adjust this threshold as needed
                    print(f"Price manipulation detected! Transaction at {transaction.timestamp} has price {transaction.price}")
                    return True
        return False

# Example usage
