    elif action == "exit":
        break
    else:
        print("Invalid input. Please try again.")

    # Detect price manipulation every 5 seconds
    if current_time % 5 == 0:
        if price_manipulator.detect_price_manipulation():
            exit()

import weakref

class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

# Create a list of nodes
nodes = [Node(i) for i in range(10)]

def main():
    # Create a cycle to create dangling pointers
    nodes[0].next = nodes[-1]

    # Use weakref to detect cycles
    weak_nodes = [weakref.ref(node) for node in nodes]

    try:
        while True:
            for ref_node in weak_nodes[:]:
                if ref_node() is None:
                    print("Node", ref_node()[0], "has been garbage collected")
                    weak_nodes.remove(ref_node)
                else:
                    # We have found a cycle
                    print("Cycle detected between node", ref_node()[0].data, "and node", ref_node()[0].next.data)
    except IndexError:
        pass

if __name__ == "__main__":
    main()

