import time
from collections import deque

class RateLimiter:
    def __init__(self, max_calls: int, period: int):
        self.max_calls = max_calls  # Maximum number of calls allowed in the given period
        self.period = period  # Period in seconds
        self.call_timestamps = deque()  # We use a double-ended queue to store timestamps

    def wait(self):
        current_time = time.monotonic()

        # Remove timestamps that are older than the period
        while self.call_timestamps and (current_time - self.call_timestamps[0]) > self.period:
            self.call_timestamps.popleft()

        # If we've exceeded the limit, wait until we can make a call
        if len(self.call_timestamps) >= self.max_calls:
            time_to_wait = self.period - (current_time - self.call_timestamps[0])
            if time_to_wait > 0:
                print(f"Rate limit exceeded, sleeping for {time_to_wait} seconds")
                time.sleep(time_to_wait)

        # Add the current timestamp to our queue
        self.call_timestamps.append(current_time)

