import logging
from threading import Lock

class TenantLogger(object):
    _instance = None
    _lock = Lock()
    _loggers = {}

    def __new__(cls, tenant_id=None):
        if cls._instance is None:
            with cls._lock:
                if cls._instance is None:
                    cls._instance = super(TenantLogger, cls).__new__(cls)
        return cls._instance

    def __init__(self, tenant_id=None):
        self.tenant_id = tenant_id

        # Create a new logger if not already exists
        if self.tenant_id and self.tenant_id not in self._loggers:
            logger = logging.getLogger(f'TenantLogger_{self.tenant_id}')
            handler = logging.FileHandler(f'/path/to/logs/{self.tenant_id}.log')

            # Create formatter and add it to the handlers
            formatter = logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s')
            handler.setFormatter(formatter)

            logger.addHandler(handler)
            self._loggers[self.tenant_id] = logger

    def info(self, message):
        if self.tenant_id:
            self._loggers[self.tenant_id].info(message)

