import sys

def parse_args():
    args = sys.argv[1:]
    if len(args) == 0:
        print("No arguments provided")
        return
    for i, arg in enumerate(args):
        if arg.startswith("-"):
            # Check if the argument is a flag (e.g., -h or --help)
            if arg == "-h" or arg == "--help":
                print("Usage: python script.py [flags]")
                return
            else:
                # If the argument is not a recognized flag, raise an error
                raise ValueError(f"Unrecognized flag {arg}")
        else:
            # If the argument is not a flag, assume it is a positional argument
            print(f"Positional argument {i + 1}: {arg}")

