import re

def validate_date(date_string):
    pattern = r"^\d{4}-\d{2}-\d{2}$"
    if not re.match(pattern, date_string):
        return False
    year, month, day = map(int, date_string.split("-"))
    if year < 1 or year > 9999:
        return False
    if month < 1 or month > 12:
        return False
    if day < 1 or day > 31:
        return False
    return True

def validate_time(time_string):
    pattern = r"^\d{2}:\d{2}:\d{2}$"
    if not re.match(pattern, time_string):
        return False
    hour, minute, second = map(int, time_string.split(":"))
    if hour < 0 or hour > 23:
        return False
    if minute < 0 or minute > 59:
        return False
    if second < 0 or second > 59:
        return False
    return True

def validate_datetime(date_time_string):
    pattern = r"^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$"
    if not re.match(pattern, date_time_string):
        return False
    year, month, day = map(int, date_time_string.split("-")[0].split())
    hour, minute, second = map(int, date_time_string.split(" ")[1].split(":"))
    if year < 1 or year > 9999:
        return False
    if month < 1 or month > 12:
        return False
    if day < 1 or day > 31:
        return False
    if hour < 0 or hour > 23:
        return False
    if minute < 0 or minute > 59:
        return False
    if second < 0 or second > 59:
        return False
    return True

