    time_string = "12:00:00"
    datetime_string = "2022-01-31 12:00:00"
    print(validate_date(date_string))
    print(validate_time(time_string))
    print(validate_datetime(datetime_string))

import hashlib
import json

class TenantData:
    def __init__(self, tenant_id):
        self.tenant_id = tenant_id
        self.data = {}

    def add_data(self, key, value):
        hashed_key = hashlib.sha256(str(key).encode()).hexdigest()
        if hashed_key not in self.data:
            self.data[hashed_key] = {}

        self.data[hashed_key][self.tenant_id] = value

    def get_data(self, tenant_id=None):
        if tenant_id is None:
            return {hashed_key: data for hashed_key, data in self.data.items()}

        # Find all the hashed keys that correspond to this tenant
        hashed_keys = [key for key, data in self.data.items() if self.tenant_id in data]

        # Construct a dictionary with the correct tenant ID for each value
        result = {}
        for key in hashed_keys:
            result[key] = {tenant: data[tenant] for tenant in self.tenant_id if data.get(self.tenant_id) is not None}

        return result

    def delete_data(self, key):
        hashed_key = hashlib.sha256(str(key).encode()).hexdigest()

        # Remove the entire tenant-specific data for this key
        if hashed_key in self.data:
            del self.data[hashed_key]

# Usage example:

