import graphene
from graphene import ObjectType, Field, String
from graphene import Schema
from graphene_auth import AuthMutation, AuthenticationMiddleware
import jwt
import datetime

# Define the schema for our GraphQL endpoint
class Query(graphene.ObjectType):
    # Define a field to query the user's name
    user = graphene.Field(String)

    def resolve_user(self, info):
        return "John Doe"

# Define a mutation to update the user's name
class UpdateUser(graphene.Mutation):
    class Arguments:
        new_name = graphene.String()

    updated_user = graphene.Field(String)
    def mutate(self, info, new_name):
        # Simulate an authentication token validation process
        token = "your_auth_token"
        try:
            decoded_token = jwt.decode(token, 'your_secret_key', algorithms=['HS256'])
            return UpdateUser(updated_user=decoded_token['name'])
        except jwt.ExpiredSignatureError:
            print("Token has expired")
            raise graphene AuthenticationError(message='Invalid token')
        except jwt.InvalidTokenError:
            print("Invalid token")
            raise graphene.AuthenticationError(message='Invalid token')

# Create the AuthMutation class with authentication middleware
class AuthMutation(graphene.Mutation):
    auth = graphene.Field(AuthenticationResult)

    class Arguments:
        username = graphene.String()
        password = graphene.String()

    def mutate(self, info, username, password):
        try:
            # Simulate a user checking their credentials
            user_data = {"username": "your_username", "password": "your_password"}
            if username == user_data['username'] and password == user_data['password']:
                token = jwt.encode({"username": user_data['username'], "exp": datetime.datetime.now() + datetime.timedelta(minutes=30)}, 'your_secret_key', algorithm="HS256")
                return AuthMutation(auth=token)
            else:
                raise graphene.AuthenticationError(message='Invalid credentials')
        except Exception as e:
            print(f"An error occurred: {e}")
            raise graphene.AuthenticationError(message='An error occurred')

# Define the AuthenticationResult class for our mutation
class AuthenticationResult(graphene.ObjectType):
    token = graphene.String()

# Create the schema and register the authentication middleware
schema = Schema(query=Query, mutation=AuthMutation)
middleware = AuthMiddleware(schema=schema)

# Start the GraphQL server
if __name__ == "__main__":
    server = graphqlHTTP({'schema': schema})
    server.addMiddleware(middleware)
    server.serve(on_port=8000)

