class Transaction:
    def __init__(self, amount):
        self.amount = amount
        self.charge_status = False

    def charge(self):
        if not self.charge_status:
            self.charge_status = True
            print(f"Charged ${self.amount} successfully.")
        else:
            print("Already charged.")

class Store:
    def __init__(self):
        self.transactions = []

    def add_transaction(self, amount):
        transaction = Transaction(amount)
        self.transactions.append(transaction)

# Example usage
store = Store()
store.add_transaction(100)  # Charges $100 and prints "Charged $100 successfully."
store.add_transaction(50)   # Prints "Already charged."

class DoubleChargePreventer:
    def __init__(self, store):
        self.store = store

    def prevent_double_charging(self):
        for transaction in self.store.transactions:
            if not transaction.charge_status:
                transaction.charge()
            else:
                print(f"Transaction ${transaction.amount} was already charged.")

# Usage
double_charge_preventer = DoubleChargePreventer(store)
double_charge_preventer.prevent_double_charging()

