import secrets
import string
from typing import Dict

class SessionManager:
    def __init__(self):
        # Generate a secret key for encryption
        self.secret_key = secrets.token_urlsafe(16)
        self.sessions: Dict[str, str] = {}

    def create_session(self, user_id: str) -> str:
        """Create a new session and store the user's data"""
        session_id = ''.join(secrets.choice(string.ascii_letters + string.digits) for _ in range(32))
        encrypted_data = self._encrypt(user_id)
        self.sessions[session_id] = encrypted_data
        return session_id

    def get_session(self, session_id: str) -> str:
        """Retrieve the user's data from a stored session"""
        if session_id not in self.sessions:
            raise ValueError("Invalid session ID")
        encrypted_data = self.sessions[session_id]
        return self._decrypt(encrypted_data)

    def delete_session(self, session_id: str):
        """Delete a stored session"""
        if session_id not in self.sessions:
            raise ValueError("Invalid session ID")
        del self.sessions[session_id]

    @staticmethod
    def _encrypt(data: str) -> str:
        """Encrypt data using the secret key"""
        # Simple encryption for demonstration purposes (not recommended for production use)
        return ''.join(chr((ord(c) + ord(secret_key[i % len(secret_key)])) % 256) for i, c in enumerate(data))

    @staticmethod
    def _decrypt(encrypted_data: str) -> str:
        """Decrypt data using the secret key"""
        # Simple decryption for demonstration purposes (not recommended for production use)
        return ''.join(chr((ord(c) - ord(secret_key[i % len(secret_key)])) % 256) for i, c in enumerate(encrypted_data))

# Example usage
if __name__ == "__main__":
    session_manager = SessionManager()

    # Create a new session and store user data
    user_id = "12345"
    session_id = session_manager.create_session(user_id)
    print(f"Created new session ID: {session_id}")

    # Retrieve the stored user data
    stored_data = session_manager.get_session(session_id)
    print(f"User ID: {stored_data}")

    # Delete the stored session
    session_manager.delete_session(session_id)

    # Attempt to retrieve deleted data (should raise an error)
    try:
        session_manager.get_session(session_id)
    except ValueError as e:
        print(f"Error: {e}")

