class TransactionProcessor:
    def __init__(self):
        self.processed_transactions = set()

    def process_transaction(self, transaction_id):
        if transaction_id in self.processed_transactions:
            print("Transaction already processed. Preventing double charging.")
            return False
        else:
            # Process the transaction here (e.g., update database, send confirmation)
            print(f"Processing new transaction: {transaction_id}")
            self.processed_transactions.add(transaction_id)
            return True

