import time

def process_message_with_retries(message, max_attempts=5, delay_between_retries=1):
    for attempt in range(max_attempts):
        try:
            result = process_message(message)
            print(f"Message processed successfully on attempt {attempt + 1}.")
            return result
        except Exception as e:
            if attempt < (max_attempts - 1):
                time.sleep(delay_between_retries)
    print("All attempts exhausted after", max_attempts, "attempts.")
    return None

