        # This ensures the table exists and is correctly structured.
        return True
    except sqlite3.IntegrityError as e:
        print(f"Username {username} already exists. Rolling back.")
        conn.rollback()
        return False
    except Exception as e:
        print(f"An error occurred during table creation: {e}")
        conn.rollback()
        return False

