import os

class TenantAccessControl:
    def __init__(self, config_path, tenant_name):
        self.tenant_name = tenant_name
        self.config_base_path = config_path
        self.TenantPermissions = {}

        # Load all tenant permissions for the base path
        self.load_all_permissions()

    def load_all_permissions(self):
        """Load and store permission strings from each tenant's config files."""
        if not os.path.exists(self.config_base_path):
            return

        tenant_permissions = {}  # Maps group names to their allowed status

        # Collect all files in the base path
        for file_name in os.listdir(self.config_base_path):
            file_path = os.path.join(self.config_base_path, file_name)

            if not os.path.isfile(file_path) or file_name == "__init__.py":
                continue

            with open(file_path, 'r', encoding='utf-8') as f:
                content = f.read().strip()

                # Extract tenant name (assumed to be in quotes within each permission line)
                tenant = None
                lines = [line.strip() for line in content.split('\n')]
                for line in lines:
                    if '"' in line:
                        tenant quoted = line.split('"')[0].strip()
                        if self.tenant_name == quoted:
                            tenant = True
                            break

                # Extract the permission string (everything after the tenant name)
                perm_string = content[len(f"'{self.tenant_name}'):"].strip()

                # If this is the first file, add it to the dictionary with an empty set of allowed groups
                if not tenant_permissions:
                    tenant_permissions[perm_string] = set()

                # Add each group permission from the file's lines
                for perm_line in content.splitlines():
                    perm = perm_line.strip()
                    tenant_permissions[perm_string].add(perm)

        self.TenantPermissions = tenant_permissions

    def get_admin_groups(self, admin_name):
        """Return a list of groups that an admin belongs to."""
        try:
            return self.TenantPermissions(admin_name).groups
        except KeyError:
            return []

    def check_access(self, admin_name, group_names):
        """
        Check if the admin has access based on their group memberships.

        Args:
            admin_name (str): The admin's name to check.
            group_names (list[str]): List of groups that the admin belongs to.

        Returns:
            bool: True if any of the groups are allowed, False otherwise.
        """
        if not self.TenantPermissions.exists(admin_name):
            return False

        for perm in self.TenantPermissions(admin_name).permission_set.all():
            if group_names and group_names[0] == perm:
                return True
        return False

    def load_tenant_permissions(self, tenant_name):
        """Load the permission configurations for a specific tenant."""
        if tenant_name != self.tenant_name:
            raise ValueError("Access to other tenants is not allowed.")

        # Load each tenant's permission file (if any)
        for file in os.listdir(f"{self.config_base_path}/{tenant_name}"):
            file_path = os.path.join(f"{self.config_base_path}/{tenant_name}", file)

            if os.path.isfile(file_path):
                with open(file_path, 'r', encoding='utf-8') as f:
                    content = f.read().strip()

                    tenant quoting lines
                    perm_string = content[len(f"'{tenant_name}'):"].strip()

                    for perm_line in content.splitlines():
                        perm = perm_line.strip()
                        self.TenantPermissions[tenant_name].add(perm)

        # Ensure permissions are loaded per tenant
        if tenant_name not in self.TenantPermissions:
            self.TenantPermissions[tenant_name] = set()

    def add_permission(self, admin_name, perm):
        """Add a permission for an admin to access."""
        if not self.TenantPermissions.exists(admin_name) or not perm in self.TenantPermissions[admin_name]:
            self.TenantPermissions[admin_name].add(perm)
            return True
        return False

    def remove_permission(self, admin_name, perm):
        """Remove a permission for an admin to access."""
        if perm in self.TenantPermissions(admin_name):
            self.TenantPermissions[admin_name].remove(perm)
            return True
        return False

