class EventBuffer:
    def __init__(self):
        self.buffer = []
        self.last_sequence = -1

    def add_event(self, sequence, data):
        # Append event to buffer
        self.buffer.append((sequence, data))

        # Sort the buffer by sequence number
        self.buffer.sort()

        # Process events in order
        for i, (seq, evt) in enumerate(self.buffer):
            if seq == self.last_sequence + 1:
                # If event is next in sequence, process it and remove from buffer
                self.process_event(evt)
                self.last_sequence = seq
                del self.buffer[i]
            else:
                # If there's a gap in the sequence, stop processing
                break

    def process_event(self, event):
        print('Processing event:', event)

# Create an instance of EventBuffer and simulate events arriving out of order
eb = EventBuffer()
events = [(3, 'third'), (1, 'first'), (5, 'fifth'), (2, 'second')]
for seq, evt in events:
    eb.add_event(seq, evt)

