import os
import psutil

def is_cronjob_running(command):
    for proc in psutil.process_iter(['pid', 'name', 'cmdline']):
        if proc.info['name'] == 'CRON' and command in proc.info['cmdline']:
            return True
    return False

def run_cronjob(command):
    if not is_cronjob_running(command):
        os.system(f"(crontab -l ; echo '{command}') | crontab -")
        print('Cron job added')
    else:
        print('Cron job already exists')

# Example usage:
run_cronjob("* * * * * /path/to/your/script.sh")

def handle_malformed_file(filename):
    try:
        with open(filename, 'rb') as f:
            data = f.read().decode('utf-8')
            return data
    except UnicodeDecodeError:
        # Try decoding as ASCII
        with open(filename, 'r', encoding='ascii') as f:
            return f.read()
    return ''

def decorated(func, max_calls):
    def wrapper(*args, **kwargs):
        nonlocal func
        # Initialize the counter outside the inner wrapper to ensure all branches share it
        count = [0]

        def f(*args2, **kwargs2):
            if count[0] < max_calls:
                count[0] += 1
                return func(*args2, **kwargs2)
            else:
                raise Exception("Function call limit exceeded")

        # Preserve the docstring of the original function
        f.__doc__ = func.__doc__

        # Preserve other possible attributes to allow full functools features
        if hasattr(func, ' __name__'):
            setattr(f, '__name__', func.__name__)
        if hasattr(func, ' __module__'):
            setattr(f, '__module__', func.__module__)
        return f

    return wrapper

# Example usage of the decorator with a maximum of 3 calls:
def myfunc():
    return "Hello"

myfunc = decorated(myfunc, 3)

try:
    print(myfunc())  # Hello
    print(myfunc())  # Hello
    print(myfunc())  # Hello
    print(myfunc())  # Exception: Function call limit exceeded
except Exception as e:
    print(e)

import re

def validate_phone_number(phone_number):
    # Define a regular expression pattern for a valid phone number
    pattern = r'^(\+?1\s?)?((?:\(\d{3}\))?\s?)(\d{3})(\s?)(\d{4})$'

    # Check if the phone number matches the pattern
    if re.match(pattern, phone_number):
        return True
    else:
        return False

