import datetime
from dataclasses import dataclass

@dataclass
class ModelVersion:
    """Data class representing a model version."""
    id: int
    model_name: str
    version_number: int
    created_at: datetime.datetime
    updated_at: datetime.datetime

class ModelVersionManager:
    """Class responsible for managing model versions."""

    def __init__(self):
        self.versions = {}

    def create_version(self, model_name, version_number):
        """Create a new model version."""
        if model_name not in self.versions:
            self.versions[model_name] = []

        new_version = ModelVersion(
            id=len(self.versions[model_name]) + 1,
            model_name=model_name,
            version_number=version_number,
            created_at=datetime.datetime.now(),
            updated_at=datetime.datetime.now()
        )

        self.versions[model_name].append(new_version)
        return new_version

    def update_version(self, model_name, version_id):
        """Update the specified model version."""
        if model_name not in self.versions:
            raise ValueError(f"Model {model_name} does not exist.")

        for version in self.versions[model_name]:
            if version.id == version_id:
                # Update created and updated timestamps
                version.created_at = datetime.datetime.now()
                version.updated_at = datetime.datetime.now()
                return version

        raise ValueError(f"Version {version_id} does not exist.")

    def get_version(self, model_name, version_id):
        """Retrieve the specified model version."""
        if model_name not in self.versions:
            raise ValueError(f"Model {model_name} does not exist.")

        for version in self.versions[model_name]:
            if version.id == version_id:
                return version

        raise ValueError(f"Version {version_id} does not exist.")

    def delete_version(self, model_name, version_id):
        """Delete the specified model version."""
        if model_name not in self.versions:
            raise ValueError(f"Model {model_name} does not exist.")

        for version in list(self.versions[model_name]):
            if version.id == version_id:
                self.versions[model_name].remove(version)
                return

# Example usage
manager = ModelVersionManager()

# Create a new model version
version1 = manager.create_version("example_model", 1)

print(f"Created Version: {version1.model_name} ({version1.version_number})")

# Update the created and updated timestamps of the first version
updated_version1 = manager.update_version("example_model", 1)
print(f"Updated Version: {updated_version1.id}")

# Get the first version
version2 = manager.get_version("example_model", 1)
print(f"Retrieved Version: {version2.model_name} ({version2.version_number})")

# Delete the first version
manager.delete_version("example_model", 1)

try:
    print(manager.get_version("example_model", 1))
except ValueError as e:
    print(e)  # Output: Version 1 does not exist.

class Inventory:
    def __init__(self):
        self.items = {}

    # Function to add item to inventory
    def add_item(self, name, quantity):
        if name in self.items:
            print(f"Item {name} already exists. Quantity will be updated.")
        self.items[name] = quantity

    # Function to remove item from inventory
    def remove_item(self, name, quantity):
        if name not in self.items:
            print("Item does not exist.")
            return False
        else:
            current_quantity = self.items[name]
            if current_quantity >= quantity:
                self.items[name] -= quantity
                return True
            else:
                print(f"Not enough quantity of {name} available. Available: {current_quantity}")
                return False

    # Function to check item's availability
    def check_availability(self, name):
        if name not in self.items:
            print("Item does not exist.")
            return False
        else:
            return True

    # Function to update quantity of item
    def update_quantity(self, name, new_quantity):
        if name in self.items:
            self.items[name] = new_quantity
        else:
            print("Item does not exist.")

    # Function to display inventory
    def display_inventory(self):
        for item, quantity in self.items.items():
            print(f"Item: {item}, Quantity: {quantity}")


