        if inventory.check_availability(name):
            print(f"Item {name} is available.")
        else:
            print(f"Item {name} does not exist.")
    elif choice == "4":
        name = input("Enter item name: ")
        new_quantity = int(input("Enter new quantity: "))
        inventory.update_quantity(name, new_quantity)
    elif choice == "5":
        inventory.display_inventory()
    elif choice == "6":
        break
    else:
