import hashlib
import getpass
from decimal import Decimal

class Product:
    def __init__(self, name, price):
        self.name = name
        self.price = price

class ShoppingCart:
    def __init__(self):
        self.items = []

    def add_item(self, product, quantity=1):
        if quantity > 0 and isinstance(product, Product) and isinstance(quantity, int):
            self.items.append((product, quantity))
        else:
            raise ValueError("Invalid product or quantity")

    def remove_item(self, product):
        for item in self.items:
            if item[0] == product:
                self.items.remove(item)
                return
        raise ValueError("Product not found in cart")

    def get_total_price(self):
        total = Decimal('0')
        for product, quantity in self.items:
            total += product.price * quantity
        return total

def secure_credit_card_input():
    # Get credit card number using getpass module to prevent echoing the input
    cc_number = getpass.getpass("Enter your credit card number: ")
    # Hash the credit card number for secure storage (real-world would use encryption)
    hashed_cc_number = hashlib.sha256(cc_number.encode()).hexdigest()
    return hashed_cc_number

import time
from functools import wraps

def log_activity(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        start = time.time()

        result = func(*args, **kwargs)

        end = time.time()
        execution_time = end - start

        with open('user_activities.log', 'a') as f:
            f.write(f'Function {func.__name__} was called. Execution Time: {execution_time}\n')

        return result
    return wrapper

