def validate_file_name(filename):
    # Maximum allowed length
    max_length = 256
    if len(filename) > max_length:
        return False

    # Check for spaces
    if ' ' in filename:
        return False

    # Allowed characters
    allowed_chars = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-@.")

    # Check each character
    for char in filename:
        if char not in allowed_chars:
            return False

    # Reserved keywords to exclude (e.g., 'config', 'notes')
    reserved_keywords = {"readme", "config", "appdata", "programfiles"}
    if any(keyword in filename.lower() for keyword in reserved_keywords):
        return False

    return True

