import threading
import time

class SessionManager:
    def __init__(self, timeout):
        self.timeout = timeout  # in seconds
        self.sessions = {}

    def create_session(self, user_id):
        if user_id not in self.sessions:
            session_start_time = time.time()
            self.sessions[user_id] = {
                'start_time': session_start_time,
                'last_activity': session_start_time
            }
            return True
        else:
            return False

    def update_last_activity(self, user_id):
        if user_id in self.sessions:
            self.sessions[user_id]['last_activity'] = time.time()

    def is_session_expired(self, user_id):
        if user_id in self.sessions:
            current_time = time.time()
            session_age = current_time - self.sessions[user_id]['start_time']
            last_activity_age = current_time - self.sessions[user_id]['last_activity']

            if (current_time - self.sessions[user_id]['start_time']) > self.timeout and \
               (current_time - self.sessions[user_id]['start_time']) != last_activity_age:
                del self.sessions[user_id]
                return True
            elif session_age > self.timeout or last_activity_age > self.timeout:
                del self.sessions[user_id]
                return True

        return False


# Example usage:

session_manager = SessionManager(timeout=300)  # Create a new manager with timeout of 5 minutes

def simulate_user_inactivity(user_id):
    while True:
        time.sleep(60)  # Sleep for 1 minute
        session_manager.update_last_activity(user_id)
        if not session_manager.is_session_expired(user_id):
            break

# Create two sessions
session_manager.create_session('user1')
session_manager.create_session('user2')

print("User 1 is still active:", session_manager.is_session_expired('user1'))  # Output: False
time.sleep(301)  # Wait for timeout to expire
print("User 1 has expired:", session_manager.is_session_expired('user1'))  # Output: True

# Stop user inactivity simulation
threading.Thread(target=simulate_user_inactivity, args=('user2',)).start()

