def admin_cmd(command, username, token):
    try:
        # Decode the JWT token and verify if it is valid
        payload = jwt.decode(token, os.environ['JWT_SECRET'], algorithms=['HS256'])

        # Check if the user has admin rights
        if 'admin' not in payload['roles']:
            logging.warning('Non-Admin user tried to run command')
            return {'error': 'Unauthorized'}

    except jwt.ExpiredSignatureError:
        return {'error': 'Token expired'}
    except jwt.InvalidTokenError:
        return {'error': 'Invalid token'}

    # If all checks are passed, log the command and run it
    logging.info(f'User {username} executed admin command: {command}')

    try: 
        # Encrypt the command before running it (This is a mock encryption)
        encrypted_cmd = cipher_suite.encrypt(bytes(command, 'utf-8'))

        # Mock running the command by returning an encrypted version of the input
        return {'output': encrypted_cmd}
    except Exception as e:
        logging.error('Error executing admin command')
        return {'error': str(e)}

