from lxml import etree
import namespace_utils

def safe_xml_deserializer(xml_str):
    try:
        # Create an object tree from the XML string
        otree = etree.ET.parse(xml_str)

        # Custom method to get children in a safe way, including attributes
        def _get_children_safe(parent):
            children = []
            namespace = namespace_utils.get_namespaces()[parent.nsmap]
            for child_tag in parent._nsmap.keys():
                if not (child_tag in parent or parent[child_tag].tag.is_ns()):
                    continue

                # Safely evaluate the child element's value
                child_value = parent.safe_eval(child_tag, namespaces=namespace)

                children.append({
                    'tag': child_tag,
                    'value': _evaluate_value(child_value),
                    'attr': parent.attrib.copy(),
                    'children': []
                })

            return children

        # Evaluate the root element and its nested elements
        result = _get_children_safe(otree._nsmap[otree.root])

        return {tag: data for tag, data in result.items()}
    except Exception as e:
        print(f"Error deserializing XML: {e}")
        return None

