import threading
import os

def terminate_hanging_threads():
    # Get all running threads
    threads = threading.enumerate()

    for thread in threads:
        if not thread.is_alive() or thread.name == 'MainThread':
            continue

        tid = thread.name
        try:
            # Send the terminate signal to the thread
            os.systemcall('kill', '-t', tid)
            print(f"Terminated thread {tid}")
        except Exception as e:
            print(f"Failed to terminate thread {tid}: {str(e)}")

if __name__ == "__main__":
    terminate_hanging_threads()

