class InventoryItem:
    def __init__(self, part_number, description, quantity):
        self.part_number = part_number
        self.description = description
        self.quantity = quantity

def validate_integer(prompt, min_val=1, max_val=None):
    """Validates user input for an integer between min_val and max_val (exclusive)."""
    while True:
        try:
            value = int(input(prompt))
            if min_val <= value < max_val:
                return value
            else:
                print(f"Please enter a number between {min_val} and {max_val}")
        except ValueError:
            print("Invalid input. Please enter a valid integer.")

def validate_string(prompt, allowed_chars="abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"):
    """Validates user input to ensure it only contains allowed characters."""
    while True:
        try:
            value = input(prompt).strip().upper()
            if all(c in allowed_chars for c in value):
                return value
            else:
                print(f"Invalid character(s) in input. Allowed characters: {allowed_chars}")
        except ValueError:
            print("Invalid input. Please enter a string with only alphanumeric characters.")

def main():
    print("Inventory Check Program")
    print("Please provide inventory data below.")

    items = []
    item_count = int(input("How many items do you want to check? "))

    for _ in range(item_count):
        part_number = validate_integer("Enter part number: ")
        description = validate_string("Enter item description: ").strip()
        expected_quantity = int(input(f"What is the expected quantity of {description}? "))

        # Create a new inventory item
        items.append(InventoryItem(part_number, description, expected_quantity))

    print("\nStarting inventory check...")

    for idx, item in enumerate(items):
        # Check if the actual quantity meets or exceeds the expected quantity
        pass_criteria = (item.quantity >= expected_quantity) or (item.quantity > 0)

        status = "Pass" if pass_criteria else "Fail"
        print(f"Item {idx+1}:")
        print(f"- Part Number: {item.part_number}")
        print(f"- Description: {item.description}")
        print(f"- Actual Quantity: {item.quantity}")
        print(f"- Expected Quantity: {expected_quantity}")
        print(f"- Status: {status}\n")

if __name__ == "__main__":
    main()

import graphql
from graphql import errors

class UserQuery:
    def __init__(self, users):
        self.users = users

    def resolve_user(self, parent, args, context, info):
        user_id = args['id']
        if not isinstance(user_id, int) or user_id < 0:
            raise errors.GraphQLError('Invalid user ID')
        return next((u for u in self.users if u.id == user_id), None)

