import hashlib
import time

class DistributedCache:
    def __init__(self):
        self.cache = {}
        self.ttl = 3600 # seconds
        self.lock = threading.Lock()

    def get(self, key):
        with self.lock:
            value = self.cache.get(key)
            if value is not None and time.time() - value['time'] < self.ttl:
                return value['value']
            else:
                return None

    def set(self, key, value):
        with self.lock:
            self.cache[key] = {
                'value': value,
                'time': time.time()
            }

# Example usage
cache = DistributedCache()
print(cache.get('hello')) # None
cache.set('hello', 'world')
print(cache.get('hello')) # 'world'

