def traverse_tree(node, max_depth, current_depth=1):
    if current_depth > max_depth:
        return
    print('Depth:', current_depth, 'Value:', node['value'])
    for child in node.get('children', []):
        traverse_tree(child, max_depth, current_depth + 1)

