import time
from redis import Redis

class RateLimitExceededException(Exception):
    pass

class RateLimiter:
    def __init__(self, requests_per_unit=10, unit=1, redis_host='localhost', port=6379):
        self.redis = Redis(host=redis_host, port=port)
        self.requests_per_unit = int(requests_per_unit)
        self.unit = int(unit)

    def is_rate_limited(self, user):
        key = f'{user}:{int(time.time()) // self.unit}'
        request_number = self.redis.incr(key)
        self.redis.expire(key, self.unit)

        if request_number > self.requests_per_unit:
            raise RateLimitExceededException()

    def rate_limit(self, user):
        try:
            self.is_rate_limited(user)
        except RateLimitExceededException:
            return False  # Request exceeded limit

        return True  # OK to go ahead with request

import graphql
from graphql import GraphQLSchema, GraphQLObjectType, GraphQLString, GraphQLInt, GraphQLBoolean
from ast import literal_eval
from typing import List

class Person(GraphQLObjectType):
    """Represents a person with a name, age, and is_active."""
    name = GraphQLString()
    age = GraphQLInt()
    is_active = GraphQLBoolean()

# Create the GraphQL schema.
def create_schema():
    # Define the types.
    type_defs = [
        graphql.TypeDefinition(
            name="Person",
            fields=[
                graphql.FieldDefinition(
                    name="name",
                    type=GraphQLString,
                    description="The person's name."
                ),
                graphql.FieldDefinition(
                    name="age",
                    type=GraphQLInt,
                    description="The person's age."
                ),
                graphql.FieldDefinition(
                    name="is_active",
                    type=GraphQLBoolean,
                    description="Whether the person is active."
                )
            ],
            resolve=True
        )
    ]

    # Create the query.
    query = """
query {
  allPeople {
    edges {
      node {
        name
        age
        isActive
      }
    }
  }
}
"""

    # Parse the query and execute it on the schema.
    schema = GraphQLSchema(
        query=literal_eval(query),
        types=[
            Person,
            graphql.TypeDefinition(name="Query", fields=[graphql.FieldDefinition(name="allPeople", type=GraphQLObjectType(type_defs[0]))])
        ]
    )

    return schema

schema = create_schema()
print(schema)

