import datetime
import collections

class Event:
    def __init__(self, name, date):
        self.name = name
        self.date = date

class DuplicateHandler:
    def __init__(self):
        self.events = {}

    def handle_event(self, event_name, event_date):
        if event_name in self.events:
            print(f"Duplicate event: {event_name} on {event_date}")
        else:
            self.events[event_name] = set()

        for existing_event in self.events[event_name]:
            if existing_event.date == event_date:
                print(f"Already scheduled for the same date: {event_name}")

    def add_event(self, event_name, event_date):
        if event_name in self.events:
            self.events[event_name].add(event_date)
        else:
            self.events[event_name] = {event_date}

    def delete_event(self, event_name, event_date):
        if event_name in self.events:
            if event_date in self.events[event_name]:
                self.events[event_name].remove(event_date)
                print(f"Event {event_name} on {event_date} has been deleted")
            else:
                print(f"No event scheduled for {event_name} on {event_date}")
        else:
            print(f"No events found for {event_name}")

def main():
    handler = DuplicateHandler()

    while True:
        print("1. Handle an event")
        print("2. Add an event")
        print("3. Delete an event")
        print("4. Exit")

        choice = input("Enter your choice: ")

        if choice == "1":
            event_name = input("Enter the name of the event: ")
            event_date = datetime.datetime.strptime(input("Enter the date of the event (YYYY-MM-DD): "), "%Y-%m-%d")
            handler.handle_event(event_name, event_date)
        elif choice == "2":
            event_name = input("Enter the name of the event: ")
            event_date = datetime.datetime.strptime(input("Enter the date of the event (YYYY-MM-DD): "), "%Y-%m-%d")
            handler.add_event(event_name, event_date)
        elif choice == "3":
            event_name = input("Enter the name of the event: ")
            event_date = datetime.datetime.strptime(input("Enter the date of the event (YYYY-MM-DD): "), "%Y-%m-%d")
            handler.delete_event(event_name, event_date)
        elif choice == "4":
            break
        else:
            print("Invalid choice")

if __name__ == "__main__":
    main()

