class CaesarCipher:
    def __init__(self, shift):
        self.shift = shift

    def encrypt(self, text):
        """Encrypts the given text using the Caesar cipher."""
        encrypted_text = ""
        for char in text:
            if char.isalpha():
                ascii_offset = 65 if char.isupper() else 97
                encrypted_char = chr((ord(char) - ascii_offset + self.shift) % 26 + ascii_offset)
                encrypted_text += encrypted_char
            else:
                encrypted_text += char
        return encrypted_text

    def decrypt(self, text):
        """Decrypts the given text using the Caesar cipher."""
        decrypted_text = ""
        for char in text:
            if char.isalpha():
                ascii_offset = 65 if char.isupper() else 97
                decrypted_char = chr((ord(char) - ascii_offset - self.shift) % 26 + ascii_offset)
                decrypted_text += decrypted_char
            else:
                decrypted_text += char
        return decrypted_text

# Example usage
if __name__ == "__main__":
    shift = 3  # Caesar cipher shift
    cipher = CaesarCipher(shift)

    # Generate encrypted text
    original_text = "Hello, World!"
    encrypted_text = cipher.encrypt(original_text)
    print(f"Encrypted Text: {encrypted_text}")

    # Decrypt the encrypted text
    decrypted_text = cipher.decrypt(encrypted_text)
    print(f"Decrypted Text: {decrypted_text}")

import json
import os

class ConfigManager:
    def __init__(self, config_file_path):
        self.config_file_path = config_file_path
        self.load_config()

    def load_config(self):
        if not os.path.exists(self.config_file_path):
            raise FileNotFoundError(f"No configuration file found at {self.config_file_path}")

        with open(self.config_file_path, 'r') as file:
            self.config_data = json.load(file)

    def save_config(self):
        with open(self.config_file_path, 'w') as file:
            json.dump(self.config_data, file, indent=4)

    def get_config_value(self, key):
        if key in self.config_data:
            return self.config_data[key]
        else:
            raise KeyError(f"No configuration value found for {key}")

# Example usage
