            print(f"An error occurred: {e}")

import sqlite3  # For SQLite databases
# import psycopg2  # For PostgreSQL databases
from typing import List

class DatabaseConnection:
    def __init__(self, db_name: str, user: str, password: str, host: str = None, port: int = None):
        self.db_name = db_name
        self.user = user
        self.password = password
        self.host = host
        self.port = port

    def connect(self) -> sqlite3.Connection:
        if self.host and self.port:
            # For PostgreSQL databases
            return sqlite3.connect(f"postgresql://{self.user}:{self.password}@{self.host}:{self.port}/{self.db_name}")
        else:
            # For SQLite databases
            return sqlite3.connect(self.db_name)

    def insert_records(self, table_name: str, data: List[dict]):
        conn = self.connect()
        try:
            cur = conn.cursor()
            columns = ', '.join(data[0].keys())
            placeholders = ', '.join(['?'] * len(data[0]))
            query = f"INSERT INTO {table_name} ({columns}) VALUES ({placeholders})"
            cur.executemany(query, data)
            conn.commit()
        except sqlite3.Error as e:
            print(f"An error occurred: {e}")
        finally:
            if conn:
                conn.close()

# Example usage
if __name__ == "__main__":
    db_name = "example.db"
    user = "user"
    password = "password"
    table_name = "users"

    data = [
        {"id": 1, "name": "John Doe", "email": "john@example.com"},
        {"id": 2, "name": "Jane Doe", "email": "jane@example.com"}
    ]

    db_connection = DatabaseConnection(db_name, user, password)
    db_connection.insert_records(table_name, data)

