import logging
import urllib

def log_failed_query(query_params, database_url, indent_level=4):
    logger = logging.getLogger(__name__)
    logger.setLevel(logging.ERROR)

    try:
        connection = urllib.request.urlopen(database_url)
        # Assuming query_params is a dictionary with 'query' and 'params'
        params = urllib.parse.urlencode(query_params['params'], doseq=True)
        query_url = f"{database_url}?{params}"

        result = urllib.request.urlopen(query_url)
        return result.read()
    except Exception as e:
        error_message = (
            f"Failed to execute query {query_params['query']}\n"
            f"Params: {urllib.parse.unquote_plus(query_params['params'])}\n"
            f"Stack trace:\n{'-' * 30}"
        )
        logger.log(
            logging.ERROR,
            {
                'indent': '    ' * indent_level,
                'error': error_message
            }
        )
        raise e

