import time

# Dictionary to store user id as key and a list with last request timestamp and count of requests
requests_dict = {}

MAX_REQUESTS = 10  # Max number of requests within the time period
TIME_PERIOD = 60   # Time period in seconds

def rate_limit(user_id):
    now = time.time()
    if user_id not in requests_dict:
        # User's first request
        requests_dict[user_id] = [now, 1]
        return True
    else:
        last_request_time, request_count = requests_dict[user_id]
        if now - last_request_time < TIME_PERIOD:
            # If the time period has not passed since the last request
            if request_count >= MAX_REQUESTS:
                # Exceeded maximum number of requests within the time period
                return False
            else:
                # Increase the count of requests and update the timestamp
                requests_dict[user_id] = [now, request_count + 1]
        else:
            # Time period has passed since the last request. Reset the count
            requests_dict[user_id] = [now, 1]
    return True

