from flask import Flask, jsonify, request  # We use Flask for setting up simple server
app = Flask(__name__)

@app.route('/pay', methods=['POST'])
def pay():
    data = request.get_json()  # Assume that we get card info and amount from user in JSON format

    payment_gateway_response = requests.post('https://your-third-party-payment-gateway/api', json=data)

    if payment_gateway_response.status_code != 200:  # If status code is not 200, then it means some kind of error occurred
        return jsonify({'message': 'Payment failed.'}), payment_gateway_response.status_code  # We return the HTTP status code as it indicates the type of error

    response = payment_gateway_response.json()

    if not response['success']:  
        return jsonify({'message': 'Payment failed.'}), 402  # 402 is a standard HTTP status code for 'payment required' which we use here as an example

    return jsonify({'message': 'Payment successful.'})

