from flask import Flask, request, jsonify, make_response
from flask_sqlalchemy import SQLAlchemy
import json
from datetime import datetime
import jwt

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///users.db'
app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False
db = SQLAlchemy(app)

class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(100), nullable=False)
    email = db.Column(db.String(120), unique=True, nullable=False)
    created_at = db.Column(db.DateTime, default=datetime.utcnow)

@app.route('/users', methods=['GET'])
def get_users():
    users = User.query.all()
    return jsonify([u.__dict__ for u in users])

@app.route('/users', methods=['POST'])
def create_user():
    if not request.json:
        return jsonify({'error': 'Request body is required'}), 400

    user = User(
        name=request.json['name'],
        email=request.json['email']
    )

    db.session.add(user)
    try:
        db.session.commit()
        response = make_response(jsonify(user.__dict__)), 201
        response.set_cookie('access_token', jwt.encode({'user_id': user.id}, app.config['SECRET_KEY']))
        return response
    except Exception as e:
        db.session.rollback()
        return jsonify({'error': str(e)}), 500

@app.route('/users/<id>', methods=['GET'])
def get_user(id):
    user = User.query.get(id)
    if not user:
        return jsonify({'error': 'User not found'}), 404

    response = make_response(jsonify(user.__dict__)), 200
    response.set_cookie('access_token', jwt.encode({'user_id': user.id}, app.config['SECRET_KEY']))
    return response

@app.route('/users/<id>', methods=['PUT'])
def update_user(id):
    user = User.query.get(id)
    if not user:
        return jsonify({'error': 'User not found'}), 404

    if not request.json:
        return jsonify({'error': 'Request body is required'}), 400

    setattr(user, 'name', request.json['name'])
    setattr(user, 'email', request.json['email'])

    db.session.commit()
    response = make_response(jsonify(user.__dict__)), 200
    response.set_cookie('access_token', jwt.encode({'user_id': user.id}, app.config['SECRET_KEY']))
    return response

@app.route('/users/<id>', methods=['DELETE'])
def delete_user(id):
    user = User.query.get(id)
    if not user:
        return jsonify({'error': 'User not found'}), 404

    db.session.delete(user)
    db.session.commit()

    return jsonify({'message': 'User deleted successfully'})

@app.route('/auth', methods=['POST'])
def get_auth_token():
    user = User.query.first()
    if not user:
        return jsonify({'error': 'Unauthorized'}), 401

    payload = {
        'user_id': user.id,
        'exp': datetime.utcnow() + datetime.timedelta(seconds=3600)
    }

    token = jwt.encode(payload, app.config['SECRET_KEY'])
    access_token = token.decode(jwt.JWT_FILE_KEY)

    return jsonify({'access_token': access_token})

if __name__ == '__main__':
    with app.app_context():
        db.create_all()
        # You might want to add some dummy data here for testing

