import datetime

def is_valid_cvv(cvv):
    # Check that the CVV is a string
    if not isinstance(cvv, str):
        return False

    # Check that the CVV is a valid length (3 or 4 digits)
    if len(cvv) != 3 and len(cvv) != 4:
        return False

    # Check that the CVV only contains numbers
    for char in cvv:
        if not char.isdigit():
            return False

    return True

def is_valid_expiration(month, year):
    # Check that the month and year are both strings
    if not isinstance(month, str) or not isinstance(year, str):
        return False

    # Check that the month is a valid value (1-12)
    try:
        month_int = int(month)
    except ValueError:
        return False
    if month_int < 1 or month_int > 12:
        return False

    # Check that the year is a valid value (4 digits)
    try:
        year_int = int(year)
    except ValueError:
        return False
    if len(str(year_int)) != 4:
        return False

    # Check that the current date is before the expiration date
    today = datetime.date.today()
    expiration_date = datetime.date(year_int, month_int, 1)
    if today >= expiration_date:
        return False

    return True

import os
from tempfile import mkdtemp
import webbrowser

def save_files_to_temp_directory(files):
    temp_dir = mkdtemp()

    for file in files:
        if not any(file.endswith(f) for f in ['*.txt', '*.pdf', '*.png', '*.jpg']):
            continue  # Skip non-image files

        new_file_path = os.path.join(temp_dir, file)

        try:
            with open(new_file_path, 'wb') as f:
                pass
        except Exception as e:
            print(f"Error saving file {file}: {e}")
            return

    print(f"All files saved successfully to {temp_dir}")

    # Clean up the temporary directory
    try:
        for filename in os.listdir(temp_dir):
            file_path = os.path.join(temp_dir, filename)
            if os.path.isfile(file_path):
                os.remove(file_path)
        print("Temporary directory cleaned up.")
    except FileNotFoundError:
        print("Temporary directory cleanup skipped.")

def main():
