# Define the maximum allowed query depth
MAX_QUERY_DEPTH = 2

def limit_query_depth(max_depth):
    def decorator(func):
        def wrapper(*args, **kwargs):
            args = list(args)
            kwargs = dict(kwargs)

            # Limit the number of arguments in the function call
            while len(args) + len(kwargs) > max_depth:
                raise ValueError("Too many query parameters")

            return func(*args, **kwargs)
        return wrapper
    return decorator

@app.route('/', methods=['GET'])
@limit_query_depth(MAX_QUERY_DEPTH)
def index():
    return "Welcome to the restricted server"

