# Create a dictionary to store tenant-specific data
tenant_data = {}

# Function to create a new tenant
def create_tenant(tenant_id):
    tenant_data[tenant_id] = {}

# Function to add data to a tenant's data store
def add_data(tenant_id, data):
    if tenant_id not in tenant_data:
        create_tenant(tenant_id)
    tenant_data[tenant_id][uuid.uuid4()] = data

# Function to retrieve data from a tenant's data store
def get_data(tenant_id, data_id):
    if tenant_id not in tenant_data:
        return None
    return tenant_data[tenant_id].get(data_id)

# Function to delete data from a tenant's data store
def delete_data(tenant_id, data_id):
    if tenant_id in tenant_data and data_id in tenant_data[tenant_id]:
        del tenant_data[tenant_id][data_id]

