import threading
from queue import Queue
import time

class DynamicQueue:
    def __init__(self):
        self.queue = Queue()
        self.lock = threading.Lock()

    def put(self, item):
        with self.lock:
            self.queue.put(item)

    def get(self):
        with self.lock:
            return self.queue.get()

    def size(self):
        with self.lock:
            return self.queue.qsize()

    def is_empty(self):
        with self.lock:
            return self.queue.empty()

import logging
from collections import deque

# Set up logging
logging.basicConfig(filename='queue_activities.log', level=logging.INFO, format='%(asctime)s %(message)s')
logger = logging.getLogger()

class Queue:
    def __init__(self):
        self.buffer = deque()

    def enqueue(self, item):
        logger.info('Enqueued item: {}'.format(item))
        self.buffer.appendleft(item)

    def dequeue(self):
        if len(self.buffer) > 0:
            item = self.buffer.pop()
            logger.info('Dequeued item: {}'.format(item))
            return item
        else:
            logger.warning('Attempted to dequeue from an empty queue')
            return None

    def size(self):
        logger.info('Checked size of the queue: {} items'.format(len(self.buffer)))
        return len(self.buffer)

def func():
    # Simulate a function that might throw an error after several attempts
    return 42  # Successful return

max_retries = 3  # Number of retries allowed before raising exception
current_backoff = 1  # Initial backoff time in seconds

for attempt in range(max_retries):
    try:
        result = func()
        print(f"Success after {attempt + 1} attempts.")
        return result
    except Exception as e:
        if attempt == max_retries - 1:
            raise
        else:
            current_backoff *= 2
            print(f"Failed after {attempt + 1} attempts. Retrying with backoff of {current_backoff} seconds.")

from urllib.parse import urlparse

def validate_url(url):
    parsed = urlparse(url)

    # Check if scheme is http or https
    if not (parsed.scheme in ('http', 'https')):
        return False

    # Check if hostname is present and valid
    if not parsed.hostname:
        return False

    # Check port: if present, it should be numeric
    if parsed.port != '':
        try:
            int(parsed.port)
        except ValueError:
            return False

    # Check fragment identifier
    if parsed.fragment:
        if not (fragment := parsed.fragment.split('#')[1].strip()):
            return False  # fragment is empty after #

    return True

