import time
import requests
from typing import Callable

def request_with_throttle(func: Callable, *args, **kwargs):
    def wrapper(*args, **kwargs):
        time.sleep(5)  # Here we are throttling at a rate of one request every 5 seconds
        return func(*args, **kwargs)
    return wrapper

@request_with_throttle
