class Node:
    """Represents a single node in the linked list."""
    def __init__(self, id):
        self.id = id
        self.next = None


class LinkedList:
    """Manages the nodes in the linked list."""
    def __init__(self):
        self.head = None

    def append(self, id):
        """Adds a new node to the end of the linked list."""
        if not self.head:
            self.head = Node(id)
        else:
            current = self.head
            while current.next:
                current = current.next
            current.next = Node(id)

    def free_node(self, node_id):
        """Frees the memory associated with a node in the linked list."""
        current = self.head
        if current and current.id == node_id:
            self.head = current.next
            return True
        while current and current.next:
            if current.next.id == node_id:
                current.next = current.next.next
                return True
            current = current.next
        return False

    def check_dangling_pointer(self, node_id):
        """Checks if a pointer is dangling."""
        # If the node does not exist in the list, it's a dangling pointer.
        return not self.find_node(node_id)

    def find_node(self, id):
        """Finds a node with the specified id in the linked list."""
        current = self.head
        while current:
            if current.id == id:
                return True
            current = current.next
        return False


# Example usage:
if __name__ == "__main__":
    linked_list = LinkedList()
    linked_list.append(1)
    linked_list.append(2)
    linked_list.append(3)

