import stripe

def process_payment(token, amount):
    try:
        # Assumes you've set your API keys when initialized the `stripe` module
        charge = stripe.Charge.create(
            amount=amount,   # in cents
            currency="usd",
            source=token,  # obtained with Stripe.js
            description="Example charge")

        return {"success": True, "message": "Payment processed successfully"}
    except stripe.error.CardError as e:
        body = e.json_body
        err  = body['error']
        return {
                "success": False, 
                "message": f"There was an issue processing your card. Message: {err['message']}"}
    except stripe.error.RateLimitError as e:
        # Too many requests made to the API too quickly
        return {"success": False, "message": "Too many requests made, please try again later."}
    except stripe.error.InvalidRequestError as e:
        # Invalid parameters were supplied to Stripe's API
        return {"success": False, "message": f"Invalid parameters error: {e}"}
    except stripe.error.AuthenticationError as e:
        # Authentication with Stripe's API failed (maybe you changed API keys recently)
        return {"success": False, "message": f"Authentication with Stripe's API failed: {e}"}
    except stripe.error.APIConnectionError as e:
        # Network communication with Stripe failed
        return {"success": False, "message": f"Network communication error with Stripe's API: {e}"}
    except stripe.error.StripeError as e:
        # Display a very generic error to the user, and maybe send yourself an email
        return {"success": False, "message": "Something went wrong. You were not charged. Please try again."}
    except Exception as e:
        # Something else happened, completely unrelated to Stripe
        return {"success": False, "message": f"A serious error occurred. Please notify us. Error message: {e}"}

