import datetime
import pickle
from typing import Dict, List, Optional, Tuple

class RateLimiter:
    def __init__(self):
        self.search_counts: Dict[str, int] = {}
        self.last Activity: Dict[str, datetime.datetime] = {}
        self BlacklistedIPs: Set[str] = set()
        self window_size: int = 5
        self.max_consecutive: int = 3
        self.max_frequency: int = 2

    def add_query(self, query: str) -> bool:
        """Track a search query and prevent abuse."""
        timestamp = datetime.datetime.now().replace(microsecond=0)

        # Convert the query to an immutable type for uniqueness across different references (like cookies)
        normalized_query = tuple(sorted(query.split()))
        key = normalized_query

        if key in self.search_counts:
            current_count = self.search_counts[key]
            if timestamp - self.last_activity.get(key, datetime.datetime.now()) < \
                datetime.timedelta(seconds=self.window_size):
                return False

            # Block the IP address
            ip_address = '127.0.0.1'  # Replace with actual client IP
            if ip_address in self.BlacklistedIPs:
                return True

            # Ensure we don't exceed max_consecutive consecutive attempts within window_size seconds
            if current_count >= self.max_consecutive - 1:
                self_BlacklistIP(ip_address)
                return True

            # Update the last activity time for this query
            self.last_activity[key] = timestamp

            # Increment count and update
            self.search_counts[key] += 1
        else:
            # Initialize search counts if not present
            self.search_counts[key] = 1

        self.last_activity[key] = timestamp
        return True

    def _BlacklistIP(self, ip_address: str):
        """Blacklist client IP address."""
        self.BlacklistedIPs.add(ip_address)
        return True

    def setPeriodicity(self, seconds: int) -> None:
        """Set periodicity for saving state to disk."""
        if not hasattr(self, 'state_save_interval'):
            self.state_save_interval = seconds

        while True:
            try:
                # Save every "seconds" period
                with open('limiter_state', 'wb') as f:
                    pickle.dump(self, f)

                print(f"Saved limiter state at {datetime.datetime.now()}")

            except KeyboardInterrupt:
                break
            except Exception as e:
                print(f"Error saving limiter state: {e}")

    def exitSurvey(self) -> None:
        """Prepare to exit survey by saving the current state."""
        try:
            while True:
                if input("Type 'exit' to save and exit, or any other key to continue saving...") == 'exit':
                    print("Saving limiter state...")
                    with open('limiter_state', 'wb') as f:
                        pickle.dump(self, f)
                    print("Limiter saved. Exiting in 5 seconds...")
                    break
                time.sleep(1)
        except KeyboardInterrupt:
            pass

    @property
    def isBlacklistedIP(self, ip_address: str) -> bool:
        """Check if client IP has been blacklisted."""
        return ip_address in self.BlacklistedIPs

    @staticmethod
    def log_request(query: str, timestamp: datetime.datetime,
                    status: str, ip_address: Optional[str] = None) -> None:
        """Log each request with details."""
        logger = {
            'query': query,
            'timestamp': timestamp.isoformat(),
            'status': status,
            'ip_address': ip_address
        }

        try:
            with open('request_log.log', 'a') as f:
                # Use json.dumps for serialization since pickling might not work
                pickle.dump(logger, f)

        except Exception as e:
            print(f"Error logging request: {e}")

# Example usage:

# Initialize limiter
limiter = RateLimiter()

# Set periodicity to save state every 30 minutes (1800 seconds)
limiter.setPeriodicity(1800)

try:
    while True:
        # Replace '127.0.0.1' with actual client IP and query string
        ip_address = '127.0.0.1'
        query = input(f"Enter search term {ip_address} (or Ctrl+D to exit): ")

        if not query.strip():
            break

        # Log request before limiting
        limiter.log_request(query, datetime.datetime.now(), status='continue')

        # Check rate limit and allow/disallow access
        if limiter.add_query(query):
            print(f"Access denied due to {limiter.get_reason()}")

except KeyboardInterrupt:
    limiter.exitSurvey()

