import hashlib
import sys

def main():
    if len(sys.argv) < 2:
        print("Usage: python3 checksum.py <filename> [expected_checksum]")
        return

    filename = sys.argv[1]
    expected_checksum = sys.stdin.readline().strip().lower()

    try:
        with open(filename, 'rb') as f:
            # Compute the SHA-256 checksum
            sha = hashlib.sha256()
            data = f.read(sha.digest_size)
            while data:
                sha.update(data)
                data = f.read(sha.digest_size)
            computed_checksum = sha.hexdigest().lower()

            if computed_checksum == expected_checksum:
                print(f"Checksum for {filename} matches: {computed_checksum}")
            else:
                print(f"Checksum failed for {filename}. Expected: {expected_checksum}, Actual: {computed_checksum}")
    except FileNotFoundError as e:
        print(f"File not found: {e}")
    except Exception as e:
        print(f"An error occurred while verifying the checksum: {str(e)}")

if __name__ == "__main__":
    main()

