import psutil
import time
from datetime import timedelta

class CronJobMonitor:
    def __init__(self):
        self.processes = {}

    def get_process_ids(self):
        """Get a list of process IDs running cron jobs"""
        return [p.info['pid'] for p in psutil.process_iter(['pid', 'name']) if p.info['name'] == 'crond']

    def monitor_job_duration(self, job_id, expected_start_time):
        """Monitor the duration of a specific cron job"""
        start_time = expected_start_time
        while True:
            current_time = time.time()
            process_info = self.get_process_info(job_id)
            if not process_info:
                break

            # Calculate the elapsed time
            elapsed_time = (current_time - start_time) / 60  # Convert seconds to minutes
            duration = timedelta(minutes=elapsed_time)

            print(f"Elapsed Time: {duration}")
            if elapsed_time > 30 * 60:  # Check if job is running for more than 30 minutes
                print("Cron Job not found or timed out after 30 minutes")
                break

            time.sleep(1)  # Wait for 1 second before checking again


    def get_process_info(self, process_id):
        """Get information about a specific process by its ID"""
        try:
            return psutil.Process(process_id).as_dict(['pid', 'name'])
        except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
            return None

def main():
    monitor = CronJobMonitor()
    job_id = 1
    expected_start_time = time.time() - 30 * 60  # Assume cron job started 30 minutes ago
    while True:
        monitor.monitor_job_duration(job_id, expected_start_time)
        time.sleep(60)  # Check every minute

if __name__ == "__main__":
    main()

import os
from collections import defaultdict

class TenantAPIKeysHandler:
    def __init__(self):
        self._keys = defaultdict(str)

    def add_key(self, tenant_id, key):
        # Check if the key is already in use by another tenant
        for t_id, k in self._keys.items():
            if k == key:
                raise ValueError("This API key is already in use.")

        # Store the new key
        self._keys[tenant_id] = key

    def get_key(self, tenant_id):
        return self._keys.get(tenant_id)

