import hashlib

class BlockChain(object):
    def __init__(self):
        self.blocks = []  # Our blockchain, which will be made up of blocks

    def add_block(self, data):
        """
        Adds a new block to the blockchain
        :param data: The data that you want to store in the block
        """
        if len(self.blocks) == 0:  # If this is our first block
            prev_hash = 0  # There's no previous hash, so we set it to zero
        else:
            prev_hash = self.blocks[-1].hash  # We want the last block in the chain as our 'previous'

        new_block = Block(data=data, prev_hash=prev_hash)
        new_block.mine()  # Mine the new block to add some validation

        self.blocks.append(new_block)

    def validate_chain(self):
        """
        Validates that all blocks in our chain have not been tampered with
        """
        for i, b in enumerate(self.blocks[1:], 1):
            if b.prev_hash != self.blocks[i-1].hash:  # If this block's previous hash doesn't match the last block's hash, it was altered
                return False
        return True  

class Block(object):
    def __init__(self, data, prev_hash=0):
        self.data = data  # The transaction data
        self.prev_hash = prev_hash  # A reference to the previous block's hash
        self.nonce = 0  

    @property
    def hash(self):
        """
        Returns the hash of this block
        """
        return self._calculate_hash()

    def _calculate_hash(self):
        # The first two bytes of a SHA256 hash are enough for our purposes
        return int.from_bytes(hashlib.sha256((str(self.data) + str(self.prev_hash) + str(self.nonce)).encode()).digest()[:2], 'big')

    def mine(self):
        """
        Mines this block by finding a nonce value that would make the hash of the block start with two zeroes
        """
        while self._calculate_hash() > 0xFF:  # While our first two bytes are greater than 255 (hex for FF), which is what we want
            self.nonce += 1  # Increase the nonce and try again

