class Inventory:
    def __init__(self):
        self.items = {}

    # Method to add an item to the inventory
    def add_item(self, id, name, quantity):
        if id not in self.items:
            self.items[id] = {'name': name, 'quantity': quantity}
        else:
            print("Error: Item with ID {} already exists.".format(id))

    # Method to remove an item from the inventory
    def remove_item(self, id):
        if id in self.items:
            del self.items[id]
        else:
            print("Error: Item with ID {} does not exist.".format(id))

    # Method to update the quantity of an item in the inventory
    def update_item(self, id, quantity):
        if id in self.items:
            self.items[id]['quantity'] = quantity
        else:
            print("Error: Item with ID {} does not exist.".format(id))

    # Method to check the inventory for an item
    def check_item(self, id):
        if id in self.items:
            return "Item: {}, Quantity: {}".format(self.items[id]['name'], self.items[id]['quantity'])
        else:
            return "Error: Item with ID {} does not exist.".format(id)

def caesar_decrypt(text, shift):
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    shifted_alphabet = alphabet[shift:] + alphabet[:shift]
    table = str.maketrans(shifted_alphabet, alphabet)
    return text.translate(table)

import json

def deserialize_json(data):
    if isinstance(data, dict):
        return data
    try:
        return json.loads(data)
    except json.JSONDecodeError:
        raise ValueError("Invalid JSON string")
    except Exception as e:
        raise ValueError(f"Unexpected error during deserialization: {e}")

