        # Dictionary to store usernames as keys, values are lists containing two items.
        # The first item is a boolean that indicates if the account is locked (True) or not (False).
        # The second item is an integer that keeps track of failed login attempts.
        self.accounts = {}

    def add_user(self, username):
        if username in self.accounts:
            print("User already exists.")
        else:
            self.accounts[username] = [False, 0]

    def login_attempt(self, username, password):
        if username not in self.accounts:
            print("Username does not exist.")
            return False

        account_status = self.accounts[username]

        if account_status[0]:
            print("Account is locked.")
            return False

        # For the sake of this example, assume password is always "password"
        if password == "password":
            account_status[1] = 0 # Reset failed attempts upon successful login.
            return True
        else:
            account_status[1] += 1

            if account_status[1] >= 3:
                account_status[0] = True # Lock the account after three failed attempts.
                print("Account is now locked.")

            print(f"Failed login attempt {account_status[1]} of 3.")
            return False

