import sys
import inspect

def log_error(exception):
    exc_type, exc_value, tb = sys.exc_info()

    # Print a message indicating an error occurred before detailed information
    print(f"Error: {exc_type.__name__}: {exc_value}")

    # Extract stack trace frames starting from the first frame (most recent)
    for frame in inspect.stacktrace()[:]:
        if frame is inspect.currentframe(0):
            continue  # Skip the current frame that runs this function

        # Get more detailed information about each frame
        code = getattr(frame, 'code', None) 
        func_name = getattr(frame, '__func__', None)
        line_num = getattr(frame, 'lineno', None)

        # Print relevant details for each frame in the stack trace
        if code:
            print(f"Code object {hex(id(code))}: Line {line_num} - {func_name}")
        elif func_name:
            print(f"Function '{func_name}' at line {line_num}")
        else:
            print("Other error information")

if __name__ == "__main__":
    try:
        # This will raise an error, triggering the log_error function
        a = 10
        b = a + [5]
        print("This is a test of logging errors with stack traces")
        log_error(RuntimeError("An example error occurred"))

    except Exception as e:
        print(f"\nUnhandled exception: {e}")

from flask import Flask, request, abort
import hmac
import hashlib

app = Flask(__name__)
SECRET_KEY = "your-secret-key"  # Replace with your actual secret key

def verify_signature(payload, sig_header):
    signature = 'sha1=' + hmac.new(SECRET_KEY.encode('utf-8'), payload, hashlib.sha1).hexdigest()
    return hmac.compare_digest(sig_header, signature)

@app.route('/webhook', methods=['POST'])
def webhook():
    sig_header = request.headers.get('X-Hub-Signature')
    if not verify_signature(request.data, sig_header):
        abort(403)  # Forbidden

    # Process the request here...
    return 'Success', 200

