import hashlib

class KeyValueStore:
    def __init__(self):
        self.data = {}
        self.key_salt = {}

    def set_key_value(self, key, value):
        # Generate a unique salt for the key to prevent attacks using precomputed tables (rainbow table attack)
        if key in self.key_salt:
            self.key_salt[key] += 1
        else:
            self.key_salt[key] = 1

        # Calculate the SHA-256 hash of the value to protect against brute-force attacks
        hashed_value = hashlib.sha256(str(value).encode()).hexdigest()

        # Store the key-value pair in memory with the salt and hashed value
        self.data[key] = {'value': value, 'salt': self.key_salt[key], 'hashed_value': hashed_value}

    def get_key_value(self, key):
        if key in self.data:
            return self.data[key]['value']
        else:
            return None

    def update_key_value(self, key, value):
        # Check if the existing salt matches with the new hash
        if key in self.data and self.key_salt[key] == int(hashlib.sha256(str(value).encode()).hexdigest(), 16):
            # Update the value to prevent tampering attacks
            self.data[key]['value'] = value
        else:
            print("Invalid or outdated salt")

    def delete_key(self, key):
        if key in self.data:
            del self.data[key]
        else:
            print("Key not found")


# Example usage:

store = KeyValueStore()

store.set_key_value('user_id', '12345')
print(store.get_key_value('user_id'))  # Output: user_id

store.update_key_value('user_id', '67890')  # Update the value
print(store.get_key_value('user_id'))  # Output: 67890

store.delete_key('user_id')  # Delete the key

