from graphql import parse, GraphQLSchema, build_ast_schema, validate
from graphql.error import GraphQLError

def validate_graphql_query(query: str):
    try:
        ast = parse(query)
        validation_errors = validate(build_ast_schema(ast), ast)
        if validation_errors:
            for error in validation_errors:
                print("Validation Error:", error.message)
            return False
        else:
            print("Query is valid.")
            return True
    except GraphQLError as e:
        print("Syntax Error:", e.message)
        return False

