class AccessControl:
    def __init__(self):
        self.access_levels = {
            'admin': {'users': ['create', 'read', 'update', 'delete'],
                       'files': ['create', 'read', 'update', 'delete']},
            'user':  {'users': ['read'],
                       'files': ['read', 'update']}
        }

    def can_access(self, level, resource, permission):
        return (level in self.access_levels and
                resource in self.access_levels[level] and
                permission in self.access_levels[level][resource])

