    try:
        # Insert a new record into the projects table
        sql = ''' INSERT INTO projects(id, name, begin_date)
                  VALUES(?,?,?) '''
        cur = conn.cursor()
        cur.execute(sql, project)
        return cur.lastrowid
    except Error as e:
        print(e)

