import time
from datetime import timedelta
from typing import Dict, Any
import logging

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - [%(levelname)s] - %(message)s',
    handlers=[
        logging.FileHandler('ip_ban.log'),
        logging.StreamHandler()
    ]
)
logger = logging.getLogger(__name__)

class IPBannedHandler:
    def __init__(self, banned_ips: Dict[IPv4Address, int], ban_duration: timedelta):
        self.banned_ips = banned_ips.copy()  # To prevent modification error
        self.ban_duration = ban_duration
        self.last_activity = {}

    async def handle_request(self, ip_address: IPv4Address) -> None:
        current_time = time.time()

        try:
            request_timestamp = int(current_time)

            # Assign a random port to avoid multi IP issues for same user-agent/browser
            random_port = str(int(time.time()) % 256)
            assigned_ip = IPv4Address(f"{ip_address}.{random_port}")

            if assigned_ip in self.last_activity:
                last_time = self.last_activity[assigned_ip]
                delta = current_time - last_time

                if delta > self.ban_duration.total_seconds():
                    # Remove IP from banned list
                    del self.banned_ips[assigned_ip]
                    logger.info(f"Unbanned: {str(assigned_ip)} after {delta} seconds")
                else:
                    # Update timestamp to keep it in the banned state
                    self.last_activity[assigned_ip] = current_time
                    logger.debug(f"Banned IP {assigned_ip} until {current_time + self.ban_duration}")
            else:
                # Create a new entry for the IP if not banned yet or just banned
                self.last_activity[assigned_ip] = request_timestamp
                logger.debug(f"Allowed: {str(assigned_ip)} at {request_timestamp}")

        except Exception as e:
            logging.error(f"Error handling IP ban: {e}")
            raise

    # To be used with concurrent requests, to prevent too many IPs from timing out
    @classmethod
    def concurrent_request_handler(cls):
        pass  # This can be implemented using LRU cache or similar for rate limiting

def ip_ban_manager(banned_ips: Dict[IPv4Address, int], ban_duration: timedelta) -> IPBannedHandler:
    return IPBannedHandler(banned_ips, ban_duration)

