from functools import wraps

def requires_privilege(privilege):
    """
    Decorator for validating user privileges.

    Args:
        privilege: The required privilege for the decorated function.

    Returns:
        A decorated function that validates user privileges.
    """

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            # Get the current user's privilege.
            user_privilege = get_current_user_privilege()

            # Check if the user has the required privilege.
            if user_privilege < privilege:
                raise PermissionError("Insufficient privileges.")

            # Call the decorated function.
            return func(*args, **kwargs)

        return wrapper

    return decorator

# Example usage:
@requires_privilege(1)
def admin_only_function():
    print("This function is only accessible to admins.")

@requires_privilege(0)
def user_function():
    print("This function is accessible to all users.")

