        data = response.json()
        return data
    except requests.exceptions.RequestException as e:
        print(f"Error fetching IoT status: {e}")
        return []

# Function to send device status update
def send_update(data):
    if not data or 'devices' not in data:
        return

    devices = []
    for dev in data['devices']:
        status = dev.get('status', {}).get('state', 'Not Monitoried')
        temp = str(round(dev.get('temperature'), 1))
        uptime = str(round(dev.get('uptime_seconds') / (3600 * 24), 1)) + 'h'

        devices.append({
            'name': dev['name'],
            'status': status,
            'temp': temp,
            'uptime': uptime
        })

    # Update HTML template content with device data
    output = app.send_string(HTML_TEMPLATE, render_kwargs={'devices': devices})

# Main monitoring loop
def monitor():
    print("Starting IoT monitor...")
    last_update_time = 0

    try:
        while True:
            now = time.time()
            if now - last_update_time > 60:  # Update every minute
                device_data = get_iot_status()
                send_update(device_data)
                last_update_time = time.time()

    except KeyboardInterrupt:
        print("\nShutting down IoT monitor...")

    finally:
        print("Stopping HTTP server...")

# Run the Flask server
@app.route('/')
def home():
    return HTML_TEMPLATE

if __name__ == "__main__":
    # Start Flask server
    app.run(host='0.0.0.0', port=5000)

    # Start monitoring thread
    monitor_thread = threading.Thread(target=monitor)
    monitor_thread.daemon = True  # Stops when main program exits

    print("Monitoring IoT devices... Starting from http://localhost:5000")
    input("Press Enter to start monitoring...\n")
    monitor_thread.start()

import pickle

def serialize_object(obj, filename):
    try:
        with open(filename, 'wb') as file:
            # Use protocol version 4 which is the latest and has better security features.
            pickle.dump(obj, file, protocol=pickle.HIGHEST_PROTOCOL)
        print("Object successfully serialized.")
    except Exception as e:
        print("An error occurred while serializing object.", str(e))

