import requests
from unittest import mock
from retry import waits
import logging

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(name)s - %(levelname)s - %(message)s',
    filename='api_fallback.log'
)
logger = logging.getLogger(__name__)

def fallback_mechanism():
    """
    Attempt to get a resource from multiple API endpoints with fallback mechanisms.
    """
    base_api_url = "https://api.example.com"
    api_alternates = [
        "https://api.example alternate.com",
        "https://api.example.com/v2"
    ]
    api2 = "https://api2.example.com"
    api3 = "https://api3.example.com"

    # Define retry logic
    @mock.patch('socket.timeout')
    def _retry(request, max_retries=1):
        for i in range(max_retries):
            request.setTimeout(i * 10)  # Exponential backoff

    try:
        # First attempt with base API URL
        response = requests.get(base_api_url, timeout=30)
        if response.status_code == 200:
            logger.info(f"Successfully retrieved from {base_api_url}")
            return response.json()
        else:
            logger.warning(f"API request to {base_api_url} failed with status code: {response.status_code}")

    except Exception as e:
        logger.error(f"Failed to get from {base_api_url}: {str(e)}")
        if api_alternates:
            # Fallback to alternate URLs
            for alt_url in api_alternates:
                try:
                    alt_response = requests.get(alt_url, timeout=30)
                    if alt_response.status_code == 200:
                        logger.info(f"Successfully retrieved from {alt_url}")
                        return alt_response.json()
                    else:
                        logger.warning(f"API request to {alt_url} failed with status code: {alt_response.status_code}")
                except Exception as e_alt:
                    logger.error(f"Fallback to {alt_url} also failed: {str(e_alt)}")

            # If all alternates fail, retry the initial API call
            if api2 and api3:
                try:
                    response = requests.get(api2, timeout=60)
                    if response.status_code == 200:
                        logger.info(f"Successfully retrieved from {api2}")
                        return response.json()
                    elif requests.get(api3, timeout=60).status_code == 200:
                        logger.info(f"Successfully retrieved from {api3}")
                        return requests.get(api3).json()
                except Exception as e_fallback:
                    logger.error(f"Fallback to {api2} and {api3} also failed: {str(e_fallback)}")

        # If initial attempt fails completely
        try:
            final_response = requests.get(api2, timeout=60)
            if final_response.status_code == 200:
                return final_response.json()
            elif requests.get(api3, timeout=60).status_code == 200:
                return requests.get(api3).json()

        except Exception as e_final:
            logger.error(f"Final fallback to {api2} and {api3} failed: {str(e_final)}")
            raise

    except waits.Wait as wait:
        # Handle retry logic
        logger.info("Retrying after waiting a random interval between {} and {} seconds".format(wait))
        return fallback_mechanism()

if __name__ == "__main__":
    try:
        result = fallback_mechanism()
        print("API response:", result)
    except Exception as e:
        print(f"Error executing fallback mechanism: {str(e)}")

import time

class IPBanHandler:
    def __init__(self):
        self.banned_ips = set()

    def add_ip(self, ip_address):
        """Add an IP address to the banned list."""
        if ip_address not in self.banned_ips:
            self.banned_ips.add(ip_address)
            print(f"IP {ip_address} added to banned list.")

    def remove_ip(self, ip_address):
        """Remove an IP address from the banned list."""
        if ip_address in self.banned_ips:
            self.banned_ips.remove(ip_address)
            print(f"IP {ip_address} removed from banned list.")
        else:
            print(f"IP {ip_address} not found in banned list.")

    def check_ip(self, ip_address):
        """Check if an IP address is banned."""
        return ip_address in self.banned_ips

def main():
    ban_handler = IPBanHandler()

    while True:
        print("\n1. Add IP to banned list")
        print("2. Remove IP from banned list")
        print("3. Check IP against banned list")
        print("4. Exit")

        choice = input("Choose an option: ")

        if choice == "1":
            ip_address = input("Enter IP address to add: ")
            ban_handler.add_ip(ip_address)
        elif choice == "2":
            ip_address = input("Enter IP address to remove: ")
            ban_handler.remove_ip(ip_address)
        elif choice == "3":
            ip_address = input("Enter IP address to check: ")
            if ban_handler.check_ip(ip_address):
                print(f"IP {ip_address} is banned.")
            else:
                print(f"IP {ip_address} is not banned.")
        elif choice == "4":
            break
        else:
            print("Invalid option. Please choose again.")

