import secrets
from cryptography.fernet import Fernet

def generate_credentials():
    # Generate 32-byte key using Fernet encryption
    key = Fernet.generate_key()
    return key

def encrypt_credentials(plaintext, key):
    """Encrypt plaintext with a given key"""
    cipher_suite = Fernet(key)
    cipher_text = cipher_suite.encrypt(plaintext.encode('utf-8'))
    return cipher_text.decode('utf-8')

def decrypt_credentials(cipher_text, key):
    """Decrypt cipher text with a given key"""
    cipher_suite = Fernet(key)
    plain_text = cipher_suite.decrypt(cipher_text.encode('utf-8'))
    return plain_text

def main():
    # Generate credentials
    key = generate_credentials()

    # Define pipeline configuration as plaintext
    pipeline_config = """
        {
            "pipeline": {
                "stage1": {
                    "input": "data",
                    "output": "intermediate"
                },
                "stage2": {
                    "input": "intermediate",
                    "output": "final"
                }
            }
        }
    """

    # Encrypt pipeline configuration
    encrypted_config = encrypt_credentials(pipeline_config, key)

    # Print credentials (key and encrypted config)
    print("Generated Key:", key.decode('utf-8'))
    print("Encrypted Pipeline Config:", encrypted_config)

    # Use credentials to decrypt pipeline config in production
    decrypted_config = decrypt_credentials(encrypted_config, key)
    print("Decrypted Pipeline Config:")
    print(decrypted_config)

if __name__ == "__main__":
    main()

