import email
from imaplib import IMAP4_SSL

def process_mailbox(M):
    # Select mailbox and search for UNSEEN emails from the last 24 hours
    rv, data = M.search(None, '(UNSEEN SENTSINCE "{}")'.format(email.utils.formatdate(time.time()-86400)))
    if rv != 'OK':
        print('No new emails')
        return

    for num in data[0].split():
        rv, data = M.fetch(num, '(RFC822)')
        if rv != 'OK':
            print('ERROR getting message'), num
            continue

        msg = email.message_from_bytes(data[0][1])
        handle_bounced_email(msg)

def handle_bounced_email(msg):
    # Check for various types of bounce messages
    if 'Status: 5' in msg['Subject'] or 'Undelivered Mail Returned to Sender' in msg.get_payload():
        with open('hard_bounces.log', 'a') as f:
            f.write(msg.as_string())
    elif 'Status: 4' in msg['Subject'] or 'delivery has been delayed' in msg.get_payload():
        with open('soft_bounces.log', 'a') as f:
            f.write(msg.as_string())
    else:
        with open('unknown_bounces.log', 'a') as f:
            f.write(msg.as_string())

def main():
    # Connect to the mail server and login
    M = IMAP4_SSL('imap.gmail.com')
    M.login('your-username@gmail.com', 'your-password')

    # Select the INBOX and process all mailboxes
    rv, mailboxes = M.list()
    if rv == 'OK':
        for mailbox in mailboxes:
            rv, mailbox_name = M.select(mailbox.decode('utf-8').split()[2])
            if rv == 'OK':
                process_mailbox(M)

    # Logout and close the connection
    M.logout()

if __name__ == "__main__":
    main()

