import importlib
import os

class CMS:
    def __init__(self):
        self.plugins = {}

    def register_plugin(self, name, plugin_class):
        """
        Register a new plugin with the given name.

        :param name: The name of the plugin.
        :param plugin_class: The class of the plugin.
        """
        if name in self.plugins:
            raise ValueError(f"Plugin '{name}' already registered")
        self.plugins[name] = plugin_class

    def load_plugin(self, name):
        """
        Load a registered plugin.

        :param name: The name of the plugin to load.
        :return: The loaded plugin instance.
        """
        if name not in self.plugins:
            raise ValueError(f"Plugin '{name}' not found")
        return self.plugins[name]()

    def run(self, command):
        """
        Run a plugin with the given command.

        :param command: The command to pass to the plugin.
        """
        plugins = [self.load_plugin(plugin_name) for plugin_name in self.plugins]
        for plugin in plugins:
            try:
                result = plugin.run(command)
                print(result)
            except Exception as e:
                print(f"Error running plugin: {e}")

