import numpy as np
from scipy import stats

class StatisticalAnalysis:
    def __init__(self, data):
        self.data = sorted(data)  # sorting is required for median calculation

    def mean(self):
        return np.mean(self.data)

    def median(self):
        return np.median(self.data)

    def mode(self):
        mode = stats.mode(self.data)  # returns the smallest in case of tie
        return mode[0][0]  

    def variance(self):
        return np.var(self.data)

    def std_deviation(self):
        return np.std(self.data)

