import asyncio
from queue import Queue
import threading

class EventQueueManager:
    def __init__(self, num_workers=10):
        self.num_workers = num_workers
        self.event_queue = asyncio.Queue()

        # Create worker threads
        self.workers = []
        for _ in range(num_workers):
            loop = asyncio.new_event_loop()
            asyncio.set_event_loop(loop)
            thread = threading.Thread(target=self._run_worker, args=(loop,))
            thread.start()
            self.workers.append(thread)

    def _run_worker(self, loop):
        loop.run_coroutine_threadsafe(
            self.handle_eventcoroutine,
            loop
        )

    async def handle_eventcoroutine(self, event_type=None, data=None):
        if event_type is None and data is None:
            return

        await asyncio.sleep(0.1)  # Sleep to avoid handling events too quickly

        while not self.event_queue.empty():
            event_type, data = self.event_queue.get()

            for handler in self.handlers[event_type]:
                try:
                    asyncio.run_coroutine_threadsafe(
                        handler(event_data=data),
                        asyncio.new_event_loop()
                    )
                except Exception as e:
                    print(f"Error executing handler: {e}")

    def register_listener(self, event_type, callback):
        self.handlers = {
            type: {} for type in (int, str, bytes)
        }

        # Add the callback to the appropriate event type
        if isinstance(event_type, type):
            self.handlers[event_type][callback] = callback
        else:
            print(f"Invalid event type {event_type}")

    def add_handler(self, event_type, callback, *args, **kwargs):
        for key in (event_type,) + args:
            if key not in self.handlers or not isinstance(self.handlers[key], dict):
                print(f"Creating new handler mapping for {key}")
                self.handlers[key] = {}
            self.handlers[key][callback] = callback

    def handle_event(self, event_type, data):
        # Add the event to the queue
        await asyncio.sleep(0.1)

        if not isinstance(data, (bytes, str)):
            return

        await self.event_queue.put((event_type, data))

        # Register the handler
        try:
            for handler in self.handlers.get(event_type, {}):
                asyncio.run_coroutine_threadsafe(
                    handler(event_data=data),
                    asyncio.new_event_loop()
                )
        except Exception as e:
            print(f"Error handling event: {e}")

