                name_exists = True
            except Error as e:
                print(f"Error: {e}")
                delete = False

        if criteria[0] == 'EMAIL':
            try:
                c.execute(f"SELECT email FROM users WHERE email = '{name}';", (name,))
                result = c.fetchone()
                email_exists = True
            except Error as e:
                print(f"Error: {e}")
                delete = False

        if not delete:
            return

        # Now, check all conditions and perform deletion(s)
        to_delete = []

        id_to_del = None
        name_to_del = None
        email_to_del = None

        try:
            if criteria[0] == 'ID':
                c.execute(f"SELECT id FROM users WHERE id = '{id}'")
                (id_to_del,) = c.fetchone()
                to_delete.append(('id', id_to_del))

            # Check name or email based on the first criterion
            if len(criteria) >= 2:
                if criteria[1] == 'text' and criteria[0] in ['NAME', 'EMAIL']:
                    search_term = next_part = criteria[1].strip().lower()
                    try:
                        if criteria[0] == 'NAME':
                            c.execute(f"SELECT name FROM users WHERE name LIKE '%{search_term}%'")
                        else:  # EMAIL
                            c.execute(f"SELECT email FROM users WHERE email = '{search_term}'")
                        results = c.fetchall()
                        for row in results:
                            if criteria[0] == 'NAME':
                                name_to_del = row[0]
                            else:
                                email_to_del = row[0]

                    except Error as e:
                        print(f"Error: {e}")
                        delete = False

        except Exception as e:
            print(f"Error in database query: {e}")

        if id_to_del is not None and name_to_del is not None:
            to_delete.append(('name', name_to_del))
            to_delete.append(('email', email_to_del))

        # Now, delete the records
        for (col, val) in to_delete:
            try:
                c.execute(f"DELETE FROM users WHERE {col} = '{val}'")
                conn.commit()
                print(f"Deleted {len(to_delete) - len(to_delete)} record(s).")
            except Error as e:
                print(f"Error: {e}")

    finally:
        # Close the database connection
        if 'conn' in locals() and conn is not None:
            conn.close()

