import os
from datetime import datetime

def validate_user_config():
    policies = {
        'tenant1': {
            'users': [
                {'name': 'validuser1', 'email': 'user1@example.com', 'password': 'securepassword123!'},
                {'name': 'invaliduser', 'email': 'user@unrealisticdomain.com', 'password': 'shortpass'}
            ],
            'roles': ['admin']
        },
        'tenant2': {
            'users': [
                {'name': 'testuser', 'email': 'user@test.com', 'password': '!@#$testpass123'}
            ],
            'roles': []
        }
    }

    policy_file = os.path.join(os.path.dirname(__file__), 'config/policies.yaml')
    if not os.path.exists(policy_file):
        return False

    with open(policy_file, 'r') as file:
        try:
            policies.update(eval(file.read()))  # Load policies from the file
        except:
            print("Error reading policy configuration")
            return False

    main_config = {
        'valid': True,
        'errors': []
    }

    def get_tenant_policy(ten_id):
        for key, value in policies.items():
            if key.startswith(f"{ten_id}config_") or ten_id == key:
                return value
        print(f"Policy not found for tenant '{ten_id}'")
        return None

    def check_user_config(ten_id, user_data):
        nonlocal main_config
        errors = []
        name_min, name_max = 3, 20
        email_valid = True
        password_min_length = 8
        active_required = True

        # Check User Name
        if not isinstance(user_data['name'], str) or len(user_data['name']) < name_min:
            errors.append(f"User {user_data.get('username', 'user')} has invalid username length.")
        elif len(user_data['name']) > name_max:
            errors.append(f"User {user_data.get('username', 'user')} has an excessively long username.")

        # Check Email
        if not isinstance(user_data['email'], str):
            errors.append(f"Invalid email format for user {user_data.get('username', 'user')}.")
        else:
            parts = user_data['email'].split('@')
            if len(parts) != 2 or not parts[0].isalpha() or not parts[1].isdigit():
                errors.append(f"Invalid email format for user {user_data.get('username', 'user')}.")

        # Check Password
        password_str = user_data.get('password', '')
        if len(password_str) < password_min_length:
            errors.append(f"Password must be at least {password_min_length} characters long.")
        elif not (password_str.isalpha() or password_str.isdigit() or password_str.replace("-", "", 1).isalnum()):
            errors.append(f"Password contains invalid characters.")

        # Check Active Status
        if not isinstance(user_data['active'], bool):
            errors.append(f"Active status must be a boolean for user {user_data.get('username', 'user')}.")

        # Log validation results
        main_config['errors'].append({"tenant": ten_id, "user": user_data.get("username", None), "errors": errors})

    def check_role_config(ten_id, role):
        nonlocal policies
        if ten_id not in policies:
            print(f"Policy does not exist for tenant '{ten_id}'")
            return False

        role_policy = next((r for r in policies[ten_id]['roles'] if r['name'] == role), None)
        if not role_policy:
            print(f"Role '{role}' is invalid or not allowed in tenant '{ten_id}'")
            return False
        else:
            return True  # Role is valid

    def validate_tenants():
        global main_config
        for key, value in policies.items():
            if key.startswith("config_"):
                continue
            tenant_name = key.split('.')[0]
            tenant_config = value.copy()
            try:
                # Validate users within the tenant
                users_in_policy = list(tenant_config['users'])

                for user_data in users_in_policy:
                    check_user_config(tenant_name, user_data)

                    if len(main_config['errors']) >= 10:  # Prevent excessive logging
                        break

                # Validate roles within the tenant
                success = True
                try:
                    for role_name in tenant_config.get('roles', []):
                        if not check_role_config(tenant_name, role_name):
                            success = False
                            break
                except Exception as e:
                    print(f"Error validating role '{role_name}' in tenant '{tenant_name}': {str(e)}")

                # Log success message per tenant
                main_config['errors'].append({"tenant": tenant_name, "status": f"Tenants and roles within '{tenant_name}' validated successfully."})

            except Exception as e:
                print(f"Error validating tenant '{tenant_name}': {str(e)}")

    validate_tenants()
    if main_config['valid']:
        print("All valid configurations.")
    else:
        for error in main_config['errors']:
            print(f"{error['user']} validation errors: {', '.join(error['errors'])}")

import hmac, hashlib, base64
from flask import request

def verify_signature(secret, signature, data):
    secret = bytes(secret, 'UTF-8')
    mac = hmac.new(secret, msg=data, digestmod=hashlib.sha256)
    calculated_signature = base64.b64encode(mac.digest())
    return hmac.compare_digest(calculated_signature, signature)

@app.route('/webhook', methods=['POST'])
def webhook():
    data = request.get_data()
    sig_header = request.headers.get('X-Hub-Signature')
    if not sig_header:
        return 'No Signature Provided', 403
    sha_name, signature = sig_header.split('=')
    if sha_name != 'sha256':
        return 'Invalid hash algorithm', 400
    secret = 'your_secret' # replace with your actual secret key
    if not verify_signature(secret, bytes(signature, 'UTF-8'), data):
        return 'Invalid Signature', 403
    return 'Valid Signature', 200

