import datetime

class Charge:
    def __init__(self, amount, timestamp):
        self.amount = amount
        self.timestamp = timestamp

class Customer:
    def __init__(self, customer_id, name):
        self.customer_id = customer_id
        self.name = name
        self.charges = []

    def add_charge(self, charge):
        if not any(charge.timestamp >= datetime.datetime.now() - datetime.timedelta(days=30) for charge in self.charges):
            self.charges.append(charge)

class ChargingSystem:
    def __init__(self):
        self.customers = {}

    def add_customer(self, customer_id, name):
        self.customers[customer_id] = Customer(customer_id, name)

    def make_charge(self, customer_id, amount):
        if customer_id in self.customers:
            charge = Charge(amount, datetime.datetime.now())
            self.customers[customer_id].add_charge(charge)
            return charge
        else:
            raise ValueError("Customer not found")

system = ChargingSystem()
system.add_customer(1, "John Doe")
charge = system.make_charge(1, 100)

if charge.timestamp - datetime.datetime.now() < datetime.timedelta(days=30):
    print(f"Double charging detected for customer {system.customers[1].name}.")
else:
    print(f"Charge made successfully to customer {system.customers[1].name} for ${charge.amount}")

def parse_cron job(line):
    parts = line.split()
    if not parts:
        return ''

    # Extract each component (min, hour, day_of_week, etc.)
    min_part = parts[0]
    hour_part = parts[1] if len(parts) > 1 else '0'
    day_part = parts[2] if len(parts) > 2 else '*'  # default to all days

    # Function to convert part (e.g., */5, 3-5, etc.) into a set of integers
    def get_values(part):
        values = []
        if part == '*':
            return list(range(60))
        elif '-' in part:
            start, end = map(int, part.split('-'))
            values = list(range(start, end + 1))
        else:  # single value
            values.append(int(part) % 60)
        return values

    minutes = get_values(min_part)

    hours = []
    if hour_part == '*':
        hours = list(range(24))
    elif '-' in hour_part:
        start, end = map(int, hour_part.split('-'))
        # Ensure that the range wraps around midnight if necessary
        h1 = max(start % 24, (start - 24) % 24)
        h2 = min(end % 24, (end - 24) % 24)
        if h1 > h2:
            hours += list(range(h1, 24)) + list(range(0, h2 + 1))
        else:
            hours += list(range(h1, h2 + 1))
    else:  # single value
        hours.append(int(hour_part) % 24)

    day_values = []
    if day_part == '*':
        day_values = list(range(7))  # all days of the week

    # Format each part back to its cron representation, handling wrapping cases for day and hour
    min_str = ''
    if len(min_part) > 1:
        # Check if the original had something other than * (since */* wraps)
        if any(c in '/' for c in min_part):
            pass
        else:
            start = int(min_part[0]) % 60
            if len(min_part) > 2 and min_part[2] == '*':
                end = 59  # since it was expanded to */* earlier
            else:
                try:
                    end = int(min_part[-1]) % 60
                except IndexError:
                    end = 59
            if start <= end:
                min_str = f"{start}"
            else:
                min_str = f"{start} - {end}"

    hour_str = ''
    if len(hour_part) > 1:
        pass
    else:
        h = int(hour_part)
        if day_part == '*':
            if h % 24 != 0 and '/' not in min_part:
                # Wrap around midnight
                if h < 0 or h >= 24:
                    h -= 24
                elif '/' in hour_part:
                    pass

    return f"{' '.join([min_str, hour_str, day_values[0]]).replace(' ', '')}"

import ijson

def parse_large_file(filename):
    file = open(filename, 'r') # Open the file in read mode

    # Create an instance of the items iterator 
    parser = ijson.parse(file) 

    for prefix, type, value in parser:
        if prefix == '' and type == 'start_map':
            data_object = {}
        elif type == 'map_key':
            last_key = value
        elif type in ['string', 'number']:
            data_object[last_key] = value
        elif type == 'end_map':
            yield data_object  # Yield the data object for processing

# Use it like this:
for obj in parse_large_file('filename.json'):
    print(obj)

class QueryDepthError(Exception):
    """Raised when the query depth exceeds the allowed limit"""
    pass

def restricted_query(data, depth=0, max_depth=10):
    if depth > max_depth:
        raise QueryDepthError("The maximum query depth has been reached.")

    # If data is not a dictionary or list (base case), just return it.
    if not isinstance(data, (dict, list)):
        return data

    # If data is a dictionary, recursively call restricted_query on each value.
    elif isinstance(data, dict):
        for key in data:
            data[key] = restricted_query(data[key], depth + 1, max_depth)
        return data

    # If data is a list, recursively call restricted_query on each element.
    else:
        return [restricted_query(item, depth + 1, max_depth) for item in data]

