import queue

def safe_enqueue(q, item):
    """Safely enqueues an item to the given queue. If the queue is full, it waits until space becomes available."""
    try:
        q.put(item, block=False)  # Try adding without blocking
    except queue.Full:
        print("Queue is full. Waiting for space...")
        q.put(item, block=True)  # Block and wait until there's room in the queue

# Create a new FIFO Queue with maximum size of 10 items
q = queue.Queue(maxsize=10)

for i in range(20):  # Try to add 20 items (more than the queue can hold)
    safe_enqueue(q, f"Item {i}")

import os
import sys

def ensure_append_path(filename):
    """Ensure the file exists and its path is valid."""
    base_dir = os.path.dirname(os.path.abspath(filename))
    if not os.path.exists(base_dir):
        try:
            os.makedirs(base_dir)
        except OSError as e:
            print(f"Error creating directory: {e}")
            sys.exit(1)

def append_to_file(filename, data_to_append):
    """Append data to a file safely."""
    ensure_append_path(filename)

    try:
        with open(filename, 'a', encoding='utf-8') as f:
            f.write(data_to_append)
        print(f"Successfully added {len(data_to_append)} bytes to {filename}")
    except Exception as e:
        print(f"Error appending to file: {e}")

def main():
    """Main function to handle command line arguments."""
    filename = sys.argv[1]
    data = sys.stdin.read().strip()

    append_to_file(filename, data)

if __name__ == "__main__":
    main()

