import re

def validate_address(address):
    """Validate a US shipping address."""
    # A very basic regex for US addresses. This will match most common formats, but it is not perfect.
    pattern = r'^(\d+) [A-Za-z ]+(?:St|St\.)?[ ,]?(?:Apt|Suite)?(?: \#\d+)?$'

    if re.match(pattern, address):
        return True
    else:
        return False

