import json
import time
from datetime import datetime
import os
import psutil
from http.server import HTTPServer, BaseHTTPRequestHandler

# Function to get CPU percentage
def get_cpu_usage():
    return psutil.cpu_percent()

# Function to get Memory usage
def get_memory_usage():
    return process_meminfo()

def process_meminfo():
    py.process = psutil.Process()
    mem = py.process.memory_info()
    return (mem.rss + mem.vms) / 1024 ** 2

# Function to get disk I/O
def get_disk_io():
    free_space = os.statvfs(os.getcwd())
    free_space_percent = (free_space freel percent) / free_space.f_bswap_percent)
    return {'read': free_space.fread_percent, 'write': free_space.fswidth_percent}

def get_network_traffic():
    try:
        server = HTTPServer(('localhost', 80), SimpleHTTPRequestHandler)
        with server.socket:
            while True:
                try:
                    request = server._handler._server._sinput()
                    if not request: break
                    response = request.split()
                    return {'status': 'connected', 'bytes_received': len(request)}
    except Exception as e:
        print(f"Error reading network traffic: {e}")
        return {'status': 'error'}

def main():
    metric_names = {
        get_cpu_usage(): 'CPU Usage',
        get_memory_usage(): 'Memory Usage',
        get_disk_io(): 'Disk I/O',
        get_network_traffic(): 'Network Traffic'
    }

    current_dir = os.path.join(os.path.expanduser('~'), 'server_metrics')
    if not os.path.exists(current_dir):
        os.makedirs(current_dir)

    try:
        while True:
            metrics = {}

            # Get and store metrics
            for name, func in metric_names.items():
                value = func()
                current_time = datetime.now().timestamp()

                # Store metrics in JSON format
                metrics[str(current_time)] = {
                    'timestamp': current_time,
                    **value
                }

                print(f"[{current_time:.1f}] {func.__name__}: {value}%")

            # Save to file
            with open(os.path.join(current_dir, f'server_metrics_{int(current_time)}.json'), 'w') as file:
                json.dump(metrics, file, indent=2)

            time.sleep(60)
    except Exception as e:
        print(f"An error occurred: {e}")

if __name__ == "__main__":
    main()

