    print("Block is valid!")
else:
    print("Block is not valid.")

import datetime
from enum import Enum

class Status(Enum):
    """Status of the content"""
    DRAFT = "Draft"
    APPROVED = "Approved"
    REJECTED = "Rejected"

class Content:
    """Represents a piece of content"""
    def __init__(self, id, title, content):
        self.id = id
        self.title = title
        self.content = content
        self.status = Status.DRAFT

class WorkflowManager:
    """Manages the content approval workflow"""
    def __init__(self):
        self.content_queue = []

    def add_content(self, content):
        """Adds a new piece of content to the queue"""
        self.content_queue.append(content)

    def approve_content(self, content_id):
        """Approves a piece of content in the queue"""
        for item in self.content_queue:
            if item.id == content_id:
                item.status = Status.APPROVED
                print(f"Content {item.title} approved.")
                return

    def reject_content(self, content_id):
        """Rejects a piece of content in the queue"""
        for item in self.content_queue:
            if item.id == content_id:
                item.status = Status.REJECTED
                print(f"Content {item.title} rejected.")
                return

    def view_status(self, content_id):
        """Displays the status of a piece of content"""
        for item in self.content_queue:
            if item.id == content_id:
                print(f"Content ID: {item.id}")
                print(f"Title: {item.title}")
                print(f"Content: {item.content}")
                print(f"Status: {item.status.name}")
                return

class ContentManager:
    """Manages the content queue"""
    def __init__(self):
        self.workflow_manager = WorkflowManager()

    def create_content(self, id, title, content):
        """Creates a new piece of content and adds it to the queue"""
        content_obj = Content(id, title, content)
        self.workflow_manager.add_content(content_obj)

    def display_queue(self):
        """Displays all pieces of content in the queue"""
        for item in self.workflow_manager.content_queue:
            print(f"Content ID: {item.id}")
            print(f"Title: {item.title}")
            print(f"Status: {item.status.name}")

def main():
    manager = ContentManager()

    while True:
        print("1. Create Content")
        print("2. Display Queue")
        print("3. Approve Content")
        print("4. Reject Content")
        print("5. View Content Status")
        print("6. Exit")

        choice = input("Enter your choice: ")

        if choice == "1":
            id = int(input("Enter content ID: "))
            title = input("Enter content title: ")
            content = input("Enter content: ")
            manager.create_content(id, title, content)
        elif choice == "2":
            manager.display_queue()
        elif choice == "3":
            id = int(input("Enter content ID to approve: "))
            manager.workflow_manager.approve_content(id)
        elif choice == "4":
            id = int(input("Enter content ID to reject: "))
            manager.workflow_manager.reject_content(id)
        elif choice == "5":
            id = int(input("Enter content ID to view status: "))
            manager.workflow_manager.view_status(id)
        elif choice == "6":
            break
        else:
            print("Invalid choice. Please try again.")

if __name__ == "__main__":
    main()

def enqueue(prio):
    global inserted_at
    queue.append((prio, inserted_at))
    inserted_at += 1

def dequeue():
    min_prio = float('inf')
    best_index = -1
    for i in range(len(queue)):
        if queue[i][0] < min_prio:
            min_prio = queue[i][0]
            best_index = i
        elif queue[i][0] == min_prio and (i < best_index or queue[i][1] < queue[best_index][1]):
            # Update when same priority but earlier insertion or new position after check due to possible update of best_index
            best_index = i
    if best_index != -1:
        del queue[best_index]
        return min_prio, queue[best_index][1]
    else:
        return None  # Queue is empty

