import pickle

class Person:
    def __init__(self, name, age):
        self.name = name
        self.age = age

def deserialize_binary_data(binary_data):
    """
    Deserializes binary data into a dictionary of objects.

    Args:
        binary_data (bytes): Binary data to be deserialized.

    Returns:
        dict: Dictionary of deserialized objects.
    """
    try:
        # Load the binary data into a Python object
        data = pickle.loads(binary_data)

        # Convert the loaded data into a dictionary of objects
        person_dict = {}
        for key, value in data.items():
            if isinstance(value, Person):
                person_dict[key] = {
                    'name': value.name,
                    'age': value.age
                }
            else:
                person_dict[key] = value

        return person_dict

    except pickle.UnpicklingError as e:
        print(f"Error deserializing binary data: {e}")
        return None

# Example usage
if __name__ == "__main__":
    # Create a Person object
    person = Person("John Doe", 30)

    # Serialize the Person object into binary format
    binary_data = pickle.dumps(person)

    # Deserialize the binary data into a dictionary of objects
    deserialized_data = deserialize_binary_data(binary_data)

    if deserialized_data:
        print(deserialized_data)

import os
import json
import time
from uuid import uuid4
import requests
from cryptography.fernet import Fernet  # For AES encryption


def generate_session_id():
    """Generate a unique session ID."""
    return str(uuid4()).replace('-', '')


def get_authorization_url(client_secret):
    """Generate the authorization URL for OAuth flow."""
    response = requests.get(
        'https://localhost:8080/oauth2(authorize)',
        params={'client_secret': client_secret}
    )
    return response.url


def obtain_access_token(client_id, authorization_code):
    """Obtain the access token using OAuth flow."""
    headers = {
        'Authorization': f'Basic {client_id}:{authORIZATION_CODE}'
    }
    response = requests.post(
        'https://localhost:8080/oauth2/token',
        auth=(None, os.getenv('CLIENT_SECRET')),
        data={'grant_type': 'authorization_code', 'code': authorization_code}
    )
    if response.status_code == 200:
        return response.json()['access_token']
    else:
        raise ValueError(f'Failed to obtain access token: {response.status_code}')


def save_tokens(token, refresh_token):
    """Save tokens securely using database encryption."""
    # Using Fernet for AES-128 encryption
    f = Fernet(os.getenv('SECRET_KEY'))
    encrypted_data = {
        'access_token': f.encrypt(bytes(token, encoding='utf-8')),
        'refresh_token': f.encrypt(bytes(refresh_token, encoding='utf-8'))
    }
    return encrypted_data


def load_tokens():
    """Load tokens from storage."""
    f = Fernet(os.getenv('SECRET_KEY'))
    try:
        with open('tokens.json', 'r') as file:
            data = json.load(file)
            access_token = f.decrypt(bytes(data['access_token'], encoding='utf-8')).decode('utf-8')
            refresh_token = f.decrypt(bytes(data['refresh_token'], encoding='utf-8')).decode('utf-8')
        return access_token, refresh_token
    except FileNotFoundError:
        with open('tokens.json', 'w') as file:
            file.write('[]')
        return None, None


def refresh_tokens(access_token):
    """Refresh the access token if it's about to expire."""
    response = requests.post(
        'https://localhost:8080/oauth2/token',
        auth=(None, os.getenv('CLIENT_SECRET')),
        data={'grant_type': 'refresh_token', 'refresh_token': access_token}
    )
    new_access_token = None
    if response.status_code == 200:
        response_data = response.json()
        if 'access_token' in response_data:
            new_access_token = response_data['access_token']
    return new_access_token


def handle_oauth_flow(client_id, client_secret):
    """Handle the entire OAuth flow securely."""
    session_id = generate_session_id()

    try:
        authorization_url = get_authorization_url(client_secret)
        print(f"Please visit this URL to authorize: {authorization_url}")

        auth_response = requests.post(authorization_url, data={'grant_type': 'client_credentials'})
        if not auth_response.ok:
            raise ValueError('Failed to obtain authorization code')

        access_token = obtain_access_token(client_id, auth_response.json()['code'])
        print(f'Successfully obtained access token: {access_token}')

        save_tokens(access_token, None)
        print('Tokens saved successfully.')

    except Exception as e:
        print(f"Error during OAuth flow: {str(e)}")
        time.sleep(60 * 5)  # Rate limiting window
        handle_oauth_flow(client_id, client_secret)


def main():
    """Main function to initiate OAuth authentication."""
    client_id = os.getenv('CLIENT_ID')
    client_secret = os.getenv('CLIENT_SECRET')

    try:
        handle_oauth_flow(client_id, client_secret)

    except KeyboardInterrupt:
        print("\nShutting down...")


if __name__ == "__main__":
    main()

