    # Add new content to the approval workflow
    def add_content(self, content_id, content_data, author_id):
        if author_id in self.users:
            self.content.append({"id": content_id, "data": content_data, "author_id": author_id, "status": "Pending Approval"})
            print(f'Content {content_id} added to the approval workflow by user {author_id}.')
        else:
            print('Invalid User ID.')

    # Add new user to the system
    def add_user(self, user_id, role):
        self.users[user_id] = role
        print(f'User {user_id} added with role {role}.')

    # Approve content (only allowed for admins or moderators)
    def approve_content(self, user_id, content_id):
        if self.users[user_id] in ["Admin", "Moderator"]:
            for c in self.content:
                if c['id'] == content_id:
                    c['status'] = 'Approved'
                    print(f'Content {content_id} has been approved by user {user_id}.')
        else:
            print('User does not have the required permission to approve content.')

# Sample usage
