import threading
import multiprocessing

class ResourceLimiter:
    def __init__(self, max_threads=100, max_processes=10):
        self.max_threads = max_threads
        self.max_processes = max_processes
        self.thread_count = 0
        self.process_count = 0

    def acquire_thread(self):
        with threading.RLock():
            if self.thread_count >= self.max_threads:
                raise ValueError("Maximum number of threads reached")
            self.thread_count += 1

    def release_thread(self):
        with threading.RLock():
            self.thread_count -= 1

    def acquire_process(self):
        with multiprocessing.Lock():
            if self.process_count >= self.max_processes:
                raise ValueError("Maximum number of processes reached")
            self.process_count += 1

    def release_process(self):
        with multiprocessing.Lock():
            self.process_count -= 1

