import os
from os import Permission

# Define roles and their respective permissions on directories
roles = {
    'admin': [Permission('r', 0o755), Permission('w', 0o644), Permission('x', 0o555)],
    'contributor': [Permission('r', 0o755), Permission('w', 0o644)],
    'user': [Permission('r', 0o644)]
}

def get_user_role(username):
    """Determine the role of the current user based on their username."""
    return next((role for role in roles if os.getuser() == username), None)

def check_access(role, target_dir):
    """Check if a given role has access to the specified directory."""
    if not role:
        raise AttributeError(f"Permission denied: {role} is not granted.")

    file_perms = Permission(target_dir)
    target_perm = Permission(target_dir)

    # Ensure permissions are compared correctly
    for attr in ('ro', 'wx'):
        current = getattr(file_perms, attr)
        req = getattr(target_perm, attr)
        if (role & 0o1) and not (current & req):
            raise AttributeError(f"Permission denied: Access to {target_dir} denied for role {role}.")

    return True

def main():
    user = input("Enter your username: ")
    role = get_user_role(user)
    target = input("Enter the directory you want access to: ").strip()

    if not check_access(role, target):
        print(f"Access denied. You are not authorized to access {target}.")
    else:
        print(f"Welcome! You have access to {target}.")

if __name__ == "__main__":
    main()

import websockets
import asyncio
from selectors import Selectors
import json
import threading

async def listen_websocket():
    async with websockets.connect('ws://localhost:8080') as websocket:
        try:
            selector = Selectors()
            reader = selector.get selectively bound to the WebSocket socket)

            while True:
                # Read from the selection of sockets
                events = await selector.select(reader, timeout=1.0)

                if not events:
                    continue

                for key, value in events.items():
                    message = await value.read(1024).decode('utf-8')

                    # Parse JSON payload and process it accordingly
                    try:
                        data = json.loads(message)
                        print(f"Received: {data}")
                    except json.JSONDecodeError as e:
                        print(f"Invalid JSON received: {e}")

def parse_websocket_messages():
    asyncio.run(listen_websocket())

