import requests
from time import sleep
from random import randint

def get_headers(url):
    """Attempt to automatically extract authentication headers from cookies."""
    try:
        response = requests.get(url)
        return {k.lower(): v for k, v in response.headers.items()}
    except requests.exceptions.RequestException as e:
        print(f"Could not extract headers. Error: {e}")
        return {
            'X-Forwarded-Passwd': None,
            'X-Forwarded-Disposition': None
        }

def send_request(method, url, data=None):
    """Send a request with headers and automatic retry logic."""
    headers = get_headers(url)
    response = requests.request(
        method=method,
        url=url,
        data=data,
        headers=headers,
        timeout=10  # Timeout in seconds
    )
    return response

def retry_request(request_func, url, data=None, 
                 retries=3, delay=1, max_delay=None):
    """Attempt to make a request with retries and backoff."""
    for attempt in range(retries):
        if max_delay is None:
            current_delay = delay
        else:
            current_delay = min(attempt * delay, max_delay)

        try:
            response = request_func(url, data=data)
            return response
        except requests.exceptions.HTTPError as e:
            print(f"Request failed: {e}")
            if attempt < retries - 1 and current_delay < max_delay:
                sleep(current_delay)
            else:
                raise

    return None

def main():
    headers = get_headers("https://example.com")
    print("Headers:", headers)

    try_response = retry_request(
        send_request,
        "https://api.example.com/resource",
        data={"key": "value"},
        retries=5,
        delay=1,
        max_delay=30
    )

    if try_response:
        print("Request successful. Response:", try_response.text)
    else:
        print("Request failed after all attempts.")

if __name__ == "__main__":
    main()

