import logging
import requests
import json
from typing import Dict

class WebhookLogger:
    def __init__(self, url: str):
        self.url = url
        self.logger = self._setup_logging()

    @staticmethod
    def _setup_logging():
        logger = logging.getLogger('WebhookLogger')
        logger.setLevel(logging.INFO)
        handler = logging.StreamHandler()
        formatter = logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s')
        handler.setFormatter(formatter)
        logger.addHandler(handler)
        return logger

    def log_event(self, event: Dict):
        try:
            headers = {'Content-Type': 'application/json'}
            response = requests.post(self.url, data=json.dumps(event), headers=headers)
            if response.status_code == 200:
                self.logger.info('Event logged successfully')
            else:
                self.logger.error(f'Failed to log event, status code: {response.status_code}')
        except Exception as e:
            self.logger.exception(f'An error occurred while trying to log the event: {e}')

