def compute_failure(pattern):
    n = len(pattern)
    fail = [0] * n
    j = 0
    for i in range(1, n):
        while j > 0 and pattern[i] != pattern[j]:
            j = fail[j - 1]
        if pattern[i] == pattern[j]:
            j += 1
            fail[i] = j
        else:
            fail[i] = 0
    return fail

def kmp_search(pattern, text):
    n = len(pattern)
    m = len(text)
    failure = compute_failure(pattern)

    j = 0  # Index for text
    i = 0  # Index for pattern

    occurrences = []
    while j < m:
        if pattern[i] == text[j]:
            i += 1
            j += 1
        else:
            if i != 0:
                i = failure[i - 1]
            else:
                j += 1

        if i == n:
            # Match found at position j - n in the text (0-based)
            occurrences.append(j - n)
            i = failure[i - 1]  # Move to next possible match

    return occurrences

