import json
from jsonschema import validate
import hashlib
from pycrypto import hash

# Define the schema for the tenant configuration data
tenant_schema = {
    "type": "object",
    "properties": {
        "name": {"type": "string"},
        "email": {"type": "string"},
        "phone": {"type": "string"}
    },
    "required": ["name", "email", "phone"]
}

# Define the hash function for validating the integrity of the configuration data
def validate_hash(data):
    hash_value = hashlib.sha256(json.dumps(data).encode("utf-8")).hexdigest()
    return hash_value == "e7293cce112b4609bef38a93aa8e5629"

# Define a function for validating the tenant configuration data against the schema
def validate_tenant(data):
    try:
        validate(instance=data, schema=tenant_schema)
        hash_value = hashlib.sha256(json.dumps(data).encode("utf-8")).hexdigest()
        if not validate_hash(data):
            raise ValueError("Invalid tenant configuration data")
    except jsonschema.ValidationError as e:
        raise ValueError("Invalid tenant configuration data: {}".format(e))
    return data

