import os
from pypm import PYP
import subprocess

def check_dependencies():
    # Path to requirements.txt file
    requirements_path = "requirements.txt"

    # Fetch all packages and their vulnerabilities
    pm = PYP()
    packages = pm.fetch(requirements_path)

    # Vulnerability scanners setup
    scanners = [
        ("CVEChecker", "http://cve-checker.com/"),
        ("CVEQ", "https://cvequality.org/"),
        ("security southern", "https://southern Penumbra security southern tool")
    ]

    vulnerability_report = []

    for package in packages:
        # Fetch package metadata
        metadata = pm.fetch_meta(package)

        # Check vulnerabilities using scanners
        for scanner_name, scanner_url in scanners:
            try:
                result = subprocess.run(
                    [scanner_url, '--output', 'json'],
                    capture_output=True,
                    text=True
                )
                if result.returncode == 0:
                    scanned = json.loads(result.stdout)
                    if isinstance(scanned.get('CVE_Items'), list):
                        for item in scanned['CVE_Items']:
                            cvd = item.get('CVD')
                            if cvd:
                                vulnerabilities.append({
                                    'Package': package,
                                    'Vulnerable Version': cvd.get('ProductVersion'),
                                    'CVSS Score': cvd.get('Score') or 0,
                                    'Details': item.get('Details', {}).get('Message'),
                                    ' remediation': {
                                        'Recommendations': item.get('Recommendation', {}).get('Avoid', []),
                                        'Fixes': item.get('Fixes', {}).get('Apply', [])
                                    }
                                })
            except Exception as e:
                print(f"Error running {scanner_name}: {e}")

    # Write report
    if vulnerabilities:
        with open(requirements_path.replace('.txt', '_vulnerabilities.txt'), 'w') as f:
            f.write(f"Vulnerabilities found in {os.path.basename(requirements_path)}:\n")
            for v in vulnerabilities:
                f.write(f"{v['Package']} ({v['Vulnerable Version']})\n")
                f.write(f"Score: {'N/A' if not v['CVSS Score'] else v['CVSS Score']}\n")
                f.write(f"Details: {v['Details']}\n\n")
                if v.get(' remediation'):
                    f.write("Recommendation:\n")
                    f.write("- ".join(v[' remediation']['Avoid']) + "\n")
                    f.write("\n")
                    f.write("Fixes:\n")
                    f.write("- ".join(v[' remediation']['Apply']) + "\n")
                else:
                    print(f"No recommendations for {v['Package']} ({v['Vulnerable Version']})")
    else:
        print("No vulnerabilities found in dependencies.")

# Run the checker
check_dependencies()

