import os

def read_secure_file(filename):
    if not os.path.exists(filename):
        print(f"Error: The file '{filename}' does not exist.")
        return None

    try:
        with open(filename, 'r') as file:
            content = file.read()
            print(f"File contents of '{filename}': {content}")
            return content
    except IOError as e:
        print(f"An error occurred while accessing the file: {str(e)}")
        return None
    except UnicodeDecodeError as e:
        print(f"Error decoding file content: {str(e)}")
        return None

