import functools

def memoize(func):
    cache = dict()  # create a local cache for storing results of function calls.

    @functools.wraps(func)  # preserves name, docstring, etc of func
    def wrapper(*args):
        if args in cache:
            print("Using cached result")
            return cache[args]

        res = func(*args)  # calculate the value
        cache[args] = res  # store it in cache
        return res

    wrapper.clear_cache = lambda : cache.clear()  # adds method to clear the cache

    return wrapper

# example usage:
@memoize
def fib(n):
    if n < 2:
         return n
    return fib(n-2) + fib(n-1)

def check_null_or_empty(data):
    if data is None:
        return True
    elif isinstance(data, (str, bytes)):
        return len(data) == 0
    elif isinstance(data, (list, tuple, set)):
        return len(data) == 0
    elif isinstance(data, dict):
        return len(data) == 0
    elif isinstance(data, bool):
        return data is False
    else:
        # For other types like integers, floats, etc., only consider exactly False as boolean?
        if isinstance(data, bool):
            return data is False
        else:
            # Non-container and not a boolean. Only consider it as empty if it's explicitly False.
            # However, for non-boolean values (e.g., int, float), we don't treat them as 'empty'.
            # But since they are not containers or exactly False, return False unless they evaluate to False somehow.
            # However, the function should generally treat only None and empty structures as null/empty.
            # So for non-container types, just return False except when data is boolean and False.
            return False

