import socket

def bind_socket(allowed_ips, protocol):
    if not allowed_ips:
        print("No IPs provided")
        return None

    # Determine the socket type based on the protocol
    if protocol.lower() == 'ipv4':
        s = socket.socket(socket.AF_INET)
        ip_type = lambda x: socket.inet_aton(str(x))
    else:  # protocol is ipv6
        s = socket.socket(socket.AF_INET6)
        ip_type = str

    for ip in allowed_ips:
        try:
            if protocol.lower() == 'ipv4':
                ip_obj = ip_type(ip)
                s.bind(ip_obj)
            else:
                s.bind(ip)
            break  # Bind to the first valid IP
        except socket.error as e:
            print(f"Skipping {ip}: {e}")

    return s

# Example usage:
allowed_ips = ["192.168.1.1", "fe80::1"]
protocol = "ipv4"
result = bind_socket(allowed_ips, protocol)
if result:
    print("Socket bound to:", result.getsockname()[0])

