import os
import hashlib
from flask import Flask, request, jsonify
from werkzeug.utils import secure_filename

class FileUploader:
    def __init__(self):
        self.storage_path = '/uploads'
        os.makedirs(self.storage_path, exist_ok=True)

    def validate_file_extension(self, allowed_extensions):
        file_extension = request.files['file'].filename.split('.')[-1]
        if file_extension not in allowed_extensions:
            return False
        return True

    def hash_file(self, filename):
        # Generate a SHA-256 hash of the uploaded file
        with open(os.path.join(self.storage_path, filename), 'rb') as f:
            file_hash = hashlib.sha256(f.read()).hexdigest()
        return file_hash

    def upload_file(self, file, filename=None):
        if not self.validate_file_extension(allowed_extensions=['jpg', 'jpeg', 'png', 'gif']):
            return jsonify({'error': 'Invalid file extension'}), 400

        # Hash the uploaded file
        file_hash = self.hash_file(filename or file.filename)

        # Securely store the file on the server
        secure_filename_str = secure_filename(file.filename)
        with open(os.path.join(self.storage_path, secure_filename_str), 'wb') as f:
            f.write(file.read())

        return jsonify({'message': 'File uploaded successfully'}), 201

# Example usage in Flask CMS
app = Flask(__name__)

