import hashlib
from datetime import datetime

class ContentVersioner:
    def __init__(self):
        self.content_map = {}

    def create_version(self, content):
        """Generate a unique hash for the given content."""
        return self._generate_hash(content)

    def get_version(self, content_id):
        """Return the corresponding version of the given content ID."""
        if content_id in self.content_map:
            return self.content_map[content_id]
        else:
            raise ValueError("Content ID not found")

    def update_version(self, content_id, new_content):
        """Update the version of the given content ID with the new content."""
        current_hash = self.get_version(content_id)
        new_hash = self._generate_hash(new_content)

        if new_hash != current_hash:
            # Only update the map if the hash has changed
            self.content_map[content_id] = new_hash

    def _generate_hash(self, content):
        """Generate a unique hash for the given content using SHA-256."""
        return hashlib.sha256(content.encode()).hexdigest()

# Example usage:

if __name__ == "__main__":
    versioner = ContentVersioner()
    content = "Hello, World!"
    content_id = "hello-world"

    # Create an initial version
    initial_version = versioner.create_version(content)
    print(f"Initial version: {initial_version}")

    # Update the content
    updated_content = f"{content} (Updated)"
    versioner.update_version(content_id, updated_content)

    # Get the latest version
    latest_version = versioner.get_version(content_id)
    print(f"LATEST VERSION: {latest_version}")

import re

class InvalidInputError(Exception):
    """Raised when input is invalid"""
    pass

def validate_input(input_string):
    """
    Validate the input string.

    Args:
        input_string (str): The input string to be validated.

    Returns:
        bool: True if the input string is valid, False otherwise.
    """

    # Regular expression pattern to match valid inputs
    pattern = r"^[a-zA-Z0-9]{1,}$"

    try:
        # Attempt to compile and check the input against the pattern
        regex = re.compile(pattern)
        return bool(regex.match(input_string))
    except re.error as e:
        # If there's a parsing error in the regular expression, raise an exception
        raise InvalidInputError("Invalid input format") from e

# Example usage:
try:
    if validate_input("Hello123"):
        print("Valid input")
    else:
        print("Invalid input")

except InvalidInputError as e:
    print(e)

