import uuid
from typing import Dict, List

class Tenant:
    def __init__(self, name: str):
        self.name = name
        self.users = {}

    def add_user(self, user_id: str, permissions: List[str]):
        """Add a new user to the tenant."""
        if user_id not in self.users:
            self.users[user_id] = {"permissions": set(permissions)}
            return True
        else:
            raise Exception("User already exists")

class User:
    def __init__(self, name: str):
        self.name = name

    def get_permissions(self) -> List[str]:
        """Get the permissions assigned to this user."""
        return list(self.tenant.users[self.id]["permissions"])

class TenantBasedAccessControl:
    def __init__(self):
        self.tenants: Dict[str, Tenant] = {}

    def add_tenant(self, name: str):
        """Add a new tenant."""
        if name not in self.tenants:
            self.tenants[name] = Tenant(name)
            return True
        else:
            raise Exception("Tenant already exists")

    def get_tenant(self, name: str) -> Tenant:
        """Get a tenant by its name."""
        return self.tenants.get(name)

    def create_user(self, tenant_name: str, user_id: str, permissions: List[str]):
        """Create a new user for a specific tenant."""
        if tenant_name in self.tenants and user_id not in self.tenants[tenant_name].users:
            self.tenants[tenant_name].add_user(user_id, permissions)
            return True
        else:
            raise Exception("Tenant does not exist or user already exists")

    def grant_permissions(self, user_id: str, tenant_name: str, new_permissions: List[str]):
        """Grant new permissions to a specific user in a tenant."""
        if tenant_name in self.tenants and user_id in self.tenants[tenant_name].users:
            current_permissions = list(set(self.tenants[tenant_name].users[user_id]["permissions"]))
            current_permissions.update(new_permissions)
            self.tenants[tenant_name].users[user_id]["permissions"] = set(current_permissions)
            return True
        else:
            raise Exception("Tenant does not exist or user does not exist")

# Example usage:

# Create a new tenant based access control object.
acl = TenantBasedAccessControl()

# Add a new tenant.
acl.add_tenant('tenant1')

# Get the created tenant.
tenant = acl.get_tenant('tenant1')
print(tenant.name) # Output: tenant1

# Create a new user in 'tenant1'.
acl.create_user('tenant1', 'user1', ['read', 'write'])

# Grant new permissions to 'user1' in 'tenant1'.
acl.grant_permissions('user1', 'tenant1', ['update'])

# Get the permissions for 'user1' in 'tenant1'.
print(acl.get_tenant('tenant1').users['user1']['permissions']) # Output: ['read', 'write', 'update']

