import os
from s3boto3.s3 import S3Client
import requests

class Storage:
    def __init__(self):
        self.AWS_ACCESS_KEY_ID = os.getenv('AWS_ACCESS_KEY_ID')
        self.AWS_SECRET_ACCESS_KEY = os.getenv('AWS_SECRET_ACCESS_KEY')
        self.BUCKET_NAME = 'your-bucket-name'

    def connect_s3(self):
        return S3Client(
            access_key=self.AWS_ACCESS_KEY_ID,
            secret_access_key=self.AWS_SECRET_ACCESS_KEY
        )

    def list_files(self, bucket_name=None):
        client = self.connect_s3()
        response = client.list_object_v2(Bucket=bucket_name)
        return response['Contents']['Key'] if response else []

    def check_file_update(self, local_path, remote_prefix):
        pass

    def upload_file(self, local_path, file_name, remote_path=None, force=False):
            remote_path = f"{remote_path}/{file_name}" if remote_path is None else remote_path
            headers = {
                'Content-Type': 'binary',
                'Cache-Control': 'no-cache',
                'Content-Length': os.path.getsize(local_path)
            }

            try:
                response = requests.put(
                    remote_path,
                    data=open(local_path, 'rb'),
                    headers=headers,
                    verify=True
                )

                if response.status_code == 200:
                    print(f"File {file_name} uploaded successfully to {remote_path}")
                    return True

                else:
                    print(f"Failed to upload file {file_name}. Status code: {response.status_code}")
                    return False

            except Exception as e:
                print(f"An error occurred while uploading {file_name}: {str(e)}")
                return False

def main():
    storage = Storage()

    # List existing files in the bucket
    local_files = os.listdir('.')
    remote_files = storage.list_files()

    for file_name in local_files:
        if not file_name.endswith('.'):
            continue  # Skip non-file items like directories or hidden files

        local_path = f"."
        remote_path = file_name  # You might need to adjust based on your bucket structure
        exists, updated = storage.check_file_update(local_path, remote_path)

        if not exists and not updated:
            success = upload_file(storage.AWS_ACCESS_KEY_ID, 
                                  AWS_SECRET_ACCESS_KEY,
                                  BUCKET_NAME,
                                  os.path.join('.'))
            if not success:
                break  # Stop on first failed upload
    return

if __name__ == "__main__":
    main()

def validate_email(email):
    if '@' not in email:
        return False

    local_part, _, domain = email.partition('@')

    # Check local part validity
    if len(local_part) < 1 or len(local_part) > 58:
        return False

    allowed_chars_local = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-._')
    for char in local_part:
        if char not in allowed_chars_local:
            return False

    # Check domain part validity
    parts = domain.split('.')
    for part in parts:
        if len(part) < 1 or len(part) > 63:
            return False
        for char in part:
            if char not in allowed_chars_local:
                return False

    # Check that local part doesn't start with a digit
    if len(local_part) > 0 and local_part[0].isdigit():
        return False

    return True

from collections import OrderedDict 

class LRUCache: 
    def __init__(self, capacity): 
        self.cache = OrderedDict() 
        self.capacity = capacity 

    def get(self, key): 
        if key not in self.cache:
            return -1
        else:
            self.cache.move_to_end(key) # If the key is found, move it to the end to show that it was recently used.
            return self.cache[key] 

    def put(self, key, value): 
        self.cache[key] = value 
        self.cache.move_to_end(key) # Add or update the value and move it to the end.
        if len(self.cache) > self.capacity: 
            self.cache.popitem(last=False) # If size is more than capacity, evict the Least Recently Used item.

    def delete(self, key): 
        if key in self.cache: 
            del self.cache[key] # Delete the key-value pair from cache.

    def reset(self): 
        self.cache.clear() # Clear all items from cache.

