from flask import Flask, request, jsonify
from flask_restful import Resource, Api
from werkzeug.security import generate_password_hash, check_password_hash
from itsdangerous import TimedJSONWebSignatureSerializer as Serializer, BadSignature, SignatureExpired
from functools import wraps

app = Flask(__name__)
api = Api(app)

app.config['SECRET_KEY'] = 'ThisIsASecretKey'  # replace with a strong secret key!
serializer = Serializer(app.config['SECRET_KEY'], expires_in=3600)

# A simple in-memory database for this example
users = {}

def token_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-API-TOKEN')
        if not token:
            return jsonify({'message': 'Token is missing!'}), 403
        try:
            data = serializer.loads(token)
        except SignatureExpired:
            return jsonify({'message': 'The token has expired.'}), 401
        except BadSignature:
            return jsonify({'message': 'The token is invalid!'}), 403
        return f(*args, **kwargs)
    return decorated

class Register(Resource):
    def post(self):
        data = request.get_json()
        if not data or 'username' not in data or 'password' not in data:
            return jsonify({'message': 'Missing username or password.'}), 400
        hashed_password = generate_password_hash(data['password'], method='sha256')
        users[data['username']] = {'password': hashed_password}
        token = serializer.dumps({'username': data['username']}).decode('utf-8')
        return jsonify({'message': 'User created.', 'token': token}), 201

class Login(Resource):
    def post(self):
        data = request.get_json()
        if not data or 'username' not in data or 'password' not in data:
            return jsonify({'message': 'Missing username or password.'}), 400
        user = users.get(data['username'])
        if not user or not check_password_hash(user['password'], data['password']):
            return jsonify({'message': 'Invalid username or password.'}), 401
        token = serializer.dumps({'username': data['username']}).decode('utf-8')
        return jsonify({'token': token})

class Protected(Resource):
    @token_required
    def get(self):
        return jsonify({'message': 'This is a protected endpoint.'})

api.add_resource(Register, '/register')
api.add_resource(Login, '/login')
api.add_resource(Protected, '/protected')

if __name__ == '__main__':
    app.run(debug=True)  # Don't run debug mode on production!

