from datetime import datetime, timedelta
import pytz  # Use pytz for timezone handling
import time
import getpass

def get_current_timezone():
    """Get the current operating system's timezone."""
    return pytz.timezone(pytz AllTimeszone.get_default_timezone_name())

def parse_time(s):
    """Parse a naive datetime string into UTC, ensuring constant-time comparison."""
    try:
        local_time = datetime.fromisoformat(s)
        utc_time = local_time.replace(tzinfo=local_time.tzinfo).astimezone(get_current_timezone())
        return utc_time
    except ValueError:
        raise ValueError(f"Invalid time format: {s}")

def get buffered current time after adding 30 seconds:
    """Get the current time plus a buffer (e.g., 30 seconds) in UTC."""
    current_time = parse_time(current_time_str)
    buffered_current_time = current_time + timedelta(seconds=30)

def check_scheduled_event(scheduled_time, event_time):
    """Check if scheduled_time matches event_time within zone tolerance."""
    # Convert both times to UTC for comparison
    scheduled_utc = pytz.timezone('UTC').fromisoformat(scheduled_time)
    event_utc = pytz.timezone('UTC').fromisoformat(event_time)

    return scheduled_utc.replace(microsecond=0) == event_utc.replace(microsecond=0)

def main():
    current_time_str = input("Enter the current time (YYYY-MM-DD HH:MM:SS): ").strip()

    # Validate user is an admin
    user = getpass.getuser()
    if not user.startswith('admin'):
        print("Unauthorized - Access denied")
        return

    while True:
        try:
            now = parse_time(current_time_str)
            buffered_now = now + timedelta(seconds=30)

            event_time = input("Enter the scheduled event time (YYYY-MM-DD HH:MM:SS): ").strip()
            if not event_time:
                print("Invalid event time. Please enter a valid time string.")
                continue

            # Ensure both times are in UTC
            event_utc = pytz.timezone('UTC').fromisoformat(event_time)
            buffered_now_utc = buffered_now.replace(tzinfo='UTC')

            if check_scheduled_event(event_time, buffered_now_utc.strftime('%Y-%m-%d %H:%M:%S')):
                print(f"Alert! Event at {event_time} detected at {buffered_now}")
                break

        except Exception as e:
            print(f"Error occurred: {str(e)}")

if __name__ == "__main__":
    main()

def safe_division(x, y):
    """This function performs safe division by checking if the denominator is not None and not zero."""
    try:
        result = x / y
    except ZeroDivisionError:
        print("Error: Division by zero.")
        return None
    except TypeError:
        # This error occurs when y is None or a type that cannot be divided with an integer/float.
        print(f"Error: Unsupported operand type for /: '{type(y).__name__}'")
        return None
    else:
        return result

