import psutil
import os
from datetime import datetime

class CacheMonitor:
    def __init__(self):
        self.cache_usage = {}

    def get_cache_usage(self):
        # Get current cache usage
        try:
            self.cache_usage['cache'] = psutil.virtual_memory().percent
            self.cache_usage['cpu_percent'] = psutil.cpu_percent(interval=1)
            self.cache_usage['memory_usage'] = psutil.Process(os.getpid()).memory_info().rss / (1024 * 1024)

            # Record current timestamp
            self.cache_usage['timestamp'] = datetime.now()

        except Exception as e:
            print(f"Error getting cache usage: {str(e)}")

    def update_cache_usage(self, new_value):
        try:
            if isinstance(new_value, dict):
                for key in new_value.keys():
                    self.cache_usage[key] = new_value[key]
            else:
                # Update the 'cache' value with a fixed percentage
                self.cache_usage['cache'] = new_value

            print("Cache usage updated")

        except Exception as e:
            print(f"Error updating cache usage: {str(e)}")


    def display_cache_usage(self):
        try:
            for key, value in self.cache_usage.items():
                print(f"{key}: {value}")

        except Exception as e:
            print(f"Error displaying cache usage: {str(e)}")

def main():
    monitor = CacheMonitor()

    # Initial get
    print("Initial Cache Usage:")
