from datetime import datetime
from simple_websocket_server import WebSocketServer, WebSocket

class SimpleEcho(WebSocket):
    def __init__(self, server, sock, address):
        super().__init__(server, sock)
        self.last_message_time = None
        self.rate_limit = 2  # messages per second

    def handle(self):
        if self.last_message_time is not None:
            elapsed = (datetime.now() - self.last_message_time).total_seconds()
            if elapsed < 1 / self.rate_limit:
                print('Rate limit exceeded!')
                return

        # Handle message...

        self.last_message_time = datetime.now()

    def connected(self):
        print(self.address, 'connected')

    def handle_close(self):
        print(self.address, 'closed')

class SimpleChat(WebSocketServer):
    def __init__(self, host, port):
        super().__init__(host, port, SimpleEcho)

if __name__ == "__main__":
    server = SimpleChat('localhost', 5000)
    server.serve_forever()

import graphql

class QueryValidator:
    def __init__(self, schema):
        self.schema = schema

    def validate(self, query):
        errors = []
        try:
            result = self.schema.execute(query)
            if result.errors:
                for error in result.errors:
                    errors.append({
                        "message": error.message,
                        "location": {
                            "column": error.location.column,
                            "line": error.location.line
                        }
                    })
        except Exception as e:
            errors.append({
                "message": str(e),
                "location": None
            })

        return errors

# Define a GraphQL schema
class Query:
    def __init__(self):
        self.fields = {
            "name": {"type": "String"},
            "age": {"type": "Int"}
        }

schema = graphql.Schema(query=Query)

# Create an instance of the query validator
validator = QueryValidator(schema)

# Define a GraphQL query
query = """
    query GetPerson($name: String, $age: Int) {
        person(name: $name, age: $age) {
            name
            age
        }
    }
"""

# Validate the query
errors = validator.validate(query)

if errors:
    print("Validation errors:")
    for error in errors:
        print(f"Message: {error['message']}")
        if 'location' in error:
            print(f"Location: Line {error['location']['line']}, Column {error['location']['column']}")
else:
    print("Query is valid")

