logger = logging.getLogger(__name__)

class Cart:
    def __init__(self):
        self.items: Dict[str, str] = {}
        self._cart_key = "shopping_cart"

    async def get(self, request: str) -> None:
        params = parse_qs(request)
        method = params.get("method", ["GET"])[0]

        if method == "GET":
            self.display_cart()
        elif method == "POST":
            data = parse_qs(request)
            action = data.get("action", ["GET'])[0]

            if action in ["add_item", "remove_item", "update_quantity", "delete_item"]:
                self._handle_cart_operation(action, data)

    async def display_cart(self) -> None:
        cart_str = urlunparse(
            (
                parse_qs(urlencode(str(url))["cart"]),
                {},
                {"_cart_key": self._cart_key}
            )
        )

        response = await self._fetch_cart()
        if response.status == 200:
            cart_dict = {k: v for v in response.json().get("cart", {}).items() if k != "_token"}
            self.items.clear()
            self.items.update(cart_dict)
        else:
            logger.error(f"Failed to display cart: {response.text}")

    async def _fetch_cart(self) -> Any:
        url = f"http://{host}:{port}/{self._cart_key}"
        response = await fetch(url)
        return response

    async def _handle_cart_operation(self, action: str, data: Dict[str, Any]) -> None:
        item_id = data.get("id", [None])[0]
        name = data.get("name", [None])[0]
        quantity = int(data.get("quantity", [1])[0])

        if action == "add_item":
            self.items.update({item_id: quantity})
            await add_item_db(item_id, name, quantity)
        elif action == "remove_item":
            if item_id in self.items:
                self.items.pop(item_id)
                await delete_item_db(item_id)
        elif action == "update_quantity":
            current = int(self.items.get(item_id, 0))
            new = max(current - quantity, 0)
            if new > current:
                self.items[item_id] = new
                await add_item_db(item_id, name, new)
        elif action == "delete_item":
            if item_id in self.items:
                del self.items[item_id]
                await delete_item_db(item_id)

    async def save_cart(self) -> None:
        cart_url = urlunparse(
            (
                parse_qs(urlencode(str(url))["cart"]),
                {},
                {"_cart_key": self._cart_key}
            )
        )

        response = await fetch(cart_url, method="PUT", body=json.dumps({
            "_token": str(uuid.uuid4()),
            "cart": {k: v for k, v in self.items.items()}
        }))
        if response.status == 204:
            logger.info("Cart saved successfully")
        else:
            raise RuntimeError(f"Failed to save cart: {response.text}")

    async def close(self) -> None:
        await self._fetch_cart()

