import pycountry_countrypoints

def detect_language():
    # Check if the required module is installed
    if not hasattr(pycountry_countrypoints, 'get'):
        raise ValueError("pycountry-countries library is not available. Please install it.")

    try:
        # Fetch country points which might take some time on first request
        pycountry_countrypoints.download()
    except Exception as e:
        print(f"Error fetching country points: {e}", file=sys.stderr)
        return "English"

    try:
        en_data = pycountry_countrypoints.get('en')
        lang_code = en_data.lang
        if lang_code in ('en-GB', 'en-US'):
            # Default to English if detected as British or US English
            return "English"
        language_name = en_data.get('alpha2').name
    except (KeyError, AttributeError) as e:
        print(f"Language detection error: {e}", file=sys.stderr)
        return "English"

    print(f"Detected ISO 639-1 Alpha-2 Code: {lang_code}")
    print(f"Language Name: {language_name}")

def detect_platform():
    if platform.system() == 'iOS':
        return "iPhone/iPad"
    elif system_info := getapi('platform_info'):
        if system_info[' manufacturer'] in ('Apple', 'iPad'):
            return "iOS"
    # Check for Windows Phone or similar
    elif platform.node_id.startswith(" smartphone"):
        # This is a heuristic; not foolproof but better than nothing
        return "Android"
    else:
        return "Desktop Environment"

def main():
    print("Security-Aware Language Detection")
    try:
        platform_type = detect_platform()
        language = detect_language()
        print(f"Platform: {platform_type}")
        print(f"Language detected as: {language}\nThis message is securely formatted and cannot be exploited.")
    except Exception as e:
        print(f"Error in main function: {e}", file=sys.stderr)

if __name__ == "__main__":
    main()

