import time

# Define the cache and its maximum size
cache = {}
max_size = 1000

# Define a function for adding new items to the cache
def add_to_cache(key, value):
    if len(cache) >= max_size:
        # Remove the oldest item from the cache
        del cache[list(cache)[0]]
    cache[key] = value

# Define a function for checking the cache for stale entries and removing them
def check_cache():
    for key in list(cache):
        if time.time() - cache[key][1] > 3600:
            # Remove the stale entry from the cache
            del cache[key]

