import threading

class SharedResource:
    def __init__(self):
        self._value = 0
        self._lock = threading.Lock()

    def increment(self, by):
        with self._lock:
            print(f"Thread {by} is changing shared resource")
            self._value += by
            print(f"After thread {by}, value = {self._value}")

class MyThread(threading.Thread):
    def __init__(self, by, shared_resource):
        super().__init__()
        self._increment_by = by
        self._shared_resource = shared_resource

    def run(self):
        for _ in range(10):
            self._shared_resource.increment(self._increment_by)

def main():
    shared_resource = SharedResource()

    threads = [MyThread(i, shared_resource) for i in range(5)]
    for t in threads:
        t.start()

    for t in threads:
        t.join()

if __name__ == "__main__":
    main()

import PyPDF2

def validate_pdf(file):
    # Create a PyPDF2 reader object
    with open(file, 'rb') as pdf_file:
        reader = PyPDF2.PdfFileReader(pdf_file)

    # Check the PDF version number
    if reader.getVersion() != 1.4:
        raise ValueError('Invalid PDF version')

    # Check the PDF trailer dictionary
    if reader.getTrailer() is None:
        raise ValueError('No trailer dictionary found in PDF')

    # Check the PDF cross-reference table
    if reader.getCrossReferenceTable() is None:
        raise ValueError('No cross-reference table found in PDF')

    # Check the PDF root object
    if reader.getRootObject() is None:
        raise ValueError('No root object found in PDF')

    # Check the PDF information dictionary
    if reader.getInfoDictionary() is None:
        raise ValueError('No information dictionary found in PDF')

    # Check the PDF encryption dictionary
    if reader.getEncryptionDictionary() is not None:
        raise ValueError('PDF is encrypted')

    # Check the PDF page count
    if reader.getNumPages() == 0:
        raise ValueError('No pages found in PDF')

