import time
from collections import deque

class RateLimiter(object):
    def __init__(self, max_requests, period):
        self.max_requests = max_requests
        self.period = period
        self.request_times = deque()

    def allow_request(self):
        current_time = time.monotonic()

        # Remove requests that are outside of the time limit
        while self.request_times and self.request_times[0] <= current_time - self.period:
            self.request_times.popleft()

        if len(self.request_times) >= self.max_requests:
            # Too many requests, so we deny the request
            return False
        else:
            # Add this request to our list and allow it
            self.request_times.append(current_time)
            return True

# Limit IoT devices to 100 requests per minute
rate_limiter = RateLimiter(max_requests=100, period=60)

def handle_iot_request():
    if rate_limiter.allow_request():
        # Process the request
        pass
    else:
        # Deny the request due to too many requests in a short amount of time
        pass

import json
from xml.dom import minidom

class SecureJsonGenerator:
    @staticmethod
    def serialize(data):
        """Serialize any data type into a properly escaped JSON string"""
        if isinstance(data, str) and len(data) > 0:
            # Convert UTF-8 encoded bytes to Unicode strings
            data = data.encode('utf-8').decode('unicode_escape')
        elif isinstance(data, dict):
            return json.dumps(data, ensure_ascii=False, escaper=lambda x: x.replace u'\u201c', '\u201d'))
        elif isinstance(data, list):
            return json.dumps(data, ensure_ascii=False, escape_rfunc=minidom.ESCapedString)
        else:
            # For other data types (strings, numbers, booleans), use standard JSON encoding
            return json.dumps(data)

    @staticmethod
    def send_message(data):
        """Serialize data and return it as a properly escaped JSON string"""
        try:
            json_str = SecureJsonGenerator.serialize(data)
            # Decode the JSON string to bytes using UTF-8
            encoded_data = json_str.encode('utf-8')
            return encoded_data
        except Exception as e:
            raise ValueError(f"Invalid data type for WebSocket message: {e}")

    @staticmethod
    def receive_message(encoded_data):
        """Decode a received WebSocket message from bytes to a Python object"""
        try:
            # Encode the incoming bytes back to a UTF-8 string before decoding JSON
            json_str = encoded_data.decode('utf-8')
            return json.loads(json_str)
        except Exception as e:
            raise ValueError(f"Invalid WebSocket message format: {e}")

