class EventHandler:
    def __init__(self):
        self.seen_events = set()  # Keep a record of all previously seen events

    def handle_event(self, event):
        if event in self.seen_events:
            print("Duplicate event detected and discarded:", event)
            return False

        # If the event hasn't been seen before, add it to our set of known events
        self.seen_events.add(event)

        # Handle the event as normal
        print("Handling event:", event)  # Replace this with your actual handling code
        return True

import os
import hashlib
from Cryptodome.Cipher import AES

class Encryption:
    def __init__(self, key):
        self.key = key

    def encrypt(self, message):
        iv = os.urandom(16) # 16 bytes of random data used as initialization vector
        cipher = AES.new(self.key, AES.MODE_CBC, iv)
        return iv + cipher.encrypt(message)

    def decrypt(self, message):
        iv = message[:16] # 16 bytes of initialization vector
        cipher = AES.new(self.key, AES.MODE_CBC, iv)
        return cipher.decrypt(message[16:])

