import re

def validate_phone_number(number):
    # Remove all non-digit characters
    number = re.sub("\D", "", number)

    # Check if the remaining string matches a valid US phone number pattern (10 digits for local numbers, 11 digits for international numbers starting with 1)
    if re.match("^[2-9]\d{9}$|^1[2-9]\d{9}$", number):
        return True
    else:
        return False

