import os
from email import Parser
import re

# Define fake credentials and signatures to check against
FAKE_USERNAME = ['admin', 'Admin']
FAKE_PASSWORD = ['password123', 'Password!', 'passw0rd']
FAKE_SIGNATURES = ['Best regards,']
FAKE_COMPANY = ['TechCorp Inc.', 'techcorp.com']

def parse_email(email_content):
    parser = Parser()
    parsed = parser.parsestr(email_content)
    return {
        'body': parsed.gettextpart(),
        'from': parsed.get_header('From'),
        'date': parsed.get_header('Date')
    }

def check_spoofing(email_body, from_addr, date):
    conditions_met = 0

    # Check if any fake username is in the body
    for fake_user in FAKE_USERNAME:
        if fake_user.lower() in email_body.lower():
            conditions_met += 1

    # Check if any fake user part exists in the from address
    fake_user_pattern = re.compile(r'\b(' + '|'.join(FAKE_USERNAME) + r')\b')
    if fake_user_pattern.search(from_addr):
        conditions_met += 1

    # Check for any fake signature in the body
    for sig in FAKE_SIGNATURES:
        if sig.lower() in email_body.lower():
            conditions_met += 1

    # If at least two out of three conditions match, flag as suspicious
    if conditions_met >= 2:
        return True
    else:
        return False

def main():
    fake_email_content = "From: admin@example.com\nDate: Today\nSubject: Test Subject\nBody: Testing spoofing detection."
    real_email_content = "From: user@real.com\nDate: Yesterday\nSubject: Re: Test Subject\nBody: Testing genuine email."

    for content in [fake_email_content, real_email_content]:
        parsed = parse_email(content)
        body = parsed['body']
        from_addr = parsed['from']

        if check_spoofing(body, from_addr, None):
            print("Suspicious email detected.")
        else:
            print("Email appears legitimate.")

if __name__ == "__main__":
    main()

