import time
from functools import wraps

def retry(exceptions_to_check, total_tries=4, initial_wait=0.5, backoff_factor=2):
    """
    Decorator for retrying functions if specific exceptions occur.

    :param exceptions_to_check: tuple of exception types to check for
    :param total_tries: maximum number of times to try the operation
    :param initial_wait: seconds to wait before retrying (will be multiplied by backoff_factor each time)
    :param backoff_factor: factor to increase wait time between retries
    """
    def deco_retry(f):
        @wraps(f)
        def f_retry(*args, **kwargs):
            mtries, mdelay = total_tries, initial_wait
            while mtries > 1:
                try:
                    return f(*args, **kwargs)
                except exceptions_to_check as e:
                    print(f"{str(e)}, Retrying in {mdelay} seconds...")
                    time.sleep(mdelay)
                    mtries -= 1
                    mdelay *= backoff_factor
            # Last attempt without retrying
            return f(*args, **kwargs)
        return f_retry  # true decorator
    return deco_retry

import time
from threading import Thread

class SessionManager:
    def __init__(self, max_inactivity_time):
        self.max_inactivity_time = max_inactivity_time
        self.sessions = {}
        self.lock = ThreadLock()

    def create_session(self, user_id):
        with self.lock:
            if user_id in self.sessions:
                return False  # Session already exists for this user
            timestamp = time.time()
            session_data = {"last_active": timestamp}
            self.sessions[user_id] = session_data
            return True

    def update_last_active(self, user_id):
        with self.lock:
            if user_id not in self.sessions:
                return False  # Session does not exist for this user
            timestamp = time.time()
            self.sessions[user_id]["last_active"] = timestamp

    def has_expired(self, user_id):
        with self.lock:
            if user_id not in self.sessions:
                return True  # Session does not exist for this user
            timestamp = self.sessions[user_id]["last_active"]
            elapsed_time = time.time() - timestamp
            return elapsed_time > self.max_inactivity_time

    def expire_sessions(self):
        with self.lock:
            current_time = time.time()
            to_expire = [user_id for user_id, data in self.sessions.items() if current_time - data["last_active"] > self.max_inactivity_time]
            for user_id in to_expire:
                del self.sessions[user_id]

class ThreadLock:
    def __init__(self):
        self.lock = threading.Lock()

    def acquire(self):
        return self.lock.acquire(False)

    def release(self):
        self.lock.release()

