import cv2

def resize_image(image, width=None, height=None):
    # Calculate the scale factor for resizing the image
    if width is not None and height is not None:
        scale = (width / image.shape[1], height / image.shape[0])
    elif width is not None:
        scale = (width / image.shape[1], 1)
    elif height is not None:
        scale = (height / image.shape[0], 1)
    else:
        raise ValueError("Invalid parameters for resizing")

    # Resize the image using OpenCV's resize function
    return cv2.resize(image, dsize=None, fx=scale[0], fy=scale[1], interpolation=cv2.INTER_LINEAR)

