    print(f'{"Resource":<10} | {"Usage"}')
    for key, value in info.items():
        if isinstance(value, dict):
            print("-"*40)
            print(f'{key:<10}')
            for sub_k, sub_v in value.items():
                print(f'{sub_k:<10}: {sub_v} MB')
        else:
