class SessionManager:
    def __init__(self):
        self.last_active_time = {}

    def update_last_active(self, user_id):
        if user_id in self.last_active_time:
            self.last_active_time[user_id] = time.time()
        else:
            self.last_active_time[user_id] = time.time()

    def check_expiration(self):
        current_time = time.time()
        for user_id, last_active_time in list(self.last_active_time.items()):
            if current_time - last_active_time > 1800:  # session expires after 5 minutes
                del self.last_active_time[user_id]
                session.clear()

