import time

class RequestTracker:
    def __init__(self, max_requests):
        self.max_requests = max_requests
        self.window_requests = dict()  # Key: timestamp, Value: True (processed)

    def process_request(self):
        current_time = time.time()

        # Remove expired requests older than 24 hours
        for t in list(self.window_requests.keys()):
            if t < (current_time - 86400):  # Subtract one day in seconds
                del self.window_requests[t]

        # Add the new request to the window
        timestamp = current_time
        self.window_requests[timestamp] = True

        # Check and remove if exceeding max allowed requests for the day
        while len(self.window_requests) > self.max_requests:
            oldest_timestamp = min(self.window_requests.keys())
            del self.window_requests[oldest_timestamp]

        return len(self.window_requests)

