class Payment Gateway Error(Exception):
    pass

def get_payment_token():
    session = ClientSession()
    try:
        response = requests.get(
            'https://payment-gateway.example.com/auth',
            headers={
                'Authorization': f'Basic {os.getenv("PAYLOAD_TOKEN")}'
            }
        )
        response.raise_for_status()
        token = os.getenv('GATEWAY_AUTH_KEY')
        secret_key = os.getenv('GATEWAY_SECRET_KEY')
        session.close()
        return (token, secret_key)
    except Exception as e:
        raise Payment Gateway Error(f"Failed to authenticate with payment gateway: {str(e)}")

def handle_paymentTransaction(card_number: str, card_expires: int, card_cvv: str) -> Optional[Dict[str, Any]]:
    try:
        token, secret_key = get_payment_token()
        session = ClientSession()
        headers = {
            'Authorization': f'Basic {token}',
            'Content-Type': 'application/json',
            'Authorization': f'Basic {token}'
        }
        response = requests.post(
            'https://payment-gateway.example.com/processPayment',
            json={
                'card_number': card_number,
                'card_expires': card_expires,
                'card_cvv': card_cvv,
                'cid': os.getenv('GATEWAY_CID')
            },
            headers=headers
        )
        session.close()
        response.raise_for_status()
        return response.json()
    except requests.exceptions.RequestException as e:
        send_clear_error_message(card_number)
        raise Payment Gateway Error(f"Payment failed: {str(e)}")
    except (ValueError, TypeError) as e:
        send_clear_error_message(card_number)
        raise Payment Gateway Error("Invalid card details")
    except (FileNotFoundError, AttributeError) as e:
        send_clear_error_message(card_number)
        raise Payment Gateway Error("Server error on payment gateway")

def send_clear_error_message(card_number: str):
    message = f"Payment failed for card number {card_number}. Reason: Invalid card details or server-side issue."
    headers = {
        'Content-Type': 'application/json',
        'Authorization': f'Basic {os.getenv("PAYLOAD_TOKEN")}'
    }
    session = ClientSession()
    response = requests.post(
        'https://payment-gateway.example.com/sendError',
        json={'card_number': card_number, 'message': message},
        headers=headers
    )
    session.close()
    if response.status_code == 200:
        print(f"Successfully sent error message for card number {card_number}")
    else:
        raise Payment Gateway Error(f"Failed to send error message: {str(response)}")

def delay_request(retry_count: int = 3) -> None:
    sleep_time = random.uniform(1, 3)
    for _ in range(retry_count):
