import re

class FixedWidthTextParser:
    def __init__(self, file_path, delimiter=None):
        """
        Initializes the parser with a file path and optional delimiter.

        Args:
            file_path (str): Path to the fixed-width text file.
            delimiter (str): Delimiter character used in the file. Defaults to None.
        """
        self.file_path = file_path
        self.delimiter = delimiter

    def _get_delimited_fields(self, line):
        """
        Extracts delimited fields from a single line.

        Args:
            line (str): Line from the file with fixed-width fields.

        Returns:
            list: List of extracted fields.
        """
        if self.delimiter is None:
            return re.split(r'\s+', line)
        else:
            pattern = f'{self.delimiter}([a-zA-Z0-9_]+)'
            return re.findall(pattern, line)

    def parse(self):
        """
        Parses the fixed-width text file and returns a pandas DataFrame.

        Returns:
            pandas.DataFrame: Dataframe with extracted fields.
        """
        try:
            with open(self.file_path, 'r') as f:
                lines = [line.strip() for line in f.readlines()]
                return pd.DataFrame([self._get_delimited_fields(line) for line in lines])
        except FileNotFoundError:
            print(f"Error: File '{self.file_path}' not found.")
            return None

# Example usage
