import time

def process_event(event):
    try:
        # Code to process the event
        pass
    except Exception as e:
        # Log the error
        print(f"Error processing event: {e}")

        # Retry the event processing with exponential backoff
        max_retries = 5
        retry_count = 0
        while retry_count < max_retries:
            time.sleep(2**retry_count)
            try:
                process_event(event)
                break
            except Exception as e:
                retry_count += 1
                print(f"Retry attempt {retry_count} failed.")

        if retry_count == max_retries:
            print(f"Event {event} could not be processed after {max_retries} retries.")

def pig_latin(word):
    vowels = ['a', 'e', 'i', 'o', 'u']

    # If the first letter is a vowel, add "way" to the end
    if word[0].lower() in vowels:
        return word + "way"

    else:
        # If the first letter is not a vowel, move it to the end and then add "ay"
        return word[1:] + word[0] + "ay"

print(pig_latin("Python"))  # Expected output: 'ythonpay'

