import os
import json

class Config:
    def __init__(self, filename):
        self.filename = filename
        self.load_config()

    def load_config(self):
        if not os.path.exists(self.filename):
            raise FileNotFoundError(f'File {self.filename} does not exist')

        with open(self.filename, 'r') as file:
            config = json.load(file)
            for key, value in config.items():
                setattr(self, key, value)

    def save_config(self):
        config = {}
        for attribute in dir(self):
            if attribute.startswith('__') or attribute.endswith('__'):
                continue
            value = getattr(self, attribute)
            if isinstance(value, (str, int, float)):
                config[attribute] = value
        with open(self.filename, 'w') as file:
            json.dump(config, file)

class ConfigManager:
    def __init__(self):
        self.configs = {}

    def load_config(self, filename):
        try:
            return Config(filename)
        except FileNotFoundError:
            print(f'File {filename} does not exist')
            return None

    def save_config(self, config):
        if config.filename in self.configs:
            self.configs[config.filename].save_config()
        else:
            with open(config.filename, 'w') as file:
                json.dump({f'__{key}': value for key, value in dir(config) if not key.startswith('__')}, file)

    def reload_configs(self):
        for filename in os.listdir():
            if filename.endswith('.json'):
                self.save_config(self.load_config(filename))

# Usage
config_manager = ConfigManager()
config_manager.reload_configs()

