def stream_parser(file_path, chunk_size=1024):
    """
    Stream parser for large files.

    Args:
        file_path (str): Path to the file to be parsed.
        chunk_size (int, optional): Size of each chunk. Defaults to 1024.

    Yields:
        str: A line from the file as a string.
    """
    try:
        with open(file_path, 'r') as file:
            while True:
                # Read a chunk of data from the file
                chunk = file.read(chunk_size)
                if not chunk:
                    break  # End of file reached
                yield chunk.strip()
    except FileNotFoundError:
        print(f"File {file_path} not found.")
    except Exception as e:
        print(f"An error occurred: {e}")


