    def authenticate_user(self, username, password):
        """Authenticate user using OAuth 2.0 flow."""
        data = {
            'grant_type': 'password',
            'username': username,
            'password': password,
            'client_id': os.getenv('CLIENT_ID'),
            'redirect_uri': os.getenv('REDIRECT_URI')
        }

        response = requests.post(
            self.authUrl,
            data=data,
            auth=(os.getenv('AUTH_USER'), os.getenv('AUTH_PASSWORD'))
        )

        if response.status_code == 200:
            access_token = response.json()['access_token']
            refresh_token = response.json().get('refresh_token')

            token_data = {
                'access_token': access_token,
                'expires_in': response.json().get('expires_in', 0),
                'refresh_token': refresh_token
            }

            return token_data, True
        else:
            logger.error(f"Authentication failed for user {username}. Status code: {response.status_code}")
            return None, False

    def get_onboarding_code(self):
        """Generate and return onboarding code for tenant."""
        try:
            response = requests.get(
                self.onboardingCodeEndpoint,
