    def get_access_token(self, refresh_token):
        """Obtain access token using refresh token."""
        try:
            headers = {
                'Content-Type': 'application/json',
                'Authorization': f'Basic {os.getenv("AUTH_BASE64")}'
            }

            data = {
                'grant_type': 'refresh_token',
