# The event queue manager
class EventQueueManager(threading.Thread):
    def __init__(self, queue):
        threading.Thread.__init__(self)
        self.queue = queue

    # Method to add events to the queue
    def put_event(self, event):
        self.queue.put(event)

    # This method runs in a separate thread and handles events from the queue
    def run(self):
        while True:
            event = self.queue.get()
            print("Processing Event {}".format(event))

            # Add your logic to handle the event here
            time.sleep(1)  # Simulate some processing

# Main code that uses these classes
