    queue = Queue()

    manager = EventQueueManager(queue)
    manager.daemon = True
    manager.start()

    while True:
        time.sleep(1)  # Simulate delay between events

        event_name = "Event {}".format(int(time.time()))
        print("Adding Event {} to queue".format(event_name))
        manager.put_event(Event(event_name))

