from functools import wraps
import time

def retry(max_retries, delay=1):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            tries = 0
            while True:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    if tries >= max_retries:
                        raise e  # If we've reached the maximum number of retries, re-raise the exception.
                    else:
                        print(f"An error occurred ({e}). Retrying in {delay} seconds...")
                        time.sleep(delay)
                        tries += 1
        return wrapper
    return decorator

import sys

def optimize_text_parse(chunk_size=None):
    """Optimize text parsing for large files using generators."""
    lines = (line.strip() for line in sys.stdin)

    def process_chunk(chunk, callback=None):
        """Process a chunk of lines with optional processing function."""
        if not chunk:
            return
        for line in chunk:
            yield next(line)  # Apply processing and yield result

    while True:
        try:
            if chunk_size is None or chunk_size <= 0:
                # Read all remaining data without chunking
                chunk = [line for line in lines]
                processed = process_chunk(chunk)
            else:
                # Read a chunk of data (lines), each line being stripped
                buffer = []
                while len(buffer) < chunk_size and next(lines, None) is not None:
                    buffer.append(next(lines))
                if buffer:  # At least one line was read
                    processed = process_chunk(buffer)
            for result in processed:
                yield result

        except StopIteration:
            break
        except:
            print("Error processing file:", sys.exc_info()[1])
            break

# Example usage:
