from PyPDF2 import PdfFileReader, PdfFileWriter

def split_pdf(path_to_pdf, name_of_split, page_step):
    pdf = PdfFileReader(path_to_pdf)

    for page in range(0, pdf.getNumPages(), page_step):
        pdf_writer = PdfFileWriter()

        output = f'{name_of_split}{page}.pdf'

        for i in range(page, page + page_step):
            if i < pdf.getNumPages():
                pdf_writer.addPage(pdf.getPage(i))

        with open(output, 'wb') as output_pdf:
            pdf_writer.write(output_pdf)

# Usage example
split_pdf('largefile.pdf', 'smallerfile_part', 5)

def translate_string(text, cipher):
    translated = []
    for char in text:
        if char in cipher:
            translated.append(cipher[char])
    return ''.join(translated)

