class Product:
    def __init__(self, id, name, price):
        self.id = id
        self.name = name
        self._price = price

class ShoppingCart:
    def __init__(self):
        self.products = {}

    def add_product(self, product):
        if product not in self.products:
            self.products[product] = 0

        self.products[product] += 1

    def total_price(self):
        return sum([product._price * quantity for product, quantity in self.products.items()])

    def verify_prices(self):
        current_prices = {product: product._price for product in self.products}

        if any([product._price != current_prices[product] for product in self.products]):
            raise Exception("Price manipulation detected!")

