import json
from requests import Request, Response

# Define the schema for the API inputs
schema = {
    "type": "object",
    "properties": {
        "name": {"type": "string"},
        "age": {"type": "integer"}
    },
    "required": ["name"]
}

def validate_input(request: Request) -> Response:
    try:
        # Parse the request data into a JSON object
        data = json.loads(request.data)

        # Validate the input against the schema
        errors = json.validate(data, schema)

        if len(errors) > 0:
            return Response(status=400, body={"error": "Invalid input"})
        else:
            return Response(status=200)
    except json.JSONDecodeError as e:
        return Response(status=400, body={"error": "Invalid JSON data"})

class FormValidator:
    def __init__(self, name, email, phone, address):
        self.name = name
        self.email = email
        self.phone = phone
        self.address = address

    def validate_name(self):
        if len(self.name) < 2 or len(self.name) > 50:
            return "Name should be between 2 to 50 characters"
        else:
            return True

    def validate_email(self):
        if "@" not in self.email:
            return "Invalid email address"
        elif "." not in self.email.split("@")[1]:
            return "Invalid domain"
        else:
            return True

    def validate_phone(self):
        if len(self.phone) != 10 or not self.phone.isdigit():
            return "Invalid phone number"
        else:
            return True

    def validate_address(self):
        if len(self.address) < 5 or len(self.address) > 100:
            return "Address should be between 5 to 100 characters"
        elif not any(char.isalpha() for char in self.address):
            return "Address should contain at least one letter"
        else:
            return True

