class Content(object):
    def __init__(self, title, body, author):
        self.title = title
        self.body = body
        self.author = author
        self.status = 'Draft'

    def approve_content(self):
        if self.status == 'Approved':
            print('Content already approved')
        else:
            self.status = 'Approved'
            print('Content Approved Successfully!')

    def reject_content(self):
        if self.status != 'Draft':
            print('Cannot reject content that has already been processed')
        else:
            self.status = 'Rejected'
            print('Content Rejected Successfully!')

    def __str__(self):
        return f"Title: {self.title}, Body: {self.body}, Author: {self.author}, Status: {self.status}"

