from flask import Flask, request, abort
import hmac
import hashlib

app = Flask(__name__)
WEBHOOK_SECRET = 'your-webhook-secret' # Replace with your actual webhook secret

@app.route('/webhook', methods=['POST'])
def handle_webhook():
    data = request.data
    signature = request.headers.get('X-Hub-Signature')

    if not is_valid(signature, data):
        abort(403) # Forbidden

    # Process the webhook event...

def is_valid(signature, data):
    secret = bytes(WEBHOOK_SECRET, 'utf-8')
    digest = hmac.new(secret, msg=data, digestmod=hashlib.sha256).hexdigest()
    return hmac.compare_digest(signature, "sha256=" + digest)

