@partial(max_retries=3, wait=1, failfast=True)
def process_event(event, callback, content_type, headers):
    logger.debug(f"Processing event: {event}")
    try:
        return callback(event=event, content_type=content_type, headers=headers)
    except Exception as e:
        logger.error(f"Event processing failed: {str(e)}")
        raise

def example_callback(event, content_type, headers):
