import graphene
from graphene import ObjectType, String, ID, Field, List

class Book(ObjectType):
    id = ID()
    title = String(required=True)
    author_id = ID(required=True)

class Author(ObjectType):
    id = ID()
    name = String(required=True)
    books = List(Book)

# In a real-world application, you would use a database to store and retrieve data.
# For simplicity, I'll use in-memory storage here.
books_data = {}
authors_data = {}

class Query(ObjectType):
    book = Field(Book, id=ID())
    author = Field(Author, id=ID())

    def resolve_book(self, info, id):
        return books_data.get(id)

    def resolve_author(self, info, id):
        author = authors_data.get(id)
        if author:
            author.books = [book for book in books_data.values() if book.author_id == id]
        return author

class CreateBook(graphene.Mutation):
    class Arguments:
        title = String(required=True)
        author_id = ID(required=True)

    book = Field(Book)

    def mutate(self, info, title, author_id):
        if not authors_data.get(author_id):
            raise Exception("Author does not exist.")

        book = Book(id=len(books_data)+1, title=title, author_id=author_id)
        books_data[book.id] = book
        return CreateBook(book=book)

class CreateAuthor(graphene.Mutation):
    class Arguments:
        name = String(required=True)

    author = Field(Author)

    def mutate(self, info, name):
        author = Author(id=len(authors_data)+1, name=name)
        authors_data[author.id] = author
        return CreateAuthor(author=author)

class Mutation(ObjectType):
    create_book = CreateBook.Field()
    create_author = CreateAuthor.Field()

schema = graphene.Schema(query=Query, mutation=Mutation)

