def validate_expiry_date(expiry):
    current_year = datetime.datetime.now().year % 100   # Getting the last two digits of the current year.
    try:
        month, year = map(int, expiry.split('/'))      # Splitting and converting to integers.
        if (month > 0 and month <= 12) and (year >= current_year):   # Checking for valid month and future year.
            return True
    except ValueError:                       # If the split or conversion fails, it's invalid.
        pass
    return False

