class VersionControlSystem:
    def __init__(self):
        self.versions = {}

    def commit(self, content):
        # Automatically determine next version number based on existing versions
        version = len(self.versions) + 1

        # Store the content in the versions dictionary
        self.versions[version] = content

        return f"Committed as version {version}"

    def revert(self, version):
        if version in self.versions:
            # Revert to specified version by returning its content
            return self.versions[version]
        else:
            return "Version not found."

# Usage
vcs = VersionControlSystem()
print(vcs.commit("Initial Content"))  # Outputs: Committed as version 1
print(vcs.commit("Updated Content"))  # Outputs: Committed as version 2
print(vcs.revert(1))                  # Outputs: Initial Content

import requests
import json

def handle_api_error(url):
    try:
        response = requests.get(url)
        print(f"Response Code: {response.status_code}")

        data = json.loads(response.text)
        if 'error' in data:
            error_message = f"API Error: {data['error']}"
            print(error_message)
        else:
            if response.status_code == 200:
                print("Success! API response received.")
                # You can process the data here as needed.
                pass
            else:
                print(f"Request failed with status code {response.status_code}")
    except requests.exceptions.RequestException as e:
        print(f"Request failed due to: {e}")
    except json.JSONDecodeError as je:
        print("Failed to parse API response JSON")
    except KeyError as ke:
        print(f"API Error: Key 'error' missing. Response data: {data}")

