class ReportGenerator:
    def __init__(self):
        self.columns_to_sanitize = ['first_name', 'last_name', 'email']
        self column_max_length = {
            'first_name': 50,
            'last_name': 50
        }

    def sanitize_input(self, input_str):
        """Sanitize input to prevent SQL injection and XSS."""
        if not isinstance(input_str, str):
            return input_str

        # Replace special characters for SQL injection prevention
        safe_chars = {'&', '"', '`', '>', '<', '{', '}', '\\', '/', '?', ':'}
        sanitized = ''
        for char in input_str:
            if char in safe_chars:
                continue
            else:
                sanitized += '_'.join([char if c not in safe_chars else '__' 
                                    for c in str(char)])

        # HTML escaping for XSS prevention
        escaped = unquote_plus(input_str.replace('\n', ''))
        return escaped

    def fetch_user credentials(self, user_id):
        """Fetch user credentials using OAuth2."""
        url = "https://api.example.com/oauth"
        params = {
            "grant_type": "authorization_code",
            "redirect_uri": "http://localhost:8080/callback",
            "code": user_id
        }

        response = requests.request(
            "POST", url, json=params,
            headers={'Authorization': self.get_consumer_key()}
        )

        if response.status_code == 200:
            logger.info(f"User {user_id} authenticated successfully")
            return response.json()
        else:
            raise Exception(f"Authentication failed for user {user_id}")

    def process_dataset(self, csv_path):
        """Process large CSV file in chunks and sanitize data."""
        try:
            chunk_size = 10**6
            chunks = pd.read_csv(
                csv_path,
                usecols=self.columns_to_sanitize + ['status'],
                chunksize=chunk_size,
                dtype={col: str for col in self.columns_to_sanitize},
                na_values=['', 'Not Found']
            )

            processed_data = []
            for _, chunk in enumerate(chunks):
                # Replace special characters in columns
                cols_to Sanitize = [c for c in chunk.columns if c in self.columns_to_sanitize]
                for col in cols_to Sanitize:
                    chunk[col] = chunk[col].apply(lambda x: self.sanitize_input(str(x)))

                # Drop rows with missing values after sanitizing
                chunk = chunk.dropna(how='any', axis=0, subset=self.columns_to_sanitize)

                processed_data.append(chunk)

            logger.info(f"Successfully processed {len(processed_data)} chunks")
            return pd.concat(processed_data).reset_index(drop=True)

        except Exception as e:
            logger.error(f"Error processing dataset: {str(e)}")
            raise

    def generate_report(self, data):
        """Generate report with dynamic content using Jinja2."""
        try:
            context = {
                'data': data,
                'title': self.get_current_title(),
                'status': self.get_current_status()
            }

            # Replace variables with sanitized values
            template = jinja2.Template("""
                {% for item in data %}
                    <div>
                        {{ item.first_name }} {{ item.last_name }}
                        Job Title: {{ item.job_title }}
                        Status: {{ item.status }}
                    </div>
                {% endfor %}
            """)

            report_html = template.render(**context)
            return report_html

        except Exception as e:
            logger.error(f"Error generating report: {str(e)}")
            return None

    def get_current_title(self):
        """Get current report title."""
        titles = ['General Report', 'Department-wise Analysis', 'Employee Performance']
        return random.choice(titles)

    def get_current_status(self):
        """Get current status of the report."""
        statuses = ['Active', 'Pending', 'In Progress', 'Complete']
        return random.choice(statuses)

