class PaymentTransaction:
    def __init__(self, transaction_id, date, amount, payment_method):
        self.transaction_id = transaction_id
        self.date = date
        self.amount = amount
        self.payment_method = payment_method

    def log_transaction(self):
        print(f"Transaction ID: {self.transaction_id}")
        print(f"Date: {self.date}")
        print(f"Amount: {self.amount}")
        print(f"Payment Method: {self.payment_method}")

class PaymentSystem:
    def __init__(self):
        self.transactions = []

    def add_transaction(self, transaction):
        self.transactions.append(transaction)
        print("Transaction logged successfully.")

    def view_transactions(self):
        if not self.transactions:
            print("No transactions to display.")
        else:
            for i, transaction in enumerate(self.transactions, start=1):
                print(f"Transaction {i}:")
                transaction.log_transaction()
                print("\n")

def main():
    payment_system = PaymentSystem()

    while True:
        print("Payment Transaction System")
        print("1. Log a new transaction")
        print("2. View all transactions")
        print("3. Exit")

        choice = input("Enter your choice: ")

        if choice == "1":
            transaction_id = int(input("Enter the transaction ID: "))
            date = input("Enter the transaction date: ")
            amount = float(input("Enter the transaction amount: "))
            payment_method = input("Enter the payment method: ")

            payment_transaction = PaymentTransaction(transaction_id, date, amount, payment_method)
            payment_system.add_transaction(payment_transaction)

        elif choice == "2":
            payment_system.view_transactions()

        elif choice == "3":
            print("Exiting the system.")
            break

        else:
            print("Invalid choice. Please choose a valid option.")

if __name__ == "__main__":
    main()

import re

def escape_special_characters(query):
    # This pattern matches any character not alphanumeric or a space, underscore, dash, or percent sign.
    pattern = re.compile('[^A-Za-z0-9 _\-%]+')

    # If the query has special characters, replace them with their escaped versions (i.e., add a backslash before them)
    if pattern.search(query):
        return re.sub(pattern, lambda match: '\\' + match.group(), query)
    else:
        return query  # No special characters to escape, so just return the original string

def handle_special_characters(query):
    # This pattern matches any character not alphanumeric or a space, underscore, dash, percent sign, single quote, or double quotes.
    pattern = re.compile('[^A-Za-z0-9 _\-%\'\"]+')

    # Remove special characters that don't match the pattern
    return re.sub(pattern, '', query)

