import configparser
import os
from typing import Dict

class DynamicConfig:
    def __init__(self, path: str):
        self.path = path
        self.config = configparser.ConfigParser()
        self._load_config()

    def _load_config(self) -> None:
        if os.path.exists(self.path):
            self.config.read(self.path)
        else:
            raise FileNotFoundError(f"The config file {self.path} does not exist.")

    def reload_config(self) -> bool:
        try:
            self._load_config()
            return True
        except Exception as e:
            print(f"An error occurred while reloading the config: {e}")
            return False

    def get_config(self, section: str, key: str) -> str:
        if self.config.has_option(section, key):
            return self.config[section][key]
        else:
            raise ValueError(f"The config option {section}.{key} does not exist.")

# Usage example
