    print(dynamic_config.get_config("Database", "Host"))  # Should print the new value if reload is successful

def validate_input(form):
    if not all(key in form for key in ('username', 'email', 'password', 'confirm_password')):
        return False, "Missing required fields"

    # Check username length and characters
    if len(form['username']) < 4 or len(form['username']) > 20:
        return False, "Username must be between 4 to 20 characters long"
    if not form['username'].isalnum():
        return False, "Username can only contain alphanumeric characters"

    # Validate email address using a regular expression
    import re
    if not re.match(r"[^@]+@[^@]+\.[^@]+", form['email']):
        return False, "Invalid email address"

    # Check password length and match with confirm_password
    if len(form['password']) < 8:
        return False, "Password must be at least 8 characters long"
    if form['password'] != form['confirm_password']:
        return False, "Passwords do not match"

    # All checks passed
    return True, "Input is valid"

import socket
import random

def main():
    host = 'localhost'
    port = 8080

    try:
        server_key = random.getrandbits(4096)
        print("Server key generated successfully")
    except Exception as e:
        print(f"Error generating server key: {e}")
        return

    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)

    # Bind to the host and port
    try:
        s.bind((host if host != '' else '::1', port))
        s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)  # Enable reuse after close
    except socket.error as e:
        print(f"Error binding: {e}")
        return

    while True:
        try:
            conn = s.accept()
            print(f"Connected by {conn[0]}")
            data = ''
            while True:
                chunk = conn.recv(1024)
                if not chunk:
                    break
                data += chunk.decode('utf-8', errors='ignore')
            print(f"Received data from {conn[0]}: {data}")
            conn.close()
            break  # Exit after handling the connection
        except OSError as e:
            if str(e).lower().startswith('connection refused'):
                continue  # Retries accepting a new connection
            else:
                raise

    finally:
        s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 0)
        s.close()

if __name__ == '__main__':
    main()

