import os
from prometheus_client import Client, Push d

def container_resource_monitor(interval=5):
    client = Client(os.getlogin() + ':' + os.getenv('PROMETHEUS_PORT'))

    while True:
        try:
            output = os.popen('containerd client -v | cut -d " " -f 2-').read()
            metrics_data = output.strip().split('\n')

            for line in metrics_data:
                parts = line.split(': ')
                container_name = parts[0]
                stats = {str(part).strip() for part in parts[1:] if str(part).strip()}

                labels = {
                    'name': [container_name],
                    'resource_type': ['cpu', 'memory', 'swap']
                }

                for metric, value in zip(stats.keys(), stats.values()):
                    labels['metric'][0][metric] = value
                    labels['label_values'].append({'metric': metric})

                client.get('containerd/{}:{}'.format(' '.join(labels['name']), 
                            'CPU=CPU,CORES=cores,MEM=memory,SWAP=swap'), 
                            labels={'name': [container_name], 'resource_type': ['cpu', 'memory', 'swap']})
        except Exception as e:
            print(f"Error checking Prometheus: {e}")
            if not client.is_server_alive():
                break
        time.sleep(interval)

