import requests

class PaymentGatewayError(Exception):
    """Base class for all payment gateway errors"""
    pass

class InvalidCardNumberError(PaymentGatewayError):
    """Raised when the card number is invalid"""
    def __init__(self, message):
        self.message = message
        super().__init__(message)

class InsufficientFundsError(PaymentGatewayError):
    """Raised when there are insufficient funds in the account"""
    def __init__(self, amount, balance):
        self.amount = amount
        self.balance = balance
        self.message = f"Insufficient funds. Balance: {balance}"
        super().__init__(self.message)

class NetworkConnectionError(PaymentGatewayError):
    """Raised when there is a network connection error"""
    def __init__(self, message):
        self.message = message
        super().__init__(message)

def process_payment(card_number, amount, payment_gateway_url):
    try:
        # Send request to payment gateway
        response = requests.post(payment_gateway_url, json={"card_number": card_number, "amount": amount})

        # Check if the response was successful
        if response.status_code == 200:
            return True
        else:
            raise PaymentGatewayError("Payment gateway returned an error")

    except requests.exceptions.RequestException as e:
        raise NetworkConnectionError(e.__str__())

    except Exception as e:
        raise InvalidCardNumberError(f"Invalid card number: {e.__str__()}")

# Example usage
payment_gateway_url = "https://example.com/payment"
card_number = "1234567890123456"
amount = 100.0

try:
    if process_payment(card_number, amount, payment_gateway_url):
        print("Payment successful")
    else:
        raise PaymentGatewayError()
except PaymentGatewayError as e:
    print(f"Payment gateway error: {e.message}")

