def verify_activity(activity_id):
    headers = {'Content-Type': 'application/json'}
    params = {'id': activity_id}

    response = requests.get(f"{LOG_CMS_URL}/rest/activity", params=params, headers=headers)
    if response.status_code == 200:
        return response.json()
    else:
        raise Exception(f"Activity {activity_id} not found: {response.text}")

def update_activity(activity_id, new_data):
    headers = {'Content-Type': 'application/json'}
    params = {'id': activity_id}

    payload = {
        "time": datetime.now().isoformat(),
        "username": user_creds['username'],
        "event_type": new_data.get('event_type'),
        "details": new_data.get('details'),
        "status": new_data.get('status', 'Unknown')
    }

    response = requests.put(f"{LOG_CMS_URL}/rest/activity", params=params, json=payload, headers=headers)
    if response.status_code == 200:
        return True
    else:
        raise Exception(f"Failed to update activity log: {response.text}")

