    headers = {'Content-Type': 'application/json'}
    params = {}

    response = requests.get(f"{LOG_CMS_URL}/rest/activity", params=params, headers=headers)
    if response.status_code == 200:
        activity_data = response.json()
        return [activity['id'] for activity in activity_data.get('results', [])]
