def filter_data(report_data, filter_key, filter_value):
    """Filter report data by a specific key and value."""
    filtered_data = []
    for entry in report_data:
        if isinstance(entry, dict) and entry.get(filter_key) == filter_value:
            filtered_data.append(entry)
    return filtered_data

import hashlib
import hmac
import json
from typing import Dict

# This should be securely stored and never hard-coded in your source code.
SECRET_KEY = b'your-secret-key'

def verify_signature(message: str, signature: str) -> bool:
    """Verify that the data was not tampered with."""
    digest = hmac.new(SECRET_KEY, msg=message.encode('utf-8'), digestmod=hashlib.sha256).hexdigest()
    return hmac.compare_digest(signature, digest)

def aggregate_data(data: Dict[str, int], new_data: Dict[str, int]) -> None:
    """Aggregate new data into existing data."""
    for key in new_data:
        if key in data:
            data[key] += new_data[key]
        else:
            data[key] = new_data[key]

def process_streaming_data(message: Dict) -> None:
    """Process a message from the stream."""
    if 'signature' in message and 'data' in message:
        signature = message['signature']
        data = json.loads(message['data'])

        # Verify that the data was not tampered with
        if verify_signature(message['data'], signature):
            aggregate_data(streaming_data, data)
        else:
            print("Invalid message received.")
    else:
        print("Invalid message format.")

# This is where we store our aggregated data. In a real-world scenario this would be securely stored and updated periodically.
streaming_data = {}

# Example of how to process new data. In a real-world scenario this could come from a streaming source or API.
new_message = {
    'signature': hmac.new(SECRET_KEY, msg='{"key1": 5}'.encode('utf-8'), digestmod=hashlib.sha256).hexdigest(),
    'data': '{"key1": 5}'
}
process_streaming_data(new_message)

