import os
from urllib.parse import urlparse, urlunparse

# Define directories containing robots.txt files to process
directories = ['/path/to/dir1', '/path/to/dir2']

def parse_robots_file(robots_path):
    """Parse robots.txt file and return a dictionary of rules."""
    try:
        with open(robots_path, 'r') as f:
            content = f.read()
        # Example parsing: looking for Allow or Disallow directives
        rules = {}
        current_rule = None
        allowed_paths = set()
        for line in content.splitlines():
            if not line.strip() or line.startswith('Disallow:'):
                continue  # Skip empty lines and Disallow instructions
            elif 'Allow' in line:
                parts = line.split()
                rule = ' '.join(parts)
                rules[rule] = True
            else:
                allowed_paths.add(line)  # Assume this is an allowed path
        return rules, allowed_paths
    except FileNotFoundError:
        print(f"Error: robots.txt not found at {robots_path}")
        return {}, None

# Process each directory for robots.txt files
robot_rules = {}

for dir_path in directories:
    file_list = os.listdir(dir_path)
    for filename in file_list:
        if filename.endswith('.robots.txt'):
            full_path = os.path.join(dir_path, filename)
            rules, allowed_paths = parse_robots_file(full_path)
            # Update robot_rules with the current directory's rules
            for rule, value in rules.items():
                path = urlunparse(parse_robots_file(full_path)[1])
                robot_rules[path] = {'allow': True}
            if allowed_paths:
                for path in allowed_paths:
                    robot_rules[parse_robots_file(full_path)[1]]['allow'] = False

# Example check: Check if a certain path is crawlable
path_to_check = '/example/path'
if path_to_check in robot_rules.get(allowed_paths, {}):
    status = 'Not Crawlable' if not allowed else 'Crawlable'
    print(f"Path {path_to_check} is {status}")
else:
    # Handle paths that don't have explicit rules
    pass

