class Policy:
    def __init__(self):
        pass

    def evaluate(self, resource):
        raise NotImplementedError('evaluate() not implemented in subclass')


class TimeRole(Policy):
    def __init__(self, allowed_roles):
        self.allowed_roles = allowed_roles

    def evaluate(self, resource):
        return resource.user_role in self.allowed_roles


class UserRole(Policy):
    def __init__(self, allowed roles):
        # Note: Fixed a typo here from 'allowed roles' to 'allowed_roles'
        self.allowed_roles = allowed_roles

    def evaluate(self, resource):
        return resource.user_role == self.allowed_roles


class CheckTime(Policy):
    def __init__(self, threshold):
        self.threshold = threshold

    def evaluate(self, resource):
        return resource.time >= self.threshold


class CompositeAnd(Policy):
    def __init__(self, policies):
        self.policies = policies

    def evaluate(self, resource):
        for policy in self.policies:
            if not policy.evaluate(resource):
                return False
        return True


class CompositeOr(Policy):
    def __init__(self, policies):
        self.policies = policies

    def evaluate(self, resource):
        for policy in self.policies:
            if policy.evaluate(resource):
                return True
        return False


