import ipaddress
from datetime import datetime, timedelta

class Throttler:
    def __init__(self, rate=10):
        self.rate = rate
        self.clients = {}

    def is_private_ip(self, ip_str):
        try:
            return not ipaddress.ip_address(ip_str).is_private
        except ValueError:
            return False

    def get_client_id(self, ip_str):
        if '.' not in ip_str:
            raise ValueError("Invalid IP address format")
        try:
            ip = ipaddress.ip_address(ip_str)
        except ValueError:
            return None
        # Generate a unique identifier for this client's usage tracking
        return f"{ip_str}"

    def allow_request(self, current_time):
        if not self.clients:
            return True  # first request allowed

        last_client_id = list(self.clients.keys())[0]
        last_client_info = self.clients[last_client_id]

        delta_seconds = (current_time - last_client_info['last']}).total_seconds()

        if delta_seconds <= 60:  # Check within the last minute
            return False

        # Reset client info after allowing request and incrementing count
        del self.clients[last_client_id]
        new_count = 1
        self.clients[last_client_id] = {
            'last': current_time,
            'count': new_count
        }
        return True

def throttle(rate=10):
    def decorator(func):
        throttler = Throttler(rate)
        async def wrapper(*args, **kwargs):
            try:
                ip_str = args[0].split(',')[0] if isinstance(args[0], str) else str(args[0])
                client_id = throttler.get_client_id(ip_str)

                current_time = datetime.now()

                # Allow the first request
                allowed = True

                if client_id not in throttler.clients:
                    allowed = False  # should never happen due to get_client_id, but just in case

                if allowed and (current_time - throttler.clients[client_id]['last']).total_seconds() <= 60:
                    return await asyncio.sleep(1)  # Wait one minute before allowing next request
                    allowed = True  # Reset after the sleep

                response = await func(*args, **kwargs)
                return response
            except Exception as e:
                print(f"Exception occurred: {e}")
                raise
        return wrapper
    return decorator

