import hashlib

class Block:
    def __init__(self, index, previous_hash, timestamp, data, nonce=0):
        self.index = index
        self.previous_hash = previous_hash
        self.timestamp = timestamp
        self.data = data
        self.nonce = nonce

    def calculate_hash(self):
        block_string = str(self.index) + self.previous_hash + str(self.timestamp) + self.data + str(self.nonce)
        return hashlib.sha256(block_string.encode()).hexdigest()

class Blockchain:
    def __init__(self, difficulty=2):
        self.chain = [self.create_genesis_block()]
        self.difficulty = difficulty

    def create_genesis_block(self):
        return Block(0, "0", 1576739400, "Genesis Block")

    def get_latest_block(self):
        return self.chain[-1]

    def add_block(self, new_block):
        if not isinstance(new_block, Block):
            raise ValueError("Invalid block")

        new_block.previous_hash = self.get_latest_block().calculate_hash()
        new_block.timestamp = int(time.time())
        new_block.hash = new_block.calculate_hash()

        for _ in range(10):
            if new_block.calculate_hash()[:self.difficulty] == "0" * self.difficulty:
                break
            new_block.nonce += 1

    def validate_chain(self):
        for i in range(len(self.chain) - 1):
            current_block = self.chain[i]
            next_block = self.chain[i + 1]

            if current_block.hash != current_block.calculate_hash():
                return False
            if next_block.previous_hash != current_block.hash:
                return False

        return True


# Example usage
if __name__ == "__main__":
    blockchain = Blockchain()

    # Create a new block
    new_block = Block(1, blockchain.get_latest_block().hash, int(time.time()), "Transaction 1")
    blockchain.add_block(new_block)

    # Validate the chain
    print("Is the chain valid?", blockchain.validate_chain())

