import time
from datetime import datetime
from typing import Callable

def limit(requests: int = 20, reset_time: int = 60) -> Callable:
    """Decorator to implement rate limits."""
    request_count = 0
    last_reset = datetime.now()

    def decorator(func: Callable) -> Callable:
        nonlocal request_count, last_reset

        def wrapper(*args, **kwargs):
            nonlocal request_count, last_reset

            current_time = datetime.now()

            # Check if rate limit is exceeded
            if (current_time - last_reset).total_seconds() < reset_time and request_count >= requests:
                raise RateLimitExceeded(f"Rate limit reached. Last reset at {last_reset.strftime('%Y-%m-%d %H:%M:%S')}")

            # Increment request count
            request_count += 1

            try:
                result = func(*args, **kwargs)
                return result

            finally:
                pass

        wrapper.request_count = request_count
        wrapper.last_reset = last_reset

        return wrapper

    return decorator

class RateLimitExceeded(Exception):
    pass

def main():
    @limit(requests=20, reset_time=60)
    def example_api_call():
        # Simulate an API call to an AI model
        print(f"Sending request {request_count} at {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}")
        time.sleep(0.1)  # Simulate processing time

        return {"status": "success", "result": "This is a simulated response"}

    try:
        for _ in range(30):
            example_api_call()
            print(f"Completed request {_+1} successfully")

            if (datetime.now() - last_reset) >= timedelta(minutes=1):
                print("\nRate limit reached. Waiting 60 seconds...\n")

    except RateLimitExceeded as e:
        print(f"Error: {e}")

    print("All API calls completed.")

