class BackupMonitor:
    def __init__(self):
        self.jobs = {
            "backup_job_1": {
                "id": "BJ1",
                "name": "Daily Backup",
                "type": "daily",
                "last Checked": None,
                "status": "pending"
            },
            "backup_job_2": {
                "id": "BJ2",
                "name": "Weekly Backup",
                "type": "weekly",
                "last Checked": None,
                "status": "pending"
            }
        }
        self.scheduler = sched.Scheduler()
        self.current_time = datetime.now().time()

    def add_job(self, job_id, name, type_, status="pending"):
        if job_id in self.jobs:
            print(f"Job {job_id} already exists")
            return
        self.jobs[job_id] = {
            "id": job_id,
            "name": name,
            "type": type_,
            "last Checked": None,
            "status": status
        }

    def check_jobs(self):
        while True:
            current_time = datetime.now().time()
            delta = current_time - self.current_time
            if delta.total_seconds() > 0:
                elapsed_time = time.strftime("%H:%M:%S", time.gmtime(delta))
                self._update_job_statuses(elapsed_time)
                self.current_time = current_time
            os.system('python3 -m schedule.clear')
            time.sleep(60 * 60)  # Check every hour

    def _update_job_statuses(self, elapsed_time):
        for job_id in self.jobs:
            job = self.jobs[job_id]
            if not job.get("last Checked") or (time.time() - job["last Checked"]) > 3600:  # Over an hour
                self._determine_job_status(elapsed_time, job)
            job["last Checked"] = time.time()

    def _determine_job_status(self, elapsed_time, job):
        duration = elapsed_time.split(':')
        hours = int(duration[0])
        minutes = int(duration[1])
        seconds = int(duration[2])

        if job["type"] == "daily":
            if hours > 23 or (hours == 23 and minutes >= 59) or (hours == 23 and minutes == 59 and seconds >= 60):
                job["status"] = "completed"
                self._send_notification(f"Backup Job {job['id']} completed")
            elif hours < 23:
                job["status"] = "running"

        if not job.get("failed"):
            job["failed"] = False
            if minutes >= 5 or (minutes == 0 and seconds >= 60):
                job["status"] = "completed"
                self._send_notification(f"Backup Job {job['id']} completed")
            else:
                job["status"] = "pending"

    def _send_notification(self, message):
        sender = "your_email@gmail.com"
        recipient = "backup_monitor@example.com"
        subject = f"Backup Job Status: {message}"
        try:
            email_body = f"""
            <html>
              <head><title>{subject}</title></head>
              <body style="margin:0cm; padding:0cm; font-family: Arial, sans-serif;" >
                <h1 style="color: #333333;">{message}</h1>
              </body>
            </html>
            """
            server = smtplib.SMTP('smtp.example.com', 587)
            server.startover()
            server.sendmail(sender, recipient, email_body)
            server.quit()
        except Exception as e:
            print(f"Failed to send email: {e}")

