import subprocess

def get_backup_status(job_name):
    # Get the status of the backup job
    command = "sudo crontab -l | grep {}".format(job_name)
    process = subprocess.Popen(command, shell=True, stdout=subprocess.PIPE)
    output, error = process.communicate()

    # Parse the status from the output
    if "OK" in output:
        return "successful"
    elif "FAILED" in output:
        return "failed"
    else:
        return "unknown"

