# Function to check container status periodically
def check_container_status(node_name):
    try:
        node = concurnode.Node(node_name)
        if not node.isrunning():
            log.warning(f"Container {node_name} is down")
            return True
        else:
            return False
    except Exception as e:
        log.error(f"Error checking {node_name}: {e}")
        return True  # Assume degraded state

# Main loop to monitor and handle container crashes
while True:
    for node in containers:
        if check_container_status(node.name):
            log.warning(f"Container {node.name} has crashed. Attempting recovery.")
            time.sleep(5)  # Time before retrying

            try:
                node.start()  # Reboot the container
                log.info(f"Recovering: Container {node.name} is back online")
            except Exception as e:
                log.error(f"Failed to recover {node.name}: {e}")

    time.sleep(30)  # Sleep between checks

# After all containers are running normally, close them
for node in containers:
    node.stop()

