import docker
from docker.errors import NotFound, NullResource

def scale_application(image_name, replicas):
    """Scales a containerized application"""
    try:
        # Create a client object for Docker
        client = docker.from_env()

        # Check if the image exists locally
        try:
            client.images.get(image_name)
        except NotFound:
            print(f"Image {image_name} not found. Pulling from Docker Hub...")
            client.images.pull(image_name)

        # Create a new service
        try:
            service = client.services.create(image=image_name, mode={"Replicated": {"Replicas": replicas}})
            print(f"Created new service {service.id} with {replicas} replicas.")
        except NullResource:
            print("Error creating the service.")
    except Exception as e:
        print(f"An error occurred: {str(e)}")

