# Social media platforms and their respective API endpoints
social_platforms = {
    'Facebook': {'endpoint': 'https://www.facebook.com/sharer/sharer.php?u={}',
                 'params': {'title': '', 'description': ''}},
    'Twitter': {'endpoint': 'https://twitter.com/intent/tweet?text={}',
                'params': {'title': '', 'description': ''}},
    'LinkedIn': {'endpoint': 'https://www.linkedin.com/shareArticle?mini=true&url={}',
                 'params': {'title': '', 'description': ''}},
}

