    return render_template('index.html')

@app.route('/share', methods=['POST'])
def share():
    # Get the URL to be shared from the request data
    url = request.form['url']

    # Populate the title and description fields with default values
    for platform in social_platforms.values():
        if not platform['params']['title']:
            platform['params']['title'] = 'Share on {}!'.format(platform['endpoint'].split('?u=')[1])
        if not platform['params']['description']:
            platform['params']['description'] = 'Check out this awesome resource: {}'.format(url)

    # Make API calls to each social media platform
    for platform in social_platforms.values():
        import requests
        params = {**platform['params'], **{'u': url}}
        response = requests.get(platform['endpoint'].format(**params))

        # Handle any errors that might occur during the API call
        if response.status_code != 200:
            print(f"Error on {platform['endpoint']}: {response.text}")

    return redirect(url_for('index'))

