def main():
    import sys

    # Read input: each line is "ip attempt_time"
    lines = [line.strip() for line in sys.stdin]
    ipattempts = []
    for line in lines:
        if not line:
            continue
        parts = line.split()
        ip = parts[0]
        t = int(parts[1])
        ipattempts.append((ip, t))

    # Initialize variables
    last_reset_time = {}  # Maps IP to its last reset time (in seconds)
    failed_attempts = {}  # Maps IP to the number of current failed attempts since last reset

    for ip, t in ipattempts:
        if ip not in last_reset_time or t < last_reset_time[ip]:
            delta = t - last_reset_time.get(ip, 0)  # Default is 0 when not set
            if delta > 0 and delta <= 3600:  # FRESH is one hour (3600 seconds)
                failed_attempts[ip] = 0
            else:
                failed_attempts[ip] = failed_attempts.get(ip, 0) + 1

        if failed_attempts[ip] >= ABUSE:
            last_reset_time[ip] = t
            failed_attempts[ip] = 0

    # Output the results in order of processing
    for ip, t in sorted(ipattempts, key=lambda x: x[0]):
        print(f"{ip} {t}")

if __name__ == "__main__":
    ABUSE = int(input().strip())
    main()

