redis_client = Redis(host='localhost', port=6379, db=0)

def rate_limit(key: str, limit: int = 10, period: int = 60):
    """ Rate limiting decorator for Flask API endpoints """

    def decorator(func):
        @wraps(func)  # Preserve function metadata

        def wrapper(*args, **kwargs):
            current_time = time.time()

            count = 0
            last_reset_time = redis_client.hget('rate-limit', 'last_reset')

            if not last_reset_time:  # If first request after reset, set counter and timestamp
                redis_client.hset('rate-limit', key, current_time)
            else:
                count = redis_client.hget('rate-limit', key)

                if current_time - last_reset_time > period:  # If time since last reset is longer than the period, reset counter and timestamp
                    redis_client.hset('rate-limit', 'last_reset', current_time)
                    redis_client.hdel('rate-limit', key)
                elif count < limit:
                    redis_client.hincrby('rate-limit', key, 1)  # Increment counter for this key
                else:  
                    return jsonify({'error': 'Rate limit exceeded.'}), 429  # Return error if rate is limited

            return func(*args, **kwargs)
        return wrapper
    return decorator

# Example endpoint for demonstration purposes
@app.route('/api/resource', methods=['GET'])
@rate_limit('get:/api/resource')  
def get_resource():
    return jsonify({'message': 'Successful response.'}), 200

