def check_permissions(role, action):
    """Check if a user has permission to perform an action."""
    actions = {
        'create_record': {'admin': True, 'staff': True, 'user': False},
        'edit_record': {'admin': True, 'staff': True, 'user': False},
        'delete_record': {'admin': True, 'staff': False, 'user': False},
        'view_record': {'admin': True, 'staff': True, 'user': False},
    }

    return actions.get(action).get(role, False)

