    """Log an access control violation if permissions are exceeded."""
    if not check_permissions(user_role, action_name):
        error_message = f"Access denied for {user_role} with ID {user_id} attempting to {action_name} at time: {timestamp}"
        print(f"[{timestamp}] Error: {error_message}", file=sys.stderr)

