def decrypt(c, p, q):
    if p == q:
        return 0  # This case is when p equals q; decryption handled separately to avoid miscalculations due to φ(n) being (p-1)^2

    phi_n = (p - 1) * (q - 1)
    e = ...  # The public exponent 'e' should be provided or computed
    d = pow(e, -1, phi_n)

    m_int = pow(c, d, n)  # n is p*q

    return bytes(m_int).decode('utf-8')

class PriorityQueue(object):
    def __init__(self):
        self.queue = []
        self.priorities = {}

    def add(self, item, priority):
        if priority not in self.priorities:
            self.priorities[priority] = []
        self.priorities[priority].append(item)
        self.queue.append((priority, item))

    def remove(self, item):
        for priority, queue in self.priorities.items():
            if item in queue:
                queue.remove(item)
                break
        self.queue = [(priority, item) for priority, item in self.queue if item != item]

    def peek(self):
        return self.queue[0][1]

    def is_empty(self):
        return not self.queue

from collections import deque

class Queue:
    def __init__(self, max_size):
        self.queue = deque(maxlen=max_size)

    def enqueue(self, item):
        self.queue.append(item)

    def dequeue(self):
        if len(self.queue)> 0:
            return self.queue.popleft()
        else:
            print("Queue is empty")

