    """
    Translate the provided text using system's default locale or fallback to en_US.

    Args:
        text (str): The text to translate.

    Returns:
        str: Translated text.
    """
    try:
        # First, attempt to use the system's default locale
        return text.translate(locale.getdefaultlocale(text))
    except (RuntimeError, ValueError):
        # If translation fails in the default locale, use fallback options
        return text.translate(LOCALE_Fallbacks, text)

    # As a fallback, also provide English translation
    try:
        eng_trans = gettext('en_US')
        return text.translate(eng_trans)
    except (RuntimeError, ValueError):
        pass

    return text

