import json
from py加密 import Encrypt, Decrypt

# Constants
PAGINATION_KEY = 'paginated'
PAGINATION_TOKEN = 'token'
CONVERSION_KEY = 'conversionId'

class Payment Gateway:
    def __init__(self):
        self._encryption = Encrypt()
        self._decryption = Decrypt()

    def process_payment_response(self, response_data):
        try:
            # Parse the JSON response
            data = json.loads(response_data)

            if PAGINATION_KEY in data:
                pagination = data[PAGINATION_KEY]
                if PAGINATION_TOKEN in pagination:
                    tokens = pagination[PAGINATION_TOKEN]
                    transaction_id = self._decryption.decrypt(tokens[0])
                    session_id = self._decryption.decrypt(tokens[1])

                    return {
                        'transaction_id': transaction_id,
                        'session_id': session_id
                    }

            raise Exception("Invalid payment response format")

        except json.JSONDecodeError:
            raise Exception("Failed to parse payment response")

        except Exception as e:
            raise Exception(f"Error processing payment response: {str(e)}")

