from flask import Flask, request, abort
import hmac
import hashlib

app = Flask(__name__)
SECRET_KEY = 'your_secret_key' # Keep this secret!

@app.route('/webhook', methods=['POST'])
def webhook():
    if not validate_signature(request):
        abort(401)

    data = request.json
    process_data(data)

    return 'Success', 200

def validate_signature(req):
    signature = req.headers.get('X-Hub-Signature')
    if not signature:
        return False

    sha_name, signature = signature.split('=')
    if sha_name != 'sha1':
        return False

    mac = hmac.new(SECRET_KEY.encode(), msg=req.data, digestmod=hashlib.sha1)
    return hmac.compare_digest(str(mac.hexdigest()), str(signature))

