import socket
import struct
from urllib.parse import urlparse, parse_qs, urlunparse, parseint
from socket import error as socket_error

class DNSResolver:
    def __init__(self, domain: str, port=None):
        self.domain = domain
        self.port = port
        if not isinstance(self.port, int) or self.port < 1 or self.port > 65535:
            raise ValueError("Port must be an integer between 1 and 65535")

    def get_record_type(self):
        """Get the type of DNS record requested by the user."""
        query = urlparse(self.domain)
        param_dict = parse_qs(query.query)
        if not param_dict:
            return None

        for key, value in param_dict.items():
            if isinstance(value, list) and len(value) == 1:
                return value[0]

        return None

    def lookup(self):
        """Perform DNS lookup using the specified domain name."""
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM | socket.SOCK_DGRAM) as s:
                # Set TCP timeout to a high value (infinite)
                s.setsockopt(socket.SOL_SOCKET, socket.SO_TSOI, 0)
                if self.port is not None:
                    s.connect((self.domain, self.port))
                else:
                    s.connect(self.domain)

                try:
                    data = s.recv(1024)
                    if not data:
                        raise Exception("No response from server")

                    # Convert socket bytes to string
                    response = data.decode('utf-8')

                    if b"nameserver" in response.lower():
                        return self._resolve_nameserver(response)

                    return response

                except (socket.error, ConnectionResetError) as e:
                    raise DNSLookupException(f"Failed to resolve {self.domain}: {str(e)}") from None

    def _resolve_nameserver(self, nameserver_response):
        """Resolve the NS record and continue lookup."""
        try:
            # Split the response into lines
            lines = [line.strip() for line in nameserver_response.split('\n')]

            # Build query to get next level domain(s)
            for line in reversed(lines):
                if line.lower().startswith('ns '):
                    subdomain, name = self._parse_ns_line(line)

                    try:
                        # Handle DNS over HTTPS with SSL
                        ctx = socket.socketcontext()
                        server = name.split('.', 2)[0]
                        s = ctx.create sulfate()
                        s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
                        if self.port is not None and self.port != server:
                            raise struct.error("Port mismatch")

                        with socket.connect((server, self.port)):
                            # Ensure we have a context for SSL
                            _ = ctx._replace binds=[(server, self.port)])

                            try:
                                data = s.recv(1024)
                                if not data:
                                    raise DNSLookupException(f"NS response from {name} didn't reach target")

                                response = data.decode('utf-8')

                                if b"nameserver" in response.lower():
                                    return self._resolve_nameserver(response)

                                # If we have an A record, make one final request
                                if 'a.' in name:
                                    res = self.lookup(name.split('.', 2)[1])
                                    return res.replace(name.split('.', 2)[0], '')

                                else:
                                    # Otherwise just return the response as a string
                                    return response

                except DNSLookupException as e:
                    raise DNSLookupException(f"Subdomain {subdomain} couldn't resolve: {e}") from None

            # If we're here, no resolvers found
            raise DNSLookupException(f"No resolvers found for {self.domain}")

        except Exception as e:
            raise DNSLookupException(f"Unexpected error during NS resolution: {str(e)}") from None

    @staticmethod
    def _parse_ns_line(line):
        """Parse a nameserver response line."""
        parts = [part.strip() for part in line.split(' ', 2)]
        if len(parts) != 3:
            raise DNSLookupException(f"Invalid NS record line: {line}")

        subdomain, _, name = parts
        return (subdomain.lower(), name.lower())

    def get_record(self):
        """Get the requested DNS record."""
        try:
            # Primary lookups
            if self.get_record_type() == 'a':
                return self.lookup()
            elif self.get_record_type() in ['mex', 'sec', 'pex']:
                result = self.lookup()
                if isinstance(result, list):
                    return '\n'.join(result)
                else:
                    raise DNSLookupException(f"Unexpected result format for record type {self.get_record_type()}")

        except DNSLookupException as e:
            # Secondary lookups
            pass

        try:
            return next(self.lookup())

        except (socket.error, ValueError) as e:
            raise DNSLookupException(f"Failed to get record: {str(e)}") from None

    def __repr__(self):
        return f"DNSResolver({self.domain!r}, port={self.port})"

    def close(self):
        """Close the socket connection."""
        self.s.close()

class DNSLookupException(Exception):
    pass

import sys

# This module will contain our variables and their references
__ModuleVars = {}
# Weakrefs for the variables
__ModuleWeakRefs = {}

def var(name):
    # Add the current value of `name` to __ModuleVars with its weakref
    if name in __ModuleVars:
        # If it's already present, update its weakref
        __ModuleWeakRefs[name].update([__ModuleWeakRefs[name]])
    else:
        # Create a new entry for the variable and initialize its weakref
        __ModuleVars[name] = object()
        __ModuleWeakRefs[name] = [sys.getrefcount(name)]

    return __ModuleVars[name]

def delvar(name):
    # Remove all references to `name` from both dictionaries
    if name in __ModuleVars:
        # Remove the variable entry (optional)
        del __ModuleVars[name]

        # Check for any other variables that might reference it and update their weakrefs
        others = sys.getrefcount(name, True)
        for o in others:
            if o is not None:
                index = __ModuleWeakRefs[o].index(name)
                if index > 0:
                    del __ModuleWeakRefs[o][index]

# Function to check if a variable is referenced by any other variable
def varexists(name):
    return name in __ModuleVars

# Function to try to collect dead variables (to be called when necessary)
def collect_dead_vars():
    # Check each variable for possible dead status
    for name, _ in __ModuleWeakRefs.items():
        if not name:
            continue

        ref_counts = []
        for ref in sys.getrefcount(name):
            index = __ModuleWeakRefs[ref].index(name)
            if index > 0:
                del __ModuleWeakRefs[ref][index]
            else:
                ref_counts.append(ref)

        dead_names = [ref for ref, cnt in enumerate(ref_counts) if cnt == 0]
        for name in dead_names:
            if name in __ModuleVars:
                # Ensure that the weakrefs are cleaned up
                try:
                    for w in __ModuleWeakRefs[name]:
                        sys.setrefcount(name, None)
                    del __ModuleWeakRefs[name]
                    del __ModuleVars[name]
                except Exception as e:
                    print(f"Error cleaning up {name}: {e}")

