import cv2
import os

def validate_input(filepath):
    if not os.path.exists(filepath):
        raise Exception("The file does not exist")

    if not filepath.lower().endswith(('.mp4', '.avi')):
        raise Exception("Invalid file format. Only mp4 and avi are supported.")

def stream_video(filepath):
    validate_input(filepath)
    cap = cv2.VideoCapture(filepath)

    if not cap.isOpened():
        print("Error opening video file")
        return

    while True:
        ret, frame = cap.read()

        if not ret:
            print("Can't receive frame (stream end?). Exiting ...")
            break

        cv2.imshow('frame', frame)
        if cv2.waitKey(1) == ord('q'):
            break
    cap.release()
    cv2.destroyAllWindows()

# Usage
stream_video('/path/to/your/video.mp4')

def is_valid_credit_card(s):
    reversed_s = s[::-1]
    total = 0
    for i, c in enumerate(reversed_s):
        digit = int(c)
        if i % 2 == 1:
            doubled = digit * 2
            total += (doubled // 10) + (doubled % 10)
        else:
            total += digit
    return total % 10 == 0

