from abc import ABC, abstractmethod

class Subject(ABC):
    def __init__(self, name):
        self.name = name

    @abstractmethod
    def get_attributes(self):
        pass


class Resource(ABC):
    def __init__(self, name):
        self.name = name
        self.policy = {}

    @abstractmethod
    def check_access(self, subject, action):
        pass

    def add_policy_rule(self, resource, attribute, allowed_values):
        """
        Add a policy rule to the resource's policy.

        Args:
            resource (str): The resource that this rule applies to.
            attribute (str): The attribute to check against the requestor.
            allowed_values (list): A list of allowed values for the attribute.
        """
        if resource not in self.policy:
            self.policy[resource] = {}
        self.policy[resource][attribute] = allowed_values


class Action(ABC):
    def __init__(self, name):
        self.name = name

    @abstractmethod
    def check_access(self, subject, resource):
        pass


class UserSubject(Subject):
    def __init__(self, name, attributes):
        super().__init__(name)
        self.attributes = attributes

    def get_attributes(self):
        return self.attributes


class PolicyCheck:
    @staticmethod
    def check_access(subject, action, resource):
        """
        Check if a subject has access to a resource based on the ABAC policy.

        Args:
            subject (UserSubject): The subject that is requesting access.
            action (Action): The action being requested.
            resource (Resource): The resource that the requestor wants to access.

        Returns:
            bool: True if the requestor has access, False otherwise.
        """
        for attribute, allowed_values in resource.policy.get(subject.name, {}).items():
            subject_attributes = getattr(subject, "attributes", None)
            if subject_attributes and subject_attributes[attribute] in allowed_values:
                return True
        return False


# Example usage:

class CreateResource(Action):
    def check_access(self, subject, resource):
        return PolicyCheck.check_access(subject, self, resource)


class ReadResource(Action):
    def check_access(self, subject, resource):
        return PolicyCheck.check_access(subject, self, resource)


class UpdateResource(Action):
    def check_access(self, subject, resource):
        return PolicyCheck.check_access(subject, self, resource)


# Create subjects and resources
user1 = UserSubject("John Doe", {"department": ["Sales"], "job title": ["Manager"]})
resource = Resource("Database")

# Add policy rules to the resource
resource.add_policy_rule("Database", "department", ["Sales"])
resource.add_policy_rule("Database", "job title", ["Manager"])

action_create = CreateResource()
action_read = ReadResource()
action_update = UpdateResource()

print(PolicyCheck.check_access(user1, action_create, resource))  # True
print(PolicyCheck.check_access(user1, action_read, resource))   # True
print(PolicyCheck.check_access(user1, action_update, resource)) # False

# Create another subject with different attributes
user2 = UserSubject("Jane Doe", {"department": ["Marketing"], "job title": ["Employee"]})

print(PolicyCheck.check_access(user2, action_create, resource))  # True
print(PolicyCheck.check_access(user2, action_read, resource))   # True
print(PolicyCheck.check_access(user2, action_update, resource)) # False

