from flask import Flask, request, jsonify
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.backends import default_backend
from cryptography.fernet import Fernet

app = Flask(__name__)

# Generate asymmetric keys for each container
container1_private_key = serialization.load_pem_private_key(
    open('container1_private_key.pem', 'rb').read(),
    password=None,
    backend=default_backend()
)
container2_public_key = serialization.load_pem_public_key(
    open('container2_public_key.pem', 'rb').read(),
    backend=default_backend()
)

# Define a function to encrypt data using the recipient's public key
def encrypt(data, recipient):
    cipher = Fernet(container1_private_key.encrypt(recipient.public_key))
    return cipher.encrypt(data).decode('utf-8')

# Define a function to decrypt data using the sender's private key
def decrypt(data, sender):
    cipher = Fernet(container2_private_key.decrypt(sender.public_key))
    return cipher.decrypt(data).decode('utf-8')

# Define a function to sign data using the sender's private key
def sign(data, sender):
    signature = container1_private_key.sign(data)
    return signature.decode('utf-8')

# Define a function to verify the signature of received data
def verify(data, sender):
    try:
        sender.public_key.verify(data, signature)
        return True
    except ValueError:
        return False

@app.route('/communicate', methods=['POST'])
def communicate():
    # Get the data and recipient from the request body
    data = request.get_json()['data']
    recipient = request.get_json()['recipient']

    # Encrypt the data using the recipient's public key
    encrypted_data = encrypt(data, recipient)

    # Sign the encrypted data using the sender's private key
    signed_encrypted_data = sign(encrypted_data, container1_private_key)

    # Send the signed and encrypted data back to the client
    return jsonify({'signed_encrypted_data': signed_encrypted_data})

