import random
import string
from getpass import getpass

class User:
    def __init__(self, username, password):
        self.username = username
        self.password = password
        self.mfa_token = None

# Simulated database of users
users = {}

def register():
    print('Registration')
    while True:
        username = input("Enter your new username: ")
        if username in users:
            print("Sorry, that username is already taken.")
        else:
            break

    password = getpass("Enter your new password: ") #getpass hides the user's input
    confirm_password = getpass("Confirm your new password: ")

    if password == confirm_password:
        users[username] = User(username, password)
        print('User created successfully.')
    else:
        print('Passwords do not match. Please try again.')

def login():
    print('Login')
    username = input("Enter your username: ")
    if username in users:
        # If the user has set up MFA, request token
        if users[username].mfa_token:
            while True:
                mfa_code = getpass("Enter your MFA code: ")
                if mfa_code == users[username].mfa_token:
                    print('Login successful!')
                    break
                else:
                    print('Incorrect code. Please try again.')
        # If the user has not set up MFA, proceed directly 
        else:
            password = getpass("Enter your password: ")
            if password == users[username].password:
                print('Login successful!')
            else:
                print('Incorrect username or password. Please try again.')
    else:
        print('User not found. Please register first.')

def setup_mfa():
    username = input("Enter your username: ")
    if username in users:
        # Generate a random code for MFA token
        mfa_token = ''.join(random.choices(string.digits, k=6))
        users[username].mfa_token = mfa_token
        print('MFA set up successfully! Your code is:', mfa_token)
    else:
        print('User not found. Please register first.') 

def main():
    while True:
        action = input("Enter 'register' to create a new account, 'login' to log in, or 'setup MFA' to set up multi-factor authentication (or type 'exit' to quit): ")
        if action == "register":
            register()
        elif action == "login":
            login()
        elif action == "setup MFA":
            setup_mfa()
        elif action == "exit":
            break
        else:
            print("Invalid command. Please try again.")  

if __name__ == '__main__':
    main()

