import requests

def send_http_request(url, method='GET', data=None, headers=None):
    """
    Sends an HTTP request to the specified URL.

    Args:
        url (str): The URL of the server to connect to.
        method (str, optional): The HTTP method to use. Defaults to 'GET'.
        data (dict, optional): A dictionary containing the data to send in the body of the request. Defaults to None.
        headers (dict, optional): A dictionary containing the headers for the request. Defaults to None.

    Returns:
        requests.Response: The response from the server.
    """
    try:
        if method.upper() == 'GET':
            return requests.get(url, params=data, headers=headers)
        elif method.upper() == 'POST':
            return requests.post(url, data=data, headers=headers)
        elif method.upper() == 'PUT':
            return requests.put(url, data=data, headers=headers)
        elif method.upper() == 'DELETE':
            return requests.delete(url, data=data, headers=headers)
        else:
            raise ValueError("Invalid HTTP method")
    except requests.exceptions.RequestException as e:
        print(f"An error occurred: {e}")
        return None

