from flask import Flask, request
from schedule import Scheduler
import threading
import time

app = Flask(__name__)
scheduler = Scheduler()

def job_func():
    print("Running job")
    # Your job code here. This is just a placeholder

@app.route('/schedule', methods=['POST'])
def schedule_job():
    data = request.get_json()  # Get the json payload from the POST request

    if 'time' not in data:
        return {"error": "Missing 'time' field"}, 400

    try:
        job_time = time.strptime(data['time'], "%Y-%m-%d %H:%M")
    except ValueError as e:
        return {"error": str(e)}, 400

    # Check for overlapping jobs and remove if needed
    job_to_remove = None
    for job in scheduler.jobs:
        if time.mktime(job.last_run) == time.mktime(job_time):
            job_to_remove = job
            break

    if job_to_remove is not None:
        print("Removing overlapping job")
        scheduler.cancel_job(job_to_remove)

    # Schedule the new job
    job = scheduler.every().day.at(data['time']).do(job_func)
    print("Scheduled a new job at:", data['time'])

    return {"message": "Job scheduled successfully"}, 201

def run_scheduler():
    while True:
        scheduler.run_pending()
        time.sleep(1)

if __name__ == '__main__':
    threading.Thread(target=run_scheduler).start()
    app.run(debug=True, use_reloader=False)  # disable reloader to avoid a second execution of run_scheduler

