import multiprocessing as mp
import time

def send_message(queue):
    try:
        while True:
            message = f"Message from main: {time.time()}"
            queue.put(message)
            print(f"Sent message: {message}")
            time.sleep(1)  # Wait before sending the next message to avoid overwhelming the worker)
    except Exception as e:
        print(f"Error sending messages: {e}")

def receive_message(queue):
    try:
        while True:
            try:
                message = queue.get(timeout=0.1)  # Get a message from the queue
                print(f"Received message: {message}")
            except mp.Empty:
                time.sleep(0.1)  # Wait if there's no message available
    except KeyboardInterrupt:
        print("\nShutting down processes...")
        break

def main():
    try:
        send_queue = mp.Queue()
        recv_queue = mp.Queue()

        worker = mp.Process(target=receive_message, args=(recv_queue,))
        worker.start()

        # Send messages from the main process to the worker
        for i in range(5):
            message = f"Message #{i}: Hello from sender #{i}"
            send_queue.put(message)

        print("Messages have been sent to the worker process.")

    except Exception as e:
        print(f"Error initializing processes: {e}")

if __name__ == "__main__":
    main()

