def check_cloud_service_health():
    """
    Checks if the cloud service is operational and handles outages gracefully.
    """
    base_url = os.environ.get('CLOUD_SERVICE_BASE_URL', 'http://localhost:8080')
    region = os.environ.get('CLOUD_SERVICE_REGION', 'us-east-1')
    availability_zone = os.environ.get('CLOUD_SERVICE_AVAILABILITY_ZONE', None)

    try:
        params = {
            'region': region,
            'availability_zone': availability_zone
        }
        response = requests.get(f"{base_url}/cloudservicehealth", params=params, timeout=30)
        if response.status_code != 200:
            return False

        last_response_time = datetime.now()
        logging.info(f"Cloud service is currently operational. Last check at {last_response_time}")
        return True

    except requests.exceptions.RequestException as e:
        current_time = datetime.now()
        duration = (current_time - last_response_time).total_seconds() if 'last_response_time' in locals() else 0
        duration_str = f" (approximately {duration:.2f}s)"

        if response is None:
            status = "Unknown"
        elif response.status_code == 503:
            status = "Transient"
        else:
            status = "Down"

        message = (
            f"Cloud service health check failed: {e} {status}{duration_str}. "
            f"Retries in {os.environ.get('CLOUD_SERVICE_RETRY_DELAY', '10s')} seconds. "
            f"Trying backup region: {os.environ.get('CLOUD_SERVICE_BACKUP_REGION', None)}"
        )

        send_notification(message)
        logging.info(f"Cloud service health check failed at {current_time}. Response: {e} {status}{duration_str}")

        if os.environ.get('CLOUD_SERVICE_BACKUP_REGION') and os.environ.get('CLOUD_SERVICE_BACKUP ZONE'):
            logging.info("Switching to backup region for recovery efforts.")
            try:
                response_backup = requests.get(
                    f"{base_url}/cloudservicehealth",
                    params={
                        'region': os.environ['CLOUD_SERVICE_BACKUP_REGION'],
                        'availability_zone': os.environ['CLOUD_SERVICE_BACKUP_ZONE']
                    }
                )
                if response_backup.status_code == 200:
                    logging.info("Switched to backup region successfully.")
            except requests.exceptions.RequestException:
                pass

        return False

def send_notification(message):
    try:
        from twilio.twimit import TwimitClient
        client = TwimitClient(
            account_sid=os.environ.get('TWILIO_ACCOUNT_SID'),
            auth_token=os.environ.get('TWILIO_AUTH_TOKEN')
        )
        message = f"Cloud Service Health Alert: {message}"
        if 'push' in os.environ and os.environ['push']:
            client.push(message)
        elif 'email' in os.environ and os.environ['email']:
            client.sendEmail(
                to=os.environ.get('TWILIO"To}),
                from_="Twilio",
                subject="Cloud Service Health Alert",
                body=message
            )

    except Exception as e:
        logging.error(f"Failed to send notification: {e}")

