import docker
from flask import Flask, request

app = Flask(__name__)
client = docker.DockerClient(base_url='unix://var/run/docker.sock')

@app.route('/deploy', methods=['POST'])
def deploy():
    data = request.get_json()

    if 'version' not in data:
        return {'error': 'Missing version'}, 400

    service_name = f"app_{data['version']}"

    try:
        image = client.images.pull('my-registry/app', tag=data['version'])

        # Create a new service with the new image and desired scale
        client.services.create(image, name=service_name, mode='replicated', replicas=2)
    except docker.errors.ImageNotFound as e:
        return {'error': str(e)}, 404

    # Remove old services if exists
    remove_old_services()

    return {'message': 'Deployment successful'}, 201

def remove_old_services():
    for service in client.services.list():
        if 'app' in service.name and not service.tasks():
            service.remove()

import os
import json

def load_config_files():
    home_dir = os.path.expanduser("~")
    config_path = os.path.join(os.path.expandvars(home_dir), "config", "*")

    config_dict = {}

    try:
        for file in os.listdir(config_path):
            config_file = os.path.join(config_path, file)
            if os.path.isfile(config_file):
                with open(config_file, 'r') as f:
                    content = f.read().strip()
                    lines = [line for line in content.split('=') if line.strip() != '']

                    for key, value in map(int, lines):
                        config_dict[f"{key}"] = value
    except Exception as e:
        print(f"An error occurred while loading configuration files: {e}")
        return

    # Optional: Print loaded configurations for verification
    print("Configurations loaded:")
    for key, value in config_dict.items():
        print(f"{key}: {value}")

load_config_files()

