import requests
from requests.exceptions import HTTPError, Timeout
import logging

class APIFallback:
    def __init__(self):
        self.endpoints = [
            {'method': 'get', 'url': 'https://api.example.com/data', 'headers': {'Authorization': f'Bearer {self.generate_token()}'}},
            {'method': 'post', 'url': 'https://api.example.com/update', 'headers': {'Authorization': f'Bearer {self.generate_token()}'}}
        ]
        self.max_retries = 3
        self retriable_errors = (requests.exceptions.Timeout, HTTPError)
        self retrial_wait_min = 1
        self.retrial_wait_max = 30

    def generate_token(self):
        import random
        return ''.join(random.ascii_letters + random.digits)

    async def fetch_data(self, params=None):
        retries_left = self.max_retries
        for endpoint in self.endpoints:
            method = endpoint['method']
            url = endpoint['url']
            headers = endpoint['headers'].copy()
            headers.update(params or {})

            try:
                if method == 'get':
                    response = await requests.get(url, params=params, headers=headers, timeout=10)
                elif method == 'post':
                    response = await requests.post(url, params=params, headers=headers, timeout=10)
                else:
                    raise ValueError(f"Unsupported HTTP method: {method}")

                if response.status_code != 200:
                    raise HTTPError(f"API returned status code {response.status_code}", response=response)

                return response.json()
            except Exception as e:
                if isinstance(e, self.retriable_errors):
                    if retries_left > 0:
                        await self._retries waiting for the correct duration
                        retries_left -=1
                    else:
                        logging.error(f"Failed to fetch data from {url}: {str(e)}")
                        raise
                else:
                    logging.error(f"Failed to fetch data from {url}: {str(e)} after {retries_left} attempts")
                    if retries_left <= 0 or not self.endpoints:
                        raise HTTPError("All fallback endpoints failed")

    async def _retries waiting(self):
        wait = random.uniform(self.retrial_wait_min, self.retrial_wait_max)
        logging.info(f"Waiting {wait:.2f} seconds before retry")
        await requests sleep(wait)

async def main():
    api_fallback = APIFallback()
    try:
        data = await api_fallback.fetch_data({'parameter': 'value'})
        print("Successfully fetched data:", data)
    except HTTPError as e:
        print(f"HTTP Error occurred: {str(e)}")
    except Exception as e:
        print(f"Unexpected error occurred: {str(e)}")

if __name__ == "__main__":
    import asyncio
    asyncio.run(main())

