import requests
import time

class WebhookRetry:
    def __init__(self, url, max_retries=5, retry_delay=1):
        self.url = url
        self.max_retries = max_retries
        self.retry_delay = retry_delay

    def send_request(self):
        try:
            response = requests.get(self.url)
            if response.status_code == 200:
                print("Webhook delivered successfully")
                return True
            else:
                print(f"Failed to deliver webhook with status code {response.status_code}")
                return False
        except requests.exceptions.RequestException as e:
            print(f"Error occurred while sending request: {e}")
            return False

    def retry(self):
        for i in range(self.max_retries):
            if self.send_request():
                break
            else:
                time.sleep(self.retry_delay)
        if not self.send_request():
            raise Exception("Failed to deliver webhook after max retries")

# Example usage:
url = "https://example.com/webhook"
retryer = WebhookRetry(url, 3, 2) #max_retries:3, retry_delay:2
try:
    retryer.retry()
except Exception as e:
    print(e)

def convert_currency(amount_str, from_currency, to_currency):
    try:
        # Convert the input string amount to a float for calculation
        amount = float(amount_str)

        if from_currency not in conversion_rates or to_currency not in conversion_rates:
            raise ValueError("Invalid currency code")

        current_rate = conversion_rates[from_currency]
        target_rate = conversion_rates[to_currency]

        # Calculate the exchange rate. For multi-step conversions, calculate each step.
        exchange_rate = 1
        if from_currency != to_currency:
            for curr in to_currency.split('-'):
                if curr not in conversion_rates:
                    raise ValueError(f"Conversion path includes an invalid currency: {curr}")
                exchange_rate *= conversion_rates[curr]

        converted_amount = amount * exchange_rate

        # Round the result appropriately (e.g., 2 decimal places)
        return round(converted_amount, 2)
    except Exception as e:
        print(f"Error in currency conversion: {str(e)}")
        raise

