def serialize(obj):
    processed = {}

    obj_type = type(obj)
    has_instance_dict = hasattr(obj_type, '__dict__')

    if has_instance_dict:
        data = dict(obj.__dict__)
        name = obj_type.__name__
        module = getattr(obj_type, '__module__', None)
        processed = {
            '_name': name,
            '_dict': data.copy(),
            '_module': module
        }
    else:
        # For objects without __dict__ or other cases, reflectively get attributes
        for attr_name in dir(obj):
            try:
                value = getattr(obj, attr_name)
                processed[attr_name] = value
            except Exception as e:
                pass  # Ignore exceptions when getting attribute

    return processed

import time
from threading import Thread
from collections import defaultdict

class EmailRateLimiter(object):
    def __init__(self, tokens_per_minute=5):
        self.rate = tokens_per_minute
        self.tokens = defaultdict(int)
        self.last_check = time.time()
        Thread(target=self._fill_tokens).start()

    def _fill_tokens(self):
        while True:
            now = time.time()
            delta_seconds = now - self.last_check
            self.last_check = now

            for email in self.tokens:
                self.tokens[email] += delta_seconds * (self.rate / 60)
                if self.tokens[email] > self.rate:
                    self.tokens[email] = self.rate

            time.sleep(1)

    def can_send_email(self, email):
        if self.tokens[email] >= 1:
            self.tokens[email] -= 1
            return True
        else:
            return False

