import hashlib
import time

class Block:
    def __init__(self, index, previous_hash, timestamp, data, hash):
        self.index = index
        self.previous_hash = previous_hash
        self.timestamp = timestamp
        self.data = data
        self.hash = hash

def calculate_hash(index, previous_hash, timestamp, data):
    value = str(index) + str(previous_hash) + str(timestamp) + str(data)
    return hashlib.sha256(value.encode('utf-8')).hexdigest()

def create_genesis_block():
    return Block(0, "0", int(time.time()), "Genesis Block", calculate_hash(0, "0", int(time.time()), "Genesis Block"))

def create_new_block(previous_block, data):
    index = previous_block.index + 1
    timestamp = int(time.time())
    hash = calculate_hash(index, previous_block.hash, timestamp, data)
    return Block(index, previous_block.hash, timestamp, data, hash)

def is_chain_valid(chain):
    for i in range(1, len(chain)):
        current_block = chain[i]
        previous_block = chain[i - 1]

        if current_block.hash != calculate_hash(current_block.index, current_block.previous_hash, current_block.timestamp, current_block.data):
            return False

        if current_block.previous_hash != previous_block.hash:
            return False
    return True

# Testing the functions
blockchain = [create_genesis_block()]
previous_block = blockchain[0]

for i in range(1, 256): # creating a chain of 256 blocks for testing
    new_block_data = "Block #{} has been added to the blockchain!".format(i)
    new_block = create_new_block(previous_block, new_block_data)
    blockchain.append(new_block)
    previous_block = new_block

print("Is the Blockchain valid? {}".format(is_chain_valid(blockchain)))

import subprocess
from pip import Package

def get_dependencies():
    """Get list of installed packages and their versions."""
    result = subprocess.run(
        ['pip', 'list', '--format=pipe'],
        text=True,
        check=False
    )
    return result.stdout.splitlines()

def update_dependencies(expected_versions):
    """Update packages that are outdated or can be upgraded."""
    for package in get_dependencies():
        if package.startswith('package=='):
            package_name = package.split('==')[0]
            current_version = package.split('==')[1].strip()
            expected_version = expected_versions.get(package_name, None)

            if not expected_version:
                print(f"Warning: No expected version found for {package_name}. Skipping update.")
                continue

            if current_version < expected_version:
                try:
                    result = subprocess.run(
                        ['pip', 'install', '--upgrade', package_name],
                        text=True,
                        check=False
                    )
                    if result.returncode == 0 or result.stdout.find(' upgraded') != -1:
                        print(f"Updated {package_name} from {current_version} to {expected_version}")
                    else:
                        print(f"Failed to update {package_name}.")
                except Exception as e:
                    print(f"Error updating {package_name}: {str(e)}")
            elif result.returncode == 0 or result.stdout.find(' upgraded') != -1:
                continue

import pipreqs
from licensefinder import LicenseFinder

def get_licensed_packages(package_list, approved_licenses):
    licensed_packages = []
    for package in package_list:
        found = False
        for approved_license in approved_licenses:
            if LicenseFinder().find_package_license(package) == approved_license:
                licensed_packages.append(package)
                found = True
                break
        if not found:
            print(f"{package} has an unapproved license. Skipping...")
    return licensed_packages

