    package_list = pipreqs.generate_requirements("requirements.txt")
    approved_licenses = ["MIT", "Apache-2.0"]
    licensed_packages = get_licensed_packages(package_list, approved_licenses)

    with open("requirements.txt", "w") as f:
        for package in licensed_packages:
            f.write(f"pip install {package}\n")

if __name__ == "__main__":
