import psutil
import time
from datetime import datetime

def monitor_cron_jobs():
    # Threshold in seconds
    MAX_DURATION = 3600

    for process in psutil.process_iter(['pid', 'name', 'create_time']):
        if process.info['name'] == 'CRON' or process.info['name'] == 'cron':
            continue
        parent = psutil.Process(process.info['ppid'])
        if parent.info['name'] == 'CRON' or parent.info['name'] == 'cron':
            start_time = datetime.fromtimestamp(process.info['create_time'])
            current_time = datetime.now()
            duration = (current_time - start_time).total_seconds()

            if duration > MAX_DURATION:
                print(f"Alert! Cron job {process.info['pid']} has been running for more than {MAX_DURATION} seconds.")
            else:
                print(f"Cron job {process.info['pid']} is running normally.")

if __name__ == "__main__":
    while True:
        monitor_cron_jobs()
        time.sleep(60) # Check every minute

class Data:
    def __init__(self, id, name, age, city):
        self.id = id
        self.name = name
        self.age = age
        self.city = city

class SearchEngine:
    def __init__(self):
        self.data = []

    def add_data(self, data):
        """Add new data to the search engine."""
        self.data.append(data)

    def search(self, filters=None):
        """
        Search for data based on multiple filters.

        Args:
            filters (dict): A dictionary where keys are filter names and values are filter values.
        Returns:
            list: List of Data objects that match the given filters.
        """
        result = self.data
        if filters is not None:
            for key, value in filters.items():
                if hasattr(self.data[0], key):
                    attribute_name = f"_{key}_"
                    for item in self.data:
                        attr_value = getattr(item, attribute_name + key)
                        if attr_value != value:
                            result = [item for item in result if hasattr(item, attribute_name + key) and getattr(item, attribute_name + key) == value]
        return result

# Example usage
search_engine = SearchEngine()

# Add data to the search engine
search_engine.add_data(Data(1, "John Doe", 30, "New York"))
search_engine.add_data(Data(2, "Jane Smith", 25, "Chicago"))
search_engine.add_data(Data(3, "Bob Johnson", 35, "Los Angeles"))

# Search by multiple filters
filters = {"age": 30, "city": "New York"}
result = search_engine.search(filters)

