import resource
import sys

class Tenant:
    def __init__(self, name, cpu_limit=None, memory_limit=None):
        self.name = name
        self.cpu_limit = cpu_limit
        self.memory_limit = memory_limit

def set_resource_limits(tenant):
    if tenant.cpu_limit is not None:
        # Set CPU limit in seconds
        resource.setrlimit(resource.RLIMIT_CPU, (tenant.cpu_limit, tenant.cpu_limit))

    if tenant.memory_limit is not None:
        # Set memory limit in bytes
        resource.setrlimit(resource.RLIMIT_AS, (tenant.memory_limit, tenant.memory_limit))

def main():
    # Define tenants with their respective resource limits
    tenants = [Tenant("Tenant1", cpu_limit=5, memory_limit=5*1024*1024),  # 5 seconds CPU and 5MB Memory
               Tenant("Tenant2", cpu_limit=3, memory_limit=3*1024*1024)]   # 3 seconds CPU and 3MB Memory

    for tenant in tenants:
        set_resource_limits(tenant)

        try:
            print("Running tasks for", tenant.name)
            # Your task goes here

        except ValueError as ve:
            print("Tenant exceeded resource limit:", str(ve))

if __name__ == "__main__":
    main()

