from flask import Flask, make_response
from functools import wraps

app = Flask(__name__)

# Define your valid credentials here (for simplicity, using a hardcoded dict)
VALID_CREDENTIALS = {
    "username1": "password1",
    "username2": "password2"
}

def check_auth(username, password):
    """This function is called to check if a username / password combination is valid."""
    return username in VALID_CREDENTIALS and VALID_CREDENTIALS.get(username) == password

def authenticate():
    """Sends a 401 response that enables basic auth"""
    return make_response('Could not verify your login!', 401, {'WWW-Authenticate': 'Basic realm="Login required!"'})

def requires_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth = request.authorization
        if not auth or not check_auth(auth.username, auth.password):
            return authenticate()
        return f(*args, **kwargs)
    return decorated

@app.route('/secret-page')
@requires_auth
def secret_page():
    return 'This is a secret page!'

if __name__ == '__main__':
    app.run()

import requests
from time import sleep
import logging

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

def secure_logout():
    try:
        # Initial authentication token request
        logger.info("Initializing token for logout")
        response = requests.post('http://localhost:8080/api/auth/token')
        if response.status_code != 200:
            raise ValueError(f"Failed to get initial token. Status code: {response.status_code}")

        data = response.json()
        access_token = data.get('access_token')
        refresh_token = data.get('refresh_token')

        # Check token validity (example expiration logic)
        if not is_token_expired(access_token):
            logger.info("Token is valid for logout")
            perform_logout(access_token)
            return

        # Refresh the token
        logger.info("Token expired; refreshing...")
        response_refresh = refresh_access_token(refresh_token)
        if response_refresh.status_code != 200:
            raise ValueError(f"Failed to refresh token. Status code: {response_refresh.status_code}")

        updated_access_token = response_refresh.json().get('access_token')
        logger.info("Updated access token obtained")

        # Check new token validity
        if not is_token_expired(updated_access_token):
            perform_logout(updated_access_token)
            return

    except Exception as e:
        logger.error(f"Error during logout process: {str(e)}")
        handle_retries()

def refresh_access_token(refresh_token):
    try:
        response = requests.post('http://localhost:8080/api/auth/refresh', json={'refresh_token': refresh_token})
        if response.status_code != 200:
            raise ValueError(f"Failed to get access token. Status code: {response.status_code}")
        return response
    except Exception as e:
        logger.error(f"Error refreshing token: {str(e)}")
        sleep(30)  # Wait before retrying, implementing a simple retry logic here

def is_token_expired(token):
    try:
        expiration = get_token_expiration_time(token)
        if expiration and time_diff(current(), expiration) > 30 * 60:  # More than half-hour old
            return True
        return False
    except Exception as e:
        logger.error(f"Error checking token expiration: {str(e)}")
        return True

def get_token_expiration_time(token):
    try:
        response = requests.get('http://localhost:8080/api/auth/tokens/' + token)
        if response.status_code == 200:
            data = response.json()
            if 'expires_in' in data:
                return data['expires_in']
            else:
                return None
        return None
    except Exception as e:
        logger.error(f"Error fetching token expiration: {str(e)}")
        return None

def perform_logout(access_token):
    try:
        headers = {
            'Authorization': f'Bearer {access_token}'
        }
        response = requests.post('http://localhost:8080/auth/logout', headers=headers)
        if response.status_code == 200:
            logger.info("Successful logout")
            return True
        else:
            raise ValueError(f"Failed to perform logout. Status code: {response.status_code}")
    except Exception as e:
        logger.error(f"Error performing logout: {str(e)}")
        return False

def handle_retries():
    try:
        sleep(10)  # Initial retry after 10 seconds
        secure_logout()
    except KeyboardInterrupt:
        logger.info("Exited due to user interrupt")

import ftplib
from getpass import getpass
import hashlib

def connect_to_ftp(server, username, password):
    """Establish an FTP connection"""
    try:
        ftp = ftplib.FTP(server)
        ftp.login(username=username, password=password)
        return ftp
    except ftplib.error_perm:
        print("Login failed. Please check your credentials.")
        exit(1)

def calculate_md5(file_path):
    """Calculate the MD5 hash of a file"""
    md5_hash = hashlib.md5()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b""):
            md5_hash.update(chunk)
    return md5_hash.hexdigest()

def upload_file(ftp, file_path):
    """Upload a file to the FTP server"""
    try:
        file_name = file_path.split("/")[-1]
        with open(file_path, 'rb') as f:
            ftp.storbinary(f"STOR {file_name}", f)
    except ftplib.error_perm:
        print("Failed to upload the file. Please check your permissions.")
        exit(1)

def download_file(ftp, file_path):
    """Download a file from the FTP server"""
    try:
        file_name = file_path.split("/")[-1]
        with open(file_path, 'wb') as f:
            ftp.retrbinary(f"RETR {file_name}", f.write)
    except ftplib.error_perm:
        print("Failed to download the file. Please check your permissions.")
        exit(1)

def main():
    # FTP server details
    server = "ftp.dlptest.com"
    username = input("Enter your FTP username: ")
    password = getpass("Enter your FTP password: ")

    # Local file path
    local_file_path = input("Enter the full path of the file to upload/download: ")

    ftp = connect_to_ftp(server, username, password)

    if ftp:
        print(f"Connected to {server} as {username}")

        md5_hash = calculate_md5(local_file_path)
        print(f"MD5 hash of the file: {md5_hash}")

        action = input("Do you want to upload (U), download (D) or quit (Q)? ")
        if action.upper() == 'U':
            upload_file(ftp, local_file_path)
        elif action.upper() == 'D':
            download_file(ftp, local_file_path + ".downloaded")
        elif action.upper() == 'Q':
            print("Goodbye!")
            ftp.quit()
            exit(0)
        else:
            print("Invalid action. Please try again.")

if __name__ == "__main__":
    main()

import re

def validate_phone(number):
    pattern = re.compile("^\\d{10}$")

    if pattern.match(number) is None:
        return False  # not valid number
    else:
        return True   # valid number

import threading

def hang_forever():
    while True:
        pass  # hang forever

# create a new thread that hangs forever
hang_thread = threading.Thread(target=hang_forever)
hang_thread.start()

# terminate the hanging thread if it takes more than 10 seconds to complete
if hang_thread.join(timeout=10):
    print("Hanging thread was terminated")
else:
    print("Hanging thread completed successfully")

