import json
from datetime import datetime

def validate_api_input(input_data):
    # Define validation rules for each field
    validation_rules = {
        "name": ["required", "max_length=50"],
        "age": ["required", "min_value=1", "max_value=100"],
        "email": ["required", "email_format"]
    }

    # Initialize a flag to track if all fields are valid
    is_valid = True

    # Iterate over each field in the input data
    for field, value in input_data.items():
        # Check if the field has a validation rule
        if field in validation_rules:
            # Get the validation rules for this field
            field_rules = validation_rules[field]

            # Iterate over each rule
            for rule in field_rules:
                # If the rule is "required", check that the value is not empty
                if rule == "required" and value is None or value == "":
                    is_valid = False
                    break

                # If the rule is "max_length", check that the value has a maximum length
                elif rule == "max_length":
                    if len(value) > int(field_rules[rule]):
                        is_valid = False
                        break

                # If the rule is "min_value" or "max_value", check that the value falls within a valid range
                elif rule in ["min_value", "max_value"]:
                    if (field_rules[rule] == "min_value" and int(value) < int(field_rules[rule])) or \
                       (field_rules[rule] == "max_value" and int(value) > int(field_rules[rule])):
                        is_valid = False
                        break

                # If the rule is "email_format", check that the value has a valid email format
                elif rule == "email_format":
                    try:
                        datetime.strptime(value, "%(asctime)s.%H:%M:%S")
                        if "@" not in value or "." not in value:
                            is_valid = False
                            break
                    except ValueError:
                        pass

    # Return True if all fields are valid, otherwise return False
    return is_valid


# Example usage:

input_data = {
    "name": "John Doe",
    "age": 30,
    "email": "john@example.com"
}

print(validate_api_input(input_data))  # Output: True

input_data = {
    "name": "",
    "age": None,
    "email": ""
}

print(validate_api_input(input_data))  # Output: False

from flask import Flask, render_template, request, redirect, url_for
from flask_login import LoginManager, UserMixin, login_user, logout_user, current_user, login_required

# Create a Flask application
app = Flask(__name__)

# Configure the login manager
login_manager = LoginManager()
login_manager.init_app(app)

# Define the User model
class User(UserMixin):
    def __init__(self, username, role):
        self.username = username
        self.role = role

# Create a list of users with roles
users = [
    User('john', 'admin'),
    User('jane', 'editor'),
    User('bob', 'viewer'),
]

# Create a dictionary of accessible features by role
features_by_role = {
    'admin': ['edit', 'delete', 'publish'],
    'editor': ['edit', 'delete', 'publish'],
    'viewer': ['view'],
}

# Define the login view
@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']

        # Check if the user exists in the users list
        for user in users:
            if user.username == username:
                # Log in the user
                login_user(user)
                return redirect(url_for('index'))

        # Incorrect username or password
        return render_template('login.html', error='Invalid username or password.')

    return render_template('login.html')

# Define the logout view
@app.route('/logout')
@login_required
def logout():
    logout_user()
    return redirect(url_for('login'))

# Define the index view
@app.route('/')
@login_required
def index():
    # Get the user's role
    role = current_user.role

    # Get the list of accessible features
    features = features_by_role[role]

    return render_template('index.html', features=features)

if __name__ == '__main__':
    app.run(debug=True)

import urllib.parse
from urllib import rawurlparse, parse
import w3lib
import requests
import json
import logging

logging.basicConfig(level=logging.INFO)

def make_request(url, method='GET', params=None, data=None):
    """
    Send a secure HTTP request with proper authentication and headers.
    """
    # Prepare the request parameters
    if params:
        query_string = urllib.parse.urlencode(params)
    else:
        query_string = ''

    if data is not None:
        body = json.dumps(data)
    else:
        body = ''

    # Construct the full URL for the response
    response_url = f"{url}?query={query_string}"

    try:
        request_headers = {
            'X-Realized-Origin': urllib.parse.quote('http://localhost:8080'),
            'Forwarded': '1',
            'X-Requested-With': method if method.upper() == urllib.parse.unquote(method).upper() else None,
            'Content-Type': 'application/json',
            'Authorization': f'Basic {urllib.parse.quote(base64.b64encode(f"{method:lower}://").decode())}'
        }

        # Add custom headers as needed
        request_headers['X-Frame-Options'] = 'Deny'
        request_headers['HSTS'] = '1'
        request_headers['Content-Security-Policy'] = f"default-src '{urllib.parse.quote('self')}'"

        if 'Set-Cookie' in rawurlparse(urllib.request.urlopen(f"http://{response_url}")).headers:
            response_headers = urllib.request.urlopen(f"http://{response_url}").headers
        else:
            response_headers = {}

        # Send the request using requests library for simplicity and security
        response = requests.request(
            method,
            url,
            headers=request_headers,
            json=data,
            verify=True,
            proxies={'http': 'http://localhost:8080'},
            timeout=10,
            allow_redirects=False
        )

        # Extract the response content
        response_content = rawurlparse(response.request, allow_fragments=False).fragment or ''

        if response.status_code in (400, 403):
            logging.error(f"Request failed with status code: {response.status_code}")
            return None, f"Request failed due to status code {response.status_code}"

        # Handle other error cases
        for header in ['Server', 'Content-Type']:
            if not hasattr(response, header) or getattr(response, header) is None:
                logging.error(f"Missing required response header: {header}")
                return None, f"Response missing {header} header"

    except requests.exceptions.RequestException as e:
        code = str(e)
        error_headers = {}
        try:
            if 'Set-Cookie' in rawurlparse(urllib.request.urlopen(code)).headers:
                response_headers_code = urllib.request.urlopen(code).headers
            else:
                response_headers_code = {}

            for header in ['Server', 'Content-Type']:
                if hasattr(rawurlparse(code), header):
                    error_headers[header] = getattr(rawurlparse(code), header)
        except Exception as err:
            error_headers['Error'] = str(err)

        logging.error(f"Request failed with error: {e}, Error headers: {error_headers}")
        return None, f"Request failed due to: {e}"

    # Return the response content or parsed JSON if needed
    return response.content, response.json() if isinstance(response.content, json) else response.content

