class CurrencyConverter:
    def __init__(self):
        self.rates = {
            "USD": 1,  # assuming USD is the base currency
            "EUR": 0.85,  # 1 EUR = 0.85 USD
            "GBP": 0.73,  # 1 GBP = 0.73 USD
        }

    def convert(self, amount, from_currency, to_currency):
        initial_amount = amount / self.rates[from_currency]
        return round(initial_amount * self.rates[to_currency], 2)


converter = CurrencyConverter()
