import psycopg2
from datetime import datetime, timedelta
import logging

# Set up logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class QueryMonitor:
    def __init__(self, db_host, db_user, db_password, db_name):
        self.db_host = db_host
        self.db_user = db_user
        self.db_password = db_password
        self.db_name = db_name

    def connect_to_db(self):
        try:
            self.conn = psycopg2.connect(
                host=self.db_host,
                user=self.db_user,
                password=self.db_password,
                database=self.db_name
            )
            logger.info("Connected to database successfully")
            return self.conn.cursor()
        except psycopg2.Error as e:
            logger.error(f"Failed to connect to database: {e}")
            return None

    def execute_query(self, query):
        try:
            cursor = self.connect_to_db()
            if cursor is not None:
                cursor.execute(query)
                result = cursor.fetchall()
                cursor.close()
                return result
            else:
                logger.error("Failed to connect to database")
                return []
        except psycopg2.Error as e:
            logger.error(f"Error executing query: {e}")
            return []

    def get_query_performance(self, query):
        results = self.execute_query(query)
        if not results:
            return None
        execution_time = datetime.now() - results[0][4]
        execution_time_in_seconds = (execution_time.total_seconds())
        logger.info(f"Query: {query}, Execution Time: {execution_time_in_seconds:.2f} seconds")
        return execution_time_in_seconds

    def monitor_query_performance(self, query):
        if not self.execute_query(query):
            return None
        previous_execution_time = None
        try:
            while True:
                current_execution_time = self.get_query_performance(query)
                if current_execution_time is not None and (previous_execution_time is not None or current_execution_time > 0.1):
                    execution_time_difference = current_execution_time - previous_execution_time
                    logger.info(f"Query: {query}, Execution Time Difference: {execution_time_difference:.2f} seconds")
                previous_execution_time = current_execution_time
        except Exception as e:
            logger.error(f"Error monitoring query performance: {e}")

def main():
    db_host = "localhost"
    db_user = "your_username"
    db_password = "your_password"
    db_name = "your_database"

    monitor = QueryMonitor(db_host, db_user, db_password, db_name)
    query = "SELECT * FROM your_table"
    monitor.monitor_query_performance(query)

if __name__ == "__main__":
    main()

