@app.route("/verify-token", methods=["POST"])
def verify():
    data = request.json
    token = data.get("token")
    if not token:
        return jsonify({"error": "Missing JWT token"}), 401
    user_id, payload_expiration = verify_token(token)
    if not user_id or payload_expiration < datetime.utcnow():
        return jsonify({"error": "Invalid or expired token"}), 401
    return jsonify({"message": "Token verified successfully"}), 200

