from smtplib import SMTPStarttlsHandler, SMTPException
import mimetypes
from mailbox import parseheader
import datetime

class MTA(object):
    def __init__(self):
        self._server = None  # type: str
        self._port = 587   # type: int
        self._username = None  # type: str
        self._password = None  # type: str
        self._localhost = 'localhost'  # type: str

    def connect_mta(self):
        """Connect to MTA (message transfer agent)."""
        try:
            start = datetime.datetime.now()
            obj = self._server.start_server()
            obj.connect(self._localhost, self._port)
            print(f"[+] Successfully connected to {self._server}")
            return True
        except SMTPException as e:
            print(f"[-] Could not connect to MTA: {str(e)}")
            return False

    def parse_address(self, address):
        """Parse an email address into its components."""
        try:
            lines = [line.strip() for line in address.splitlines()]
            if len(lines) < 2:
                raise ValueError("Invalid address format")
            parts = parseheader(lines[0], 'address')
            local_part = parts.getfield('from').value
            remote_part = parts.getfield('to').value
            return (local_part, remote_part)
        except Exception as e:
            print(f"[-] Error parsing address: {str(e)}")
            raise ValueError("Invalid or missing address components")

    def send_email(self, subject, body, from_address, to_addresses,
                  bounce_reason=None):
        """Send email to multiple recipients."""
        # Setup MTA
        try:
            mta = MTA()
            mta.connect_mta()  # @风险: 打开连接后会关闭！

            for address in to_addresses:
                local_part, remote_part = self.parse_address(address)

                if not (local_part and remote_part):
                    print(f"[+] Local part: {local_part}")
                    print(f"[+] Remote part: {remote_part}")
                    # Set default bounce reason if parsing fails
                    bounce_reason = 'Invalid address'
                    continue

                msg = mta._server.sendmail(
                    from_address,
                    [address],
                    subject,
                    body.encode('utf-8')
                )

                print(f"[+] Sent to: {address} successfully")
        except SMTPException as e:
            # On failure, check if it's due to invalid recipient
            try:
                if str(e).lower().startswith("550 bad local part"):
                    bounce_reason = "Invalid address"
                    msg = mta._server.sendmail(
                        from_address,
                        [address],
                        subject,
                        body.encode('utf-8'),
                        delay=1  # Retries after 1 second
                    )
                elif str(e).lower().startswith("420 user error - auth failed"):
                    print(f"[-] Authentication failed: {str(e)}")
            except Exception as e:
                msg = mta._server.sendmail(
                    from_address,
                    [address],
                    subject,
                    body.encode('utf-8'),
                    delay=1
                )
            finally:
                if not isinstance(msg, int):
                    print(f"[-] Failed to send email: {str(msg)}")
        except ValueError as e:
            print(f"[-] Error parsing address: {str(e)}")
        else:
            pass  # On success

    def close(self):
        """Close the SMTP connection."""
        try:
            self._server.quit()
        except Exception as e:
            print(f"[-] Failed to close SMTP connection: {str(e)}")

