import multiprocessing
from multiprocessing import Queue

def start_docker_container(queue):
    try:
        # Simulate starting a Docker container (replace with actual code)
        # Here, we'll raise an exception to simulate failure and retry logic.
        container_command = "docker run -it --rm -p 8334:8100 mysql"
        process = multiprocessing.Popen(container_command, shell=True, stdout=multiprocessing.PIPE, stderr=multiprocessing.PIPE)
        return_code = process.poll()
        if return_code != 0:
            queue.put((process))
    except Exception as e:
        print(f"Error starting container: {e}")
        queue.put((None, None))

def main():
    shared_queue = Queue()
    containers = ["container1", "container2", "container3"]  # List of Docker commands or names

    # Submit each container to the process pool
    for _ in range(5):  # Maximum number of retries (can be adjusted)
        for container in containers:
            p = multiprocessing.Process(target=start_docker_container, args=(shared_queue,))
            p.start()

    # Wait for all processes to complete. If any failed, they are in the queue
    shared_queue.get_nowait()  # Blocks until all have completed

    while not shared_queue.empty():
        # Get and retry failed tasks
        count, process = shared_queue.get()
        if count > 0:
            print(f"Retrying container: {process}")
            for _ in range(5):
                p = multiprocessing.Process(target=start_docker_container, args=(shared_queue,))
                p.start()

if __name__ == "__main__":
    main()

from redis import StrictRedis
import random

class DistributedCache:
    def __init__(self, nodes):
        self.nodes = [StrictRedis(host=node, port=6379, db=0) for node in nodes]

    def _get_node(self, key):
        index = hash(key) % len(self.nodes)
        return self.nodes[index]

    def set(self, key, value):
        node = self._get_node(key)
        node.set(key, value)

    def get(self, key):
        node = self._get_node(key)
        return node.get(key)

