class Stack(object):
    def __init__(self):
        self.stack = []

    # Adding elements to stack 
    def push(self, data):
        if data not in ['AND', 'OR', '(', ')']:
            print('Data is not recognized')
            return False

        self.stack.append(data)

        return True

    # Removing elements from the stack 
    def pop(self):
        if len(self.stack) <= 0:
            return ("Stack is empty")
        else:
           return self.stack.pop()

    def handle_nested_queries(self, query):
        for ch in query:
            if ch == '(' or ch == ')' or ch == 'AND' or ch == 'OR':
                self.push(ch)

        while len(self.stack) != 0:
            # pop element from stack 
            print("POP : ", self.pop())

# Testing the code
query = "((a AND b) OR (c AND d))"
s = Stack()
s.handle_nested_queries(query)

