def levenshtein_distance(s1, s2):
    if len(s1) == 0:
        return len(s2)
    if len(s2) == 0:
        return len(s1)

    # Initialize a table to store distances of subproblems
    dp = [[0] * (len(s2) + 1) for _ in range(len(s1) + 1)]

    # Fill the first row and column with incremental values
    for i in range(len(s1) + 1):
        dp[i][0] = i
    for j in range(len(s2) + 1):
        dp[0][j] = j

    # Iterate through each character of both strings
    for i in range(1, len(s1) + 1):
        for j in range(1, len(s2) + 1):
            if s1[i-1] == s2[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                # Take the minimum of three possible operations
                dp[i][j] = 1 + min(dp[i-1][j],    # Delete from s1
                                   dp[i][j-1],    # Insert into s1
                                   dp[i-1][j-1])  # Replace in s1

    return dp[len(s1)][len(s2)]

def main():
    import sys
    input = sys.stdin.read().split()

    words = input[0].split() if len(input) > 0 else []
    query = input[1] if len(input) > 1 else ''
    max_distance = int(input[2]) if len(input) > 2 else 0

    print(f"Processing: Query - {query}, Max Distance: {max_distance}")

    results = []

    # Preprocess the query into a list of words
    processed_query = query.split()

    for word in words:
        distance = levenshtein_distance(word, processed_query)
        if distance <= max_distance or (len(processed_query) == 0 and len(word) > 0):
            results.append(word)

    print(f"Results with distance ≤ {max_distance}:")
    for result in results:
        print(result)

if __name__ == "__main__":
    main()

class ListManager:
    def __init__(self):
        self.cache = {}
        self.last_access = {}

    def add(self, key, value):
        if key not in self.cache:
            self.cache[key] = []
        cache_list = self.cache[key]
        cache_list.append(value)
        self.last_access[key] += 1

    def get(self, key):
        self.last_access.setdefault(key, 0)
        self.last_access[key] += 1
        return self.cache.get(key, None)

import threading
from queue import Queue

class PriorityTask(object):
    def __init__(self, priority=0):
        self.priority = priority

class PrioritizedThread(threading.Thread):
    def __init__(self, task_queue):
        super().__init__()
        self.task_queue = task_queue
        self.start()

    def run(self):
        while True:
            task = self.task_queue.get()
            if isinstance(task, PriorityTask):
                priority = task.priority
            else:
                priority = 0
            # Process the task with the appropriate priority
            print("Processing task {} with priority {}".format(task, priority))

import datetime

def is_valid(s):
    s_clean = s.strip()
    if not s_clean:
        return False

    try:
        # Check date only
        datetime.datetime.strptime(s_clean, "%Y-%m-%d")
        return True
    except ValueError:
        pass

    try:
        # Check time only
        datetime.datetime.strptime(s_clean, "%H:%M:%S")
        return True
    except ValueError:
        pass

    try:
        # Check date and time combined with space separator
        if len(s_clean) >= 16:  # Minimum length for "YYYY-MM-DD HH:MM:ss"
            datetime.datetime.strptime(s_clean, "%Y-%m-%d %H:%M:%S")
            return True
    except ValueError:
        pass

    return False

