import logging
from datetime import datetime

class LogDataProcessor:
    def __init__(self):
        self.logger = logging.getLogger(__name__)
        formatter = '%(asctime)s - %(levelname)s - %(message)s'
        self.logger.setLevel(logging.INFO)
        self.logger.addHandler(logging.StreamHandler())

    def process_log_entry(self, column_name, data):
        try:
            # Simulate processing the log entry
            processed_data = self._process_column(column_name, data)
            message = f"Processed {column_name}: {processed_data}"
            self._log_info(message)
        except Exception as e:
            error_message = f"Error processing {column_name}: {str(e)}"
            self._log_error(error_message)

    def _process_column(self, column, data):
        # Simulate processing logic for the given column
        processed = {
            'Count': len(data),
            'Average': sum(data) / len(data) if len(data) > 0 else None,
            'Max': max(data) if data else None,
            'Min': min(data) if data else None
        }
        return processed

    def _log_info(self, message):
        timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        self.logger.info(f"[{timestamp}] [I] {message}")

    def _log_warning(self, message):
        timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        self.logger.warning(f"[{timestamp}] [W] {message}")

    def _log_error(self, message):
        timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        self.logger.error(f"[{timestamp}] [E] {message}", exc_info=True)

