import logging
from datetime import datetime
from enum import Enum

class DeploymentStatus(Enum):
    STARTED = "Started"
    RUNNING = "Running"
    COMPLETED = "Completed"
    FAILED = "Failed"

class DeploymentActivityLogger:
    def __init__(self, log_file="deployment_activities.log"):
        self.log_file = log_file
        self.logger = logging.getLogger(__name__)
        self.logger.setLevel(logging.INFO)
        handler = logging.FileHandler(log_file)
        formatter = logging.Formatter("%(asctime)s - %(levelname)s - %(message)s")
        handler.setFormatter(formatter)
        self.logger.addHandler(handler)

    def log_start(self, deployment_name):
        self.logger.info(f"Deployment {deployment_name} started at {datetime.now()}")

    def log_run(self, status):
        self.logger.info(f"Deployment running. Status: {status}")

    def log_end(self, status, error_message=None):
        if error_message:
            self.logger.error(f"Deployment completed with error: {error_message}")
        else:
            self.logger.info(f"Deployment completed at {datetime.now()}")

    def log_error(self, error_message):
        self.logger.error(error_message)

# Example usage
