def deploy_deployment(deployment_name):
    try:
        logger.log_start(deployment_name)
        # Simulate deployment work
        import time
        for i in range(10):
            logger.log_run(DeploymentStatus.RUNNING)
            time.sleep(1)
        logger.log_end(DeploymentStatus.COMPLETED)
    except Exception as e:
        logger.log_error(f"Deployment failed: {e}")
        logger.log_end(DeploymentStatus.FAILED, str(e))

import hashlib
from time import sleep
import sys

class IncrementalBackup:
    def __init__(self):
        self.file_hashes = {}  # Maps filenames to their hash digests
        self.last_modified = {}  # Tracks last modified times of backups
        self.current_backup = {}  # Stores the current state for comparison
        self.options = {
            'list': 'List file differences',
            'diff': 'Run incremental backup',
            'progress': 'Show progress',
            'finish': 'Finish backup'
        }

    def collect_differences(self):
        """Compare current backup with previous and return differences."""
        new_files = []
        changed_files = []

        # Check for files not in the previous backup
        for filename, content in self.current_backup.items():
            if filename not in self.file_hashes:
                new_files.append(filename)
                continue

            # Recalculate hash to check for changes
            current_hash = hashlib.sha1(content.encode()).hexdigest()
            if current_hash != self.file_hashes[filename]:
                changed_files.append(filename)

        # Add new files to file hashes and last_modified
        for filename in new_files:
            self.file_hashes[filename] = hashlib.sha1(self.current_backup[filename].encode()).hexdigest()

        return {**new_files, **changed_files}

    def run_backup(self):
        """Run an incremental backup."""
        differences = self.collect_differences()

        if not differences:
            print("No changes detected since last backup.")
            input("\nPress Enter to continue...")
            return

        # Update all affected files
        for filename in differences:
            content = open(filename, 'rb').read()
            current_hash = hashlib.sha1(content.encode()).hexdigest()

            # Write updated hash and file content back
            with open(filename, 'wb') as f:
                f.write(content)

            if filename in self.file_hashes:
                del self.file_hashes[filename]
            self.file_hashes[filename] = current_hash

        print(f"\nBackup completed. Differences saved for: {differences}")
        input("\nPress Enter to continue...")

    def show_progress(self):
        """Print progress of the backup."""
        total_files = len(self.current_backup)
        done_files = sum(1 for _ in self.file_hashes.values() if _ is not None)
        percentage = (done_files / total_files) * 100

        sys.stdout.write(f"\rBackup progress: {percentage:.2f}%  ["
                         f"{'#' * int(percentage)} " 
                         f"{ done_files }/{ total_files } files completed ]\n")
        sys.stdout.flush()

    def finish_backup(self):
        """Mark the backup as complete."""
        self.last_modified = {
            filename: None for filename in self.file_hashes.keys()
        }

def main():
    print("Welcome to Incremental Backup System")
    ib = IncrementalBackup()

    while True:
        print("\nAvailable commands:")
        print(f"{ib.options['list']}")
        print(f"{ib.options['diff']}")
        print(f"{ib.options['progress']}")
        print(f"{ib.options['finish']}")
        print()

        command = input("Enter command ('help' to see available options): ").lower()

        if command == 'help':
            print(__doc__)
            continue

        elif command in ib.options:
            func = getattr(ib, command)
            if hasattr(func):
                try:
                    func()
                except KeyboardInterrupt:
                    print("\nBackup cancelled by user.")
                    main()

        elif command == 'finish':
            ib.finish_backup()
            input("Backup completed. Press Enter to finish the system.\n")
            break

        else:
            print(f"Unknown command: {command}")

if __name__ == "__main__":
    main()

