from flask import Flask, request, jsonify
import datetime

app = Flask(__name__)

# IoT device data storage (in-memory for simplicity)
iot_device_data = {}

@app.route('/iot', methods=['POST'])
def receive_iot_data():
    # Validate user input
    try:
        data = request.get_json()
        required_keys = ['device_id', 'data']
        if not all(key in data for key in required_keys):
            return jsonify({'error': 'Missing device ID or data'}), 400

        # Rate limiting (e.g., limit to 10 requests per minute)
        current_time = datetime.datetime.now()
        if current_time - iot_device_data['last_request'] < datetime.timedelta(minutes=1) and len(iot_device_data) >= 10:
            return jsonify({'error': 'Too many requests from this device'}), 429

        # Store IoT device data
        iot_device_data['device_id'] = data['device_id']
        iot_device_data['data'] = data['data']

    except Exception as e:
        return jsonify({'error': str(e)}), 500

    return jsonify(iot_device_data)

