import time
from collections import defaultdict
from psutil import process, cpu_count

class CacheMonitor:
    def __init__(self):
        self.cache_size = 0
        self.cache_hits = defaultdict(int)
        self.cache_misses = defaultdict(int)
        self.cache_timestamps = {}
        self.process_id = None

    def start(self, pid):
        """Start monitoring cache usage for the given process."""
        self.process_id = pid
        self.cache_size = psutil.Process(pid).memory_info().rss / (1024 * 1024)  # Convert bytes to MB
        self.cache_timestamps[pid] = int(time.time())

    def update(self, values):
        """Update cache usage statistics based on the given values."""
        if 'hits' in values:
            for key, value in zip(values['hits'], [self.cache_hits[pid]] * len(values['hits'])):
                self.cache_hits[key] += value
        if 'misses' in values:
            for key, value in zip(values['misses'], [self.cache_misses[pid]] * len(values['misses'])):
                self.cache_misses[key] += value

    def calculate(self):
        """Calculate and return the cache hit ratio and miss ratio."""
        if not self.process_id or not self.cache_hits or not self.cache_misses:
            return 0, 0
        current_time = int(time.time())
        elapsed_time = current_time - self.cache_timestamps[self.process_id]
        cache_hits = sum(self.cache_hits.values()) / elapsed_time
        cache_misses = sum(self.cache_misses.values()) / elapsed_time
        return cache_hits, cache_misses

    def get_cache_size(self):
        """Return the current cache size in MB."""
        return self.cache_size


def main():
    # Create a new CacheMonitor instance
    monitor = CacheMonitor()

    # Start monitoring for process with PID 1234
    monitor.start(1234)

    while True:
        values = []
        if monitor.process_id is not None and psutil.Process(monitor.process_id).memory_info().rss != monitor.cache_size * (1024 * 1024):
            print("Cache size has changed. Updating statistics.")
            # Simulate cache hit/miss events
            for i in range(10):
                values.append((f"Key{i}", {"hits": [1], "misses": [0]}))
                time.sleep(0.5)
        else:
            break

        monitor.update(values)

        hits, misses = monitor.calculate()
        print(f"Hits: {hits:.2f}%, Misses: {misses:.2f}%")

        # Check if the process has finished
        try:
            psutil.Process(monitor.process_id).memory_percent()
        except psutil.NoSuchProcess:
            break

if __name__ == "__main__":
    main()

import sqlite3
from sqlite3 import Error
import hashlib

def create_connection(db_file):
    conn = None
    try:
        conn = sqlite3.connect(db_file)
        return conn
    except Error as e:
        print(e)

def create_table(conn):
    query = """
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT NOT NULL,
            password_hash TEXT NOT NULL
        );
    """
    try:
        cursor = conn.cursor()
        cursor.execute(query)
    except Error as e:
        print(e)

def register_user(conn, username, password):
    hashed_password = hashlib.sha256(password.encode()).hexdigest()
    query = """
        INSERT INTO users (username, password_hash) VALUES (?, ?);
    """
    try:
        cursor = conn.cursor()
        cursor.execute(query, (username, hashed_password))
        return True
    except Error as e:
        print(e)
        return False

def authenticate_user(conn, username, password):
    query = """
        SELECT * FROM users WHERE username = ? AND password_hash = ?;
    """
    try:
        cursor = conn.cursor()
        cursor.execute(query, (username, hashlib.sha256(password.encode()).hexdigest()))
        row = cursor.fetchone()
        if row is not None and len(row) > 0:
            return True
    except Error as e:
        print(e)
    return False

def main():
    db_file = "user_data.db"

    conn = create_connection(db_file)
    if conn is not None:
        create_table(conn)

        username = input("Enter your username: ")
        password = input("Enter your password: ")

        if register_user(conn, username, password):
            print(f"User '{username}' created successfully.")
        else:
            print("Failed to create user.")

        again = True
        while again:
            username = input("Do you want to login? (yes/no): ")
            if username.lower() == "no":
                break

            if authenticate_user(conn, username, password):
                print(f"User '{username}' authenticated successfully.")
            else:
                print(f"Incorrect credentials for user '{username}'.")

    conn.close()

if __name__ == "__main__":
    main()

from PIL import Image
import os

def secure_resize(input_image_path, output_image_path, basewidth):
    img = Image.open(input_image_path)
    if hasattr(img, '_getexif'):
        exif=img._getexif()
        orientation = 274
        if exif and orientation in exif:
            if exif[orientation] == 3: img = img.rotate(180, expand=True)
            elif exif[orientation] == 6: img = img.rotate(270, expand=True)
            elif exif[orientation] == 8: img = img.rotate(90, expand=True)
    wpercent = (basewidth/float(img.size[0]))
    hsize = int((float(img.size[1])*float(wpercent)))
    img = img.resize((basewidth,hsize), Image.ANTIALIAS)
    img.save(output_image_path, format='JPEG', quality=85)

# usage: secure_resize('input.jpg', 'output.jpg', 1024)

import time

# A cache object to store the data
cache = {}

# A dictionary to keep track of the last update time for each piece of data
last_update_time = {}

def get_data(key):
    # Check if the data is in the cache
    if key in cache:
        return cache[key]

    # If not, retrieve it from the database and add it to the cache
    else:
        # Retrieve the data from the database
        data = retrieve_data(key)

        # Add it to the cache with a unique identifier
        cache[key] = data
        last_update_time[key] = time.time()

        return data

def invalidate_cache():
    # Clear the cache and reset the last update time for each piece of data
    global cache, last_update_time
    cache = {}
    last_update_time = {}

def update_data(key):
    # Retrieve the data from the database
    new_data = retrieve_data(key)

    # Update the cache with the new data and reset the last update time
    cache[key] = new_data
    last_update_time[key] = time.time()

from PIL import Image
from PIL.ExifTags import TAGS, GPSTAGS
import os

def get_exif(filename):
    image = Image.open(filename)
    image.verify()
    return image._getexif()

def get_labeled_exif(exif):
    labeled = {}
    for (key, val) in exif.items():
        labeled[TAGS.get(key)] = val

    return labeled

def get_geotagging(exif):
    if not exif:
        raise ValueError("No EXIF metadata found")

    geotagging = {}
    for (idx, tag) in TAGS.items():
        if tag == 'GPSInfo':
            if idx not in exif:
                raise ValueError("No EXIF geotagging found")

            for (key, val) in GPSTAGS.items():
                if key in exif[idx]:
                    geotagging[val] = exif[idx][key]

    return geotagging

def get_decimal_from_dms(dms, ref):

    degrees = dms[0][0] / dms[0][1]
    minutes = dms[1][0] / dms[1][1] / 60.0
    seconds = dms[2][0] / dms[2][1] / 3600.0

    if ref in ['S', 'W']:
        degrees = -degrees
        minutes = -minutes
        seconds = -seconds

    return round(degrees + minutes + seconds, 5)

def get_coordinates(geotags):
    lat = get_decimal_from_dms(geotags['GPSLatitude'], geotags['GPSLatitudeRef'])

    lon = get_decimal_from_dms(geotags['GPSLongitude'], geotags['GPSLongitudeRef'])

    return (lat,lon)

def extract_metadata(filename):
    exif = get_exif(filename)
    labeled_exif = get_labeled_exif(exif)
    print("Labeled EXIF data:")
    print(labeled_exif)

    try:
        geotags = get_geotagging(exif)
        coordinates = get_coordinates(geotags)
        print("Geolocation data:")
        print(f"Latitude: {coordinates[0]}")
        print(f"Longitude: {coordinates[1]}")
    except ValueError as e:
        print(str(e))

# Path to the image file
image_path = "path/to/your/image.jpg"
extract_metadata(image_path)

from flask import Flask, request, abort
import hmac
import hashlib

app = Flask(__name__)
SECRET_TOKEN = 'your-secret-token'  # replace with your actual secret token

def verify_signature(request):
    received_signature = request.headers.get('X-Hub-Signature')
    if received_signature is None:
        return False

    sha_name, signature = received_signature.split('=')
    if sha_name != 'sha1':
        abort(403)

    mac = hmac.new(SECRET_TOKEN.encode(), msg=request.data, digestmod=hashlib.sha1)

    return hmac.compare_digest(str(mac.hexdigest()), str(signature))

@app.route('/webhook', methods=['POST'])
def webhook():
    if verify_signature(request):
        print('Received data: ' + request.data)  # you should process this data as needed
        return '', 200
    else:
        abort(403)

if __name__ == '__main__':
    app.run()

