    for t in threads:
        t.join()

import requests
import time
from datetime import timedelta

class APIMonitor:
    def __init__(self, url):
        self.url = url
        self.request_start_time = None
        self.request_end_time = None

    def make_request(self):
        start_time = time.time()
        response = requests.get(self.url)
        end_time = time.time()

        if response.status_code == 200:
            return (end_time - start_time) * 1000, response.json()
        else:
            print(f"Failed to retrieve data. Status code: {response.status_code}")
            return None

    def monitor_response_time(self):
        try:
            while True:
                response = self.make_request()

                if response is not None:
                    _, data = response
                    request_start_time, request_end_time = self.request_start_time, self.request_end_time
                    if request_start_time is None or request_end_time is None:
                        self.request_start_time = time.time()
                        continue

                    # Calculate average and maximum response times
                    avg_response_time = (request_end_time - request_start_time) * 1000 / 2 + data['responseTime'] * 1000
                    max_response_time = request_end_time - request_start_time
                    print(f"Average Response Time: {avg_response_time:.2f}ms, Max Response Time: {max_response_time:.2f}ms")
                    self.request_start_time = None
                else:
                    time.sleep(1)  # Sleep for 1 second before retrying the request
        except KeyboardInterrupt:
            print("\nStopping API Monitor...")

# Example usage:
if __name__ == "__main__":
    url = "https://api.example.com/data"
    api_monitor = APIMonitor(url)

    # Start monitoring response times
    try:
        api_monitor.monitor_response_time()
    except KeyboardInterrupt:
        pass

