import mimetypes
from os import path

class FileTypeValidator:
    def __init__(self):
        # Define a list of approved file extensions
        self.approved_types = {
            'image': ['jpg', 'jpeg', 'png', 'gif', 'bmp'],
            'video': ['mp4', 'avi', 'mov'],
            'document': ['pdf', 'docx', 'doc', 'txt'],
            'audio': ['mp3', 'wav']
        }

    def validate_file_type(self, file_path):
        # Get the MIME type of the uploaded file
        mime_type = mimetypes.guess_type(file_path)[0]

        # Extract the file extension from the MIME type
        file_extension = path.splitext(mime_type)[1].lower()

        # Check if the file extension is in the approved types
        for file_type, extensions in self.approved_types.items():
            if file_extension in extensions:
                return True

        return False


