def handle_null_pointer_exceptions(func):
    """
    Decorator to handle null pointer exceptions in a function.

    Args:
        func: The function to decorate.

    Returns:
        A new function that wraps the original function and handles null pointer exceptions.
    """

    def wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except TypeError as e:
            if "null pointer" in str(e):
                print("Null pointer exception detected. Handling gracefully.")
                return None
            else:
                raise e

    return wrapper

from enum import Enum

class Permission(Enum):
    """Permissions for RBAC"""
    VIEW = 1
    EDIT = 2
    DELETE = 3

class Role(Enum):
    """Roles in the system"""
    ADMIN = "admin"
    MODERATOR = "moderator"
    USER = "user"

class User:
    """Represents a user with roles and permissions"""

    def __init__(self, username):
        self.username = username
        self.roles = []

    def add_role(self, role):
        """Assigns a role to the user"""
        if role not in [r.value for r in Role]:
            raise ValueError("Invalid role")
        self.roles.append(role)

class RoleManager:
    """Manages roles and permissions"""

    def __init__(self):
        self.users = {}
        self.roles = set()

    def add_user(self, username, roles):
        """Adds a user with their assigned roles"""
        if not roles:
            raise ValueError("No roles assigned")
        self.users[username] = User(username)
        for role in roles:
            self.users[username].add_role(role)

    def grant_permission(self, user, permission):
        """Grants a permission to the user"""
        if permission not in [p.value for p in Permission]:
            raise ValueError("Invalid permission")
        user.add_role(permission)

    def revoke_permission(self, user, permission):
        """Revoke a permission from the user"""
        user.roles = [r for r in user.roles if r != permission]

# Example usage
rbac_manager = RoleManager()

# Add users with roles and grant permissions
rbac_manager.add_user("admin", [Role.ADMIN.value])
rbac_manager.grant_permission(rbac_manager.users["admin"], Permission.VIEW)

rbac_manager.add_user("moderator", [Role.MODERATOR.value, Role.ADMIN.value])
rbac_manager.grant_permission(rbac_manager.users["moderator"], Permission.EDIT)
rbac_manager.grant_permission(rbac_manager.users["moderator"], Permission.VIEW)

# Attempt to revoke a permission that doesn't exist
try:
    rbac_manager.revoke_permission(rbac_manager.users["admin"], Permission.DELETE)
except ValueError as e:
    print(e)  # Output: Invalid permission

# Attempt to access an action or resource without the required permission
try:
    rbac_manager.users["moderator"].username  # This should raise an exception
except Exception as e:
    print(e)  # Output: Access denied

