def handle_duplicate_events(event_list):
    # Use a set to automatically remove duplicates
    unique_events = set()

    for event in event_list:
        unique_events.add(event)

    return list(unique_events)

import pyclamd
from django.core.files.storage import FileSystemStorage
from django.http import HttpResponse

def scan_file(uploaded_file):
    """Scan a file for viruses"""
    try:
        cd = pyclamd.ClamdAgnostic()  # create an instance of the ClamAV daemon
        if uploaded_file:
            with open(uploaded_file.path, 'rb') as file_to_scan:
                return cd.scan_stream(file_to_scan)  # scan the file
    except pyclamd.ConnectionError:
        return "Could not connect to antivirus server"

def upload_file(request):
    """Handle a file upload"""
    if request.method == 'POST' and request.FILES['myfile']:
        myfile = request.FILES['myfile']
        fs = FileSystemStorage()
        filename = fs.save(myfile.name, myfile)
        scan_result = scan_file(fs.open(filename))
        if scan_result is None:  # no viruses found
            return HttpResponse("File uploaded and scanned successfully")
        else:
            fs.delete(filename)  # delete the file to prevent it from being used
            return HttpResponse("Malware detected in the uploaded file")
    return HttpResponse("No file was uploaded")

import numpy as np

def handle_inference_results(results):
    # Check if the results are valid
    if not results or len(results) == 0:
        raise ValueError("Invalid results")

    # Get the highest probability result
    max_probability = None
    max_result = None
    for result in results:
        if max_probability is None or result[1] > max_probability:
            max_probability = result[1]
            max_result = result[0]

    # Check if the highest probability result is within a reasonable threshold
    if max_probability < 0.5:
        raise ValueError("Inference results are not trustworthy")

    return max_result

import requests
import time

def check_api_response(url):
    start = time.time()
    try:
        response = requests.get(url)
        end = time.time()
        return end - start, response.status_code
    except requests.RequestException as e:
        print("Error occurred:", str(e))
        return None

def monitor_api(url, interval=5):
    while True:
        response_time = check_api_response(url)
        if response_time is not None:
            print(f'Response time: {response_time[0]} seconds. Status code: {response_time[1]}')
        else:
            print('Failed to get API response')
        time.sleep(interval)

