import threading
import time

class Worker(threading.Thread):
    def __init__(self, target, args, queue, lock):
        super().__init__()
        self.target = target
        self.args = args
        self.queue = queue
        self.lock = lock
        self.exception = None

    def run(self):
        try:
            result = self.target(*self.args)
            with self.lock:
                self.queue.put(result)
        except Exception as e:
            with self.lock:
                self.queue.put(('error', str(e)))

def execute_task(task, queue, lock):
    """Runs a task in a new thread and collects the result."""
    worker = Worker(target=task, args=(queue, lock))
    worker.start()
    worker.join()
    return queue.get()

def parallel_execute(tasks, num_workers=10):
    """Executes tasks in parallel using multiple threads."""
    if len(tasks) == 0:
        return

    # Create a result queue and lock
    result_queue = []
    lock = threading.Lock()

    # Create worker threads for each task
    workers = []
    for i in range(num_workers):
        if i < len(tasks):
            args = (tasks[i], result_queue, lock)
            thread = Worker(*args)
            workers.append(thread)

    # Run all tasks
    for thread in workers:
        thread.start()

    # Collect results and sort them by input order
    sorted_results = []
    for i, task in enumerate(tasks):
        try:
            result = execute_task(task, result_queue, lock)
            sorted_results.append(result)
        except Exception as e:
            print(f"Error executing task {i}: {e}")

    # Print the results
    for result in sorted_results:
        if isinstance(result, str) and result.startswith('error'):
            print(f"Error: {result}")
        else:
            print(result)

# Example usage:
def main():
    tasks = [
        (print, ['Hello']),
        (print, ['World']),
        (lambda x, y: x + y, (42, 'age')),
        (lambda x: x ** 3, [3]),
        (lambda x: sum([1]*x), [5])
    ]

    parallel_execute(tasks)

if __name__ == "__main__":
    main()

import datetime

class Message:
    def __init__(self, message_id, content, timestamp):
        self.message_id = message_id
        self.content = content
        self.timestamp = timestamp

class MessagingSystem:
    def __init__(self):
        self.messages = []

    def add_message(self, message):
        self.messages.append(message)

    def delete_message(self, message_id):
        for message in self.messages:
            if message.message_id == message_id:
                self.messages.remove(message)
                print(f"Message {message_id} deleted successfully.")
                return
        print(f"No message with ID {message_id} found.")

    def process_messages(self, days):
        current_date = datetime.date.today()
        processed_messages = [message for message in self.messages if (current_date - message.timestamp).days <= days]
        for message in processed_messages:
            self.delete_message(message.message_id)

# Example usage
