import jwt
from websockets import WebSocketServer
from datetime import datetime, timedelta

# Secret key for JWT token signing
secret_key = b'your_secret_key_here'

class Authenticator:
    def __init__(self):
        self.expiration_time = 60 * 60  # 1 hour

    def generate_token(self, username):
        payload = {
            'exp': datetime.utcnow() + timedelta(seconds=self.expiration_time),
            'iat': datetime.utcnow(),
            'sub': username
        }
        return jwt.encode(payload, secret_key, algorithm='HS256')

    def verify_token(self, token):
        try:
            decoded_token = jwt.decode(token, secret_key, algorithms=['HS256'])
            return decoded_token['sub']
        except jwt.ExpiredSignatureError:
            raise ValueError("Token has expired")
        except jwt.InvalidTokenError as e:
            raise ValueError(f"Invalid token: {e}")

class WebSocketServer:
    def __init__(self):
        self.authenticator = Authenticator()

    async def register(self, websocket):
        username = await websocket.recv()
        token = self.authenticator.generate_token(username)
        await websocket.send(token)

    async def authenticate(self, websocket, token):
        try:
            username = self.authenticator.verify_token(token)
            return username
        except ValueError as e:
            raise ValueError(f"Invalid token: {e}")

    async def handle_message(self, websocket, message):
        if message.startswith('token '):
            token = message.split(' ', 1)[1]
            try:
                username = await self.authenticate(websocket, token)
                # Token is valid, authenticate and authorize the user
                print(f"User {username} authenticated successfully")
                # Your authorization logic here...
                return f"Welcome back, {username}!"
            except ValueError as e:
                print(f"Invalid token: {e}")
                return "Error: Invalid token"
        else:
            return "Error: Missing token"

async def main():
    server = WebSocketServer()
    async with WebSocketServer as ws:
        await ws.serve_forever()

if __name__ == '__main__':
    import asyncio
    asyncio.run(main())

