import requests
import logging

# Set up logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class APIFallback:
    def __init__(self, base_url, max_retries=3):
        self.base_url = base_url
        self.max_retries = max_retries

    def get(self, endpoint, params=None):
        for retry in range(self.max_retries):
            try:
                response = requests.get(f"{self.base_url}{endpoint}", params=params)
                if response.status_code == 200:
                    return response.json()
            except requests.exceptions.RequestException as e:
                logger.error(f"Request failed after {retry+1} retries: {e}")
                time.sleep(1)  # wait for 1 second before retrying
        raise Exception(f"Failed to retrieve data after {self.max_retries} retries")

    def post(self, endpoint, json_data):
        for retry in range(self.max_retries):
            try:
                response = requests.post(f"{self.base_url}{endpoint}", json=json_data)
                if response.status_code == 201:
                    return response.json()
            except requests.exceptions.RequestException as e:
                logger.error(f"Request failed after {retry+1} retries: {e}")
                time.sleep(1)  # wait for 1 second before retrying
        raise Exception(f"Failed to create data after {self.max_retries} retries")

    def put(self, endpoint, json_data):
        for retry in range(self.max_retries):
            try:
                response = requests.put(f"{self.base_url}{endpoint}", json=json_data)
                if response.status_code == 200:
                    return response.json()
            except requests.exceptions.RequestException as e:
                logger.error(f"Request failed after {retry+1} retries: {e}")
                time.sleep(1)  # wait for 1 second before retrying
        raise Exception(f"Failed to update data after {self.max_retries} retries")

    def delete(self, endpoint):
        for retry in range(self.max_retries):
            try:
                response = requests.delete(f"{self.base_url}{endpoint}")
                if response.status_code == 200:
                    return response.json()
            except requests.exceptions.RequestException as e:
                logger.error(f"Request failed after {retry+1} retries: {e}")
                time.sleep(1)  # wait for 1 second before retrying
        raise Exception(f"Failed to delete data after {self.max_retries} retries")

# Usage example
api = APIFallback("https://example.com/api")
try:
    data = api.get("/users", params={"limit": 10})
    print(data)
except Exception as e:
    logger.error(f"Error: {e}")

from flask import Flask, g, abort
