import jwt

app = Flask(__name__)

def requires_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization')

        if not auth_header:
            abort(403)
        try:
            token = auth_header.split(" ")[1]
            data = jwt.decode(token, app.config['SECRET_KEY'])

            # Here you could add more tenant specific logic depending on your needs
            if 'tenant' not in data:
                abort(403)

            g.current_tenant = data['tenant']
        except Exception as e:
            print(e)
            abort(403)

        return f(*args, **kwargs)

    return decorated

@app.route('/api/resource')
@requires_auth
def my_resource():
    # This endpoint will only be accessible if the JWT token includes a 'tenant' field
    return {'message': f"Hello from tenant {g.current_tenant}"}, 200

