import json
from collections import OrderedDict

class VersionedModel:
    def __init__(self):
        self.version = 0
        self.models = {}
        self.initial_state()

    def initial_state(self):
        # Initialize your model here, for example:
        model = {"model_name": "my_model", "version": 0}
        self.save_model(model)

    def save_model(self, model):
        self.version += 1
        self.models[self.version] = model

    def get_latest_model(self):
        if self.models:
            latest_version = max(self.models.keys())
            return self.models[latest_version]
        else:
            return None

    def get_model_by_version(self, version):
        return self.models.get(version)

    def update_model(self, changes):
        latest_model = self.get_latest_model()
        if latest_model is not None:
            for key, value in changes.items():
                latest_model[key] = value
            self.save_model(latest_model)

