import pickle
from urllib.parse import quote, unquote

class NetworkSerializer:
    @staticmethod
    def serialize(obj):
        if hasattr(obj, 'serialize'):
            return obj.serialize()

        encoded = quote(str(obj))
        try:
            return encoded.encode('utf-8')
        except AttributeError:
            pass

        return pickle.dumps(obj)

    @staticmethod
    def deserialize(data):
        try:
            decoded = unquote(unpickle.loads(data.decode('utf-8')))
            return decoded
        except Exception as e:
            raise ValueError(f"Failed to deserialize data: {e}")

# Example usage:
if __name__ == "__main__":
    import json

    # Serialize a dictionary
    obj = {"name": "John Doe", "age": 30}
    serialized = NetworkSerializer.serialize(obj)

    print("Serialized:", bytes hex(serialized))
    print("JSON Encoded:", json.dumps(serialized))

    # Serialize a list
    lst = [1, 2, 3]
    serialized_lst = NetworkSerializer.serialize(lst)
    print("\nSerialized List:", bytes hex(serialized_lst))

    # Serialize a custom object
    class CustomObject:
        def __init__(self, value):
            self.value = value

    obj = CustomObject("Test value")
    serialized_obj = NetworkSerializer.serialize(obj)
    print("\nSerialized Object:", bytes hex(serialized_obj))

    # Serialize a raw string that's quoted before serialization
    raw_str = '"Hello, World!"'
    serialized_str = NetworkSerializer.serialize(raw_str)
    print("\nSerialized String:", bytes hex(serialized_str))

    # Deserialize the data
    try:
        deserialized = NetworkSerializer.deserialize(serialized_str)
        print("\nDeserialized String:", unquote(deserialized))
    except Exception as e:
        print(f"Error during deserialization: {e}")

