import json

def validate_json(json_data):
    try:
        # Parse the JSON data
        parsed_data = json.loads(json_data)

        # Validate the data structure
        if not isinstance(parsed_data, dict):
            raise ValueError("Invalid data structure: must be a dictionary.")

        # Check for required fields
        required_fields = ["name", "email", "age"]
        for field in required_fields:
            if field not in parsed_data:
                raise ValueError(f"Missing required field: {field}")

        # Perform additional validation as needed
        if not isinstance(parsed_data["age"], int):
            raise ValueError("Invalid data type for field 'age': must be an integer.")

        # Data structure is valid
        return True

    except ValueError as e:
        # Invalid data structure
        print(f"Error validating JSON data: {e}")
        return False

