def handle_large_dataset(file_path):
    # Use chunksize to read the file in chunks, not all at once
    chunksize = 10 ** 6
    chunks = []

    for chunk in pd.read_csv(file_path, chunksize=chunksize):
        # Process each chunk here. For example, let's say we want to calculate the mean of a column:
        chunks.append(chunk['column_name'].mean())

    # Concatenate all the chunks and return the result
    return pd.concat(chunks).mean()

import time
from collections import OrderedDict

class CacheEvictionPolicy:
    def __init__(self, cache_size):
        self.cache_size = cache_size
        self.cache = OrderedDict()

    def set(self, key, value):
        self.cache[key] = value
        if len(self.cache) > self.cache_size:
            self.cache.popitem(last=False)

    def get(self, key):
        if key in self.cache:
            self.cache.move_to_end(key)
            return self.cache[key]
        return None

def main():
    cache_size = 5
    cache = CacheEvictionPolicy(cache_size)

    # Set cache entries
    for i in range(10):
        cache.set(i, i)

    # Get cache entries
    for i in range(10):
        value = cache.get(i)
        print(value)

if __name__ == "__main__":
    main()

