import time

# This is a simple simulation of our "database" where we store valid session tokens along with their expiration times.
session_tokens = {
    'token1': {'expiry': time.time() + 3600},   # Token expires in 1 hour
    'token2': {'expiry': time.time() + 7200},   # Token expires in 2 hours
}

def validate_token(token):
    if token not in session_tokens:
        return False, "Invalid token"

    if time.time() > session_tokens[token]['expiry']:
        del session_tokens[token]   # Remove expired token from the database
        return False, "Token has expired"

    return True, "Token is valid"

import os
import mmap

class StreamingParser:
    def __init__(self, file_path):
        self.file_path = file_path
        self.mmap_file = None

    def open(self):
        if not self.mmap_file:
            self.mmap_file = mmap.map_file(self.file_path, access=mmap.ACCESS_READ)
        return self.mmap_file

    def read(self, size=1024):
        try:
            if self.mmap_file is None or self.mmap_file.size() < size:
                raise ValueError("File has ended")
            # Read from the map
            data = self.mmap_file.read(size)
            return data
        except mmap.error as e:
            print(f"Error: {e}")
            return None

    def close(self):
        if self.mmap_file:
            self.mmap_file.close()
            self.mmap_file = None


# Example usage:

if __name__ == "__main__":
    parser = StreamingParser("large_file.txt")

    # Open the file
    file_handle = parser.open()

    # Read 1024 bytes from the file
    data = parser.read(1024)
    while data:
        print(data.decode('utf-8'))
        data = parser.read(1024)

    # Close the file
    parser.close()

