import itertools

def sorted_search(results, field, ascending=True):
    if not field:
        return results

    sort_key = lambda result: getattr(result, field)
    sort_direction = 1 if ascending else -1

    return itertools.sorted(results, key=sort_key, reverse=sort_direction)

