from flask import Flask, jsonify, request, make_response
from functools import wraps
import jwt
import datetime
from flask_sqlalchemy import SQLAlchemy
from werkzeug.security import generate_password_hash, check_password_hash

app = Flask(__name__)

# Set up the database configuration
app.config['SECRET_KEY'] = 'your-secret-key'
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:////mnt/database.db'
app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = True

db = SQLAlchemy(app)

class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(50), unique=True)
    password = db.Column(db.String(80))

def token_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.args.get('token')  # http://localhost:5000/route?token=xxx

        if not token:
            return jsonify({'message': 'Token is missing!'}), 403

        try:
            data = jwt.decode(token, app.config['SECRET_KEY'])
        except:
            return jsonify({'message': 'Token is invalid!'}), 403

        return f(*args, **kwargs)

    return decorated

@app.route('/register', methods=['POST'])
def signup_user():
    data = request.get_json()

    hashed_password = generate_password_hash(data['password'], method='sha256')

    new_user = User(username=data['username'], password=hashed_password)
    db.session.add(new_user)
    db.session.commit()

    return jsonify({'message': 'registered successfully'})

@app.route('/login', methods=['POST'])
def login_user():
    auth = request.authorization

    if not auth or not auth.username or not auth.password:
        return make_response('Authentication failure', 401, {'WWW-Authenticate': 'Basic realm="Login required!"'})

    user = User.query.filter_by(name=auth.username).first()

    if check_password_hash(user.password, auth.password):
        token = jwt.encode({'user': auth.username, 'exp': datetime.datetime.utcnow() + datetime.timedelta(minutes=30)}, app.config['SECRET_KEY'])
        return jsonify({'token': token})

    return make_response('Authentication failure', 401, {'WWW-Authenticate': 'Basic realm="Login required!"'})

@app.route('/user', methods=['GET'])
@token_required
def get_all_users():
    users = User.query.all()
    output = []

    for user in users:
        user_data = {}
        user_data['id'] = user.id
        user_data['username'] = user.username
        user_data['password'] = user.password
        output.append(user_data)

    return jsonify({'users': output})

import os
import shutil
import pickle

# Define the disaster recovery plan
recovery_plan = {
    "source_directory": "/path/to/source/directory",
    "backup_directory": "/path/to/backup/directory",
    "exclude_files": ["exclude.txt"],
    "restore_files": ["restore.txt"]
}

# Function to backup files
def backup_files():
    for filename in os.listdir(recovery_plan["source_directory"]):
        if filename not in recovery_plan["exclude_files"]:
            shutil.copy2(
                os.path.join(recovery_plan["source_directory"], filename),
                os.path.join(recovery_plan["backup_directory"], filename)
            )

# Function to restore files
def restore_files():
    for filename in os.listdir(recovery_plan["backup_directory"]):
        if filename in recovery_plan["restore_files"]:
            shutil.copy2(
                os.path.join(recovery_plan["backup_directory"], filename),
                os.path.join(recovery_plan["source_directory"], filename)
            )

# Function to save the recovery plan
def save_recovery_plan():
    with open("recovery_plan.pkl", "wb") as f:
        pickle.dump(recovery_plan, f)

# Function to load the recovery plan
def load_recovery_plan():
    with open("recovery_plan.pkl", "rb") as f:
        return pickle.load(f)

# Create the backup directory if it doesn't exist
if not os.path.exists(recovery_plan["backup_directory"]):
    os.makedirs(recovery_plan["backup_directory"])

# Save the recovery plan
save_recovery_plan()

# Run the backup and restore functions
backup_files()
restore_files()

