    print('Connection closed')

def create_table(conn):
    try:
        query = """ CREATE TABLE IF NOT EXISTS items (
                    id integer PRIMARY KEY,
                    name text NOT NULL,
                    quantity integer
                ); """

        cursor = conn.cursor() # cursor object helps us execute SQL statements
        cursor.execute(query)
        print('Table created successfully')
    except Error as e:
        print(e)

def insert_into_table(conn, id, name, quantity):
    try:
        query = """ INSERT INTO items(id,name,quantity) VALUES (?,?,?) """

        cursor = conn.cursor()
        cursor.execute(query, (id, name, quantity))
        conn.commit() # commits the current transaction
        print('Data inserted successfully')
    except Error as e:
        print(e)

def main():
    database = create_connection()

    if database is not None:
        create_table(database)
        insert_into_table(database, 1, 'Item One', 50)
        close_connection(database)
    else:
        print('Error occurred while creating connection')

