import socket
import select
import struct
from typing import Tuple, Any

class WebSocketParser:
    def __init__(self, host: str = 'localhost', port: int = 80):
        self.host = host
        self.port = port
        self.socket = None

    def create_socket(self):
        self.socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)

    def connect_to_server(self):
        self.socket.connect((self.host, self.port))

    def receive_data(self) -> Tuple[bytes, bool]:
        readable_sockets, _, _ = select.select([self.socket], [], [])
        if not readable_sockets:
            return b'', False

        data = bytearray()
        while True:
            chunk = self.socket.recv(8192)
            if not chunk:
                break
            data.extend(chunk)

        try:
            return bytes(data), True
        except struct.error:
            return b'', False

    def send_message(self, message: str):
        # Encode the message in UTF-8 and add a WebSocket header
        encoded_message = f'HTTP/1.1 101 Switching Protocols\r\nContent-Type: text/html\r\n\r\n{message}'.encode('utf-8')
        self.socket.sendall(encoded_message)

    def parse_message(self, data: bytes) -> str:
        # Parse the WebSocket header
        header_length = struct.unpack('>I', data[:4])[0]
        header_end = 4 + header_length

        # Extract the message type and payload
        message_type = data[8]
        payload_start = 9

        # Handle the message type
        if message_type == b'':
            return f"Connection established"
        elif message_type in [b'\x80', b'\x7f']:
            length = struct.unpack('>i', data[payload_start:payload_start + 4])[0]
            payload = data[payload_start + 4 : payload_start + 4 + length]
            return payload.decode('utf-8')
        else:
            return "Invalid message type"

# Example usage
if __name__ == "__main__":
    parser = WebSocketParser()
    parser.create_socket()
    parser.connect_to_server()

    while True:
        data, is_readable = parser.receive_data()
        if not is_readable:
            break

        print(parser.parse_message(data))

