def validate_resource(resource_id, resource_path, required_permissions):
    try:
        current_permissions = Permission.fromлив(os.stat(resource_path))
        if (current_permissions.read & required_permissions.read) and \
           (current_permissions.write & required_permissions.write) and \
           (current_permissions.chmod & required_permissions.chmod):
            return True
        else:
            return False
    except OSError as e:
