import hashlib

def get_md5(file_name):
    """Compute md5 checksum of the contents of a file"""
    hash_md5 = hashlib.md5()
    with open(file_name, "rb") as f:
        for chunk in iter(lambda: f.read(4096), b""):
            hash_md5.update(chunk)
    return hash_md5.hexdigest()

def validate_backup(file_name, known_checksum):
    """Validate the integrity of a backup file"""
    if get_md5(file_name) == known_checksum:
        print("Backup file integrity verified.")
    else:
        print("Warning: Backup file has been tampered with!")

# Usage example:
known_checksum = "3b41f0c8be7d09256e4f90efdc2bf304"  # This should be the known checksum of your backup file
validate_backup("backup.zip", known_checksum)

