import crontab

# Get the current cron jobs
cron = crontab.CronTab()

# Create a dictionary to store the start times of each job
job_start_times = {}

# Iterate over each cron job
for job in cron:
    # Extract the start time of the job
    start_time = job.minute + " " + job.hour + " " + job.day_of_month + " " + job.month + " " + job.day_of_week

    # Add the start time to the dictionary
    job_start_times[job] = start_time

# Check for overlapping jobs
for job1 in cron:
    for job2 in cron:
        if job1 != job2 and job_start_times[job1] == job_start_times[job2]:
            # Remove the job with the later start time
            if job1.is_enabled():
                cron.remove_all(job1)
            else:
                cron.remove_all(job2)

# Save the updated cron jobs
cron.write()

import random
import time

def limitAPI(response_size=10, window_size=60):
    """API Rate Limiting decorator"""
    responses = 0
    last_reset = 0

    def decorator(func):
        def wrapper(*args, **kwargs):
            nonlocal responses, last_reset
            current_time = int(round(time.time()))

            if (current_time - last_reset) < window_size:
                # Check rate limits
                try:
                    response = func(*args, **kwargs)
                    responses += 1
                    if responses >= response_size:
                        reset_time = last_reset + window_size
                        print(f"Rate limited! Resolved {response_size} requests in the past {window_size}s. Next request after {reset_time - current_time} seconds.")
                        time.sleep(reset_time - current_time)
                        return response
                    else:
                        print(f"Allowed {responses}/{response_size}.")
                except Exception as e:
                    responses = 0
                    last_reset = current_time
                    print(f"API Error: {str(e)}. Trying again in a few seconds...")
                    if not func.__name__ == "get":
                        return None
            else:
                last_reset = current_time
            return response

        # Reset rate limits after successful response
        reset responses and last_reset inside wrapper function
        wrapper.reset = {
            'responses': 0,
            'last_reset': time.time()
        }

        return wrapper

    return decorator

def testAPI():
    @limitAPI(5, 60)
    def getWeather(currentCity):
        # Simulate API call - wait 2 seconds per request
        time.sleep(random.uniform(1, 3))
        print(f"Weather in {currentCity}: ", end="")
        if currentCity == "London":
            return {"temperature": 25, "condition": "sunny"}
        elif currentCity == "Paris":
            return {"temperature": 18, "condition": "cloudy"}
        else:
            return {"temperature": random.uniform(0, 30), "condition": "variable"}

    cities = ["London", "Paris", "New York", "Tokyo", "Sydney", "Dubai"]
    for city in cities:
        print(f"\nTesting {city}")
        result = getWeather(city)
        print(result)

testAPI()

