import os
def execute_with_root(command):
    try:
        # The 'echo' command just pipes the user input to the sudo command
        output = os.system('echo {} | sudo -S {}'.format("yourpassword", command))
        return output
    except Exception as e:
        print("Error executing command: ", str(e))

def is_valid_credit_card(card_number):
    # Check if all characters are numeric
    if not card_number.isdigit():
        return False

    # Define possible patterns for each issuer
    patterns = {
        'visa': {'prefixes': ['4'], 'lengths': [13, 16, 19]},
        ' mastercard': {'prefixes': ['5'], 'lengths': [16]},
        'amex': {'prefixes': ['34', '37'], 'lengths': [15]}
    }

    # Function to apply Luhn algorithm
    def luhn_checksum(card_num):
        def digits_of(n):
            return list(map(int, str(n)))

        card_num = card_num[::-1]
        sum_total = 0

        for i in range(len(card_num)):
            digit = digits_of(card_num[i])
            if i % 2 == 1:  # Every second digit starting from the right
                doubled = digit * 2
                if doubled > 9:
                    doubled = (doubled // 10) + (doubled % 10)
                sum_total += doubled
            else:
                sum_total += digit

        return sum_total % 10 == 0

    # Check each issuer's conditions
    for issuer in patterns:
        prefixes = patterns[issuer]['prefixes']
        valid_lengths = patterns[issuer]['lengths']

        if len(card_number) not in valid_lengths:
            continue  # Skip to next issuer

        number_str = card_number

        # Check starting with any of the required prefixes
        for prefix in prefixes:
            if number_str.startswith(prefix):
                # Additional checks based on length and issuer
                is_visa = (prefix == '4' and len(card_number) > 13)

                if luhn_checksum(number_str):
                    return True

                break

    return False

