import subprocess
import shlex

ALLOWED_COMMANDS = {
    'sudo', 'ls', 'git', 'cp', 'rm', 'mv',
    'python', 'pip', 'python3', 'sed', 'awk'
}

def execute_command(command):
    try:
        # Escape the command string to prevent shell injection
        quoted_command = shlex.quote(command)

        # Execute the command with safety measures
        subprocess.run(
            quoted_command,
            shell=False,  # Prevent shell features like brace expansion
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            shell=False,
            check=True  # Raises an error if command fails
        )
    except Exception as e:
        print(f"Error executing command: {e}")

# Example usage
if __name__ == "__main__":
    while True:
        try:
            cmd = input("Enter a system command (or 'exit' to quit): ").strip()
            if not cmd or cmd in ALLOWED_COMMANDS:
                execute_command(cmd)
            else:
                print(f"Command '{cmd}' is not allowed.")
        except KeyboardInterrupt:
            print("\nShutting down...")
            break

