from Crypto.Cipher import AES
from Crypto.Random import get_random_bytes
import base64

class AESCipher:
    def __init__(self, key):
        self.key = key

    def encrypt(self, data):
        cipher_config = AES.new(self.key, AES.MODE_EAX)
        cipher_text, tag = cipher_config.encrypt_and_digest(data)
        return base64.b64encode(cipher_text).decode('utf-8'), base64.b64encode(cipher_config.nonce).decode('utf-8'), base64.b64encode(tag).decode('utf-8')

    def decrypt(self, cipher_text, nonce, tag):
        try:
            cipher_config = AES.new(self.key, AES.MODE_EAX, nonce=base64.b64decode(nonce))
            plaintext = cipher_config.decrypt_and_verify(base64.b64decode(cipher_text), base64.b64decode(tag))
            return plaintext
        except:
            return False

