def validate_report_inputs(company_name, budget, number_of_team_members, 
                            project_duration, risk_assessment_score, incident_report_text,
                            draft):
    # Validate company name: must be a non-empty string with at least one letter/number
    if not isinstance(company_name, str) or len(company_name.strip()) == 0:
        raise ValueError("company_name must be a non-empty string containing letters or numbers")

    # Validate budget: must be a positive integer
    try:
        budget = int(budget)
    except ValueError:
        raise TypeError("budget must be an integer")
    if budget <= 0:
        raise ValueError("budget must be greater than zero")

    # Validate number of team members: non-negative integer (including zero)
    try:
        number_of_team_members = int(number_of_team_members)
    except ValueError:
        raise TypeError("number_of_team_members must be an integer")
    if number_of_team_members < 0:
        raise ValueError("number_of_team_members cannot be negative")

    # Validate project duration: non-negative integer (including zero)
    try:
        project_duration = int(project_duration)
    except ValueError:
        raise TypeError("project_duration must be an integer")
    if project_duration < 0:
        raise ValueError("project_duration cannot be negative")

    # Validate risk assessment score: integer between 1-5 inclusive
    try:
        risk_assessment_score = int(risk_assessment_score)
    except ValueError:
        raise TypeError("risk_assessment_score must be an integer")
    if not (1 <= risk_assessment_score <= 5):
        raise ValueError("risk_assessment_score must be between 1 and 5 inclusive")

    # Validate incident report text: only contains allowed characters
    allowed_characters = 'abcdefghijklmnopqrstuvwxyz0123456789_'
    for char in incident_report_text:
        if char not in allowed_characters or char == '"' or char == ',':
            raise ValueError(f"incident_report_text cannot contain invalid characters")

    # Validate draft parameter: must be boolean with exactly one True/False
    if draft not in [True, False]:
        raise TypeError("draft must be a boolean (either True or False)")

    # Generate filename
    try:
        # Replace spaces and commas with underscores to ensure filename validity
        sanitized_incident_report = incident_report_text.replace(' ', '_').replace(',', '_')
        filename = f"Report_{company_name}_"
        filename += f"Budget_{budget:}_{number_of_team_members}Team"
        filename += f"ProjectDuration_{project_duration:}"
        filename += f"RiskAssessment_{risk_assessment_score}" + \
                    f"_{draft}_IncidentReport_{sanitized_incident_report}.csv"

    except Exception as e:
        raise ValueError(f"Error generating filename: {e}")

    return filename

import socket
import select

HEADER_LENGTH = 10
IP = "127.0.0.1"
PORT = 1234

server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)

server_socket.bind((IP, PORT))
server_socket.listen()

sockets_list = [server_socket]
clients = {}

def receive_message(client_socket):
    try:
        message_header = client_socket.recv(HEADER_LENGTH)
        if not len(message_header):
            return False
        message_length = int(message_header.decode('utf-8').strip())
        return {"header": message_header, "data": client_socket.recv(message_length)}
    except:
        return False

while True:
    read_sockets, _, exception_sockets = select.select(sockets_list, [], sockets_list)
    for notified_socket in read_sockets:
        if notified_socket == server_socket:
            client_socket, client_address = server_socket.accept()
            user = receive_message(client_socket)
            if user is False:
                continue
            sockets_list.append(client_socket)
            clients[client_socket] = user
        else:
            message = receive_message(notified_socket)
            if message is False:
                print('Closed connection from: {}'.format(clients[notified_socket]['data'].decode('utf-8')))
                sockets_list.remove(notified_socket)
                del clients[notified_socket]
                continue
            user = clients[notified_socket]
            print(f'Received message from {user["data"].decode("utf-8")}: {message["data"].decode("utf-8")}')
            for client_socket in clients:
                if client_socket != notified_socket:
                    client_socket.send(user['header'] + user['data'] + message['header'] + message['data'])
    for notified_socket in exception_sockets:
        sockets_list.remove(notified_socket)
        del clients[notified_socket]

