def read_image(input_pdf_path):
    """Reads a single image from an input PDF."""
    try:
        with open(input_pdf_path, 'rb') as f:
            reader = PyPDF2.PdfReader(f)
            page = reader.pages[0]
            if hasattr(page, 'images'):
                images = page.images
                for img in images:
                    img_bytes = BytesIO()
                    image_array = bytes_to_image(img[3:])
                    img.frombytes(image_array, 'RGB', (img[0], img[1]))
                    temp_path = os.path.join('temp', f'image_{img[2]}_{img[3]}.png')
                    with open(temp_path, 'wb') as f:
                        img.save(f)
    except Exception as e:
        print(f"Error reading PDF: {e}")
        raise

def extract_images(input_pdf_path):
    """Extracts images from a PDF and saves them into the 'temp' directory."""
    try:
        temp_dir = os.path.join(os.getcwd(), 'temp')
        if not os.path.exists(temp_dir):
            os.makedirs(temp_dir)

        input_pdf = os.path.abspath(input_pdf_path)
        reader = PyPDF2.PdfReader(input_pdf)
        for i in range(len(reader.pages)):
            page = reader.pages[i]
            width, height = page MediaBox.width, page.MediaBox.height

            if hasattr(page, 'images'):
                images = page.images
                for j in range(len(images)):
                    img_w, img_h = images[j][0], images[j][1]
                    bytes = BytesIO()
                    image_array = bytes_to_image(images[j][3:])
                    img = Image.new('RGB', (img_w, img_h), (0, 0, 0))
                    img.frombytes(image_array, 'RGB', (img_w, img_h))
                    temp_path = os.path.join('temp', f'image_{i+1}_{j}.png')
                    with open(temp_path, 'wb') as f:
                        img.save(f)
    except Exception as e:
        print(f"Error extracting images: {e}")
        raise

def bytes_to_image(data):
    """Converts image data to a BytesIO object."""
    return Image.open(BytesIO(data))

def create_empty_pdf(images_in_temp_dir):
    """Creates an empty PDF containing all extracted images."""
    temp_dir = os.path.join(os.getcwd(), 'temp')

    images = []
    for file in os.listdir(temp_dir):
        if file.lower().endswith('.png'):
            image_path = os.path.join(temp_dir, file)
            try:
                img = Image.open(image_path)
                images.append(img)
            except Exception as e:
                print(f"Error loading image {image_path}: {e}")

    # Create a composite PDF
    composite = Image.new('RGB', (0, 0), None)
    for img in reversed(images):
        composite.paste(img, mask=img.getmask())

    output_path = os.path.join(os.getcwd(), 'empty.pdf')
    composite.save(output_path)

def main():
    import sys
    input_pdf_path = sys.argv[1]
    try:
        extract_images(input_pdf_path)
        create_empty_pdf()
    except Exception as e:
        print(f"Error: {e}")
        return

if __name__ == '__main__':
    main()

