import socket

def connect_to_device(ip_address, port):
    try:
        # Create a TCP/IP socket
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        # Set the timeout value for the connection attempt to 5 seconds
        sock.settimeout(5)

        # Try to connect to the device
        result = sock.connect_ex((ip_address, port))

        if result == 0:
            print("Connected successfully.")
            # Add your code here for communication with the device
        else:
            print(f"Failed to connect to {ip_address}:{port}. Device is offline or unreachable.")
    except socket.gaierror:
        print(f"Failed to resolve hostname {ip_address}.")
    except socket.error as e:
        print("A socket error occurred:", str(e))

