import logging
from requests import Session
import sys

logger = logging.getLogger(__name__)

def log_activity(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        target_func_name = func.__name__
        logger.info(f"Starting {target_func_name}")

        try:
            response = func(*args, **kwargs)
            status_code = response.status_code

            if status_code == 422:  # Unauthorized
                auth_header = kwargs.get('auth', None)

                if isinstance(auth_header, list):
                    for auth in auth_header:
                        if ':' in auth:
                            basic_auth, digest_auth = auth.split(':', 1)
                            if basic_auth.strip() == '':
                                user = digEST_auth.strip().strip('"')
                            elif digest_auth.strip() == '':
                                user = basic_auth.strip()

                            if user.strip():
                                logger.error(f"Missing username for request: {response.request.url}?{auth}")
                                return

                # If no auth info or couldn't extract username, check query params
                params = kwargs.get('params', {})
                session_params = response.headers.get('session').params if hasattr(response.headers, 'session') and hasattr(response.headers.session, 'params') else None

                for param in ['username', 'user-agent']:
                    if param in params:
                        user_value = params[param]

                        # Try to extract username from user-agent string
                        if isinstance(user_value, str):
                            import re
                            pattern = r'(.+?)\s+(?:(?:Basic\.|Digest\.)([^\s]+))'
                            match = re.search(pattern, user_value)
                            if match:
                                username = match.group(1).strip()
                                logger.error(f"Missing username in request: {response.request.url}?{auth=auth or ''}")
                                return

                        elif isinstance(user_value, dict):
                            username = next((v for k, v in user_value.items() if k == param), None)
                            if username is not None:
                                logger.error(f"Missing username in request: {response.request.url}?{auth=auth or ''}")
                                return

                # Check session params for username-like fields
                if session_params and 'username' in session_params:
                    user_session = session_params['username']
                    logger.error(f"Missing username in request: {response.request.url}?{auth=auth or ''}")
                    return

                logger.error(f"Unauthorized access to API endpoint {target_func_name}. Could not identify the user.")
            else:
                # For other exceptions, capture and log them
                exception_type = None
                if len(sys.exc_info()) == 3:
                    _, exc, tb = sys.exc_info()
                    error_type = type(exc)
                else:
                    error_type = Exception

                if isinstance(error_type, (requests.exceptions.RequestException, requests.exceptions.UnknownAuthType)):
                    logger.error(f"Request to API endpoint {target_func_name} raised an exception: {str(exc)}")
                elif isinstance(error_type, type) and 'requests' in str(error_type).lower():
                    exc_str = str(exc)
                    logger.error(f"An error occurred during request to API endpoint {target_func_name}: {exc_str}")
                else:
                    logger.error(f"Request failed for API endpoint {target_func_name}: An unexpected error occurred.")
        except Exception as e:
            logger.error(f"Unexpected error while calling function {func.__name__}: {str(e)}")

        return response
    return wrapper

