import time
from collections import deque

class RateLimiter:
    def __init__(self, max_requests, per_seconds):
        self.max_requests = max_requests
        self.per_seconds = per_seconds
        self.timestamps = deque()

    def allow(self):
        current_time = time.time()
        while self.timestamps and (current_time - self.timestamps[0]) > self.per_seconds:
            # Remove requests older than per_seconds
            self.timestamps.popleft()

        if len(self.timestamps) < self.max_requests:
            self.timestamps.append(current_time)
            return True
        else:
            return False

def handle_nested_queries(data: dict, queries: list) -> any:
    """
    Handle nested queries on a python dictionary by traversing it with the given query list.

    :param data: The data to perform the queries on (dictionary)
    :param queries: A list of keys/indices for navigating through the layers of the data structure
    :return: The retrieved value or None if not found
    """
    # Making a copy of the data to prevent any modifications to the original data
    temp_data = data.copy()

    try:
        for query in queries:
            temp_data = temp_data[query]  # Traversing through each layer of data
        return temp_data
    except (KeyError, TypeError):
        return None  # Handling any errors that might occur during the traversal (e.g., invalid key)

