import requests
from urllib.parse import urlencode

class SocialMediaShare:
    def __init__(self, message, url):
        self.message = message
        self.url = url

    def twitter(self):
        base_url = "https://twitter.com/intent/tweet?"
        params = {"text": self.message, "url": self.url}
        return base_url + urlencode(params)

    def facebook(self):
        base_url = "http://www.facebook.com/sharer/sharer.php?"
        params = {"u": self.url}
        return base_url + urlencode(params)

    def linkedin(self):
        base_url = "https://www.linkedin.com/shareArticle?mini=true&"
        params = {"title": self.message, "url": self.url}
        return base_url + urlencode(params)

def test_sharing():
    message = "Check out this article!"
    url = "http://example.com/article1"
    sms = SocialMediaShare(message, url)

    try:
        response = requests.get(sms.twitter())
        if response.status_code == 200:
            print("Twitter share link created successfully.")
        else:
            print("Failed to create Twitter share link.")
    except Exception as e:
        print(f"An error occurred while creating the Twitter share link: {e}")

    try:
        response = requests.get(sms.facebook())
        if response.status_code == 200:
            print("Facebook share link created successfully.")
        else:
            print("Failed to create Facebook share link.")
    except Exception as e:
        print(f"An error occurred while creating the Facebook share link: {e}")

    try:
        response = requests.get(sms.linkedin())
        if response.status_code == 200:
            print("LinkedIn share link created successfully.")
        else:
            print("Failed to create LinkedIn share link.")
    except Exception as e:
        print(f"An error occurred while creating the LinkedIn share link: {e}")

if __name__ == "__main__":
