# Validation blacklist
Blacklist = {' common passwords '}

def validate(username, password):
    if not username or not password:
        return False
    for black in Blacklist:
        if black in username.lower() or black in password.lower():
            return False
    return True

@app.route('/users', methods=['GET'])
def get_users():
    users = User.query.all()
    return jsonify([u.to_dict() for u in users])

@app.route('/users', methods=['POST'])
def create_user():
    data = request.json
    if not validate(data['name'], data['email']):
        return jsonify({'error': 'Invalid name or email'}), 422

    try:
        user = User(**data)
        db.session.add(user)
        db.session.commit()
        return jsonify(user.to_dict()), 201
    except Exception as e:
        db.session.rollback()
        return jsonify({'error': str(e)}), 500

# ... other routes for PUT, DELETE, etc.

@app.route('/users/<int:user_id>', methods=['PUT', 'PATCH'])
def update_user(user_id):
    try:
        user = User.query.get_or_404(user_id)
        data = request.json
        if not validate(data['name'], data['email']):
            return jsonify({'error': 'Invalid name or email'}), 422

        for key, value in data.items():
            setattr(user, key, value)

        db.session.commit()
        return jsonify(user.to_dict())
    except Exception as e:
        db.session.rollback()
        return jsonify({'error': str(e)}), 500

@app.route('/users/<int:user_id>', methods=['DELETE'])
def delete_user(user_id):
    try:
        user = User.query.get_or_404(user_id)
        db.session.delete(user)
        db.session.commit()
        return jsonify({'message': 'User deleted successfully'}), 200
    except Exception as e:
        db.session.rollback()
        return jsonify({'error': str(e)}), 500

if __name__ == '__main__':
    with app.test_context():
        db.create_all()
        app.run(debug=True)

