import sys

# Initialize colorama
init()

def process_line(line, keywords):
    """Process a line of text and highlight matching keywords."""
    for word in line.split():
        if word.lower() in [keyword.lower() for keyword in keywords]:
            yield f"{Fore.GREEN}{word}{Style.RESET_ALL}"
        else:
            yield word

def main():
    # Read keywords from 'keywords.txt'
    keywords = set()
    try:
        with open('keywords.txt', 'r') as file:
            keywords = {keyword.strip() for keyword in file}
    except FileNotFoundError:
        print("Keywords file not found.")
        return

    # Process each line of input
    for line in sys.stdin:
        processed_line = []
        for word in line.split():
            if word.lower() in [k.lower() for k in keywords]:
                processed_word = f"{Fore.GREEN}{word}{Style.RESET_ALL}"
            else:
                processed_word = word
            processed_line.append(processed_word)

        # Join the words to form the complete line
        highlighted_line = ' '.join(processed_line)
        print(highlighted_line)

