import re

def validate_metadata(metadata):
    required_fields = {
        "title": {"min_length": 5, "allowed_chars": "a-zA-Z_"},
        "description": {"min_length": 100, "allowed_chars": "a-zA-Z\\w -", "max_hyphens": 2},
        "category": {"min_length": 1, "max_length": 3, "no_underscores": True},
        "version": {"min_length": 7, "allowed_chars": "a-zA-Z0-9"}
    }

    for field, criteria in required_fields.items():
        value = metadata.get(field)
        if not value:
            return False, f"Missing required field: {field}"

        # Check min length
        if len(value) < criteria["min_length"]:
            return False, f"{field} does not meet minimum length requirement ({criteria['min_length']})."

        # Check allowed characters
        pattern = re.compile(criteria["allowed_chars"])
        if not pattern.match(str(value).lower()):
            return False, f"{field} contains invalid characters."

        # Handle category specific checks
        if field == "category":
            filtered_value = value.replace("_", "")
            if len(filtered_value) != criteria["min_length"] or len(filtered_value) > criteria["max_length"]:
                return False, f"Category must be exactly {criteria['min_length']} to {criteria['max_length']} characters."

        # Handle version specific checks
        if field == "version":
            pattern = re.compile("[a-zA-Z0-9]{", criteria["min_length"] + 1)
            if not pattern.match(str(value)):
                return False, f"Version must contain at least {criteria['min_length']} alphanumeric characters."

    return True, "Metadata validation successful!"

