class Queue:
    def __init__(self):
        self.queue = []

    def enqueue(self, item):
        self.queue.append(item)

    def dequeue(self):
        if not self.is_empty():
            return self.queue.pop(0)
        else:
            return None

    def is_empty(self):
        return len(self.queue) == 0

    def scale_queue(self, factor):
        new_queue = [item for item in self.queue]
        new_queue *= factor
        self.queue = new_queue


# Test the Queue class
