queue.enqueue(1)
queue.enqueue(2)
queue.enqueue(3)

print("Original queue:", queue.queue)  # Output: [1, 2, 3]

queue.scale_queue(2)
print("Scaled queue:", queue.queue)  # Output: [1, 2, 4, 5, 6]

queue.scale_queue(0.5)
print("Scaled queue:", queue.queue)  # Output: [0.5, 1, 1.0, 2.0, 3.0]

import sqlite3
from sqlite3 import Error

def create_connection():
    conn = None;
    try:
        conn = sqlite3.connect(':memory:')       # Create in-memory database for this example
        print(sqlite3.version)
    except Error as e:
        print(e)
    return conn

def execute_transaction(conn, query):
    try:
        cursor = conn.cursor()
        cursor.execute('BEGIN TRANSACTION')   # Start transaction
        cursor.execute(query)                  # Execute query
        conn.commit()                          # Commit changes to database
        print("Transaction committed successfully")
    except Error as e:
        conn.rollback()                       # Roll back changes if error occurred
        print(f"The transaction has been rolled back due to an error: {e}")

def main():
    connection = create_connection()
    if connection is not None:
        # Creating a new table for this example
        execute_transaction(connection, '''CREATE TABLE IF NOT EXISTS employees (id integer PRIMARY KEY, name text NOT NULL)''')
        # Inserting a record into the database.
        execute_transaction(connection, "INSERT INTO employees(name) VALUES('John Doe')")
    else:
        print("Error! Cannot create the database connection.")

if __name__ == '__main__':
    main()

import json

def restricted_query(query, max_depth):
    """Restricts the query depth to a maximum value."""
    if len(json.dumps(query).split()) <= max_depth:
        return query
    else:
        raise Exception("Query depth exceeded maximum allowed value")

import hashlib
import secrets
import string
from datetime import datetime

def generate_session_id():
    """Generate a random session ID"""
    return ''.join(secrets.choice(string.ascii_letters + string.digits) for _ in range(32))

def hash_session_id(session_id):
    """Hash the session ID with SHA-256"""
    return hashlib.sha256(session_id.encode()).hexdigest()

def verify_session_id(user_input, stored_session_id):
    """Verify if user input matches the stored session ID"""
    if not user_input:
        return False

    # Hash both inputs and compare
    hashed_user_input = hash_session_id(user_input)
    hashed_stored_session_id = hash_session_id(stored_session_id)

    return hashed_user_input == hashed_stored_session_id

# Example usage:
user_input = input("Enter your session ID: ")
stored_session_id = generate_session_id()

if verify_session_id(user_input, stored_session_id):
    print("Session ID verified")
else:
    print("Invalid session ID")

import collections
from collections import defaultdict

class Cache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.cache_dict = collections.OrderedDict()

    def get(self, key):
        if key in self.cache_dict:
            return self.cache_dict[key]['value']
        else:
            return -1  # Return a default value if key not found

    def put(self, key, value):
        if key in self.cache_dict:
            del self.cache_dict[key]
        elif len(self.cache_dict) >= self.capacity:
            self.cache_dict.popitem(last=False)
        self.cache_dict[key] = {'value': value}

class LRU Cache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.cache = Cache(capacity)

    def get(self, key):
        return self.cache.get(key)

    def put(self, key, value):
        self.cache.put(key, value)

# Example usage:

cache = LRUCache(2)
cache.put('key1', 'value1')
cache.put('key2', 'value2')
print(cache.get('key1'))  # Output: 'value1'
cache.put('key3', 'value3')  # evicts key2
print(cache.get('key2'))  # Output: -1 (not found)

