import jwt
from flask import Flask, request, jsonify
from functools import wraps

app = Flask(__name__)

# Secret key for JWT token
SECRET_KEY = b'your_secret_key'

# Function to generate a JWT token
def generate_token(username):
    payload = {
        'username': username,
        'exp': datetime.utcnow() + timedelta(hours=1)  # Token expiration time
    }
    token = jwt.encode(payload, SECRET_KEY, algorithm='HS256')
    return token

# Function to verify a JWT token
def verify_token(func):
    @wraps(func)
    def decorated_function(*args, **kwargs):
        token = request.headers.get('Authorization')
        if not token:
            return jsonify({'error': 'Missing token'}), 401
        try:
            payload = jwt.decode(token, SECRET_KEY, algorithms=['HS256'])
            return func(payload['username'], *args, **kwargs)
        except jwt.ExpiredSignatureError:
            return jsonify({'error': 'Token expired'}), 401
        except jwt.InvalidTokenError:
            return jsonify({'error': 'Invalid token'}), 401
    return decorated_function

# Example API endpoint
@app.route('/protected', methods=['GET'])
@verify_token
def protected_endpoint(username):
    return jsonify({'message': f'Hello, {username}'})

if __name__ == '__main__':
    app.run(debug=True)

from urllib3.client import RateLimiter

def limit_requests(max_limit=10, window_size=1):
    limiter = RateLimiter(initial_checks=[("HTTP_X_FORWARDED_PROTO", "https")], window_size=window_size)

    def rate_limited(request):
        try:
            yield request  # Process the request
        except StopIteration:
            return

    with limiter as limiter_context:
        for req in rate_limited(requests_iterator):  # Replace with actual requests
            pass

    raise RuntimeError("Rate limiting exceeded") from None

