def secure_refund(
    original_balance,
    transaction_amount,
    tax_rate=0,
    payment_method_type='credit_card',
    refund_status='processing'
):
    """
    Handles the refund process securely by calculating the new balance after a refund.

    Args:
        original_balance (float|int): The current account balance.
        transaction_amount (float|int): The amount of the transaction to be refunded.
        tax_rate (float|int, optional): Tax rate applied for transactions. Defaults to 0.
        payment_method_type (str, optional): Type of payment method ('credit_card', 'bank_transfer'). Defaults to 'credit_card'.
        refund_status (str, optional): Status indicating if the refund is processed or pending. Options: 'processing' or 'completed'. Defaults to 'processing'.

    Returns:
        tuple: A tuple containing the new balance and an integer status code indicating the transaction's success.
              Possible status codes: 0 - success; 1 - invalid request; 2 - insufficient funds.

    Raises:
        ValueError: If any of the input parameters are invalid or if there's a calculation error.
    """
    try:
        # Input validation
        if not isinstance(original_balance, (int, float)):
            raise ValueError("Original balance must be an integer or float.")

        if transaction_amount <= 0:
            return (original_balance, 1)  # Refund amount can't be zero or negative

        valid_payment_methods = {'credit_card', 'bank_transfer'}
        if payment_method_type not in valid_payment_methods:
            raise ValueError(f"Invalid payment method type: {payment_method_type}.")

        if tax_rate < 0 or isinstance(tax_rate, str):
            raise ValueError("Tax rate must be a non-negative number.")

        # Calculate new balance
        new_balance = original_balance - transaction_amount

        # Add tax if applicable
        if tax_rate > 0:
            total_amount_with_tax = (transaction_amount + 
                                    transaction_amount * tax_rate)
            if payment_method_type == 'credit_card':
                # Apply sales tax for credit card transactions
                new_balance += total_amount_with_tax
            else:
                # For bank transfers, apply only service fees without tax
                new_balance -= transaction_amount

        # Determine the status
        if refund_status == 'processing':
            return (new_balance, 0)
        elif refund_status == 'completed':
            return (new_balance, 0)  # No change to balance on successful completion
    except ValueError as e:
        print(f"Error handling refund: {e}")
        return (original_balance, 1)
    except Exception as e:
        print(f"Unexpected error in refund calculation: {e}")
        return (original_balance, 2)

