# User class
class User:
    def __init__(self, username, password, role):
        self.username = username
        self.password = password
        self.role = role

# Resource class 
class Resource:
    def __init__(self, name, access_level):
        self.name = name
        self.access_level = access_level

# Access Levels for Roles 
ACCESS_LEVELS = {
    "admin": 3,
    "user": 2,
    "guest": 1
}

users = [User("admin", "password", "admin"), User("user", "password", "user"), User("guest", "password", "guest")]
resources = [Resource("File1", 3), Resource("File2", 2), Resource("File3", 1)]

def authenticate_user(username, password):
    for user in users:
        if user.username == username and user.password == password:
            return user
    return None

def authorize_resource(user, resource):
    required_access_level = resource.access_level
    user_role_access_level = ACCESS_LEVELS[user.role]

    if user_role_access_level >= required_access_level:
        return True
    else:
        return False

def access_resource(username, password, resource):
    user = authenticate_user(username, password)
    if user is None:
        print("Authentication failed.")
        return False

    for res in resources:
        if res.name == resource:
            authorized = authorize_resource(user, res)
            if authorized:
                print("Access granted to", username,"for the resource -", resource)
            else:
                print("Access denied to",username,"for the resource -", resource)

access_resource("admin", "password", "File1")  # Access Granted 
access_resource("user", "password", "File2")   # Access Granted
access_resource("guest", "password", "File3")  # Access Denied

def check_depth(dictionary, max_depth=10):
    def _check_depth(_dict, _max_depth, current_depth=1):
        if current_depth > _max_depth:
            raise ValueError('Maximum depth exceeded')

        for value in _dict.values():
            if isinstance(value, dict):
                _check_depth(value, _max_depth, current_depth + 1)

    _check_depth(dictionary, max_depth)

