# Simple token bucket implementation for rate limiting
class TokenBucket:
    def __init__(self, capacity, fill_rate):
        self.capacity = float(capacity)
        self.tokens = capacity
        self.fill_rate = float(fill_rate)
        self.last_refill_time = time.time()

    def consume(self, tokens=1):
        current_time = time.time()
        if (current_time - self.last_refill_time) > 0:
            refill = (current_time - self.last_refill_time) * self.fill_rate
            self.tokens = min(self.capacity, self.tokens + refill)
        if tokens <= self.tokens:
            self.tokens -= tokens
            self.last_refill_time = current_time
            return True
        else:
            print("Too many requests")
            return False

# Decorator for rate limiting and user authentication
def secure(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        # Check for valid username/password pair
        if args[0] not in USERS or hashlib.sha256(args[1].encode()).hexdigest() != USERS[args[0]]:
            return "Invalid credentials"

        # Rate limit the requests (100 per minute)
        if not TOKEN_BUCKET.consume():
            return "Too many requests"

        # Execute the function if all checks pass
        return func(*args, **kwargs)
    return wrapper

