import time

class Session:
    def __init__(self):
        self.sessions = {}  # Dictionary to hold sessions

    def create_session(self, user_id):
        session_id = str(user_id) + '_' + str(time.time())
        self.sessions[session_id] = {'timestamp': time.time(), 'user_id': user_id}
        return session_id

    def is_valid_session(self, session_id, timeout=300):  # Timeout in seconds (default: 5 minutes)
        if session_id in self.sessions:
            last_active = self.sessions[session_id]['timestamp']
            return time.time() - last_active < timeout
        else:
            return False

    def update_session(self, session_id):
        if session_id in self.sessions:
            self.sessions[session_id]['timestamp'] = time.time()

# Usage example:
