user_id = '123'
session_id = sess.create_session(user_id)
print("Session created:", session_id)

# Check if session is valid (within timeout limit)
time.sleep(60)  # Simulate inactivity for 60 seconds
if not sess.is_valid_session(session_id):
    print("Session expired")
else:
    print("Session still active")

class Buffer:
    def __init__(self, size):
        self.size = size
        self.data = bytearray(size)
        self.index = 0

    def write(self, new_data):
        if len(new_data) > self.available():
            raise BufferError("Not enough space in buffer")

        self.data[self.index:self.index + len(new_data)] = new_data
        self.index += len(new_data)

    def available(self):
        return self.size - self.index

