import os
import datetime

class Tenant:
    def __init__(self, id, limit):
        self.id = id
        self.limit = limit
        self.used = 0

    def use_resource(self, amount):
        if amount > self.limit - self.used:
            return False
        else:
            self.used += amount
            return True


class ResourceLimitEnforcer:
    def __init__(self):
        self.tenants = {}
        self.resources = {}

    def add_tenant(self, id, limit):
        tenant = Tenant(id, limit)
        self.tenants[id] = tenant

    def add_resource(self, name, limit):
        resource = {"limit": limit}
        self.resources[name] = resource

    def enforce_limit(self, tenant_id, resource_name, amount):
        if resource_name in self.resources:
            tenant = self.tenants.get(tenant_id)
            if tenant and tenant.use_resource(amount):
                return True
            else:
                print(f"Insufficient resources for tenant {tenant_id} for resource {resource_name}")
                return False

    def get_resource_limit(self, tenant_id, resource_name):
        return self.resources[resource_name]["limit"]


# Example usage:

enforcer = ResourceLimitEnforcer()

# Add tenants
enforcer.add_tenant("tenant1", 100)
enforcer.add_tenant("tenant2", 200)

# Add resources
enforcer.add_resource("cpu", 50)
enforcer.add_resource("memory", 20)

# Enforce limit for tenant1
print(enforcer.enforce_limit("tenant1", "cpu", 10))  # Output: True
print(enforcer.get_resource_limit("tenant1", "cpu"))  # Output: 40

# Enforce limit for tenant2
print(enforcer.enforce_limit("tenant2", "memory", 10))  # Output: True
print(enforcer.get_resource_limit("tenant2", "memory"))  # Output: 10

import requests
import time
from urllib.parse import urlencode

def get_report(apikey, resource):
    params = {'apikey': apikey, 'resource': resource}
    response = requests.get('https://www.virustotal.com/vtapi/v2/file/report',params=urlencode(params))
    json_response = response.json()

    if "scans" in json_response:
        return json_response["scans"]

    else: 
        print("The requested file is not present in VirusTotal's dataset, a new analysis is started")
        params={'apikey': apikey,'resource': resource}
        response = requests.post('https://www.virustotal.com/vtapi/v2/file/scan',params=urlencode(params))
        json_response = response.json()

        while True:  # keep checking for report until we get it
            time.sleep(30)
            print("Checking for report...")
            if "scans" in get_report(apikey, resource):
                break

        return get_report(apikey,resource)  

def check_file(filename, apikey):
    with open(filename,'rb') as f:  # read as binary to not miss some files
        print("Checking file:", filename)
        response = requests.post('https://www.virustotal.com/vtapi/v2/file/scan',files={'file':f},params={'apikey': apikey})

    json_response = response.json()  # convert response to JSON

    if json_response["response_code"] == 1:
        resource = json_response["resource"]
        print("Submitted. Getting report...")
        return get_report(apikey, resource)

    else: 
        print("Could not submit file")
        return False

