import random

class TradingOrder:
    def __init__(self, price, quantity):
        self.price = price
        self.quantity = quantity
        self.is_buy = False  # False for sell, True for buy

def apply_stop_loss(order, last_price, stop_loss_percent=0.5):
    """Apply stop-loss mechanism to limit potential losses."""
    if order.is_buy:
        min_price = last_price * (1 - stop_loss_percent)
        if order.price < min_price:
            return False
    else:
        max_price = last_price * (1 + stop_loss_percent)
        if order.price > max_price:
            return False
    return True

def dynamic_price_adjust(last_price, price_change, volatility=0.3):
    """Adjust prices dynamically based on volatility and change."""
    new_price = last_price * (1 + price_change)
    # Add a random fluctuation to mimic real market behavior
    random_factor = random.uniform(1 - volatility/2, 1 + volatility/2)
    adjusted_price = new_price * random_factor
    return max(last_price*(1 - volatility), min(last_price*(1 + volatility)), adjusted_price)

def prevent manipulation(trading_book, stop_loss=0.5):
    """Prevent price manipulation by applying safeguards."""
    if not trading_book:
        return False

    # Define recent prices for trend detection
    recent_prices = [order.price for order in trading_book.values()][-100:]  # last 100 orders

    # Calculate average and volatility
    avg_price = sum(recent_prices) / len(recent_prices)
    price_diffs = [abs(price - avg_price) for price in recent_prices]
    std_dev = (sum(price_diffs) ** 2) ** 0.5 / len(recent_prices)

    # Stop-loss application on new orders
    new_order = trading_book.get("new_order", None)
    if new_order:
        if apply_stop_loss(new_order, avg_price, stop_loss):
            pass
        else:
            # If price is out of bounds, do not allow manipulation
            return False

    # Dynamic adjustment for existing orders
    order_list = list(trading_book.items())
    random.shuffle(order_list)

    for _, order in order_list:
        if order.is_buy:
            new_price = dynamic_price_adjust(avg_price, 0.1, std_dev)
            adjusted_order = TradingOrder(new_price, order.quantity)
            trading_book[adjusted_order] = {
                'price': new_price,
                'quantity': order.quantity
            }
        else:
            new_price = dynamic_price_adjust(avg_price, -0.1, std_dev)
            adjusted_order = TradingOrder(new_price, order.quantity)
            trading_book[adjusted_order] = {
                'price': new_price,
                'quantity': order.quantity
            }

    return True

# Example usage
trading_book = {
    "new_order": {"price": 100.0, "quantity": 100},
    "order1": {"price": 98.5, "quantity": 200},
}

result = prevent_manipulation(trading_book)
print("Prevention successful:", result)

