    cur.execute(sql, transaction)
    return cur.lastrowid

def check_existing_transaction(conn, customer_id):
    cur = conn.cursor()
    cur.execute("SELECT * FROM transactions WHERE customer_id=?", (customer_id,))
    rows = cur.fetchall()
    return len(rows) > 0

def process_transaction(conn, transaction):
    if not check_existing_transaction(conn, transaction[0]):
        insert_transaction(conn, transaction)
        print("Transaction successful")
    else:
        print("Double charging attempt detected. Transaction declined.")

def main():
    database = r"pythonsqlite.db"

    sql_create_transactions_table = """ CREATE TABLE IF NOT EXISTS transactions (
                                            id integer PRIMARY KEY,
                                            customer_id text NOT NULL,
                                            amount real); """

    # create a database connection
    conn = create_connection()

    if conn is not None:
        # create transactions table
        create_table(conn, sql_create_transactions_table)
    else:
        print("Error! cannot create the database connection.")

    # Testing transactions
    transaction1 = ('CUST001', 50.00)
    transaction2 = ('CUST001', 60.00)   # Same customer id as transaction1, this will be declined as double charging

    process_transaction(conn, transaction1)
    process_transaction(conn, transaction2)

    close_connection(conn)

if __name__ == '__main__':
    main()

import uuid
from datetime import datetime, timedelta

# Session management class
class SessionManager:
    def __init__(self):
        self.sessions = {}

    # Function to create a new session
    def create_session(self):
        session_id = str(uuid.uuid4())
        self.sessions[session_id] = {
            "start_time": datetime.now(),
            "expiration_time": datetime.now() + timedelta(minutes=30),
            "active": True,
        }
        return session_id

    # Function to check if a session is valid
    def is_session_valid(self, session_id):
        if session_id in self.sessions:
            if self.sessions[session_id]["expiration_time"] > datetime.now():
                return True
        return False

    # Function to invalidate a session
    def invalidate_session(self, session_id):
        if session_id in self.sessions:
            self.sessions[session_id]["active"] = False
            self.sessions[session_id]["expiration_time"] = datetime.now()

    # Function to get the session data
    def get_session_data(self, session_id):
        if self.is_session_valid(session_id):
            return self.sessions[session_id]
        else:
            return None

    # Function to update the session expiration time
    def update_session_expiration(self, session_id):
        if self.is_session_valid(session_id):
            self.sessions[session_id]["expiration_time"] = datetime.now() + timedelta(minutes=30)

# Usage example
session_manager = SessionManager()

# Create a new session
session_id = session_manager.create_session()

# Check if the session is valid
is_valid = session_manager.is_session_valid(session_id)

# Get the session data
session_data = session_manager.get_session_data(session_id)

# Invalidate the session
session_manager.invalidate_session(session_id)

class TaskManager:
    def __init__(self):
        self.tasks = {}

    def add_task(self, task_name, task_description):
        """
        Adds a new task with its description.

        Args:
            task_name (str): Name of the task.
            task_description (str): Description of the task.
        """
        if task_name not in self.tasks:
            self.tasks[task_name] = task_description
            print(f"Task '{task_name}' added successfully.")
        else:
            print(f"Task '{task_name}' already exists.")

    def delete_task(self, task_name):
        """
        Deletes a task by its name.

        Args:
            task_name (str): Name of the task to be deleted.
        """
        if task_name in self.tasks:
            del self.tasks[task_name]
            print(f"Task '{task_name}' deleted successfully.")
        else:
            print(f"Task '{task_name}' not found.")

    def view_tasks(self):
        """
        Displays all tasks with their descriptions.
        """
        if not self.tasks:
            print("No tasks available.")
        else:
            for task, description in self.tasks.items():
                print(f"Task: {task}")
                print(f"Description: {description}")
                print("------------------------")


