class Queue:
    def __init__(self, max_size):
        self._data = []
        self.max_size = max_size
        self.size = 0

    def add(self, item):
        if self.size >= self.max_size:
            raise OverflowError("Queue is full")
        self._data.append(item)
        self.size += 1

    def remove(self):
        if self.size == 0:
            return None
        removed_item = self._data.pop(0)
        self.size -= 1
        return removed_item

    def __str__(self):
        return str(self._data)

# Example usage:
