import re

def process_text_file(input_filename, output_filename):
    """
    Process a malformed text file by skipping invalid lines, 
    replacing duplicate values with unique ones, and writing the 
    processed data to a new file.

    Args:
        input_filename (str): The name of the input text file.
        output_filename (str): The name of the output text file.
    """

    # Initialize an empty dictionary to store unique values
    unique_values = {}

    try:
        with open(input_filename, 'r') as file:
            for line in file:
                # Use regular expression to validate line format
                if re.match(r'^\S+$', line):
                    # Extract the value from the line
                    value = line.strip()

                    # Check if the value is already in the dictionary
                    if value not in unique_values:
                        unique_values[value] = True
                    else:
                        # Replace duplicate values with a unique one
                        value += '_duplicat_' + str(len(unique_values))

            # Write the processed data to the output file
            with open(output_filename, 'w') as file:
                for line in input_filename.split('\n'):
                    if line.strip():
                        file.write(line + '\n')

    except FileNotFoundError:
        print(f"File {input_filename} not found.")

    except Exception as e:
        print(f"An error occurred: {e}")


# Example usage
