import inspect

class AccessControl:
    def __init__(self):
        self.access_dict = {}

    def add_permission(self, object, method_name, permission_level):
        if object not in self.access_dict:
            self.access_dict[object] = {}
        if method_name not in self.access_dict[object]:
            self.access_dict[object][method_name] = []
        self.access_dict[object][method_name].append(permission_level)

    def check_permission(self, object, method_name, permission_level):
        if object not in self.access_dict:
            return False
        if method_name not in self.access_dict[object]:
            return False
        for level in self.access_dict[object][method_name]:
            if level == permission_level:
                return True
        return False

# Example usage:

class User:
    def __init__(self):
        self.permissions = AccessControl()

    def read_data(self):
        pass

    def write_data(self):
        pass

user1 = User()
user1.permissions.add_permission(user1, 'read_data', 'admin')
user1.permissions.add_permission(user1, 'write_data', 'moderator')

def test_read_user(user):
    if user.permissions.check_permission(user, 'read_data', 'user'):
        print("User can read their data")
    else:
        print("User cannot read their data")

test_read_user(user1)  # Output: User can read their data

def test_write_user(user):
    if user.permissions.check_permission(user, 'write_data', 'moderator') or user.permissions.check_permission(user, 'write_data', 'admin'):
        print("User can write their data")
    else:
        print("User cannot write their data")

test_write_user(user1)  # Output: User can write their data

import mimetypes

def is_executable(file):
    # Get the file type and extension
    filetype = mimetypes.guess_type(file)
    ext = os.path.splitext(file)[1]

    # Check if the file is executable
    if filetype == 'application/octet-stream' or ext == '.exe':
        return True
    else:
        return False

