class SocialMediaUpdater:
    def __init__(self, platform, api_token, account_id=None):
        self.platform = platform
        self.api_token = api_token
        self.account_id = account_id

    def post_update(self, message):
        if self.platform == 'twitter':
            self.twitter_post(message)
        elif self.platform == 'facebook':
            self.facebook_post(message)
        elif self.platform == 'instagram':
            self.instagram_post(message)

    def twitter_post(self, message):
        headers = {'Authorization': f'Bearer {self.api_token}'}
        data = {
            'status': message
        }
        response = requests.post('https://api.twitter.com/2/tweets', headers=headers, json=data)
        if response.status_code == 201:
            print(f"Tweet posted on Twitter: {message}")
        else:
            print(f"Failed to post tweet on Twitter: {response.text}")

    def facebook_post(self, message):
        headers = {'Authorization': f'Bearer {self.api_token}'}
        data = {
            'message': message
        }
        response = requests.post('https://graph.facebook.com/v13.0/me/feed', headers=headers, json=data)
        if response.status_code == 201:
            print(f"Post posted on Facebook: {message}")
        else:
            print(f"Failed to post on Facebook: {response.text}")

    def instagram_post(self, message):
        headers = {'Authorization': f'Bearer {self.api_token}'}
        data = {
            'caption': message
        }
        response = requests.post('https://graph.facebook.com/v13.0/me Media', headers=headers, json=data)
        if response.status_code == 201:
            print(f"Post posted on Instagram: {message}")
        else:
            print(f"Failed to post on Instagram: {response.text}")


