def repair_image(file_path, output_path='fixed_image.png'):
    img = image.load(file_path)
    threshold_low = 0.2
    threshold_high = 0.85

    # Detect corrupt pixels based on intensity
    mask = np.where((img < threshold_low) | (img > threshold_high))
    if not mask[0].any():
        return True  # No corruption found

    mean_val = img[mask].mean()

    # Replace corrupted pixels with mean value
    img[mask] = mean_val

    image.save(img, output_path)
    return False  # Corrupted and repaired

def repair_audio(file_path, output_path='fixed_audio.wav'):
    y, sr = sounddevice.read(file_path)

    # Simple noise reduction by thresholding
    y[abs(y) < 0.1 * np.max(abs(y))] = 0

    sounddevice.write(y, output_path, samplerate=sr)
    return False

def repair_video(videofile_path, output_path='fixed_video.mp4'):
    clip = VideoFileClip(videofile_path)
    repaired_clip = clip.with_vfill()
    repaired_clip.write_videofile(output_path)
    return False

def detectCorruption(file_path):
    if is_image_file(file_path):
        img = image.load(file_path)
        corrupted_pixels = np.where((img < 0.2) | (img > 0.85))
        num_corrupted = len(corrupted_pixels[0])
        return {'type': 'image', 'corrupted_pixels': num_corrupted}
    elif is_audio_file(file_path):
        y, sr = sounddevice.read(file_path)
        zero_crossings = np.abs(np.diff(np.sign(y)))
        silent_segments = (zero_crossings < 100) & (np.max(abs(y)) < 0.1 * np.max(np.abs(y)))
        num_silent = np.sum(silent_segments)
        return {'type': 'audio', 'silent_segments': num_silent}
    elif is_video_file(file_path):
        clip = VideoFileClip(file_path)
        corrupted_frames = len(clip.fps) - len(clip.write_videofile('temp Corruption'))
        return {'type': 'video', 'corrupted_frames': corrupted_frames}

    return None

def repairMedia(file_path, output_path=None):
    result = detectCorruption(file_path)
    if not result:
        return file_path

    rep_type = 'image' if result['type'] == 'image' else result['type']
    if output_path is None:
        output_path = f'corrupted_{rep_type}_repaired'

    if rep_type == 'image':
        success = repair_image(file_path, output_path)
    elif rep_type == 'audio':
        success = repair_audio(file_path, output_path)
    else:  # video
        success = repair_video(file_path, output_path)

    return f"Final path: {output_path}"

# Example usage:
corrupted_file_path = 'path_to_corrupted_image.jpg'
fixed_file_path = repairMedia(corrupted_file_path, 'fixed_repaired_image.jpg')
print(f"File has been repaired. Check at {fixed_file_path}")

from PyPDF2 import PdfFileReader, utils

def validate_pdf(filepath):
    try:
        with open(filepath, 'rb') as f:
            pdf = PdfFileReader(f)
            if not pdf.getNumPages() > 0:
                return False  # Empty PDF file

            for page in range(pdf.getNumPages()):
                pdf.getPage(page)

    except utils.PdfReadError:
        return False  # Invalid PDF file

    except FileNotFoundError:
        return "File not found"

    return True  # Valid PDF file

