import hashlib
import hmac
import secrets

class SecureUserSession:
    def __init__(self, user_id):
        self.user_id = user_id
        self.session_key = self.generate_session_key()
        self.session_data = {}

    def generate_session_key(self):
        # Use a cryptographically secure pseudo-random number generator to generate a session key.
        salt = secrets.token_bytes(16)
        return hmac.new(salt, str(self.user_id).encode(), hashlib.sha256).digest()

    def create_session(self):
        # Create a new session by generating a new session key and storing it in the user's data.
        self.session_key = self.generate_session_key()
        self.session_data['session_key'] = self.session_key.hex()

    def update_session(self, key_value_pairs):
        # Update the existing session data with the provided key-value pairs.
        for key, value in key_value_pairs.items():
            if key == 'session_key':
                continue  # Don't update the session key.
            self.session_data[key] = value

    def verify_session(self, expected_session_key):
        # Verify the session key by comparing it with the provided expected session key.
        expected_session_key_bytes = bytes.fromhex(expected_session_key)
        salt = secrets.token_bytes(16)
        return hmac.compare_digest(hmac.new(salt, str(self.user_id).encode(), hashlib.sha256).digest(), expected_session_key_bytes)

    def get_session_data(self):
        # Return the session data as a dictionary.
        return self.session_data

# Example usage:
if __name__ == "__main__":
    user_id = "user123"
    secure_user_session = SecureUserSession(user_id)
    secure_user_session.create_session()
    print("Created new session.")

    key_value_pairs = {
        'session_key': 'some_new_session_key',
        'user_data': {'username': user_id}
    }
    secure_user_session.update_session(key_value_pairs)
    print("Updated session data.")

    expected_session_key_bytes = bytes.fromhex('some_expected_session_key')
    is_valid = secure_user_session.verify_session(expected_session_key_bytes)
    print(f"Session key verification result: {is_valid}")

    session_data = secure_user_session.get_session_data()
    print("Session data:", session_data)

import psutil
import time

class ServerPerformanceMonitor:
    def __init__(self):
        self.cpu_percent = None
        self.memory_percent = None
        self.disk_percent = None

    def get_cpu_usage(self):
        return psutil.cpu_percent(interval=1)

    def get_memory_usage(self):
        return psutil.virtual_memory().percent

    def get_disk_usage(self):
        return psutil.disk_usage('/').percent

    def monitor_performance(self):
        while True:
            self.cpu_percent = self.get_cpu_usage()
            self.memory_percent = self.get_memory_usage()
            self.disk_percent = self.get_disk_usage()

            print(f"CPU Usage: {self.cpu_percent}%")
            print(f"Memory Usage: {self.memory_percent}%")
            print(f"Disk Usage: {self.disk_percent}%")

            time.sleep(1)


if __name__ == "__main__":
    monitor = ServerPerformanceMonitor()
    monitor.monitor_performance()

