import time
from collections import deque

class TokenBucket:
    def __init__(self, tokens, fill_rate):
        self._tokens = tokens
        self._capacity = tokens
        self._fill_rate = fill_rate
        self._last_time = time.time()

    def consume(self, tokens):
        if tokens <= self._tokens:
            self._tokens -= tokens
        else:
            raise Exception('Insufficient number of tokens')

    def add(self):
        now = time.time()
        delta = self._fill_rate * ((now - self._last_time) / 1000)
        print(delta)
        self._tokens = min(self._capacity, self._tokens + delta)
        self._last_time = now

    def tryConsume(self, tokens):
        if tokens <= self._tokens:
            self.consume(tokens)
            return True
        else:
            return False

class LeakyBucket:
    def __init__(self, capacity, fill_rate):
        self._capacity = capacity
        self._fill_rate = fill_rate
        self._queue = deque() 

    def consume(self, tokens):
        if len(self._queue) + tokens > self._capacity:
            raise Exception('Insufficient bucket size')

        for _ in range(tokens):
            now = time.time()
            self._queue.append(now)

    def add(self):
        now = time.time()
        while len(self._queue) > 0:
            if now - self._queue[0] >= 1 / self._fill_rate:
                self._queue.popleft()
            else: 
                break

    def tryConsume(self, tokens):
        self.add()

        if len(self._queue) + tokens > self._capacity:
            return False

        for _ in range(tokens):
            now = time.time()
            self._queue.append(now)

        return True

