def allocate_memory(n):
    from array import array

    # Create an array of integers with n elements
    arr1 = array('i', [])  # 'i' represents a signed integer
    if n > 0:
        for i in range(n):
            arr1.append(i)

    size1 = len(arr1.tobytes())

    # Create an array of integers with twice as many elements
    arr2 = array('i', [])
    if 2 * n > 0:
        for i in range(2 * n):
            arr2.append(i)

    size2 = len(arr2.tobytes())

    return (size1, size2)

import re

def extract_key_value_pairs(text):
    pairs = []
    for match in re.findall(r'([^\s]+)\s*=\s*(\S+)', text):
        pairs.append({match[0]: match[1]})
    return pairs

def parse_fixed_width_file(filename, field_sizes):
    with open(filename) as f:
        lines = f.readlines()

    data = []

    for line in lines:
        record = {}
        start = 0
        for i, size in enumerate(field_sizes):
            field_name = 'field' + str(i+1)
            record[field_name] = line[start : start + size].strip()
            start += size
        data.append(record)

    return data

