import json

def validate_json(json_input, schema):
    try:
        data = json.loads(json_input)
    except json.JSONDecodeError:
        print("Invalid JSON format")
        return False

    for prop in schema["properties"]:
        required = schema.get("required", [])
        if prop not in required:
            continue

        expected_type = schema["properties"][prop]["type"]

        try:
            instance_value = data[prop]

            # Check type and additional constraints
            if isinstance(instance_value, expected_type):
                continue

            print(f"Invalid value for field '{prop}': Expected {expected_type}, got {type(instance_value)}")
            return False

        except KeyError:
            print(f"Missing required field: '{prop}'")
            return False

    return True

