import sys

class WebSocket:
    def __init__(self):
        self.window_size = 5  # Number of previous messages to compare
        self.message_thresholds = {
            'user_id': 20,       # Max difference in user ID between messages
            'message': 100,      # Max difference in message content length
            'timestamp': 60*1000,  # Max timestamp difference (in ms)
            'sourceIP': 5  # Max source IP difference (e.g., within same subnet)
        }
        self.messages = []       # Stores the last N messages to compare
        self.last_valid_diff = None  # Tracks the latest valid message differences
        self.block_counter = 0      # Counts consecutive blocked messages

    def rate_limit(self, message):
        if len(self.messages) >= self.window_size:
            self.messages.pop(0)

        current_diff = self._calculate_diff(message)

        for i in range(len(self.messages)):
            compared_message = self.messages[i]
            comp_diff = self._calculate_diff(compared_message)

            # Compare differences
            match = True
            for key, value in comp_diff.items():
                if not (value < self.message_thresholds[key]):
                    match = False
                    break

            if match:
                sys.stderr.write(f"Blocking message: {message}\n")
                self.block_counter += 1

                # Block consecutive messages with similar content
                for j in range(self.block_counter):
                    if len(self.messages) + j >= len(self.messages):
                        pass
                    else:
                        new_diff = self._calculate_diff(self.messages[len(self.messages)+j])
                        match = True
                        for key, value in new_diff.items():
                            if not (value < self.message_thresholds[key]):
                                match = False
                                break
                        if not match:
                            sys.exit(1)
                return

        # New valid message: reset counters and add to window
        if current_diff is None or all(key in current_diff for key, value in zip(current_diff.keys(), [v < td for v, td in zip(current_diff.values(), self.message_thresholds.values())])):
            sys.stdout.write(f"Accepted message: {message}\n")
            self.messages.append(message)
            self.last_valid_diff = current_diff
            self.block_counter = 0

        return

    def _calculate_diff(self, msg):
        if not hasattr(msg, 'dict') and isinstance(msg, dict):
            # Convert to dictionary for consistent comparison (if needed)
            msg = msg.dict

        diff = {}
        for key in self.message_thresholds:
            if key in msg:
                current_diff = abs(msg[key] - self.last_valid_diff.get(key, 0))
                diff[key] = current_diff
        return diff

    def run(self):
        import json
        while True:
            message = sys.stdin.readline().strip()
            WebSocket().rate_limit(message)

class MemoryStore:
    def __init__(self):
        self.store = {}

    def set(self, key, value):
        self.store[key] = value

    def get(self, key):
