import pandas as pd

# Kafka Config
kafka_params = {
    'bootstrap.servers': 'localhost:9092',
    'group.id': 'aggregator_group',
    'auto.offset.reset': 'earliest'
}

class Aggregator:
    def __init__(self):
        self.consumer = None
        self.topics = ['topic1', 'topic2']  # List of topics to aggregate

    def start_consumer(self):
        try:
            self.consumer = Consumer(kafka_params)
            self.consumer.subscribe(self.topics)

            while True:
                msg = self.consumer.poll(1.0)
                if msg is None:
                    continue
                elif msg.error():
                    print(f"Error occurred: {msg.error()}")
                else:
                    # Aggregate data here
                    # For demonstration purposes, we'll store the message in a pandas DataFrame.
                    df = pd.DataFrame({'key': [msg.key()], 'value': [msg.value().decode('utf-8')]})

                    # Process and aggregate data as needed (e.g., group by key).
                    print(df)
                self.consumer.commit(msg)

        except KeyboardInterrupt:
            self.consumer.commit(msg)
            self.consumer.close()

    def stop_consumer(self):
        if self.consumer:
            self.consumer.close()

# Example usage
if __name__ == '__main__':
    aggregator = Aggregator()
    aggregator.start_consumer()

