    password = input("Enter your password: ")

    access_token, refresh_token = auth.authenticate(username, password)
    if access_token:
        print(f"Access token: {access_token}")
        print(f"Refresh token: {refresh_token}")

from flask import Flask, jsonify, request
import jwt
import secrets
from datetime import datetime, timedelta

app = Flask(__name__)
app.config["SECRET_KEY"] = secrets.token_hex(16)

# Sample in-memory database for users
users = {
    "user1": {"password": "password123", "exp": int(datetime.now() + timedelta(days=30).timestamp())},
}

def verify_token(token):
    try:
        payload = jwt.decode(
            token, app.config["SECRET_KEY"], algorithms=["HS256"]
        )
        return payload
    except jwt.ExpiredSignatureError:
        return None
    except jwt.InvalidTokenError:
        return None

@app.route("/register", methods=["POST"])
def register():
    username = request.json.get("username")
    password = request.json.get("password")

    if username in users and users[username]["password"] == password:
        return jsonify({"message": "User already exists"}), 400
    else:
        user_id = secrets.token_hex(16)
        payload = {"exp": int(datetime.now() + timedelta(days=30).timestamp())}
        token = jwt.encode(payload, app.config["SECRET_KEY"], algorithm="HS256")
        users[username] = {
            "user_id": user_id,
            "password": password,
            "exp": int(datetime.now() + timedelta(days=30).timestamp()),
        }
        return jsonify({"token": token.decode("utf-8"), "message": "User created successfully"}), 201

@app.route("/login", methods=["POST"])
def login():
    username = request.json.get("username")
    password = request.json.get("password")

    if username in users and users[username]["password"] == password:
        payload = {"exp": int(datetime.now() + timedelta(days=30).timestamp())}
        token = jwt.encode(payload, app.config["SECRET_KEY"], algorithm="HS256")
        return jsonify({"token": token.decode("utf-8"), "message": "Login successful"}), 200
    else:
        return jsonify({"error": "Invalid credentials"}), 401

@app.route("/protected", methods=["GET"])
def protected():
    token = request.headers.get("Authorization")

    if not token or not verify_token(token):
        return jsonify({"error": "Unauthorized"}), 403

    return jsonify({"message": "Hello, authenticated user!"}), 200

if __name__ == "__main__":
    app.run(debug=True)

def recurring_payments(principal, annual_rate, loan_duration_years, n):
    monthly_rate = annual_rate / (100 * 12)
    total_periods = loan_duration_years * 12
    if n >= total_periods:
        return round(remaining_balance, 2)  # This would be zero

    # Calculate monthly payment
    monthly_payment = (principal * monthly_rate) / (1 - (1 + monthly_rate)**(-total_periods))

    remaining_balance = principal
    for month in range(n):
        interest = remaining_balance * monthly_rate
        principal_part = monthly_payment - interest
        remaining_balance -= principal_part

    return round(remaining_balance, 2)

