import time
from functools import wraps

def throttle(delay):
    """ Decorator that makes sure the function is not called more than once every delay seconds. """
    def decorator(func):
        last_called = [0]  # Keep track of last call time in a mutable object so it's retained between calls.
        @wraps(func)
        def wrapper(*args, **kwargs):
            elapsed = time.time() - last_called[0]
            if elapsed < delay:
                print(f"Throttling: Wait for {delay - elapsed} seconds...")
                time.sleep(delay - elapsed)
            result = func(*args, **kwargs)
            last_called[0] = time.time()
            return result
        return wrapper
    return decorator

@throttle(1)  # Wait at least 1 second between calls to this function.
def scrape(url):
    print(f"Scraping: {url}")
    # Your scraping logic here...

from flask import Flask
