# Define subjects and resources with attributes
class Subject:
    def __init__(self, id, username, email, role):
        self.id = id
        self.username = username
        self.email = email
        self.role = role
        self.attributes = {'id': id, 'username': username, 'email': email, 'role': role}

class Resource:
    def __init__(self, resource_id, allowed_attrs):
        self.resource_id = resource_id
        self.allowed_attrs = allowed_attrs
        # The rest of the attributes (beyond allowed_attrs) are considered part of the object's data
        self.object_attrs = {}

# Define access rules
def always_allowed(attr_value):
    return True

def specific(attr_name, attr_value):
    if attr_value in Resource.allowed_attrs:
        return True
    else:
        return False

def subset(attr_name):
    # Check all possible values for the attribute in allowed_attrs
    for allowed_value in Resource.allowed_attrs[attr_name]:
        if allowed_value == attr_value:
            return True
    return False

def deny_all(attr_name):
    return False


# Example of applying access control rules to decide if a subject can access a resource
def check_access(subject, resource):
    for rule in [always_allowed, specific, subset, deny_all]:
        # Check all applicable attributes for the resource
        allowed_attrs = []
        for attr_name in Resource.allowed_attrs:
            value = getattr(resource, attr_name)
            allowed_attrs.append((attr_name, value))

        for rule in (specific, subset):
            for attr_name, attr_value in allowed_attrs:
                if callable(rule) and rule(attr_value) and attr_name == subject.attributes[attr_name]:
                    return True
    # After checking all applicable rules: check always_allowed or deny_all
    return False  # default is to deny access


# Testing example
subject = Subject(1, "admin", "user@example.com", "admin")
resource = Resource(resource_id=1, allowed_attrs={
    'username': ['user1@example.com', 'user2@example.com'],
    'role': ['admin']
})

allowed_sub_attrs = ["username", "role"]

for attr_name in allowed_sub_attrs:
    setattr(subject, attr_name, getattr(resource, attr_name))

if check_access(subject, resource):
    print(f"Access granted for Subject with ID {subject.id}")
else:
    print(f"Access denied for Subject with ID {subject.id}")

