class Event:
    def __init__(self, value):
        self.value = value

    def __repr__(self):
        return f"Event({self.__dict__['value']})"

    def __eq__(self, other):
        return type(self) == type(other) and self.value == other.value


class Counter:
    def __init__(self):
        self.events = {}  # Maps event identifiers to their counters

    def add(self, event):
        identifier = id(event)
        count = self.events.get(identifier, 0)
        new_count = (count + event.value) % 2
        self.events[identifier] = new_count


def main():
    counter = Counter()
    event_a = Event(1)
    event_b = Event(1)

    # Trigger in different orders to test functionality

    print(counter.add(event_a))       # Should be 1 (event_a has been triggered once)
    print(counter.add(event_b))       # Should be 1 (event_b has been triggered once)

    counter.add(event_a)              # Now event_a is triggered again, total for event_a should wrap to 0
    print(counter.add(event_a))       # Should be 0

    counter.add(event_b)              # Event_b triggers twice in a row; both times it wraps back to 0
    print(counter.add(event_b))       # Should be 0


if __name__ == "__main__":
    main()

