# Set up logging configuration
logging.basicConfig(filename='cache_usage.log', level=logging.INFO, format='%(asctime)s - %(message)s')

class CacheMonitor:
    def __init__(self):
        self.cache_size = 0

    def get_cache_usage(self):
        # Get the current cache size in bytes
        mem_info = psutil.virtual_memory()
        total_size = mem_info.total / (1024.0 **3)

        # Calculate the percentage of cache used
        self.cache_size = mem_info.used / total_size * 100

        return self.cache_size

    def log_cache_usage(self):
        current_time = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        cache_usage = self.get_cache_usage()

        if cache_usage is not None:
            logging.info(f'Cache usage at {current_time}: {cache_usage}%')

def main():
    monitor = CacheMonitor()

    # Main loop to continuously monitor cache usage
    while True:
        try:
            time.sleep(60)  # Monitor every minute
            monitor.log_cache_usage()
        except KeyboardInterrupt:
            break

if __name__ == "__main__":
    main()

import queue

class DynamicQueue(queue.Queue):
    def __init__(self, maxsize=0):
        super().__init__(maxsize)
        self._scaling = 1  # initial scaling factor

    def put(self, item, block=True, timeout=None):
        if self.qsize() >= self.maxsize * self._scaling * 0.8:
            self._scale_up()
        super().put(item, block, timeout)

    def get(self, block=True, timeout=None):
        item = super().get(block, timeout)
        if self.qsize() <= self.maxsize * self._scaling * 0.2:
            self._scale_down()
        return item

    def _scale_up(self):
        # Scale up the queue by increasing maxsize
        self._scaling += 1
        self.maxsize *= 2

    def _scale_down(self):
        # Scale down the queue by decreasing maxsize (but never go below 1)
        if self._scaling > 1:
            self._scaling -= 1
            self.maxsize = max(1, self.maxsize // 2)

def encrypt(payment_details, key):
    encrypted = ""
    for i in range(len(payment_details)):
        char = payment_details[i]
        if (char.isupper()):
            encrypted += chr((ord(char) + key-65) % 26 + 65)
        else:
            encrypted += chr((ord(char) + key - 97) % 26 + 97)
    return encrypted

def decrypt(encrypted_details, key):
    decrypted = ""
    for i in range(len(encrypted_details)):
        char = encrypted_details[i]
        if (char.isupper()):
            decrypted += chr((ord(char) - key-65) % 26 + 65)
        else:
            decrypted += chr((ord(char) - key - 97) % 26 + 97)
    return decrypted

