key = 4
encrypted_details = encrypt(payment_details, key)
print('Encrypted payment details:', encrypted_details)
decrypted_details = decrypt(encrypted_details, key)
print('Decrypted payment details:', decrypted_details)

import time
from collections import defaultdict

class EmailRateLimiter:
    def __init__(self, rate_limit=10, period=3600):
        self.rate_limit = rate_limit  # Max emails per period
        self.period = period  # Period length in seconds (e.g., 3600 for hour)
        self.timestamps = defaultdict(list)

    def check_limit(self, user_id):
        now = time.time()
        emails_sent = self.timestamps[user_id]

        # Remove timestamps that are older than the specified period
        while emails_sent and emails_sent[0] < (now - self.period):
            emails_sent.pop(0)

        if len(emails_sent) >= self.rate_limit:
            return False  # Limit exceeded, deny email sending
        else:
            self.timestamps[user_id].append(now)
            return True   # Email can be sent

# Usage example:
limiter = EmailRateLimiter()

if limiter.check_limit('user1'):
    print("Sending email to user1")
else:
    print("Cannot send more emails to user1 at this time.")

