import json

def validate_tenant_config(tenant_config):
    """
    Validates a tenant configuration.

    Args:
        tenant_config (dict): The tenant configuration to be validated.
            It should contain 'name', 'email', and 'roles' keys.

    Returns:
        bool: True if the tenant configuration is valid, False otherwise.
    """

    # Check if the tenant configuration is a dictionary
    if not isinstance(tenant_config, dict):
        return False

    # Check if the required keys are present in the tenant configuration
    required_keys = ['name', 'email', 'roles']
    for key in required_keys:
        if key not in tenant_config:
            return False

    # Check if the email address is valid
    try:
        import re
        if not re.match(r"[^@]+@[^@]+\.[^@]+", tenant_config['email']):
            return False
    except ImportError:
        pass  # Skip this check if email validation is not available in the environment

    # Check if roles are a list or array of strings
    try:
        if not isinstance(tenant_config['roles'], (list, tuple)):
            return False
        for role in tenant_config['roles']:
            if not isinstance(role, str):
                return False
    except KeyError:
        return False  # If 'roles' key is missing

    # Check if the roles list contains any empty strings
    if len(tenant_config['roles']) == 0 or ('' in tenant_config['roles']):
        return False

    # If all checks pass, the tenant configuration is valid
    return True

