tenant_config = {
    'name': 'John Doe',
    'email': 'john@example.com',
    'roles': ['admin', 'user']
}

if validate_tenant_config(tenant_config):
    print("Tenant configuration is valid.")
else:
    print("Tenant configuration is invalid.")

import threading

class PriorityQueue(object):
    def __init__(self, maxsize=0):
        self.queue = []
        self.maxsize = maxsize

    def put(self, task, priority=0):
        if len(self.queue) >= self.maxsize:
            raise QueueFullError("Queue is full")
        self.queue.append((task, priority))

    def get(self):
        if not self.queue:
            raise EmptyQueueError("Queue is empty")
        task, priority = self.queue.pop()
        return task

class PriorityThread(threading.Thread):
    def __init__(self, target, args=(), kwargs={}, daemon=None, name=None, start_priority=0):
        super().__init__(target, args, kwargs, daemon, name)
        self.start_priority = start_priority

    def run(self):
        task = PriorityQueue()
        task.put(self.target, priority=self.start_priority)
        while True:
            try:
                task = PriorityQueue()
                task.put(self.target, priority=self.start_priority)
                return task.get()
            except QueueFullError as e:
                print("Queue is full")
            except EmptyQueueError as e:
                print("Queue is empty")

import requests
import json

def send_request(url, method='GET', data=None):
    try:
        if method == 'GET':
            response = requests.get(url)
        elif method == 'POST':
            response = requests.post(url, data=data)
        else:
            raise ValueError("Invalid request method")

        # Check for HTTP errors
        response.raise_for_status()

        return response.json()

    except requests.exceptions.HTTPError as http_err:
        print(f'HTTP error occurred: {http_err}')
    except requests.exceptions.ConnectionError as conn_err:
        print(f'Some problem connecting to the server (connection error): {conn_err}')
    except requests.exceptions.Timeout as time_err:
        print(f'Timeout error occurred: {time_err}')
    except requests.exceptions.RequestException as err:
        print(f'Error: {err}')
    except json.JSONDecodeError as json_err:
        print(f'JSON decode error: {json_err}')

# Example usage
