import hashlib
import secrets
from flask import Flask, request, session, redirect, url_for

app = Flask(__name__)
app.secret_key = secrets.token_hex(32)

def generate_session_token(username):
    """Generates a unique session token for a given username."""
    secret_key = app.secret_key
    token = hashlib.sha256(f"{username}:{secret_key}".encode()).hexdigest()
    return token

def set_session_cookie(username):
    """Sets a secure cookie with the session token."""
    token = generate_session_token(username)
    session[username] = token
    response = redirect(url_for('home'))
    response.set_cookie('session_token', token, httponly=True, secure=True)
    return response

@app.route('/login', methods=['GET', 'POST'])
def login():
    """Handles user login."""
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']
        # Perform authentication logic here
        if authenticate(username, password):
            return set_session_cookie(username)
    return render_template('login.html')

@app.route('/home')
def home():
    """Renders the home page."""
    username = request.cookies.get('session_token')
    if username in session:
        return render_template('home.html', username=username)
    return redirect(url_for('login'))

if __name__ == '__main__':
    app.run(debug=True)

