class RecurringPayment:
    def __init__(self, amount, interval_days):
        self.amount = amount
        self.interval_days = interval_days
        self.last_payment_date = None

    def make_payment(self, today):
        if self.last_payment_date is None:
            print("Payment of", self.amount, "made")
            self.last_payment_date = today
        else:
            days_since_last_payment = (today - self.last_payment_date).days
            if days_since_last_payment >= self.interval_days:
                print("Payment of", self.amount, "made")
                self.last_payment_date = today
            else:
                print("No payment due yet.")

import time
from collections import defaultdict

class RateLimiter:
    def __init__(self, limit=10, duration=60):
        self.limit = limit
        self.duration = duration
        self.requests = defaultdict(list)

    def allow_request(self, ip):
        now = time.time()
        request_times = self.requests[ip]

        # Remove requests that are outside of the current window.
        while request_times and request_times[0] < now - self.duration:
            del request_times[0]

        if len(request_times) >= self.limit:
            return False  # Too many requests, deny this one.
        else:
            request_times.append(now)
            return True  # Request allowed.

# Usage
limiter = RateLimiter()

def handle_websocket_message(ip):
    if limiter.allow_request(ip):
        print("Message accepted.")
    else:
        print("Rate limit exceeded, message rejected.")

