import math

def create_hilbert_tree(levels):
    tree = {}
    for level in range(levels + 1):
        current_nodes = []
        if level == 0:
            current_nodes.append((0, 0))
        else:
            half_level = int(math.log(level, 2)) 
            step = 1 << (level - 1)
            for node_id, (x, y) in enumerate(current_nodes):
                a = x & step
                b = y & step
                c = a ^ b
                d = max(a, b)
                e = min(a, b)

                if level % 2 == 1:
                    next_node_x = a + (y // step) * (step << 1) | (x >> step + 1)
                    next_node_y = b - (x // step) * (step << 1) 
                else:
                    next_node_x = x + (a + b) * step
                    next_node_y = y - (a - b) * step

                for i in range(step):
                    new_x = a + ((y >> (level)) & (i+1))
                    new_y = b | (((x >> (level)) & ~((i+1) << level - 1))) & (step)
                    current_nodes.append((new_x, new_y))
        tree[level] = [(new_x, new_y) for new_x, new_y in current_nodes]
    return tree

def compute_hilbert_distance(h_index, q_index):
    return abs(h_index - q_index)

def find_closest_nodes(tree, query_id, num_neighbors=3):
    closest = []
    min_distance = float('inf')

    for level, nodes in tree.items():
        if not nodes:
            continue
        distance = compute_hilbert_distance(query_id, level)
        if distance < min_distance:
            if len(closest) < num_neighbors:
                closest.append((distance, nodes))
            else:
                if distance > closest[-1][0]:
                    continue

    return closest

