def validate_api_inputs(**kwargs):
    # Required parameters check
    required_params = ['username', 'password']
    for param in required_params:
        if param not in kwargs or kwargs[param] is None:
            raise ValueError(f"Required parameter '{param}' is missing")

    validated_inputs = {}

    # Validate each parameter with appropriate checks
    def _validate_int(param, value):
        if isinstance(value, int) and min <= value <= max:
            return True
        else:
            raise TypeError(f"{param} must be an integer between {min} and {max}")

    def _validate_str(param, value, length=None, pattern=None):
        if isinstance(value, str):
            if length is not None and len(value) != length:
                raise ValueError(f"{param} for '{value}' has incorrect length")
            elif pattern is not None and not re.match(pattern, value):
                raise ValueError(f"{param} for '{value}' does not match the required pattern")
            return True
        else:
            raise TypeError(f"{param} must be a string")

    # Check each parameter based on its type and range
    params_to Validate = {
        'username': {'type': str, 'min_len': 3, 'max_len': 15},
        'password': {'type': str, 'min_len': 6, 'max_len': 20}
    }

    for param, criteria in params_to_validate.items():
        value = kwargs.get(param)
        if not isinstance(value, criteria['type']):
            raise TypeError(f"{param} must be of type {criteria['type']}")

        # Handle repeated fields by joining valid values
        if 'usernames' in kwargs and kwargs['usernames'] is None:
            usernames = [kwargs[username] for username in kwargs['usernames']]
            validated_inputs['usernames'] = ','.join([str(u) for u in usernames if u is not None])
        elif param != 'password':
            value = str(value)
            if ',' in value and len(value.strip().split(',')) > 0:
                validated_inputs[param] = ','.join(value.split(','))
            else:
                validated_inputs[param] = value

    # Handle other parameters
    for param, criteria in params_to_validate.items():
        if param not in kwargs or (isinstance(kwargs[param], criteria['type']) and 
                                   min <= kwargs[param] <= max):
            if isinstance(kwargs[param], str) and len(kwargs[param]) == 0:
                valid_value = ''
            else:
                valid_value = str(kwargs[param])
            validated_inputs[param] = valid_value

    return validated_inputs

