from cryptography.fernet import Fernet
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC
from cryptography.hazmat.primitives.asymmetric import padding
import os, base64

app = Flask(__name__)
key_passphrase = b"tenant_password"  # This should be replaced with actual passphrases per tenant
salt = os.urandom(16)  # Generate some salt
kdf = PBKDF2HMAC(algorithm=hashes.SHA256(), length=32, salt=salt, iterations=100000)
key = base64.urlsafe_b64encode(kdf.derive(key_passphrase))  # Can be securely stored, key per tenant
