@app.route('/encrypt', methods=['POST'])
def encrypt():
    data = request.get_json()

    if 'message' not in data:
        return jsonify({"error": "Missing field 'message'"}), 400

    encrypted_msg = fernet.encrypt(data['message'].encode())
    return jsonify({"ciphertext": encrypted_msg.decode()})

@app.route('/decrypt', methods=['POST'])
def decrypt():
    data = request.get_json()

    if 'ciphertext' not in data:
        return jsonify({"error": "Missing field 'ciphertext'"}), 400

    try:
        decrypted_msg = fernet.decrypt(data['ciphertext'].encode()).decode()
        return jsonify({"message": decrypted_msg})
    except Exception as e:
        return jsonify({"error": str(e)}), 500

import json
from enum import Enum
from typing import Any, Optional

class ValidationErrors(Enum):
    """Enum for validation errors"""
    INVALID_FORMAT = "Invalid format"
    REQUIRED_FIELDS_MISSING = "Required fields are missing"
    EXCESSIVE_DATA = "Excessive data provided"

def validate_request_data(data: dict[str, Any]) -> tuple[dict[str, Any], list[str]]:
    """Validate API request data"""

    # Define required fields
    required_fields = ["name", "age"]

    # Check if all required fields are present
    if not all(field in data for field in required_fields):
        return {"error": REQUIRED_FIELDS_MISSING}, []

    # Validate age (must be an integer)
    if not isinstance(data["age"], int) or data["age"] < 0:
        return {"error": ValidationErrors.INVALID_FORMAT.value}, []

    # Check if excessive data is provided
    if len(data) > len(required_fields):
        return {"error": ValidationErrors.EXCESSIVE_DATA.value}, []

    # If all checks pass, return validated data and an empty list of errors
    return data, []

def validate_json_data(data: str) -> tuple[dict[str, Any], list[str]]:
    """Validate JSON data"""

    try:
        json_data = json.loads(data)
        return validate_request_data(json_data), []
    except json.JSONDecodeError as e:
        return {"error": "Invalid JSON format"}, [str(e)]

def main():
    # Example usage
    request_data = {
        "name": "John Doe",
        "age": 30,
        "email": "john@example.com"
    }

    json_string = '{"name":"John Doe","age":30}'

    validated_data, errors = validate_json_data(json_string)
    if errors:
        print(f"Validation Errors: {', '.join(errors)}")
    else:
        print("Validated Data:", validated_data)

if __name__ == "__main__":
    main()

