from flask import Flask, request, jsonify
from time import time
import logging

app = Flask(__name__)

# We store requests count and timestamp in a dictionary
# The key will be the IP address of the client making the request
rate_limits = {}

@app.before_request
def limit_remote_addr():
    remote_address = request.remote_addr  # get IP of the requester
    if not remote_address in rate_limits:
        rate_limits[remote_address] = {'start': time(), 'requests': 1}
    else:
        current_time = time()
        time_difference = int(current_time - rate_limits[remote_address]['start'])

        # If more than 60 seconds have passed since the first request, reset the counter
        if time_difference > 60:
            rate_limits[remote_address] = {'start': current_time, 'requests': 1}
        else:
            rate_limits[remote_address]['requests'] += 1

        # If more than 5 requests have been made within the last minute, return an error
        if rate_limits[remote_address]['requests'] > 5:
            response = jsonify({'error': 'Rate limit exceeded!'})
            response.status_code = 429
            logging.warning(f"Rate limit exceeded by {remote_address}")
            return response  # stop request processing here and send the error message

import os
from configparser import ConfigParser

class SecureConfigParser(object):
    def __init__(self, filename='config.ini', auto_commit=False):
        self._filename = filename
        self._auto_commit = auto_commit
        self._config = ConfigParser()
        if os.path.exists(filename):
            with open(filename) as fh:
                self._config.read_file(fh)

    def get_section(self, section):
        """Return a dictionary for the given section of the config."""
        return dict(self._config.items(section)) if self._config.has_section(section) else {}

    def set_option(self, section, option, value):
        """Set an option in a section."""
        if not self._config.has_section(section):
            self._config.add_section(section)
        self._config.set(section, option, value)
        if self._auto_commit:
            self.save()

    def remove_option(self, section, option):
        """Remove an option from a section."""
        if self._config.has_option(section, option):
            self._config.remove_option(section, option)
        if self._auto_commit:
            self.save()

    def save(self):
        with open(self._filename, 'w') as fh:
            self._config.write(fh)

