    if not isinstance(config, dict) or len(expected) != len(config):
        return False
    for key, expected_value in expected.items():
        if key not in config or config[key] != expected_value:
            print("Config mismatch.")
            print_config(config)
            print_config(expected)
            raise AssertionError("Configuration mismatch detected.")

def load_config(config_path, config_key="CONFIG"):
    """Load configuration from a JSON/YAML file."""
    with open(config_path, "r", encoding="utf-8") as file:
        if not file.readable():
            raise ValueError(f"Could not read {config_path}.")
        return json.load(file)

def get_config(config_loader, config_key):
    """Retrieve the current configuration."""
    print(f"Loading configuration...")
    try:
        return getattr(config_loader, config_key)
    except AttributeError:
        raise FileNotFoundError("Configuration file not found.")

def refresh_config(config_loader, config_key="CONFIG"):
    """Reload the configuration if it has changed."""
    current = get_config(config_loader, config_key)
    last reloading = getattr(config_loader, "__last_reloading_time__", None)
    print(f"Last reloaded at: {last reloading}")

    # Get new data
    try:
        new_data = load_config(config_path=config_path, config_key=config_key)
    except Exception as e:
        raise RuntimeError("Failed to refresh configuration.") from e

    if current != new_data or last reloading is not None:
        setattr(config_loader, "__last_reloading_time__", time.time())
        print(f"Config has changed; reloading started at: {time.time()}")

    # Wrap in a function that will be run via timer
    def reload():
        refresh_config(config_loader, config_key)

    return reload

def setup dynamically:
    importlib.reload(sys.modules[__name__])

# Initial configuration loading
current_config = get_config(importlib.utilsalt("config_loader"), "CONFIG")

# Register the atexit handler
atexit_handler = None

# Function to handle reloading with interval
def atexit_timer(func):
    global atexit_handler
    atexit_handler = func
    # Check if already set and run once only
    while atexit_handler:
        try:
            func()  # Run it once
            print("Config loaded, attempting reload.")
            return None
        except Exception as e:
            print(f"Error in configuration reload: {e}")
            break

# Register the handler to call refresh_config every minute (60 seconds)
atexit_timer(refresh_config)

# Cleanup function for atexit
def cleanup():
    global atexit_handler
    if atexit_handler is not None and callable(atexit_handler):
        print("Removing timer...")
        del atexit_handler

register(cleanup)

from flask import Flask, request, jsonify
from werkzeug.utils import secure_filename
import os

app = Flask(__name__)

# Restrict executable file extensions here
ALLOWED_EXTENSIONS = {'txt', 'pdf', 'png', 'jpg', 'jpeg', 'gif'}

def allowed_file(filename):
    return '.' in filename and \
           filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

@app.route('/upload', methods=['POST'])
def upload_file():
    if request.method == 'POST':
        # check if the post request has the file part
        if 'file' not in request.files:
            return jsonify({"message": "No file part."}), 400
        file = request.files['file']
        # If user does not select file, browser also submit an empty part without filename
        if file.filename == '':
            return jsonify({"message": "No selected file."}), 400
        if file and allowed_file(file.filename):
            filename = secure_filename(file.filename)
            file.save(os.path.join('/path/to/uploads', filename))
            return jsonify({"message": "File successfully uploaded."}), 201
        else:
            return jsonify({"message": "Invalid file extension."}), 400

