class AccessControl:
    def __init__(self):
        self.logger = logging.getLogger(__name__)
        pass

    def check_access(self, user_data, resource_data, action='read'):
        """
        Validate access control based on user role and resource type.

        Args:
            user_data: Dictionary with 'name' (str) and 'role' (str).
            resource_data: Dictionary with 'path' (str) and 'permissions'.
                Permissions is a dictionary where keys are actions ('read', 'write') 
                and values are allowed roles for each action.
            action: Action to perform, defaults to 'read'.

        Raises:
            Exception: If access control is violated.
        """
        try:
            # Get the permissions for this resource and action
            permissions = resource_data.get(action)
            if not permissions:
                raise Exception(f"Permission policy not found for action '{action}' on {resource_data['path']}")

            user_role = user_data['role']

            # Check access based on role and resource
            for role, allowed_actions in self.resource_permissions.items():
                if role == user_role:
                    expected_actions = set(permissions.keys())
                    actual_actions = set(resource_data.get('actions', set()))
                    actions_allowed = expected_actions.intersection(actual_actions)

                    if action not in actions_allowed:
                        self.logger.error(
                            f"Access denied: {user_data['name']} attempted to {action} on {resource_data['path']}."
                        )
                        raise Exception(f"Unauthorized access attempt by {user_data['name']} on resource '{resource_data['path']}'")
            return True

        except KeyError as e:
            self.logger.error(f"Missing permission policy for action '{e.args[0]}' on {resource_data['path']}")
            raise
        except Exception as e:
            self.logger.exception(f"Unexpected error checking access control: {str(e)}")

# Define resource permission policies
resource_permissions = {
