# A basic fraud detection system
class PaymentFraudDetection:
    def __init__(self):
        self.fraud_dict = {}  # Key is user id and value is total amount spent by the user

    def monitor(self, user_id, payment_amount):
        if user_id not in self.fraud_dict:
            self.fraud_dict[user_id] = payment_amount
        else:
            self.fraud_dict[user_id] += payment_amount

    def detect(self, user_id):
        if self.fraud_dict[user_id] > 1000:  # Set threshold as $1000 for fraud detection
            return "Fraud detected"
        else:
            return "No Fraud detected"

# Sample usage
