import json

def parse_json(incoming_data):
    if not isinstance(incoming_data, str):
        raise TypeError("Incoming data must be a string.")

    try:
        parsed = json.loads(incoming_data)
        # Schema validation for the parsed JSON here
        schema = define_schema()
        validate(parsed, schema)
        return parsed

    except json.JSONDecodeError as e:
        log_error(e, "JSON Decode Error")
        return None

    except Exception as e:
        log_error(e, "Unexpected error during parsing or validation")
        return None

def define_schema():
    # Define your JSON schema here
    return {
        "$schema": "http://json-schema.org/schema.json",
        "type": ["object"],
        "required": [
            "user_id",
            "email",
            "role"
        ],
        "additionalProperties": false,
        "properties": {
            "user_id": {"type": "integer"},
            "email": {"type": "string", "pattern": "^\\S+\\.\\S+@\\S+\\.\\S+$"},
            "role": {"const": ["admin", "user", "moderator"]}
        }
    }

def validate(parsed, schema):
    jsonschema.validate(parsed, schema)

def log_error(error, message):
    import logging
    logging.error(f"[parse_json] {message}")

import jwt
from datetime import datetime, timedelta

# Define the secret key for your application
SECRET_KEY = 'Your_Secret_Key'  # Replace with your own secret key
ALGORITHM = 'HS256'  # The algorithm used to sign JWT tokens
TOKEN_EXPIRY = 30  # In minutes, adjust as per your needs

def generate_token(device_id):
    expiry = datetime.utcnow() + timedelta(minutes=TOKEN_EXPIRY)
    payload = {
        'iat': datetime.utcnow(),  # Issued At Time
        'exp': expiry,  # Expiration time
        'device_id': device_id
    }
    token = jwt.encode(payload, SECRET_KEY, ALGORITHM)
    return {'token': token, 'expires_at': str(expiry)}

def authenticate_device(token):
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
        device_id = payload['device_id']  # Get the device id from the token's payload
        return {'authenticated': True, 'device_id': device_id}
    except jwt.ExpiredSignatureError:
        return {'error': 'Token has expired'}
    except (jwt.InvalidTokenError, KeyError):
        return {'error': 'Invalid token'}

import multiprocessing
from multiprocessing import Queue, Lock
import time
from concurrent.futures import ForkJoinPool, Process

try:
    from queue import Queue as system_queue
except ImportError:  # Python <3.7
    system_queue = None

def add_message(queue, delay=0):
    """Add a message with some processing delay."""
    try:
        msg = f"Message {delay}"
        for i in range(5):  # Simulate processing time
            time.sleep(0.1)
        queue.put(msg)
    except Exception as e:
        print(f"Error adding message: {e}")

def main():
    try:
        if hasattr(ForkJoinPool, 'wrap'):
            pool = ForkJoinPool.wrap(system_queue)
        else:
            # For Python <3.7 where ForkJoinPool isn't available
            pool = Pool(queue_size=0)

        queue = multiprocessing.Queue()
        lock = Lock()

        messages_queue = multiprocessing.Queue(maxsize=10)
        messages_queue.put(1)  # Signal to start workers

        # Create worker processes
        workers = []
        for _ in range(5):
            worker = Process(target=add_message, args=(messages_queue,))
            worker.start()
            workers.append(worker)

        if hasattr(ForkJoinPool, 'wrap'):
            with ForkJoinPool(pool) as fjp:
                fjp.toPool().start()
                try:
                    # Wait for all workers to finish
                    fjp.join()
                except Exception as e:
                    print(f"Error waiting for workers: {e}")
        else:
            pool.join()

        while not queue.empty():
            msg = queue.get_nowait()
            print(f"Received message: {msg}")

    finally:
        if hasattr(ForkJoinPool, 'wrap'):
            pool.close()
        else:
            process.close()  # Ensure processes are closed
        messages_queue.close()
        queue.close()

if __name__ == '__main__':
    main()

