import re
from datetime import datetime

def validate_cvv(cvv):
    # CVV should be 3 or 4 digits long
    cvv_pattern = re.compile(r'^\d{3,4}$')

    if cvv_pattern.match(cvv):
        return True
    else:
        print("Invalid CVV format")
        return False

def validate_expiration_date(date):
    # Date should be in MM/YYYY format
    date_format = "%m/%Y"

    try:
        expiry_date = datetime.strptime(date, date_format)
        if expiry_date > datetime.now():
            return True
        else:
            print("Card has expired")
            return False

    except ValueError:
        print("Invalid date format. Use MM/YYYY")
        return False

# Testing the functions 
print(validate_cvv('123')) # True
print(validate_expiration_date('10/2025')) # True

import random

class DisasterPlan:
    def __init__(self, organization_name, contact_information):
        self.organization_name = organization_name
        self.contact_information = contact_information
        self.risk_assessment = []
        self.contingency_plan = []
        self.incident_management = []
        self_recovery_plan = []
        self.test_cases = []
        self.training_materials = []

    def assess_risk(self):
        """Assesses potential threats and vulnerabilities."""
        threats = ["Natural Disasters", "Cyber Attacks", "Power Outages", "Water Leaks"]
        vulnerabilities = ["Infrastructure", "Data Backups", "Communication Systems"]

        for threat in threats:
            self.risk_assessment.append(threat)
        for vulnerability in vulnerabilities:
            self.risk_assessment.append(vulnerability)

    def prepare_contingency(self):
        """Prepares for immediate actions during a disaster."""
        contingency = {
            "teams": ["Disaster Recovery Team", "Information Security Team"],
            "channels": ["Email", "Internal Intranet", "Third-party应急预案"],
            "guides": ["Incident Response Guide", "Emergency Procedures Document"],
            "equipment": ["Backup Generators", "Mobile Communication Devices"]
        }

        for key, value in contingency.items():
            setattr(self, f"contingency_plan_{key}", value)

    def manage_incident(self):
        """Handles incident management after a disaster."""
        incident_management = {
            "response": {
                "steps": ["Immediate Access", "Contain the Incident", "Secure the Area"],
                "communication": {
                    "primary_channel": "Emergency Operations Center",
                    "secondary_channel": "Media Outlets"
                },
                "logistics": {
                    "coordination": "Multi-agency Coordination Team",
                    ")|(recovery_team": ["Recovery", "Testing", "Training"]
                }
            },
            "review": {
                "period": "Weekly",
                "evaluation": "Incident Handling Report"
            }
        }

        for key, value in incident_management.items():
            setattr(self, f"incident_management_{key}", value)

    def plan_recovery(self):
        """Plans the recovery process post-disaster."""
        recovery_steps = [
            {"task": "Restart Systems", "duration": "24 hours"},
            {"task": "Restore Data", "duration": "48 hours"},
            {"task": "Re-establish Communication", "duration": "72 hours"},
            {"task": "Return Staff to duties", "duration": "3 days"}
        ]

        for step in recovery_steps:
            setattr(self, f"recovery_plan_step_{step['task']}", step)

    def test_plan(self):
        """Simulates a disaster to test the contingency plan."""
        test_cases = [
            {"incident": "Power outage", "expected_response": ["Generator restart", "Communication check"]},
            {"incident": "Water leak", "expected_response": ["Evacuate staff", "Contaminant removal"]},
            {"incident": "Cyber attack", "expected_response": ["Network rollback", "Data encryption review"]}
        ]

        self.test_cases = test_cases

    def train_staff(self):
        """Trains employees on disaster recovery procedures."""
        training_materials = [
            {
                "module": "Incident Handling",
                "content": ["Identify incident types", "Coordinate resources", "Log recovery actions"]
            },
            {
                "module": "Recovery Process",
                "content": ["Restart systems", "Restore data", "Secure environments"]
            }
        ]

        for material in training_materials:
            setattr(self, f"training_material_{material['module']}", material)

    def print_plan(self):
        """Prints the disaster recovery plan."""
        print(f"\nDisaster Recovery Plan for {self.organization_name}")
        print("==================================================")
        print(f"Risk Assessment: {', '.join(self.risk_assessment)}")
        print("==================================================")
        self.display_plan("Contingency Plan", ["Teams", "Channels", "Guides", "Equipment"])
        print("==================================================")
        self.display_plan("Incident Management", ["Response Steps", "Communication", "Logistics"])
        print("==================================================")
        self.display_plan("Recovery Plan", ["Steps", "Duration"])
        print("==================================================")

    def display_plan(self, category, items):
        """Helper method to display plan categories and items."""
        print(f"\n{category}:")
        for item in items:
            if isinstance(item, dict):
                attribute = item.get("attribute", "")
                description = item.get("description", "")
                setattr(self, f"{category}_{attribute}", {
                    "number": len(description.split(",")) if "," in description else 1,
                    "details": ", ".join(description.split(":")[1:]) if ":" in description else ""
                })
            else:
                print(f"- {item}")

    def test_plan effectiveness(self):
        """Simulates a disaster to test the preparedness."""
        random_incident = random.choice(["Fire", "Flood", "Cyber attack", "Earthquake"])
        test_case = self.test_cases[0] if len(self.test_cases) > 0 else {}
        if random_incident in ["Fire", "Flood"]:
            print(f"Simulated Incident: {random_incident}")
            print("Response Plan:")
            for step, duration in zip(test_case["expected_response"], ["Generator restart", "Communication check"]):
                print(f"{step}: Duration {duration} hours")
        elif random_incident == "Cyber attack":
            print(f"Simulated Incident: {random_incident}")
            print("Response Plan:")
            print("1. Network rollback and encryption review.")
            print("2. Data backup verification.")
        else:
            print(f"Simulated Incident: {random_incident}")
            print("Response Plan:")
            print("1. Evacuate staff and secure communication.")

# Example usage
if __name__ == "__main__":
    organization = "Sample Organization"
    contact = "support@organization.com"
    plan = DisasterPlan(organization, contact)

    # Access methods:
    plan.assess_risk()
    plan.prepare_contingency()
    plan.plan_recovery()

    # Test the plan:
    plan.test_plan()
    plan.train_staff()
    plan.print_plan()

    # Simulate a disaster:
    print("Simulated Disaster: Water Leak")
    print("Response Plan:")
    plan.test_plan_effectiveness()

import os
import filecmp

def check_file_existance(filename):
    if os.path.exists(filename):
        print(f"File {filename} already exists.")
        return True
    else:
        print(f"No existing file found for {filename}.")
        return False

def compare_files(existing_filename, new_filename):
    try:
        with open(existing_filename, 'rb') as f1, open(new_filename, 'rb') as f2:
            if filecmp.cmp(f1, f2):
                print("Files match.")
                return True
            else:
                print("Files do not match.")
                return False
    except FileNotFoundError:
        print("One or both of the files do not exist")
        return False

def prevent_overwriting(existing_filename, new_filename):
    if check_file_existance(new_filename):
        response = input(f"File {new_filename} already exists. Do you want to overwrite it? (y/n): ")
        if response.lower() == 'y':
            print("Overwriting existing file.")
            return True
        else:
            print("Operation cancelled.")
            return False
    elif compare_files(existing_filename, new_filename):
        return True
    else:
        print(f"No overwriting required for {new_filename}.")
        return False

# Example usage
existing_filename = "test.txt"
new_filename = "test2.txt"

if prevent_overwriting(existing_filename, new_filename):
    with open(new_filename, 'w') as f:
        # Write data to the file if no overwriting is needed.
        pass

from flask import Flask, request, jsonify
import sqlite3

app = Flask(__name__)

def db_connection():
    conn = None
    try:
        conn = sqlite3.connect('tenants.sqlite')
    except sqlite3.error as e:
        print(e)
    return conn

@app.route('/api/keys', methods=['POST'])
def get_key():
    tenant_id = request.form['tenant_id']
    password = request.form['password']

    conn = db_connection()
    cur = conn.cursor()

    sql = "SELECT api_key FROM tenants WHERE id=? AND password=?"
    result = cur.execute(sql, (tenant_id, password)).fetchone()

    if result is None:
        return jsonify({'error': 'invalid tenant_id or password'}), 401

    api_key = result[0]
    conn.close()

    return jsonify({'api_key': api_key})

import datetime
import sqlite3
import requests

class WebhookMonitor:
    def __init__(self, database_name='webhook_data.db'):
        self.database_name = database_name
        self._setup_database()

    def _setup_database(self):
        try:
            with sqlite3.connect(self.database_name) as conn:
                cursor = conn.cursor()
                cursor.execute('''
                    CREATE TABLE IF NOT EXISTS metrics (
                        timestamp DATETIME,
                        metric_name TEXT,
                        value TEXT,
                        unit TEXT,
                        status INTEGER
                    )''')
        except sqlite3.OperationalError as e:
            print(f"Database setup error: {e}")

    def _get_response_time(self, request):
        start = datetime.datetime.now()
        response = requests.request(request['method'], 
                                  request['url'],
                                  headers=request.get('headers', {}),
                                  params=request.get('params', {}),
                                  json=request.get('json', {}))
        end = datetime.datetime.now()

        if response.status_code >= 200 and response.status_code < 300:
