from typing import List, Dict

class PriorityQueue:
    def __init__(self):
        self.queue: List[tuple] = []
        self.priorities: Dict[int, int] = {}

    def add(self, item: str, priority: int) -> None:
        """Add an element to the queue with a specified priority."""
        if priority not in self.priorities:
            self.priorities[priority] = len(self.queue)

        self.queue.append((item, priority))

    def remove(self) -> tuple:
        """Remove and return the item with the highest priority from the queue."""
        if not self.queue:
            raise ValueError("Queue is empty")

        # Find the index of the item with the highest priority
        max_index = min([i for i, (item, _) in enumerate(self.queue) if (_, _) == tuple(sorted([(priority, -i) for i, (item, priority) in enumerate(self.queue)], key=lambda x: x[0]))])

        # Remove and return the item with the highest priority
        return self.queue.pop(max_index)

    def display(self) -> None:
        """Display the current state of the queue."""
        print("Queue:")
        for i, (item, priority) in enumerate(self.queue):
            print(f"{i+1}. {item} - Priority: {priority}")


# Example Usage
