    q.add("Task 4", 4)

    # Display the current state of the queue
    q.display()

    # Remove and print elements from the queue based on priority
    while True:
        try:
            item, priority = q.remove()
            print(f"Removed: {item} - Priority: {priority}")
        except ValueError as e:
            print(e)
            break

