import time

def retry(func, args=None, kwargs=None, max_attempts=3):
    attempts = 0
    while True:
        try:
            return func(*args, **kwargs)
        except Exception as e:
            if attempts >= max_attempts:
                raise e from None
            time.sleep(1)
            attempts += 1

