def serialize_xml(obj, starting_path=""):
    xml_elements = {}

    # Define the namespace mappings
    namespaces = {
        'person': 'http://example.org/2004',
        'address': 'http://example.org/ns#'
    }

    def to_xml element):
        if len(element) == 1:
            key, value = next(iter(element.items()))
            # For address, nest street and city elements
            if key == 'address':
                xml_elements['{}/{}'.format(namespaces[key], key)] = [to_xml(v) for v in value.values()]
                return xml_elements['{}/{}'.format(namespaces[key], key)]
            else:
                return to_xml({key: value})
        elif key == 'address':
            street = next(iter(element.values()))
            city = next(iter(street.values()))
            xml_elements['{}/street'.format(ns)] = to_xml(street)
            xml_elements['{}/city'.format(ns)] = to_xml(city)
            return xml_elements['{}/address'.format(ns)]
        else:
            return to_xml({key: value})

    def serialize(obj):
        current_path = starting_path
        for key, value in obj.items():
            if isinstance(value, dict) and ' address' in value:
                # Handle nested dictionaries
                xml_elements[current_path + namespace[key] + key] = [to_xml(v) for v in value.values()]
            else:
                xml_elements[current_path + namespace[key] + key] = to_xml(value)
        return xml_elements

    result = serialize(obj)
