import time 

# Create a dictionary to hold users' data
users = { 'JohnDoe': {'password': '123456', 'attempts': 0, 'last_failure_time': None} }

def check_password(username, password):
    if username in users:
        # Check the number of attempts made from this IP. If more than 3 and less than a minute has passed since last failure, lockout.
        if users[username]['attempts'] >= 3 and (users[username]['last_failure_time'] is None or time.time() - users[username]['last_failure_time'] < 60):
            print("Account locked: Too many failed attempts, please try again later.")
            return False
        # If the password is incorrect
        elif users[username]['password'] != password:
            # Increase the failure attempts counter 
            users[username]['attempts'] += 1
            if users[username]['attempts'] == 3:
                # If this was the third failed attempt, record the time of the last one
                users[username]['last_failure_time'] = time.time()
            print("Incorrect password.")
            return False
        else:
            # Reset attempts on a correct password entry 
            if users[username]['attempts'] > 0:
                users[username]['attempts'] = 0
            print("Login successful.")
            return True
    else:
        print("Username not found.")
        return False

