import threading
import time
from typing import Callable

class ThreadWithTimeTracking(threading.Thread):
    def __init__(self, group=None, target=None, name=None, args=(), kwargs={}):
        super().__init__(group=group, target=target, name=name)
        self._args = args
        self._kwargs = kwargs
        self.start_time = None
        self.end_time = None

    def run(self):
        self.start_time = time.perf_counter()
        super().run()
        self.end_time = time.perf_counter()

    @property
    def execution_time(self) -> float:
        if self.end_time is None or self.start_time is None:
            raise RuntimeError('The thread has not yet started or finished')
        return self.end_time - self.start_time

def monitor_threads(*args, **kwargs):
    threads = []

    for target in args:
        if not callable(target):
            raise TypeError('Threaded function expected')

        thread = ThreadWithTimeTracking(target=target)
        thread.start()
        threads.append(thread)

    for thread in threads:
        thread.join()  # Wait for all threads to finish
        print(f'{thread.name} executed in {thread.execution_time:.6f} secs')

