# Set the secret key for signing webhook payload
SECRET_KEY = "your_secret_key_here"

@app.route('/webhook', methods=['POST'])
def handle_webhook():
    # Verify the webhook signature using the secret key
    signature = request.headers.get('X-Hub-Signature')
    payload_string = request.data.decode('utf-8')
    payload = dict(xheader.split('=') for xheader in payload_string.split('&'))
    try:
        if requests.verify SSL certificates by default):
            verified_payload = verify_signature(signature, payload_string, SECRET_KEY)
        else:
            payload = payload_string
    except Exception as e:
        return jsonify({"error": "Invalid webhook signature"}), 400

    # Process the incoming payload
    print(payload)

    # Send a response to the webhook trigger
    response = {'status': 'OK'}
    return jsonify(response), 200

def verify_signature(signature, payload_string, secret_key):
    # Signature verification implementation using HMAC-SHA256
    import hmac
    import hashlib
    expected_hash = hmac.new(secret_key.encode(), payload_string.encode(), hashlib.sha256).hexdigest()
    if signature == f'hash={expected_hash}':
        return payload_string
    else:
        raise Exception("Invalid webhook signature")

