def rotate_right(lst, r):
    n = len(lst)
    if n == 0:
        return []
    effective_rotation = r % n
    if effective_rotation == 0:
        return list(lst)
    return lst[-effective_rotation:] + lst[:-effective_rotation]

def is_valid(n):
    s = str(n)
    reversed_digits = s[::-1]
    total = 0

    for i in range(len(reversed_digits)):
        digit = int(reversed_digits[i])
        if i % 2 == 1:
            doubled = digit * 2
            # Sum the digits of the doubled value
            total += (doubled // 10) + (doubled % 10)
        else:
            total += digit

    return total % 10 == 0

