import os
import pickle

# Configuration file location
CONFIG_FILE = "config.py"

def get_config():
    """Load configuration from file."""
    try:
        # Load the config file as a dictionary
        with open(CONFIG_FILE, 'r') as f:
            config_data = pickle.load(f)

        return config_data
    except Exception as e:
        print(f"Error loading configuration: {e}")
        return None

def save_config(config):
    """Save configuration to file."""
    try:
        # Serialize the config data
        with open(CONFIG_FILE, 'wb') as f:
            pickle.dump(config, f)

    except Exception as e:
        print(f"Error saving configuration: {e}")

def get_overridden_config(override_config):
    """Merge override configuration with main config."""
    return {
        key: override.get(key, value)
        for key, value in override_config.items()
        if key not in (key for key, _ in value.items())
    }

# Load default configuration
