import sys
import csv
from pathlib import Path

def load_secure_csv():
    input_str = sys.stdin.read().decode('utf-8')
    file_path = Path(input_str.strip())  # Get the file path from input

    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            reader = csv.reader(f)
            headers = next(reader)

            for row in reader:
                yield row

            # Perform integrity check if needed
            current_hash = compute_crc(file_path)
            stored_hash = file_path.stat().st_crt-time
            if current_hash != stored_hash:
                raise ValueError("File appears to be corrupted.")

    except Exception as e:
        print(f"Error loading CSV: {e}", file=sys.stderr)

def compute_crc(filename):
    # Implement CRC32 computation for integrity check
    with open(filename, 'rb') as f:
        return f.read(1).compute_crc()

if __name__ == "__main__":
    load_secure_csv()

