from flask import Flask, request
from flask_restful import Resource, Api

app = Flask(__name__)
api = Api(app)

# This data store is just an example. In a real-world scenario, you would use a database to store and retrieve the data.
data = {}

class HelloWorld(Resource):
    def get(self):
        return {'message': 'Hello, World!'}

class DataStore(Resource):
    # This method retrieves all records from the data store.
    def get(self):
        return data

    # This method adds a new record to the data store.
    def post(self):
        new_data = request.get_json()
        data[len(data)+1] = new_data
        return {len(data): new_data}, 201

    # This method updates an existing record in the data store.
    def put(self, id):
        updated_data = request.get_json()
        if id not in data:
            return {'error': 'Resource not found'}, 404
        data[id] = updated_data
        return {id: updated_data}, 200

    # This method deletes a record from the data store.
    def delete(self, id):
        if id not in data:
            return {'error': 'Resource not found'}, 404
        del data[id]
        return '', 204

api.add_resource(HelloWorld, '/')
api.add_resource(DataStore, '/data', '/data/<int:id>')

if __name__ == '__main__':
    app.run(debug=True)

import uuid
from datetime import datetime

class Post:
    def __init__(self, title, content, author):
        self.id = str(uuid.uuid4())
        self.title = title
        self.content = content
        self.author = author
        self.created_at = datetime.now()

class Comment:
    def __init__(self, content, post_id, author):
        self.id = str(uuid.uuid4())
        self.content = content
        self.post_id = post_id
        self.author = author
        self.created_at = datetime.now()

class User:
    def __init__(self, username, email):
        self.username = username
        self.email = email

class ContentManager:
    def __init__(self):
        self.posts = []
        self.comments = []

    def create_post(self, title, content, author):
        new_post = Post(title, content, author)
        self.posts.append(new_post)

    def add_comment(self, post_id, content, author):
        for post in self.posts:
            if post.id == post_id:
                new_comment = Comment(content, post_id, author)
                self.comments.append(new_comment)
                return True
        return False

    def get_posts(self):
        return self.posts

    def get_comments(self, post_id=None):
        if post_id is None:
            return self.comments
        else:
            for post in self.posts:
                if post.id == post_id:
                    return [comment for comment in self.comments if comment.post_id == post_id]
            return []

def main():
    manager = ContentManager()

    # Create users
    user1 = User('john', 'john@example.com')
    user2 = User('jane', 'jane@example.com')

    # Create posts
    manager.create_post('Post 1', 'This is the content of post 1.', user1)
    manager.create_post('Post 2', 'This is the content of post 2.', user2)

    # Add comments
    print(manager.add_comment('post1', 'This is a comment on post 1.', user2))
    print(manager.add_comment('post1', 'This is another comment on post 1.', user1))

    print(manager.get_posts())

    print(manager.get_comments())

if __name__ == "__main__":
    main()

class Tenant:
    def __init__(self, name, cpu_limit, memory_limit):
        self.name = name
        self._cpu_limit = cpu_limit
        self._memory_limit = memory_limit

        self._current_cpu = 0
        self._current_mem = 0

    def allocate_resources(self, cpu, mem):
        if (self._current_cpu + cpu > self._cpu_limit) or \
           (self._current_mem + mem > self._memory_limit):
            raise Exception('Resource limit exceeded.')

        self._current_cpu += cpu
        self._current_mem += mem

    def free_resources(self, cpu, mem):
        if self._current_cpu - cpu < 0 or \
           self._current_mem - mem < 0:
            raise Exception('Cannot free more resources than allocated.')

        self._current_cpu -= cpu
        self._current_mem -= mem

    @property
    def cpu(self):
        return self._cpu_limit, self._current_cpu

    @property
    def memory(self):
        return self._memory_limit, self._current_mem

tenant1 = Tenant('Tenant 1', 500, 2048)
try:
    tenant1.allocate_resources(300, 1024)
except Exception as e:
    print(e)

print(f'CPU limit for {tenant1.name}: {tenant1.cpu}')
print(f'Memory limit for {tenant1.name}: {tenant1.memory}')

