import logging
import functools

class TextParserError(Exception):
    """Custom exception for text parsing errors."""
    pass

def log_error(func):
    """
    Decorator to log any text parsing errors.

    Args:
        func: The function being decorated.

    Returns:
        A wrapper function that logs text parsing errors.
    """
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except TextParserError as e:
            logging.error(f"Text Parsing Error: {e}")
    return wrapper

@log_error
def parse_text(input_string):
    """
    Simulates text parsing by splitting the input string into individual words.

    Args:
        input_string (str): The string to be parsed.

    Returns:
        list: A list of individual words in the input string.
    """
    return input_string.split()

# Example usage
if __name__ == "__main__":
    logging.basicConfig(level=logging.ERROR)

    # Test with valid input
    print(parse_text("Hello World"))

    # Test with invalid input (non-string value)
    try:
        parse_text(12345)
    except TextParserError as e:
        print(f"Caught error: {e}")

import hashlib
from collections import OrderedDict

class Cache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.cache = OrderedDict()

    def get(self, key):
        if key in self.cache:
            value, timestamp = self.cache[key]
            if time.time() - timestamp < 60: # assuming cache is valid for 1 minute
                return value
            else:
                del self.cache[key]
        return None

    def set(self, key, value):
        if key in self.cache:
            del self.cache[key]

        hash_key = hashlib.sha256(str(key).encode()).hexdigest()
        self.cache[hash_key] = (value, time.time())

        if len(self.cache) > self.capacity:
            oldest_item = self.cache.popitem(last=False)
            del self.cache[oldest_item[0]]

def main():
    cache = Cache(100)

    # Set some values in the cache
    cache.set('key1', 'value1')
    cache.set('key2', 'value2')

    # Get a value from the cache
    print(cache.get('key1'))  # prints: value1

    # Try to get an item that is not in the cache
    print(cache.get('nonexistent_key'))  # prints: None

if __name__ == "__main__":
    main()

