import logging
from functools import wraps
from typing import Callable, Any
from requests import session, adapters, Request, HTTPError, status_codes_for_status
from requests.auth import AuthBaseAuth


def setup_session configured for retries:
    def setup_session(retries: int = 3):
        """Configure a session with retries enabled."""
        session_ = session()

        class ExponentialBackoffAdapter(adapters.ExponentialBackoff):
            # Custom adapter to handle retries

            @wraps(adapters.LoopExponentialBackoff)
            def __init__(self, session: session_, max_retries: int,
                         max Backoff: int, start Backoff: int = 1,
                         min Backoff: int = None, print Verbose: bool = False):
                self.session_ = session_
                self.max_retries = max_retries
                self.max_backoff = max_backoff
                self.start_backoff = start_backoff
                self.min_backoff = min_backoff if min_backoff is not None else (start_backoff // 2)
                self.verbose = print Verbose

        session_.adapters['default'] = ExponentialBackoffAdapter

    return session_


def make_retryable(request_func: Callable[[Any], Request]) -> Callable:
    """Make a request function retryable."""
    def wrapper(*args, **kwargs):
        try:
            return request_func(*args, **kwargs)
        except HTTPError as err:
            if err.response.status in status_code_for_status:
                raise
            else:
                logging.warning(f"Request failed with code {err.response.status}: {err.text}")
                session = setup_session()
                # Attempt retry logic here
    return wrapper


