class Block:
    def __init__(self, previous_hash, transactions):
        self.previous_hash = previous_hash
        self.transactions = transactions
        self.block_data = f"{previous_hash}{transactions}".encode()
        self.block_hash = hashlib.sha256(self.block_data).hexdigest()

class Blockchain:
    def __init__(self):
        self.chain = []
        self.genesis()

    def genesis(self):
        transactions = ""
        previous_hash = "0"
        self.chain.append(Block(previous_hash, transactions))

    def add_block(self, transactions):
        previous_hash = self.last_block().block_hash
        new_block = Block(previous_hash, transactions)
        self.chain.append(new_block)

    def last_block(self):
        return self.chain[-1]

    def is_valid(self):
        for i in range(1, len(self.chain)):
            current_block = self.chain[i]
            prev_block = self.chain[i - 1]

            if current_block.block_hash != current_block.calculate_hash():
                return False

            if current_block.previous_hash != prev_block.block_hash:
                return False
        return True

# Sample usage:
def validate_transaction(transactions):
    blockchain = Blockchain()
    blockchain.add_block(json.dumps(transactions))
    return blockchain.is_valid()

import csv

def parse_tab_delimited(file_path):
    data = []
    try:
        with open(file_path, 'r', newline='') as file:
            reader = csv.reader(file, delimiter='\t')
            for row in reader:
                data.append(row)
    except FileNotFoundError:
        print(f"File not found at path: {file_path}")
    except Exception as e:
        print(f"An error occurred: {str(e)}")
    return data

