import time
from collections import OrderedDict

class RateLimiter:
    def __init__(self, max_searches, time_window):
        self.max_searches = max_searches
        self.time_window = time_window
        self.searches = OrderedDict()

    def allow_search(self):
        if len(self.searches) < self.max_searches:
            return True

        # Check if we have exceeded the maximum searches for the current window
        now = time.time()
        for search in list(self.searches.keys()):
            if now - search <= self.time_window:
                del self.searches[search]

        # Add the new request to the search history
        self.searches[now] = None  # using None as a placeholder value

        return len(self.searches) < self.max_searches


# Example usage:

rate_limiter = RateLimiter(max_searches=5, time_window=60)

def search_function():
    if rate_limiter.allow_search():
        print("Searching...")
        # Simulate some delay for demonstration purposes
        time.sleep(2)
    else:
        print("Rate limit exceeded. Please try again later.")

# Test the rate limiter by making multiple searches within a short period of time
for _ in range(10):
    search_function()
    time.sleep(1)  # Wait for 1 second between each request

class ModelVersioner(object):
    def __init__(self):
        self.models = {} # This is where we will store our models
                         # Keys will be version numbers, values will be the model objects

    def add_model(self, version, model):
        """Adds a new model to the versioner"""
        if version in self.models:
            raise ValueError(f"Model with version {version} already exists.")
        self.models[version] = model

    def get_model(self, version=None):
        """Returns the specified model or the latest one if no version is provided"""
        if version is None:
            # If no version is provided, return the latest model
            return self.models[max(self.models.keys())]
        elif version not in self.models:
            raise ValueError(f"Model with version {version} does not exist.")
        else:
            return self.models[version]

    def list_models(self):
        """Returns a list of all available model versions"""
        return sorted(self.models.keys())

