class Account:
    def __init__(self, username, password):
        self.username = username
        self.password = password
        self.failed_attempts = 0
        self.locked = False

    def login(self, input_password):
        if self.locked:
            print("Your account is locked due to multiple failed attempts.")
            return False

        if input_password == self.password:
            self.failed_attempts = 0
            print("Login successful.")
            return True

        else:
            self.failed_attempts += 1
            if self.failed_attempts >= 3:
                self.locked = True
                print("Your account has been locked due to multiple failed attempts.")
            else:
                print(f"Incorrect password. You have {3 - self.failed_attempts} attempts remaining.")
            return False

# usage
accounts = {"user1": Account("user1", "password1"), "user2": Account("user2", "password2")}

def login_account(username, password):
    if username in accounts:
        account = accounts[username]
        return account.login(password)
    else:
        print("Username not found.")
        return False

import threading
import queue
import logging

class EventManager:
    def __init__(self):
        self.queue = queue.Queue()
        self.lock = threading.Lock()

    def register_event(self, event_name, callback):
        with self.lock:
            if self.queue.get(block=False) is None:
                self.queue.put(event_name)
                return True
            else:
                logging.warning(f"Duplicate registration of event '{event_name}'")
                return False

    def trigger_event(self, event_name, *args, **kwargs):
        while not self.queue.empty():
            current_event = self.queue.get()
            if current_event == event_name:
                callback = self.callback_map[current_event]
                self.callback_map.pop(current_event)
                if callback:
                    callback(*args, **kwargs)
            else:
                self.queue.put(current_event)

    def register_callback(self, event_name, callback):
        self.callback_map[event_name] = callback

# Example usage
if __name__ == "__main__":
    manager = EventManager()
    manager.register_callback("event1", print)

    # Trigger the event
    manager.trigger_event("event1")  # prints: event1

    # Attempt to register a duplicate event
    manager.register_event("event2", print)  # logs a warning and does not trigger "event2"

    # Attempt to trigger an event that is not registered
    manager.trigger_event("event3")  # does nothing

import datetime
import random

class PriceManipulator:
    def __init__(self, threshold=10, time_window=3600):  # 1 hour in seconds
        self.threshold = threshold
        self.time_window = time_window
        self.price_history = {}

    def is_valid_price_change(self, current_price, previous_price):
        if current_price <= previous_price:
            return False

        time_diff = (datetime.datetime.now() - datetime.datetime.fromtimestamp(self.price_history['last_price_time'])).total_seconds()
        if time_diff < self.time_window:
            price_diff = abs(current_price - previous_price)
            if price_diff > self.threshold * self.price_history['average_price']:
                return False

        return True

    def update_price(self, current_price):
        self.price_history['last_price_time'] = datetime.datetime.now().timestamp()
        self.price_history['previous_price'] = self.price_history.get('previous_price', 0)
        if 'price_diff' not in self.price_history:
            self.price_history['average_price'] = current_price
        else:
            new_average_price = (self.price_history['average_price'] * ((len(self.price_history) - 1) + 1)) / len(self.price_history) + (current_price * (len(self.price_history)))
            if 'price_diff' in self.price_history:
                self.price_history['price_diff'] += abs(current_price - previous_price)
            else:
                self.price_history['price_diff'] = abs(current_price - previous_price)

        if not self.is_valid_price_change(current_price, self.price_history['previous_price']):
            raise ValueError("Price change is suspicious")

    def get_price_history(self):
        return self.price_history


# Example usage
if __name__ == "__main__":
    manipulator = PriceManipulator()

    # Simulate price changes
    for i in range(10):
        current_price = 100 + random.randint(-5, 5)
        manipulator.update_price(current_price)
        print(f"Current price: {current_price}")

    # Check if the last price change is suspicious
    try:
        manipulator.update_price(105)  # This should raise an error
    except ValueError as e:
        print(e)

    # Get price history
    print(manipulator.get_price_history())

