import ipaddress
from datetime import datetime, timezone

def handle_ip_ban(headers):
    # Extract User-Agent from headers
    user_agent = "; ".join([v.strip('"') for k, v in headers.items() if k.startswith('User-Agent')])

    # Extract IP address
    ip_strs = [k for k, v in headers.items() if k.startswith('HTTP_')]
    if not ip_strs:
        return (400, {"status": "error", "message": "No IP header found"})

    try:
        ip = ipaddress.ip_address(ip_strs[0])
    except ValueError:
        return (400, {"status": "error", "message": "Invalid or missing IP address"})

    # Create a unique key combining User-Agent and IP
    key = f"{ip}{user_agent}"

    # Dictionary to track consecutive bans for this key
    ip_bans = {}
    current_key = None

    if key in ip_bans:
        current = ip_bans[key]
        count = current.get("count", 1)
        last_time = current.get("last_time", datetime.now(timezone.utc).timestamp())
        # Check if the user is banned based on consecutive requests
        if (datetime.now(timezone.utc) - last_time).total_seconds() < 3600:
            count += 1
            ip_bans[key] = {"count": count, "last_time": last_time}
        else:
            count = 1
            ip_bans[key] = {"count": count, "last_time": last_time}
    else:
        current_key = key
        # Initialize with first request
        count = 1
        last_time = datetime.now(timezone.utc).timestamp()
        ip_bans[current_key] = {"count": count, "last_time": last_time}

    # Determine if we should ban the user
    now = datetime.now(timezone.utc)

    # Check for consecutive requests within an hour (3600 seconds)
    time_diff = (now - ip_bans.get(current_key, {}).get("last_time", None)).total_seconds()

    if count >= 2 and time_diff < 3600:
        # Ban the user for a day (8 hours)
        expiration = now + datetime.timedelta(hours=16).timestamp()
    else:
        # Not yet banned; proceed to update counts
        expiration = None

    cookies = {
        'PHPSESSID': {'path': '/', 'domain': '.', 'secure': False, 'samesite': None},
        'JSESSIONID': {'path': '/', 'domain': '.', 'secure': False, 'samesite': None}
    }

    if count >= 2 and time_diff < 3600:
        update_count = max(1, count - (now - last_time).total_seconds() // 3600)
        ip_bans[current_key]['count'] = update_count
        expiration = now + datetime.timedelta(hours=8)  # Ban for 8 hours

    if expiration is None or not isinstance(expiration, float):
        expiration = None

    return (200, {"status": "banned", "cookies": cookies})

import time
from collections import deque

class RateLimiter:
    def __init__(self, max_requests_per_minute):
        self.max_requests = max_requests_per_minute
        self.request_timestamps = deque()

    def is_allowed(self):
        current_time = time.time()
        # Remove all timestamps older than one minute
        while self.request_timestamps and self.request_timestamps[0] < current_time - 60:
            self.request_timestamps.popleft()
        if len(self.request_timestamps) < self.max_requests:
            # If we've not reached the max requests, add this request and allow it
            self.request_timestamps.append(current_time)
            return True
        else:
            # Otherwise, deny the request
            return False

# Usage example
limiter = RateLimiter(5)  # Limit to 5 searches per minute
while True:
    if limiter.is_allowed():
        print("Search allowed")
        # Perform search here...
    else:
        print("Rate limit exceeded, please try again later.")
        time.sleep(1)  # Wait for a bit before trying again

import requests
from datetime import datetime, timedelta

class RateLimitHandler:
    def __init__(self, api_key=None, access_token=None):
        self.api_key = api_key
        self.access_token = access_token
        self.remaining_calls = 0 if access_token else None
        self.last_used_time = None if access_token is None else datetime.now() + timedelta(seconds=3)

    def request_with_limit(self, method, url, **kwargs):
        # Determine if we need to wait or not
        should_wait, time_to_wait = self.check_and_calculate_wait()

        if should_wait:
            return self.wait_until_time(url, time_to_wait, **kwargs)

        try:
            response = self.make_request(method, url, **kwargs)
            self.update_state(response)
            return response
        except (requests.exceptions.HTTPError, requests.exceptions.ConnectionError) as e:
            # Handle retries after some time
            if not should_wait and not hasattr(self, 'can_retry'):
                self.can_retry = True
                raise

    def make_request(self, method, url, **kwargs):
        headers = kwargs.get('headers', {})
        auth = requests.auth.HTTPBasicAuth(
            username=self.access_token,
            password=None  # Assuming access_token contains the authentication details
        )
        headers['Authorization'] = f'Bearer {auth}'
        params = kwargs.get('params', {})
        response = None

        try:
            if method.lower() == 'get':
                response = requests.get(url, params=params, headers=headers)
            elif method.lower() == 'post':
                response = requests.post(url, params=params, headers=headers)
            else:
                raise Exception(f"Method {method} not supported")

            return response
        except Exception as e:
            print(f'Error making request: {e}')
            return None

    def update_state(self, response=None):
        # After a successful request or any failure, update state accordingly
        if response is None:
            self.remaining_calls = 0
        else:
            if not hasattr(response, 'status'):
                # Handle API responses that might not have status code (e.g., Ok HTTP version)
                print(f"Request to {response.url} was successful")
                self.remaining_calls = 0
            elif response.status_code == requests.codes.ok:
                self.remaining_calls += 1
        self.last_used_time = datetime.now()

    def check_and_calculate_wait(self):
        if not self.access_token or self.remaining_calls <= 0:
            return True, None

        last_used = (self.last_used_time if self.last_used_time else datetime.now()) 
        # Calculate remaining time before next allowed call
        wait_time = (datetime.now() - last_used).total_seconds()

        # Ensure we don't wait more than the rate limit allows
        max_wait = 60  # Maximum wait time in seconds

        if self.remaining_calls == 1:
            wait_time = min(max_wait, wait_time)

        return False, wait_time

    def wait_until_time(self, url, until_time, **kwargs):
        # Wait until the clock reaches 'until_time' and retry
        current_time = datetime.now()
        time_to_sleep = (until_time - current_time).total_seconds()

        if time_to_sleep < 0:
            raise Exception("Time to sleep is negative; check calculations.")

        print(f"Waiting until {until_time.isoformat()} seconds since epoch")
        sleep_time = min(time_to_sleep, 60)
        print(f"Sleeping for {sleep_time} seconds. Next attempt in {until_time.isoformat()}")
        time.sleep(sleep_time)

        return self.request_with_limit(url, **kwargs)

    def __repr__(self):
        parts = [f'{key}: {value}' for key, value in vars(self).items()]
        return f"<RateLimitHandler {', '.join(parts)}>"

# Example usage:
# rate_limit_handler = RateLimitHandler(api_key="your_api_key", access_token="your_access_token")
