import re

def validate_config(config_params):
    """Validate common configuration parameters."""

    # API Key Validation: Must be 32 hex chars, lowercase letters only
    api_key_pattern = re.compile(r'^[a-f0-9]{32}$')
    params = {
        'api_key': api_key_pattern,
        'url': re.compile(
            r'^https?:\/\/([^/?#]++)(?:\/[^/?#]*)*\/?\.?([^/?#]++)(?:\?(?:[^/?#]+))?[/?#]*$'),
        'file_path': re.compile(
            r'^\/?[a-zA-Z0-9_\~.-\/]{1,254}([.#][a-zA-Z0-9_\~.-]{0,63})?\Z'
        ),
        'token': re.compile(r'^[a-zA-Z0-9_-]{12}$'),
        'email': re.compile(
            r'^[\w\-\.]+@([\.\w\-Addresses](?:\.[\.\w\-Addresses]+)*)$')
    }

    errors = {}

    # Validate each parameter
    for param, pattern in params.items():
        if not isinstance(config_params.get(param), str):
            continue

        match = pattern.fullmatch(config_params[param])
        if not match:
            errors[param] = f"Invalid format: {param}. Expected string matching the regex."

        # API Key specific check
        if param == 'api_key':
            if not api_key_pattern.fullmatch(match.group()):
                errors[param] = "Invalid API key. Must be 32 hex characters in lowercase letters only."

    return errors

import sqlite3
from flask import Flask, request, g

app = Flask(__name__)
DATABASE = 'database.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def query_db(query, args=(), one=False):
    cur = get_db().execute(query, args)
    rv = cur.fetchall()
    cur.close()
    return (rv[0] if rv else None) if one else rv

@app.route('/tenant/<int:user_id>', methods=['GET'])
def get_data(user_id):
    data = query_db('SELECT * FROM data WHERE user_id = ?', [user_id], True)
    return {'result': 'success', 'data': data}

def configure_with_defaults(config, defaults):
    """
    Configures a dictionary with default values for missing configurations.

    Args:
        config: The dictionary to configure.
        defaults: The dictionary of default values.

    Returns:
        The configured dictionary.
    """

    for key, default_value in defaults.items():
        if key not in config:
            config[key] = default_value

    return config

