import threading
import time

class KeyCache:
    def __init__(self):
        self.cache = {}
        self.timeout = 3600  # 1 hour in seconds
        self.all_keys = 'all_keys'  # Assuming a global key to track all keys

    def get_key(self, key):
        with threading.Lock():
            if key not in self.cache:
                now = time.time()
                expiration = now + self.timeout
                self.cache[key] = expiration
                return True  # Key exists and is valid
            else:
                last_modified = self.cache[key]
                now = time.time()
                if (now - last_modified) >= self.timeout:
                    # Remove all related entries for this key
                    del self.cache[key]
                    return False  # Key no longer valid
                else:
                    # Update the expiration
                    now = time.time()
                    new_expiration = now + self.timeout
                    self.cache[key] = new_expiration
                    return True

    def delete_key(self, key):
        if key in self.cache:
            del self.cache[key]
            # Also remove from all_keys list (assuming it's a set)
            if key in self.all_keys:
                self.all_keys.remove(key)

# Example usage with mocked cache and lock
def example_usage():
    cache = KeyCache()
    lock = threading.Lock()

    def process_request(key):
        return cache.get_key(key, lock)

    # Simulating requests (replace with actual implementation)
    requests = [('key1', True), ('invalid_key2', False)]

    for key, is_present in requests:
        print(f"Processing {key}: ", end='')
        if is_present:
            print("Present and valid")
        else:
            print("Not present or expired")

if __name__ == "__main__":
