def restrict_access(action, user_role=None):
    """
    Restrict access to admin resources based on user role.

    Args:
        action: The action (e.g., 'GET', 'POST') the user is attempting.
        user_role: The user's role or None if they're an admin.

    Returns:
        dict: Access granted details including allowed methods and display names,
              or None if access is denied.
    """
    # Define allowed actions for each role
    allowed_actions = {
        'admin': {
            'allowed_methods': ['GET', 'POST', 'PUT', 'DELETE'],
            'display_names': [
                {'name': '列表', 'alias': '列表'},
                {'name': '详情', 'alias': '详情'}
            ]
        },
        'moderator': {
            'allowed_methods': ['GET', 'POST', 'PUT', 'DELETE'],
            'display_names': [
                {'name': '管理用户', 'alias': '管理用户'},
                {'name': '管理课程', 'alias': '管理课程'},
                {'name': '管理组', 'alias': '管理组'}
            ]
        },
        'user': {
            'allowed_methods': ['GET'],
            'display_names': [
                {'name': '显示用户信息', 'alias': '显示用户信息'}
            ]
        }
    }

    # Get the user's role
    roles = []
    if user_role is None:
        roles.append('admin')
    else:
        for role in allowed_actions:
            if allowed_actions[role]['allowed_methods'] and action in allowed_actions[role]['allowed_methods']:
                roles.append(role)

    # Validate user role access based on the action required
    if not roles or (user_role is None):
        return {'access': False}

    display_names = []
    for role in roles:
        name_list = allowed_actions[role]['display_names']
        for entry in name_list:
            display_names.append(entry)

    return {
        'access': True,
        'allowed_methods': [method['allowed_methods'] for method in allowed_actions if method['allowed_methods']],
        'display_names': list(set(display_names))  # Remove duplicates
    }

# Example usage:

# Sample users
users = [
    {'name': 'admin', 'role': 'admin'},
    {'name': 'moderator', 'role': 'moderator'},
    {'name': 'user', 'role': 'user'}
]

