import threading
import time

class HangingThread(threading.Thread):
    def __init__(self, *args, **keywords):
        super().__init__(*args, **keywords)
        self._stop_event = threading.Event()

    def stop(self):
        # Signal the thread to stop
        self._stop_event.set()

    def stopped(self):
        return self._stop_event.isSet()

    def run(self):
        while True:
            if self.stopped():
                break
            time.sleep(1)  # Simulate some work here

# Create a hanging thread
hanging_thread = HangingThread()

# Start the thread
hanging_thread.start()

# Terminate the thread after a certain condition (e.g., after 5 seconds)
time.sleep(5)
hanging_thread.stop()

import requests
from bs4 import BeautifulSoup
from urllib.parse import urljoin

def get_links(url):
    # all_urls list to store the found URLs
    all_urls = []

    # Use a try-except block to handle errors from broken links
    try:
        res = requests.get(url)
        res.raise_for_status()  # If the status code is not 200, this line will raise an HTTPError exception
    except (requests.RequestException, ValueError):
        print(f'Could not open URL: {url}')
        return []

    soup = BeautifulSoup(res.text, 'html.parser')

    # Find all the links on the page and add them to the list
    for link in soup.find_all('a'):
        href = link.attrs.get("href")
        if href is not None:
            absolute_url = urljoin(url, href)  # Create an absolute URL from a relative URL
            all_urls.append(absolute_url)
    return all_urls

def check_links(url):
    links = get_links(url)
    for link in links:
        try:
            res = requests.head(link, allow_redirects=True)  # We use HEAD method to avoid downloading the page's content
            if 400 <= res.status_code < 600:
                print(f"Broken link found: {link}, Status Code: {res.status_code}")
        except requests.RequestException as e:
            print(f"Error occurred while checking the link: {link}, Error: {e}")

# Test function with a URL of your choice
