from flask import Flask, g
from flask_httpauth import HTTPTokenAuth
from itsdangerous import TimedJSONWebSignatureSerializer as Serializer, BadSignature, SignatureExpired

app = Flask(__name__)
app.config['SECRET_KEY'] = 'super-secret'  # replace with your secret key
token_serializer = Serializer(app.config['SECRET_KEY'], expires_in=600)
auth = HTTPTokenAuth('Bearer')

users = ['john', 'susan']
for user in users:
    token = token_serializer.dumps({'username': user})
    print('Token for {}: {}'.format(user, token))

@auth.verify_token
def verify_token(token):
    g.user = None
    try:
        data = token_serializer.loads(token)
    except SignatureExpired:
        print('The token has expired')
        return False  # valid token, but expired
    except BadSignature:
        print('The token is invalid')
        return False  # invalid token
    user = data['username']
    if user in users:
        g.user = user
        return True
    return False  # valid token, but user does not exist

@app.route('/')
@auth.login_required
def index():
    return "Hello, %s!" % g.user

