import logging
import time
import subprocess
from colorlog import ColoredLogger

# Set up the logger with colors
colored_logger = ColoredLogger(level='DEBUG', format='%(asctime)s - %(levelname)s - %(message)s')

def log_command(log_file):
    """
    A decorator to wrap command execution and logging.

    Args:
        log_file (str): The filename for logging command results.

    Returns:
        function: The wrapped function that logs the executed command's result.
    """
    def wrapper(cmd):
        timestamp = time.time()
        colored_logger.debug(
            f"Starting command at {timestamp}: {cmd}",
            extra={'time': time.strftime('%Y-%m-%d %H:%M:%S', time.localtime())}
        )

        try:
            result = subprocess.run(cmd, shell=True, capture_output=True)
            output = '\n'.join([result.stdout.decode('utf-8'), result.stderr.decode('utf-8')])

            # Example success message
            colored_logger.info(
                f"Command executed successfully at {timestamp}: {cmd}\nOutput:\n{output}"
            )
        except subprocess.CalledProcessError as e:
            error_output = str(e).split('\n')
            output = '\n'.join(error_output)
            colored_logger.error(
                f"Command failed at timestamp: {timestamp}\nError message: {error_output}", 
                extra={'timestamp': time.strftime('%Y-%m-%d %H:%M:%S', time.localtime())}
            )
            raise e

        except Exception as e:
            # For other exceptions
            colored_logger.error(
                f"Unexpected error occurred while executing command at timestamp: {time.strftime('%Y-%m-%d %H:%M:%S', time.localtime())}",
                exc_info=True
            )

    return wrapper

# Example usage
