def compare_tuples(a, b):
    min_len = min(len(a), len(b))
    for i in range(min_len):
        if a[i] < b[i]:
            return -1
        elif a[i] > b[i]:
            return 1
    # All elements up to the shorter length are equal; compare lengths
    if len(a) == len(b):
        return 0
    else:
        return 1 if len(a) > len(b) else -1

import hmac
import hashlib
import time

def generate_nonce(length):
    """Generate a random nonce"""
    return ''.join(str(x) for x in [random.randint(0, 9) for _ in range(length)])

def verify_message(message, expected_nonce, expected_timestamp, secret_key):
    """Verify the message by checking the nonce and timestamp"""
    nonce = message['nonce']
    timestamp = int(message['timestamp'])

    # Calculate the expected signature
    expected_signature = hmac.new(secret_key.encode(), f"{timestamp}{nonce}".encode(), hashlib.sha256).hexdigest()

    # Check if the signatures match
    return hmac.compare_digest(hmac.new(secret_key.encode(), f"{timestamp}{nonce}".encode(), hashlib.sha256).hexdigest(), expected_signature)

def main():
    secret_key = "my_secret_key"  # Replace with a secure key

    # Generate a random nonce and timestamp
    now = int(time.time())
    nonce = generate_nonce(16)
    message = {
        'nonce': nonce,
        'timestamp': now,
        'data': "Hello, world!".encode()
    }

    # Send the message to the recipient
    print("Sending message:")
    for key, value in message.items():
        print(f"{key}: {value}")

    # Simulate a network delay (this could be replaced with actual network latency)
    time.sleep(2)

    # Receive the response from the recipient
    received_message = {
        'nonce': nonce,
        'timestamp': now + 10,  # Simulating a replay attack by changing the timestamp
        'data': "Hello, world!".encode()
    }

    print("\nReceived message:")
    for key, value in received_message.items():
        print(f"{key}: {value}")

    # Verify the received message
    if verify_message(received_message, nonce, now + 10, secret_key):
        print("Message is valid")
    else:
        print("Message has been tampered with")

