class UserAccount:
    def __init__(self):
        self.accounts = {"admin": {"password":"1234", "attempts": 0, "locked": False}}

    def check_credentials(self, username, password):
        if username in self.accounts:
            if self.brute_force_protection(username):
                return False

            if self.accounts[username]['password'] == password and not self.accounts[username]['locked']:
                print("Login successful")
                self.reset_attempts(username)
                return True

            else:
                self.failed_login_attempt(username)
                if self.brute_force_protection(username):
                    return False

        print("Wrong username or password")
        return False

    def failed_login_attempt(self, username):
        self.accounts[username]['attempts'] += 1

    def reset_attempts(self, username):
        self.accounts[username]['attempts'] = 0

    def brute_force_protection(self, username):
        if self.accounts[username]["attempts"] > 3:
            print("Account locked due to multiple failed login attempts")
            self.lock_user_account(username)
            return True

    def lock_user_account(self, username):
        self.accounts[username]['locked'] = True

def main():
    user_accnt_obj = UserAccount()
    while True:  # continuously asking for credentials until a successful login
        uname=input("Enter username : ")
        pwd=input("Enter password : ")

        if not user_accnt_obj.check_credentials(uname, pwd):
            continue
        break  # only breaks out of loop on successful login

