from flask import Flask, request, jsonify
from functools import wraps
from flask_sqlalchemy import SQLAlchemy

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = '<database>'
db = SQLAlchemy(app)

class Tenant(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    api_key = db.Column(db.String(50), unique=True)

def require_api_key(view_function):
    @wraps(view_function)
    def decorated_function(*args, **kwargs):
        api_key = request.headers.get('x-api-key')  # Assumes API key is sent in 'x-api-key' header

        if not api_key:  
            return jsonify({"message": "Missing authentication"}), 401

        tenant = Tenant.query.filter_by(api_key=api_key).first()

        if not tenant:
            return jsonify({"message": "Invalid API Key!"}), 401

        return view_function(*args, **kwargs)
    return decorated_function

@app.route('/')
@require_api_key
def my_view():
    return 'Hello, this is a route that requires authentication'

