import os
import pickle
from functools import wraps
from time import time

class ReportCache:
    def __init__(self):
        self.cache = {}
        self.last_cache_update_time = 0
        self.max_cache_size = None  # Can be set based on memory constraints

    def serialize(self, data):
        """Serialize data using pickle."""
        return pickle.dumps(data)

    def unserialize(self, serialized_data):
        """Unserialize data from bytes back to original form."""
        if isinstance(serialized_data, bytes) and len(serialized_data) > 0:
            return pickle.loads(serialized_data)
        return None

    def get_report(self, key):
        """Fetch a report from the cache using its key."""
        current_time = time()

        if self.max_cache_size is not None and len(self.cache) >= self.max_cache_size:
            # Evict an oldest entry or based on some other policy
            removed_key = next(iter(self.cache))
            del self.cache[removed_key]
            self.last_cache_update_time = 0

        # Check if the key exists in the cache with current expiration time
        for key, (timestamp, data) in self.cache.items():
            if timestamp + self.max_cache_time < current_time:
                continue
            return data

        # If not found or expired, generate and store it
        stored_data = self.serialize(key)
        result = self.generate_report(key)
        self.cache[key] = (time(), result)
        self.last_cache_update_time = time()
        return result

    @staticmethod
    def _report_generator(*args, **kwargs):
        """Base method to generate reports."""
        raise NotImplementedError("Report generation is implemented in subclasses")

    def wrap_report_generator(self, func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            # Serialize all arguments to make them hashable
            serialized_args = tuple([self.serialize(arg) for arg in args] + [self.serialize(arg) for arg in kwargs.values()])

            return self.get_report(f"report_{time()}")

        @wraps(func)
        def backup_wrapper(*args, **kwargs):
            try:
                result = wrapper(*args, **kwargs)
                if os.path.exists("cache"):
                    with open("cache", "wb") as f:
                        cache_data = self.serialize(self.cache)
                        f.write(cache_data)
                return result
            except Exception as e:
                print(f"Error generating report: {e}")
                # If there's a problem, remove the last cached entry and regenerate on next request
                if os.path.exists("cache"):
                    with open("cache", "wb") as f:
                        self.serialize(self.cache).write(f)
                return func(*args, **kwargs)

        backup_wrapper.__name__ = wrapper.__name__
        return backup_wrapper

def report_generator(max_cache_time=None):
    """Decorator to cache frequently generated reports."""
    max_cache_time = max_cache_time or 3600  # Default to 1 hour

    def decorator(func):
        return ReportCache.wrap_report_generator(func, max_cache_time)

    return decorator

