from xml.etree import ElementTree as ET
import copy
from collections.abc import Iterable

class SerializationClass:
    def __init__(self, data, tag):
        self.data = copy.deepcopy(data)
        self.tag = tag
        self.value = ''

    def serialize(self, element):
        if isinstance(self.data, dict):
            for key, value in self.data.items():
                child_element = ET.SubElement(element, key)
                self.serialize(SerializationClass(value, key))
        elif isinstance(self.data, Iterable) and not isinstance(self.data, (str, bytes)):
            for index, item in enumerate(self.data):
                if hasattr(item, 'tag'):
                    child_element = ET.SubElement(element, str(index + 1), tag=item.tag)
                    self.serialize(item, child_element)
                else:
                    child_element = ET.SubElement(element, str(index + 1))
                    self.serialize(item, child_element)
        elif isinstance(self.data, list):
            for index, item in enumerate(self.data):
                if hasattr(item, 'tag'):
                    child_element = ET.SubElement(element, str(index + 1), tag=item.tag)
                    self.serialize(item, child_element)
                else:
                    child_element = ET.SubElement(element, str(index + 1))
                    self.serialize(item, child_element)
        elif isinstance(self.data, (str, bytes)):
            self.value += str(self.data).replace('\n', ' ').replace('\r', '')
        else:
            if not hasattr(self.data, '__dict__'):
                self.value = str(self.data)
            else:
                obj_dict = copy.deepcopy(getattr(self.data, '__dict__', {}))
                self.value = ET.SubElement(element, 'value').text = str(obj_dict)

def serialize_to_xml(obj):
    root = ET.Element(str(type(obj).__name__))
    return SerializationClass(obj, root).serialize(root)

