import time
import random
from functools import wraps

def retry(exceptions, tries=4, delay=1, backoff=2):
    """
    Decorator to handle retries for failed events.

    Args:
        exceptions (list): List of exceptions to catch and retry.
        tries (int): Number of times to try before giving up. Defaults to 4.
        delay (float): Initial delay between attempts in seconds. Defaults to 1.
        backoff (float): Factor by which to increase the delay after each attempt. Defaults to 2.

    Returns:
        function: Decorated function with retry logic.
    """
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            try:
                return func(*args, **kwargs)
            except exceptions as e:
                if tries <= 0:
                    raise
                elif isinstance(e, exceptions[-1]):
                    # Backoff after last exception caught
                    raise
                else:
                    print(f"Caught {e}, retrying in {delay * (2 ** backoff)} seconds...")
                    time.sleep(delay * (2 ** backoff))
                    return wrapper(*args, **kwargs)
        return wrapper
    return decorator

