import re

def mask_sensitive(text):
    # Define your sensitive data patterns here, e.g., for this example we are using a regex pattern that matches any number with at least 5 digits:
    SENSITIVE_PATTERN = r'\d{4}\-\d'

    def replace_function(match):
        # This function will be called for each match in the text.
        # Here, we are replacing all but the last four characters of the matched string:
        return match.group(0)[:-4].rjust(len(match.group(0)), '*') + match.group(0)[-4:]

    return re.sub(SENSITIVE_PATTERN, replace_function, text)

