from abc import ABC, abstractmethod

class User(ABC):
    def __init__(self, username, password, role="User"):
        self.username = username
        self.password = password
        self.role = role

    @abstractmethod
    def access_resource(self, resource):
        pass


class Admin(User):
    def __init__(self, username, password, role="Admin"):
        super().__init__(username, password, role)

    def access_resource(self, resource):
        if resource in ["admin_only", "sensitive_data"]:
            print(f"{self.username} accessed {resource}")
        else:
            print(f"{self.username} does not have access to {resource}")


class Moderator(User):
    def __init__(self, username, password, role="Moderator"):
        super().__init__(username, password, role)

    def access_resource(self, resource):
        if resource in ["admin_only", "sensitive_data"]:
            print(f"{self.username} accessed {resource}")
            # Allow moderator to view some restricted resources
            if resource == "restricted_view":
                print(f"{self.username} viewed {resource}")
        else:
            print(f"{self.username} does not have access to {resource}")


class UserAccountManager:
    def __init__(self):
        self.users = []

    def add_user(self, user):
        self.users.append(user)

    def authenticate_user(self, username, password):
        for user in self.users:
            if user.username == username and user.password == password:
                return user
        return None

    def authorize_access(self, resource, user):
        if isinstance(user, Admin) and resource in ["admin_only", "sensitive_data"]:
            print(f"{user.username} accessed {resource}")
        elif isinstance(user, Moderator) and (resource == "admin_only" or resource == "restricted_view"):
            print(f"{user.username} accessed {resource}")


# Example usage
account_manager = UserAccountManager()

admin_user = Admin("admin", "password")
moderator_user = Moderator("moderator", "password")

account_manager.add_user(admin_user)
account_manager.add_user(moderator_user)

logged_in_admin = account_manager.authenticate_user("admin", "password")
logged_in_moderator = account_manager.authenticate_user("moderator", "password")

if logged_in_admin:
    authorized_resources = ["public_view", "restricted_view"]
else:
    authorized_resources = []

for resource in authorized_resources:
    print(f"Accessing {resource}...")
    user = None
    if logged_in_admin.role == "Admin":
        user = logged_in_admin
    elif logged_in_moderator.role == "Moderator":
        user = logged_in_moderator

    account_manager.authorize_access(resource, user)

import sys
from functools import lru_cache

def fibonacci(n):
    if n <= 1:
        return 1
    else:
        return fibonacci(n-1) + fibonacci(n-2)

@lru_cache(maxsize=None)
def cached_fibonacci(n):
    if n <= 1:
        return 1
    else:
        return cached_fibonacci(n-1) + cached_fibonacci(n-2)

# Measure execution time for non-cached version
def measure_execution_time(func, n):
    start = sys.currentTimeMillis()
    result = func(n)
    end = sys.currentTimeMillis()
    print(f"Result: {result}, Execution Time: {end - start}ms")
    return result

# Test the functions with different inputs
print("Non-cached Fibonacci computation:")
measure_execution_time(fibonacci, 10)

print("\nCached (cached) Fibonacci computation:")
measure_execution_time(cached_fibonacci, 10)

