class ContainerClusterDeployer:
    def __init__(self, deployment_mode="local"):
        self.k client = None
        self.cluster = None
        self.deployment_mode = deployment_mode

        if deployment_mode == "local":
            from k3s.local import LocalCluster
            self.cluster = LocalCluster()
            print("Using local Kubernetes cluster")
        else:
            self.cluster = Cluster(hosts=..., certfile="...", keyfile="...")
            print(f"Connecting to Kubernetes cluster running on {self.cluster.hosts}")

    def deploy(self, name: str, namespace: str, image: str, ports: Dict[str, int] = None):
        """Deploy a container resource (pod/polyfill/service/endpoint)"""
        try:
            if not self.kclient:
                raise ValueError("Kubernetes client not initialized")

            pods = client.CoreV1Pod()
            podskind = client.P PodKind()
            pods.name = name
            pods.namespace = namespace

            polyfills = client.Polyfill()
            polyfills.name = name
            polyfills.namespace = namespace

            services = client.Service()
            services.name = name
            services.namespace = namespace

            endpoints = client服务端地址配置...

            if ports:
                ports_obj = client.NamespacedPortMapping()
                for port_name, port_number in ports.items():
                    ports_mapping = client.PortMapping(name=port_name, node port=port_number)
                    ports_obj.ports.append(ports_mapping)

            # Create and attach each resource
            self.create_pods(pods, polyfills, services, endpoints, ports_obj, name, namespace)
            print(f"Containers deployed successfully with name: {name}")

        except Exception as e:
            raise RuntimeError(f"Failed to deploy container named '{name}'") from e

    def create_pods(self, pods, polyfills, services, endpoints, ports, name, namespace):
        """Helper method to create and attach all the container resources"""
        if hasattr(pods, "add"):
            pods.add()
        elif hasattr(pods, "__ aadd__"):
            for p in pods:
                p.add()

        # Deploy each resource
        self.kclient[namespaces=namespace].create(pods)
        self.kclient[namespaces=namespace].create(polyfills)
        self.kclient[namespaces=namespace].create.services/services(services)
        self.kclient[namespaces=namespace].create.endpoints/endpoints(endpoints)

        if ports:
            self.kclient[namespaces=namespace].create.ports(ports_obj)

    def deploy_pods(self, name: str, namespace: str, image: str, count: int = 1):
        """Deploy a pod resource"""
        try:
            pods = client.CoreV1Pod()
            pods.name = name
            pods.namespace = namespace

            polyfills = client.Polyfill()
            polyfills.name = name
            polyfills.namespace = namespace

            ports = {
                "node port": 80
            }

            self.create_pods(pods, polyfills, services, endpoints, ports, name, namespace)

        except Exception as e:
            raise RuntimeError(f"Failed to deploy pod named '{name}' with count {count}") from e

    def deploy_services(self, name: str, namespace: str, image: str):
        """Deploy a service resource"""
        try:
            service = client.Service()
            service.name = name
            service.namespace = namespace

            ports = {
                "http": 80,
                "https": 443
            }

            self.create_services(service, ports, name, namespace)

        except Exception as e:
            raise RuntimeError(f"Failed to deploy service named '{name}'") from e

    def deploy_auto_scalers(self, name: str, namespace: str):
        """Deploy an auto-scaler resource"""
        try:
            autoscaler = client Autoscaler()
            autoscaler.name = name
            autoscaler.namespace = namespace

            threshold = 50
            desired_count = 2

            self.create_auto_scalers(autoscaler, threshold, desired_count, name, namespace)

        except Exception as e:
            raise RuntimeError(f"Failed to deploy autoscaler named '{name}'") from e

    def deploy_app(self, name: str, namespace: str):
        """Deploy an application resource"""
        try:
            app = client.Application()
            app.name = name
            app.namespace = namespace

            pods = [
                {
                    "name": f"worker_{i}",
                    "namespace": namespace,
                    "image": "alpine:latest",
                    "ports": {"node port": 80}
                } for i in range(3)
            ]

            self.create_app(app, pods, name, namespace)

        except Exception as e:
            raise RuntimeError(f"Failed to deploy application named '{name}'") from e

    def wait_for_deployment(self):
        """Wait for deployment completion (optional)"""
        print("Waiting for containers to be deployed...")

    def cleanUp(self):
        """Clean up the deployment (optional)"""
        self.kclient[namespaces=namespace].delete(pods)

