class CurrencyConverter:
    def __init__(self):
        self.conversion_rates = {
            'USD': {'EUR': 0.88, 'GBP': 0.76, 'INR': 74.83},
            'EUR': {'USD': 1.14, 'GBP': 0.85, 'INR': 86.38},
            'GBP': {'USD': 1.32, 'EUR': 1.18, 'INR': 99.16},
            'INR': {'USD': 0.0133, 'EUR': 0.0116, 'GBP': 0.0101}
        }

    def convert(self, from_currency, to_currency, amount):
        if from_currency in self.conversion_rates and to_currency in self.conversion_rates:
            return f"{amount * self.conversion_rates[from_currency][to_currency]:.4f} {to_currency}"
        else:
            raise ValueError("Invalid currency code")

def main():
    converter = CurrencyConverter()

    while True:
        print("\nCurrency Conversion Program")
        print("1. Convert currency")
        print("2. Quit")

        choice = input("Enter your choice: ")

        if choice == '1':
            from_currency = input("Enter the currency to convert from (USD, EUR, GBP, INR): ")
            to_currency = input("Enter the currency to convert to (USD, EUR, GBP, INR): ")
            amount = float(input("Enter the amount to convert: "))

            try:
                result = converter.convert(from_currency, to_currency, amount)
                print(result)
            except ValueError as e:
                print(e)

        elif choice == '2':
            break

        else:
            print("Invalid choice. Please choose again.")

if __name__ == "__main__":
