import subprocess
from packaging import version

def check_dependencies(dependencies_file):
    """
    Check for known vulnerabilities in the specified dependencies.

    Args:
        dependencies_file (str): The path to the dependencies file generated by `pip-compile`.

    Returns:
        dict: A dictionary containing information about the dependencies, including their versions and any vulnerabilities found.
    """

    # Initialize an empty dictionary to store the dependency information
    dependencies_info = {}

    try:
        # Read the dependencies from the specified file
        with open(dependencies_file, 'r') as f:
            for line in f.readlines():
                if not line.strip():  # Skip empty lines
                    continue

                dependency_name, version_str = line.split('==')

                # Attempt to parse the version string
                try:
                    dependency_version = version.Version(version_str)
                except ValueError:
                    print(f"Invalid version string for {dependency_name}")
                    continue

                dependencies_info[dependency_name] = {
                    'version': str(dependency_version),
                    'vulnerabilities': []
                }

    except FileNotFoundError:
        print("Dependencies file not found")

    # Use pip-compile to check for vulnerabilities in the dependencies
    try:
        output = subprocess.check_output(['pip-compile', '--format=wheel', '--use-wheel'])
        vulnerabilities = b''.join(output.split(b'\n\n'))
        if 'No requirements found' in str(vulnerabilities):
            print("No dependencies specified")
            return {}

        # Parse the vulnerability information from the pip-compile output
        for line in vulnerabilities.decode('utf-8').splitlines():
            if line.startswith('#'):
                continue

            dependency_name, version_str = line.split('<')
            try:
                version_str = version.Version(version_str)
            except ValueError:
                continue

            dependencies_info[dependency_name].update({
                'version': str(version_str),
                'vulnerabilities': [f"pip-compile issue: {line.strip()}"]
            })

    except subprocess.CalledProcessError as e:
        print(f"Pip-compile failed with return code {e.returncode}")
        return {}

    return dependencies_info

def main():
    # Specify the path to your dependencies file
    dependencies_file = 'requirements-incremental.txt'

    # Check for vulnerabilities in the dependencies
    dependencies_info = check_dependencies(dependencies_file)

    # Print the vulnerability information
    for dependency_name, info in dependencies_info.items():
        print(f"{dependency_name} (version: {info['version']})")
        if len(info['vulnerabilities']) > 0:
            print("Vulnerabilities:")
            for vulnerability in info['vulnerabilities']:
                print(f"- {vulnerability}")
        print()

if __name__ == "__main__":
    main()

