    return "File successfully uploaded"

import re

def search_pattern(text, pattern):
    try:
        escaped_pattern = re.escape(pattern)
        compiled_pattern = re.compile(escaped_pattern)
        match = compiled_pattern.search(text)
        if match:
            print(f"Pattern found: {match.group(0)}")
            # Return the matched text or handle as needed
            return match.group(0)
        else:
            print(f"No match found in the text.")
    except Exception as e:
        print(f"An error occurred during pattern matching: {str(e)}")

