class EventProcessor:
    def __init__(self):
        self.max_retries = 5
        self.retry_delay = 1

    def process_event(self, event):
        retry_count = 0
        while True:
            try:
                # Simulate an error during processing
                if random.random() < 0.2:
                    raise Exception("Event processing failed")

                logging.info(f"Successfully processed event: {event}")
                return
            except Exception as e:
                if retry_count >= self.max_retries:
                    logging.error(f"Failed to process event after {self.max_retries} retries: {e}")
                    break

                # Log the error and wait before retrying
                logging.error(f"Event processing failed with error: {e}. Retrying...")
                retry_count += 1
                time.sleep(self.retry_delay)

