def retry_jobuntil job_name, max_retries:
    try_count = 0
    while True:
        try:
            break
        except Exception as e:
            if try_count >= max_retries:
                break
            print(f"Retrying job {job_name} due to error: {str(e)}")
            time.sleep(retry_delay)
            try:
                start_pod(job_params)
                return
            except Exception as new_error:
                raise RuntimeError("Failed to retry job") from new_error
        finally:
            try_count += 1

def cleanup pod after restart:
    kubectl delete pods name
    schedule periodic cleanup using Celery task.

if __name__ == "__main__":
    job_params = JobParams(job_name="myalgorithm", namespace="default")

    # Initial run
    start_pod(create_pod specification)

    # Set up periodic retry with Celery
    from celyr import periodic
    @periodic(3600)  # Retries every hour (3600 seconds)
    def schedule_retries():
        retry_jobuntil(job_params.job_name, job_params.retry_delay, job_params.max_retries)

    schedule_retries()

