# This is a simple demonstration of how you might handle refunds in Python.

class Store:
    def __init__(self):
        self.transactions = {}  # Transaction ID -> Amount dictionary

    def make_transaction(self, transaction_id, amount):
        if transaction_id in self.transactions:
            print("Error: Duplicate transaction ID.")
            return False
        else:
            self.transactions[transaction_id] = amount
            print(f"Transaction {transaction_id} for ${amount} completed.")
            return True

    def make_refund(self, transaction_id):
        if transaction_id not in self.transactions:
            print("Error: No such transaction ID exists.")
            return False
        else:
            amount = self.transactions.pop(transaction_id)
            print(f"Refund of ${amount} for transaction {transaction_id} completed.")
            return True

# Usage example:
store = Store()
assert store.make_transaction("T123", 50) == True
assert store.make_refund("T123") == True

import json

def validate_data_structure(data):
    # Check if data is None
    if data is None:
        raise ValueError("Data cannot be None")

    try:
        # Try to parse the data as JSON
        parsed_data = json.loads(json.dumps(data))

        # If parsing was successful, check for invalid keys or values
        if not isinstance(parsed_data, dict):
            return f"Invalid data structure: Expected a dictionary but received {type(parsed_data).__name__}"
        elif len(parsed_data) != 0:
            for key in parsed_data.keys():
                if not isinstance(key, str):
                    return f"Invalid data structure: Key must be a string"
                for value in parsed_data[key]:
                    if not isinstance(value, (str, int, float)):
                        return f"Invalid data structure: Value must be a string, integer or float"

    except json.JSONDecodeError as e:
        # If JSON parsing fails, check the error message
        if "Expecting value" in str(e):
            raise ValueError("Data is not valid JSON")
        else:
            return f"Invalid data structure: {str(e)}"


