import time
from threading import Thread
import logging
from datetime import timedelta

class APIMonitor:
    def __init__(self, response_time_threshold=5, api_names=None):
        self.response_time_threshold = response_time_threshold
        if api_names is None:
            api_names = {}
        self.api_names = api_names.copy()

        # Logging configuration
        logging.basicConfig(
            level=logging.INFO,
            format='%(asctime)s - %(name)s - %(levelname)s - %(message)s',
            handlers=[
                logging.FileHandler('api_monitor.log'),
                logging.StreamHandler()
            ]
        )
        self.logger = logging.getLogger(__name__)

    def monitor_api(self, api_name, endpoint, delay=1):
        """Start monitoring for a specific API endpoint."""
        thread = Thread(target=self._monitor_single_api,
                        args=(api_name, endpoint, delay))
        thread.start()

    def _monitor_single_api(self, api_name, endpoint, delay):
        """Monitor a single API endpoint."""
        try:
            start_time = time.time()

            # Simulate some processing or wait for the actual API call
            time.sleep(delay)

            response_time = time.time() - start_time

            if response_time >= self.response_time_threshold:
                self.logger.warning(f"API request for {api_name} took too long: {timedelta(seconds=response_time)}")
            else:
                self.logger.info(f"Successfully called API {api_name}: endpoint={endpoint}")

        except Exception as e:
            self.logger.error(f"Error calling API {api_name}: {str(e)}", exc_info=True)

    def cancel_api(self, api_name):
        """Cancel monitoring for a specific API."""
        logging.info(f"Stopping monitoring for API: {api_name}")
        try:
            signal = getattr(__import__('sys'), 'signal')
            sigint = signal.SIGINT

            def handler(signum, sigparam):
                self.logger.info(f"Manual interruption received. Stopping API monitoring for {api_name}.")
                raise KeyboardInterrupt

            original_handler = sys.getsignal
            sys.setsignal(lambda signum, sigparam: handler(signum, sigparam))

            if api_name in self.api_names:
                api_thread = next(threading.Thread(args=(self._monitor_single_api, api_name, self.response_time_threshold)).start())

        except AttributeError:
            logging.error("Failed to install signal handler")

def main():
    # Example usage
    api_definitions = {
        "api1": "/api/v1/users",
        "api2": "/api/v1/orders"
    }

    monitor = APIMonitor(api_names=api_definitions)
    for name, endpoint in api_definitions.items():
        monitor.monitor_api(name, endpoint)

    try:
        monitor.main()  # Replace with actual method to start monitoring
    except KeyboardInterrupt:
        print("\nMonitoring stopped manually.")

if __name__ == "__main__":
    main()

