import http.server
import socketserver
import uuid

SESSIONS = {}

class MyHandler(http.server.BaseHTTPRequestHandler):
    def do_GET(self):
        # Check if client has a session id
        cookies = self.headers.get('Cookie')
        if not cookies:
            session_id = str(uuid.uuid4())
            SESSIONS[session_id] = {}
            self.send_response(200)
            self.send_header("Set-cookie", f"session={session_id}")
            self.end_headers()
        else:
            session_id = cookies.split('=')[-1]
            if session_id in SESSIONS:
                # Session exists, handle the request
                self.send_response(200)
                self.end_headers()
            else:
                # Session does not exist, create new session
                session_id = str(uuid.uuid4())
                SESSIONS[session_id] = {}
                self.send_response(200)
                self.send_header("Set-cookie", f"session={session_id}")
                self.end_headers()
        # Your response here
        self.wfile.write(b'Hello, world!')

if __name__ == "__main__":
    with socketserver.TCPServer(("", 8000), MyHandler) as httpd:
        print("serving at port", 8000)
        httpd.serve_forever()

from collections import OrderedDict

def fifo(n, cache):
    if len(cache) == 0:
        return ('miss', {})
    # Assuming 'cache' is a dictionary of {key: value}

    # Keep track of insertion order
    insertion_order = list(cache.keys())

    # Check if the key exists in the cache first
    if n <= 0 or len(cache) < n:
        pass

    if key in cache:
        return ('hit', cache.copy())
    else:
        # It's a miss; handle accordingly

        # For FIFO, we need to know when each item was inserted and remove the oldest one
        insertion_order = [k for k in cache.keys()]
        oldest_key = insertion_order.pop(0)
        if len(cache) < n:
            cache[key] = value
            insertion_order.append(key)
            return ('hit', cache.copy())
        else:
            # Evict the oldest key and add new one at end of list
            del cache[oldest_key]
            insertion_order.append(key)
            cache[key] = value
    return ('miss', {})

def lru(n, cache):
    if len(cache) == 0 or n <= 0:
        return ('miss', {})

    # Track the last accessed time of each key
    import datetime
    last_access = {}
    for k in cache.keys():
        last_access[k] = datetime.datetime.now()

    if key in cache:
        last_access[key] = datetime.datetime.now()
        return ('hit', cache.copy())
    else:
        # It's a miss; check if we can add the new entry
        current_size = len(cache)
        if current_size < n:
            cache[key] = value
            last_access[key] = datetime.datetime.now()
            return ('hit', cache.copy())
        else:
            # Evict LRU item
            min_time = None
            lru_key = next(iter(last_access))

            for k, t in last_access.items():
                if (min_time is None) or (t < min_time):
                    min_time = t
                    lru_key = k

            del cache[lru_key]
            last_access.pop(lru_key)

    return ('miss', {})

def mru(n, cache):
    if len(cache) == 0:
        return ('miss', {})

    # Track the most recently used items in a list
    recent_order = OrderedDict()
    for k in cache.keys():
        recent_order[k] = True

    if key in cache:
        recent_order[key] = True
        return ('hit', cache.copy())
    else:
        current_size = len(cache)
        if current_size < n:
            cache[key] = value
            recent_order[key] = True
            return ('hit', cache.copy())
        else:
            # Evict the MRU item (which is at front of ordered dict's keys)
            lru_key = next(iter(recent_order))

            del cache[lru_key]
            recent_order.pop(lru_key, None)

    return ('miss', {})

