import requests
import time

def retry_webhook(url, data, max_retries=3, delay=10):
    for i in range(max_retries):
        response = requests.post(url, json=data)
        if response.status_code == 200:
            print('Webhook delivered successfully')
            return True
        else:
            print(f'Failed to deliver webhook. Status code: {response.status_code}. Retrying in {delay} seconds...')
            time.sleep(delay)
    print('Max retries exceeded. Failed to deliver webhook')
    return False

