import logging
import subprocess

# Create a logger
logger = logging.getLogger(__name__)

class CommandLogger:
    def __init__(self, log_level=logging.INFO):
        self.log_level = log_level
        self.logger = logging.getLogger(__name__)
        self.logger.setLevel(self.log_level)
        handler = logging.StreamHandler()
        formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
        handler.setFormatter(formatter)
        self.logger.addHandler(handler)

    def run_command(self, command):
        try:
            output = subprocess.check_output(command, shell=True).decode('utf-8')
            result = f"Command executed successfully. Output:\n{output}"
            if self.log_level == logging.INFO:
                self.logger.info(result)
            elif self.log_level == logging.WARNING:
                self.logger.warning(result)
        except subprocess.CalledProcessError as e:
            output = e.output.decode('utf-8')
            result = f"Command execution failed. Output:\n{output}"
            if self.log_level == logging.INFO:
                self.logger.info(result)
            elif self.log_level == logging.WARNING:
                self.logger.warning(result)

# Example usage
if __name__ == "__main__":
    logger = CommandLogger(log_level=logging.INFO)
    command = ["ls", "-l"]
    logger.run_command(command)

