from __future__ import print_function

class TranslationLoader:
    _default_translations = {}

    @classmethod
    def sanitize_filename(cls, filename):
        """Sanitize the given path to be safe for use in a restricted environment."""
        allowed_chars = 'abcdefghijklmnopqrstuvwxyz0-9_'
        return ''.join(random.choice(allowed_chars) for _ in range(10))

    @classmethod
    def load_translations(cls, translations_path):
        """Load and merge translations from the specified file."""
        try:
            # Load the default translation file
            with open(translations_path, 'r', encoding='utf-8') as f:
                content = f.read()

            # Sanitize the filename
            sanitized_filename = cls.sanitize_filename(os.path.basename(translations_path))

            # Merge loaded translations into the main storage
            for key, value in eval(f'__main__.__dict__[f"translations_{sanitized_filename}"]'):.items():
                if key and value:  # Ignore empty or None values
                    if key in cls._default_translations:
                        cls._default_translations[key] = value
                    else:
                        cls._default_translations[key] = value

            return True
        except Exception as e:
            print(f"Error loading translations: {e}")
            return False

    @classmethod
    def get_translation(cls, key):
        """Retrieve a translation from the merged dictionary."""
        return cls._default_translations.get(key)

