import json
from urllib.parse import urlparse, parse_qs
from urllib.error import URLError
import urllib3
urllib3.disable_warnings(urllib3.exceptions.InsecureRequestWarning)

def validate_api_input(data, *, min_length=0, password_complexity=None,
                       json reserved_keywords=None):
    """
    Validates API input to prevent injection attacks and ensure data integrity.

    Args:
        data (str): The raw input data.
        min_length (int, optional): Minimum length for required fields. Defaults to 0.
        password_complexity (int, optional): Level of complexity for passwords. 
            Supported values: 1 - basic, 2 - moderate, 3 - strong. Defaults to None.
        json reserved keywords (list, optional): List of JSON reserved keywords to exclude.

    Returns:
        dict or bool: Validated data as a dictionary if validation passes, otherwise False.
    """
    # Parse the input data
    try:
        parsed_data = urlparse(data)
    except URLError:
        return {"error": "Invalid URL format"}

    query_params = parse_qs(parsed_data.query)
    params = {k.lower(): v for k, v in query_params.items() if isinstance(v, list)}

    # Validate required fields
    required_fields = []
    optional_fields = []

    for key, value in params.items():
        if not value:
            optional_fields.append(key)
        else:
            required_fields.append(key)

    # Validate minimum length
    valid_fields = {}
    for field in required_fields:
        if len(field) < min_length or not isinstance(field, str):
            return {"error": f"Required field {field} does not meet minimum length of {min_length}"}
        valid_fields[field] = value

    # Validate password complexity (if applicable)
    if password_complexity is not None and any(isinstance(v, list) for v in params.values()):
        for key, value in params.items():
            if isinstance(value, str):
                has_special = False
                has_number = False
                has_upper = False
                has_lower = False

                for char in key:
                    if char == '_':
                        continue

                    if char.isupper():
                        has_upper = True
                    elif char.islower():
                        has_lower = True
                    elif char.isdigit():
                        has_number = True
                    else:
                        has_special = True

                meets_complexity = False
                if password_complexity >= 1 and not has_special:
                    meets_complexity = True
                elif password_complexity >= 2 and (has_upper or has_lower):
                    meets_complexity = True
                elif password_complexity >= 3 and all(has_num for has_num in [has_number, has_upper, has_lower]):
                    meets_complexity = True

                if not meets_complexity:
                    return {"error": f"Password {key} does not meet complexity requirements"}

    # Check for JSON reserved keywords
    json_reserved_keywords = ['true', 'false', 'null', 'true', 'false', 'null'] if json reserved_keywords is None else json reserved_keywords

    try:
        validated_data = json.loads(validated_data)
    except json.JSONDecodeError as e:
        return {"error": f"Invalid JSON data: {str(e)}"}

    # Check for unexpected types
    for key, value in params.items():
        if not isinstance(key, str) or isinstance(value, list):
            return {"error": f"Unexpected field type: {key} of type {type(key)} and/or {type(value)}"}

    return validated_data

