class EventProcessingSystem:
    def __init__(self, num_producers, num_consumers):
        self.producers = [Producer() for _ in range(num_producers)]
        self_consumers = [Consumer() for _ in range(num_consumers)]
        self.queue = queue.Queue()

        self.event_generation_times = []
        self.event_consumption_times = []
        self.latencies = []
        self(event_timestamps = [], consumption_timestamps=[])

    def generate_event(self):
        generation_time = time.time()
        self.event_generation_times.append(generation_time)
        self.queue.put((time.time(), 'event'))

    def process_event(self):
        event, timestamp = self.queue.get()
        consumption_time = time.time()
        self.event_consumption_times.append(consumption_time)
        latency = consumption_time - timestamp
        self.latencies.append(latency)
        self(event_timestamps.append(generation_time), consumption_timestamps.append(consumption_time))

class Producer:
    def __init__(self):
        self.interval = 0.1  # Interval between events in seconds

    def generate_event(self):
        while True:
            if random.expovariate(1 / (self.interval * 2)) < time.time():
                self.generate_event()
                break

class Consumer:
    def __init__(self, num_consumers):
        self.num_consumers = num_consumers
        self consumer_index = random.randint(0, self.num_consumers - 1)

    def process_event(self):
        if not self.queue.empty() and random.expovariate(1 / (5 * 2)) < time.time():
            start_time = time.time()
            self.process_event()

def run_system(system):
    try:
        while True:
            for producer in system.producers:
                producer.generate_event()

            for _ in range(system.num_consumers):
                consumer = system.consumers[_]
                if not consumer.process_event():
                    break

            time.sleep(0.1)
    except KeyboardInterrupt:
        print("\nShutting down...")
        plt.close()

def main():
    system = EventProcessingSystem(num_producers=2, num_consumers=3)

    try:
        run_system(system)

        avg_latency = sum(system.latencies) / len(system.latencies) if system.latencies else 0
        max_latency = max(system.latencies) if system.latencies else 0
        min_latency = min(system.latencies) if system.latencies else 0
        std_dev = random.sample(system.latencies, k=len(system.latencies)).std() if system.latencies else 0

        print(f"Average latency: {avg_latency:.4f}s")
        print(f"Maximum latency: {max_latency:.4f}s")
        print(f"Minimum latency: {min_latency:.4f}s")
        print(f"Standard Deviation: {std_dev:.4f}s")

        plt.figure(figsize=(10, 6))
        plt.plot(system.event_timestamps, marker='o', linestyle='-', color='blue')
        plt.plot(system.event_consumption_times, marker='o', linestyle='-', color='red')
        plt.title('Event Generation and Consumption Times Over Time')
        plt.xlabel('Timestamp (seconds)')
        plt.ylabel('Time (seconds)')
        plt.legend(['Generation', 'Consumption'])
        plt.grid(True)
        plt.show()

    except Exception as e:
        print(f"An error occurred: {e}")

