import time

class Task:
    def __init__(self, name):
        self.name = name
        self.start_time = 0
        self.end_time = 0

    def start(self):
        self.start_time = time.time()

    def end(self):
        self.end_time = time.time()

    @property
    def execution_time(self):
        return self.end_time - self.start_time

class Pipeline:
    def __init__(self, tasks=None):
        if tasks is None:
            tasks = []
        self.tasks = tasks

    def add_task(self, task):
        self.tasks.append(task)

    def execute(self):
        for task in self.tasks:
            print("Starting", task.name)
            task.start()

            # Assume that the task's work is done here. 
            # Replace this line with actual code performing the task.
            time.sleep(1)

            task.end()
            print(task.name, "finished in", task.execution_time, "seconds")

# Create a pipeline and add tasks to it
pipeline = Pipeline()
pipeline.add_task(Task("Extract Data"))
pipeline.add_task(Task("Transform Data"))
pipeline.add_task(Task("Load Data"))

# Execute the pipeline
pipeline.execute()

import datetime
import hashlib
import json

class Backup:
    def __init__(self, data):
        self.data = data
        self.timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")

    def generate_checksum(self):
        return hashlib.md5(str(self.data).encode()).hexdigest()

class DisasterRecoveryPlan:
    def __init__(self):
        self.backups = []

    def create_backup(self, data):
        backup = Backup(data)
        self.backups.append(backup)

    def roll_back(self):
        if not self.backups:
            print("No backups available.")
            return

        # Get the last backup
        latest_backup = self.backups[-1]

        # Generate a new checksum for the latest backup
        current_checksum = latest_backup.generate_checksum()

        # Check if the user's input matches the expected checksum
        while True:
            user_input = input(f"Enter the checksum of the last backup ({current_checksum}): ")
            if user_input == current_checksum:
                break
            else:
                print("Incorrect checksum. Please try again.")

        # Roll back to the previous state
        self.backups.pop()
        print("Rollback successful!")

    def restore(self):
        if not self.backups:
            print("No backups available.")
            return

        # Get the last backup
        latest_backup = self.backups[-1]

        # Generate a new checksum for the latest backup
        current_checksum = latest_backup.generate_checksum()

        # Check if the user's input matches the expected checksum
        while True:
            user_input = input(f"Enter the checksum of the last backup ({current_checksum}): ")
            if user_input == current_checksum:
                break
            else:
                print("Incorrect checksum. Please try again.")

        # Restore from the latest backup
        self.backups.pop()
        print("Restoration successful!")

    def display_backups(self):
        for i, backup in enumerate(self.backups):
            print(f"Backup {i+1}:")
            print(backup.data)
            print(f"Timestamp: {backup.timestamp}")
            print(f"Checksum: {backup.generate_checksum()}\n")

# Example usage
drp = DisasterRecoveryPlan()

while True:
    print("\nDisaster Recovery Plan Options:")
    print("1. Create backup")
    print("2. Roll back to previous state")
    print("3. Restore from latest backup")
    print("4. Display backups")
    print("5. Quit")

