import requests
import json
import logging

logging.basicConfig(level=logging.ERROR)

def handle_payment_gateway_errors(api_key, url):
    try:
        response = requests.get(
            url,
            headers={'Authorization': f'Bearer {api_key}'}
        )

        if response.status_code != 200:
            logging.error(f"Payment gateway request failed with status code: {response.status_code}")
            error_data = {"status_code": response.status_code, "url": url}
            try:
                error_data.update(json.loads(response.text))
            except json.JSONDecodeError:
                pass
            finally:
                logging.error(f"Error details: {json.dumps(error_data, indent=2)}")
        else:
            try:
                data = json.loads(response.text)
                if 'error' in data:
                    logging.error(f"Payment gateway error detected: {json.dumps(data, indent=2)}")
            except json.JSONDecodeError:
                pass

    except requests.exceptions.RequestException as e:
        logging.error(f"Unexpected error during payment gateway request: {str(e)}")

