import datetime
from functools import wraps
from flask import Flask, request, g

app = Flask(__name__)

def cache_expiration(t):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            # Get the current time plus the expiration time.
            exp_time = datetime.datetime.utcnow() + datetime.timedelta(seconds=t)

            # Check if the cache entry has expired.
            if g.cache.get(func.__name__, None) and g.cache[func.__name__]['expires'] < exp_time:
                return func(*args, **kwargs)

            # Return the cached result or a 304 Not Modified response.
            if 'cache_result' in kwargs:
                return kwargs['cache_result']

            cache_result = func(*args, **kwargs)
            g.cache[func.__name__] = {'result': cache_result, 'expires': exp_time}

            return cache_result

        return wrapper
    return decorator

@app.route('/example')
@cache_expiration(3600)  # expires in 1 hour
def example_function():
    # Simulate an expensive function call.
    result = some_expensive_function()
    return result

def some_expensive_function():
    import time
    time.sleep(3)  # simulate an expensive operation
    return 'Example result'

