    app.run(debug=True)

import subprocess

def safe_execute_command(command):
    """
    Execute a system command safely using subprocess.

    Args:
        command (str): The system command to execute.

    Returns:
        str: The output of the executed command.
    """
    try:
        # Use subprocess.run to run the command and capture its output
        result = subprocess.run(command, shell=True, check=True)

        # If the command was successful, return its output
        if result.returncode == 0:
            return result.stdout.decode("utf-8")
        else:
            # If the command failed, raise an exception
            raise Exception(f"Command '{command}' failed with return code {result.returncode}")
    except Exception as e:
        # Catch any exceptions that occur during execution and re-raise them
        raise e

# Example usage
if __name__ == "__main__":
    try:
        output = safe_execute_command("ls -l")
        print(output)
    except Exception as e:
        print(f"Error executing command: {e}")

import hashlib
import time

class Transaction:
    def __init__(self, sender, receiver, amount):
        self.sender = sender
        self.receiver = receiver
        self.amount = amount
        self.time = time.time()

class Block:
    def __init__(self, previous_hash, transactions):
        self.timestamp = time.time()
        self.transactions = transactions
        self.previous_hash = previous_hash
        self.nonce = 0
        self.hash = self.computeHash()

    def computeHash(self):
        block_string = str(self.timestamp) + str(self.transactions) + \
            str(self.previous_hash) + str(self.nonce)
        return hashlib.sha256(block_string.encode()).hexdigest()

    def proofOfWork(self, difficulty):
        while self.hash[:difficulty] != "0" * difficulty:
            self.nonce += 1
            self.hash = self.computeHash()
        print("Block mined! Hash: ", self.hash)

class Blockchain:
    def __init__(self):
        self.chain = [self.createGenesis()]
        self.difficulty = 2
        self.pending_transactions = []

    def createGenesis(self):
        return Block("0", ["Genesis"])

    def getLatestBlock(self):
        return self.chain[-1]

    def minePendingTransactions(self, miner_reward_address):
        block = Block(self.getLatestBlock().hash, self.pending_transactions)
        block.proofOfWork(self.difficulty)
        print("Block mined successfully!")
        self.chain.append(block)
        self.pending_transactions = [
            Transaction(None, miner_reward_address, 1)]

    def createTransaction(self, transaction):
        self.pending_transactions.append(transaction)

    def isChainValid(self):
        for i in range(1, len(self.chain)):
            currentBlock = self.chain[i]
            previousBlock = self.chain[i - 1]
            if currentBlock.hash != currentBlock.computeHash():
                return False
            if currentBlock.previous_hash != previousBlock.hash:
                return False
        return True

