import time
from threading import Lock

class RateLimiter:
    def __init__(self, limit=10):
        self.lock = Lock()
        self.limit = limit  # Number of requests allowed per second
        self.request_times = []

    def check_ratelimit(self):
        current_time = time.time()

        # Remove old request times outside our window (1 sec)
        while len(self.request_times) > 0 and (current_time - self.request_times[0]) >= 1:
            self.request_times.pop(0)

        if len(self.request_times) < self.limit:
            # Request is allowed, add to list and return True
            self.request_times.append(current_time)
            return True

        else:
            # Too many requests in the window, don't allow this request
            return False

    def limit_ai_inference(self):
        if self.check_ratelimit():
            with self.lock:  # Ensure thread safety while modifying shared state (the AI model)
                # Run inference here
                pass
        else:
            print("Rate limit exceeded")

