import requests

def validate_token(token_data):
    # List of required keys to be validated
    required_fields = ['access_token', 'refresh_token', 'client_id', 'client_secret']

    # Check if all required fields are present in token_data
    for field in required_fields:
        if field not in token_data:
            return f"Missing required field: {field}"

    # Validate that the values of these keys are strings
    for field in required_fields[:3]:  # Exclude refresh_token as optional (can be empty)
        if not isinstance(token_data[field], str):
            return f"{field} is not a string"

    client_id = token_data['client_id']
    client_secret = token_data['client_secret']

    headers = {
        'Authorization': f'Basic {base64.b64encode(f"{client_id}:{client_secret}".encode()).decode()}',
        'Client-ID': client_id,
        'Client-Secret': client_secret
    }

    # Example endpoint, adjust according to your OAuth provider
    access_token_url = 'https://your-access-token-server.com/api/token'

    data_to_send = {
        'grant_type': 'authorization_code',
        'redirect_uri': token_data.get('redirect_uri', ''),
        'code': token_data.get('code', '')
    }

    response = requests.post(
        access_token_url,
        headers=headers,
        data=data_to_send,
        json=True
    )

    if response.status_code == 401:
        error_message = f"Authorization failed with status code {response.status_code}"
        try:
            error_data = response.json()
            error_message += "\nError details:\n%s" % '\n'.join(error_data.get('error', []))
        except ValueError as e:
            # Handle JSON parsing errors if any
            pass
        return f"Token validation failed: {error_message}"

    return "Access token validation successful!"

if __name__ == "__main__":
    import sys

    if len(sys.argv) != 2:
        print("Usage: python validate_token.py <token_data_json>")
        sys.exit(1)

    try:
        with open(sys.argv[1]) as f:
            token_data = json.load(f)

        result = validate_token(token_data)
        print(result)
    except Exception as e:
        print(f"Error reading or processing token data: {str(e)}")

import time

class CacheEvictionPolicy:
    def __init__(self, max_size=100, expiration_time=3600):
        self.max_size = max_size
        self.expiration_time = expiration_time
        self.cache = {}

    def add(self, key, value):
        if len(self.cache) >= self.max_size:
            self.evict()
        self.cache[key] = (value, time.time())

    def get(self, key):
        try:
            return self.cache[key][0]
        except KeyError:
            return None

    def evict(self):
        to_evict = []
        for k in self.cache:
            if time.time() - self.cache[k][1] > self.expiration_time:
                to_evict.append(k)
        for k in to_evict:
            del self.cache[k]

