import requests
import json
import re

def fetch_api(endpoint, headers=None, params=None):
    try:
        response = requests.get(endpoint, headers=headers, params=params)
        return response.json()
    except requests.exceptions.RequestException as e:
        # Check for 5xx errors
        if response.status_code >= 500 and hasattr(response, 'text'):
            error_pattern = re.compile(r"Error.*?:(\w+).*?$")  # Regex to extract error messages from 5xx responses
            match = error_pattern.search(response.text)
            if match:
                return {"error": f"API Error: {match.group(1)}"}
        raise  # Re-raise the exception for other request-related errors

def handle_response(response_data):
    """Process API response data and handle any errors found in the response"""
    try:
        if 'errors' in response_data or 'error_message' in response_data:
            error_msg = response_data.get('errors', response_data.get('error_message'))
            return f"API Error: {error_msg}"
        return response_data
    except Exception as e:
        # Handle unexpected errors (e.g., malformed JSON, unexpected API responses)
        return {"error": f"Unexpected error occurred during API call: {str(e)}"}

# Test cases for the fetch_api function
def test_fetch_api_success():
    success_response = requests.get("http://localhost/api/sample")
    assert isinstance(success_response.json(), dict), "Response should be a dictionary"

def test_fetch_api_error_5xx():
    # Simulate a 500 error response
    requests.Response.status_code = 500
    response = fetch_api("http://localhost/api/bad endpoint")
    assert isinstance(response, dict), "Should return a JSON object with error details"

def test_fetch_api_error_malformed_json():
    # Return an invalid JSON structure to cause parsing errors
    invalid_json = "{invalid"
    try:
        responses = requests.get("http://localhost/api/malformed", json=invalid_json)
        data = responses.json()
    except ValueError as e:
        assert str(e) == "Malformed data could not be parsed into a Python object.", "Should handle malformed JSON"

