import base64
import requests

def check_https(url):
    """Ensure the URL is secure (HTTPS)."""
    if not url.startswith(('http://', 'https://')):
        return f"{url}s"
    return url

def https_decorator(func):
    def wrapper(request):
        # Check and enforce HTTPS protocol
        checked_url = check_https(request.url)
        response = requests.get(checked_url)  # Replace with appropriate HTTP function if needed

        # Encode headers
        headers = request.headers.copy()
        encoded_headers = base64.b64encode(list(headers.values()))

        # Encode body content
        body = request.body
        encoded_body = base64.b64encode(body)

        return func(request._request, b''.join(encoded_headers), b''.join(encoded_body))
    return wrapper

def data_encryption_decorator(func):
    """Decorator to encode headers and body in Base64."""
    def wrapper(request):
        # Encode headers
        encoded_headers = base64.b64encode(list(request.headers.values()))

        # Encode body content
        encoded_body = base64.b64encode(request.body)

        return func(request._request, b''.join(encoded_headers), b''.join(encoded_body))
    return wrapper

