def currency_converter(amount, from_currency, to_currency):
    rates = {
        'USD': 1.0,
        'EUR': 0.85,
        'GBP': 0.74,
        'JPY': 110.69,
        'CAD': 1.26
    }

    if from_currency not in rates or to_currency not in rates:
        return "Currency not supported."

