from flask import Flask, request, jsonify
from collections import defaultdict

app = Flask(__name__)

# Store IP addresses and their corresponding timestamps
ip_timestamps = defaultdict(list)

def is_rate_limited(ip_address):
    """Check if the IP address has exceeded the rate limit"""
    # Remove timestamps older than 1 hour
    ip_timestamps[ip_address] = [timestamp for timestamp in ip_timestamps[ip_address] 
                                 if time.time() - timestamp < 3600]

    # Check if the IP address has exceeded the rate limit
    if len(ip_timestamps[ip_address]) >= 10:
        return True

    # Add the current timestamp to the list of timestamps
    ip_timestamps[ip_address].append(time.time())
    return False

def block_ip(ip_address):
    """Block the IP address"""
    print(f"Blocking IP address: {ip_address}")
    # You can also use a database or a third-party service to store and retrieve blocked IPs

def rate_limiting():
    """Rate limiting middleware function"""
    def decorator(func):
        def wrapper(*args, **kwargs):
            ip_address = request.remote_addr
            if is_rate_limited(ip_address):
                block_ip(ip_address)
                return jsonify({"error": "Too many requests, please try again later"}), 429

            # Allow the request to proceed if not rate limited
            return func(*args, **kwargs)
        return wrapper
    return decorator

@app.route('/endpoint', methods=['GET'])
@rate_limiting()
def endpoint():
    """Example endpoint"""
    return jsonify({"message": "Hello World!"})

