import threading
import time

# Define a class for tasks
class Task:
    def __init__(self, name, interval):
        self.name = name
        self.interval = interval

    # Method to execute the task
    def run(self):
        while True:
            print(f"Running {self.name}...")
            time.sleep(self.interval)

# Define a class for the task manager
class TaskManager:
    def __init__(self):
        self.tasks = {}

    # Add new tasks to the task manager
    def add_task(self, name, interval):
        if name not in self.tasks:
            self.tasks[name] = Task(name, interval)
            threading.Thread(target=self.tasks[name].run).start()
        else:
            print(f"Task '{name}' already exists.")

    # Remove existing tasks from the task manager
    def remove_task(self, name):
        if name in self.tasks:
            del self.tasks[name]
        else:
            print(f"Task '{name}' does not exist.")

# Example usage
task_manager = TaskManager()

while True:
    print("1. Add new task")
    print("2. Remove existing task")
    print("3. Exit")

    choice = input("Choose an option: ")

    if choice == "1":
        name = input("Enter the task name: ")
        interval = int(input("Enter the task interval in seconds: "))
        task_manager.add_task(name, interval)
    elif choice == "2":
        name = input("Enter the task name to remove: ")
        task_manager.remove_task(name)
    elif choice == "3":
        break
    else:
        print("Invalid option. Please choose again.")

import threading
import queue

class Task:
    def __init__(self, priority, task_func):
        self.priority = priority
        self.task_func = task_func

class TaskQueue(queue.PriorityQueue):
    def get(self):
        return super().get()[1]

def worker(task_queue):
    while True:
        task = task_queue.get()
        task.task_func()
        task_queue.task_done()

if __name__ == "__main__":
    task_queue = TaskQueue()

    # Create worker threads
    for _ in range(3):
        threading.Thread(target=worker, args=(task_queue,), daemon=True).start()

    # Add tasks to the queue
    task_queue.put(Task(1, lambda: print("Low priority task")))
    task_queue.put(Task(5, lambda: print("High priority task")))
    task_queue.put(Task(3, lambda: print("Medium priority task")))

    # Wait for all tasks to be completed
    task_queue.join()

    print("All tasks completed.")

import socket
import time
import random

class ConnectionHealthChecker:
    def __init__(self, host, port):
        self.host = host
        self.port = port
        self.time_to_live = 1  # in seconds
        self.max_retries = 3

    def ping(self):
        try:
            socket.create_connection((self.host, self.port), timeout=self.time_to_live)
            return True
        except (socket.error, socket.timeout):
            return False

    def check_connection_health(self):
        for _ in range(self.max_retries + 1):
            if self.ping():
                return "Connection is healthy"
            time.sleep(random.uniform(0.5, 2))  # wait for a random amount of time before retrying
        return "Connection is unhealthy"

