from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity):
        self.cache = OrderedDict()
        self.capacity = capacity

    # Return the value of the key that is queried in O(1) and return -1 if we don't find the key in out dict / cache
    def get(self, key):
        if key not in self.cache:
            return -1
        else:
            self.cache.move_to_end(key)
            return self.cache[key]

    # First, we add / update the key by conventional methods. And also move the key to the end to show that it was recently used. But here we will also check whether the length of our ordered dictionary has exceeded our capacity, If so we remove the least recently used key (which is available at 0th index).
    def put(self, key, value):
        self.cache[key] = value
        self.cache.move_to_end(key)

        if len(self.cache) > self.capacity:
            self.cache.popitem(last=False)

import time

def retry(operation, max_attempts=5):
    attempts = 0
    while True:
        try:
            return operation()
        except Exception as e:
            if attempts >= max_attempts:
                raise
            print("Operation failed. Retrying...")
            time.sleep(2 ** attempts)
            attempts += 1

