import ast
from collections import defaultdict

class DependencyRemover(ast.NodeVisitor):
    def __init__(self):
        self.loaded_modules = set() # Modules loaded with `import`
        self.used_modules = set() # Modules directly used in the code

    def visit_Import(self, node):
        for alias in node.names:
            self.loaded_modules.add(alias.name)

    def visit_ImportFrom(self, node):
        if node.module is not None: # If it's `from X import Y` 
            self.used_modules.add(node.module)

    def visit_Call(self, node):
        try:
            self.used_modules.add(node.func.value.id)
        except AttributeError:
            pass # Not a function call

def remove_unused_dependencies(code, dependencies):
    tree = ast.parse(code)
    remover = DependencyRemover()
    remover.visit(tree)

    for dependency in set(dependencies): # To avoid duplicates
        if dependency not in remover.used_modules:
            dependencies.remove(dependency)

    return dependencies

def safe_access(array, index):
    if 0 <= index < len(array):
        return array[index]
    else:
        print("Error: Index is out of bounds")
        return None

# usage
