import time
from multiprocessing import Process, Queue, cpu_count

def worker(queue):
    while True:
        item = queue.get()
        if item is None:
            break
        # process the item here
        print(f'Processed {item}')
        time.sleep(1)  # simulate processing delay

def main():
    task_queue = Queue()

    for i in range(50):
        task_queue.put(i)

    processors = cpu_count()
    processes = []

    for _ in range(processors):
        p = Process(target=worker, args=(task_queue,))
        processes.append(p)
        p.start()

    # wait for all tasks to be processed
    task_queue.join()

    # stop worker processes
    for _ in range(processors):
        task_queue.put(None)

    for p in processes:
        p.join()

if __name__ == '__main__':
    main()

import hashlib
from collections import OrderedDict

class Transaction(object):
    def __init__(self, sender, recipient, amount):
        self.sender = sender
        self.recipient = recipient
        self.amount = amount

class Block(object):
    def __init__(self, transactions, previous_block_hash=""):
        self.transactions = transactions
        self.previous_block_hash = previous_block_hash
        string_to_hash = "".join(transaction.__str__() for transaction in transactions) + previous_block_hash
        self.block_data = string_to_hash
        self.block_hash = hashlib.sha256(string_to_hash.encode()).hexdigest()

class Blockchain(object):
    def __init__(self):
        self.blocks = []
        self.pending_transactions = []

    def new_transaction(self, sender, recipient, amount):
        transaction = Transaction(sender, recipient, amount)
        self.pending_transactions.append(transaction)

    def new_block(self):
        if len(self.blocks) == 0:
            previous_hash="Genesis Block"
        else:
            previous_hash = self.blocks[-1].block_hash

        block = Block(self.pending_transactions, previous_hash)

        # reset the list of pending transactions
        self.pending_transactions = []
        self.blocks.append(block)

    def validate_transaction(self):
        for i in range(len(self.blocks)):
            current_block = self.blocks[i]

            # compare block data with the hashed value of block data
            if hashlib.sha256(current_block.block_data.encode()).hexdigest() != current_block.block_hash:
                return False

            # check if previous block's hash is correct
            if i > 0 and self.blocks[i-1].block_hash != current_block.previous_block_hash:
                return False
        return True

