def restrict_input(input_str):
    # Define allowed characters (letters, numbers, and common symbols)
    allowed_chars = set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()")

    # Check if input is a string; convert non-strings to string first
    try:
        s = str(input_str)
    except:
        return f"Invalid input type: {type(input_str)}"

    max_length = 50  # You can adjust this limit as needed

    for char in s:
        if char not in allowed_chars:
            raise ValueError(f"Invalid character '{char}' in input")

    if len(s) > max_length:
        raise ValueError(f"Input length exceeds maximum allowed length of {max_length}")

    return f"The input is valid: {s}"

import os
import subprocess

class GitVersionControl():
    def __init__(self):
        self.git = "/usr/bin/git" # update this to your git path if it's not in the default location

    def init(self, directory=None):
        if directory is None:
            directory = os.getcwd()
        command = [self.git, 'init', directory]
        return self._execute_shell_command(' '.join(command))

    def add(self, file):
        command = [self.git, 'add', file]
        return self._execute_shell_command(' '.join(command))

    def commit(self, message='Auto-commit'):
        command = [self.git, 'commit', '-m', '"{}"'.format(message)]
        return self._execute_shell_command(' '.join(command))

    def checkout(self, branch):
        command = [self.git, 'checkout', branch]
        return self._execute_shell_command(' '.join(command))

    def create_branch(self, branch):
        command = [self.git, 'branch', branch]
        return self._execute_shell_command(' '.join(command))

    def _execute_shell_command(self, command):
        try:
            process = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=None, shell=True)
            output = process.communicate()[0]
            if process.returncode != 0:
                print("Command execution failed: {}".format(command))
                return None
            else:
                return output
        except Exception as e:
            print("Caught exception: " + str(e))
            return None

class ShoppingCart(object):
    def __init__(self):
        self.items = []

    def add_item(self, item):
        # Check if the input is in appropriate format
        if not isinstance(item, dict) or 'name' not in item or 'price' not in item:
            print("Invalid item")
            return False

        self.items.append(item)
        return True

    def remove_item(self, name):
        for i, item in enumerate(self.items):
            if item['name'] == name:
                del self.items[i]
                return True

        print("Item not found")
        return False

    def total_cost(self):
        total = 0
        for item in self.items:
            total += item['price']

        return total

    def list_items(self):
        return [item['name'] for item in self.items]

