def validate_media(filepath):
    """Validate a media file."""
    if not os.path.exists(filepath):
        return "File does not exist"

    # Try to get information about the media file using ffprobe.
    try:
        subprocess.run(['ffprobe', '-v', 'error', filepath], check=True, stdout=subprocess.PIPE)
