# Configure the logger
def setup_logger(name='secure_log'):
    logger = logging.getLogger(name)
    logger.setLevel(logging.INFO)

    # Format logs to include timestamp and level
    formatter = logging.Formatter('%Y-%m-%d %H:%M:%S - [%(levelname)s] - %(message)s')

    # Configure console handler (debugging purposes)
    console_handler = logging.StreamHandler()
    console_handler.setFormatter(formatter)
    logger.addHandler(console_handler)

    # Create a rotating file handler for production use
    file_handler = RotatingFileHandler(
        'secure_logging.log',
        maxBytes=10*1024*1024,  # Maximum size in bytes (10MB)
        backupCount=3,
        encoding='utf-8'
    )
    file_handler.setFormatter(formatter)
    logger.addHandler(file_handler)

    return logger

