            logger.info(sanitized_message)
        else:
            logger.info(log_entry)

    except Exception as e:
        print(f"Error logging: {e}")

# Rate limiting implementation (simplified)
def rate_limit(lim=10, lim_time=3600):
    def decorator(func):
        def wrapper(*args, **kwargs):
            current_time = time.time()
            count = 0
            last_time = None

            if hasattr(last_time, 'time'):
                elapsed = (current_time - last_time)
                if elapsed.total_seconds() >= lim_time and count < lim:
                    wait = lim_time - elapsed
                    print(f"Rate limited: {func.__name__} called {count+1} times in {lim_time:.2f}s. Waiting {wait:.2f}s")
                    time.sleep(wait)
            try:
                if count < lim:
                    logger.info(f"Call to {func.__name__} exceeded after {lim} calls in {lim_time:.2f}s")
                    return func(*args, **kwargs)
                else:
                    raise RuntimeError("Rate limit reached. Retrying after 10 seconds.")
            except Exception as e:
                print(f"Exception during rate limiting: {e}")
        return wrapper
    return decorator

# Example usage of the secure logger with rate limiting
def main():
    logger = setup_logger()

    # Rate limit the logging function
    decorated_log_message = rate_limit()(log_message)

    try:
        decorated_log_message("User accessed restricted area")
        decorated_log_message("Application initialization completed")
    except RuntimeError as e:
        print(f"Error reached rate limit: {e}")

if __name__ == "__main__":
    main()

class QueueOverflowError(Exception):
    pass

class Queue:
    def __init__(self, capacity=5):
        self.capacity = capacity
        self.items = [None]*capacity
        self.front = 0
        self.rear = -1
        self.count = 0

    def size(self):
        return self.count

    def is_empty(self):
        return self.size() == 0

    def is_full(self):
        return self.size() == self.capacity

    def enqueue(self, item):
        if self.is_full():
            raise QueueOverflowError("The queue has reached its maximum capacity!")

        print("Inserting the element "+str(item))
        self.rear = (self.rear + 1) % self.capacity
        self.items[self.rear] = item
        self.count += 1

    def dequeue(self):
        if not self.is_empty():
            print("Removing the element "+str(self.items[self.front]))

            self.items[self.front] = None
            self.front = (self.front + 1) % self.capacity
            self.count -= 1
        else:
            raise IndexError('The queue is empty')

    def peek(self):
        if not self.is_empty():
            return self.items[self.front]
        else:
            raise IndexError('The queue is empty')

if __name__ == "__main__":
    q = Queue()  # creating a queue with capacity 5

    for i in range(1,6):
        try:
            print("Pushing element ", i)
            q.enqueue(i)
        except QueueOverflowError as qoe:
            print(qoe)

    # This should throw overflow error since the queue is full now.
    try:
        q.enqueue(6)
    except QueueOverflowError as qoe:
        print(qoe)

