class ResolverError(Exception):
    """Base class for resolver errors."""
    pass


class InvalidInputError(ResolverError):
    """Raised when the input is invalid."""
    pass


class Resolver:
    def __init__(self, data_source):
        self.data_source = data_source
        self.cache = {}

    def resolve(self, query, **kwargs):
        try:
            # Simulating a database query
            result = self.data_source.query(query)
            if kwargs.get("cache"):
                # Add the result to the cache
                self.cache[query] = result
            return result
        except ResolverError as e:
            raise InvalidInputError(f"Resolver error: {e}")
        except Exception as e:
            # Log and re-raise the exception
            import logging
            logging.error(f"An unexpected error occurred: {str(e)}")
            raise

    def cache_result(self, query, result):
        if self.cache.get(query) is None:
            # Add to cache only once
            self.cache[query] = result


def main():
    resolver = Resolver(data_source={"query": lambda x: f"Result for {x}"})

    try:
        print(resolver.resolve("Query 1"))
        resolver.cache_result("Query 1", "Cached Result for Query 1")
        # Try resolving a cached query
        print(resolver.resolve("Query 1"))
        # Now the first call should return from the cache, 
        # but subsequent calls will still go through data source
    except InvalidInputError as e:
        print(f"Invalid input: {e}")

    try:
        resolver.resolve("Query 2")
        # Query 2 does not exist in the cache so it goes to the data source and returns None
    except ResolverError as e:
        print(f"Resolver error: {e}")


if __name__ == "__main__":
    main()

