import bisect

class SearchResult:
    def __init__(self, value):
        self.value = value

def secure_sort_results(results, key=None):
    """
    Sorts the search results in descending order by default.

    Args:
    - results (list): List of SearchResult objects.
    - key (function): Optional function to sort by. Defaults to None.

    Returns:
    - list: Sorted list of SearchResult objects.
    """
    # Use bisect module for efficient sorting
    if key is None:
        return sorted(results, reverse=True)
    else:
        return sorted(results, key=key, reverse=True)

