import getpass
from cryptography.hazmat.primitives.asymmetric import prf

def get_encrypted_password(prompt):
    """Get password securely with encryption."""
    return getpass.getpass(prompt=prompt, encrypt=True)

def get_encrypted_token(salt_bytes, password, token):
    """Generate a hash using the given salt and compare it to the provided token."""
    algorithm = prf.PRF1(prf.NONCE_96, b'hmac-sha256')
    algorithm.update(salt_bytes)

    try:
        key = algorithm BoxedToken(salt=salt_bytes, password=password)
        token_bytes = key.value
        return token_bytes + bytes(token.encode())
    except Exception as e:
        raise ValueError(f"Invalid token: {e}")

def validate_token(salt_bytes):
    """Validate a session token."""
    try:
        hashed_token = get_encrypted_token(salt_bytes, None, None)
        raw_token, plain_token = hashed_token[:16], hashed_token[16:]
        return bytes(plain_token.encode()) == (input().strip())
    except Exception as e:
        print(f"Invalid session token. Error: {e}")

# Example usage
