import socket
import struct

class NetworkPacketParser:
    def __init__(self, port):
        self.port = port
        self.socket = None

    def create_socket(self):
        """Create a new socket object"""
        self.socket = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)

    def bind_socket(self):
        """Bind the socket to a specific address and port"""
        self.socket.bind(("localhost", self.port))

    def parse_packet(self, data):
        """Parse incoming network packet data"""
        # Assuming 16-byte packet structure
        if len(data) < 16:
            raise ValueError("Packet data too small")

        # Unpack packet header (4 bytes)
        src_ip, dst_ip = struct.unpack("!L", data[:4])

        # Unpack packet payload (12 bytes)
        payload = struct.unpack("!L" * 5, data[4:20])

        return {
            "src_ip": src_ip,
            "dst_ip": dst_ip,
            "payload": payload
        }

    def receive_packet(self):
        """Receive and parse incoming network packets"""
        data, address = self.socket.recvfrom(1024)
        parsed_packet = self.parse_packet(data)

        print(f"Received packet from {address}:")
        for src_ip, dst_ip, payload in parsed_packet.values():
            print(f"- Source IP: {src_ip}")
            print(f"- Destination IP: {dst_ip}")
            print(f"- Payload: {payload}")


def main():
    parser = NetworkPacketParser(8080)  # Set port to 8080
    parser.create_socket()
    parser.bind_socket()

    while True:
        parser.receive_packet()


if __name__ == "__main__":
    main()

import time
from datetime import timedelta, datetime

class AccountLockout:
    def __init__(self):
        self.lockout_time = {}
        self.max_lockout_time = timedelta(hours=1)  # maximum lockout time is 1 hour

    def check_lockout(self, account_id):
        if account_id in self.lockout_time:
            if datetime.now() < self.lockout_time[account_id]:
                return True
            else:
                del self.lockout_time[account_id]
                return False
        else:
            return False

    def lock_out(self, account_id):
        self.lockout_time[account_id] = datetime.now()
        print(f"Account {account_id} is now locked out for {self.max_lockout_time}")

# Example usage:

lockout_system = AccountLockout()

def login Attempt(account_id):
    # simulate a failed login attempt
    time.sleep(2)  # wait for 2 seconds

    if lockout_system.check_lockout(account_id):
        print(f"Account {account_id} is already locked out. Please try again in {self.max_lockout_time}")
    else:
        print(f"Login successful for account {account_id}")

# Test the code
login_Attempt("user1")
time.sleep(2)  # wait for 2 seconds

lockout_system.lock_out("user1")

login_Attempt("user1")  # This will trigger a lockout

