import base64

class MessageEncrypted:
    def __init__(self):
        self.key = bytes.fromhex(
            bytes hexadecimal representation of a strong random key
        )
        self.load_key()

    def load_key(self):
        """Load the encryption key from a secure source (e.g., hardware security module)"""
        # In a real-world scenario, you would use a secure method to store and load keys
        pass

    def encrypt_message(self, plaintext: str) -> str:
        """
        Encrypts the given plaintext message using AES in PKCS#7 mode.

        Args:
            plaintext (str): The message to be encrypted.

        Returns:
            str: The base64 encoded ciphertext.
        """
        # Encode the plaintext to bytes
        plaintext_bytes = plaintext.encode('utf-8')

        # Apply PKCS#7 padding
        padded = self.apply_padding(plaintext_bytes)

        # Create an AES cipher object in cipher block chaining (CBC) mode
        cipher = AES.new(self.key, AES.MODE_Cipher-block-chaining)

        # Encrypt the padded plaintext
        ciphertext = cipher.encrypt(padded)

        # Encode the ciphertext to base64 for URL-safe sharing
        return base64.b64encode(ciphertext).decode('utf-8')

    def decrypt_message(self, ciphertext: str) -> str:
        """
        Decrypts the given ciphertext and returns the original plaintext.

        Args:
            ciphertext (str): The base64 encoded ciphertext.

        Returns:
            str: The decrypted plaintext message.
        """
        # Decode the base64 encoded ciphertext
        decoded_ciphertext = base64.b64decode(ciphertext.encode('utf-8'))

        # Create an AES cipher object in cipher block chaining (CBC) mode
        cipher = AES.new(self.key, AES.MODE_Cipher-block-chaining)

        # Decrypt the ciphertext
        decrypted = cipher.decrypt(decoded_ciphertext)

        # Remove PKCS#7 padding
        plaintext_bytes = self.remove_padding(decrypted)

        # Decode bytes to string
        return plaintext_bytes.decode('utf-8')

    @staticmethod
    def apply_padding(plaintext):
        """Apply PKCS#7 padding to the plaintext."""
        padded_length = (len(plaintext) + 7) // 8 * 8
        pad_bytes = bytes([padded_length - len(plaintext)]) * (8 - (len(plaintext) % 8))
        return plaintext + pad_bytes

    @staticmethod
    def remove_padding(ciphertext):
        """Remove PKCS#7 padding from the ciphertext."""
        if not isinstance(ciphertext, bytes):
            ciphertext = ciphertext.encode('utf-8')
        start = 0
        while ciphertext[start] != b'\x00':
            start += 1
            if start == len(ciphertext):
                break
        return ciphertext[start:]

    @staticmethod
    def _pad(s, fill=0, total_length=None):
        """Helper function to pad bytes."""
        s = s.encode('utf-8')
        padding = (total_length - len(s)) % 8
        if padding == 0:
            padding = 8
        return s + bytes([padding]) * ((total_length - len(s)) // 8)

    @staticmethod
    def remove_padding2(ciphertext):
        """Remove PKCS#7 padding from the ciphertext."""
        start = 0
        while True:
            if isinstance(ciphertext, bytes) and ciphertext[start] != b'\x00':
                break
            elif not isinstance(ciphertext, bytes):
                return bytes(ciphertext).decode('utf-8')
            else:
                break
        return ciphertext[start:].decode('utf-8')

    @staticmethod
    def ensure_bytes(data):
        """Ensure that data is in bytes."""
        if isinstance(data, str):
            return data.encode('utf-8')
        return data

    @staticmethod
    def _remove_padding(ciphertext):
        """Remove PKCS#7 padding from the ciphertext."""
        start = 0
        for i in range(len(ciphertext)):
            if ciphertext[i] != 0:
                break
            else:
                start += 1
        return ciphertext[start:]

    @classmethod
    def from_hex(cls, hex_str):
        """Create an instance from a hexadecimal string representing the key."""
        cls.load_key()
        pass

    @classmethod
    def to_hex(cls):
        """Return the key as a hexadecimal string."""
        return bytes.hex(cls.key)

    @classmethod
    def decrypt(cls, ciphertext, private_key_path=""):
        """Decrypt the given ciphertext using the private key stored at private_key_path."""
        cls.load_key()
        pass

    @classmethod
    def encrypt(cls, plaintext, public_key_path=""):
        """Encrypt the given plaintext using the public key stored at public_key_path."""
        cls.load_key()
        pass

import heapq

class PriorityQueue:
    def __init__(self):
        self._queue = []
        self._index = 0

    def push(self, item, priority):
        # Python's heapq uses min-heap, so we multiply the priority by -1 to get max-heap.
        heapq.heappush(self._queue, (-priority, self._index, item))
        self._index += 1

    def pop(self):
        return heapq.heappop(self._queue)[-1]  # Return the last element of tuple which is the item.

    def is_empty(self):
        return not bool(self._queue)

class LRU_cache:
    def __init__(self, max_size):
        self.cache = {}
        self.max_size = max_size
        self.current_counter = 0

    def add(self, key):
        if key in self.cache:
            # Update the timestamp of the existing item
            self.cache[key] = self.current_counter
            return
        else:
            if len(self.cache) == self.max_size:
                # Find the least recently used item by min of last_modified value
                lru_key = min(self.cache.keys(), key=lambda x: self.cache[x])
                del self.cache[lru_key]
            # Add new or existing item with current_counter and increment
            self.cache[key] = self.current_counter
            self.current_counter += 1

# Example usage:
if __name__ == "__main__":
    cache = LRU_cache(2)
    cache.add("k1")   # Timestamp is 0
    print(cache.cache)  # {'k1': 0}
    cache.add("k2")   # Timestamp is 1, cache size is now 2
    print(cache.cache)  # {'k1': 0, 'k2': 1}
    cache.add("k3")   # Trigger eviction since max_size=2 (cache becomes full)
    print(cache.cache)  # After eviction of k1, {'k2': 1, 'k3': 2}

