import os

def compress_images(directory=None, out_dir='compressed_img/'):
    if directory == None:
        directory = os.getcwd()  # current working directory

    if not os.path.exists(out_dir):
        os.makedirs(out_dir)

    for filename in os.listdir(directory):
        if filename.endswith(".jpg") or filename.endswith(".png"):  # modify according to your need
            image = Image.open(directory + '/' + filename)

            name, extension = os.path.splitext(filename)
            image.save(out_dir + name + extension, optimize=True, quality=65)  # quality can be adjusted to compress more or less

