def can_login(role, required_permission):
    if role == "admin":
        return any(required_permission.values())
    elif role == "user":
        return all(required_permission.values())
    else:
        return False  # For other roles like guest, assume access is denied.

def validate_user_privileges(user_role, user_level, user_exp):
    required_privileges = {
        "admin": {"level": 5, "experience": 100},
        "moderator": {"experience": 50}
    }

    # Check the basic level requirement for all users
    if user_level < 1:
        return False

    role_reqs = required_privileges.get(user_role, {})
    user_attrs = {
        "level": user_level,
        "experience": user_exp
    }

    for attr in role_reqs:
        min_val = role_reqs[attr]
        if user_attrs.get(attr) < min_val:
            return False

    return True

