from ftplib import FTP

def send_file(ftp, file):
    ext = file.split('.')[-1]

    if ext in ("txt", "py", "java"):
        ftp.storlines("STOR " + file, open(file))

    else:
        ftp.storbinary("STOR " + file, open(file, 'rb'), 1024)

ftp = FTP('ftp.example.com')   # connect to host, default port
ftp.login(user='username', passwd='password')     # user credentials

files = ["example.txt", "hello.py"]    # files you want to transmit
for file in files:
    send_file(ftp, file)

def validate_transaction(transaction):
    # Extract inputs and outputs
    txins = transaction.get('txins', [])
    txouts = transaction.get('txouts', [])

    # Validate each input (TxIn)
    for idx, txin in enumerate(txins):
        if 'denomination' not in txin or txin['denomination'] <= 0:
            raise ValueError(f"Invalid denomination {txin['denomination']} at index {idx}")

    # Create a map from txin index to data
    txin_map = {txin['index']: txin['data'] for txin in txins}

    # Validate each output (TxOut)
    for out_idx, out in enumerate(txouts):
        script_pubkey = out.get('script_pubkey', None)

        if not script_pubkey:
            raise ValueError(f"Missing script_pubkey at index {out_idx}")

        data = out.get('data', '')
        if isinstance(data, bytes) and len(data):
            hash_address = out.get('data', '').hex()
            txin_index = txin_map.get(hash_address)
            if not txin_index:
                raise ValueError(f"Unrecognized address hash: {hash_address}")

            # Check if the txin index is used elsewhere
            other_outs_with_txin = next((i for i, o in enumerate(txouts) if txin_map[o['script_pubkey']] == txin_index), None)
            if other_outs_with_txin is not None:
                raise ValueError(f"Txin {txin_index} referenced multiple times")

        else:
            # Check if the script matches a known txin
            match = False
            for txin_idx, txin_data in txin_map.items():
                if txin_data == data:
                    match = True
                    break
            if not match:
                raise ValueError(f"Unknown script PubKey at index {out_idx}: {data}")

    # Ensure all inputs are used exactly once as outputs
    used_txins = set()
    for out in txouts:
        if 'script_pubkey' in out and (out['script_pubkey'] is None or 
                                        out['script_pubkey'].strip() != ''):
            if out['script_pubkey'] not in txin_map:
                raise ValueError(f"Unknow script PubKey {out['script_pubkey']} at index {txouts.index(out)}")

    # Check for duplicate txin references
    txins_used = set()
    for txin in txins:
        idx = txin.get('index', None)
        if idx is not None and idx in txins_used:
            raise ValueError(f"Txin with index {idx} used more than once")
        txins_used.add(idx)

    return True

# Example usage
