# Importing necessary libraries
from hashlib import sha256
import hmac
import secrets
import json

class SecureRefunds:
    def __init__(self, secret_key):
        self.secret_key = bytes(secret_key, 'utf-8')  # Secret key for HMAC

    def generate_signature(self, payload):
        # Create a signature using HMAC and SHA256
        return hmac.new(self.secret_key, msg=payload, digestmod=sha256).hexdigest()

    def verify_signature(self, received_signature, payload):
        # Verify the signature
        expected_signature = self.generate_signature(payload)
        return hmac.compare_digest(received_signature, expected_signature)

    def process_refund(self, payload, signature):
        # Convert the payload to bytes
        payload = json.dumps(payload).encode('utf-8')

        # Verify the signature before processing the refund
        if self.verify_signature(signature, payload):
            # Process the refund here
            print("Refund processed successfully")
        else:
            print("Invalid refund request")

# Usage
secret_key = secrets.token_hex(16)  # A securely generated secret key
handler = SecureRefunds(secret_key)

payload = {
    "transaction_id": "abc123",
    "refund_amount": 50.00,
    "currency": "USD"
}
signature = handler.generate_signature(json.dumps(payload).encode('utf-8'))
handler.process_refund(payload, signature)

import requests

def respond_to_webhook(webhook_url, data):
    """
    Sends a response to the webhook trigger.

    Args:
        webhook_url (str): The URL of the webhook trigger.
        data (dict): The data to be sent as a response.

    Returns:
        None
    """

    # Set API endpoint and headers for requests
    api_endpoint = webhook_url
    headers = {
        "Content-Type": "application/json"
    }

    # Convert data into JSON format
    payload = {"event": "new_event", "data": data}
    payload_json = json.dumps(payload)

    try:
        # Send POST request to the API endpoint
        response = requests.post(api_endpoint, headers=headers, data=payload_json)

        if response.status_code == 200:
            print("Webhook trigger responded successfully")
        else:
            print(f"Failed to respond to webhook trigger. Status code: {response.status_code}")

    except Exception as e:
        print(f"An error occurred while responding to webhook trigger: {e}")


