def validate_input(model_input):
    # Checking if the input is a number
    try:
        float_input = float(model_input)
    except ValueError:
        print("Invalid input, please enter a numeric value.")
        return False

    # Checking if the number is within the acceptable range for our model
    if float_input < 0 or float_input > 100:
        print("Input out of bounds. Please enter a number between 0 and 100 (inclusive).")
        return False

    # If all checks pass, we'll return True to indicate valid input
    return True

