    unittest.main()

import subprocess

def check_command(cmd):
    try:
        # Here we use the 'check' argument set to True to throw an exception if the command fails.
        process = subprocess.run(cmd, shell=True, check=True)
    except subprocess.CalledProcessError as e:
        print("The command failed with error code:", e.returncode)
        return False
    else:
        print("The command was successful.")
        return True

