import base32
from Crypto.Cipher import AES
from Crypto.Random import getrandbytes

class SmartContract:
    def __init__(self, name, description, version=None):
        self.name = name
        self.description = description
        self.version = version or "1.0"
        self.url = f"https://{name}.io"

    def initialize_contract(self, user_inputs):
        try:
            # Sanitize inputs
            sanitized_input = self.sanitize(user_inputs)

            # Encrypt the contract text
            key = getrandbytes(32)  # Generate a random AES-256 key
            cipher = AES.new(key, AES.MODE_EAX)
            encrypted_text = cipher.encrypt(self.description.encode('utf-8'))

            # Check if user is whitelisted (e.g., allowed to create contracts)
            if self.is_whitelisted(user_inputs):
                self.contract_data = {
                    "name": self.name,
                    "description": decrypted_description,
                    "version": self.version,
                    "url": self.url
                }

                return True, self.contract_data
            else:
                raise ValueError("User not whitelisted. Access denied.")
        except Exception as e:
            raise RuntimeError(f"Error initializing contract: {str(e)}")

    @staticmethod
    def sanitize(input_str):
        # Remove special characters and whitespace
        allowed_chars = base32.bases32chars
        sanitized = ''
        for char in input_str.lower():
            if char in allowed_chars or char.isdigit() or (char == '-' and len(input_str) > 0 and ord(char) >= 32):
                sanitized += char
        return sanitized

    @staticmethod
    def is_whitelisted(user_input):
        # Example whitelist mechanism: only predefined users can create contracts
        whitelisted_users = ["admin", "user1", "user2"]
        for user in whitelisted_users:
            if user in user_input:
                return True
        return False

    @classmethod
    def main(cls):
        contract_name = input("Enter contract name: ")
        description = input("Enter contract description: ")

        try:
            contract = cls(contract_name, description)
            success, data = contract.initialize_contract(input("Enter contract initialization parameters: "))
            if success:
                print(f"Contract '{contract.name}' created successfully!")
                print(data)
        except Exception as e:
            print(f"An error occurred: {str(e)}")

if __name__ == "__main__":
    SmartContract.main()

