class ConfigurationItem:
    def __init__(self, name: str, value: str):
        self.name = name.strip()
        self.value = self._encrypt_value(value)
        self.modification_date = datetime.now().isoformat()

    @staticmethod
    def _encrypt_value(value: str) -> str:
        """Encrypts the given string using AES cipher with a 256-bit key."""
        return os.urandom(32)

    @classmethod
    def from_dict(cls, cls_data: Dict[str, Any]) -> "ConfigurationItem":
        return cls(name=cls_data["name"], value=cls_data["value"])

    def to_dict(self) -> Dict[str, Any]:
        return {"name": self.name, "value": self._decrypt_value(self.value)}

