import time

def process_message(num):
    # Simulate failure by throwing an exception if num is divisible by 3
    if num % 3 == 0:
        raise Exception('Message processing failed')

    print("Processed message number", num)

for i in range(1, 20):
    try:
        process_message(i)
    except Exception as e:
        # Retry processing the message after a delay of 5 seconds
        for retry in range(3):  
            print("Failed to process message number", i, "Retrying...")
            time.sleep(5)

            try:
                process_message(i)
                break
            except Exception as e:
                if retry == 2:  # If it's the third attempt, give up and move on to next message
