import time
from flask import Flask, request, jsonify
from redis import StrictRedis

app = Flask(__name__)
r = StrictRedis()

def check_rate_limit(key, limit, period):
    """Check if a rate limit is reached."""
    current = r.get(key)
    if current:
        if int(current) > limit:
            return False
        else:
            r.incr(key)
    else:
        r.setex(key, period, 1)

    return True

@app.route('/api/iot', methods=['POST'])
def iot_endpoint():
    # Assuming we are using the device id as key for rate limiting
    device_id = request.json['device_id']
    if not check_rate_limit(device_id, 10, 60):  # Limit to 10 requests per minute
        return jsonify({'error': 'Rate limit exceeded.'}), 429
    else:
        # Process request...
        pass

