import subprocess

def check_command(command):
    try:
        result = subprocess.run(
            command,
            shell=True,
            capture_output=True,
            text=True,
            encoding='utf-8'
        )
        # Check if both stdout and stderr are empty except for success message
        if not (result.stdout or result.stderr):
            print(f"Command executed successfully: {command}")
            return True
        else:
            print(f"Command execution failed with output:\n{result.stdout}\n\nError message:\n{result.stderr}")
            return False
    except Exception as e:
        print(f"An error occurred during command execution: {e}")
        return False

