import graphql
from graphql import GraphQLError
from typing import Dict, List, Union

class Resolver:
    def __init__(self):
        self.data = {
            "users": [
                {"id": 1, "name": "John Doe", "email": "john@example.com"},
                {"id": 2, "name": "Jane Doe", "email": "jane@example.com"}
            ]
        }

    def resolve_users(self):
        return self.data["users"]

    def resolve_user_by_id(self, parent, args):
        user_id = int(args['user_id'])
        if user_id not in [u['id'] for u in self.data['users']]:
            raise GraphQLError(f"User with id {args['user_id']} not found")
        return next((u for u in self.data['users'] if u['id'] == user_id), None)

    def resolve_posts(self):
        return [
            {"title": "Post 1", "content": "This is the content of post 1"},
            {"title": "Post 2", "content": "This is the content of post 2"}
        ]

    def resolve_post_by_id(self, parent, args):
        post_id = int(args['post_id'])
        if post_id not in [p['id'] for p in self.data['posts']]:
            raise GraphQLError(f"Post with id {args['post_id']} not found")
        return next((p for p in self.data['posts'] if p['id'] == post_id), None)

# Define the schema
schema = graphql.Schema(query='query', mutation='mutation')

# Create an instance of Resolver
resolver = Resolver()

# Query resolvers
@schema.query('query')
def resolve_users():
    return resolver.resolve_users()

@schema.query('query', arguments={'user_id': int})
def resolve_user_by_id(user_id: int):
    return resolver.resolve_user_by_id(None, {'user_id': user_id})

# Mutation resolvers
@schema.mutation('mutation', arguments={'title': str, 'content': str})
def create_post(title: str, content: str):
    new_post = {
        "id": len(resolver.data['posts']) + 1,
        "title": title,
        "content": content
    }
    resolver.data["posts"].append(new_post)
    return {'post_id': new_post['id']}

@schema.mutation('mutation', arguments={'post_id': int})
def delete_post(post_id: int):
    if post_id not in [p['id'] for p in resolver.data['posts']]:
        raise GraphQLError(f"Post with id {post_id} not found")
    resolver.data["posts"] = [p for p in resolver.data['posts'] if p['id'] != post_id]
    return {'message': 'Post deleted successfully'}

# Test the schema
if __name__ == '__main__':
    query1 = """
        query {
            users {
                id name email
            }
        }
    """

    response1 = schema.execute(query1)
    print(f"Query 1 result: {response1.data}")

    query2 = """
        query($user_id: Int!) {
            user(id: $user_id) {
                id name email
            }
        }
    """

    response2 = schema.execute(query2, variables={'user_id': 1})
    print(f"Query 2 result: {response2.data}")

    mutation1 = """
        mutation($title: String!, $content: String!) {
            createPost(title: $title, content: $content) {
