def secure_logout():
    """Logs out the user securely and sets a random session expiration."""
    if 'user_id' in session:
        session['logout'] = secrets.token_urlsafe(16)  # Generate a unique token for logging out
        session['expires_at'] = int(time.time()) + (30 * 60)  # Session expires after 30 minutes
    return redirect(url_for('index'))

# Define the logout route
@app.route('/logout')
def logout():
    """Logs out the user and redirects to the index page."""
    if 'logout' in session and 'expires_at' in session:
        del session['logout']
        del session['expires_at']
        return secure_logout()
    else:
        return redirect(url_for('index'))

