import threading
import time

def main():
    print("Starting program...")

    # Enumerate all active threads
    threads = list(threading.enumerate())

    start_times = {}
    end_times = {}

    for thread in threads:
        if hasattr(thread, 'name'):
            name = thread.name
        else:
            name = f"anonymous_thread_{thread.ident}"
        print(f"Starting {name}: ID={thread.ident}")

        try:
            # Record the start time
            start_time = time.time()
            start_times[thread.ident] = start_time
            thread.start()
        except Exception as e:
            print(f"Error in starting thread: {e}")
            input("Press Enter to continue...")

    print("\nWaiting for all threads to finish...")

    # Wait until all threads are done
    while True:
        done = True
        for thread in threads:
            if not thread.is_alive():
                done = False
                break
        if done:
            break

    end_time = time.time()

    print("\nThread results:")
    for ident in start_times.keys():
        duration = end_time - start_times[ident]
        print(f"Thread {ident}: finished at {end_time}, took {duration} seconds")

if __name__ == "__main__":
    main()

import os
import hashlib
from datetime import datetime, timedelta
from typing import Optional, Dict, Any
import requests
import json

# Initialize secrets and configuration variables

# Configuration variables (to be set by environment or configuration file)
CLIENT_ID = "your_client_id"
CLIENT_SECRET = "your_client_secret"
ACCESS_TOKEN_EXPIRE_MINUTES = 30

# Token generation parameters
HMAC_KEY = os.urandom(32)  # A random key for HMAC
STORAGE_URL = "database.db"  # Replace with your database storage

class OAuth2Client:
    def __init__(self, client_id: str, secret: str):
        self.client_id = client_id
        self.secret = bytes.fromhex(secret)
        self._session = requests.Session()

    async def authenticate_client(self, username: Optional[str] = None, password: Optional[str] = None):
        # Simulate token generation and storage
        # In production, use database or secure storage instead
        token_data = {
            "token_type": "bearer",
            "access_token": f"Bearer {self._generate_access_token()}",
            "expires_in": 3600,
            "refresh_token": self._generate_refresh_token(),
            "user_id": str(uuid.uuid4()),
            "exp": datetime.utcnow() + timedelta(minutes=ACCESS_TOKEN_EXPIRE_MINUTES)
        }
        storage = {"access_token": token_data["access_token"], "refresh_token": token_data["refresh_token"]}
        with open(STORAGE_URL, 'w') as f:
            json.dump(storage, f)

        # Example of MFA flow
        if password is not None:
            response = await self._make_request("POST", "auth/mfa", data={"username": username, "password": password})
            return response.json()
        else:
            response = await self._make_request("POST", "auth/login", data={"username": username, "password": password})
            return response.json()

    def _generate_access_token(self) -> str:
        current_time = int(datetime.utcnow().timestamp())
        h1 = hashlib.sha256(str(current_time).encode()).digest()
        token = bytes.fromhex(HMAC_KEY.hex() + h1)
        return bin(int(token.hex(), 16))[2:]

    def _generate_refresh_token(self) -> str:
        current_time = int(datetime.utcnow().timestamp())
        h1 = hashlib.sha256(str(current_time).encode()).digest()
        token = bytes.fromhex(HMAC_KEY.hex() + h1)
        return bin(int(token.hex(), 16))[2:]

    def _make_request(self, method: str, endpoint: str, data: Optional[Dict[str, Any]] = None) -> requests.Response:
        headers = {
            'Content-Type': 'application/x-www-form-urlencoded',
            'Authorization': f'Basic {base64.b64encode(f"{self.client_id}:{self.secret}".encode()).decode()}'
        }
        response = requests.request(method, endpoint, headers=headers, params=data)
        return response

class OAuth2Server:
    def __init__(self):
        self.tokens = {}

    async def store_token(self, token_type: str, access_token: str, refresh_token: str) -> None:
        self.tokens.update({
            access_token: {
                "token_type": token_type,
                "expires_in": 30,
                "refresh_token": refresh_token
            }
        })

    def refresh_tokens(self, old_access_token: str):
        if old_access_token in self.tokens:
            new_access_token = self._generate_access_token()
            self.tokens[new_access_token] = {
                "token_type": "access_token",
                "expires_in": 30,
                "refresh_token": self._generate_refresh_token()
            }
            del self.tokens[old_access_token]

    async def get_authorization_url(self) -> str:
        expires_in = 3600
        return f"https://localhost/oauth2/auth?client_id={self.client_id}&redirect_uri=https://localhost/callback&display_mode=original&scope=&expires_in={expires_in}"

async def main():
    client = OAuth2Client(CLIENT_ID, CLIENT_SECRET)
    print("Auth starting")
    try:
        response = await client.authenticate_client()
        print(response.json())
    except Exception as e:
        print(f"Authentication failed: {e}")
    finally:
        token_data = {
            "access_token": client.access_token,
            "refresh_token": client.refresh_token
        }
        storage = {"access_token": token_data["access_token"], "refresh_token": token_data["refresh_token"]}
        with open(STORAGE_URL, 'w') as f:
            json.dump(storage, f)

if __name__ == "__main__":
    import asyncio
    loop = asyncio.get_event_loop()
    loop.run_until_complete(main())

