import requests
from bs4 import BeautifulSoup

def get_dynamic_content(url):
    try:
        response = requests.get(url)
        soup = BeautifulSoup(response.content, 'html.parser')
        return soup
    except Exception as e:
        print(f"An error occurred: {e}")
        return None

def parse_dynamic_content(soup):
    # Find all dynamic content on the page (e.g. JavaScript-generated elements)
    dynamic_content_elements = soup.find_all('script')

    for element in dynamic_content_elements:
        try:
            js_code = element.get_text()
            # Use BeautifulSoup's execute_js method to execute the JavaScript code
            parsed_soup = soup.execjs(js_code)
            return parsed_soup
        except Exception as e:
            print(f"Failed to parse JavaScript code: {e}")

def main():
    url = 'http://example.com'
    soup = get_dynamic_content(url)

    if soup is not None:
        dynamic_content_elements = parse_dynamic_content(soup)
        # Print the dynamic content elements
        for element in dynamic_content_elements.find_all(True):
            print(element.get_text())

