from enum import Enum
from datetime import datetime

class ContentStatus(Enum):
    NEW = "New"
    PENDING_REVIEW = "Pending Review"
    APPROVED = "Approved"
    REJECTED = "Rejected"

class Content:
    def __init__(self, title, content):
        self.title = title
        self.content = content
        self.status = ContentStatus.NEW
        self.review_date = None

class User:
    def __init__(self, name):
        self.name = name

class ReviewWorkflow:
    def __init__(self, content, reviewers):
        self.content = content
        self.reviewers = reviewers
        self.current_reviewer_index = 0

    def next_reviewer(self):
        self.current_reviewer_index += 1
        if self.current_reviewer_index >= len(self.reviewers):
            return None
        return self.reviewers[self.current_reviewer_index]

class ContentApprovalSystem:
    def __init__(self):
        self.contents = []
        self.workflows = []

    def submit_content(self, title, content, reviewers):
        new_content = Content(title, content)
        self.contents.append(new_content)
        self.workflows.append(ReviewWorkflow(new_content, reviewers))

    def approve_content(self, content):
        content.status = ContentStatus.APPROVED
        content.review_date = datetime.now()

    def reject_content(self, content):
        content.status = ContentStatus.REJECTED
        content.review_date = datetime.now()

    def review_content(self, content, reviewer, review_result):
        if review_result == "Approve":
            self.approve_content(content)
        else:
            self.reject_content(content)

# Example usage
content_approval_system = ContentApprovalSystem()

content_approval_system.submit_content(
    "New Article",
    "This is a new article that needs to be reviewed.",
    [User("Reviewer 1"), User("Reviewer 2")]
)

# Review content
content_approval_system.review_content(
    content_approval_system.contents[0],
    content_approval_system.workflows[0].next_reviewer(),
    "Approve"
)

# Print content status
print(content_approval_system.contents[0].status)  # Output: Approved

