def validate_input(input):
    """Function to validate input for an AI model"""

    # Check if the input is None or empty
    if input is None or len(input) == 0:
        raise ValueError("Input cannot be None or empty.")

    # Check if the input contains any non-numeric values for a numeric model
    try:
        [float(i) for i in input]
    except ValueError as ve:
        raise ValueError("All inputs must be numbers.") from ve

    # Check that each input value is within an acceptable range
    for i in input:
        if not (MIN_VALUE <= i <= MAX_VALUE):
            raise ValueError(f"Input values must be between {MIN_VALUE} and {MAX_VALUE}.")

    return True

# Set the minimum and maximum allowable values for inputs
MIN_VALUE = 0.0
MAX_VALUE = 1.0

try:
    # Test the function with some inputs
    print(validate_input([0.5, 0.7, 0.2]))     # Expected output: True
    print(validate_input([-0.1, 0.0, 1.1]))   # Expected output: ValueError
    print(validate_input(['a', 'b', 'c']))   # Expected output: ValueError
except ValueError as ve:
    print(ve)

import hashlib
from typing import Dict, List

class ConsensusMechanism:
    def __init__(self, name: str):
        self.name = name

    def validate(self, params: dict) -> bool:
        raise NotImplementedError


class POW(ConsensusMechanism):
    def __init__(self):
        super().__init__("Proof of Work")

    def validate(self, params: Dict[str, int]) -> bool:
        # Check if the hash rate is within a valid range
        if 'hash_rate' not in params or params['hash_rate'] < 1e10:
            return False

        # Check if the block reward is positive and less than or equal to the maximum block reward
        if 'block_reward' not in params or params['block_reward'] <= 0:
            return False

        return True


class POS(ConsensusMechanism):
    def __init__(self):
        super().__init__("Proof of Stake")

    def validate(self, params: Dict[str, int]) -> bool:
        # Check if the stake amount is positive and less than or equal to the maximum stake
        if 'stake_amount' not in params or params['stake_amount'] <= 0:
            return False

        # Check if the epoch time is within a valid range
        if 'epoch_time' not in params or params['epoch_time'] < 1:
            return False

        return True


class DPoS(ConsensusMechanism):
    def __init__(self):
        super().__init__("Delegated Proof of Stake")

    def validate(self, params: Dict[str, int]) -> bool:
        # Check if the voting power is positive and less than or equal to 100
        if 'voting_power' not in params or params['voting_power'] <= 0:
            return False

        # Check if the block time is within a valid range
        if 'block_time' not in params or params['block_time'] < 1:
            return False

        return True


# Example usage:

if __name__ == "__main__":
    pow_params = {'hash_rate': 1000000, 'block_reward': 10}
    pos_params = {'stake_amount': 100, 'epoch_time': 2}
    dpos_params = {'voting_power': 50, 'block_time': 1}

    pow_validator = POW()
    pos_validator = POS()
    dpos_validator = DPoS()

    print(pow_validator.validate(pow_params))
    print(pos_validator.validate(pos_params))
    print(dpos_validator.validate(dpos_params))

import json

def sanitize_key(key):
    """Sanitize a key by removing any special characters from the start and end."""
    allowed_chars = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-.')
    sanitized = []
    for char in key:
        if char in allowed_chars or (char == '"' and len(sanitized) > 0):
            sanitized.append(char)
    return ''.join(sanitized).strip('"')

def sanitize_value(value):
    """Sanitize a value by converting it into a string representation."""
    return json.dumps(value, ensure_ascii=False)

def safe_json_loads(json_obj):
    """Safely deserialize a JSON object/strings into Python objects."""
    try:
        if isinstance(json_obj, dict):
            # If already a dictionary, proceed directly
            return json.loads(json_obj)
        elif isinstance(json_obj, str):
            # If it's a string without quotes and whitespace only
            if not (json_obj.isspace()):
                data = {}
                for key, value in zip(
                    json.loads(json_obj.split('"'*10)[0]),
                    json.loads(json_obj.split('"'*10)[1])
                ):
                    sanitized_key = sanitize_key(key)
                    sanitized_value = sanitize_value(value)
                    if sanitized_key:
                        data[sanitized_key] = sanitized_value
                return data
            else:
                return {}
        # For other types, return empty dict or handle as needed
        return json.loads(json_obj)
    except json.JSONDecodeError:
        return {}

# Example usage:
json_str = '{"name": "John", "age": 30, "city": "New York"}'
parsed_data = safe_json_loads(json_str)
print(parsed_data)  # Output: {'name': 'John', 'age': 30, 'city': 'New York'}

