import datetime

def deduplicate_events(events):
    seen = set()
    deduplicated_events = []

    for event in events:
        if event not in seen:
            deduplicated_events.append(event)
            seen.add(event)

    return deduplicated_events

import threading
from queue import PriorityQueue

class Worker(threading.Thread):
    def __init__(self, tasks):
        threading.Thread.__init__(self)
        self.tasks = tasks
        self.daemon = True
        self.start()

    def run(self):
        while True:
            func, priority, args, kwargs = self.tasks.get()
            try:
                func(*args, **kwargs)
            except Exception as e:
                print(e)
            finally:
                self.tasks.task_done()

class TaskScheduler:
    def __init__(self, num_workers):
        self.tasks = PriorityQueue()
        for _ in range(num_workers): Worker(self.tasks)

    def add_task(self, func, priority=0, *args, **kwargs):
        """Add a new task"""
        self.tasks.put((func, priority, args, kwargs))

# Example usage:
def print_task(message):
    print(f"Task executed: {message}")

scheduler = TaskScheduler(num_workers=5)
scheduler.add_task(print_task, 2, "This is a high priority task")
scheduler.add_task(print_task, 1, "This is a medium priority task")
scheduler.add_task(print_task, 3, "This is a low priority task")
# Join the queue to ensure that all tasks are completed before exiting
scheduler.tasks.join()

