import os

class FilePermissionManager:
    def __init__(self, file_path):
        self.file_path = file_path

    def grant_read_permission(self):
        try:
            # Using os.chmod to change the permissions of a file. The argument 0o444 is for read-only permission.
            os.chmod(self.file_path, 0o444)
            print("Read permission granted")
        except Exception as e:
            print("An error occurred:", e)

    def grant_write_permission(self):
        try:
            # Using os.chmod to change the permissions of a file. The argument 0o644 is for read-write permission.
            os.chmod(self.file_path, 0o644)
            print("Write permission granted")
        except Exception as e:
            print("An error occurred:", e)

    def grant_execute_permission(self):
        try:
            # Using os.chmod to change the permissions of a file. The argument 0o755 is for read-write-execute permission.
            os.chmod(self.file_path, 0o755)
            print("Execute permission granted")
        except Exception as e:
            print("An error occurred:", e)

