int main() {
    // Allocate memory for a 10-element array of integers
    int* arr = malloc(sizeof(int) * 10);

    // Initialize the elements of the array
    for (int i = 0; i < 10; i++) {
        arr[i] = i + 1;
    }

    // Reuse the allocated memory by freeing it and reallocating it
    free(arr);
    arr = malloc(sizeof(int) * 5);

    // Access the elements of the array
    for (int i = 0; i < 5; i++) {
        printf("%d\n", arr[i]);
    }

    // Free the allocated memory again
    free(arr);

    return 0;
}

