    for d in os.listdir(os.path.dirname(os.getcwd())):
        temp_dir = tempfile.mkdtemp()
        if not create_dir(temp_dir):
            continue
        try:
            rmtree(temp_dir)
        except OSError as e:
            print(f"Error cleaning up {temp_dir}: {e}")

    print("All temporary directories cleaned up")

