import threading

class ThreadPoolManager:
    def __init__(self, max_threads):
        self.max_threads = max_threads
        self.thread_pool = []
        self.queue = queue.Queue()

    def add_task(self, task):
        if len(self.thread_pool) < self.max_threads:
            thread = threading.Thread(target=task)
            self.thread_pool.append(thread)
            thread.start()
            return True
        else:
            self.queue.put(task)
            return False

    def get_result(self):
        if not self.queue.empty():
            task = self.queue.get()
            result = task()
            self.queue.task_done()
            return result
        else:
            return None

import time
from sendgrid import SendGrid

# Configuration variables
API_KEY = "your_api_key"  # Replace with your actual API key
RATE_LIMIT = 5  # Number of emails allowed per IP address before rate limiting is applied
RESET_TIME = 3600  # Time in seconds to reset the counter after a failed attempt

class RateLimiting:
    def __init__(self, api_key, limit=RATE_LIMIT, reset_time=RESET_TIME):
        self.sendgrid = SendGrid(api_key)
        self.limit = limit
        self.reset_time = reset_time
        self.sender_count = {}
        self.last_reset = 0

    def _increment_sender(self, sender):
        key = f"{sender}.count" if '.' in sender else sender
        if key not in self.sender_count:
            self.sender_count[key] = 1
        else:
            self.sender_count[key] += 1

            # Check if we need to reset the counter
            current_time = time.time()
            if (current_time - self.last_reset) >= self.reset_time:
                self.last_reset = current_time

    def _is_ratelimited(self, sender):
        key = f"{sender}.count" if '.' in sender else sender
        return self.sender_count.get(key, 0) > self.limit

    def sendEmail(self, fromaddr, toaddr, subject, body):
        try:
            # If rate limited for this sender (IP/Domain), add a delay before retrying
            if self._is_ratelimited(fromaddr):
                if time.time() - self.last_reset < self.reset_time:
                    raise Exception("Rate Limited. Please try after {} seconds".format(self.reset_time))

            # Send the email using sendgrid
            grid = self.sendgridiosisend()
            grid.createEmail(
                from_email=fromaddr,
                to_emails=[toaddr],
                subject=subject,
                body=body,
                html=None  # If needed, add HTML content here
            )
        except Exception as e:
            print(f"Error sending email: {e}")
            raise

