import time
import random
from functools import wraps

def retry(max_attempts=3, backoff_strategy=lambda x: 2**x):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(1, max_attempts + 1):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    if attempt == max_attempts:
                        raise
                    # Backoff strategy
                    backoff = backoff_strategy(attempt)
                    print(f"Attempt {attempt} failed: {e}. Retrying in {backoff} seconds...")
                    time.sleep(backoff + random.random() * 1)  # Add some randomness to the backoff
            return None
        return wrapper
    return decorator

# Example usage:

@retry(max_attempts=5, backoff_strategy=lambda x: 2**x)
def example_function():
    import requests
    response = requests.get("https://example.com/failed-endpoint")
    if response.status_code == 200:
        print("Success!")
    else:
        raise Exception(f"Failed to retrieve data: {response.text}")

try:
