import socket
import threading
import time

class ConnectionChecker:
    def __init__(self, host, port):
        self.host = host
        self.port = port
        self.is_connected = False

    def check_connection(self):
        try:
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.settimeout(1)  # set timeout to 1 second
            connection_time = time.time()
            sock.connect((self.host, self.port))
            if time.time() - connection_time < 1:
                self.is_connected = True
            sock.close()
        except socket.error:
            pass

    def start_check(self):
        while not self.is_connected and threading.active_count() < 10:
            self.check_connection()
            time.sleep(0.5)

def main():
    host = '127.0.0.1'  # replace with the target IP or hostname
    port = 80  # replace with the target port

    checker = ConnectionChecker(host, port)
    thread = threading.Thread(target=checker.start_check)
    thread.daemon = True  # set as daemon to exit when main program exits
    thread.start()

if __name__ == "__main__":
    main()

