import time
from collections import OrderedDict

class Cache:
    def __init__(self, size):
        self.size = size
        self.cache = OrderedDict()

    def get(self, key):
        if key in self.cache:
            self.cache.move_to_end(key)
            return self.cache[key]
        else:
            return None

    def put(self, key, value):
        if key in self.cache:
            self.cache[key] = value
            self.cache.move_to_end(key)
        else:
            if len(self.cache) == self.size:
                self.cache.popitem(last=False)
            self.cache[key] = value

    def evict_oldest(self):
        return self.cache.popitem(last=False)[0]

    def evict_least_recently_used(self):
        return self.cache.popitem(last=True)[0]

# Example usage:

cache = Cache(size=3)

cache.put("a", 1)
cache.put("b", 2)
cache.put("c", 3)

print("Get 'a':", cache.get("a"))  # Output: 1

cache.put("d", 4)

print("Least Recently Used eviction:", cache.evict_least_recently_used())  # Output: 'b'
print("Oldest eviction:", cache.evict_oldest())  # Output: 'a'

