import os
import shutil
from datetime import datetime, timedelta

class BackupManager:
    def __init__(self, backup_dir):
        self.backup_dir = backup_dir
        if not os.path.exists(self.backup_dir):
            os.makedirs(self.backup_dir)

    def create_full_backup(self, source_dir):
        """Create a full backup of the specified directory"""
        timestamp = datetime.now().strftime("%Y-%m-%d_%H-%M-%S")
        full_backup_path = os.path.join(self.backup_dir, f"{timestamp}_full_backup.tar.gz")

        # Create a tarball of the source directory
        with shutil.make_archive(f"{source_dir}_{timestamp}", "gz", source_dir) as archive:
            shutil.move(archive, full_backup_path)

    def create_incremental_backup(self, source_dir, previous_backup):
        """Create an incremental backup of the specified directory"""
        timestamp = datetime.now().strftime("%Y-%m-%d_%H-%M-%S")
        incremental_backup_path = os.path.join(self.backup_dir, f"{timestamp}_incremental.tar.gz")

        # Check if the previous backup exists
        if not os.path.exists(previous_backup):
            print("Previous backup does not exist. Skipping incremental backup.")
            return

        # Copy files from previous backup to new incremental backup
        with tarfile.open(previous_backup, "r:gz") as previous_archive:
            with tarfile.open(incremental_backup_path, "w:gz") as new_archive:
                for member in previous_archive.getmembers():
                    if os.path.basename(member.name) not in [f"{timestamp}.tar.gz", f"{timestamp}_full_backup.tar.gz"]:
                        new_archive.addmember(member)

    def delete_old_backups(self):
        """Delete old backups from the specified directory"""
        current_timestamp = datetime.now().strftime("%Y-%m-%d_%H-%M-%S")
        for file in os.listdir(self.backup_dir):
            if not file.startswith(current_timestamp) or file == f"{current_timestamp}_full_backup.tar.gz":
                os.remove(os.path.join(self.backup_dir, file))

def main():
    # Create a backup manager
    backup_manager = BackupManager("/path/to/backup/directory")

    while True:
        print("\nBackup Manager Menu:")
        print("1. Create full backup")
        print("2. Create incremental backup")
        print("3. Delete old backups")
        print("4. Quit")

        choice = input("Enter your choice: ")

        if choice == "1":
            source_dir = input("Enter the source directory path: ")
            backup_manager.create_full_backup(source_dir)
        elif choice == "2":
            source_dir = input("Enter the source directory path: ")
            previous_backup = input("Enter the path of the previous full backup: ")
            backup_manager.create_incremental_backup(source_dir, previous_backup)
        elif choice == "3":
            backup_manager.delete_old_backups()
        elif choice == "4":
            break
        else:
            print("Invalid choice. Please try again.")

if __name__ == "__main__":
    main()

