from http.client import HTTPClient, IncompleteReadError

def decode_webhook_payload(payload):
    """Decode a base64 encoded string payload"""
    total = 0
    lines = []

    while True:
        line = payload.readline()
        if not line:
            break
        # Strip the trailing newline character (LF)
        line = line.rstrip('\n\r')
        lines.append(line.encode('utf-8'))

        length = int(lines[-1][:2])  # First two characters are the length field in CCITT format
        total += length

    decoded = binascii.a2ceil(binascii.b2aalt(total, bytes=b'', len=len(payload)))

    # Now decode as UTF-8 and return as a string
    payload_str = decoded.decode('utf-8')
    return json.loads(payload_str)

def send_request(method, url, data=None):
    """Send an HTTP request with the given method"""
    client = HTTPClient(url)
    try:
        if method == 'POST':
            response = client.request(method, url, body=data)
        elif method == 'PUT':
            # PUT can also use body parameter
            response = client.request(method, url, body=data)
        else:  # GET
            response = client.request(method, url)

        return response
    except IncompleteReadError as e:
        raise ValueError(f"Request failed: {e}")

def fetch_webhooks(api_url):
    """Fetch all webhooks from an API URL"""
    webhooks = []

    try:
        with requests.Session() as s:
            response = s.get(api_url)
            response.raise_for_status()

            webhooks_data = response.json()
            for webhook in webhooks_data['webhooks']:
                yield webhook

    except requests.exceptions.RequestException as e:
        print(f"Failed to fetch webhooks: {e}")

def process_webhook(payload, channel_name):
    """Process the incoming webhook payload"""
    try:
        # Parse the payload
        data = decode_webhook_payload(payload)

        if 'message' in data and 'content' in data:
            message = f"{data['message']}: {data['content'].strip()}"
        else:
            return

        print(f"Received message from {channel_name}: {message}")
        # Here you would typically send a response or handle the event accordingly
    except Exception as e:
