import logging
from collections import deque

# Create a logger
logger = logging.getLogger(__name__)
logging.basicConfig(level=logging.INFO)

class Queue:
    def __init__(self):
        self._queue = deque()

    def enqueue(self, item):
        self._queue.appendleft(item)
        logger.info('Enqueue operation - Item added: {}'.format(item))

    def dequeue(self):
        if len(self._queue)!=0:
            removed_item = self._queue.pop()
            logger.info('Dequeue operation - Removed item: {}'.format(removed_item))
            return removed_item
        else:
            logger.error('Dequeue operation - Queue is empty, cannot dequeue')
            raise IndexError("Queue is empty")

    def size(self):
        logger.info('Size operation - Current queue size: {}'.format(len(self._queue)))
        return len(self._queue)

    def peek(self):
        if len(self._queue)!=0:
            return self._queue[-1]
        else:
            logger.error('Peek operation - Queue is empty, cannot peek')
            raise IndexError("Queue is empty")

# Example usage        
q = Queue()
q.enqueue(5)  # logs "Enqueue operation - Item added: 5"
print(q.size())  # logs "Size operation - Current queue size: 1", prints "1"
q.dequeue()  # logs "Dequeue operation - Removed item: 5"

import dns.resolver
from email import message_from_bytes
import re

def get_domain(email):
    match = re.search(r'@[\w.-]+', email)
    if match:
        return match.group()[1:]
    return None

def check_dmarc(email):
    domain = get_domain(email)
    if not domain:
        return False

    query = f'_{"dmarc"}.{domain}'

    try:
        records = dns.resolver.query(query, 'TXT')
        for record in records:
            if "p=reject" in str(record):
                return True
    except (dns.resolver.NXDOMAIN, dns.resolver.NoAnswer):
        pass

    return False

def is_spoofed(raw_email):
    msg = message_from_bytes(raw_email)
    from_address = msg['From']
    if check_dmarc(from_address):
        return False
    else:
        return True

