import os
from pathlib import Path

# List of potentially malicious file extensions (this is not exhaustive)
MALICIOUS_EXTENSIONS = ['.exe', '.dll', '.bat', '.cmd']

def scan_directory(path):
    for entry in os.scandir(path):
        if entry.is_file():
            ext = Path(entry).suffix
            if ext in MALICIOUS_EXTENSIONS:
                print(f"Potentially malicious file detected: {entry.path}")
        elif entry.is_dir():
            scan_directory(entry.path)  # Recursively scan subdirectories

# Replace 'your_folder' with the path to the folder you want to scan
