def check_inventory(required, available):
    low_stock = []

    for item in required:
        if available.get(item, 0) < required[item]:
            shortfall = required[item] - available[item]
            low_stock.append(f"{item}: Shortage of {shortfall}")

    if low_stock:
        return f"Low stock items:\n{('\n').join(low_stock)}"
    else:
        return "No items are low on stock."

import time

# Define the scraping function
def scrape(url):
    # Perform scraping logic here
    print(f"Scraping {url}")

# Define the throttle function
def throttle(request_interval):
    last_request_time = time.time()

    def wrapper(func, *args, **kwargs):
        current_time = time.time()
        if current_time - last_request_time >= request_interval:
            func(*args, **kwargs)
            last_request_time = current_time
        else:
            print(f"Throttling request to {url}")

    return wrapper

# Apply throttle to the scrape function
