import requests
from abc import ABC, abstractmethod
from typing import Dict, Any

class PaymentGatewayResponse(ABC):
    @abstractmethod
    def handle_response(self, response: requests.Response) -> None:
        pass


class SuccessResponseHandler(PaymentGatewayResponse):
    def handle_response(self, response: requests.Response) -> None:
        print(f"Payment successful. Response code: {response.status_code}")
        if 'transaction_id' in response.json():
            print(f"Transaction ID: {response.json()['transaction_id']}")


class FailureResponseHandler(PaymentGatewayResponse):
    def handle_response(self, response: requests.Response) -> None:
        print(f"Payment failed. Error: {response.text}")
        print(f"Response code: {response.status_code}")


class PaymentGateway:
    def __init__(self, url: str, api_key: str):
        self.url = url
        self.api_key = api_key

    def send_payment(self, amount: float) -> requests.Response:
        data = {
            'amount': str(amount),
            'currency': 'USD'
        }
        headers = {
            'Authorization': f'Bearer {self.api_key}',
            'Content-Type': 'application/json'
        }

        response = requests.post(f"{self.url}/payment", json=data, headers=headers)

        if response.status_code == 200:
            return response
        else:
            raise Exception("Failed to send payment")


def main():
    gateway_url = "https://api.example.com/payment/gateway"
    api_key = "your_api_key"

    gateway = PaymentGateway(gateway_url, api_key)
    try:
        amount = 10.99
        response = gateway.send_payment(amount)

        # Get the response from the payment gateway
        response_json = response.json()

        if 'transaction_id' in response_json:
            handler = SuccessResponseHandler()
            handler.handle_response(response)
        else:
            handler = FailureResponseHandler()
            handler.handle_response(response)

    except Exception as e:
        print(f"An error occurred: {e}")


if __name__ == "__main__":
    main()

