import time
import random

def retry(max_retries=3, delay=1, retries_type="exponential"):
    """
    Implement retry mechanism with different policies.

    Args:
        max_retries (int): Maximum number of retries allowed.
        delay (int): Initial delay between retries in seconds.
        retries_type (str): Type of retry policy. 
                            Can be 'fixed' for fixed intervals,
                            'exponential' for exponential backoff,
                            or 'geometric' for geometric backoff.

    Returns:
        Function: A decorator that can be applied to functions to enable retries.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            for _ in range(max_retries + 1):  # Include the initial attempt
                try:
                    result = func(*args, **kwargs)
                    return result
                except Exception as e:
                    if _ == max_retries:
                        break
                    # Calculate wait time based on retry policy
                    if retries_type == "fixed":
                        time.sleep(delay)
                    elif retries_type == "exponential" or retries_type == "geometric":
                        exponent = random.randint(1, 5)  # Random exponent between 1-5
                        if retries_type == "geometric":
                            base = 2
                            delay = base ** exponent
                        else:
                            delay *= 2  # Exponential backoff: double the previous delay
                    else:
                        raise ValueError(f"Unsupported retry type: {retries_type}")
            return result  # In case of success, though exception is caught above

        wrapper.__name__ = func.__name__
        return wrapper
    return decorator

# Example usage:
@retry(max_retries=3, delay=1)
def example_task():
    # Simulate a failed function; replace this with actual task
    raise Exception("Task failed")

try:
