except Exception as e:
    print(f"Error: {e}")

import pickle

class SecureSerializer:
    def __init__(self):
        self.validated_data = None

    def validate_data(self, data):
        # Basic validation: check if data is a dictionary or a list of dictionaries
        if isinstance(data, dict) or (isinstance(data, list) and all(isinstance(item, dict) for item in data)):
            return True
        return False

    def serialize_object(self, obj):
        try:
            validated_data = self.validate_data(obj)
            if not validated_data:
                raise ValueError("Invalid data type")
            serialized_obj = pickle.dumps(obj)
            return serialized_obj
        except Exception as e:
            print(f"Error serializing object: {e}")
            return None

    def deserialize_object(self, serialized_obj):
        try:
            deserialized_obj = pickle.loads(serialized_obj)
            return deserialized_obj
        except Exception as e:
            print(f"Error deserializing object: {e}")
            return None


# Example usage:

if __name__ == "__main__":
    serializer = SecureSerializer()

    # Create an example object
    user_data = {
        "username": "john_doe",
        "email": "johndoe@example.com"
    }

    serialized_obj = serializer.serialize_object(user_data)
    print(f"Serialized Object: {serialized_obj}")

    deserialized_obj = serializer.deserialize_object(serialized_obj)
    print(f"Deserialized Object: {deserialized_obj}")

