from abc import ABC, abstractmethod

class User(ABC):
    def __init__(self, username, password):
        self.username = username
        self.password = password

class Admin(User):
    def can_access(self, resource):
        return True  # admin has access to all resources

class Manager(User):
    def can_access(self, resource):
        if resource in ["report", "dashboard"]:
            return True  # manager can access report and dashboard
        elif resource == "admin":
            return False  # manager cannot access admin page
        else:
            return False  # manager cannot access other resources

class Employee(User):
    def can_access(self, resource):
        if resource in ["email", "chat"]:
            return True  # employee can access email and chat
        elif resource == "manager":
            return False  # employee cannot access manager page
        else:
            return False  # employee cannot access other resources

class Resource(ABC):
    def __init__(self, name):
        self.name = name

    @abstractmethod
    def is_accessible(self, user):
        pass

class Report(Resource):
    def is_accessible(self, user):
        if isinstance(user, Manager) or isinstance(user, Admin):
            return True  # report is accessible to manager and admin
        else:
            return False  # report is not accessible to other users

class Dashboard(Resource):
    def is_accessible(self, user):
        if isinstance(user, Manager) or isinstance(user, Admin):
            return True  # dashboard is accessible to manager and admin
        else:
            return False  # dashboard is not accessible to other users

class Email(Resource):
    def is_accessible(self, user):
        if isinstance(user, Employee):
            return True  # email is accessible to employee
        else:
            return False  # email is not accessible to other users

class Chat(Resource):
    def is_accessible(self, user):
        if isinstance(user, Employee):
            return True  # chat is accessible to employee
        else:
            return False  # chat is not accessible to other users

# Example usage:

admin = Admin("admin", "password")
print(admin.can_access(Report()))  # Output: True

manager = Manager("manager", "password")
print(manager.can_access(Dashboard()))  # Output: True
print(manager.can_access(Email()))  # Output: False

employee = Employee("employee", "password")
print(employee.can_access(Chat()))  # Output: True
print(employee.can_access(Dashboard()))  # Output: False

