class NotificationType(Enum):
    TASK_COMPLETED = "Task Completed"
    NEW_TASK_ADDED = "New Task Added"

class TaskNotification:
    def __init__(self, notification_type: NotificationType, task_name: str):
        self.notification_type = notification_type
        self.task_name = task_name

    def send_notification(self):
        print(f"{self.notification_type.value}: {self.task_name} has been completed.")

class TaskManager:
    def __init__(self):
        self.tasks = {}

    def add_task(self, task_name: str):
        if task_name not in self.tasks:
            self.tasks[task_name] = datetime.datetime.now()
            print(f"New task '{task_name}' added.")
            send_notification(NotificationType.NEW_TASK_ADDED, task_name)
        else:
            print(f"Task '{task_name}' already exists.")

    def complete_task(self, task_name: str):
        if task_name in self.tasks:
            completion_time = datetime.datetime.now()
            elapsed_time = (completion_time - self.tasks[task_name]).total_seconds() / 60
            print(f"Task '{task_name}' completed in {elapsed_time:.2f} minutes.")
            send_notification(NotificationType.TASK_COMPLETED, task_name)
            del self.tasks[task_name]
        else:
            print(f"Task '{task_name}' does not exist.")

