import os
import time
import threading

class FileLock:
    def __init__(self, filename):
        self.filename = filename
        self.lock_file = f"{filename}.lock"

    def acquire(self):
        with open(self.lock_file, 'w') as f:
            f.write(f"Lock: {time.time()}")
        print(f"Acquired lock on file '{self.filename}'")
        return True

    def release(self):
        try:
            os.remove(self.lock_file)
        except FileNotFoundError:
            pass
        print(f"Released lock on file '{self.filename}'")

# Usage example:

def write_to_file(file_lock, filename, content):
    if not file_lock.acquire():
        print(f"Failed to acquire lock on file '{filename}'. Trying again...")
        time.sleep(0.1)
        return write_to_file(file_lock, filename, content)

    try:
        with open(filename, 'w') as f:
            f.write(content)
    except Exception as e:
        print(f"Error writing to file: {e}")
    finally:
        file_lock.release()

file_lock = FileLock("example.txt")
write_to_file(file_lock, "example.txt", "Hello, World!")

import time

class TTLCache:
    def __init__(self, max_size, ttl=None):
        self.max_size = max_size
        self.ttl = ttl  # Time-to-live; if None, never expire
        self.default_value = None  # Default value for missing keys
        self.cache = {}  # Key-value pairs stored in the cache
        self.timestamps = {}  # To track when each key was added

    def add(self, key, value):
        current_time = time.time()
        if key in self.cache:
            # Update timestamp to avoid premature expiration of existing items
            selftimestamps = self.timestamps[key]
            new_timestamp = max(selftimestamps, current_time)
            self.timestamps[key] = new_timestamp
        else:
            # New item or existing but stale entry; use the provided timestamp
            self.cache[key] = value
            self.timestamps[key] = current_time

    def evict(self):
        """
        Evicts entries based on max_size and TTL.
        First removes expired items, then applies size limit if necessary.
        Returns list of keys to remove during eviction.
        """
        # Evict all expired keys first
        expired_keys = [k for k in self.cache.keys() if (time.time() - self.timestamps[k]) >= self.ttl]
        if expired_keys:
            print(f"Removing {len(expired_keys)} expired keys: {expired_keys}")
            for key in expired_keys:
                del self.cache[key]
                del self.timestamps[key]

        # Now handle the size limit
        current_size = len(self.cache)
        if self.max_size is not None and current_size > self.max_size:
            remove_count = current_size - self.max_size
            keys_to_remove = list(self.cache.keys())[:remove_count]
            print(f"Removing {len(keys_to_remove)} to reduce size from {current_size} to {self.max_size}: {keys_to_remove}")
            for key in keys_to_remove:
                del self.cache[key]
                del self.timestamps[key]

    def get(self, key):
        current_time = time.time()
        if key not in self.cache and self.default_value is None:
            raise KeyError(f"Key {key} not found")

        # Check expiration
        if self.ttl is not None:
            if key in self.cache:
                if (current_time - self.timestamps[key]) >= self.ttl:
                    raise KeyError(f"Key {key} has expired")

        return self.cache.get(key, self.default_value)

from collections import deque

class EventHandler:
    def __init__(self):
        self.event_queue = deque()
        self.event_handlers = {}

    def register_event_handler(self, event_type, handler):
        self.event_handlers[event_type] = handler

    def handle_event(self, event):
        if event['type'] in self.event_handlers:
            self.event_handlers[event['type']](event)
        else:
            self.event_queue.append(event)

    def process_events(self):
        while self.event_queue:
            event = self.event_queue.popleft()
            self.handle_event(event)

# Example usage
event_handler = EventHandler()

# Register event handlers
event_handler.register_event_handler('login', lambda event: print(f"User {event['user']} logged in"))
event_handler.register_event_handler('purchase', lambda event: print(f"User {event['user']} purchased {event['item']}"))

# Handle events out-of-order
event_handler.handle_event({'type': 'purchase', 'user': 'john', 'item': 'book'})
event_handler.handle_event({'type': 'login', 'user': 'john'})

# Process events in order
event_handler.process_events()

