import sched
import os
import time

class DependencyChecker:
    def __init__(self, package_name, allowed_versions, last_checked_time, log_file):
        self.package_name = package_name
        self.allowed_versions = allowed_versions.copy()  # To avoid mutation
        self.last_checked_time = last_checked_time
        self.log_file = log_file
        self.check_interval_seconds = 3600  # Check every hour

    def _get_installed_packages(self):
        """Fetch and return a dictionary of installed packages with their versions."""
        try:
            result = os.popen('pip freeze').read().splitlines()
            packages = {}
            for line in result[1:]:  # Skip the header
                package, version = line.strip().split()
                if package in self.allowed_versions:
                    packages[package] = (int(version),)
            return packages
        except Exception as e:
            print(f"Error checking dependencies: {e}")
            return None

    def _check_dependencies(self):
        """Check each dependency against allowed versions and log changes."""
        current_versions = self._get_installed_packages()
        if not current_versions:
            print(f"No installed packages for {self.package_name}")
            return

        last_checked_time = time.time() * 1000
        update_interval = f"{self.check_interval_seconds} minutes"

        for package, allowed_version in self.allowed_versions.items():
            min_version, max_version = allowed_version
            current_min, _ = current_versions.get(package, (None, None))

            if current_min is None:
                print(f"Package {package} not installed.")
                continue

            # Compare versions. Note: This assumes minor version and patch are sufficient.
            is_outdated = current_min > max_version or (current_min > min_version and current_min < max_version)
            if is_outdated:
                print(f"Warning: Package {self.package_name}.{package} ({current_min}) is out of date from allowed range [min:{min_version}, max:{max_version}]")
                print(f"Please update from: https://pypi.org/project/{self.package_name}/")

        current_time = time.time() * 1000
        if (current_time - last_checked_time) > self.check_interval_seconds * 60:
            print(f"Checking dependencies at {current_time // 60} minutes {current_time % 60:.2f}s")
            checker_thread = schedunsched.checking.time_checking.checker(self.run_check, update_interval)
            if checker_thread is None:
                print("No check running yet.")
            else:
                print(f"Check will run at {self.last_checked_time // 60} minutes {self.last_checked_time % 60:.2f}s")

    def run_check(self):
        self._check_dependencies()

def schedule_checker(checker):
    scheduler = schedunsched.checking.Scheduler()
    next_run = time.time() * 1000
    while True:
        if time.time() > next_run + (59 * 60):  # Schedule at top of each hour for simplicity
            print("Scheduling checker...", file=sys.stderr)
            scheduler.run(schedulerunsched.checking.checker.run_check(), now=time.time())
            next_run = time.time()
        else:
            time.sleep(1)

def main():
    log_dir = "dependency_logs"
    os.makedirs(log_dir, exist_ok=True)

    package_checkers = {
        'requests': {
            'allowed_versions': {'requests' : (2.30, 2.31),},
            'log_file': os.path.join(log_dir, 'requests.log'),
        },
        'python-dotenv': {
            'allowed_versions': {'python-dotenv' : (0.4.0, None)},  # Allow up to latest version
            'log_file': os.path.join(log_dir, 'python-dotenv.log'),
        }
    }

    for name, config in package_checkers.items():
        checker = DependencyChecker(
            package_name=name,
            allowed_versions=config['allowed_versions'].copy(),
            last_checked_time=time.time() * 1000,
            log_file=config['log_file']
        )
        if not os.path.exists(checker.log_file):
            print(f"Creating new log file at {checker.log_file}")
            os.makedirs(os.path.dirname(checker.log_file), exist_ok=True)

        checker.run_check()
        scheduler = schedunsched.checking.Scheduler()
        job = schedulerunsched.checking.checker.run_check()
        if not job:
            print("Scheduled checker...", file=sys.stderr)

if __name__ == "__main__":
    import sys
    import schedunsched  # Ensure schedunsched is installed as a dependency

    main()

import hashlib
import time

class Block:
    def __init__(self, index, previous_hash, timestamp, data, hash):
        self.index = index
        self.previous_hash = previous_hash
        self.timestamp = timestamp
        self.data = data
        self.hash = hash

def calculate_hash(index, previous_hash, timestamp, data):
    value = str(index) + str(previous_hash) + str(timestamp) + str(data)
    return hashlib.sha256(value.encode('utf-8')).hexdigest()

def create_genesis_block():
    return Block(0, "0", time.time(), "Genesis Block", calculate_hash(0, "0", time.time(), "Genesis Block"))

def create_new_block(previous_block, data):
    index = previous_block.index + 1
    timestamp = time.time()
    hash = calculate_hash(index, previous_block.hash, timestamp, data)
    return Block(index, previous_block.hash, timestamp, data, hash)

def validate_block(new_block, previous_block):
    if new_block.previous_hash != previous_block.hash:
        print("Invalid block: Previous hashes don't match")
        return False
    elif calculate_hash(new_block.index, new_block.previous_hash, new_block.timestamp, new_block.data) != new_block.hash:
        print("Invalid block: Hash doesn't match contents")
        return False
    else:
        return True

# Create a Blockchain with the Genesis Block
blockchain = [create_genesis_block()]
previous_block = blockchain[0]

print("Blockchain contains Genesis Block: ")
print(vars(previous_block))

num_blocks = 20 # number of blocks to be added in the chain
for i in range(1, num_blocks + 1):
    new_block = create_new_block(previous_block, "Block Data:" + str(i))

    if validate_block(new_block, previous_block) == True:
        blockchain.append(new_block)
        previous_block = new_block
        print("Block ", i, " has been added to the Blockchain")
    else:
        print("Block ", i, " cannot be added to the Blockchain")

import time
from threading import Lock
import pandas as pd

# Initialize variables
stock_dict = {}
check_interval = 5 * 60  # Check every 5 minutes in seconds
threshold = 10  # Alert if stock drops below 10 units

class StockMonitor:
    def __init__(self):
        self.stock_dict = {}
        self.check_interval = check_interval
        self.threshold = threshold
        self.lock = Lock()

    def parse_inventory(self):
        """Parse the CSV file and populate the stock dictionary."""
        try:
            df = pd.read_csv('inventory.csv')
            for index, row in df.iterrows():
                product_id = int(row['Product ID'])
                name = row['Name']
                category = row['Category']
                self.stock_dict[name] = row['Stock Level']
        except Exception as e:
            print(f"Error parsing inventory file: {e}")

    def check_stock(self):
        """Check stock levels and update the dictionary."""
        self.lock.acquire()
        try:
            current_time = time.time()

            while True:
                self.parse_inventory()

                # Remove products below threshold
                for product, level in list(stock_dict.items()):
                    if level < self.threshold:
                        print(f"Alert: Product {product} has stock level {level}.")

                time.sleep(self.check_interval)
        except Exception as e:
            print(f"Error during check_stock: {e}")
        finally:
            self.lock.release()

# Initialize the monitor
monitor = StockMonitor()

# Start monitoring in a loop
while True:
    try:
        monitor.check_stock()
    except KeyboardInterrupt:
        break

import sys
import json
import requests

class ApiRequestLog:
    def __init__(self, api_key_path='api_requests.log'):
        self.api_key_path = api_key_path

    def log_request(self, method, url, headers=None, params=None, data=None):
        try:
            request_dict = {
                'Method': method,
                'URL': url,
                'Headers': str(headers),
                'Params': str(params),
                'Data': str(data) if data else None,
                'Status Code': requests.get(url).status_code,
                'Response': requests.get(url).content
            }
            log_data = {
                'Action': request_dict['Method'],
                'Platform': url.split('/')[2],
                'Details': json.dumps(request_dict, indent=2)
            }
            self._write_to_file(log_data)
            print(f"API Request Sent: {request_dict}")
        except Exception as e:
            error_dict = {
                'Error Type': str(type(e)),
                'Platform': url.split('/')[2],
                'Details': f"Error occurred during API request: {str(e)}"
            }
            self._write_to_file(error_dict)
            print(f"API Request Error: {error_dict}")

    def _write_to_file(self, data):
        with open(self.api_key_path, 'a') as f:
            json.dump(data, f, indent=2)

def make_facebook_request(action, user_ids, password, callback_url='https://graph.facebook.com'):
    facebook_token = 'REPLACE_WITH_YOUR_FACEBOOK_TOKEN'
    headers = {
        'Authorization': f'Bearer {facebook_token}',
        'X-FB-API-Version': '2.5'
    }

    if action == 'login':
        body = {'auth_state': True}
        url = f"{callback_url}/ Graph/Api/v2.4/Account/Log-In"
    elif action == 'friend_request':
        user1_id, user2_id = user_ids
        body = {
            "_主要包括发起请求的参数，如用户ID等 information": f"Id: {user1_id}",
            "FromId": user2_id,
            ",to": user1_id,
            "RequestedEntity": "Person"
        }
        url = f"{callback_url}/Graph/v3.4/Account/FriendRequest"
    else:
        raise ValueError(f"Invalid Facebook action: {action}")

    try:
        response = requests.post(url, headers=headers, json=body)
        return response
    except requests.exceptions.RequestException as e:
        print(f"Facebook API Request Error: {str(e)}")

def make_twitter_request(action, user_id=None, media_url=None):
    twitter_token = 'REPLACE_WITH_YOUR_TWITTER_TOKEN'
    headers = {
        'Authorization': f'Bearer {twitter_token}',
        'X-Auth-Token': 'REPLACE_WITH_YOUR_X_AUTH_TOKEN',
        'X-Cards-New-Twitter-App-Id': 'REPLACE_WITH_YOUR_CARDS_ID'
    }

    if action == 'follow':
        params = {'with_name': True, ' Following': user_id}
