import logging
import time
from csv import writer

class Pipeline:
    def __init__(self, name):
        self.name = name
        self.metrics = {
            "processing_time": 0,
            "data_size": 0,
            "error_rate": 0
        }
        self.log_file = f"{name}_log.csv"

    def track_metrics(self, processing_time, data_size, error_rate):
        self.metrics["processing_time"] += processing_time
        self.metrics["data_size"] += data_size
        self.metrics["error_rate"] += error_rate

    def log_metrics(self):
        with open(self.log_file, "a", newline="") as csvfile:
            fieldnames = ["timestamp", "processing_time", "data_size", "error_rate"]
            writer = csv.DictWriter(csvfile, fieldnames=fieldnames)
            if csvfile.tell() == 0:
                writer.writeheader()
            writer.writerow({
                "timestamp": time.strftime("%Y-%m-%d %H:%M:%S"),
                "processing_time": self.metrics["processing_time"],
                "data_size": self.metrics["data_size"],
                "error_rate": self.metrics["error_rate"]
            })

import sys

def add_to_input_chain(ip_str, port):
    try:
        if '.' in ip_str and len(ip_str.split('.')) == 4:
            ip_address = ' '.join(['--source-ip', ip_str])
            return f"iptables -t nat -A INPUT --source-ip {ip_str} -p incoming --dport {port}"
        elif ':' in ip_str and len(ip_str.split(':')) == 8:
            ip_address = '--source-ipv6'
            source = ' '.join(['--source-ipv6', ip_str])
            return f"iptables -t nat -A INPUT {source} --dport {port}"
        else:
            raise ValueError
    except ValueError as e:
        print(f"Invalid IP address: {e}")
        return None

def main():
    try:
        ip_line = sys.stdin.readline().strip()
        port_line = sys.stdin.readline().strip()
        if not ip_line or not port_line:
            print("Please provide both an IP address and a port number.")
            return
        port = int(port_line)
        command = add_to_input_chain(ip_line, port)
        if command is None:
            print(command)
    except ValueError:
        print("Invalid port number.")

if __name__ == "__main__":
    main()

import requests
import time

# Webhook URL
webhook_url = "YOUR_WEBHOOK_URL"

# Retry count
max_retries = 3

# Timeout for each retry
retry_delay = 5

# Function to retry webhook delivery
def retry_webhook(payload):
    retries = 0
    while retries < max_retries:
        try:
            response = requests.post(webhook_url, json=payload)
            if response.status_code == 200:
                return True
            else:
                raise Exception(f"Webhook delivery failed with status code: {response.status_code}")
        except Exception as e:
            retries += 1
            time.sleep(retry_delay)
            print(f"Retry {retries}/{max_retries}: {e}")

    return False

# Example payload
payload = {"message": "Hello, world!"}

# Retry webhook delivery
if retry_webhook(payload):
    print("Webhook delivery successful.")
else:
    print("Webhook delivery failed.")

