import logging
import os

# Define a logger class
class DependencyLogger:
    def __init__(self, log_file):
        self.log_file = log_file
        self.logger = logging.getLogger(__name__)
        self.logger.setLevel(logging.INFO)
        handler = logging.FileHandler(log_file)
        formatter = logging.Formatter('%(asctime)s - %(message)s')
        handler.setFormatter(formatter)
        self.logger.addHandler(handler)

    def info(self, message):
        """Log an informational message"""
        self.logger.info(message)

    def error(self, message):
        """Log an error message"""
        self.logger.error(message)


class Dependency:
    """Represents a dependency"""

    def __init__(self, name, version):
        self.name = name
        self.version = version

    def update_version(self, new_version):
        """Update the version of this dependency"""
        self.version = new_version


class PackageManager:
    """Represents a package manager that can log dependency changes"""

    def __init__(self):
        self.dependencies = {}
        self.logger = DependencyLogger('dependency_changes.log')

    def add_dependency(self, name, version):
        """Add a dependency with its current version"""
        if name in self.dependencies:
            self.dependencies[name].update_version(version)
            self.logger.info(f"Updated {name} to {version}")
        else:
            self.dependencies[name] = Dependency(name, version)

    def remove_dependency(self, name):
        """Remove a dependency"""
        if name in self.dependencies:
            del self.dependencies[name]
            self.logger.info(f"Removed {name}")

    def update_dependency_version(self, name, new_version):
        """Update the version of an existing dependency"""
        if name in self.dependencies:
            self.dependencies[name].update_version(new_version)
            self.logger.info(f"Updated {name} to {new_version}")
        else:
            self.logger.error(f"{name} not found")


# Example usage
package_manager = PackageManager()

# Add dependencies
package_manager.add_dependency('numpy', '1.22.3')
package_manager.add_dependency('pandas', '1.4.2')

# Update dependency version
package_manager.update_dependency_version('numpy', '1.23.0')

# Remove a dependency
package_manager.remove_dependency('pandas')

