class Permission:
    """Represents a permission that can be assigned to users."""

    def __init__(self, name):
        self.name = name

class Role:
    """Represents a role in the RBAC system."""

    def __init__(self, name, permissions=None):
        self.name = name
        self.permissions = permissions if permissions else []

class User:
    """Represents a user with assigned roles and permissions."""

    def __init__(self, username, roles=None):
        self.username = username
        self.roles = roles if roles else []

class ResourceAccessValidator:
    """Validates access to resources based on user roles and permissions."""

    def __init__(self):
        self.resources = {
            "read": Permission("READ"),
            "write": Permission("WRITE"),
            "delete": Permission("DELETE")
        }
        self.user_roles = {}

    def add_user(self, username, roles):
        """Adds a new user with assigned roles."""

        if username in self.user_roles:
            raise ValueError(f"User '{username}' already exists.")

        self.user_roles[username] = roles

    def assign_permission_to_role(self, role_name, permission_name):
        """Assigns a permission to a specific role."""

        for user, user_roles in self.user_roles.items():
            if role_name in [role.name for role in user_roles]:
                # Check if the permission already exists in the role
                existing_permissions = {p.name for p in self.user_roles[user]}
                if permission_name not in existing_permissions:
                    self.user_roles[user].append(Role(role_name, [self.resources[permission_name]]))

    def validate_access(self, username, resource, action):
        """Validates access to a specific resource."""

        user = next((user for user, roles in self.user_roles.items() if username == user.username), None)
        if user is None:
            raise ValueError(f"User '{username}' does not exist.")

        role_permissions = [p.name for r in user.roles for p in r.permissions]

        # Check if the user has the required permission
        if action in ["read", "write", "delete"] and self.resources[action] != self.resources[resource]:
            return False

        # Check if the resource exists and is accessible to the role
        if resource not in self.user_roles[user] or resource not in [p.name for r in user.roles for p in r.permissions]:
            return False

        return True

# Example usage:
validator = ResourceAccessValidator()

# Assign permissions to roles
validator.assign_permission_to_role("admin", "READ")
validator.assign_permission_to_role("admin", "WRITE")
validator.assign_permission_to_role("user", "READ")

# Add users with assigned roles
validator.add_user("admin", [Role("admin", [validator.resources["READ"], validator.resources["WRITE"]])])
validator.add_user("user", [Role("user", [validator.resources["READ"]])])

# Validate access to resources
print(validator.validate_access("admin", "read", "read"))  # Output: True
print(validator.validate_access("admin", "write", "read"))  # Output: False
print(validator.validate_access("user", "delete", "delete"))  # Output: False

