import socket
import threading

# Server setup
server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
server_socket.bind(('localhost', 12345))
server_socket.listen(5)

def broadcast(message):
    """Broadcast a message to all connected clients"""
    for client_socket in clients:
        client_socket.sendall(message.encode())

def handle_client(client_socket):
    """Handle incoming messages from a client"""
    while True:
        try:
            message = client_socket.recv(1024)
            if not message:
                break
            print(f"Received from {client_socket.getpeername()}: {message.decode()}")
            broadcast(message)  # Broadcast the message to all clients
        except Exception as e:
            print(f"Error handling client: {e}")
            client_socket.close()
            clients.remove(client_socket)

def main():
    global clients

    # Create a list to store connected client sockets
    clients = []

    while True:
        try:
            client_socket, address = server_socket.accept()
            print(f"New connection from {address}")

            # Store the client socket for later use
            clients.append(client_socket)

            # Handle incoming messages from this client
            threading.Thread(target=handle_client, args=(client_socket,)).start()
        except Exception as e:
            print(f"Error accepting new connection: {e}")
            continue

if __name__ == "__main__":
    main()

import html.parser

class MyHTMLParser(html.parser.HTMLParser):
    def __init__(self):
        super().__init__()
        self.data = ''
        self.elements = []

    def handle_data(self, data):
        self.data += data + ' '

    def handle_starttag(self, tag, attrs):
        element = {
            'tag': tag,
            'attributes': list(attrs),
            'data': self.data
        }
        self.elements.append(element)
        self.data = ''

    def handle_endtag(self, tag):
        if self.data:
            element = {
                'tag': tag,
                'data': self.data
            }
            self.elements.append(element)
            self.data = ''

parser = MyHTMLParser()
parser.feed('<p>Hello World!</p><span>This is a test</span>')
for element in parser.elements:
    print(f"Element: {element['tag']}, Attributes: {element['attributes']}, Data: {element['data']}")

# Define a class with attributes that have different levels of access
class MyClass(object):
    def __init__(self, name, age):
        self.name = name
        self.age = age

    @property
    def name(self):
        return self._name

    @name.setter
    def name(self, value):
        if value is not None:
            self._name = value
        else:
            raise ValueError("Name cannot be None")

    @property
    def age(self):
        return self._age

    @age.setter
    def age(self, value):
        if value is not None:
            self._age = value
        else:
            raise ValueError("Age cannot be None")

# Create an instance of the class with limited access to attributes
my_obj = MyClass("John Doe", 30)

# Try to access the name attribute with normal access
print(my_obj.name) # Output: John Doe

# Try to set the name attribute with normal assignment
my_obj.name = "Jane Doe" # Output: Jane Doe

# Try to access the age attribute with normal access
print(my_obj.age) # Output: 30

# Try to set the age attribute with normal assignment
my_obj.age = 31 # Output: 31

# Try to access the name attribute with limited access
try:
    print(my_obj.name) # Output: AttributeError: 'MyClass' object has no attribute 'name'
except AttributeError as e:
    print("Access denied")

# Try to set the name attribute with limited access
try:
    my_obj.name = "Jane Doe" # Output: AttributeError: 'MyClass' object has no attribute 'name'
except AttributeError as e:
    print("Access denied")

# Try to access the age attribute with limited access
try:
    print(my_obj.age) # Output: 31
except AttributeError as e:
    print("Access denied")

# Try to set the age attribute with limited access
try:
    my_obj.age = 32 # Output: AttributeError: 'MyClass' object has no attribute 'age'
except AttributeError as e:
    print("Access denied")

import re

def is_phone_number(s):
    pattern = r'^(\d{3}-\d{3}-\d{4})$|^\d{10}$'
    return bool(re.match(pattern, s))

class DeploymentHandler:
    def __init__(self):
        self.versions = ["v1", "v2", "v3"]  # List of available versions
        self.current_version = None

    def deploy(self, version):
        if version in self.versions:
            print(f"Deploying {version}...")
            self.current_version = version
            print(f"{version} deployed successfully.")
        else:
            print("Invalid version. Please choose from the available versions.")

    def rollback(self):
        if self.current_version is None or self.versions.index(self.current_version) == 0:
            print("No previous version to roll back to.")
        else:
            previous_version = self.versions[self.versions.index(self.current_version) - 1]
            print(f"Rolling back from {self.current_version} to {previous_version}...")
            self.current_version = previous_version
            print(f"Successfully rolled back to {previous_version}.")

# Example usage:
deployment_handler = DeploymentHandler()
deployment_handler.deploy("v1")  # Deploy v1
deployment_handler.deploy("v2")  # Deploy v2 (upgrade from v1)
deployment_handler.rollback()    # Roll back to previous version (from v2 to v1)

