class ReportCache:
    def __init__(self):
        self.cache = {}

    def get_report(self, param1, param2):
        # Check if this set of parameters has been used before to generate a report
        cache_key = (param1, param2)
        if cache_key in self.cache:
            print("Retrieving from cache...")
            return self.cache[cache_key]
        else:
            # If not, generate the report and store it in the cache for future use
            print("Generating new report...")
            result = self._generate_report(param1, param2)
            self.cache[cache_key] = result
            return result

    def _generate_report(self, param1, param2):
        # This would be the function to generate a new report using given parameters
        # For now, let's assume it returns a string representation of the report for simplicity
        return f"Report with params: {param1}, {param2}"

import stripe

stripe.init()

def calculate_price(price_id):
    price = stripe.price.get(price_id)
    return price['cents']

def process_payment(customer_id, method, amount_cents):
    customer = stripe.customer.create()
    card = customer.card_details[0]

    # Calculate total with tax (assuming 28% tax rate)
    if amount_cents < 1:
        return {"error": "Invalid payment amount"}

    price_data = stripe.price.get(card['card_id'])
    price_total = price_data['total']
    tax_amount = price_total * 0.28
    total_with_tax = price_total + tax_amount

    # Convert to cents and round appropriately
    charge_cents = int(round(total_with_tax))

    if charge_cents < 1:
        return {"error": "Invalid payment amount"}

    # Check for existing session before creating a new one
    if not stripe.session.id_exists(customer_id, method):
        session = stripe.session.create(
            customer_id=customer_id,
            payment_method=method,
            amount=charge_cents
        )

        charge = session.charges.first()

        return {
            'session': session.id,
            'status': charge.status,
            'metadata': {'price_id': price_id}
        }
    else:
        return {"error": "Payment already started"}

# Example usage with actual values
amount_cents = 1000  # Replace with the desired payment amount in cents
response = process_payment(customer_id, method, amount_cents)
print(response)

def validate_tenant_config(config):
    # List of required keys
    required_keys = ['name', 'domain', 'max_users', 'storage_quota']

    # Check if all required keys exist in the config
    for key in required_keys:
        if key not in config:
            return f"Missing required configuration key: {key}"

    # Additional validation logic can be added here based on your needs
    # For example, checking that max_users is a positive integer and storage_quota is a non-negative float
    if not isinstance(config['max_users'], int) or config['max_users'] <= 0:
        return "Invalid value for 'max_users'. Expected a positive integer."

    if not isinstance(config['storage_quota'], (int, float)) or config['storage_quota'] < 0:
        return "Invalid value for 'storage_quota'. Expected a non-negative number."

    # If all checks pass, return None to indicate that the config is valid
    return None

