# Payment controller
class PaymentController:
    @staticmethod
    def encrypt_data(salt, username, password, data):
        if not username or not salt or not password:
            return None

        salt = salt.encode('utf-8')
        username = username.encode('utf-8')
        password = password.encode('utf-8')

        hash = bcrypt.hash(salt, password)
        encrypted = bcrypt.hash(salt, data)

        return {
            'salt': salt,
            'username': username,
            'password': hash,
            'encrypted_data': encrypted
        }

    @staticmethod
    def decrypt_data(salt, username, password, encrypted):
        if not username or not salt or not password:
            return None

        salt = bcrypt.checksalt2(salt)
        if not salt:
            return None

        hash = bcrypt.checkpw(password.encode('utf-8'), salt)
        if not hash:
            return None

        decrypted = decrypt(encrypted, salt)
        return decrypted

    def save(self):
        db.session.add(self)
        db.session.commit()

# Create routes
bp = Blueprint('main', __name__)

@bp.route('/admin/recurrent-payment', methods=['POST'])
@login_required
@admin_required
def initiate_recurrent_payment():
    if 'payment' not in session or 'encrypted_session_id' not in session:
        flash('Payment information not provided')
        return redirect(url_for('main.main'))

    encrypted_data = {
        'card_number': session['payment'].card_number,
        'card_type': session['payment'].card_type,
        'expiry_date': str(session['payment'].expiry_date),
        'amount': session['payment'].amount
    }

    if not encrypt_data:
        flash('Error validating payment information')
        return redirect(url_for('main.main'))

    decrypted = decrypt_data()

    # Verify the payment data and store it in history
    Session = db.sessionmaker()
    session = Session()
    try:
        payment = session.query(Payment).filter_by(id=session['payment']).first()
        if not decrypted:
            flash('Invalid payment information')
        else:
            for field, value in decrypted.items():
                setattr(payment, field, value)
            history = PaymentHistory(
                id=db.uuid4(),
                payment_id=payment.id,
                **decrypted
            )
            db.session.add(history)
            db.session.commit()
    finally:
        session.remove()

    return redirect(url_for('main.main'))

