import re

def validate_tenant_config(config):
    """
    Validates a tenant configuration.

    Args:
        config (dict): The tenant configuration.

    Returns:
        bool: True if the configuration is valid, False otherwise.
    """

    # Check if config is None
    if config is None:
        return False

    # Define regular expression patterns for validation
    pattern1 = r"^[a-zA-Z0-9_-]+$"
    pattern2 = r"^[\d\.]+$"

    # Validate tenant ID
    if not re.match(pattern1, config.get("tenant_id")):
        return False

    # Validate tenant details
    if "tenant_details" in config:
        if not isinstance(config["tenant_details"], dict):
            return False

        # Check for required keys
        required_keys = ["name", "description"]
        if not all(key in config["tenant_details"] for key in required_keys):
            return False

        # Validate name and description
        if not re.match(pattern2, config["tenant_details"]["name"]):
            return False
        if not re.match(pattern2, config["tenant_details"]["description"]):
            return False

    # Validate storage configuration
    if "storage" in config:
        if not isinstance(config["storage"], dict):
            return False

        # Check for required keys
        required_keys = ["type", "size"]
        if not all(key in config["storage"] for key in required_keys):
            return False

        # Validate type and size
        if config["storage"]["type"] not in ["local", "cloud"]:
            return False
        if not re.match(pattern2, str(config["storage"]["size"])):
            return False

    # Check for other configuration options
    if "other_config" in config:
        if not isinstance(config["other_config"], dict):
            return False

        # Check for required keys
        required_keys = ["key1", "key2"]
        if not all(key in config["other_config"] for key in required_keys):
            return False

        # Validate values
        if not re.match(pattern2, str(config["other_config"]["key1"])):
            return False
        if not re.match(pattern2, str(config["other_config"]["key2"])):
            return False

    # If all checks pass, the configuration is valid
    return True

# Example usage:
config = {
    "tenant_id": "tenant-123",
    "tenant_details": {
        "name": "Example Tenant",
        "description": "This is an example tenant."
    },
