import os
import fcntl
import sys

def already_running(pidfile):
    try:
        with open(pidfile, 'r') as file:
            pid = int(file.read().strip())
        os.kill(pid, 0) # Check if process is running
    except (IOError, OSError):
        return False
    except SystemExit:
        pass
    else: # No error means the program is still running
        print('Another instance of this job is already running with PID %d' % pid, file=sys.stderr)
        return True
    return False

def create_pidfile(pidfile):
    try:
        with open(pidfile, 'w') as file:
            print(os.getpid(), file=file)
    except (IOError, OSError):
        pass

def delete_pidfile(pidfile):
    try:
        os.remove(pidfile)
    except FileNotFoundError:
        pass

if __name__ == "__main__":
    pidfile = '/tmp/myjob.pid' # Use a unique name for each job

    if already_running(pidfile):
        sys.exit()

    create_pidfile(pidfile)

    try:
        # Your cron job code here...
        pass
    finally:
        delete_pidfile(pidfile)

from flask import Flask, request, make_response
from functools import wraps

app = Flask(__name__)

def check_auth(username, password):
    """This function is called to check if a username /
    password combination is valid.
    """
    return username == 'admin' and password == 'secret'

def authenticate():
    """Sends a 401 response that enables basic auth"""
    return make_response(
        'Could not verify your login!',
        401,
        {'WWW-Authenticate': 'Basic realm="Login required"'}
    )

def requires_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth = request.authorization
        if not auth or not check_auth(auth.username, auth.password):
            return authenticate()
        return f(*args, **kwargs)
    return decorated

@app.route('/')
@requires_auth
def secret_page():
    return "You're logged in!"

if __name__ == '__main__':
    app.run(debug=True)

from flask import Flask, request
import jwt
from functools import wraps

app = Flask(__name__)
app.config['SECRET_KEY'] = 'YOUR_SECRET_KEY'

def token_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization')

        if not token:
            return {'message': 'Token is missing'}, 403

        try:
            data = jwt.decode(token, app.config['SECRET_KEY'])
        except:
            return {'message': 'Invalid Token'}, 403

        return f(*args, **kwargs)

    return decorated

