import requests
from datetime import datetime
import json
from statistics import mean
import time

class WebhookMonitor:
    def __init__(self, url, headers=None):
        self.url = url
        self.headers = headers if headers is not None else {}

    def send_request(self, payload):
        response = requests.post(self.url, headers=self.headers, data=json.dumps(payload))

        if response.status_code == 200:
            return True, response.json()
        else:
            return False, response.text

    def monitor_performance(self, num_requests=100, interval=60):
        total_successes = 0
        total_failures = 0

        for _ in range(num_requests):
            payload = {'key': 'value'}
            success, result = self.send_request(payload)
            if success:
                total_successes += 1
            else:
                total_failures += 1

            print(f'Requests: {total_successes + total_failures}, Successes: {total_successes}, Failures: {total_failures}')
            time.sleep(interval)

        average_response_time = mean([self.get_response_time() for _ in range(num_requests)])
        return average_response_time

    def get_response_time(self):
        start_time = datetime.now()
        response = self.send_request(None)
        end_time = datetime.now()

        if isinstance(response, dict):
            response_time = (end_time - start_time).total_seconds()
        else:
            response_time = float(response.split(' ')[0])

        return response_time


# Example usage
url = 'https://example.com/webhook'
headers = {'Content-Type': 'application/json'}
monitor = WebhookMonitor(url, headers)

average_response_time = monitor.monitor_performance(num_requests=100, interval=60)
print(f'Average Response Time: {average_response_time:.2f} seconds')

import os

def check_pip_version():
    try:
        pip_version = int(input("Enter your pip version: "))
        print("Current pip version is:", pip_version)
        return True
    except ValueError:
        print("Please enter a valid number.")
        return False

def list_installed_packages():
    try:
        os.system("pip list | grep -c '^\w+==\w+\.\w+'")
        print("Package list:")
        os.system("pip list")
        return True
    except Exception as e:
        print(f"Error listing packages: {e}")
        return False

def list active_packages():
    try:
        os.system("pip freeze | grep -c '^\w+==\w+\.\w+'")
        print("Packages in use:")
        os.system("pip freeze")
        return True
    except Exception as e:
        print(f"Error listing active packages: {e}")
        return False

def check_critical_packages():
    try:
        missing = []
        with open('critical_packages.txt', 'r') as f:
            for package in f:
                if package.strip() in os.listdir('pip'):
                    continue
                else:
                    missing.append(package.strip())
        print("Critical packages missing:", '\n'.join(missing))
        return True
    except FileNotFoundError:
        print("File not found. Please check the path to critical_packages.txt.")
        return False

def check_python_version():
    try:
        python_version = int(input("Enter your Python version: "))
        current_version = importlib.util/module_name()
        if current_version < 3.8:
            print("Python version is outdated. Consider upgrading.")
            return True
        return False
    except Exception as e:
        print(f"Error checking Python version: {e}")
        return False

if __name__ == "__main__":
    pip_ok = check_pip_version()
    if not pip_ok:
        exit(1)

    list_installed_packages()
    list_active_packages()

    critical_ok = check_critical_packages()
    if not critical_ok:
        exit(1)

    python_ok = check_python_version()
    if not python_ok:
        exit(1)

import os

def child():
    print('\nThis is the child process with id:', os.getpid())
    # Child process continues here.
    os._exit(0)  # Note that this exits the entire program, not just the current process.


def parent():
    while True:
        newref = os.fork()

        if newref == 0:
            child()

        else:
            pid, status = os.wait()
            print('Parent is about to exit')

parent()

