class Product:
    def __init__(self, name, price):
        self.name = name
        self._price = price
        self.history = []

    @property
    def price(self):
        return self._price

    @price.setter
    def price(self, new_price, user=None):
        if not self.is_valid_price(new_price):
            raise ValueError("Invalid price")
        if not self.is_authorized_user(user):
            raise PermissionError("Unauthorized user")
        old_price = self._price
        self._price = new_price
        self.history.append((old_price, new_price, user))
        self.check_for_suspicious_change()

    @staticmethod
    def is_valid_price(price):
        # Add your validation logic here
        return price > 0

    @staticmethod
    def is_authorized_user(user):
        # Add your authorization logic here
        return user in ["admin", "manager"]

    def check_for_suspicious_change(self):
        if self.history:
            last_price, _, _ = self.history[-1]
            if abs(last_price - self._price) / last_price > 0.05:
                print("ALERT: Suspicious price change")

