import time

class RateLimiter:
    def __init__(self, max_per_second):
        self.max_per_second = max_per_second
        self.last_call = 0

    def rate_limit(func):
        def wrapper(*args, **kwargs):
            if time.time() - wrapper.limiter.last_call < (1 / wrapper.limiter.max_per_second):
                print("Rate limit exceeded. Please wait.")
                return None
            else:
                wrapper.limiter.last_call = time.time()
                return func(*args, **kwargs)
        wrapper.limiter = self
        return wrapper

