import time
from functools import wraps
from flask import Flask, request

app = Flask(__name__)

# Define a decorator for rate limiting
def limit(max_calls, period):
    def decorator(func):
        calls = {}
        @wraps(func)
        def wrapper(*args, **kwargs):
            now = time.time()
            if func.__name__ not in calls:
                calls[func.__name__] = 0
            calls[func.__name__] += 1
            rate_limit = calls[func.__name__] / (now - calls[func.__name__][-1])
            if rate_limit > max_calls:
                return "Rate limit exceeded", 429
            calls[func.__name__].append(now)
            return func(*args, **kwargs)
        return wrapper
    return decorator

# Example usage with Flask API
