import hashlib

def calculate_checksum(file_path):
    """Calculate and return the SHA-256 checksum of a file."""
    sha256 = hashlib.sha256()
    with open(file_path, 'rb') as f:
        while True:
            data = f.read(4096)
            if not data:
                break
            sha256.update(data)
    return sha256.hexdigest()

def validate_checksum(file_path, expected_checksum):
    """Validate the checksum of a file against an expected value."""
    calculated_checksum = calculate_checksum(file_path)
    if calculated_checksum == expected_checksum:
        print('Checksum is valid.')
    else:
        print('Checksum is invalid.')

