from xml.etree import ElementTree as ET

def xml_to_dict(xml_str):
    root = ET.fromstring(xml_str)
    result = {}

    def traverse(node):
        nonlocal result  # To allow modifying 'result' from nested function
        current_tag = node.tag
        if current_tag in result:
            pass
        else:
            result[current_tag] = {}

        for child in node:
            if child.get('class') is not None:
                value = child.text.strip() or ''
                # If the class exists, add to the dictionary under its key
                if 'class' in child.attrib and child.get('class'):
                    result[child.get('class')] = {
                        child.tag: {child.text.strip() or ''}
                    }
            else:
                tag = child.tag
                text = child.text.strip() or ''
                # Add to the current level's dictionary under the tag name
                if tag in result:
                    if isinstance(result[tag], dict):
                        result[tag][child.tag] = text
                    else:
                        result[tag] = {child.tag: text}
                else:
                    result[tag] = {child.tag: text}

    traverse(root)
    return result

