class Product(object):
    def __init__(self, id, price, timestamp=None):
        self.id = id
        self._price = price
        if timestamp is None:
            self.timestamp = time.time()
        else:
            self.timestamp = timestamp

    @property
    def price(self):
        return self._price

    @price.setter
    def price(self, value):
        if value < self._price:  # prevent decreasing price
            raise ValueError("Price cannot be less than the current price")
        interval = time.time() - self.timestamp
        if interval < 3600:  # allow a maximum of one price change per hour
            raise ValueError(f"You can only change price once every {interval} seconds.")
        self._price = value
        self.timestamp = time.time()

