        conn = sqlite3.connect(':memory:')  # creates in-memory database
        print(f'Successfully Connected, sqlite version {sqlite3.version}')
    except Error as e:
        print(e)

    if conn:
        return conn

def close_connection(conn):
    # Closes connection to the database
    conn.close()

def create_table(conn):
    try:
        sql = """CREATE TABLE IF NOT EXISTS offline_data (
                    id integer PRIMARY KEY,
                    name text NOT NULL,
                    data blob NOT NULL
                );"""

        cur = conn.cursor()
        cur.execute(sql)
        print('Table created successfully')
    except Error as e:
        print(e)

def insert_data(conn, name, data):
    try:
        sql = """INSERT INTO offline_data (name, data) VALUES (?, ?);"""

        cur = conn.cursor()
        cur.execute(sql, (name, data))
        conn.commit()
        print('Data inserted successfully')
    except Error as e:
        print(e)

def retrieve_data(conn):
    try:
        sql = """SELECT * FROM offline_data;"""

        cur = conn.cursor()
        cur.execute(sql)

        rows = cur.fetchall()

