import json

def deserialize_network_data(data):
    try:
        # Attempt to parse the incoming data as JSON
        obj = json.loads(data)

        # Check for any remaining bytes that need decoding
        if isinstance(obj, dict) and '__class__' in obj:
            obj['__class__'] = obj['__class__'].decode('utf-8')
        elif isinstance(obj, list):
            for item in obj:
                if '__class__' in item:
                    item['__class__'] = item['__class__'].decode('utf-8')

        return obj
    except json.JSONDecodeError as e:
        # Return error message if deserialization fails
        return f"Error: {str(e)}"

