def process_messages(messages_dict, fi_dict):
    combined = {**messages_dict, **fi_dict}

    params = [
        ('title', 'title'),
        ('description', 'description'),
        ('source', 'source')
    ]

    translated = []
    for key, default_key in params:
        value = combined.get(key)
        if not value:
            value = messages_dict.get(default_key)
        translated.append(value)

    main_message = combined.get('content', '')
    translated.append(main_message)

    return '\n'.join(map(str, translated))

