# Dummy user database for this example, use a real one in production
users = {
    "user1": {"password": "hashed_password1", "api_key": "unique_api_key1"},
    # Add more users as needed
}

def authenticate(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization')
        if not token:
            return jsonify({'message': 'Missing token'}), 403
        try:
            data = jwt.decode(token, app.config['SECRET_KEY'], algorithms=["HS256"])
            current_user = users[data['username']]
        except:
            return jsonify({'message': 'Invalid token'}), 403
        return f(current_user, *args, **kwargs)
    return decorated

@app.route('/login', methods=['POST'])
def login():
    auth = request.get_json()

    if not auth or not auth.get('username') or not auth.get('password'):
        return jsonify({'message': 'Could not verify'}), 401

    user = users[auth['username']]
    if user and user['password'] == auth['password']:  # In production, you should use a secure hashing library to compare the password.
        token = jwt.encode({'username': auth['username'], 'api_key': user['api_key']}, app.config['SECRET_KEY'])
        return jsonify({'token': token})
    else:
        return jsonify({'message': 'Could not verify'}), 401

