@authenticate
def api_predict(current_user):
    data = request.get_json()
    if not data:
        return jsonify({'message': 'No input data provided'}), 400

    # Decrypt the API key using your secret key
    f = Fernet(app.config['SECRET_KEY'])
    decrypted_api_key = f.decrypt(current_user['api_key']).decode()

    # Verify the decrypted API key (compare it with a stored or generated one)
    if decrypted_api_key != "correct_api_key":  # Replace "correct_api_key" with the actual API key in production.
        return jsonify({'message': 'Invalid API key'}), 403

    result = predict(data)
    return jsonify({'prediction': result})

