import socket
import threading

# List to hold all client sockets
clients = []

def handle_client(client):
    while True:
        try:
            message = client.recv(1024)  # Receive messages from clients
            if not message:  # If the connection is closed, break the loop
                break
            broadcast(message)  # Broadcast the received message to all clients
        except Exception as e:
            print(f"Error: {e}")
            break
    client.close()  # Close the connection when the while loop breaks

def broadcast(message):
    for client in clients:  # Send the message to each client socket
        try:
            client.send(message)
        except Exception as e:
            print(f"Error: {e}")

def start_server():
    server = socket.socket(socket.AF_INET, socket.SOCK_STREAM)  # Create a TCP/IP socket
    server.bind(('127.0.0.1', 12345))  # Bind the socket to an address and port
    server.listen()  # Listen for incoming connections

    while True:
        client, addr = server.accept()  # Accept a connection from a client
        clients.append(client)  # Add the new client socket to the list of client sockets
        print(f"Connection from {addr} has been established!")

        thread = threading.Thread(target=handle_client, args=(client,))  # Start a new thread for each connection
        thread.start()  # Start the new thread

if __name__ == '__main__':
    start_server()

