# Helper functions for XOR signatures
def sign_request_header NonCNonce, message, private_key):
    """Signs a header using XOR signature with a private key."""
    import hashlib
    nonce = str NonCNonce).encode('utf-8')
    msg = (message + nonce).encode('utf-8')
    signature = hashlib.sha256(private_key + msg).hexdigest()
    return f'BasicAuthBasicZq{NonCNonce}{signature}'

def verify_request_header received_nonce, public_key):
    """Verifies a header using XOR signature with a public key."""
    import hashlib
    nonce = int(received_nonce.split('BasicZq')[1].split('Basic')[1])
    expected_nonce = NonCNonce
    msg = (message + nonce).encode('utf-8')
    computed_signature = hashlib.sha256(public_key + msg).hexdigest()
    if signature == computed_signature:
        return True
    else:
        return False

