import boto3

# Create a low-level service client
ec2 = boto3.client('ec2', region_name="us-west-2")

def scale_in(instance_id, count):
    # Reduce desired capacity to the current number of instances minus `count`
    response = ec2.describe_instances()
    for reservation in response["Reservations"]:
        for instance in reservation["Instances"]:
            if instance['InstanceId'] == instance_id:
                current_capacity = len(reservation["Instances"])
                desired_capacity = max(current_capacity - count, 0)

    autoscaling = boto3.client('autoscaling')
    response = autoscaling.set_desired_capacity(AutoScalingGroupName='my-auto-scaling-group', DesiredCapacity=desired_capacity)

def scale_out(instance_id, count):
    # Increase desired capacity to the current number of instances plus `count`
    response = ec2.describe_instances()
    for reservation in response["Reservations"]:
        for instance in reservation["Instances"]:
            if instance['InstanceId'] == instance_id:
                current_capacity = len(reservation["Instances"])
                desired_capacity = max(current_capacity + count, 0)

    autoscaling = boto3.client('autoscaling')
    response = autoscaling.set_desired_capacity(AutoScalingGroupName='my-auto-scaling-group', DesiredCapacity=desired_capacity)

