import os
import shutil

def delete_file(filepath):
    """Securely deletes a file using the shred method."""
    with open(filepath, "ba+") as file:
        length = file.tell()
        file.seek(0)
        # Overwrite the file with zeros
        file.write(os.urandom(length))
        file.close()

    try:
        os.remove(filepath)
    except OSError as e:
        print("Error: %s : %s" % (filepath, e.strerror))

def delete_processed_messages(directory):
    """Deletes all files in a directory representing processed messages."""
    for filename in os.listdir(directory):
        filepath = os.path.join(directory, filename)
        try:
            # Check if the path is a file (not a directory)
            if os.path.isfile(filepath):
                delete_file(filepath)
        except Exception as e:
            print("Failed to delete %s. Reason: %s" % (filepath, e))

