import threading
import time

def worker(name):
    while True:
        print(f"Thread {name}: working...")
        time.sleep(1)

threads = []
for i in range(3):
    t = threading.Thread(target=worker, args=(i,))
    threads.append(t)
    t.start()

# Monitor threads and terminate those that have hung for more than 5 seconds
timeout = 5
for t in threads:
    start_time = time.time()
    while t.is_alive():
        if time.time() - start_time > timeout:
            print(f"Terminating hung thread: {t.name}")
            t.terminate()

