@app.route('/upload', methods=['POST'])
def upload_file():
    if request.method == 'POST':
        # check if the post request has the file part
        if 'file' not in request.files:
            return "No file part"
        file = request.files['file']
        # If user does not select file, browser also
        # submit an empty part without filename
        if file.filename == '':
            return "No selected file"
        if file and allowed_file(file.filename):
            filename = secure_filename(file.filename)
            file.save(os.path.join(UPLOAD_FOLDER, filename))
            return "File uploaded successfully"
    else:
        return "Method not allowed"

# List of records, each represented as a dictionary
records = []

def add_record():
    new_record = {
        'id': len(records) + 1,
        'name': input("Enter the name: ").strip(),
        'email': input("Enter the email: ").strip(),
        'phone': input("Enter the phone number: ").strip(),
        'address': input("Enter the address: ").strip()
    }
    records.append(new_record)
    print(f"Added new record: {new_record}")

def search_records(search_term):
    if not search_term:
        return records.copy()
    matches = []
    for record in records:
        if (search_term.lower() == record['name'].lower() or
            search_term.lower() == record['email'].lower()):
            matches.append(record)
    print(f"Records matching '{search_term}':")
    return matches

def delete_records(matches):
    global records
    if not matches:
        print("No matches found.")
        return
    decision = input("Do you want to delete these records? (y/n): ").strip().lower()
    if decision == 'y':
        for record in matches:
            confirm = input(f"Are you sure you want to delete {record['name']} ({record['id']})? ").strip().lower()
            if confirm == 'y':
                print(f"Deleting {record['id']}...")
                records.remove(record)
        print("Deletion process completed.")
    else:
        print("Deletion canceled.")

