import urllib.parse as u

def log_query(query=None, variables=None):
    if query:
        query = u.quote_plus(query)
    else:
        query = ''

    var_pairs = []
    if isinstance(variables, dict):
        for key, value in variables.items():
            var_pairs.append(f"{u.quote_plus(key)}={u.quote_plus(value)}")
    elif isinstance(variables, (tuple, list)) and len(variables) == 2:
        key, value = variables
        var_pairs.append(f"{u.quote_plus(key)}={u.quote_plus(value)}")

    if var_pairs:
        query += f" ?{ '&'.join(var_pairs) }"
    return query

from flask import Flask, request, jsonify
from pyjwt import JWT
import os

app = Flask(__name__)
app.config["SECRET_KEY"] = "my_secret_key"

tenants = {
    "tenant1": {"admin": "admin", "users": ["user1", "user2"]},
    "tenant2": {"admin": "admin", "users": ["user3", "user4"]}
}

@app.route("/login")
def login():
    username = request.args.get("username")
    password = request.args.get("password")

    if not username or not password:
        return jsonify({"error": "Username and password are required."}), 401

    tenant = next((t for t in tenants if t["admin"] == username), None)
    if not tenant:
        return jsonify({"error": f"Invalid username or password."}), 401

    token = JWT.encode({"tenant_id": tenant["id"], "username": username}, app.config["SECRET_KEY"])

    return jsonify({"token": token})

@app.route("/protected")
def protected():
    token = request.headers.get("Authorization")

    if not token:
        return jsonify({"error": "No authentication provided."}), 401

    try:
        decoded_token = JWT.decode(token, app.config["SECRET_KEY"])
    except Exception as e:
        print(e)
        return jsonify({"error": "Invalid token."}), 401

    if decoded_token["tenant_id"] not in tenants:
        return jsonify({"error": f"Invalid tenant ID."}), 403

    return jsonify({"message": f"Welcome {decoded_token['username']} from tenant {decoded_token['tenant_id']}"})

