import time

class RateLimiter:
    def __init__(self, max_requests, per_seconds):
        self.max_requests = max_requests
        self.per_seconds = per_seconds
        self.request_timestamps = []

    def limit(self):
        current_time = time.time()
        # Remove timestamps that are older than the specified period
        self.request_timestamps = [t for t in self.request_timestamps if (current_time - t) < self.per_seconds]

        if len(self.request_timestamps) >= self.max_requests:
            # If we've reached the limit, calculate the time to wait before making a new request
            elapsed = current_time - self.request_timestamps[0]
            return max(0, self.per_seconds - elapsed)
        else:
            # Add the timestamp of this request and allow it
            self.request_timestamps.append(current_time)
            return 0

import re

def validate_email(email):
    if not re.match(r"[^@]+@[^@]+\.[^@]+", email):
        return False
    return True

def validate_password(password):
    # minimum 8 characters, at least one uppercase letter, one lowercase letter and one number
    if (len(password)<8 or not re.search("[a-z]", password) or not re.search("[A-Z]", password) or not re.search("[0-9]", password)):
        return False
    return True

def validate_form(email, password):
    if not validate_email(email):
        print("Invalid email address")
        return False

    if not validate_password(password):
        print("Invalid password. It should contain minimum 8 characters, at least one uppercase letter, one lowercase letter and one number.")
        return False

    # If both validations pass
    print("Valid email and password")
    return True

