import sys

def safe_input():
    while True:
        try:
            data = sys.stdin.read(1)  # Read one character at a time to prevent overflow
            if not data:  # End of stream
                break
            yield data
        except KeyboardInterrupt:
            break
        except UnicodeDecodeError:
            raise Exception("Invalid input encoding")
    return ''

