import functools
from urllib.parse import quote_plus
from datetime import datetime

def optimize_search(search_string, search_terms, field_type):
    """
    Perform an optimized and secure search operation on CMS data.

    Args:
        search_string (str): The full string to be searched.
        search_terms (tuple): Variable arguments containing the terms to search for. Can include strings, numbers, or dates.
        field_type (str): The type of field being searched in, e.g., 'text', 'number', 'date'.

    Returns:
        list: List of matching CMS data entries.

    Raises:
        ValueError: If any parameter is invalid based on its type and field type.
    """

    # Sanitize input values
    def sanitize_value(value):
        if isinstance(value, str):
            return quote_plus(escape_html(value))
        elif isinstance(value, (int, float)):
            return value  # Numbers can be safely compared after conversion to string
        else:
            raise ValueError(f"Invalid type for {field_type}: {type(value)}")

    def escape_html(s):
        if not isinstance(s, str):
            return s
        return f"<strong>{s}</strong>" if field_type in ['text', 'number'] else s

    # Convert search_terms to their appropriate types and sanitize
    sanitized_terms = []
    for term in search_terms:
        try:
            if field_type == 'text':
                sanitized_term = escape_html(sanitize_value(term))
            elif field_type == 'number':
                sanitized_term = str(sanitize_value(int(term) if isinstance(term, (str, float)) else term))
            elif field_type == 'date':
                sanitized_term = sanitize_value(datetime.fromisoformat(str(term))) if isinstance(term, str) else None
            else:
                sanitized_term = None  # Default for other types

            if sanitized_term is not None:
                sanitized_terms.append(sanitized_term)
        except ValueError as e:
            raise ValueError(f"Invalid value for {field_type}: {term} - {str(e)}")

    # Optimize search by using tuples instead of multiple string lookups
    optimized_search = tuple(map(lambda t: (t, True), sanitized_terms))

    @functools.lru_cache(maxsize=None)
    def optimize_search_function(params):
        for key in params:
            if not hasattr(key, 'decode'):
                key = str(key).strip()
            value = str(params[key]).strip()

            # Check each parameter against its optimized search term
            match_found = False
            for sanitized_param, param_type in optimized_search:
                try:
                    if param_type == 'text':
                        if sanitized_param.lower() in value.lower():
                            match_found = True
                            break
                    elif param_type == 'number':
                        num = float(value) if isinstance(param_type, int) else int(value)
                        if abs(num - sanitized_param) < 0.001:  # Tolerance for floating point comparison
                            match_found = True
                            break
                    elif param_type == 'date':
                        from datetime import datetime as dt
                        target_dt = dt.fromisoformat(str(sanitized_param)) + timedelta(days=1)
                        query_dt = dt.fromisoformat(value) if isinstance(value, str) else (target_dt - timedelta(days=1))
                        if abs((query_dt - target_dt).total_seconds()) < 3600 * 24:  # Within one day
                            match_found = True
                            break
                except Exception:
                    continue

            if match_found:
                return True
        return False

    return [entry for entry in CMS_entries if optimize_search_function(entry)]

def escape_html(s):
    """
    Escape HTML characters for safe inclusion in SQL queries.
    """
    if not isinstance(s, str):
        return s
    return f"<strong>{s}</strong>"

