import time
from collections import deque

class SlidingTimeWindow:
    def __init__(self, interval=60):  # default to one minute (60 seconds)
        self.interval = interval
        self.actions = deque()

    def add_action(self, current_timestamp):
        # Add the action at the current time
        self.actions.append(current_timestamp)

        # Remove actions older than the specified interval
        while self.actions[0] < (current_timestamp - self.interval):
            self.actions.popleft()

    def get_actions(self, current_timestamp):
        # Update the list of actions to remove those outside the time window
        self.add_action(current_timestamp)

        # Return the number of actions in the time window
        return len(self.actions)

