def multi_filter_search(dataset, *filters):
    def equals(a, b):
        return a is None and b is None or a == b

    def contains(a, b):
        if a is None:
            return False
        if isinstance(b, (int, float)):
            return False  # Comparing with numbers doesn't make sense for most strings
        return a.lower().startswith(b.lower())

    def is_between(a, lower, upper):
        return not (a is None or lower > a > upper) and (lower <= a <= upper)

    try:
        for item in dataset:
            if all(
                equals(item.get(key), value) 
                or contains(item.get(key), value) 
                or is_between(item.get(key), start, end)
                for key, (value, start, end) in zip(keys, filter_values, filter_ranges)
            ):
                return item
    except Exception as e:
        print(f"Error: {e}")

    return None

