import pickle
from berryman import Serializer

class BerrymanSerializer(Serializer):
    def serialize(self, obj):
        if isinstance(obj, (int, float, bool, str, type(None))):
            return pickle.dumps(obj)
        else:
            return None

    def deserialize(self, data):
        result = {}
        for key, value in data.items():
            if isinstance(value, (int, float, bool, str)):
                result[key] = value
            elif isinstance(value, bytes):
                try:
                    obj = pickle.loads(value)
                except:
                    obj = None
                else:
                    result[key] = obj
            else:
                # For other non-pickle types, return as is or handle accordingly
                pass  # Assuming they are handled elsewhere or treated as errors
        return result

# Usage example:

def my_function(obj):
    serialized = BerrymanSerializer.serialize(obj)
    print(f"Serialized: {serialized}")

    deserialized = BerrymanSerializer.deserialize(serialized)
    print(f"Deserialized: {deserialized}")

