import re
from datetime import datetime

class DataNormalizer:
    def __init__(self):
        pass  # Initialization is minimal since the normalization functions are static

    @staticmethod
    def normalize_date(value):
        date_patterns = [
            ('%Y-%m-%d', lambda m: f"{m.group(0)}"""),
            ('%Y-%m-%d %H:%M:%S', lambda m: f"{m.group(0)}"),
            ('%Y-%m-%d %H:%M', lambda m: f"{m.group(0)}"),
            ('%Y-%m-%d %H:%M:%S.%f', lambda m: f"{m.group(0)}")
        ]

        for pattern, converter in date_patterns:
            match = re.match(pattern, value)
            if match:
                return converter(match)
        return None

    @staticmethod
    def normalize_number(value):
        number_patterns = [
            (r'\d{1,3}(?:,\d{3})+', lambda m: int(m.group(0))),
            (r'\d+\.\d*', lambda m: float(m.group(0))),
            (r'[\d,]+\.\d+', lambda m: float(m.group(0).replace(',', '')) if ',' in m.group(0) else float(m.group(0)))
        ]

        for pattern, converter in number_patterns:
            match = re.match(pattern, value)
            if match:
                return converter(match)
        return None

    @staticmethod
    def normalize_currency(value):
        currency_patterns = [
            (r'(\$|£|\€) (\d+(?:,\d+)*)\.?\d*', lambda m: f"{m.group(1)} {m.group(2)}.00" if '.' in m.group(2) else f"{m.group(1)} {m.group(2)},00")
        ]

        for pattern, formatter in currency_patterns:
            match = re.match(pattern, value)
            if match:
                return f"{formatter}"
        return None

def normalize_data(data):
    normalized = {
        'dates': DataNormalizer.normalize_date(data.get('date')),
        'numbers': DataNormalizer.normalize_number(data.get('number')),
        'currency': DataNormalizer.normalize_currency(data.get('currency'))
    }

    # Additional data types can be added here
    return normalized

import os
