import asyncio

def setup_logging(filename='webhook.log'):
    log_dir = 'logs/'
    log_path = os.path.join(log_dir, filename)

    logging.basicConfig(
        level=logging.INFO,
        format='%(asctime)s - %(levelname)s - %(message)s',
        handlers=[
            logging.FileHandler(log_path),
            logging.StreamHandler()
        ]
    )

def send_random_request():
    headers = {
        'Content-Type': 'application/json',
        'X-Random-String': random.choice([str(i) for i in range(10000)])
    }
    try:
        response = requests.get(
            'http://localhost:8080',  # Replace with your server's URL
            headers=headers,
            timeout=30
        )
        response.raise_for_status()
        return {
            'status': response.status,
            'content': response.text,
            'response_time': response.elapsed.total_seconds()
        }
    except requests.exceptions.RequestException as e:
        logging.error(f"Request failed: {str(e)}")
        raise

def check_webhook_log(status_code):
    log_path = os.path.join('logs/', 'webhook.log')

    if not os.path.exists(log_path):
        return 0

    lines = open(log_path).read().split('\n')

    start_time = datetime.now() - timedelta(minutes=1)
    count = 0

    for line in reversed(lines[:50]):  # Check last 30 minutes
        timestamp, _, status, _ = line.partition(' ')
        if not status.isdigit():
            continue

        parts = status.split('/')
        current_code = int(parts[-1])

        if current_code == status_code:
            count += 1
            break

    return count

def calculate_metrics(requests):
    success_count = 0
    total_time = 0.0
    error_count = 0

    for req in requests:
        if not isinstance(req, dict) or 'status' not in req:
            continue

        status = req['status']

        try:
            if status == 200:
                success_count += 1
            elif status < 300 and status >= 200:
                total_time += req['response_time']
            elif status in [400, 500]:
                error_count += 1

        except Exception as e:
            logging.error(f"Error processing response: {str(e)}")

    return {
        'success_rate': success_count / len(requests) if len(requests) else 0,
        'average_response_time': total_time / len(requests) if len(requests) else 0,
        'error_rate': error_count / len(requests) if len(requests) else 0
    }

def monitor_webhook(server_url, endpoint, interval=60, minutes_to_check=1):
    requests = []

    def send_request():
        nonlocal requests
        try:
            response = send_random_request()
            responses.append(response)

            status = response.get('status', 'unknown')

            if status in [200, 4xx, 5xx]:
                request_data = {
                    'timestamp': datetime.now().isoformat(),
                    'status': status,
                    'content': response['content'][:100],  # Truncate content for logging
                    'response_time': response['response_time']
                }

                requests.append(request_data)

            if len(requests) > interval:
                logging.info(f"Sent {len(requests)} requests in the last minute.")
                calculate_metrics(requests[int(-interval):])

        except Exception as e:
            error_count = check_webhook_log(500)
            metrics = calculate_metrics(requests)

            error_log = f"Error occurred at {datetime.now()}: {str(e)}"
            logging.error(error_log)

            print(f"[{datetime.now().strftime('%Y-%m-%d %H:%M:%S')}] {error_log}")

            if '5xx' in metrics and metrics['error_rate'] >= minutes_to_check:
                print("Webhook seems to be overwhelmed. Consider upgrading.")

    while True:
        try:
            asyncio.create_task(send_request())
            loop = asyncio.get_event_loop()
            start_time = datetime.now()

            interval_start = datetime.now() + timedelta(seconds=interval)
            last_interval_start = None

            def time_to_check():
                nonlocal last_interval_start

                current_interval = (datetime.now() - last_interval_start).total_seconds() / 60
                if current_interval >= minutes_to_check:
                    last_interval_start = datetime.now()
                    return True
                else:
                    return False

            loop.add_callback(time_to_check)

            while True:
                try:
                    await asyncio.sleep(1)

                    # Break the loop after some time to avoid hanging
                    if (datetime.now() - start_time).total_seconds() > 30 * 60:
                        break

                    last_interval_start = datetime.now()

                    check_webhook_log(500)

                except asyncio.CancelledError:
                    loop.call_soon_threadsafe(loop.stop)
                    break

            logging.info(f"Webhook monitoring completed after {datetime.now() - start_time} seconds.")

        except KeyboardInterrupt:
            print("\nMonitoring stopped.\n")
            break

# Example usage
if __name__ == '__main__':
    server_url = 'http://localhost:8080'  # Replace with your server's URL
    endpoint = '/webhook'  # Replace with your webhook endpoint

    try:
        monitor_webhook(server_url, endpoint, interval=60, minutes_to_check=5)

    except Exception as e:
        print(f"An error occurred: {str(e)}")

import re

def validate_form(inputs):
    # Check that all required fields are present
    for field in ['name', 'email', 'password']:
        if not inputs.get(field):
            return False

    # Check that the email address is valid
    email = inputs['email']
    if not re.match(r'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$', email):
        return False

    # Check that the password is at least 8 characters long and contains a number
    password = inputs['password']
    if len(password) < 8 or not any(char.isdigit() for char in password):
        return False

    return True

