import boto3
from botocore.exceptions import NoCredentialsError

class CloudFilePermissionManager:
    def __init__(self, access_key, secret_key, region_name):
        self.s3 = boto3.client('s3', aws_access_key_id=access_key,
                                      aws_secret_access_key=secret_key,
                                      region_name=region_name)
        self.iam = boto3.client('iam')

    def create_bucket(self, bucket_name):
        try:
            self.s3.create_bucket(Bucket=bucket_name)
            print(f"Bucket '{bucket_name}' created successfully.")
        except NoCredentialsError:
            print("Error: Credentials not available.")

    def add_user_to_bucket(self, bucket_name, user_email, role_arn):
        try:
            response = self.iam.add_user_to_group(
                UserName=user_email,
                GroupName='s3-bucket-owners',
                RoleArn=role_arn
            )
            print(f"User '{user_email}' added to bucket '{bucket_name}'.")
        except NoCredentialsError:
            print("Error: Credentials not available.")

    def update_bucket_policy(self, bucket_name, policy):
        try:
            self.s3.put_bucket_policy(Bucket=bucket_name,
                                       Policy=policy)
            print(f"Bucket policy updated for '{bucket_name}'.")
        except NoCredentialsError:
            print("Error: Credentials not available.")

    def remove_user_from_bucket(self, bucket_name, user_email):
        try:
            response = self.iam.remove_user_from_group(
                UserName=user_email,
                GroupName='s3-bucket-owners'
            )
            print(f"User '{user_email}' removed from bucket '{bucket_name}'.")
        except NoCredentialsError:
            print("Error: Credentials not available.")

    def get_bucket_policy(self, bucket_name):
        try:
            response = self.s3.get_bucket_policy(Bucket=bucket_name)
            return response['Policy']
        except NoCredentialsError:
            print("Error: Credentials not available.")
            return None

def main():
    access_key = 'YOUR_AWS_ACCESS_KEY'
    secret_key = 'YOUR_AWS_SECRET_KEY'
    region_name = 'YOUR_AWS_REGION_NAME'

    manager = CloudFilePermissionManager(access_key, secret_key, region_name)

    bucket_name = 'your-bucket-name'
    user_email = 'user@example.com'
    role_arn = 'arn:aws:iam::123456789012:role/your-role-arn'

    # Create a new bucket
    manager.create_bucket(bucket_name)

    # Add the user to the bucket
    manager.add_user_to_bucket(bucket_name, user_email, role_arn)

    # Update the bucket policy
    policy = {
        "Version": "2012-10-17",
        "Statement": [
            {
                "Sid": "AllowPublicRead",
                "Effect": "Allow",
                "Principal": "*",
                "Action": "s3:GetObject",
                "Resource": f"arn:aws:s3:::{bucket_name}/*"
            },
            {
                "Sid": "RestrictReadAccess",
                "Effect": "Deny",
                "Principal": "*",
                "Action": "s3:*",
                "Resource": f"arn:aws:s3:::{bucket_name}"
            }
        ]
    }

    manager.update_bucket_policy(bucket_name, policy)

    # Remove the user from the bucket
    manager.remove_user_from_bucket(bucket_name, user_email)

    # Get the updated bucket policy
    print(manager.get_bucket_policy(bucket_name))

if __name__ == "__main__":
    main()

