import datetime

class PaymentProcessor:
    def __init__(self, user_id, amount, frequency):
        self.user_id = user_id
        self.amount = amount
        self.frequency = frequency
        self.next_payment_date = None

    def schedule_payment(self):
        if self.frequency == 'monthly':
            # Schedule next payment for one month from now
            self.next_payment_date = datetime.datetime.now() + datetime.timedelta(days=30)
        elif self.frequency == 'yearly':
            # Schedule next payment for one year from now
            self.next_payment_date = datetime.datetime.now() + datetime.timedelta(days=365)
        else:
            raise ValueError('Invalid frequency')

    def process_payment(self):
        if datetime.datetime.now() >= self.next_payment_date:
            # Process payment here
            print(f'Processing payment of {self.amount} for user {self.user_id}')

            # Schedule next payment
            self.schedule_payment()

