import heapq
from datetime import datetime, timedelta

class EventHandler:
    def __init__(self):
        self._queue = []  # priority queue

    def add_event(self, event, timestamp):
        """Add an event to the queue. The event is removed after a certain delay."""
        remove_time = datetime.now() + timedelta(seconds=timestamp)
        heapq.heappush(self._queue, (remove_time, event))

    def handle_events(self):
        """Handle events that their time has come."""
        while self._queue and self._queue[0][0] <= datetime.now():
            _, event = heapq.heappop(self._queue)
            print("Handling Event: ", event)  # replace this with your code

    def run_forever(self):
        """Continuously handle events."""
        while True:
            self.handle_events()

