import time

def expiring_cache(cache_entries):
    # The list of cached entries will be modified by this decorator
    cache = []

    def decorator(func):
        def wrapper(*args, **kwargs):
            key = args[0]  # Assuming the first argument is the key

            # If the entry doesn't exist in the cache yet, add a new one immediately
            if key not in [entry['key'] for entry in cache]:
                data = func(*args, **kwargs)
                cache.append({'data': data, 'lhmtime': time.time()})

            else:
                # Remove entries that have expired or are no longer needed
                now = time.time()
                to_remove = [entry['key'] for entry in cache if entry['lhmtime'] < now - 3600]

                # Remove the keys of the expired entries from the cache list
                for key_to_remove in reversed(to_remove):
                    try:
                        index = next(i for i, entry in enumerate(cache) if entry['key'] == key_to_remove)
                        del cache[index]
                    except StopIteration:
                        pass

                # Update the last modified time of the current entry
                data = func(*args, **kwargs)
                new_lhmtime = now + 3600  # Add one hour (3600 seconds) to the current time
                cache[cache.index(next(entry for entry in cache if entry['key'] == key))] = {
                    'data': data,
                    'lhmtime': new_lhmtime
                }

            return data

        return wrapper

    return decorator

# Initialize an empty list to hold cached entries (this will be captured by the expiring_cache decorator)
cache_entries = []

def test decorated_function():
    @expiring_cache(cache_entries)
    def func():
        return {"data": "Some Data"}
    return func()

# After using the decorated function, clean up the cache
clean_cache()

