def is_empty(obj):
    if obj is None:
        return True
    if isinstance(obj, str):
        return len(obj) == 0
    elif isinstance(obj, (list, tuple)):
        return any(not is_empty(item) for item in obj)
    elif isinstance(obj, dict):
        return all(not is_empty(value) for value in obj.values())
    else:
        # For other types like int, float, etc., check if they are 'falsy'
        return not obj

