import jwt
import datetime
from typing import Dict, Any

# Secret key for signing and verifying tokens
SECRET_KEY = "my_secret_key"

class TokenManager:
    def __init__(self):
        self.tokens: Dict[str, str] = {}

    def generate_token(self, user_id: str, expires_in: int) -> str:
        """Generate a new token with the specified expiration time."""
        payload = {
            "user_id": user_id,
            "exp": datetime.datetime.utcnow() + datetime.timedelta(seconds=expires_in),
        }
        return jwt.encode(payload, SECRET_KEY, algorithm="HS256")

    def verify_token(self, token: str) -> Dict[str, Any]:
        """Verify the authenticity of a given token."""
        try:
            payload = jwt.decode(token, SECRET_KEY, algorithms=["HS256"])
            return payload
        except jwt.ExpiredSignatureError:
            raise ValueError("Token has expired")
        except jwt.InvalidTokenError as e:
            raise ValueError("Invalid token") from e

    def store_token(self, user_id: str, token: str):
        """Store the token for a given user in the database."""
        self.tokens[user_id] = token

    def retrieve_token(self, user_id: str) -> str:
        """Retrieve the stored token for a given user."""
        return self.tokens.get(user_id)

# Example usage
token_manager = TokenManager()

# Generate and store a token for a user
user_id = "12345"
token = token_manager.generate_token(user_id, 3600)
token_manager.store_token(user_id, token)
print(f"Generated token: {token}")

# Verify the authenticity of the token
verified_payload = token_manager.verify_token(token)
print("Verified payload:", verified_payload)

# Retrieve the stored token
stored_token = token_manager.retrieve_token(user_id)
print("Stored token:", stored_token)

