import re
from datetime import datetime

class CardValidator:
    def __init__(self, cvv, expiration_date):
        self.cvv = cvv
        self.expiration_date = expiration_date

    def validate_cvv(self):
        # Regular expression to check if CVV is valid (3 or 4 digits)
        pattern = re.compile(r'^\d{3,4}$')
        if pattern.match(self.cvv):
            return True
        else:
            return False

    def validate_expiration_date(self):
        try:
            expiration_date = datetime.strptime(self.expiration_date, '%Y-%m')

            # Check if the expiration date is in the future
            if expiration_date > datetime.now():
                return True
            else:
                return False
        except ValueError:
            return False

    def validate_card(self):
        return self.validate_cvv() and self.validate_expiration_date()

# Example usage:
card = CardValidator('1234', '2025-12')
if card.validate_card():
    print("Card is valid")
else:
    print("Card is not valid")

