import uuid
from datetime import datetime

class ContentVersion:
    def __init__(self, id, content, created_at):
        self.id = id
        self.content = content
        self.created_at = created_at

class ContentVersioningSystem:
    def __init__(self):
        self.versions = {}

    def create_version(self, content):
        """Creates a new version of the given content"""
        if not content:
            raise ValueError("Content cannot be empty")

        id = str(uuid.uuid4())
        created_at = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        self.versions[id] = ContentVersion(id, content, created_at)
        return id

    def get_version(self, version_id):
        """Returns the version with the given ID"""
        if version_id not in self.versions:
            raise ValueError("Version not found")

        return self.versions[version_id]

    def update_version(self, version_id, new_content):
        """Updates the content of the given version"""
        if version_id not in self.versions:
            raise ValueError("Version not found")

        self.versions[version_id].content = new_content

    def delete_version(self, version_id):
        """Deletes the version with the given ID"""
        if version_id not in self.versions:
            raise ValueError("Version not found")

        del self.versions[version_id]

# Example usage
if __name__ == "__main__":
    system = ContentVersioningSystem()

    # Create a new version of some content
    id = system.create_version("This is the initial content")
    print(f"Created version with ID: {id}")

    # Get the latest version
    latest_version = system.get_version(id)
    print(f"Latest version: {latest_version.content}")

    # Update the content of the latest version
    new_content = "This is the updated content"
    system.update_version(id, new_content)
    print(f"Updated version: {system.get_version(id).content}")

    # Delete a version
    system.delete_version(id)

    # Try to get a deleted version (should raise an error)
    try:
        latest_version = system.get_version(id)
    except ValueError as e:
        print(e)

import os
from datetime import datetime

def get_file_info(filename):
    """Get or create file info dictionary."""
    if not os.path.exists(filename):
        return {filename: {'content': '', 'size': 0, 'modification_time': None}}

    file_info = {}
    with open(filename, 'r', encoding='utf-8') as f:
        content = f.read()
        size = len(content)
        modification_time = datetime.fromtimestamp(os.path.getmtime(filename))
    file_info[filename] = {'content': content, 'size': size, 'modification_time': modification_time}

    return file_info

def set_file_info(filename, data):
    """Set new file info."""
    if not os.path.exists(filename) or filename in data:
        with open(filename, 'w', encoding='utf-8') as f:
            f.write(data[filename]['content'])

def can_rewrite(filename, new_data, existing_data):
    """Check if rewrite is safe."""
    if not os.path.exists(filename) or filename not in existing_data:
        return True

    # Check modification time and size
    new_modification = new_data['modification_time']
    existing_modification = existing_data[filename]['modification_time']

    # If file was modified, only overwrite if it's actually changed
    if (new_modification > existing_modification or
        new_data[filename]['size'] != existing_data[filename]['size']):
        return True

    return False

def main():
    print("Welcome to File Overwrite Protection")

    while True:
        files = get_file_info(os.getcwd())
        for filename, data in files.items():
            if data['content'].strip() == '':
                size = 0
            else:
                size = len(data['content'])
            print(f"[{filename}] {data['modification_time']}")

        input_file = input("Enter file to modify (or 'exit' to quit): ").strip()

        if input_file == 'exit':
            break

        print("\nEnter new data for the file, or None to start a new file")
        new_data = input().strip().split('\n')

        while not new_data:
            print("Please enter at least one line of content")
            new_data = input().strip().split('\n')

        if len(new_data) == 0:
            print("No data entered, exiting.")
            break

        # Process each file
        for filename in files.keys():
            current_data = files[filename]

            try:
                with open(filename, 'r', encoding='utf-8') as f:
                    existing_content = f.read()
            except IOError:
                existing_content = ''

            if (current_data['modification_time'] >= datetime.now() and
                existing_content == new_data[0]):
                print(f"Skipping {filename} because it matches exactly")
                continue

            # Set new data for each file
            set_file_info(filename, {'content': '\n'.join(new_data), 'size': len(new_data[1]) if new_data else 0,
                                    'modification_time': datetime.now()})

if __name__ == "__main__":
    main()

import functools
import time
from typing import Callable, Any

class TimeCache:
    def __init__(self):
        self.cache = {}

    def set_expiration_time(self, key: str, expiration_time: int):
        """Set the expiration time for a given cache entry.

        Args:
            key (str): The key of the cache entry.
            expiration_time (int): The number of seconds until the cache entry expires.
        """
        self.cache[key] = {'value': None, 'expiration_time': time.time() + expiration_time}

    def get_value(self, key: str) -> Any:
        """Get the value of a cached entry.

        Args:
            key (str): The key of the cache entry.

        Returns:
            Any: The value of the cache entry if it exists and has not expired.
        """
        current_time = time.time()
        if key in self.cache:
            entry = self.cache[key]
            if entry['expiration_time'] > current_time:
                return entry['value']
            else:
                del self.cache[key]
        return None

# Usage
cache = TimeCache()

def my_function():
    # Simulate a long-running operation
    time.sleep(2)
    return "Hello, World!"

@functools.lru_cache(maxsize=32)
def cached_my_function():
    cache.set_expiration_time('my_key', 10)  # Set expiration time for 10 seconds
    return my_function()

print(cached_my_function())  # This will call the function and store its result in the cache

time.sleep(11)  # Wait for 11 seconds to test the expiration
print(cached_my_function())  # This should print None because the entry has expired

import sys
import json


def streaming_lines(file):
    try:
        while True:
            line = next(file)
            if not line.strip():  # Skip empty lines
                continue
            yield line.rstrip('\n')  # Remove newline character at the end of each line
    except StopIteration:
        pass  # Signal generator to stop iteration when EOF is reached


def parse_streaming_file(file):
    for line in streaming_lines(file):
        if not line.strip():
            continue
        content = line.strip()
        if '{' in content:  # Check for JSON format
            try:
                data = json.loads(content)
                yield data
            except json.JSONDecodeError:
                pass
        else:
            values = line.split(',')
            yield tuple(values)  # Parse as CSV row


def main():
    file_path = sys.argv[1]
    parser = parse_streaming_file(open(file_path, 'r'))

    for item in parser:
        print(item)
    return


if __name__ == '__main__':
    main()

import multiprocessing
import asyncio
from collections import deque
import sys
import threading

class ThreadPoolManager:
    def __init__(self):
        self NumOfWorkers = 4
        self.workers = []
        self.worker_processes = []
        self.task_queue = deque()
        self.result_queue = deque()
        self._initialize_workers()

    def _initialize_workers(self):
        for _ in range(self.NumOfWorkers):
            if not multiprocessingrocessing.current_process().is_alive():
                worker_process = multiprocessing.Process(
                    target=self._run_worker,
                    daemon=True
                )
                worker_process.start()
                self.worker_processes.append(worker_process)
            else:
                print(f"Worker already running, will skip {self.NumOfWorkers - len(self.worker_processes)} workers")

    def add_task(self, task_func, *args):
        if not any(p.is_alive() for p in self.worker_processes):
            self.task_queue.append((task_func, args))

    def get_result(self):
        result = self.result_queue.popleft()
        try:
            return (result[0], {k: v for k, v in result[1].items() if not isinstance(v, list)})
        except IndexError:
            raise RuntimeError("Result not found")

    async def _run_worker(self, task_func, *args):
        asyncio.set_event_loop(asyncio.new_event_loop())
        try:
            loop = asyncio.get_event_loop()
            await loop.run_until_complete(task_func(*args))
        except Exception as e:
            print(f"Error in worker: {str(e)}", file=sys.stderr)

    def start_workers(self):
        if not any(p.is_alive() for p in self.worker_processes):
            for _ in range(len(self.worker_processes), self.NumOfWorkers):
                self._initialize_worker()

    def _start_worker(self):
        loop = asyncio.new_event_loop()
        asyncio.set_event_loop(loop)
        try:
            loop.run_forever(stop=False, signal=signal.SIGTERM)
        except KeyboardInterrupt:
            pass
        finally:
            loop.close()

    def stop_workers(self, signal=None):
        if any(p.is_alive() for p in self.worker_processes):
            print("Shutting down workers...", file=sys.stderr)
            try:
                for worker_process in self.worker_processes:
                    if hasattr(worker_process, 'join'):
                        worker_process.join()
                    else:
                        # For processes that don't have join(), use a timeout
                        worker_process.terminate()
            except KeyboardInterrupt:
                pass
        print("Workers shut down successfully", file=sys.stderr)
        sys.exit(0)

