import hashlib
from typing import Dict

class SensorDataProcessor():
    def __init__(self):
        self.sensor_data = {}

    # Add sensor data to the dictionary with a unique ID and hash value for data integrity
    def add_data(self, device_id: str, data: str) -> None:
        if not self._is_valid_device_id(device_id):
            print("Invalid Device ID")
            return

        hashed_data = hashlib.sha256(data.encode()).hexdigest()
        self.sensor_data[device_id] = hashed_data

    # Retrieve sensor data from the dictionary with a unique ID and verify its integrity
    def get_data(self, device_id: str) -> str:
        if not self._is_valid_device_id(device_id):
            print("Invalid Device ID")
            return None

        hashed_data = self.sensor_data.get(device_id)
        if not hashed_data:
            print("No data found for this device.")
            return None

        # You may want to add additional checks here or call a function to verify the hash, depending on your needs.
        return hashed_data

    # Helper method to validate device ID format/length
    def _is_valid_device_id(self, device_id: str) -> bool:
        if len(device_id) != 10 or not device_id.isalnum():   # Example validation for a 10-character alphanumeric ID
            return False
        return True

