import cv2
import numpy as np

def apply_filters(image_path):
    # Load the image
    image = cv2.imread(image_path)

    # Define a list of filters to apply
    filters = [
        {'name': 'Blur', 'kernel': np.array([[1, 1, 1], [1, -4, 1], [1, 1, 1]])},
        {'name': 'Sharpen', 'kernel': np.array([[-1, -1, -1], [-1, 9, -1], [-1, -1, -1]])},
        {'name': 'Gaussian Blur', 'sigma_x': 0.5, 'sigma_y': 0.5}
    ]

    # Apply each filter to the image
    for filter in filters:
        if filter['name'] == 'Blur':
            image = cv2.filter2D(image, -1, filter['kernel'])
        elif filter['name'] == 'Sharpen':
            image = sharpen_image(image)
        elif filter['name'] == 'Gaussian Blur':
            image = gaussian_blur(image)

    # Display the filtered images
    for i, (filter_name, image) in enumerate(filters):
        cv2.imshow(filter_name, image)
        cv2.waitKey(0)

def sharpen_image(image):
    kernel = np.array([[-1, -1, -1], [-1, 9, -1], [-1, -1, -1]])
    return cv2.filter2D(image, -1, kernel)

def gaussian_blur(image):
    sigma_x = filter('sigma_x')
    sigma_y = filter('sigma_y')
    return cv2.GaussianBlur(image, (int(3 * sigma_x), int(3 * sigma_y)), 0)

# Test the function
apply_filters('image.jpg')

