import os
from datetime import timedelta, date

def get_modified_date(filename):
    """Helper function to extract and parse the modification date from a log file."""
    try:
        with open(filename, 'r') as f:
            first_line = f.readline()
            if not first_line.startswith('#'):
                # If no header line exists, assume it's the last line of the log.
                return date.fromisoformat('1970-01-01')
    except FileNotFoundError:
        return date.fromisoformat('1970-01-01')  # Default to a date before any logs.

def main():
    today = date.today()
    rotation_period_days = 30
    cutoff = today - timedelta(days=rotation_period_days)

    source_dir = 'path/to/log/files'  # Replace with actual path
    destination_dir = 'path/to/destination'  # Replace with actual destination

    # List to hold files that are within the last rotation period and have appropriate format.
    recent_files = []
    for filename in os.listdir(source_dir):
        if not os.path.isfile(os.path.join(source_dir, filename)):
            continue
        modified_date = get_modified_date(filename)
        if cutoff <= modified_date:
            # Ensure the file is new enough to be considered; we keep logs up to today.
            recent_files.append(filename)

    # Sort files by their modification date in ascending order (oldest first).
    recent_files.sort(key=lambda x: get_modified_date(x))

    max retaining = min(keep_count, len(recent_files))
    files_to_keep = recent_files[:max_retaining]

    for filename in files_to_keep:
        if os.path.exists(filename):
            # Remove the original file
            os.remove(filename)

    # Copy each kept file to destination
    for f in files_to_keep:
        if os.path.exists(f):
            source_path = os.path.join(source_dir, f)
            dest_path = os.path.join(destination_dir, f)
            if not os.path.exists(dest_path) or os.path.getsize(dest_path) == 0:
                try:
                    os.makedirs(os.path.dirname(dest_path), exist_ok=True)
                    with open(dest_path, 'x') as dest_file:
                        pass
                except Exception as e:
                    print(f"Failed to copy file {f} to destination: {e}")

if __name__ == "__main__":
    main()

