import requests

# Function to check the health status of the server
def check_health():
    try:
        response = requests.get("http://localhost:8080/health")
        if response.status_code == 200:
            print(f"Server is running - Status Code: {response.status_code}")
        else:
            print(f"Error checking server health. Status Code: {response.status_code}, Response: {response.text}")
    except requests.exceptions.RequestException as e:
        print(f"Failed to check server health. Error: {str(e)}")

# Function to send a disconnect notification
def send_disconnect_notification(event_id, user_id):
    try:
        payload = {
            "event": f"Client disconnected from server with ID: {event_id}",
            "user": user_id,
            "timestamp": os.getpid(),
            "status_code": 200
        }
        response = requests.put("http://localhost:8081/notify", json=payload)
        if response.status_code == 200:
            print(f"Successfully notified client with ID {event_id} that they disconnected.")
        else:
            print(f"Failed to notify client. Status Code: {response.status_code}, Response: {response.text}")
    except requests.exceptions.RequestException as e:
        print(f"Error sending disconnect notification. Error: {str(e)}")

if __name__ == "__main__":
    # Initial health check
    print("Checking server health...")
    check_health()

    while True:
        try:
            # Sleep for a short period to allow the server to process disconnections
            import time
            time.sleep(60)

            # Get list of connected clients (replace this with your actual implementation)
            connected_clients = ["Client1", "Client2", "Client3"]

            for client in connected_clients:
                print(f"\nConnecting to {client}...")
                try:
                    response = requests.post("http://localhost:8080/disconnect", json={
                        "event_id": str(os.getpid()),
                        "user_id": f"User_{client}",
                        "timestamp": os.getpid()
                    })

                    if response.status_code == 200:
                        print(f"Successfully disconnected from {client}. Notification sent.")
                    else:
                        print(f"Failed to disconnect from {client}. Status Code: {response.status_code}")

                    send_disconnect_notification(response.json()['event_id'], f"User_{client}")
                except requests.exceptions.RequestException as e:
                    print(f"Error establishing connection with {client}: {str(e)}")

        except KeyboardInterrupt:
            print("\n graceful shutdown\n")
            break

import psutil
from time import sleep

# Initialize resource limit dictionary: tenant_id -> (cpu_limit_percent, memory_limit_percent)
resource_limits = {}

def get_tenant_attr(process, attribute):
    """Retrieve the specified attribute from a process's resource entry."""
    for attr in dir(process):
        if hasattr(process, attr) and attr.lower() == attribute:
            return getattr(process, attr)
    return None

def monitor_systemLimits():
    global resource_limits
    tenant_id = psutil.Process().tenant()

    # Initialize processes list to collect running processes with their resource usage
    running_processes = []

    while True:
        try:
            for process in psutil(topProcesses=True):
                tenant_attr = get_tenant_attr(process, 'Tenant')

                if tenant_attr not in resource_limits:
                    # Initialize new tenant's limit with default values (e.g., 50% CPU and 25% Memory)
                    resource_limits[tenant_attr] = {
                        'cpu_limit': 50.0,
                        'memory_limit': 25.0
                    }

                running_processes.append({
                    'process': process,
                    'cpu_usage': process.cpu_percent(),
                    'memory_usage': process.memory_info().rss / 1024 / 1024,  # in MB
                    'tenant_id': tenant_attr
                })

                # Check resource usage against limits for the current tenant
                if (process.cpu_percent() > resource_limits[tenant_attr]['cpu_limit'] or
                    process.memory_info().rss / 1024 / 1024 > resource_limits[tenant_attr]['memory_limit']):
                    print(f"Tenant {tenant_attr}: Overused resources - CPU: {process.cpu_percent():.1f}%, "
                          f"Memory: {(process.memory_info().rss / 1024 / 1024):.1f}%")
        except Exception as e:
            print(f"Error monitoring processes: {str(e)}")
            continue

        # Sleep for a short period to monitor resource usage in real-time
        sleep(1)

if __name__ == "__main__":
    monitor_systemLimits()

const { makeExecutableSchema } = require('graphql-tools');
const { graphqlAuth } = require('graphql-auth');

// Define your GraphQL schema
const typeDefs = `
  type Query {
    users: [User]
  }

  type User {
    id: ID!
    name: String!
  }
`;

// Define your resolvers
const resolvers = {
  Query: {
    users: async () => {
      // Implement your authentication and authorization logic here
      const user = await getAuthenticatedUser();
      if (!user) {
        throw new Error('Unauthorized');
      }
      return user.name;
    },
  },
};

// Create an executable schema from your type definitions and resolvers
const schema = makeExecutableSchema({
  typeDefs,
  resolvers,
});

// Use graphqlAuth to secure the schema
graphqlAuth(schema, {
  authenticate: async (request) => {
    // Implement your authentication logic here
    const token = request.headers['Authorization'];
    if (!token) {
      return null;
    }
    const user = await getUserFromToken(token);
    if (!user) {
      return null;
    }
    return user;
  },
  authorize: async (request, user) => {
    // Implement your authorization logic here
    if (!user.isAdmin) {
      throw new Error('Unauthorized');
    }
    return true;
  },
});

import boto3
from botocore.exceptions import NoCredentialsError, ClientError

class CloudFileManager:
    def __init__(self, access_key, secret_access_key):
        self.s3 = boto3.client('s3', aws_access_key_id=access_key,
                              aws_secret_access_key=secret_access_key)

    def grant_read_access(self, bucket, file_name, user_email):
        try:
            self.s3.put_object_acl(ACL='public-read', Bucket=bucket, Key=file_name)
            print(f'Read access granted to {user_email} for {file_name} in bucket {bucket}.')
        except ClientError as e:
            print(e.response['Error']['Message'])

    def grant_write_access(self, bucket, file_name, user_email):
        try:
            policy = self._generate_policy('PUTObject', bucket, file_name, user_email)
            self.s3.put_bucket_policy(Bucket=bucket, Policy=policy)
            print(f'Write access granted to {user_email} for {file_name} in bucket {bucket}.')
        except ClientError as e:
            print(e.response['Error']['Message'])

    def revoke_access(self, bucket, file_name, user_email):
        try:
            policy = self._generate_policy('All', bucket, file_name, user_email)
            self.s3.delete_bucket_policy(Bucket=bucket, Policy=policy)
            print(f'Access revoked for {user_email} to {file_name} in bucket {bucket}.')
        except ClientError as e:
            print(e.response['Error']['Message'])

    def _generate_policy(self, action, bucket, file_name, user_email):
        policy = {
            'Version': '2012-10-17',
            'Statement': [
                {
                    'Sid': 'AllowUserAccess',
                    'Effect': 'Allow',
                    'Principal': {'AWS': ['arn:aws:iam::USER_ACCOUNT_ID:' + user_email]},
                    'Action': ['s3:' + action],
                    'Resource': [f'arn:aws:s3:::{bucket}/{file_name}']
                }
            ]
        }
        return str(policy)

