class Queries:
    @classmethod
    def fetch(cls, client, type_):
        return f"""query Fetch {type_}($where: ${type_}.toJSON)! {
            cls.first(client, type_)
        };"""

    @classmethod
    def first(cls, client, type_, limit=100):
        return f"""{type_}.first(limit: {limit})! """

# Operations for Person update
class PersonsOperations:
    @classmethod
    def update(cls, client, person_id, data, config=None):
        if not cls._fields["email"]:
            raise Exception("Email field is required on Persons type")

        query = f"""
            mutation UpdatePerson {{
                updatePerson(
                    id: {person_id},
                    {{ 
                        name: {{$input:{{field: name}}}},
                        email: {{$input:{{field: email}}}}
                    }}
                )
            }}
            """
        return client.query(query, config=config)

