from flask import Flask, request, render_template
import re

app = Flask(__name__)

@app.route('/', methods=['POST', 'GET'])
def form():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']

        # Regular expression to check if string is alphanumeric (letters and numbers only)
        pattern_user = re.compile('^[a-zA-Z0-9]+$') 

        # Checking username: length, it should be between 5 and 20 characters, and must contain letters and/or numbers
        if len(username) < 5 or len(username) > 20 or not bool(pattern_user.match(username)):
            return render_template('form.html', error='Invalid username!')

        # Regular expression to check if string contains uppercase, lowercase and numbers
        pattern_pass = re.compile('^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)') 

        # Checking password: length should be more than 8 chars, contain upper and lower case letters and numbers
        if len(password) < 8 or not bool(pattern_pass.match(password)):
            return render_template('form.html', error='Invalid password!')

        # If everything is valid, you can proceed with signing up user, e.g. create account in database etc. 

    else: # GET request
        return render_template('form.html')

def safe_get(dct, *keys):
    for key in keys:
        try:
            dct = dct[key]
        except KeyError:
            return None
    return dct

