def check_null_or_empty(value):
    if value is None or len(value) == 0:
        return True
    else:
        return False

def process_messages(messages):
    cache = {}
    to_delete = set()

    for msg in messages:
        msg_id = msg['id']
        if msg_id in cache:
            to_delete.add(msg_id)
        else:
            cache[msg_id] = {'processed': False}

    # Clean the cache by removing duplicates
    cleaned_cache = {k: v for k, v in cache.items() if k not in to_delete}
    return cleaned_cache

import time
import random
from collections import defaultdict

class RateLimiter:
    def __init__(self, max_requests, period):
        self.max_requests = max_requests
        self.period = period
        self.request_count = defaultdict(int)
        self.last_request_time = {}

    def is_allowed(self, client_id):
        current_time = time.time()
        for client in self.request_count:
            if client in self.last_request_time and current_time - self.last_request_time[client] < self.period:
                return False

        # Check for client's recent activity
        for client in self.request_count:
            if client == client_id:
                self.request_count[client] += 1
                self.last_request_time[client] = current_time
                return True
            elif client != client_id and self.request_count[client] >= self.max_requests / (self.period / 60):
                return False

        # New client, reset request count
        self.request_count[client_id] = 1
        self.last_request_time[client_id] = current_time

        # Check for global rate limit exceeded
        if len(self.request_count) > self.max_requests:
            return False

        return True


def throttle_scraping(url, client_id):
    limiter = RateLimiter(10, 60)
    delay_in_seconds = random.uniform(0.1, 2)

    while not limiter.is_allowed(client_id):
        time.sleep(delay_in_seconds)
        delay_in_seconds = random.uniform(0.1, 2)

    # Send scraping request
    try:
        # Your scraping logic here
        print(f"Scraping {url} from client {client_id}")
    except Exception as e:
        print(f"Error scraping {url}: {str(e)}")


# Example usage:
if __name__ == "__main__":
    url = "https://example.com"
    clients = ["Client1", "Client2", "Client3"]
    for client in clients:
        throttle_scraping(url, client)

