def get_candidate_packages(requirements_file):
    with open(requirements_file, 'r') as f:
        lines = [line.strip() for line in f.readlines()]
    packages = []
    last_idx = len(lines) - 1
    while last_idx >= 0 and (lines[last_idx].endswith('==')):
        last_idx -= 1
    if last_idx < 0:
        last_idx = len(lines) - 1
    for i in range(len(lines)):
        if lines[i] != '' and not lines[i].startswith('version'):
            packages.append((i, last_idx))
    return [(i[0], i[1]) for i in packages]

def check_upgrade(candidate, requirements_file):
    package_name = candidate[0]
    target_version = candidate[1]
    current_version = get_current_version(package_name)

    if target_version == current_version:
        print(f"No upgrade needed: {package_name} version {current_version}")
        return

    # Prepare the command to install the target version in a temporary environment
    temp_env_cmd = subprocess.getoutput([
        'python', '-m', 'pip',
        'env', '--create',
        '> /dev/null 2>&1',
        f'--no-cache-dir',
        f'pip install --upgrade {package_name}=={target_version}'
    ])

    if temp_env_cmd == '':
        print(f"Package {package_name} is already upgraded.")
        return

    # Now check all dependencies of the target package
    dep = import_module(package_name)
    for attr in dir(dep):
        obj = getattr(dep, attr)
        try:
            if hasattr(obj, '__version__'):
                current_version = get_current_version(attr.split('.')[0])
                last_version = version_to_int(current_version.split('-')[-1])
                new_version = version_to_int(obj.__version__)
                if new_version > last_version and (new_version - last_version) >= 2:
                    print(f"Potential breaking change: {attr} from {last_version} to {new_version}")
        except Exception as e:
            pass

def get_current_version(version_str):
    return int(version_str.split('-')[0])

def version_to_int(vstr):
    parts = list(map(int, vstr.split('.')))
    return sum(p * 10 ** i for i, p in enumerate(reversed(parts)))

def import_module(package_name):
    try:
        module = __import__(package_name)
        return module
    except ImportError as e:
        print(f"Error importing package {package_name}: {e}")
        raise

candidates = get_candidate_packages('requirements.txt')
for candidate in candidates:
    check_upgrade(candidate, 'requirements.txt')

def version_diff(a, b):
    a = list(map(int, str(a).split('.')))
    b = list(map(int, str(b).split('.')))
    diff = 0
    for x, y in zip(a, reversed(b)):
        if x > y:
            return (a.index(x) * len(b)) + b[::-1].index(y)
        elif x < y:
            return -(b.index(y) * len(a)) - a.index(x)
    return None

if __name__ == "__main__":
    # Check dependencies of all packages
    for candidate in candidates:
        package_name, target_version = candidate
        current_version = get_current_version(package_name)
        if target_version != current_version and version_diff(current_version, target_version) is not None:
            print(f"Potential breaking change detected: {package_name} from {current_version} to {target_version}")

