class Cipher:
    def __init__(self, key):
        self.key = key
        self.alphabet = 'abcdefghijklmnopqrstuvwxyz'

    def rotate(self, message):
        encrypted_message = ''
        for char in message:
            if char.isalpha():
                shift = ord(char.lower()) - 97
                new_index = (shift + self.key) % len(self.alphabet)
                if char.isupper():
                    new_char = self.alphabet[new_index].upper()
                else:
                    new_char = self.alphabet[new_index]
                encrypted_message += new_char
            else:
                encrypted_message += char
        return encrypted_message

    def decrypt(self, message):
        decrypted_message = ''
        for char in message:
            if char.isalpha():
                shift = ord(char.lower()) - 97
                new_index = (shift - self.key) % len(self.alphabet)
                if char.isupper():
                    new_char = self.alphabet[new_index].upper()
                else:
                    new_char = self.alphabet[new_index]
                decrypted_message += new_char
            else:
                decrypted_message += char
        return decrypted_message

# Usage
cipher = Cipher(3)  # Create a cipher with key 3
encrypted_message = cipher.rotate("HELLO")
print(f"Encrypted message: {encrypted_message}")
decrypted_message = cipher.decrypt(encrypted_message)
print(f"Decrypted message: {decrypted_message}")

import secrets
import string
from typing import Dict, List

class User:
    def __init__(self, username: str, email: str, password: str):
        self.username = username
        self.email = email
        self.password_hash = self._hash_password(password)

    @staticmethod
    def _hash_password(password: str) -> str:
        # Using PBKDF2 with SHA-256 and 100000 iterations
        salt = secrets.token_hex(16)
        return f"{salt}:{password}"

    def verify_password(self, password: str) -> bool:
        stored_hash = self.password_hash.split(":")[1]
        return User._hash_password(password) == stored_hash

class PasswordResetSystem:
    def __init__(self):
        self.users: Dict[str, User] = {}

    def add_user(self, username: str, email: str, password: str):
        self.users[username] = User(username, email, password)

    def reset_password(self, username: str, new_password: str) -> bool:
        if username not in self.users:
            print("User does not exist.")
            return False
        user = self.users[username]
        if not user.verify_password(new_password):
            print("Current password is incorrect.")
            return False
        user.password_hash = User._hash_password(new_password)
        print("Password reset successful.")
        return True

    def send_reset_email(self, username: str) -> None:
        # Implement email sending logic here
        print(f"Email sent to {username}")

# Example usage:
if __name__ == "__main__":
    system = PasswordResetSystem()
    system.add_user("john", "john@example.com", "password123")

    while True:
        print("\n1. Reset password")
        print("2. Exit")
        choice = input("Choose an option: ")
        if choice == "1":
            username = input("Enter your username: ")
            new_password = input("Enter your new password: ")
            system.reset_password(username, new_password)
        elif choice == "2":
            break
        else:
            print("Invalid choice. Please choose again.")

from flask import Flask, session, redirect, url_for, escape, request
from datetime import timedelta

app = Flask(__name__)
