def rename_file(filename):
    """Rename file to avoid conflicts."""
    if os.path.exists('uploads/{}'.format(filename)):
        name, extension = filename.rsplit('.', 1)
        return '{}-copy.{}'.format(name, extension)
    else:
        return filename

@app.route('/upload', methods=['GET', 'POST'])
def upload():
    if request.method == 'POST' and 'file_data' in request.files:
        file = request.files['file_data']

        # Rename the uploaded file to avoid conflicts
        filename = rename_file(file.filename)

        files.save(file, name=filename)
    return "File uploaded successfully"

from flask import Flask, request, jsonify
import threading
import time

app = Flask(__name__)

# Initialize rate limit counters and locks
rate_limit_counters = {
    'requests': 0,
    'requests_per_second': 10
}
lock = threading.Lock()

# Rate limiting decorator
def rate_limited(max_requests, period):
    def decorator(func):
        def wrapper(*args, **kwargs):
            with lock:
                current_time = time.time()
                if rate_limit_counters['requests'] >= max_requests:
                    return jsonify({'error': 'Rate limit exceeded'}), 429

                rate_limit_counters['requests'] += 1
                last_reset = rate_limit_counters.get('last_reset', 0)
                if current_time - last_reset > period:
                    rate_limit_counters['requests'] = 0
                rate_limit_counters['last_reset'] = current_time

            return func(*args, **kwargs)

        return wrapper
    return decorator

# AI model inference endpoint with rate limiting
@app.route('/inference', methods=['POST'])
@rate_limited(max_requests=10, period=1.0) # 10 requests per second
def inference():
    data = request.json
    if 'input' not in data:
        return jsonify({'error': 'Invalid input'}), 400

    # Simulate AI model inference time (replace with actual inference code)
    time.sleep(0.5)

    return jsonify({'output': data['input']})

if __name__ == '__main__':
    app.run(debug=True)

import requests
import hashlib
from typing import Optional

class FirmwareUpdater:
    def __init__(self, url: str, device_id: str):
        self.url = url
        self.device_id = device_id

    def get_latest_firmware(self) -> Optional[str]:
        response = requests.get(self.url + "/firmware")
        if response.status_code == 200:
            return response.json()['version']
        else:
            print("Failed to get the latest firmware version.")
            return None

    def check_update(self, current_version: str) -> bool:
        latest_version = self.get_latest_firmware()
        if latest_version is None:
            return False
        else:
            return latest_version > current_version

    def download_firmware(self, version: str):
        response = requests.get(self.url + f"/firmware/{version}", stream=True)
        if response.status_code == 200:
            with open("new_firmware.bin", "wb") as file:
                for chunk in response.iter_content(chunk_size=1024):
                    file.write(chunk)
        else:
            print("Failed to download the firmware.")

    def verify_firmware(self, version: str):
        with open("new_firmware.bin", "rb") as file:
            bytes = file.read()
            readable_hash = hashlib.sha256(bytes).hexdigest()

        response = requests.get(self.url + f"/firmware/{version}/checksum")
        if response.status_code == 200:
            expected_hash = response.json()['sha256']
            return readable_hash == expected_hash
        else:
            print("Failed to get the firmware checksum.")
            return False

    def update(self, current_version: str):
        if self.check_update(current_version):
            latest_version = self.get_latest_firmware()
            self.download_firmware(latest_version)
            if self.verify_firmware(latest_version):
                print("Firmware verified successfully.")
                # Here, you would typically call a function to initiate the firmware update process on your device.
            else:
                print("Firmware verification failed. Please try updating again later.")
        else:
            print("No updates available at this time.")

import time

class RateLimiter:
    def __init__(self):
        self.get_count = 0
        self.post_count = 0

    def limit_exceeded(self, endpoint):
        if endpoint == 'get' and self.get_count >= 10:
            raise Exception("Too many GET requests")
        elif endpoint == 'post' and self.post_count >= 5:
            raise Exception("Too many POST requests")

def handle_request(endpoint):
    limiter = RateLimiter()

    def wrapper(func):
        def inner(*args, **kwargs):
            start_time = time.time()
            result = func(*args, **kwargs)
            elapsed = time.time() - start_time

            if elapsed < 0.1:  # Assume rate limit every 0.1 seconds
                limiter.limit_exceeded(endpoint)
        return inner
    return wrapper

# Usage example:
def get_data():
    @handle_request('get')
    def inner_get():
        # Perform GET request and process result
    inner_get()

def post_data():
    @handle_request('post')
    def inner_post():
        # Perform POST request and process result
    inner_post()

import logging
from graphql import GraphQLQuery
from typing import Dict, List

# Create a logger
logger = logging.getLogger(__name__)

class GraphQLLogger:
    def __init__(self):
        self.queries_logged = {}

    def log_query(self, query: str) -> None:
        """Log a GraphQL query"""
        # Parse the GraphQL query into an AST
        try:
            ast = GraphQLQuery.parse(query)
        except Exception as e:
            logger.error(f"Failed to parse query: {e}")
            return

        # Extract relevant information from the AST
        operation_name = ast.operator
        variables = ast.variables

        # Format the log message
        log_message = f"Operation Name: {operation_name}\nVariables: {variables}"

        # Log the query
        logger.info(log_message)
        self.queries_logged[operation_name] = (log_message, variables)

    def get_logged_queries(self) -> Dict[str, List[tuple]]:
        """Return logged queries"""
        return self.queries_logged


