def translate_string(s, translation_table=None):
    if translation_table is None:
        translation_table = {}

    # Create a translation table using ordinals for efficiency and security
    table = {ord(char): ord(mapping_char) for char, mapping_char in translation_table.items()}

    return s.translate(table)

