import subprocess
from time import sleep

def remove_duplicate_cron_jobs():
    # Command to list all cron schedule tasks, including running and queued ones
    output = subprocess.run(
        ['sched-queue', '-n', '--print=pid taskname COMMAND'],
        shell=True,
        stdout=subprocess.PIPE,
        text=True
    )

    if output.returncode != 0:
        print(f"Error executing command: {output.stderr}")
        return

    unique_jobs = set()
    for line in output.stdout.strip().split('\n'):
        parts = line.split()
        task_name = parts[0]
        if task_name not in unique_jobs:
            unique_jobs.add(task_name)

    # If duplicates found, schedule them to be deleted
    if len(unique_jobs) < len(output.stdout.strip().split('\n')):
        print(f"Cleaning up {len(output.stdout.strip().split('\n')) - len(unique_jobs)} duplicate cron jobs.")
        subprocess.run(
            ['sched-queue', '-n', '--delete'],
            shell=True,
            check=False
        )

    sleep(3600)  # Sleep for one hour to allow scheduling cleanup

# Run the script periodically, e.g., every hour
if __name__ == "__main__":
    while True:
        try:
            remove_duplicate_cron_jobs()
        except KeyboardInterrupt:
            print("Shutting down duplicate cron job cleaner.")
            break

