    "tenant2": {"api_key": "hijklmn"}   # tenant2's API key is 'hijklmn'
}

@app.before_request
def check_access():
    api_key = request.args.get('api_key')  # Get the API key from the URL query parameters

    if not api_key:
        abort(403)  # Forbidden - no API key provided

    tenant = None
    for t, v in tenants.items():
        if v['api_key'] == api_key:
            tenant = t
            break

    if not tenant:
        abort(403)  # Forbidden - invalid API key

    request.tenant = tenant  # Store the current tenant for easy access in the endpoint

class Tenant:
    def __init__(self, tenant_id, tenant_name):
        self.tenant_id = tenant_id
        self.tenant_name = tenant_name
        self.users = []

    def add_user(self, user):
        """Add a user to the tenant."""
        if not user:  # Assuming 'user' is an instance of User class
            return False

        user_id = user.user_id if hasattr(user, 'user_id') else None

        existing_user = next((u for u in self.users if u.username == user.username), None)
        if existing_user:
            return False

        if not user.check_password(user.username):
            return False

        user.name = user.username  # Assuming usernames are unique and used as names
        user.user_id = len(self.users) + 1  # Assigning a sequential ID

        self.users.append(user)
        return True

    def get_user(self, username):
        """Retrieve a user by username."""
        for user in self.users:
            if user.username == username:
                return user
        return None

    def delete_user(self, username):
        """Delete a user from the tenant."""
        for i, user in enumerate(self.users):
            if user.username == username:
                del self.users[i]
                break
        return True

import time
import requests

class IotDevice:
    def __init__(self, ip_address):
        self.ip_address = ip_address

    def check_health(self):
        try:
            response = requests.get(f"http://{self.ip_address}/status", timeout=5)
            if response.status_code == 200:
                return True, response.json()
            else:
                return False, f"Received status code {response.status_code}"
        except requests.exceptions.RequestException as e:
            return False, str(e)

def main():
    devices = [IotDevice("192.168.0.1"), IotDevice("192.168.0.2")]  # Add your device IPs here

    while True:
        for device in devices:
            is_healthy, message = device.check_health()
            if is_healthy:
                print(f"Device {device.ip_address} is healthy. Status: {message}")
            else:
                print(f"Error checking health of device {device.ip_address}: {message}")
        time.sleep(60)  # Wait for 1 minute before next check

if __name__ == "__main__":
    main()

import os
import time
from getpass import getpass
import datetime

def check_backup_status(job_name):
    try:
        # List all scheduled jobs
        _, stdout, stderr = os.popen('poll job *').read().split('\n')

        for entry in stdout.split():
            if not entry.strip():
                continue

            columns = entry.rsplit(maxsplit=1)
            job_name Column = columns[0]
            job_state = columns[1].strip()

            if job_name == job_name and 'failed' in job_state:
                print(f"Backup job {job_name} failed")
                return False
    except Exception as e:
        print(f"Error checking backup status: {e}")

    return True

def main():
    username = getpass.getpass("Enter username: ")
    password = getpass.getpass("Enter password: ", prompt="Enter the password for user {username}: ").strip()

    try:
        # List and check all scheduled jobs
        _, stdout, stderr = os.popen(f'poll -u "{username}" "{password}" job *').read().split('\n')

        for entry in stdout.split():
            if not entry.strip():
                continue

            columns = entry.rsplit(maxsplit=1)
            job_name Column = columns[0]
            job_state = columns[1].strip()

            print(f"{datetime.datetime.now().strftime('%H:%M:%S')} Monitoring backup job {job_name} status: {job_state}")

        while True:
            try:
                # Check every minute
                failed_job = check_backup_status(job_name)

                if not failed_job:
                    time.sleep(60)  # Wait 1 minute before checking again
                else:
                    break

            except KeyboardInterrupt:
                print("\nShutting down backup job monitor...")
                break

    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    main()

import cron
import retry

def run_job(job):
    try:
        job()
    except Exception as e:
        # Retry the job up to 3 times if it fails
        for i in range(3):
            try:
                job()
                break
            except Exception as e:
                print("Job failed with error:", str(e))
                print("Retrying...")
    else:
        # If the job succeeds, print a success message
        print("Job succeeded!")

# Create a cron object and add a job to it
cron = cron.Cron()
cron.add_job(run_job)

# Start the cron loop
cron.start()

