import sys
from io import TextIOBase, BytesIO

def streaming_parser(lines_func):
    """A streaming parser that reads lines from input and yields parsed results."""
    for line in lines_func():
        # Process each line as it is read
        yield parse_line(line)

def parse_line(line: str) -> str:
    """Parse a single line of text."""
    try:
        if not line.strip():
            return ''
        # Process the line here (e.g., split, transform, etc.)
        return line.strip()
    except Exception as e:
        print(f"Error parsing line: {line}", file=sys.stderr)
        raise

def create_streaming_parser(input_type='text'):
    """Create a streaming parser for either text or binary files."""
    if input_type == 'text':
        return TextIOBase(sys.stdin)
    elif input_type == 'binary':
        return BytesIO(sys.stdin.read())
    else:
        raise ValueError("Invalid input type. Use 'text' or 'binary'.")

import mimetypes
from flask import request, jsonify

def validate_file_type(file_name):
    # Get the MIME type of the file
    mime_type = request.files['file'].mimetype

    # Check if the file has a valid extension
    if not mime_type:
        return False

    # Define valid extensions for different file types
    valid_extensions = {
        'image': ['jpg', 'jpeg', 'png', 'gif'],
        'document': ['pdf', 'docx', 'doc', 'txt'],
        'audio': ['mp3', 'wav', 'ogg'],
        'video': ['mp4', 'avi', 'mov']
    }

    # Extract the file extension
    _, file_extension = mime_type.split('/')
    file_extension = file_extension.lstrip('.')

    # Check if the file has a valid extension
    return file_extension in valid_extensions.get(mime_type.split('/')[0], [])

