import socket
import threading

class ThreadedServer(object):
    def __init__(self, host='127.0.0.1', port=55555):
        self.host = host
        self.port = port
        self.sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        self.sock.bind((self.host, self.port))

    def listen(self):
        self.sock.listen(5)
        while True:
            client, address = self.sock.accept()
            client.settimeout(60)
            threading.Thread(target=self.handle_client, args=(client,address)).start()

    def handle_client(self, client, address):
        size = 1024
        while True:
            try:
                data = client.recv(size)
                if data:
                    response = self.process_request(data) # This is where you would process the request
                    client.send(response)
                else:
                    raise error('Client disconnected')
            except Exception as e:
                print("Error:", str(e))
                client.close()
                return False

    def process_request(self, data):
        # This is where you would add your code to handle the request
        # For this example, I'll simply echo back whatever was sent
        return data

if __name__ == "__main__":
    ThreadedServer('127.0.0.1', 55555).listen()

