import os
import subprocess

def handle_fork securely():
    # Create a new process using subprocess.run with shell=False for security
    try:
        result = subprocess.run(['ls', '-l'], 
                                shell=False, 
                                start_new_session=True,
                                text=True)
        print("Process has exited with status:", result.returncode)
    except subprocess.CalledProcessError as e:
        # Handle any errors that occurred during the process execution
        print(f"An error occurred: {e}")

    finally:
        try:
            # Close all file descriptors in case of fork
            for fd in os.popen('ls -l | grep "$FD"').read().splitlines():
                if 'FD=' in fd:
                    fd_value = fd.split('=')[1]
                    os.close(int(fd_value))
            print("File descriptors closed successfully.")
        except Exception as e:
            print(f"Error closing file descriptors: {e}")

    # Ensure that the parent process exits only after all children are terminated
    if result.returncode != 0:
        os._exit(1)

