import threading
from typing import List, Dict, Any

class QueryBatcher:
    def __init__(self):
        self.clients: Dict[str, dict] = {}
        self.current_batch: List[str] = []
        self.pending_batches: List[List[str]] = []
        self.responses: Dict[str, dict] = {}
        self.errors: Dict[str, Any] = {}

    def add_query(self, client_id: str, query: str):
        if not client_id in self.clients:
            raise ValueError("Client already exists.")

        if len(self.current_batch) == 0:
            # Start a new batch
            self.pending_batches.append([])
        self.current_batch.append(query)

    def execute(self, client_id: str) -> None:
        if not client_id in self.clients:
            return

        try:
            queries = self.current_batch.copy()
            del self.current_batch[:]

            results = []
            for query in queries:
                # Here you would normally run the query and collect results
                result = {
                    'status': 'success',
                    'data': None  # Placeholder for actual data
                }
                results.append(result)

            self.responses[client_id] = results
        except Exception as e:
            error_info = {
                'code': str(e),
                'message': str(e.args)
            }
            self.errors[client_id] = error_info

    def run_in_thread(self, client_id: str) -> None:
        """Execute the current batch in a separate thread"""
        if client_id not in self.clients or len(self.current_batch) == 0:
            return

        batch = self.pending_batches.pop(0)

        def _execute():
            try:
                for query in batch:
                    # Simulate database execution
                    pass

                responses = {
                    c_id: {'status': 'success'}
                    for c_id in client_id  # Corrected variable name
                }
                self.responses[c_id] = responses

            except Exception as e:
                error_response = {
                    'code': str(e),
                    'message': str(e)
                }
                self.errors[client_id] = error_response

        thread = threading.Thread(target=_execute, args=(client_id,))
        thread.start()
        thread.join()

    def send_response(self, client_id: str) -> None:
        """Send the collected responses to the client"""
        if client_id not in self.responses or not client_id:
            return

        response_data = self.responses.get(client_id, {})
        error_info = self.errors.get(client_id, {})

        # Here you would send data back using an API or some other method
        print(f"Sending responses to {client_id}")
        print("Response:", response_data)
        if error_info:
            print("Error:", error_info)

