def rate_limit(invalid_count, max_consecutive_invalid, total_invalid_threshold):
    # Check if consecutive invalid frames exceed limit
    if invalid_count >= max_consecutive_invalid:
        return True
    # Check if cumulative invalid frames since last valid message exceed threshold
    elif invalid_count > total_invalid_threshold:
        return True
    else:
        return False

