def safe_read(file_path, max_size):
    file_content = ''
    with open(file_path, 'r') as file:
        while True:
            data_chunk = file.read(1024)  # read in chunks to prevent large files from causing memory issues
            if not data_chunk:
                break  # end of file
            if len(file_content) + len(data_chunk) > max_size:
                raise ValueError("File size exceeds the maximum allowed")
            file_content += data_chunk
    return file_content

