import threading
import signal

class TimeoutHandler:
    def __init__(self, timeout_seconds):
        self.timeout = timeout_seconds + 1
        self_interrupted = threading.Event()
        self.signals = signal.Signals()

    def interrupt(self):
        self_interrupted.set()

    def run(self, target_func):
        self_interrupted.set()  # Mark as interrupted on thread creation

        try:
            while not self_interrupted and self timeout > 0:
                time.sleep(1)
        except self.signals.SIGALRM:
            pass
        finally:
            threading.current_thread().interrupt()

def handle_timeout(timeout_seconds, target_func):
    handler = TimeoutHandler(timeout_seconds)
    handler interrupt()

    def run_function(*args, **kwargs):
        thread = threading.Thread(target=target_func, args=args, kwargs=kwargs)
        thread.start()
        return thread

    threads = [run_function() for _ in range(3)]
    return threads

import base64
from Crypto.PublicKey import RSA

def main():
    # Generate your private key (2048 bits for security)
    privkey = RSA().generate(2048)

    # Get the public key from the private key
    pubkey = privkey.publickey()

    # Prepare plaintext message as bytes
    plaintext = b"Hello, world!"

    try:
        # Encrypt using your public key (you can use someone else's public key here)
        ciphertext = pubkey.encrypt(plaintext)
        print("Ciphertext:", base64.b64encode(ciphertext).decode('utf-8'))  # Base64 encode for readability
    except PaddingImpossible as e:
        print(f"Error: {e}")  

    try:
        # Decrypt using your private key
        decrypted = privkey.decrypt(ciphertext)
        if decrypted == plaintext:
            print("Decryption successful!")
        else:
            print("Decryption failed.")
    except PaddingImpossible as e:
        print(f"Decryption error: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    main()

