import hmac
import hashlib
import os

app = Flask(__name__)
WEBHOOK_SECRET = os.environ['WEBHOOK_SECRET']  # This should be an environment variable storing your webhook secret key

@app.route('/webhook', methods=['POST'])
def handle_webhook():
    signature = request.headers.get('X-Hub-Signature')
    if not verify_signature(request.data, signature):
        abort(403)  # Forbidden

    # Process the webhook data...

def verify_signature(data, signature):
    mac = hmac.new(WEBHOOK_SECRET, msg=data, digestmod=hashlib.sha1)
    return hmac.compare_digest('sha1=' + mac.hexdigest(), signature)

import numpy as np

def validate_input(data):
    # Check if data is a list or numpy array
    if not isinstance(data, (list, np.ndarray)):
        return False, "Invalid type. Input should be list or numpy array."

    # Check if the input is empty
    if len(data) == 0:
        return False, "Empty input is not allowed."

    # Assume that AI model expects a 2D list or numpy array of floats
    try:
        data = np.array(data, dtype=np.float64)
    except ValueError:
        return False, "All elements in the input should be convertible to float."

    # Check if the input is a 2D array
    if len(data.shape) != 2:
        return False, "Input should be a 2D array or list of lists."

    # Assuming all rows must have same number of columns
    num_columns = data.shape[1]
    for i in range(data.shape[0]):
        if data[i].size != num_columns:
            return False, "All rows should have the same number of columns."

    # If all checks passed, then input is valid
    return True, "Input validation successful."

