class Version:
    def __init__(self, data=None, deps=None):
        self.id = str(uuid.uuid4())
        if data is None:
            data = {}
        if deps is None:
            deps = {}
        self.data = data
        self.deps = deps

    def merge(self, new_version):
        # Merge the content of new_version into this version
        for path, chunk in new_version.data.items():
            # Update dependencies first
            dep = new_version.deps.get(path)
            if dep and not dep in self.deps.values():
                dep_id = dep.id
            else:
                dep_id = None

            # If there's a dependency but it points to an older version, 
            # don't overwrite with nothing; it means removing the dependency
            if dep_id is not None and dep_id != str(uuid.uuid4()):
                self.data[path] = chunk
            else:
                if path not in self.data or new_version.id not in (self.deps.get(path, '')).split():
                    self.data[path] = chunk

        # Add any chunks that are not covered by dependencies
        for path, chunk in new_version.data.items():
            if path not in self.data or new_version.id not in (self.deps.get(path, '').split()):
                self.data[path] = chunk

    def add_content(self, data):
        # Append new content to this version's data
        for path, chunk in data.items():
            if path not in self.deps.values():
                self.data[path] = chunk

    def save_backup(self, interval=60 * 5, dir='backups'):
        import uuid
        current_version = (datetime.datetime.now().timestamp() // interval) + 1
        backup_id = str(uuid.uuid4())
        if not os.path.exists(dir):
            os.makedirs(dir)
        path = f"{dir}/{self.id}-{current_version}_{backup_id}.json"
        with open(path, 'w') as f:
            json.dump(self.__dict__, f, indent=2)

