# Define a session dictionary to store session data
sessions = {}

# Function to generate a unique session token
def generate_token():
    return secrets.token_urlsafe(32)

# Function to create a new session
def create_session(username):
    # Generate a unique session token
    token = generate_token()

    # Store the username and token in the session dictionary
    sessions[token] = {'username': username}

    # Return the session token
    return token

# Function to verify a session token
def verify_token(token):
    # Check if the token exists in the session dictionary
    if token in sessions:
        return True
    else:
        return False

# Function to get the username from a session token
def get_username(token):
    # Check if the token is valid
    if verify_token(token):
        return sessions[token]['username']
    else:
        return None

# Function to destroy a session
def destroy_session(token):
    # Remove the session from the dictionary
    del sessions[token]

