    current_time = int(time.time()) // 60  # get the current minute as a integer

    if r.get(current_time):
        count = r.incr(current_time)  # increment the counter for this minute

        if count > 10:  # only allow 10 requests per minute
            return False

    else:
        r.setex(current_time, 60, 1)  # set a new expiring key with an initial value of 1 (request made in this minute)

    return True

