import dns.resolver
import re
from email import policy
from email.parser import BytesParser

def validate_email(raw_message):
    msg = BytesParser(policy=policy.default).parsebytes(raw_message)
    sender = msg["From"]
    domain = re.search('@[\w.]+', sender).group()[1:]

    try:
        records = dns.resolver.resolve(domain, 'MX')
        mxRecord = records[0].exchange
        if verify_spf(sender, str(mxRecord)) and check_dmarc(domain):
            print("Email is valid")
        else:
            print("Email failed validation")
    except Exception as e:
        print("Validation error:", e)

def verify_spf(sender, mx):
    try:
        records = dns.resolver.resolve(mx, 'TXT')
        for record in records:
            if "v=spf1" in str(record):
                # Add your SPF validation logic here
                return True
    except Exception as e:
        print("SPF check error:", e)
    return False

def check_dmarc(domain):
    try:
        records = dns.resolver.resolve('_dmarc.' + domain, 'TXT')
        for record in records:
            if "p=reject" in str(record) or "p=quarantine" in str(record):
                # Add your DMARC validation logic here
                return True
    except Exception as e:
        print("DMARC check error:", e)
    return False

