import json

def serialize_json(data, indent=True):
    """
    Serialize the given data into a JSON-formatted string safely.

    Args:
        data: The object to serialize. Expected to be a dictionary or similar JSON-serializable structure.
        indent (bool): Whether to add indentation for readability. Defaults to True.

    Returns:
        str: A JSON-formatted string representation of the input data.
    """
    try:
        # Ensure that the data is a dictionary; handle unexpected types as needed
        if isinstance(data, dict):
            return json.dumps(data, ensure_ascii=False, indent=indent)
        else:
            raise TypeError("Data must be a dictionary to serialize.")
    except json.JSONDecodeError:
        raise ValueError("Invalid JSON structure. Please provide a serializable object.")
    except Exception as e:
        raise RuntimeError(f"An error occurred during serialization: {e}")

