import time
from typing import Callable, Any, Dict, List
from email.mime.multipart import MIMultipart
from smtplib import SMTP


def rate_limit(allowed: int = 10, window: int = 60, rate: int = 2):
    """Rate limiting decorator for API requests"""

    def decorator(func: Callable) -> Callable:
        cache = {}

        def wrapper(*args, **kwargs) -> Any:
            # Get or create request history for the client
            client = args[1] if len(args) > 1 else None

            if not isinstance(client, dict):
                # If no client IP info provided, use anonymous identifier
                key = str(uuid.uuid4())
                cache[key] = [ (time.time(), 0) ]
            else:
                key = f"{client['ip']}@{client['user']}"
                if key not in cache:
                    cache[key] = [(time.time(), 0)]

            # Check request history
            if key not in cache or time.time() - cache[key][-1][0] > window:
                cache[key].append( (time.time(), 0) )
                remaining = allowed - len(cache[key])

                if remaining <= 0:
                    raise ForbiddenRequestError(f"Rate limited for IP {client['ip']}. Try again in {rate} seconds")

            else:
                # Increment count and check against allowed limit
                cache[key][-1] = (time.time(), remaining)

            try:
                return func(*args, **kwargs)
            except Exception as e:
                # Reset the client's counter after each error
                if key in cache:
                    del cache[key]

                raise

        return wrapper

    return decorator

class ForbiddenRequestError(Exception):
    pass

# Example usage of the rate_limit decorator
def example_api():
    @rate_limit(allowed=5, window=3600, rate=1)
    def hello_world():
        print("Hello from API")
        time.sleep(2)
        return {"status": "ok"}

    client = {
        'ip': '192.168.1.1',
        'user': 'testuser'
    }

    try:
        # Make 5 calls to the API before timing out
        for _ in range(5):
            response = hello_world()
            print(f"Response {response}")

            if len(response) > 0 and isinstance(response, dict):
                time.sleep(random.uniform(1,2))

    except ForbiddenRequestError as e:
        # Send a friendly warning via email
        msg = MIMultipart()
        msg['From'] = 'API Monitoring <automation@example.com>'
        msg['To'] = f"{client['ip']}@{client['user']}"
        msg['Subject'] = "Rate Limiting Notice"

        part = MIMEText(f"Exceeded {allowed} requests in last {window} seconds. Try again later.")
        msg.attach(part)
        server = SMTP('smtp.example.com', 587)
        server.starttls()
        server.sendmail('automation@example.com', [f"{client['ip']}@{client['user']}", 'admin@example.com'], msg)
        server.quit()

    except Exception as e:
        print(f"Error accessing API: {e}")

if __name__ == "__main__":
    import uuid
    import random

    # Test the rate limit decorator
    example_api()

