        return text

def log_backup_activity(
    timestamp: str,
    command: str,
    username: str,
    hostname: str,
    status: str,
    error_message: Optional[str] = None
):
    """
    Logs backup activity with optional error details.
    """
    log_level = logging.CRITICAL if error_message else logging.INFO
    logging.basicConfig(
        level=log_level,
        format='%(asctime)s - %(name)s - %(levelname)s - %(message)s'
    )

    try:
        message = f"{username}@{hostname} - {command} completed on {timestamp}"
        log_message(status, timestamp)
        if error_message:
            log_message("ERROR", error_message, color="RED")
        print(message)
    except Exception as e:
        log_message("CRITICAL", str(e))

def log_message(level: str, message: str, color: Optional[str] = None):
    """Helper function to log messages with optional color."""
    if level == "CRITICAL":
        logging.critical(message)
        sys.exit(1)  # Exit on critical errors
    elif level == "ERROR":
        if color:
            print(colored(f"ERROR: {message}", color))
        else:
            print(f"ERROR: {message}")
    elif level == "INFO":
        print(f"{color}INFO: {message}{color}")

def trigger_backup():
    """Prompts user for backup configuration and triggers the backup."""
    print("\nBackup initiated by [User].")

    interval = getpass.getpass("Enter backup interval (in seconds): ")
    try:
        seconds = int(interval)
    except ValueError:
        print(f"Invalid input. Please enter a valid number. Exitting.")
        sys.exit(1)

    hostname = getpass.getpass("Enter the host name to backup: ")
    username = getpass.getpass("Enter the username for that host: ")

    try:
        # Here you would typically run your backup process
        # Replace this with actual backup code
        print(f"\nStarting backup in {seconds} seconds...")
        time.sleep(seconds)
        print("\nBackup completed.")

        log_backup_activity(
            datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            f"backup_{datetime.now().strftime('%Y%m%d')}.tar.gz",
            username,
            hostname,
            "SUCCESS"
        )
    except KeyboardInterrupt:
        print("\nBackup cancelled by user. Exiting.")
        sys.exit(0)
    except Exception as e:
        error_message = f"Backup failed: {str(e)}"
        log_backup_activity(
            datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "failed",
            username,
            hostname,
            "ERROR",
            error_message
        )

def main():
    try:
        while True:
            print("\n1. Trigger backup")
            print("2. Exit\n")
            choice = input().strip()

            if choice == '1':
                trigger_backup()
            elif choice == '2':
                break
    except SystemExit as e:
        pass

if __name__ == "__main__":
    main()

import sqlite3

class DatabaseTransaction:
    def __init__(self, db_name):
        self.db_name = db_name
        self.conn = sqlite3.connect(db_name)
        self.cursor = self.conn.cursor()

    def begin_transaction(self):
        """Start a new database transaction."""
        self.cursor.execute("BEGIN TRANSACTION")

    def commit_transaction(self):
        """Commit the current database transaction."""
        self.cursor.execute("COMMIT")
        self.conn.commit()

    def rollback_transaction(self):
        """Rollback the current database transaction."""
        self.cursor.execute("ROLLBACK")
        self.conn.rollback()


class DatabaseTransactionManager:
    def __init__(self, db_name):
        self.db_name = db_name
        self.transaction = None

    @property
    def is_opened(self):
        return self.transaction and self.transaction.is_opened

    @property
    def is_committed(self):
        return self.transaction and self.transaction.is_committed

    @property
    def is_rolledback(self):
        return self.transaction and self.transaction.is_rolledback

    def begin_transaction(self):
        """Start a new database transaction."""
        if not self.is_opened:
            self.transaction = DatabaseTransaction(self.db_name)
            self.transaction.begin_transaction()
            print("Database transaction started successfully.")
        else:
            print("Current transaction is already open.")

    def commit_transaction(self):
        """Commit the current database transaction."""
        if self.is_opened and not self.is_rolledback:
            self.transaction.commit_transaction()
            print("Transaction committed successfully.")
        elif self.is_rolledback:
            print("Rolling back an already rolled back transaction.")
        else:
            print("Current transaction is not open or has been rolled back.")

    def rollback_transaction(self):
        """Rollback the current database transaction."""
        if self.is_opened and not self.is_committed:
            self.transaction.rollback_transaction()
            print("Transaction rolled back successfully.")
        elif self.is_rolledback:
            print("Cannot roll back an already rolled back transaction.")
        else:
            print("Current transaction is not open or has been committed.")


# Example usage:

