import requests
from time import sleep

def check_cloud_service():
    url = "https://your-cloud-service-url" # Replace with your cloud service URL
    retries = 5

    for i in range(retries):
        try:
            response = requests.get(url)
            response.raise_for_status() # Raise exception if the status code is not 200
            return True
        except (requests.exceptions.RequestException, requests.exceptions.HTTPError) as err:
            print(f"Cloud service unavailable: {err}. Retrying ({i+1}/{retries})...")
            sleep(2**i) # Exponential backoff to avoid overwhelming the server
    return False

if check_cloud_service():
    print("Cloud service is up and running")
else:
    print("Could not reach cloud service after several retries. An outage might be occurring.")

import requests
from requests.adapters import HTTPAdapter
from requests.util import default_headers
from time import sleep
import random

class RateLimiter:
    def __init__(self, delay=1):
        self.delay = delay

    def allow_request(self):
        return True

    def block_request(self):
        return False

def throttling_requests(url, data, limit, rate_limiter):
    headers = default_headers()
    adapter = HTTPAdapter(max_retries=limit)
    retry_count = 0
    while retry_count <= limit:
        try:
            response = requests.post(url, json=data, headers=headers, adapter=adapter)
            if response.status_code == 200:
                return response
            else:
                retry_count += 1
        except Exception as e:
            print(e)
            rate_limiter.block_request()
            sleep(random.uniform(0.2, 1))
    return None

def main():
    # URL of the API endpoint to send a POST request to
    url = "https://api.example.com/endpoint"

    # Data for the POST request
    data = {
        "key": "value"
    }

    # Number of requests you want to make, and how often (in seconds) you want to retry after making an error response
    limit = 5

    # Create a RateLimiter instance with a delay of 1 second
    rate_limiter = RateLimiter(delay=1)

    # Make the POST request with throttling
    result = throttling_requests(url, data, limit, rate_limiter)

    if result:
        print(result.json())
    else:
        print("Maximum number of retries reached")

if __name__ == "__main__":
    main()

import psutil
import time
import logging

# Set up logging configuration
logging.basicConfig(
    format='%(asctime)s - %(name)s - %(levelname)s - %(message)s',
    level=logging.INFO,
    datefmt='%Y-%m-%d %H:%M:%S'
)

class BackupJob:
    def __init__(self, name, process_id):
        self.name = name
        self.process_id = process_id
        self.status = "Starting"

    def update_status(self, status):
        self.status = status

    def is_running(self):
        return psutil.pid_exists(self.process_id) and self.status != "Completed"

def get_backup_jobs():
    # Assuming you have a list of backup jobs with their names and process IDs
    # In a real-world scenario, this would likely involve querying a database or API
    backup_jobs = [
        BackupJob("Backup Job 1", psutil.pid_exists(1234)),
        BackupJob("Backup Job 2", psutil.pid_exists(5678)),
        # ...
    ]
    return backup_jobs

def main():
    logging.info("Backup job status monitor started")

    while True:
        backup_jobs = get_backup_jobs()
        for job in backup_jobs:
            if not job.is_running():
                logging.warning(f"{job.name} completed")
            else:
                logging.info(f"{job.name} is running ({job.status})")

        # Check for any new processes that may have started
        for job in backup_jobs:
            process = psutil.Process(job.process_id)
            if not process.is_running():
                job.update_status("Completed")

        time.sleep(60)  # Check every minute

if __name__ == "__main__":
    main()

