class CacheInvalidationExample(object):
    def __init__(self):
        self._cache = {}

    def get_data(self, key):
        if key not in self._cache:
            # This is where you'd retrieve your data from a database or an API.
            self._cache[key] = self.fetch_data_from_source(key)
        return self._cache[key]

    def update_data(self, key, new_data):
        # Update the data source with the new data.
        self.update_data_in_source(key, new_data)
        # Then invalidate the cache for that key.
