def load_secure_csv(filename, password=None):
    """Securely load CSV data into memory."""
    import sys

    if password is not None:
        try:
            input("Enter your password: ").strip()
        except IndexError:
            raise ValueError("Invalid password. Please enter the password.")

    with open(filename, 'r') as csvfile:
        header = next(csvfile).split(',')
        num_headers = len(header)

        for line in csvfile:
            # Skip empty lines
            if not line.strip():
                continue

            row = [s.strip() for s in line.split(',')]

            # Check if the number of fields matches the header
            if len(row) != num_headers:
                raise ValueError(f"CSV row {line.strip()} has an incorrect number of columns")

            yield row

