import struct

def safe_parse(file):
    with open(file, "rb") as f:
        # Assuming each record is an integer (4 bytes)
        while True:
            record = f.read(4)  # read exactly 4 bytes
            if len(record) != 4:
                break  # end of file or unexpected EOF
            number = struct.unpack('i', record)[0]  # unpack the integer
            print("Number:", number)

