import binascii
import json
import struct
from base64 import b64encode

def print_binary_data(data):
    # Convert binary data to hex string and print
    hex_str = binascii.a2b_hex(data)
    decoded_latin1 = hex_str.decode('latin-1')
    print(f"Hex representation: {hex_str}")
    print(f"Decoded (latin-1):    {decoded_latin1}\n")

def parse_binary(data):
    # Try to decode and parse JSON
    try:
        json_decoded = json.loads(data)
        if isinstance(json_decoded, dict) or isinstance(json_decoded, list):
            return json_decoded
        else:
            raise ValueError("JSON data is not an array or object")
    except ValueError as e:
        print(f"Error parsing JSON: {e}")

    # If JSON fails, attempt base64 encoding and try again
    if isinstance(data, bytes):
        base64_bytes = b64encode(data)
        decoded_base64 = base64_bytes.decode('utf-8')
        try:
            json_decoded = json.loads(decoded_base64)
            return json_decoded
        except ValueError as e:
            print(f"Failed to decode JSON after base64: {e}")

    # Example for decoding UUID (specific protocol)
    if isinstance(data, bytes):
        try:
            uuid_str = data.decode('latin1')
            uuid_uuid = bytes.fromhex(uuid_str.replace(':', '')).decode('latin1').strip()
            return uuid_uuid
        except UnicodeDecodeError as e:
            print(f"Error decoding UUID: {e}")

    # Example for decoding IPv4 address (specific protocol)
    if isinstance(data, bytes):
        try:
            ip_str = data.decode('latin1')
            ip = struct.pack("I", int(ip_str))[:4]
            return struct.unpack('!BBBB', ip)[:4].decode('latin1')
        except UnicodeDecodeError as e:
            print(f"Error decoding IPv4: {e}")

# Read binary data from a file
with open('example.bin', 'rb') as f:
    data = f.read()

print_binary_data(data)
parsed = parse_binary(data)

if isinstance(parsed, dict) or isinstance(parsed, list):
    print("Parsed result:", parsed)
else:
    print("Parsing failed.")

from flask import Flask, request, jsonify
app = Flask(__name__)

transactions = []

@app.route('/charge', methods=['POST'])
def charge():
    data = request.get_json()  # expecting a JSON payload with 'transaction_id' and 'user_id'

    for transaction in transactions:
        if transaction["transaction_id"] == data["transaction_id"]:
            return jsonify({"message": "Transaction already processed."}), 409

    # do the charging process here...
    charge = {'transaction_id': data['transaction_id'], 'user_id': data['user_id']}
    transactions.append(charge)

    return jsonify({"message": "Charge processed successfully."}), 201

