import os
from difflib import unified_diff
import logging
from datetime import datetime

class ConfigurationChanger:
    def __init__(self, config_keys):
        self.config = {}
        for key in config_keys:
            current_value = os.environ.get(key, '')
            self.config[key] = current_value.strip()

        # Save initial state and log it
        timestamp = datetime.now().isoformat()
        logging.info(f"Initial configuration state at {timestamp}")
        self.log_history = [self.__state_diff()]

    def __state_diff(self):
        return unified_diff(
            str(self.config).replace('\'', '"'),
            str(self.__get_current_state()).replace('\'', '""),
            'Current Configuration',
            'Previous Configuration'
        )

    def capture_config(self):
        current = {}
        for key in self.config:
            current[key] = os.environ.get(key, '')

        diff = self.__state_diff()
        if diff:
            timestamp = datetime.now().isoformat()
            log_msg = f"Configuration changes at {timestamp}:\n{diff}"
            logging.info(log_msg)

    @staticmethod
    def __get_current_state():
        return str(dict(os.environ)[k for k in ConfigurationChanger.config_keys if k in os.environ])

