from collections import deque

class DynamicQueue:
    def __init__(self, initial_size=10):
        self.queue = deque(maxlen=initial_size)

    def push(self, item):
        if len(self.queue) == self.queue.maxlen:
            # If the queue is full, we double its size
            self.queue = deque(list(self.queue), maxlen=2 * self.queue.maxlen)
        self.queue.append(item)

    def pop(self):
        if len(self.queue) > 0:
            return self.queue.popleft()
        else:
            raise IndexError("Pop from empty queue")

    def size(self):
        return len(self.queue)

