        print(f"An error occurred while processing the file '{filename}'. Details: {str(e)}")

import boto3
import os
import time
import json

# Define IAM role ARNs based on access level
IAM_ROLE_PRIVATE = 'arn:aws:iam::123456789012:sudo:privateReadWrite'
IAM_ROLE_READ_WRITE = 'arn:aws:iam::123456789012:sudo:readWrite'
IAM_ROLE_FULL_CONTROL = 'arn:aws:iam::123456789012:sudo:fullControl'

def create_iam_role(client, policy_arn):
    """Creates an IAM role with the given policy ARN."""
    response = client.create_role(
        Path='s3',
        PolicyName=policy_arn,
        PolicyDocument=json.dumps({
            "Version": "2012-10-17",
            "Statement": [{
                "Effect": "Allow",
                "Action": ["s3:PutObject", "s3:GetObject", "s3:List_objects_v2"],
                "Resource": "*"
            }]
        })
    )
    return response['IamRoleArn']

def main():
    # Get AWS credentials from environment variables
    access_key_id = os.getenv('AWS_ACCESS_KEY_ID')
    access_secret_key = os.getenv('AWS_SECRET_ACCESS_KEY')

    if not (access_key_id and access_secret_key):
        print("Error: Missing AWS credentials. Please set both AWS_ACCESS_KEY_ID and AWS_SECRET_ACCESS_KEY.")
        return

    # Create botocore client
    client = boto3.client('s3', aws_access_key_id=access_key_id, aws_secret_access_key=access_secret_key)
    client.disable_warnings()

    # Define roles
    roles = {
        IAM_ROLE_PRIVATE: {'name': 'Private Read/Write Access', 'actions': ['private:ReadOnly', 'private:Capsule ReadOnly']},
        IAM_ROLE_READ_WRITE: {'name': 'Read/Write Access', 'actions': ['s3:GetObject', 's3:List_objects_v2', 's3:PutObject']},
        IAM_ROLE_FULL_CONTROL: {'name': 'Full Control', 'actions': ['s3:*']}
    }

    # Validate input
    if not access_key_id or not access_secret_key:
        print("Error: Missing AWS credentials. Please set both AWS_ACCESS_KEY_ID and AWS_SECRET_ACCESS_KEY.")
        return

    # Get list of files from S3
    bucket_name = os.getenv('AWS_BUCKET_NAME')
    if not bucket_name:
        print("Error: Missing AWS bucket name. Please set AWS_BUCKET_NAME.")
        return

    try:
        response = client.list_object_v2(Bucket=bucket_name)
    except boto3.exceptions.Boto3Error as e:
        print(f"Error fetching S3 list: {e}")
        return

    # Convert response to JSON
    file_list_response = json.dumps(response)

    # Validate permissions for each object in the list
    warnings = []
    for obj in json.loads(file_list_response)['objects']:
        actions = client.list_object_v2(
            Bucket=bucket_name,
            Key=obj['Key']
        )['Actions']

        if not any(action in actions for action in roles[roles.keys()[0]]['actions']):
            warnings.append(f"Permission mismatch: Required Action {roles[roles.keys()[0]]['name']} but got {', '.join(actions)}")

    if warnings:
        print("\nWarnings:")
        for warning in warnings:
            print(f"> {warning}")
        input("Press Enter to continue...")
        return

    # Ask user if they want to delete the file list
    delete_list = input("Do you want to delete the file list from S3? (y/n) ").strip().lower()
    if delete_list == 'yes':
        try:
            client.delete_object(Bucket=bucket_name, Key=obj['Key'])
        except Exception as e:
            print(f"Error deleting object: {e}")

if __name__ == "__main__":
    main()

