import xml.etree.ElementTree as ET

class Person:
    def __init__(self, name, age):
        self.name = name
        self.age = age

def serialize_to_xml(obj, root_element):
    if isinstance(obj, dict):
        elem = ET.SubElement(root_element, obj.keys()[0])
        for key, value in obj.items():
            if isinstance(value, list):
                children = ET.SubElement(elem, 'children')
                for item in value:
                    child = ET.SubElement(children, 'child')
                    serialize_to_xml(item, child)
            elif isinstance(value, Person):
                serialize_to_xml(value.__dict__, elem)
            else:
                attr = ET.SubElement(elem, key)
                attr.text = str(value)
    elif isinstance(obj, Person):
        person_elem = ET.SubElement(root_element, 'person')
        name_attr = ET.SubElement(person_elem, 'name')
        name_attr.text = obj.name
        age_attr = ET.SubElement(person_elem, 'age')
        age_attr.text = str(obj.age)

# Example usage:
obj = {
    "name": "John",
    "age": 30,
    "address": {
        "street": "123 Main St",
        "city": "Anytown",
        "state": "CA"
    },
    "children": [
        {"name": "Jane", "age": 5},
        {"name": "Bob", "age": 3}
    ]
}

person = Person("Alice", 25)

root = ET.Element("root")

serialize_to_xml(obj, root)
serialize_to_xml(person, root)

Tree = ET.ElementTree(root)
Tree.write('output.xml')

