import os
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.asymmetric.rsa import RSAPKCS1_v1_5
from pytz import make_password

# Database or configuration where user credentials are stored
database = {
    "users": {},
}

def validate_username(username):
    """Securely validate username by hashing."""
    hashed_username = make_password(username)
    database["users"][username] = hashed_username
    return True  # Assuming username exists and is valid


def validate_password(username, password):
    """Securely compare input password with stored hash."""
    if not database.get("users", {}):
        return False

    stored_hash = database["users"].get(username)
    if not stored_hash:
        return False

    try:
        # Using compare for secure attribute comparison
        return stored_hash == make_password(password)
    except ValueError as e:
        print(f"Hash mismatch: {e}")
        return False


def check_access(resource_path):
    """Check access to admin resource with non-revealing filesystem operations."""
    if not os.path.exists(resource_path):
        raise FileNotFoundError(resource_path)

    try:
        # Get detailed file info without revealing path
        fileStat = os.stat(resource_path,
                          os.O_NOCTET |  # Don't return octet string (empty string)
                          os.O_ATTRIBUTE | os.Oaec)  # Don't reveal path

        # Extract relevant attributes
        is writable = fileStat.st_wa == os.W_OK or os.O Hidden
        is readable = fileStat.st_ro & 0o100000 != 0o40000  # Not a directory
        can_exec = fileStat.st executable == 0

        return {
            'writable': writable,
            'readable': readable,
            'executable': can_exec,
        }

    except PermissionError as e:
        print(f"Permission denied: {e}")
        return None


