import time
from idl import Client, IdlRequestException

class RateLimiter:
    def __init__(self, max_requests=5, min_backoff=1, multiplier=4):
        self.max_requests = max_requests  # number of allowed requests per minute
        self.min_backoff = min_backoff     # minimum wait time in seconds between attempts (starts at 1 second)
        self.multiplier = multiplier      # how much to multiply the backoff after each failure (e.g., 4x)
        self.counters = {}                # dict to store device ID and counters

    def limit(self, ip_address):
        """Check if we are over our rate limit"""
        key = f"{ip_address}/rate"
        if int(self.counters.get(key, 0)) >= self.max_requests:
            raise IdlRequestException(f"Exceeded rate limit for {key}")
        else:
            return True

    def make_request(self, client, method, endpoint, params=None):
        """Attempt to make a request with exponential backoff"""
        try:
            response = client.request(method, endpoint, params=params)
            if not self.limit(response.headers.get('X-Device-IP', '1.1.1.1')):
                return True
            # Update the counter each time regardless of success or failure
            self.counters[f"{response.headers.get('X-Device-IP', '1.1.1.1')}/rate"] =\
                response.headers.get('Content-Length', 0)
            return False

        except IdlRequestException as e:
            if not isinstance(e, IdlRequestException) and not isinstance(e, Exception):
                raise
            # Calculate next attempt after the timeout (min_backoff * multiplier^attempts)
            backoff = self.min_backoff * (self.counters.get(f"{e.header['X-Device-IP', '1.1.1.1']}/rate", 
                                                             f"{e.header['X-Device-IP', '1.1.1.1']}") or 0) + 1
            time.sleep(backoff)
            return False

def main():
    client = Client()
    limiter = RateLimiter()
    print("Testing rate limiting...")

    # Test requests from different IPs
    for ip in ["192.168.1.1", "10.0.0.1", "203.0.113.1"]:
        try:
            response = client.request('GET', f"http://{ip}/ping")
            print(f"Request from {ip} was allowed and completed in {time.time() - time.perf_counter()}")
        except IdlRequestException as e:
            print(f"Request from {ip} failed due to rate limiting: {e}")

    # Test exponential backoff
    try:
        for _ in range(10):
            ip = "192.168.4.1"
            limiter.counters[ip] += 1

            if limiter.counters[ip] >= limiter.max_requests:
                print(f"Rate limit reached from {ip}")
                break
            else:
                try:
                    time.sleep(limiter.min_backoff * (limiter.counters.get(ip, 0) // limiter.max_requests))
                    client.request('GET', f"http://{ip}/ping")
                    print(f"Request from {ip} completed after backoff: {time.time() - time.perf_counter()}")
                except IdlRequestException as e:
                    print(f"Failed to request from {ip}: {e}")
    except KeyboardInterrupt:
        print("Shutting down gracefully...")

if __name__ == "__main__":
    main()

def insert(*args):
    if not args:
        return "INSERT INTO users"
    else:
        n = len(args) - 1
        placeholders = ', '.join(f'(%s)' for _ in range(n))
        values = ', '.join(f'(%s)' for _ in range(n))
        return f"INSERT INTO users {placeholders} VALUES({values})"

def select(*args):
    if not args:
        return "SELECT FROM users"
    else:
        n = len(args) - 1
        placeholders = ', '.join(f'(%s)' for _ in range(n))
        values = ', '.join(f'(%s)' for _ in range(n))
