import os
import datetime
from shutil import copy2, rmtree
from pathlib import Path

class BackupManager:
    def __init__(self, backup_dir):
        self.backup_dir = backup_dir
        if not os.path.exists(self.backup_dir):
            os.makedirs(self.backup_dir)

    def create_backup(self, tenant_id, database_name):
        current_date = datetime.date.today()
        backup_path = f"{self.backup_dir}/tenant_{tenant_id}/{database_name}_backup_{current_date}.tar"
        try:
            copy2(f"{os.getcwd()}/{database_name}", backup_path)
            print(f"Backup created for tenant {tenant_id} and database {database_name}")
        except Exception as e:
            print(f"Failed to create backup: {e}")

    def delete_old_backups(self, days):
        current_date = datetime.date.today()
        old_date = current_date - datetime.timedelta(days=days)
        for file in os.listdir(self.backup_dir):
            if file.endswith(".tar") and os.path.getctime(os.path.join(self.backup_dir, file)) < old_date:
                try:
                    rmtree(os.path.join(self.backup_dir, file))
                    print(f"Deleted backup from {old_date}")
                except Exception as e:
                    print(f"Failed to delete backup: {e}")

    def list_backups(self):
        for file in os.listdir(self.backup_dir):
            if file.endswith(".tar"):
                print(file)

# Example usage
if __name__ == "__main__":
    backup_manager = BackupManager("/backup")
    backup_manager.create_backup("tenant1", "database1")
    backup_manager.delete_old_backups(7)
    backup_manager.list_backups()

