import os
import time
from logging import FileHandler, Logger, Info, Warning, Exception, Critical, Error
from logbook import RotatingFileHandler
import requests

# Configure the logger for secure logging to a file
log_file = "social medialogs.log"
sec_level = os.getenv("SECURITY_LEVEL") or "INFO"

class SocialMediaLogger:
    def __init__(self):
        self._logger = Logger(
            name="SocialMediaAPI",
            handlers=[
                RotatingFileHandler(
                    log_file,
                    maxBytes=1024 * 1024,  # 1MB per file
                    backupCount=5,          # Rotate every 5th copy
                    encoding="utf-8",
                    when="W*"
                )
            ],
            level=sec_level,
        )

    def info(self, message):
        self._logger.info(message)

    def warning(self, message):
        self._logger.warning(message)

    def error(self, message):
        self._logger.error(message)

    def critical(self, message):
        self._logger.critical(message)

def send_get_request(url, params=None):
    try:
        response = requests.get(
            url,
            params=params,
            timeout=10
        )
        if response.status_code >= 200 and response.status_code < 300:
            log = f"API Request to {url} made successfully"
            print(log)
            return response
    except Exception as e:
        # Catch all exceptions, including HTTP errors
        error = f"Failed to make API request: {str(e)}"
        if isinstance(e, requests.exceptions.TooManyRetries):
            log = f"Too many retries for URL: {url}"
        elif isinstance(e, requests.exceptions.Timeout) or isinstance(e, Exception):
            log = f"Request timeout occurred for URL: {url}"
        else:
            log = error

        # Log at appropriate level
        if sec_level == "INFO":
            log = error
        elif sec_level == "WARNING":
            log = warning(error)
        elif sec_level >= "ERROR":
            error(log)

    except KeyboardInterrupt:
        print("\nOperation cancelled.")

def main():
    social_media_urls = [
        {"name": "Instagram", "url": "https://api.instagram.com/api/v1/"},
        {"name": "Twitter", "url": "https://api.twitter.com"}
    ]

    for user in ["user1", "user2"]:
        params = {"username": user}
        print(f"\nLogging API requests for {user}")

        # Make the request and log
        try:
            response = send_get_request(
                social_media_urls[0]["url"],
                params=params
            )
            print(f"Successfully logged: {response}")
        except Exception as e:
            print(f"Error logging API request to Instagram: {e}")

        time.sleep(5)  # Small delay between requests

if __name__ == "__main__":
    main()

def translate(input_string, translation_table):
    output_string = ""
    for char in input_string:
        if char in translation_table:
            output_string += translation_table[char]
        else:
            output_string += char
    return output_string

