import os
from dotenv import load_dotenv

# Load the API key from the environment variables
load_dotenv()
API_KEY = os.getenv("API_KEY")

# Use a secure hashing function to hash the API key
hashed_api_key = hashlib.sha256(API_KEY.encode()).hexdigest()

# Store the hashed API key in a database or other secure storage
database = {
    "user": {
        "id": 1,
        "api_key": hashed_api_key
    }
}

# When the user wants to make an API request, retrieve their hashed API key from the database and compare it with the hashed API key sent in the request headers. If they match, allow the request, otherwise, deny it.
def check_api_key(request):
    # Get the API key sent in the request headers
    api_key = request.headers.get("X-API-Key")

    # Hash the API key and compare it with the hashed API key stored in the database
    if hashlib.sha256(api_key.encode()).hexdigest() == database["user"]["api_key"]:
        return True
    else:
        return False

import serial
from htttputty import HTTPClient, SerialHTTPClient
from coaprtty import CoAPClient
import time
import threading

class DeviceManager:
    def __init__(self, port):
        self.port = port
        self.http_client = None
        self.coap_client = None
        self Serail clients for both protocols.
        self.online_stream = None  # HTTP stream
        self.offline_stream = None  # CoAP stream
        self.running = True

    def detectOnline(self):
        try:
            if hasattr(self, 'network') and hasattr(self.network, 'adapter'):
                adapter = getattr(self.network, 'adapter', None)
                if isinstance(adapter, bytes):
                    adapter = adapter.decode()
                else:
                    adapter = str(adapter)
                if hasattr(adapter, 'hasdata'):
                    return True
        except Exception as e:
            pass
        return False

    def setupProxies(self):
        try:
            # HTTP client for online devices
            self.http_client = HTTPClient(serial.Serial(self.port, 9600))
            print("HTTP proxy initialized")

            # CoAP client for offline devices
            self.coap_client = CoAPClient(serial.Serial(self.port, 9600))
            print("CoAP proxy initialized")
        except Exception as e:
            raise RuntimeError(f"Failed to initialize proxies: {e}")

    def updateStreams(self):
        try:
            # Check online status every second
            if self.detectOnline():
                self.online_stream.update(self.getOnlineData())
            else:
                self.offline_stream.update(self.getOfflineData())
        except Exception as e:
            print(f"Error updating stream: {e}")
        finally:
            time.sleep(1)

    def getOnlineData(self):
        # Simulate online data retrieval (e.g., from HTTP)
        return f"Online data received"

    def getOfflineData(self):
        # Simulate offline data retrieval (e.g., from CoAP)
        return "No internet, using CoAP"

    def startEventLoop(self):
        update_thread = threading.Thread(target=self.updateStreams)
        update_thread.daemon = True
        update_thread.start()

        while self.running:
            time.sleep(1)

    def switchToCoAP(self):
        if not hasattr(self, 'coap_client'):
            raise RuntimeError("CoAP client not initialized")
        try:
            # Switch from HTTP proxy to CoAP
            self.http_client.close()
            print("Switching to CoAP proxy")
        except Exception as e:
            print(f"Error switching to CoAP: {e}")

    def switchToHTTP(self):
        if not hasattr(self, 'http_client'):
            raise RuntimeError("HTTP client not initialized")
        try:
            # Switch from CoAP proxy to HTTP
            self.coap_client.close()
            print("Switching to HTTP proxy")
        except Exception as e:
            print(f"Error switching to HTTP: {e}")

def main():
    port = "COM5"  # Replace with your serial port
    device_manager = DeviceManager(port)
    device_manager.setupProxies()
    device_manager.startEventLoop()

if __name__ == "__main__":
    main()

import heapq

class Event:
    def __init__(self, timestamp, name):
        self.timestamp = timestamp
        self.name = name

class EventQueue:
    def __init__(self):
        self.queue = []

    def add_event(self, event):
        # push the event to the queue with its timestamp
        heapq.heappush(self.queue, (event.timestamp, event))

    def get_events(self):
        while len(self.queue) > 0:
            _, event = heapq.heappop(self.queue)
            yield event

