def validate_input(input_value, required_fields, optional_fields=None):
    """
    Validate form input values.

    Args:
        input_value (str): The input value to validate.
        required_fields (dict): Dictionary containing required fields and their expected values.
        optional_fields (dict, optional): Dictionary containing optional fields that can be missing.

    Returns:
        dict: A dictionary containing validation results with pass/fail status and error messages for each field.
    """
    # Check required fields
    validation_results = {}
    for field, value in required_fields.items():
        actual_value = input_value.get(field)
        if not isinstance(actual_value, type(value)):
            return {
                'error': True,
                'fields': {
                    'required': False,
                    'optional': False,
                    'field_errors': []
                },
                'errors': [
                    f"Type mismatch: Expected {type(value)} for field '{field}' but got {type(actual_value)}"
                ]
            }
        if actual_value != value:
            validation_results.setdefault('fields', {}).setdefault('required', False)
            validation_results.setdefault('fields', {}).setdefault('optional', False)
            validation_results.setdefault('fields', {}).setdefault('field_errors', []).append(
                f"Field '{field}' failed validation: {actual_value}"
            )

    # Check optional fields
    if not optional_fields:
        optional_fields = required_fields.copy()

    for field, value in optional_fields.items():
        actual_value = input_value.get(field)

        if isinstance(actual_value, type(value)) and (isinstance(value, str) or isinstance(value, int)):
            pass
        else:
            validation_results.setdefault('fields', {}).setdefault('optional', False)
            validation_results.setdefault('fields', {}).setdefault('field_errors', []).append(
                f"Optional field '{field}' not present: {actual_value}"
            )

    return {
        'status': True,
        'fields': validation_results,
        'errors': []
    }

class QueueOverflowError(Exception):
    pass

class Queue:
    def __init__(self, capacity):
        self.queue = []
        self.capacity = capacity  # max size of the queue

    def enqueue(self, item):
        if len(self.queue) >= self.capacity:
            raise QueueOverflowError('Queue Overflow')
        else:
            self.queue.append(item)

    def dequeue(self):
        if len(self.queue) < 1:
            return "Queue is empty"
        return self.queue.pop(0)  # pop the first item in the queue (FIFO)

    def size(self):
        return len(self.queue)

