class AudioVideoSafeStorage:
    def __init__(self, key: bytes):
        self.key = key
        self.random_bytes = os.urandom(16)
        self3des_key = b'\x00' * 24 + binascii.unhexlify('c0c1c2')
        self.aes_iv = os.urandom(16)

    def _encrypt_file(self, file_path: str, content: bytes) -> Tuple[bytes, Dict[str, Any]]:
        with open(file_path, 'wb') as f:
            try:
                aes_ciphertext = self.aes_encrypt(content, key=self.key, iv=self.aes_iv)
                encrypted_header = base64.b64encode(f"file_type:a3d2;key_version:1.0;datetime creation: {datetime.now().isoformat()};size Creation: {os.path.getsize(file_path)}; integrity_check: 0".encode())
                return (base64.b64encode(aes_ciphertext).decode(), {'encrypted_headers': encrypted_header.decode(), 'version': '1.0', 'key': self.key, 'iv': self.aes_iv})
            except Exception as e:
                raise RuntimeError(f"Failed to encrypt file {file_path}: {str(e)}") from None

    def aes_encrypt(self, content: bytes, key: bytes, iv: bytes) -> bytes:
        import os
        from Crypto.Cipher import AES
        cipher = AES.new(key, mode=AES.MODE_XTS, nonce=iv)
        return b64encode(cipher.encrypt(content))  # Base64 encode the ciphertext

    def aes_decrypt(self, content: bytes, key: bytes, iv: bytes) -> bytes:
        import os
        from Crypto.Cipher import AES
        cipher = AES.new(key, mode=AES.MODE_XTS, nonce=iv)
        return b64decode(cipher.decrypt(content).replace(b'==', b'\n'))  # Base64 decode and clean up

    def _save(self, file_path: str, content: bytes):
        try:
            encrypted_part, headers = self._encrypt_file(file_path, content)
            with open(file_path, 'wb') as f:
                f.write(encrypted_part)
            return headers
        except Exception as e:
            raise RuntimeError(f"Failed to save file {file_path}: {str(e)}")

    def _load(self, file_path: str) -> Tuple[bytes, Optional[Dict]]:
        with open(file_path, 'rb') as f:
            try:
                encrypted_file = f.read()
                aes_part = encrypted_file.split(b'\n')[0].split(';')[1]
                aes_ciphertext = base64.b64decode(aes_part)
                decrypted_content = self.aes_decrypt(aes_ciphertext, key=self.key, iv=self.aes_iv)
                return (decrypted_content, None)  # No additional headers for loading
            except Exception as e:
                raise RuntimeError(f"Failed to load file {file_path}: {str(e)}")

    def _verify_integrity(self, file_path: str):
        with open(file_path, 'rb') as f:
            try:
                encrypted_file = f.read()
                aes_part = encrypted_file.split(b'\n')[0].split(';')[1]
                decrypted(aes_part)  # Should not throw an error if integrity is verified
            except ValueError:
                raise RuntimeError(f"File {file_path} integrity check failed")

