import time
import os

def scheduler(task_func, interval):
    """Decorator to schedule periodic tasks."""

    def wrapper(*args, **kwargs):
        task_id = id(task_func)  # Unique identifier for the task

        def _schedule():
            try:
                time.sleep(interval)
                task_func(*args, **kwargs)
            except Exception as e:
                print(f"Error executing task: {e}")
                os._exit(1)

        while True:
            try:
                os.fork()  # Fork a new process to run the task
                _schedule()
                os._exit(0)  # Exit the child process after scheduling

            except OSError as e:
                if e.errno == os.E_FAULT:
                    break  # Prevent rescheduling existing tasks

    return wrapper

def main():
    print("Creating scheduler...")

    # Define some tasks
    def task1():
        import logging
        logger = logging.getLogger(__name__)
        logger.info("User1 logged in")

    task2 = lambda: os.system("python3 example.py")  # Run another script every hour

    # Schedule the tasks
    scheduler(task1, 300)   # Every 5 minutes
    scheduler(task2, 60 * 60)  # Every hour

if __name__ == "__main__":
    main()

