import re
from datetime import datetime, timedelta

class CronJob:
    def __init__(self, minute, hour, day_of_month, month, day_of_week, command):
        self.minute = minute
        self.hour = hour
        self.day_of_month = day_of_month
        self.month = month
        self.day_of_week = day_of_week
        self.command = command

    def __str__(self):
        return f"{self.minute} {self.hour} {self.day_of_month}/{self.month}/{self.day_of_week} {self.command}"

def check_overlap(job1, job2):
    # Check for minute overlap
    if job1.minute == job2.minute:
        return True

    # Check for hour overlap
    if (job1.hour == 0 and job1.minute > 0) or (job1.hour != 0 and job1.minute < 60) and \
       (job2.hour == 0 and job2.minute > 0) or (job2.hour != 0 and job2.minute < 60):
        return True

    # Check for day overlap
    if job1.day_of_month == job2.day_of_month:
        return True

    # Check for month overlap
    if job1.month == job2.month:
        return True

    # Check for day of week overlap
    if job1.day_of_week == job2.day_of_week:
        return True

    return False

def suggest_modification(job1, job2):
    overlap = check_overlap(job1, job2)
    if not overlap:
        print("No overlap detected.")
        return

    # Suggest modifications based on the overlap
    if job1.minute == job2.minute and (job1.hour != 0 or job1.day_of_month != job2.day_of_month):
        print(f"Overlap in minutes. Consider modifying the day of month ({job1.day_of_month}) to {job2.day_of_month}.")
    elif job1.hour == job2.hour:
        if job1.minute > 0 and job2.minute > 0:
            print("Overlap in hours. Consider reducing one or both minute values.")
        else:
            print(f"Overlap in hours. Consider modifying the day of month ({job1.day_of_month}) to {job2.day_of_month}.")
    elif job1.day_of_month == job2.day_of_month and (job1.hour != 0 or job1.minute != 0):
        print(f"Overlap in days of month. Consider reducing one or both hour/minute values.")
    elif job1.month == job2.month and (job1.day_of_week != job2.day_of_week or job1.hour != 0 or job1.minute != 0):
        print(f"Overlap in months. Consider reducing one or both hour/minute values.")

