    # Define two cron jobs
    job1 = CronJob(0, 8, 15, 6, 'monday', 'command1')
    job2 = CronJob(0, 16, 20, 7, 'tuesday', 'command2')

    print("Cron Job 1:", job1)
    print("Cron Job 2:", job2)

    # Check for overlap and suggest modifications
    check_overlap(job1, job2)

class ShoppingCart:
    def __init__(self):
        self.cart = {}  # Initialize an empty dictionary

    def add_item(self, item, price, quantity=1):
        if item in self.cart:
            print("Item already exists in the cart. Use update_quantity() to modify quantity.")
            return False

        self.cart[item] = {'price': price, 'quantity': quantity}
        return True

    def remove_item(self, item):
        if item not in self.cart:
            print("Item doesn't exist in the cart.")
            return False

        del self.cart[item]
        return True

    def update_quantity(self, item, quantity):
        if item not in self.cart:
            print("Item doesn't exist in the cart.")
            return False

        self.cart[item]['quantity'] = quantity
        return True

    def total_cost(self):
        total = 0
        for item, details in self.cart.items():
            total += details['price'] * details['quantity']

        return total

import sys

def main():
    options = {}
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split('&')
        for part in parts:
            if not part:
                continue
            key_value = part.split('=', 1)
            if len(key_value) < 2:
                options.setdefault(key_value[0], []).append(None)
            else:
                key = key_value[0].strip()
                val = key_value[1].strip()
                if '%' in val or '.' in val:
                    try:
                        # Handle percentages and decimals
                        options[key] = float(val)
                    except ValueError:
                        pass  # skip invalid conversion
                elif 'true' in val.lower() or 'false' in val.lower():
                    options[key] = (val.lower() == 'true')
                else:
                    if val.strip() == '':
                        options[key] = ''
                    else:
                        try:
                            # Try to convert to integer, handle boolean-like strings
                            if '.' not in val and val.upper() != 'TRUE':
                                options[key] = int(val)
                            else:
                                options[key] = val
                        except ValueError:
                            options[key] = val  # keep as string if conversion fails

    for key, value in options.items():
        print(f"{key}: {value}")

