from datetime import datetime, timedelta

class Cache:
    def __init__(self):
        self.cache = {}

    # Set an item in the cache with expiration time (seconds)
    def set(self, key, value, ex=60):
        expire_time = datetime.now() + timedelta(seconds=ex)
        self.cache[key] = {"value": value, "expire_at": expire_time}

    # Get an item from the cache if it hasn't expired
    def get(self, key):
        if key in self.cache:
            if self.cache[key]["expire_at"] > datetime.now():
                return self.cache[key]["value"]
            else:
                # Remove the expired entry
                del self.cache[key]
        return None

    # Delete an item from the cache
    def delete(self, key):
        if key in self.cache:
            del self.cache[key]

