from collections import deque

class Queue:
    def __init__(self):
        self.queue = deque()

    # Add an element to the queue
    def enqueue(self, item):
        try:
            self.queue.append(item)
        except MemoryError as e:
            print(f"Memory Error: {e}")
            return None  # Return None if memory error occurs

    # Remove an element from the queue
    def dequeue(self):
        try:
            if len(self.queue) < 1:
                return None  # Return None if queue is empty
            return self.queue.popleft()
        except MemoryError as e:
            print(f"Memory Error: {e}")
            return None  # Return None if memory error occurs

    # Check the size of the queue
    def size(self):
        try:
            return len(self.queue)
        except MemoryError as e:
            print(f"Memory Error: {e}")
            return -1  # Return -1 if memory error occurs

# Example usage
if __name__ == "__main__":
    q = Queue()

    # Enqueue elements
    for i in range(10):
        q.enqueue(i)

    # Check queue size
    print(f"Queue Size: {q.size()}")

    # Dequeue elements
    while True:
        item = q.dequeue()
        if item is not None:
            print(item)
        else:
            break

