import hashlib

# Generate a unique session token
def generate_session_token():
    return hashlib.sha256(str(time.time()).encode()).hexdigest()

# Store the session token in a secure location
session_token = generate_session_token()

# Function to check for replay attacks
def prevent_replay_attacks(request):
    # Check if the request contains a session token
    if 'session_token' not in request.headers:
        return False

    # Get the session token from the request header
    received_token = request.headers['session_token']

    # Check if the session token matches the stored token
    if received_token != session_token:
        return False

    # If the session token matches, the request is valid
    return True

# Example usage
