import re

class InputValidator:
    def __init__(self, min_value=None, max_value=None):
        self.min_value = min_value
        self.max_value = max_value

    def validate_input_data(self, data):
        """Validate if the input data is not empty."""
        if not data:
            raise ValueError("Input data cannot be empty")

    def validate_data_type(self, data, expected_type):
        """Validate if the input data conforms to a specific data type."""
        if not isinstance(data, expected_type):
            raise TypeError(f"Expected {expected_type.__name__}, but got {type(data).__name__}")

    def validate_range(self, data, min_value=None, max_value=None):
        """Validate if the input falls within a specified range."""
        if self.min_value is None and self.max_value is None:
            return True
        if min_value is not None and data < min_value:
            raise ValueError(f"Value {data} is less than the minimum allowed value {min_value}")
        if max_value is not None and data > max_value:
            raise ValueError(f"Value {data} is greater than the maximum allowed value {max_value}")

# Example usage:

validator = InputValidator(min_value=1, max_value=100)

def ai_model_input_validation(data):
    """Validate AI model inputs."""
    try:
        validator.validate_input_data(data)
    except ValueError as e:
        print(f"Error: {e}")
        return False

    if isinstance(data, int) or isinstance(data, float):
        validator.validate_data_type(data, (int, float))
    else:
        raise TypeError("Invalid data type")

    try:
        validator.validate_range(data)
    except ValueError as e:
        print(f"Error: {e}")
        return False

    # Successful validation
    return True

