# Report Filtering Script

def read_report_data():
    """Reads report data from standard input"""
    print("Reading report data...")
    lines = []
    for _ in range(10):  # Read the first 10 lines as demo data
        line = input().strip()
        if not line:
            break  # Stop reading if empty line is encountered
        lines.append(line)
    return lines

def validate_report_data(record):
    """Validates each field of a report record"""
    valid_records = []
    for i, value in enumerate(record):
        try:
            if isinstance(value, str) and len(value.strip()) < 5:
                raise ValueError(f"Field {i+1} is too short")
            elif isinstance(value, (int, float)) and not (MIN_VALIDATION <= value <= MAX_VALIDATION):
                raise ValueError(f"Field {i+1} out of range")
        except Exception as e:
            print(f"Validation error for field {i+1}: {e}")
    return valid_records

def apply_filters(records, filters):
    """Applies dynamic filters to the report records"""
    filtered_records = []
    for record in records:
        keep_record = True
        for filter in filters:
            condition = filter['condition']
            value = filter['value']
            match = False
            for field in record:
                if condition == 'contains':
                    if str(field).lower().find(str(value).lower()) != -1:
                        match = True
                        break
                elif condition == 'equals':
                    if field == value:
                        match = True
                        break
                else:
                    # Additional conditions can be added here
                    pass
            if not match and filter['keep']:
                keep_record = False
        if keep_record:
            filtered_records.append(record)
    return filtered_records

def sort_report(records, columns=None):
    """Sorts the report data based on specified columns"""
    sorted_records = []
    if columns is None:
        columns = ['']
    for record in records:
        # Simple sorting implementation (you can enhance it based on your needs)
        sorted_record = list(record)
        try:
            for col in range(len(columns)):
                sort_key = record[col]
                if isinstance(sort_key, str):
                    parts = sort_key.split(',')
                    primary_sort = parts[0].strip()
                    secondary_sort = parts[1].strip() if len(parts) > 1 else ''
                    sorted_record[col] = f"{primary_sort}:{secondary_sort}"
        except Exception as e:
            print(f"Sorting error: {e}")
        sorted_records.append(tuple(sorted_record))
    return sorted_records

def save_report(records, filename="output.txt"):
    """Saves the report data to a file"""
    with open(filename, 'w') as f:
        for record in records:
            line = ",".join(map(str, record)) + "\n"
            f.write(line)
    print(f"Report saved to {filename}")

# Example usage
def main():
    print("Dynamic Report Filter Generator")
    report_data = read_report_data()

    # Define your filters here as list of dictionaries with 'condition' and 'value'
    filters = [
        {'condition': 'contains', 'value': 'Risk'},
        {'condition': 'equals', 'value': 100},
        # Add more fields for additional conditions
    ]

    print("\nReport Data Before Filtering:")
    for record in report_data:
        print(record)

    try:
        validated_records = validate_report_data(report_data)

        sorted_records = sort_report(validated_records, ['Start Date', 'Risk Level'])

        # Apply dynamic filters to the sorted records
        filtered_records = apply_filters(sorted_records, filters)

        for record in filtered_records:
            print("\n".join(map(str, record)))

    except Exception as e:
        print(f"Error processing report data: {e}")

    # Save filtered report (optional)
    save_report(filtered_records)

if __name__ == "__main__":
    main()

