import os
from PyPDF2 import PdfMerger, PdfReader

def merge_pdfs(input_dir='.', output_filename='merged.pdf'):
    try:
        merger = PdfMerger()

        # Get list of PDF files in input directory
        pdf_files = [f for f in os.listdir(input_dir) if f.endswith('.pdf')]

        if not pdf_files:
            print("No PDF files found in the specified directory.")
            return

        for file_path in pdf_files:
            with open(file_path, 'rb') as f:
                reader = PdfReader(f)
                merger.addDocument(reader)

        # Ensure output filename is a string
        if isinstance(output_filename, str):
            out_path = os.path.expanduser(output_filename) if (output_filename == 'merged.pdf') else output_filename
        else:
            print("Output filename must be a string.")
            return

        merger.write(out_path)

    except Exception as e:
        print(f"Error merging PDF files: {e}")

