class RestrictedQueryDepth:
    def __init__(self, max_depth):
        self.max_depth = max_depth
        self.current_depth = 0

    def query(self, func):
        def wrapper(*args, **kwargs):
            if self.current_depth >= self.max_depth:
                raise ValueError(f"Max query depth exceeded ({self.current_depth}/{self.max_depth})")

            try:
                result = func(*args, **kwargs)
            except Exception as e:
                raise ValueError(f"Error in query: {str(e)}")

            # Increase the current depth
            self.current_depth += 1

            # If recursive calls are expected, we'll decrease the current depth after execution
            if isinstance(result, (list, tuple)):
                result = [self.query(sub_func) for sub_func in result]

            return result

        wrapper.max_depth = self.max_depth
        return wrapper


def example_query(func):
    @RestrictedQueryDepth(3).query(func)
    def _example_query(*args, **kwargs):
        pass

# Test the restricted query depth functionality
@example_query
def recursive_function(n):
    if n > 0:
        print(f"Recursive call {n}")
        return [recursive_function(n-1) for _ in range(5)]
    else:
        return []

try:
    result = recursive_function(10)
except ValueError as e:
    print(e)

from flask import Flask, request, jsonify
import hmac
import hashlib
import base64

app = Flask(__name__)

# This is a secret key that you should keep safe. It's used to verify the webhook signature.
SECRET_KEY = b"YourSecretKeyHere"

@app.route('/webhook', methods=['POST'])
def handle_webhook():
    # Verify the request's signature. This helps ensure that the request came from the service you expect.
    if not verify_signature(request):
        return jsonify({"error": "Invalid signature."}), 403

    # If the signature is valid, then we can handle the webhook event.
    event = request.headers.get('X-GitHub-Event')
    if event == 'push':
        return process_push(request)
    elif event == 'pull_request':
        return process_pull_request(request)
    else:
        return jsonify({"message": "Unhandled event."}), 200

def verify_signature(req):
    # Extract the signature from the request headers.
    signature = req.headers.get('X-Hub-Signature')
    if not signature:
        return False

    # Compute a hash of the request body using the secret key and compare it to the provided signature.
    sha_name, signature = signature.split("=")
    digest = hmac.new(SECRET_KEY, req.data, digestmod=hashlib.sha1).hexdigest()
    return hmac.compare_digest(signature, digest)

def process_push(req):
    # Your code to handle a push event goes here.
    return jsonify({"message": "Push received."}), 200

def process_pull_request(req):
    # Your code to handle a pull request event goes here.
    return jsonify({"message": "Pull request received."}), 200

if __name__ == '__main__':
    app.run()

