import json

class FileVersioning:
    def __init__(self, directory):
        self.directory = directory
        self.version_file = os.path.join(directory, ".versions.json")
        self.load_versions()

    def load_versions(self):
        if os.path.exists(self.version_file):
            with open(self.version_file, "r") as f:
                self.versions = json.load(f)
        else:
            self.versions = {}

    def save_versions(self):
        with open(self.version_file, "w") as f:
            json.dump(self.versions, f)

    def version_file(self, filename):
        file_path = os.path.join(self.directory, filename)
        if filename not in self.versions:
            self.versions[filename] = 0
        else:
            self.versions[filename] += 1
        self.save_versions()
        return f"{filename}-{self.versions[filename]}"

    def restore_file(self, filename):
        file_path = os.path.join(self.directory, filename)
        version = self.versions.get(filename)
        if version:
            restored_filename = f"{filename}-{version}"
            restored_path = os.path.join(self.directory, restored_filename)
            os.rename(restored_path, file_path)
            del self.versions[filename]
            self.save_versions()

import urllib.parse

def parse_urlencoded_data(query):
    if not isinstance(query, str) or not query:
        return 'Invalid input. Please provide a valid URL-encoded string.'

    try:
        parsed_result = urllib.parse.parse_qs(query)
    except Exception as e:
        return f'An error occurred while parsing the data: {str(e)}'

    return parsed_result

import dns.resolver

def check_spf(sender):
    # Retrieve the SPF record for the sending domain
    spf_record = dns.resolver.query("{}.com.".format(sender), "TXT")

    # Check if the sender's IP address is listed in the SPF record
    for entry in spf_record:
        if entry.startswith("v=spf1"):
            authorized_senders = entry[8:]
            if sender not in authorized_senders:
                return False
            else:
                return True

