function store($user, $password, &$api_token) {
    if (empty($user) || empty($password)) {
        return;
    }

    // Check authentication details once
    if ($user && $password) {
        if (check_auth($user, $password)) {
            $token = generate_session_token();
            // Append the token to session data storage (not shown here)
            add_session_token($token);
            // Indicate no further action needed for this user
            return;
        }
    }

    // If not authenticated or other parameters are provided, handle accordingly
    if ($api_token === null) {
        return; // No more tokens to store in this context
    } elseif (is_array($api_token)) {
        foreach ($api_token as $token) {
            store($user, $password, $token);
        }
    }
}

