import functools
import time
from typing import Any, Callable

def retry(func: Callable[..., Any] = None, /, *, max_retries: int = 3) -> Callable[..., Any]:
    """Decorator to retry a function up to `max_retries` times."""
    if func is None:
        return lambda f: retry(f, max_retries=max_retries)

    @functools.wraps(func)
    def wrapper(*args: Any, **kwargs: Any) -> Any:
        for i in range(1, max_retries + 1):
            try:
                return func(*args, **kwargs)
            except Exception as e:
                if i >= max_retries:
                    raise RetryError(f"Failed to {func.__name__} after {max_retries} attempts") from e

                time.sleep(2 ** i)  # exponential backoff

    return wrapper

@retry
def process_message(msg):
    """Process a message. If this fails, it will be retried up to three times."""
    print("processing message: ", msg)
    if random.random() < 0.25:  # simulate failure
        raise Exception("Message processing failed")

