import logging
from typing import Dict, List

class DependencyChangeLogger:
    def __init__(self):
        self.dependencies: Dict[str, str] = {}  # Initialize an empty dictionary to store dependencies
        self.logger = logging.getLogger(__name__)

    def add_dependency(self, package_name: str, version: str) -> None:
        """Add a new dependency to the logger"""
        if package_name in self.dependencies:
            self.logger.warning(f"Dependency {package_name} is already up-to-date. Skipping update.")
            return
        try:
            self.dependencies[package_name] = version  # Update the dependency with the latest version
            self.log_dependency_change(package_name, version)
        except Exception as e:
            self.logger.error(f"Failed to add dependency {package_name}: {e}")

    def remove_dependency(self, package_name: str) -> None:
        """Remove a dependency from the logger"""
        if package_name not in self.dependencies:
            self.logger.warning(f"No dependency found for {package_name}.")
            return
        try:
            del self.dependencies[package_name]  # Remove the dependency from the dictionary
            self.log_dependency_change(package_name, "Removed")
        except Exception as e:
            self.logger.error(f"Failed to remove dependency {package_name}: {e}")

    def update_dependency(self, package_name: str, version: str) -> None:
        """Update an existing dependency"""
        if package_name not in self.dependencies:
            self.logger.warning(f"No dependency found for {package_name}.")
            return
        try:
            old_version = self.dependencies[package_name]  # Get the current version of the dependency
            self.dependencies[package_name] = version  # Update the dependency with the new version
            if old_version != version:  # Check if the update was successful
                self.log_dependency_change(package_name, f"Updated from {old_version} to {version}")
        except Exception as e:
            self.logger.error(f"Failed to update dependency {package_name}: {e}")

    def log_dependency_change(self, package_name: str, message: str) -> None:
        """Log the dependency change"""
        self.logger.info(f"Dependency change for {package_name}: {message}")


def main():
    logger = DependencyChangeLogger()

    # Example usage
    logger.add_dependency("numpy", "1.22.3")
    logger.update_dependency("pandas", "1.4.2", "1.5.0")
    logger.remove_dependency("scikit-learn")

if __name__ == "__main__":
    main()

