import re
from secrets import token_urlsafe

class Logger:
    def __init__(self):
        self.sensitive_data = []

    def add_log(self, log_message):
        for match in re.finditer(r'\b\d{4}-\d{2}-\d{2}-(\d{1,3})-(\D*)', log_message):
            sensitive_info = match.group(0)
            masked_sensitive_info = self.mask_sensitive_data(sensitive_info)
            log_message = log_message.replace(sensitive_info, masked_sensitive_info)

        return log_message

    def mask_sensitive_data(self, sensitive_info):
        if sensitive_info in self.sensitive_data:
            return '[MASKED]'
        else:
            self.sensitive_data.append(sensitive_info)
            return token_urlsafe(6)  # generate a random 6-character string for masking


# Example usage
