import os
import argparse

def get_value(name):
    val = os.environ.get(name)
    if val:
        return f"{val}"
    else:
        print(f"Warning: {name} not found in environment variables.")
        return DEFAULTS[name]

DEFAULTS = {
    'DB_NAME': 'default_db',
    'DATABASE_PASS': 'securepassword',
    'PUBLIC_KEY': 'key_for everyone'
}

def main():
    env_keys = ['DATABASE_NAME', 'DB_PASSWORD', 'PUBLIC_KEY']

    configs = {}
    for key in DEFAULTS:
        configs[key] = get_value(key)

    # Parse command line arguments
    parser = argparse.ArgumentParser(description='Retrieve configuration values.')
    for key in env_keys:
        group = parser.add_argument_group(f'Args for {key}')
        group.add_argument(f"--{key}", type=str, help=f'Specify "{key}" value via command line')

    args = parser.parse_args()

    # Update configs with command line arguments
    for key in env_keys:
        if hasattr(args, key):
            configs[key] = getattr(args, key)

    # Print the final configuration values and their sources
    for key in DEFAULTS.keys():
        value = configs.get(key, None)
        if isinstance(value, str) or value is None:
            continue  # Skip None and string types which shouldn't happen
        source = 'environment' if configs[key] == os.environ.get(key) else 'commandline'
        print(f"{key}={source} {configs[key]}")

