def check_query(query):
    max_depth = 10  # set your desired maximum depth here
    depth = 0
    for ch in query:
        if ch == '(':
            depth += 1
        elif ch == ')':
            depth -= 1
        if depth > max_depth:
            raise ValueError("Query exceeds maximum allowed depth")
    return True

from threading import Queue, Lock

class Worker:
    def __init__(self, q, lock):
        self.queue = q
        self.lock = lock
        self.running = True

    def get(self, timeout=1):
        try:
            return self.queue.get(timeout=timeout)
        except BlockingIOError:
            return None

    def process_message(self, message):
        print(f"Worker {self.__class__.__name__} processing message: {message}")

    def run(self):
        while self.running:
            message = self.get()
            if message is None:
                break
            with self.lock:
                self.process_message(message)
        self.running = False

def main():
    q = Queue()
    num_workers = 4  # Number of worker threads to create

    for _ in range(num_workers):
        lock = Lock()  # Each thread has its own lock to prevent deadlocks
        worker = Worker(q, lock)
        worker.run()

if __name__ == "__main__":
    main()

