import sys
import json
from io import BytesIO

def parse_large_file(file_path):
    """Parse a large file efficiently and safely."""
    try:
        # Using BytesIO for incremental reading to handle large binary files
        with open(file_path, 'rb') as file:
            while True:
                chunk = file.read(4096)  # Read in chunks of 4KB
                if not chunk:
                    break

                # Decode the chunk to bytes and then parse JSON lines or other formats
                data = BytesIO(chunk).readline().strip()

                if not data:
                    continue

                # Process each line (or object, depending on file type)
                yield json.loads(data)

    except Exception as e:
        print(f"Error parsing file: {e}")
        raise

def main():
    import sys
    file_path = sys.argv[1]  # Get the first argument as file path

    try:
        for item in parse_large_file(file_path):
            process_item(item)

    except Exception as e:
        print(f"Error processing data: {e}")

