import time

def retry(max_retries=3, delay=2):
    """
    Retry decorator for failed tasks.

    Args:
        max_retries (int): Maximum number of retries.
        delay (int): Delay between retries in seconds.

    Returns:
        Callable: Decorated function.
    """

    def decorator(func):
        def wrapper(*args, **kwargs):
            for i in range(max_retries):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    print(f"Retry {i+1}/{max_retries} failed with error: {e}")
                    time.sleep(delay)
            raise Exception("Maximum retries reached.")
        return wrapper
    return decorator

@retry(max_retries=5, delay=3)
def critical_task():
    # Code for critical task goes here.
    # If task fails, raise an exception.
    raise Exception("Critical task failed.")

try:
    critical_task()
except Exception as e:
    print(f"Critical task failed with final error: {e}")

def search_data(data, filters):
    result = []
    for item in data:
        match = True
        for key, value in filters.items():
            if key not in item or item[key] != value:
                match = False
                break  # No need to check further once a condition fails
        if match:
            result.append(item)
    return result

