from http import HTTPStatus
from urllib.parse import urlparse, parse_qs
import os

class AdminRestrictor:
    def __init__(self):
        # Set the allowed hosts for admin access
        self.allowed_hosts = ['admin.example.com', 'localhost']

        # Initialize a dictionary to store the user roles
        self.user_roles = {
            'user': {'read': True, 'write': False},
            'admin': {'read': True, 'write': True}
        }

    def authenticate_user(self, username, password):
        """Authenticate a user based on their credentials."""
        # Check if the username and password match any stored credentials
        for user in self.user_roles:
            if username == user and password == self.user_roles[user]['password']:
                return True
        return False

    def check_allowed_host(self, request):
        """Check if the client is allowed to access admin resources."""
        # Get the host from the URL
        parsed_url = urlparse(request)
        if parsed_url.netloc not in self.allowed_hosts:
            return False
        return True

    def authenticate_request(self, request, username, password):
        """Authenticate a user for a specific request."""
        if not self.authenticate_user(username, password) or not self.check_allowed_host(request):
            return HTTPStatus.UNAUTHORIZED, {"error": "Authentication failed"}

        # Return the allowed status
        return HTTPStatus.OK

def restrict_admin_access(request, username, password):
    """Restrict access to admin resources based on authentication and host checks."""
    restrictor = AdminRestrictor()
    return restrictor.authenticate_request(request, username, password)

# Example usage:
if __name__ == "__main__":
    # Create a simple HTTP server
    from http.server import BaseHTTPRequestHandler, HTTPServer

    class RequestHandler(BaseHTTPRequestHandler):
        def do_GET(self):
            """Handle GET requests."""
            if 'admin' in self.path:
                return restrict_admin_access(self.requestline, None, None)

        def do_POST(self):
            """Handle POST requests."""
            # If the request is not for admin resources, allow it
            if 'admin' not in self.path:
                self.send_response(HTTPStatus.OK)
                return

            # Authenticate the user
            try:
                username = parse_qs(self.headers.get('Authorization', [''])[0])[0]
                password = parse_qs(self.content.decode())[0][0]

                return_code, content = restrict_admin_access(self.requestline, username, password)

                self.send_response(return_code)
                if isinstance(content, dict):
                    self.end_headers()
                    self.wfile.write(str(content).encode())
                else:
                    self.end_headers()
            except Exception as e:
                # If authentication fails or the host is not allowed, return an error
                return_code = HTTPStatus.UNAUTHORIZED
                content = {"error": str(e)}
                if isinstance(content, dict):
                    self.send_response(return_code)
                    self.end_headers()
                    self.wfile.write(str(content).encode())
                else:
                    self.send_response(return_code)
                    self.send_header('Content-type', 'application/json')
                    self.end_headers()
                    self.wfile.write(content.encode())

    server_address = ('localhost', 8000)
    httpd = HTTPServer(server_address, RequestHandler)

    print("Starting server on localhost:8000")
    httpd.serve_forever()

