class ConsensusMechanism:
    def __init__(self, num_nodes):
        self.num_nodes = num_nodes
        self.votes = [random.randint(0, 1) for _ in range(num_nodes)]

    def validate(self):
        # Count votes
        votes_count = self.votes.count(1)

        # Check if a majority of nodes agree (5/6 in this example)
        if votes_count >= self.num_nodes // 2 + 1:
            return True, "Consensus reached"
        else:
            return False, "No consensus reached"

