def log_transaction(transaction, logger):
    log_entry = {
        'timestamp': datetime.now().isoformat(),
        'amount': transaction.amount,
        'date': str(transaction.date),
        'time': str(transaction.time),
        'location_id': transaction.location_id,
        'merchant_id': transaction.merchant_id,
        'card_number': transaction.card_number,
        'is_fraud': transaction.is_fraud(user)
    }
    logger.info(str(log_entry))

def detect_fraud(transactions, fraud_thresholds):
    # Moving average window size
    WINDOW_SIZE = 5

    # Track recent transactions for each card
    recent_transactions = {}

    for t in transactions:
        log_transaction(t, logger)

        # Determine if transaction is fraudulent
        is_fraud = False

        # Check for multiple charges from same card within minutes
        if t.card_number in recent_transactions:
            consecutive_large_trans = sum(1 for _ in range(WINDOW_SIZE) 
                                          if recent_transactions[t.card_number][-1]['amount'] > 0.5*t.amount)
            if consecutive_large_trans >= 2 and t.amount > 0.5*max(recent_transactions[t.card_number][-1]['amount']):
                is_fraud = True

        # Check for large amount compared to average
        avg_amount = sum([tx['amount'] for tx in recent_transactions.get(t.card_number, [])]) / max(1, len(recent_transactions.get(t.card_number, [])))
        if t.amount > 3*avg_amount:
            is_fraud = True

        # Check for geographic anomalies
        location_distinctness = len(set(recent_transactions[t.card_number][-1]['location_id']))
        merchant_density = sum([tx['merchant_id'] in recent_transactions[t.card_number][-1]['merchant_id'] 
                              for tx in recent_transactions.get(t.card_number, [])])

        if location_distinctness < 2 or merchant_density < 3:
            is_fraud = True

        # Update recent transactions
        if t.card_number not in recent_transactions:
            recent_transactions[t.card_number] = []
        recent_transactions[t.card_number].append(t)

    return any([tx['is_fraud'] for tx in recent_transactions.values()])

