def is_cronjob_duplicate(new_cronjob):
    with open('/etc/crontab', 'r') as cronfile:
        lines = cronfile.readlines()
        for line in lines:
            if new_cronjob == line.strip():
                return True
    return False

def add_cronjob(new_cronjob):
    if not is_cronjob_duplicate(new_cronjob):
        with open('/etc/crontab', 'a') as cronfile:
            cronfile.write(f"{new_cronjob}\n")
        print("Cron job added successfully.")
    else:
        print("Duplicate entry found, skipping addition of new cron job.")

