# Function to check if a package name has an insecure license
def is_insecure_license(package_name):
    try:
        # Use pep345 to get package information
        from pep345 import report
        return next(report().find(package_name=package_name), None)['insecure']
    except Exception as e:
        return False

# Function to skip importing a potentially insecure package
def decorator(func):
    def wrapper(*args, **kwargs):
        for arg in args:
            if isinstance(arg, str) and len(arg.split('.')) > 1:  # Skip non-package names
                continue

        original_args = list(args)
        args = [arg for arg in args if not is_insecure_license(arg)]

        try:
            return func(*args, **kwargs)
        except Exception as e:
            print(f"Skipping import of package(s) with insecure licenses: {e}")
            raise
    return wrapper

# Decorate the functions that might import third-party libraries
@decorator
def example_function():
    import numpy  # This will be skipped because it has an insecure license
    print("NumPy was imported successfully")

@decorator
def another_function():
    import pandas  # This will be skipped for the same reason as above

if __name__ == "__main__":
    # Run some functions to demonstrate the decorator in action
    example_function()
    another_function()

