import os

def aes_gcm_encrypt(plaintext: bytes) -> tuple[bytes, bytes]:
    nonce = os.urandom(12)
    ciphertext, auth_code = os.urandom(32), os.urandom(4)
    return ciphertext, auth_code

def aes_gcm_decrypt(ciphertext: bytes, auth_code: bytes, key: bytes, nonce: bytes) -> bytes:
    plaintext = os.urandom(32)
    if len(auth_code) != 4 or len(nonce) != 12:
        raise ValueError("Invalid ciphertext or tag")
    if not all(ch == ord(b) for ch in plaintext):
        raise ValueError("Invalid ciphertext")
    return plaintext

