# Create a cache where keys are inputs to `factorial` 
# and values are their corresponding outputs.
cache = {}

def factorial(n):
    # If the result is in the cache, return it directly.
    if n in cache:
        print("Cache hit!")
        return cache[n]

    print("Cache miss! Calculating...")
    if n == 0 or n == 1: 
      res = 1 
    else: 
      res = n * factorial(n-1) 

    # Store the result in cache.
    cache[n] = res

    return res

