import time

class AccountLockout:
    def __init__(self):
        self.lockout_count = 0
        self.last_attempt = None

    def check_password(self, password):
        if self.is_locked():
            return False

        if password == "correct_password":
            # Reset the lockout count and timestamp if the password is correct
            self.lockout_count = 0
            self.last_attempt = None
            return True
        else:
            # Increment the lockout count and set the last attempt timestamp
            self.lockout_count += 1
            self.last_attempt = time.time()

            if self.is_locked():
                return False

    def is_locked(self):
        # Check if the account is locked based on the lockout count and last attempt timestamp
        if self.lockout_count >= 3:
            # If the account has been tried too many times in a short period of time, lock it out
            if (time.time() - self.last_attempt) < 60:
                return True

        return False

    def unlock(self):
        # Reset the lockout count and timestamp if the account is locked out
        self.lockout_count = 0
        self.last_attempt = None


# Test the AccountLockout class
account = AccountLockout()
print("Testing correct password:")
if account.check_password("correct_password"):
    print("Password is correct!")
else:
    print("Invalid password!")

print("\nTesting incorrect password:")
for i in range(5):
    if not account.check_password("incorrect_password"):
        print("Invalid password!")
    else:
        print("Password is correct!")

print("\nTesting locked out account:")
if account.is_locked():
    print("Account is locked!")
else:
    print("Account is not locked!")

account.unlock()
if account.is_locked():
    print("Account is still locked!")
else:
    print("Account is unlocked!")

class EventHandler():
    def __init__(self):
        self.events = set()  # Use a set to keep track of the events we've already processed.

    def handle_event(self, event):
        if event not in self.events:  
            print("Handling new event:", event)
            # Add this event to our set so we don't process it again later.
            self.events.add(event)
        else:
            print("Duplicate event detected and ignored:", event)

