import time
import threading
from queue import Queue

class WorkerThread(threading.Thread):
    def __init__(self, queue, *args, **kwargs):
        self._queue = queue
        super().__init__(*args, **kwargs)
        self._counter = 0

    @property
    def counter(self):
        return self._counter

    def run(self):
        while True:
            item = self._queue.get()
            if item is None:  # Sentinel value to stop the thread
                break
            self._process_item(item)

    def _process_item(self, item):
        """Process the item"""
        print('processing', item)
        time.sleep(0.1)  # Simulate some work being done.
        self._counter += 1

class MonitorThread(threading.Thread):
    def __init__(self, workers, *args, **kwargs):
        self._workers = workers
        super().__init__(*args, daemon=True, **kwargs)

    def run(self):
        while True:
            time.sleep(1)  # Check every second
            rate = sum(w.counter for w in self._workers)
            print('Processed', rate, 'items per second')

# Create some workers and a monitor thread.
queue = Queue()
worker_threads = [WorkerThread(name='Worker-%d' % i, queue=queue) for i in range(4)]
monitor_thread = MonitorThread(workers=worker_threads, name='Monitor')

# Start the worker threads and the monitor.
for t in worker_threads:
    t.start()

monitor_thread.start()

# Put some items into the queue.
for i in range(10):
    for _ in range(20):  # Adding 20 messages to the queue per second, simulating a load
        queue.put('item')

time.sleep(5)  # Simulate work being done for 5 seconds.

# Stop all worker threads.
for _ in worker_threads:
    queue.put(None)

for t in worker_threads:
    t.join()

import gc
import sys

def prevent_leakage(iterable):
    items = []
    for item in iterable:
        try:
            del item  # Attempt to delete the item immediately
        except Exception as e:  # Catch any exceptions during deletion
            pass  # Log or handle as needed; Python may clean up automatically

    # After the loop, collect remaining eligible objects
    while gc.collect():
        pass

    return items

