import queue
from concurrent.futures import ThreadPoolExecutor, as_completed
import time

def run_func(func, *args):
    try:
        start = time.time()
        result = func(*args)
        elapsed = time.time() - start
        if elapsed > 5:  # timeout after 5 seconds
            raise Exception("Function timed out")
        return result
    except Exception as e:
        print(f"Exception occurred: {e}")
        q.put(str(e))

def handle_timeout(funcs, *args):
    q = queue.Queue()
    results = []

    with ThreadPoolExecutor(max_workers=4) as executor:
        futures = [executor.submit(run_func, f, *args) for f in funcs]

        try:
            for future in as_completed(futures):
                if future.exception() is not None and isinstance(future.exception(), Exception):
                    error_type, _, _ = sys.exc_info()
                    q.put(str(future.exception()))
                else:
                    results.append(future.result())
        except StopIteration:
            pass

    return results, q.get()

