import subprocess
import pkg_resources
from pkg_resources import DistributionNotFound, VersionConflict

def update(package):
    try:
        subprocess.check_call(['pip', 'install', package + ' --upgrade'])
    except Exception as e:
        print("Failed to update package {}: {}".format(package, e))

def check_updates():
    dists = [d for d in pkg_resources.working_set]
    updates = subprocess.check_output(['pip', 'list', '--outdated'], text=True)
    for line in updates.splitlines()[2:]:  # Skip the first two header lines
        try:
            name, curr_version, latest_version, _ = line.split()
            if any(d.key == name and d.parsed_version < latest_version for d in dists):
                update(name)
        except ValueError:  # Ignore lines that aren't really package lines
            continue

if __name__ == '__main__':
    check_updates()

