import requests
from literary.ratelimiter import Limiter

def restrict_operations(app_name):
    restricted_operations = [
        'POST', 'PUT', 'DELETE', 
        'GET', 'HEAD'
    ]

    limiter = Limiter(max_calls=10, block_time=2)

    def decorator(func):
        def wrapper(*args, **kwargs):
            method = func.__name__

            if method in restricted_operations:
                try:
                    with limiter.limit('10/2s'):
                        return func(*args, **kwargs)
                except ValueError as e:
                    print(f"Rate limited on {app_name} - {e}")
                    raise Exception("Rate limited") from e
            else:
                try:
                    response = func(*args, **kwargs)
                    status = response.status_code
                    if 500 <= status < 600:
                        response.add_header('Content-Type', 'text/plain')
                        response.write(f'Error: {status} occurred on {app_name}')
                    return response
                except Exception as e:
                    print(f"Error in {method}: {e}")
        return wrapper
    return wrapper

