import socket

class IPBanHandler:
    def __init__(self):
        self.banned_ips = set()

    def add_ban(self, ip):
        """Add an IP to the ban list."""
        self.banned_ips.add(ip)

    def remove_ban(self, ip):
        """Remove an IP from the ban list."""
        if ip in self.banned_ips:
            self.banned_ips.remove(ip)

    def handle_request(self, ip, request):
        """
        Check if an incoming request's IP is banned.

        Args:
            ip (str): The IP address of the incoming request.
            request: The incoming request object (not used in this example).

        Returns:
            bool: True if the IP is banned, False otherwise.
        """
        return ip in self.banned_ips


def get_client_ip(request):
    """Get the client's IP from the request."""
    x_forwarded_for = request.META.get('HTTP_X_FORWARDED_FOR')
    if x_forwarded_for:
        ip = x_forwarded_for.split(',')[0]
    else:
        ip = request.META.get('REMOTE_ADDR')
    return ip


def is_banned(request):
    """Check if the client's IP is banned."""
    handler = IPBanHandler()
    return handler.handle_request(get_client_ip(request), request)


# Example usage
if __name__ == "__main__":
    # Add banned IPs
    ban_handler = IPBanHandler()
    ban_handler.add_ban("192.168.1.100")
    ban_handler.add_ban("192.168.1.101")

    # Check if a banned IP is requesting our website
    request = {"REMOTE_ADDR": "192.168.1.100", "HTTP_USER_AGENT": "Mozilla/5.0"}
    print(is_banned(request))  # Output: True

    # Remove the ban
    ban_handler.remove_ban("192.168.1.100")
    request = {"REMOTE_ADDR": "192.168.1.100", "HTTP_USER_AGENT": "Mozilla/5.0"}
    print(is_banned(request))  # Output: False

from google.cloud import storage
import datetime

def sizeof_fmt(num, suffix="B"):
    for unit in ["", "Ki", "Mi", "Gi", "Ti", "Pi", "Ei", "Zi"]:
        if abs(num) < 1024.0:
            return f"{num:3.1f}{unit}{suffix}"
        num /= 1024.0
    return f"{num:.1f}Yi{suffix}"

def monitor_gcs():
    client = storage.Client()

    total_size = 0
    for bucket in client.list_buckets():
        blobs = client.list_blobs(bucket.name)
        size = 0
        for blob in blobs:
            size += blob.size

        print(f"Bucket {bucket.name} has {len(list(blobs))} files and total size of {sizeof_fmt(size)}")
        total_size += size

    print("Total storage used: ", sizeof_fmt(total_size))

if __name__ == "__main__":
    monitor_gcs()

