import xml.etree.ElementTree as ET
from defusedxml.ElementTree import fromstring

def parse_xml(xml_data):
    try:
        # Using defusedxml's fromstring which is safe against XML External Entity attacks
        root = fromstring(xml_data)
    except ET.ParseError as e:
        print("Error parsing XML data:", str(e))
        return None

    objects = []

    # Let's assume each object in the XML is represented by a 'record' element
    for record in root.iter('record'):
        obj = {}

        # Parsing attributes of the record element into the object dictionary
        for attr_name, attr_value in record.attrib.items():
            obj[attr_name] = attr_value

        # Parsing child elements of the record element into the object dictionary
        for elem in record:
            if len(elem):  # If it has child elements, recursively call parse_xml function
                obj[elem.tag] = parse_xml(ET.tostring(elem))
            else:
                obj[elem.tag] = elem.text

        objects.append(obj)
    return objects

def handle_payment_gateway_errors(amount, transaction_id, error_code=None, error_message=None, currency=None, error_mapping=None):
    """
    Handles payment gateway errors and returns an appropriate response.

    Args:
        amount (float): The payment amount.
        transaction_id (str): Unique identifier for the transaction.
        error_code (str, optional): Error code from the payment gateway. Defaults to None.
        error_message (str, optional): Custom error message. Defaults to None.
        currency (str, optional): Currency code (e.g., 'USD', 'EUR'). Defaults to None.
        error_mapping (dict, optional): Dictionary mapping error codes to messages. Defaults to None.

    Returns:
        dict: A dictionary containing the transaction ID and an error message.
    """
    # Initialize default error mapping
    if error_mapping is None:
        error_mapping = {
            '100': 'Invalid amount',
            '101': 'Transaction failed due to insufficient funds',
            '201': 'Payment processing failed'
        }

    # Determine the appropriate error message
    if error_code and error_code in error_mapping:
        error_msg = error_mapping.get(error_code, 'Unknown error') + f' {currency}' if currency else error_mapping[error_code]
    elif error_message:
        error_msg = error_message
    else:
        return {
            'message': 'Payment gateway error occurred',
            'amount': amount,
            'transaction_id': transaction_id
        }

    # Validate the amount
    if amount <= 0:
        return {
            'message': 'Invalid amount',
            'amount': amount,
            'transaction_id': transaction_id
        }

    # Return an error response with message details
    return {
        'message': f'{error_msg}: {error_code}' if error_code else error_msg,
        'amount': amount,
        'transaction_id': transaction_id
    }

