# Function to create a cache decorator for reports
def report_cache(max LifeTime=86400):
    def decorator(report_func):
        original = report_func

        @wraps(original)
        def wrapper(*args, **kwargs):
            timestamp = int(time.time())

            # Check if the report exists in memory
            cached_report = None
            try:
                cached_report = report_func.cache.get(str(timestamp), None)
            except AttributeError:
                pass

            if cached_report is not None:
                return cached_report

            # Generate new report
            generated_report = original(*args, **kwargs)

            # Save to cache with timestamp as filename
            cache_path = f"report_{timestamp}.json"
            report_func.cache[cache_path] = generated_report

            return generated_report

        return cache_property(
            wrapper,
            'cache'
        )

    return decorator

