class ActivityTracker:
    def __init__(self):
        self.session = None
        self.last_activity = None

    def track(self, method):
        pass  # Subclasses will implement specific tracking logic

    def track_activity(self):
        if not hasattr(self, 'session'):
            return False

        try:
            if not self.session.is_running():
                self.session.start()

            result = self.track(method='api_call')
            if result:
                self.session.stop()

            return True

        except Exception as e:
            print(f"Error tracking activity: {e}")
            return False

