    def wrapper(*args, **kwargs):
        try:
            if socketio.is_active() and g.get('session'):
                session = g['session']
                result = session.track_activity()

                if result is False:
                    print(f"Access denied for {f.__name__}")
                    return redirect(url_for('index'))

                return f(*args, **kwargs)
        except Exception as e:
            print(f"Exception in {f.__name__}: {e}")
            raise
    return wrapper

# Run the app
if __name__ == '__main__':
    socketio.run(app)

