def validate_input(data):
    # Check if data is a dictionary
    if not isinstance(data, dict):
        raise ValueError("Input should be a dictionary.")

    # Required keys for model prediction
    required_keys = ['number_of_rooms', 'square_footage', 'neighborhood']

    # Check if all necessary keys are present
    if not all(key in data for key in required_keys):
        raise ValueError("Input dictionary missing one or more required keys.")

    # Check the type and value of each key
    if not isinstance(data['number_of_rooms'], int) or data['number_of_rooms'] < 0:
        raise ValueError("'number_of_rooms' should be a non-negative integer.")

    if not isinstance(data['square_footage'], (int, float)) or data['square_footage'] <= 0:
        raise ValueError("'square_footage' should be a positive number.")

    allowed_neighborhoods = ['downtown', 'suburban', 'rural']
    if not isinstance(data['neighborhood'], str) or data['neighborhood'] not in allowed_neighborhoods:
        raise ValueError("'neighborhood' should be a string and one of the following: {}".format(", ".join(allowed_neighborhoods)))

    return True

