import json

class QueryLoggerMiddleware(object):
    def __init__(self, app):
        self.app = app

    def __call__(self, environ, start_response):
        request_body_size = int(environ.get('CONTENT_LENGTH', 0))

        # Log only if the request has a body and its method is POST
        if request_body_size > 0 and environ['REQUEST_METHOD'] == 'POST':
            request_body = environ['wsgi.input'].read(request_body_size)
            data = json.loads(request_body)

            # If the query is in the body of the request, log it
            if 'query' in data:
                self._log_query(data['query'])
        return self.app(environ, start_response)

    def _log_query(self, query):
        parsed = parse(query)
        # You can replace this with your logging mechanism
        print("Received GraphQL Query:\n", parsed.loc.source.body)

import functools
from typing import Callable, Any

class LRUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.cache = {}
        self.order = []

    def get(self, key: int) -> Any:
        if key in self.cache:
            value = self.cache[key]
            self.order.remove(key)
            self.order.append(key)
            return value
        else:
            return -1

    def put(self, key: int, value: Any) -> None:
        if key in self.cache:
            self.cache[key] = value
            self.order.remove(key)
            self.order.append(key)
        elif len(self.cache) == self.capacity:
            lru_key = self.order.pop(0)
            del self.cache[lru_key]
        else:
            self.cache[key] = value
            self.order.append(key)

def cache_results(max_size):
    def decorator(func):
        @functools.wraps(func)
        class LRUCacheWrapper:
            def __init__(self, func, max_size):
                self.func = func
                self.max_size = max_size
                self.cache = {}
            def get_result(self, key):
                if key in self.cache:
                    result = self.cache[key]
                    del self.cache[key]
                    self.cache[key] = result
                    return result
                else:
                    result = self.func(key)
                    self.cache[key] = result
                    return result
        return LRUCacheWrapper(func, max_size)

    return cache_results

@cache_results(max_size=10)
def example_func(x):
    # Simulating a time-consuming operation
    import time
    time.sleep(1)
    return x * 2

print(example_func(2))  # Takes 1 second to execute
print(example_func(3))  # Returns immediately from cache

