from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity):
        self.cache = OrderedDict()
        self.capacity = capacity

    def get(self, key):
        if key not in self.cache:
            return -1
        else:
            self.cache.move_to_end(key)  # Move accessed item to end of cache
            return self.cache[key]

    def put(self, key, value):
        if key in self.cache:
            self.cache.move_to_end(key)  # Update position if key already exists
        else:
            if len(self.cache) >= self.capacity:
                self.cache.popitem(last=False)  # Remove least recently used item when cache is full
        self.cache[key] = value

import requests
from requests.adapters import HTTPAdapter
from requests.exceptions import RequestException, Timeout

def get_response(url):
    session = requests.Session()
    # Disable automatic redirects and set your own max redirections to avoid infinite loops
    session.max_redirects = 3
    adapter = HTTPAdapter(max_retries=2)
    session.mount('http://', adapter)
    session.mount('https://', adapter)

    headers = {
        "User-Agent": "MyApp/1.0 (myemail@example.com)"  # Use a specific user agent
    }

    try:
        response = session.get(url, headers=headers, timeout=5, verify=True)  # Always validate SSL certificates
        if response.status_code == requests.codes.ok:
            return response.text
        else:
            print("Error:", response.status_code)
    except Timeout:
        print("The request timed out")
    except RequestException as e:
        print("A request exception occurred", str(e))
    finally:
        session.close()  # Close the connection when done

