# Simulated database of tenants and their resources
DATABASE = {
    'tenant1': ['resource1', 'resource2'],
    'tenant2': ['resource3']
}

def tenant_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        tenant = request.headers.get('X-Tenant')
        if not tenant or tenant not in DATABASE:
            return jsonify({'message': 'Invalid or missing tenant header'}), 401
        return f(*args, **kwargs)
    return decorated

@app.route('/resource/<resource_name>', methods=['GET'])
@tenant_required
def get_resource(resource_name):
    tenant = request.headers.get('X-Tenant')
    if resource_name not in DATABASE[tenant]:
        return jsonify({'message': 'Resource not found for this tenant'}), 404
    # Here, you would fetch and return the actual resource data
    return jsonify({'resource': resource_name})

