import hashlib

class Role:
    def __init__(self, id, name):
        self.id = id
        self.name = name

class User:
    def __init__(self, id, username, password):
        self.id = id
        self.username = username
        self.password = password
        self.roles = []

    def set_password(self, password):
        # Hash the password for secure storage
        hashed_password = hashlib.sha256(password.encode()).hexdigest()
        self.password = hashed_password

class RBAC:
    def __init__(self):
        self.users = {}
        self.roles = {}

    def create_role(self, name):
        """Create a new role."""
        self.roles[name] = Role(len(self.roles) + 1, name)

    def create_user(self, username, password):
        """Create a new user with the given username and password."""
        hashed_password = hashlib.sha256(password.encode()).hexdigest()
        self.users[username] = User(len(self.users) + 1, username, hashed_password)

    def assign_role(self, username, role_name):
        """Assign the given role to the specified user."""
        if username in self.users:
            if role_name in self.roles:
                self.users[username].roles.append(self.roles[role_name])
            else:
                raise ValueError(f"Role '{role_name}' does not exist.")
        else:
            raise ValueError(f"User '{username}' does not exist.")

    def check_access(self, username, feature):
        """Check if the user has access to the specified feature."""
        if username in self.users:
            for role in self.users[username].roles:
                if role.name == 'admin' and feature == 'create_content':
                    return True
                elif role.name == 'editor' and feature == 'edit_content':
                    return True
                # Add more roles and features as needed
        return False

# Example usage
rbac = RBAC()

# Create roles
rbac.create_role('admin')
rbac.create_role('editor')

# Create users
rbac.create_user('john_doe', 'password123')
rbac.create_user('jane_doe', 'password456')

# Assign roles
rbac.assign_role('john_doe', 'admin')
rbac.assign_role('jane_doe', 'editor')

# Check access
print(rbac.check_access('john_doe', 'create_content'))  # Output: True
print(rbac.check_access('jane_doe', 'edit_content'))   # Output: True

from urllib.parse import quote, urlencode
import requests

def log_api_call(url, params=None, headers=None):
    # Process parameters: encode them if they are not None
    processed_params = {}
    if isinstance(params, dict) or params is not None:
        for key, value in (params.items() if isinstance(params, dict) else iter([params])):
            # quote the value to include it as a parameter
            processed_params[quote(key)] = urlencode(value)

    # Prepare headers: combine given headers with processed_params (if any)
    all_headers = {}
    if headers is not None:
        for key, value in headers.items():
            all_headers[key] = value

    # Merge the two dictionaries, giving priority to headers provided by the user
    all_headers.update(processed_params)

    try:
        response = requests.get(url, headers=all_headers)
        print(f"Successfully made a request: {url}")
        if response.status_code == 200:
            print("HTTP Response:")
            print(response.text)
    except Exception as e:
        print(f"Request failed for URL: {url}. Error: {str(e)}")

