from pip._internal.utils.misc import get_installed_distributions
import os

def check_dependencies():
    # Get a list of currently installed packages and their versions
    installed = {package.key: package.version for package in get_installed_distributions()}

    # Define the dependencies you expect to have, with versions if necessary
    expected_dependencies = {'numpy': '1.20.3', 'scipy': None} 

    # Check each dependency against what we're expecting
    for name, version in expected_dependencies.items():
        try:
            installed_version = installed[name]
        except KeyError:
            print(f"Missing package {name}. Please install it.")
            return False

        # If a specific version was specified and it doesn't match, fail the check
        if version is not None and installed_version != version:
            print(f"Incorrect version of {name} installed. Expected {version}, got {installed_version}. Please update or downgrade as needed.")
            return False

    print("All dependencies are present and at the correct versions.")
    return True

