import time

def retry_operation(operation, max_retries=3, delay=1):
    """
    Retries an operation up to the maximum number of times.

    Args:
        operation: The operation to retry.
        max_retries: The maximum number of times to retry.
        delay: The delay between retries in seconds.

    Returns:
        The result of the operation.
    """

    for i in range(max_retries):
        try:
            return operation()
        except Exception as e:
            print(f"Operation failed with error: {e}")
            if i < max_retries - 1:
                time.sleep(delay)
    raise Exception("Maximum number of retries reached.")


