import logging
from collections import UserDict

class LoggingConfig(UserDict):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.logger = logging.getLogger(__name__)

    def __setitem__(self, key, value):
        if key in self.data:
            self.logger.info(f"Changing configuration {key} from '{self.data[key]}' to '{value}'")
        else:
            self.logger.info(f"Setting new configuration: {key} = '{value}'")

        super().__setitem__(key, value)

class Query:
    def __init__(self, name):
        self.name = name
        self.fields = {}
        self.nested_queries = {}

    def add_field(self, field_name, value):
        self.fields[field_name] = value

    def add_nested_query(self, query_name, nested_query):
        self.nested_queries[query_name] = Query(query_name)

    def execute(self, data):
        # Execute the main query
        print(f"Executing query: {self.name}")
        for field_name, field_value in self.fields.items():
            if isinstance(field_value, list):
                print(f"Filtering by field '{field_name}': {field_value}")
            else:
                print(f"Filtering by field '{field_name}' with value '{field_value}'")

        # Handle nested queries
        for query_name, nested_query in self.nested_queries.items():
            nested_data = {}
            for field_name, field_value in data.items():
                if field_name == query_name:
                    nested_data[field_name] = field_value
                elif isinstance(field_value, list) and query_name in field_value:
                    nested_data[query_name] = field_value[0]
            print(f"\nExecuting nested query: {query_name}")
            result = nested_query.execute(nested_data)
            print(result)


