class EventProcessingLatencyMonitor:
    def __init__(self):
        self.latency_metrics: Dict[str, List[float]] = {
            'avg_latency': [],
            'max_latency': [],
            'min_latency': []
        }

    def record_latency(self, event_id: str, latency: float):
        """Record the latency of an event."""
        self.latency_metrics['avg_latency'].append(latency)
        if len(self.latency_metrics['avg_latency']) > 10:
            self.latency_metrics['avg_latency'] = self.latency_metrics['avg_latency'][1:]
        self.latency_metrics['max_latency'].append(max(self.latency_metrics['avg_latency']))
        self.latency_metrics['min_latency'].append(min(self.latency_metrics['avg_latency']))

    def get_average_latency(self) -> float:
        """Get the average latency."""
        return sum(self.latency_metrics['avg_latency']) / len(self.latency_metrics['avg_latency'])

    def get_max_latency(self) -> float:
        """Get the maximum latency."""
        return max(self.latency_metrics['max_latency'])

    def get_min_latency(self) -> float:
        """Get the minimum latency."""
        return min(self.latency_metrics['min_latency'])

def main():
    # Create an instance of the EventProcessingLatencyMonitor
    monitor = EventProcessingLatencyMonitor()

    try:
        while True:
            # Simulate event processing latency (e.g., with sleep)
            time.sleep(1)
            event_id = f"event_{len(monitor.latency_metrics['avg_latency'])}"
            latency = 2 + (random.randint(-1, 1) / 10.0)  # Simulated latency
            print(f"Processing event {event_id} took {latency:.3f} seconds.")
            monitor.record_latency(event_id, latency)
    except KeyboardInterrupt:
        logging.info("Monitoring stopped.")

if __name__ == "__main__":
    main()

def validate_dict_config(config):
    """
    Validates the dictionary configuration format.

    Args:
        config (dict): The dictionary to validate.

    Returns:
        bool: True if valid, False otherwise.
    """
    for key in config.keys():
        if not isinstance(key, str) or not isinstance(config[key], (str, int, float)):
            return False
    return True

def is_valid_type(value, allowed_types):
    """
    Checks if a value is of any type in the allowed_types list.

    Args:
        value: The value to check.
        allowed_types (list): List of types (e.g., [int, str]).

    Returns:
        bool: True if isinstance(value, t) for some t in allowed_types, False otherwise.
    """
    return any(isinstance(value, t) for t in allowed_types)

def validate_list_config(config):
    """
    Validates the list configuration format.

    Args:
        config (list): The list to validate.

    Returns:
        bool: True if valid, False otherwise.
    """
    for element in config:
        if not isinstance(element, str) and not is_valid_type(element, [int, float]):
            return False
    return True

def validate_boolean_config(config):
    """
    Validates the boolean configuration format.

    Args:
        config (bool): The value to check.

    Returns:
        bool: True if valid, False otherwise.
    """
    allowed_types = [bool]
    if isinstance(config, str):
        # If it's a string representation of True/False
        return (config.lower() in ['true', 'false'])
    else:
        return is_valid_type(config, allowed_types)

def validate_string_encoding(config):
    """
    Validates the string encoding format.

    Args:
        config (str): The value to check.

    Returns:
        bool: True if valid, False otherwise.
    """
    # Example with UTF-8
    try:
        # Check if it's a valid Unicode string and has correct encoding
        return isinstance(config, str) and len(config.encode('utf-8')) > 0
    except UnicodeEncodeError:
        return False

def validate_config(config, section):
    """
    Validates the configuration format based on the section.

    Args:
        config (dict): The overall dictionary containing sections.
        section (str): The name of the section to validate.

    Returns:
        bool: True if valid, False otherwise. Raises KeyError if section is not present or None.
    """
    if section not in config:
        raise KeyError(f"Section '{section}' not found.")

    allowed_types = {
        'dict': (str, [int, float]),
        'list': str,
        'bool': bool,
        'string': str
    }

    if section == 'dict':
        return validate_dict_config(config[section])
    elif section == 'list':
        return validate_list_config(config[section])
    elif section == 'bool':
        return validate_boolean_config(config[section])
    elif section == 'string':
        return validate_string_encoding(config[section])
    else:
        raise ValueError(f"Unsupported configuration section: {section}")

def main():
    print("Dictionary Validation:")
    sample_dict = {'key1': 10, 'key2': "text"}
    if validate_dict_config(sample_dict):
        print("Dictionary is valid.")
    else:
        print("Dictionary validation failed.")

    print("\nList Validation:")
    sample_list = [1, True, None]
    try:
        list_valid = all(isinstance(elem, str) or isinstance(elem, (int, float)) for elem in sample_list)
        if validate_list_config(sample_list):
            print("List is valid.")
        else:
            print("List validation failed.")
    except ValueError as e:
        print(f"Error during list validation: {e}")

    print("\nBoolean Validation:")
    bool_val = True
    if validate_boolean_config(bool_val):
        print("Boolean value is valid.")
    else:
        print("Boolean validation failed.")

    print("\nString Encoding Validation:")
    sample_string = "This is a sample string."
    try:
        if validate_string_encoding(sample_string):
            print("String encoding is valid.")
        else:
            print("String encoding validation failed.")
    except UnicodeEncodeError as e:
        print(f"Error during string encoding validation: {e}")

if __name__ == "__main__":
    main()

