import os
import csv

def parse_csv_safely(file_path):
    """
    Safely parses a CSV file and returns specific fields.

    Args:
        file_path (str): Path to the CSV file.

    Returns:
        dict: A dictionary containing selected columns as keys with their values.
    """
    try:
        with open(file_path, 'r', encoding='utf-8') as file:
            csvreader = csv.DictReader(file)
            rows = []
            for row in csvreader:
                # Ensure all values are strings to prevent unintended type conversion
                row_values = {col: str(value) for col, value in row.items()}

                selected_fields = {
                    'username': row_values.get('username'),
                    'email': row_values.get('email'),
                    'name': row_values.get('name'),
                    'age': row_values.get('age')
                }

                if any(not isinstance(v, str) for v in row_values.values()):
                    raise ValueError("Found non-string value in CSV data")

                yield selected_fields

    except IOError as e:
        print(f"Error reading file: {e}")
        return None
    except UnicodeDecodeError as e:
        print(f"Invalid UTF-8 found. File may not be supported encoding.")
        return None

# Usage example
if __name__ == "__main__":
    csv_path = os.path.join(os.path.dirname(__file__), 'example_data.csv')
    parsed_data = list(parse_csv_safely(csv_path))

    if parsed_data:
        for item in parsed_data:
            print(item)
    else:
        print("No valid data found or file not accessible.")

