import os
import stat

def check_write_access(file):
    # Check if the file exists
    if not os.path.exists(file):
        return False

    # Get the file stats
    file_stat = os.stat(file)

    # Check if we can write to it (check for user's write permission)
    if bool(file_stat.st_mode & stat.S_IWUSR):
        return True
    else:
        return False

def modify_data(file, data):
    if check_write_access(file):
        with open(file, 'a') as f:  # use append mode to add content at the end of file.
            f.write(data)
        print("Data modification successful")
    else:
        print("You don't have permission to modify this file.")

# Test
