    app.run(debug=True)

def handle_dangling_pointers():
    # Create a list of pointers
    pointers = [None] * 10

    # Assign some pointers to valid objects
    pointers[0] = "Hello"
    pointers[1] = 10

    # Check for dangling pointers
    for pointer in pointers:
        if pointer is None:
            print("Dangling pointer found!")
        else:
            print("Valid pointer found.")

    # Close the objects referenced by valid pointers
    for pointer in pointers[0:2]:
        if pointer is not None:
            del pointer

    # Check for dangling pointers again
    for pointer in pointers:
        if pointer is None:
            print("Dangling pointer found!")
        else:
            print("Valid pointer found.")

handle_dangling_pointers()

