import numpy as np
from collections import namedtuple

Transaction = namedtuple('Transaction', 'product_id price quantity')

class PriceManipulationPreventionSystem:
    def __init__(self):
        self.transactions = []

    def add_transaction(self, product_id, price, quantity):
        transaction = Transaction(product_id=product_id, price=price, quantity=quantity)
        self.transactions.append(transaction)

    def calculate_average_price(self, product_id):
        prices = [t.price for t in self.transactions if t.product_id == product_id]
        return np.mean(prices)

    def check_for_outliers(self, product_id, threshold=3.0):
        average_price = self.calculate_average_price(product_id)
        prices = [t.price for t in self.transactions if t.product_id == product_id]
        z_scores = np.abs((prices - np.mean(prices)) / np.std(prices))
        outliers = [x for i, x in enumerate(self.transactions) if z_scores[i] > threshold and x.product_id == product_id]
        return outliers

    def alert_on_suspicious_activity(self, product_id):
        outliers = self.check_for_outliers(product_id)
        if outliers:
            print(f"Suspicious activity detected for product {product_id}.")
            for t in outliers:
                print(f"Transaction: Product ID={t.product_id}, Price={t.price}, Quantity={t.quantity}")
        else:
            print("No suspicious activity detected.")

