class Node:
    def __init__(self, data=None):
        self.data = data
        self.next = None

class LinkedList:
    def __init__(self):
        self.head = None

    def insert(self, data):
        if not self.head:
            self.head = Node(data)
        else:
            curr_node = self.head
            while curr_node.next:
                curr_node = curr_node.next
            curr_node.next = Node(data)

    def manipulate_data(self, target_data, new_data):
        current_node = self.head
        while current_node is not None:
            if current_node.data == target_data:
                current_node.data = new_data
                return True
            current_node = current_node.next
        return False

# Create a linked list and insert some data
linked_list = LinkedList()
linked_list.insert(1)
linked_list.insert(2)
linked_list.insert(3)

# Manipulate the data in the linked list
print("Manipulating data:")
print("Before:", [node.data for node in iterate(linked_list.head)])  # Helper function to print out the current state of the list
result = linked_list.manipulate_data(2, 'two')
print("After:", [node.data for node in iterate(linked_list.head)])
print("Successfully manipulated data:", result)

