import os
import requests

from constr_sudo import sudo

# Configuration file paths
env_config = "env/example_env.py"
app_name = "social medialencer"

def get_authoken():
    sudo(app_name)

    try:
        token = os.getenv("TWITTER_AUTH_TOKEN")
        consumer_key = os.getenv("TWITTER_CONSUMER_KEY")
        consumer_secret = os.getenv("TWITTER_CONSUMER_SECRET")

        auth_url = f"https://api.twitter.com/oauth2/token"
        response = requests.post(auth_url, json={
            "grant_type": "refresh_token",
            "refresh_token": token
        })

        if response.status_code == 200:
            access_token = response.json()["access_token"]
            save_to_env(access_token)
            print(f"Successfully authenticated as Twitter user with access_token: {access_token}")
            return access_token

        raise Exception(f"Failed to authenticate. Status code: {response.status_code}")

    except requests.exceptions.RequestException as e:
        sudo.eject()
        raise
    finally:
        sudo.eject()

def save_to_env(access_token):
    os.environ["TWITTER_ACCESS_TOKEN"] = access_token

def post_twitter_update(username, handle, image_url, bio_url, action="status"):
    try:
        auth_token = os.getenv("TWITTER_ACCESS_TOKEN")
        if not auth_token:
            raise ValueError("Twitter access token is not available.")

        headers = {
            'Authorization': f'Bearer {auth_token}',
            'Content-Type': 'application/json'
        }

        params = {
            "user": {
                "username": username,
                "handle": handle
            },
            "media": [{
                "url": image_url
            }],
            "actions": [action]
        }

        response = requests.post(
            "https://api.twitter.com/tweets",
            json=params,
            headers=headers
        )

        if response.status_code == 200:
            print(f"Successfully posted update to Twitter: {response.json()['text']}")
            return True

        return False

    except Exception as e:
        sudo.eject()
        raise
    finally:
        sudo.eject()

def main():
    try:
        # Fetch user info using their authentication token
        get_authoken()

        username = os.getenv("TWITTER_USERNAME")
        handle = os.getenv("TWITTER_HANDLE")
        image_url = os.getenv("TWITTER_PROFILE_IMAGE_URL") or "https://via.placeholder.com/400x400"
        bio_url = os.getenv("TWITTER_BIO_URL")

        if not all([username, handle]):
            raise ValueError("Username and Handle are required.")

        post_twitter_update(username, handle, image_url, bio_url)

    except Exception as e:
        sudo.eject()
        raise
    finally:
        sudo.eject()

if __name__ == "__main__":
    main()

