from typing import Optional, Dict, Any
import requests
from .graphql_client import GraphQLClient


class GraphQLResolver:
    def __init__(self, graphql_url: str, headers: Optional[Dict[str, Any]] = None):
        self/graphql_url = graphql_url
        self.headers = headers or {}
        self._client = GraphQLClient(self)

    def _make_request(
        self,
        method: str,
        path: str,
        query_params: Optional[Dict[str, Any]] = None,
        **kwargs,
    ) -> requests.Response:
        """Constructs and sends a request with proper headers."""
        full_url = f"{self/graphql_url}{path}"
        if query_params is not None:
            full_url += "?" + '&'.join([f"{k}={v}" for k, v in query_params.items()])

        headers = {**self.headers}
        headers.update(kwargs.pop("headers", {}))
        timeout = kwargs.pop("timeout", requests.Timeout(30.0))

        return self._client.request(method, full_url, headers=headers, timeout=timeout)

    def _fetch_data(self, response: requests.Response) -> Any:
        """Fetches and parses data from the API."""
        if not response.ok:
            raise ValueError(f"API request failed with status code {response.status_code}")

        content = response.json()
        return self._process_response(content)

    def _process_response(self, response_data: dict) -> Any:
        """Processes the fetched JSON data into a suitable format."""
        if "data" in response_data:
            return response_data["data"]
        elif "people" in response_data and isinstance(response_data["people"], list):
            return [person for person in response_data["people"]]
        else:
            raise ValueError(f"Invalid response structure: {response_data}")


class DefaultResolver(GraphQLResolver):
    def __init__(self, graphql_url: str, endpoint: str, headers: Optional[Dict[str, Any]] = None):
        super().__init__(graphql_url, headers)
        self.endpoint = endpoint

    async def resolve(self, query: str, variables: Optional[dict] = None) -> Any:
        """Sends a GraphQL query to the resolver."""
        params = {}
        if variables is not None:
            params["variables"] = variables

        request = f"""
            query($query: String!, $variables: {str(variables).replace('None', '')}) {{
                {self.endpoint} {{
                    {query}
                }}
            }}
        """

        return await self._fetch_data(self._make_request("GET", "", {"query": query, "variables": variables}, params=params))

    def resolve synchronous resolver:
        """Sends a GraphQL query to the resolver."""
        params = {}
        if variables is not None:
            params["variables"] = variables

        request = f"""
            query($query: String!, $variables: {str(variables).replace('None', '')}) {{
                {self.endpoint} {{
                    {query}
                }}
            }}
        """

        return self._fetch_data(self._make_request("GET", "", {"query": query, "variables": variables}, params=params))


def main():
    import sys
    from .graphql_client import GraphQLClient

    # Example usage: Replace with actual API key and endpoint URL
