import requests
from functools import wraps
import logging

# Set up logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

def retry decorator(max_attempts=3, backoff_factor=0.5):
    """
    Decorator to handle retry failures.

    Args:
        max_attempts (int): Maximum number of attempts.
        backoff_factor (float): Backoff factor for exponential backoff.
    """

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            attempt = 0
            while attempt < max_attempts:
                try:
                    return func(*args, **kwargs)
                except requests.RequestException as e:
                    logger.warning(f"Attempt {attempt + 1} failed with error: {e}")
                    if attempt == max_attempts - 1:
                        raise
                    logger.info(f"Backing off for {backoff_factor * (2 ** attempt)} seconds")
                    import time
                    time.sleep(backoff_factor * (2 ** attempt))
                else:
                    return func(*args, **kwargs)
        return wrapper

    return decorator


class ApiClient:
    def __init__(self, base_url):
        self.base_url = base_url

    @retry(max_attempts=3, backoff_factor=0.5)
    def make_request(self, url, method, data=None, params=None):
        """
        Makes a request to the API.

        Args:
            url (str): URL of the API endpoint.
            method (str): HTTP method (e.g., 'GET', 'POST').
            data (dict): Data to be sent in the request body.
            params (dict): Parameters to be sent in the request query string.

        Returns:
            response: Response from the API.
        """

        url = self.base_url + url
        response = requests.request(method, url, json=data, params=params)
        return response


# Example usage:
