        response = api_client.make_request("/create", "POST", data=data)
        print(response.json())
    except requests.RequestException as e:
        logger.error(f"Failed to make POST request: {e}")

import queue
import threading

class DynamicQueueScaler:
    def __init__(self, queue, min_size, max_size):
        self.queue = queue
        self.min_size = min_size
        self.max_size = max_size
        self.thread = threading.Thread(target=self.scale_queue)
        self.thread.daemon = True
        self.thread.start()

    def scale_queue(self):
        while True:
            queue_size = len(self.queue.queue)
            if queue_size < self.min_size:
                for _ in range(self.min_size - queue_size):
                    self.queue.put(None)
            elif queue_size > self.max_size:
                for _ in range(queue_size - self.max_size):
                    self.queue.get()

# Example usage:
