    print(task)

import random
from itertools import combinations

class WebhookLimiting:
    def __init__(self, key):
        if not hasattr(key, 'info'):
            raise ValueError("API key must have a 'info' attribute with limit information.")
        self.key = key
        self.limit = key.info['limit']
        self.uniq_reqs = []

    def generate_request_id(self):
        return f'request-{random.uuid4().hex}'

    def hamming_distance(self, s1: str, s2: str) -> int:
        """Calculate Hamming distance between two strings."""
        if len(s1) != len(s2):
            raise ValueError("Strings must be of equal length.")
        return sum(c1 != c2 for c1, c2 in zip(s1, s2))

    def handle(self, req_id: str) -> None:
        similar = [r['id'] for r in self.uniq_reqs]

        if len(similar) >= self.limit - 1:
            # Notify about rate limiting
            import logging
            logging.warning(f"Rate limiting detected. Too many requests from {req_id}.")
            return

        # Check Hamming distance similarity (threshold: 2)
        new requesting = True
        for combo in combinations(similar, r=2):
            if self.hamming_distance(combo[0], req_id) <= 2:
                len_similar = sum(1 for c in similar if self.hamming_distance(c, req_id) <= 2)
                if len_similar + 1 > self.limit - 1:
                    new = False
                    break

        # Add to list of unique request IDs
        self.uniq_reqs.append({'id': req_id, 'timestamp': random.randint(0, int(time.time()))})

        if not new or len(self.uniq_reqs) >= self.limit:
            return

    def __str__(self):
        return f"WebhookLimiting({'API key': self.key, 'limit': self.limit})"

# Example usage
if __name__ == "__main__":
    import time
    import logging

    # Replace 'your_api_key' with actual API key and define limit in key.info
    class TestKey:
        info = {'limit': 5}

    limiting = WebhookLimiting(TestKey())

    try:
        for i in range(10):
            req_id = limiting.generate_request_id()
            start_time = time.time()
            result = limiting.handle(req_id)

            # Wait between requests (e.g., every second to test rate limit)
            if not result and random.randint(0, 5) > 0:
                time.sleep(1)

            print(f"Request {i+1} made at {time.time()}")
    except Exception as e:
        print(f"Error: {str(e)}")

