api_url = 'http://example.com/api/endpoint'

def monitor_api(url):
    # Start timer
    start_time = time.time()

    try:
        # Send GET request
        response = requests.get(url)

        # Check status code, if successful then proceed otherwise print error
        if response.status_code == 200:
            return True, (time.time() - start_time), response.json()
        else:
            return False, (time.time() - start_time), None
    except requests.exceptions.RequestException as e:
        # If there was an exception while handling request, print it
        print(f"An error occured: {e}")
        return False, (time.time() - start_time), None


