import sqlite3
from bs4 import BeautifulSoup
import requests

def create_connection():
    conn = None;
    try:
        conn = sqlite3.connect('scraped_data.db')  # creates connection if db doesn't exist, else connects to it
        return conn
    except Error as e:
        print(e)

def create_table(conn):
    try:
        cursor = conn.cursor()
        cursor.execute("CREATE TABLE IF NOT EXISTS data (value TEXT);")  # creates table if not exists
    except Error as e:
        print(e)

def insert_data(conn, data):
    try:
        cursor = conn.cursor()
        cursor.executemany('INSERT INTO data VALUES (?);', [(i,) for i in data])  # inserts scraped data into table
        conn.commit()
    except Error as e:
        print(e)

def main():
    url = 'https://example.com'
    r = requests.get(url)
    soup = BeautifulSoup(r.text, 'html.parser')
    data_elements = soup.find_all('div', attrs={'data-value': True})  # finds all div elements with a data-value attribute
    data = [i['data-value'] for i in data_elements]  # extracts the value of the data-value attribute

    conn = create_connection()
    if conn is not None:
        create_table(conn)
        insert_data(conn, data)
        conn.close()

if __name__ == '__main__':
    main()

