import threading
import time
from queue import PriorityQueue

class HighPriorityThread(threading.Thread):
    def __init__(self, group=None, target=None, name=None, args=(), kwargs={}, *, daemon=None):
        super().__init__(group=group, target=target, name=name, args=args, kwargs=kwargs, daemon=daemon)
        self._priority = 1  # default priority for high-priority threads

    def run(self):
        time.sleep(0.5 / self._priority)  # simulate processing with respect to the thread's priority
        super().run()

class LowPriorityThread(threading.Thread):
    def __init__(self, group=None, target=None, name=None, args=(), kwargs={}, *, daemon=None):
        super().__init__(group=group, target=target, name=name, args=args, kwargs=kwargs, daemon=daemon)
        self._priority = 10  # default priority for low-priority threads

    def run(self):
        time.sleep(0.5 / self._priority)  # simulate processing with respect to the thread's priority
        super().run()

class Job:
    def __init__(self, priority, description):
        self.priority = priority
        self.description = description

    def __lt__(self, other):
        return self.priority < other.priority

job_queue = PriorityQueue()  # jobs with higher priority numbers will be executed first
job_queue.put(Job(3, "High-Priority Job"))
job_queue.put(Job(10, "Low-Priority Job"))

