import requests
import json

# Function to get data from API
def get_data(url, params):
    try:
        response = requests.get(url, params=params)
        if response.status_code == 200:
            return json.loads(response.text)
        else:
            # Fallback mechanism: Return an error message with the status code
            return {"error": f"Failed to retrieve data. Status code: {response.status_code}"}
    except requests.exceptions.RequestException as e:
        # Fallback mechanism: Handle any exceptions that occur during the request
        return {"error": str(e)}

# Function to post data to API
def post_data(url, data):
    try:
        response = requests.post(url, json=data)
        if response.status_code == 201:
            return json.loads(response.text)
        else:
            # Fallback mechanism: Return an error message with the status code
            return {"error": f"Failed to create data. Status code: {response.status_code}"}
    except requests.exceptions.RequestException as e:
        # Fallback mechanism: Handle any exceptions that occur during the request
        return {"error": str(e)}

# Function to put data to API
def put_data(url, data):
    try:
        response = requests.put(url, json=data)
        if response.status_code == 200:
            return json.loads(response.text)
        else:
            # Fallback mechanism: Return an error message with the status code
            return {"error": f"Failed to update data. Status code: {response.status_code}"}
    except requests.exceptions.RequestException as e:
        # Fallback mechanism: Handle any exceptions that occur during the request
        return {"error": str(e)}

# Function to delete data from API
def delete_data(url, params):
    try:
        response = requests.delete(url, params=params)
        if response.status_code == 200:
            return json.loads(response.text)
        else:
            # Fallback mechanism: Return an error message with the status code
            return {"error": f"Failed to delete data. Status code: {response.status_code}"}
    except requests.exceptions.RequestException as e:
        # Fallback mechanism: Handle any exceptions that occur during the request
        return {"error": str(e)}

# Usage example
