import time
import random

def retry_operation(operation, max_attempts=5, delay=1):
    """
    Retry a failed operation.

    Args:
        operation (function): The operation to be retried.
        max_attempts (int): The maximum number of attempts. Defaults to 5.
        delay (float): The delay between each attempt in seconds. Defaults to 1.

    Returns:
        result: The result of the operation if successful, otherwise None.
    """
    for i in range(max_attempts):
        try:
            return operation()
        except Exception as e:
            print(f"Attempt {i+1} failed with error: {str(e)}")
            time.sleep(delay + random.uniform(0, delay))  # Add a small random delay

