class RecurringPayment:
    def __init__(self, payment_id, amount, frequency, due_date):
        self.payment_id = payment_id
        self.amount = amount
        self.frequency = frequency
        self.due_date = due_date
        self.transactions = []

    def add_transaction(self, transaction_date, is_paid=False):
        self.transactions.append({
            'transaction_date': transaction_date,
            'is_paid': is_paid
        })

    def get_next_due_date(self):
        return self.get_due_date(self.due_date)

    def get_due_date(self, due_date):
        # Get the next due date by adding the frequency to the current day of the month
        from datetime import datetime
        due = datetime.strptime(due_date, '%Y-%m-%d')
        if self.frequency == 'daily':
            days_in_month = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
            due += datetime.timedelta(days=1)
        elif self.frequency == 'weekly':
            days_in_month = [7] * 12
            due += datetime.timedelta(days=self.due_date.weekday() + 7 - self.due_date.weekday())
        else:
            raise ValueError('Invalid frequency')

        return due.strftime('%Y-%m-%d')

    def get_payment_details(self):
        payment_details = {
            'payment_id': self.payment_id,
            'amount': self.amount,
            'frequency': self.frequency
        }
        return payment_details

def main():
    # Create a recurring payment object
    payment1 = RecurringPayment('Pay1', 100, 'daily', '2024-01-01')
    payment2 = RecurringPayment('Pay2', 200, 'weekly', '2024-02-03')

    # Add transactions for each payment
    payment1.add_transaction('2023-12-31', True)
    payment1.add_transaction('2023-12-31', False)

    payment2.add_transaction('2024-01-28', True)
    payment2.add_transaction('2024-02-03', False)

    # Print the next due date for each payment
    print(payment1.get_next_due_date())
    print(payment2.get_next_due_date())

    # Print the payment details
    print(payment1.get_payment_details())
    print(payment2.get_payment_details())

if __name__ == "__main__":
    main()

import os
from exifread import Exif
from PIL import Image

def extract_image_metadata(image_file):
    """
    Extracts metadata from an image file using exifread and PIL.

    Args:
        image_file (str): The path to the image file

    Returns:
        dict: A dictionary containing extracted metadata
    """
    try:
        with open(image_file, 'rb') as f:
            exif_data = Exif(f.read())

        metadata = {}

        # Extract file name
        for tag in ['Image File Name']:
            if tag in exif_data:
                value = exif_data[tag].value[0]  # Get first value, may be list
                metadata['filename'] = os.path.basename(value)

        # Extract image dimensions
        for tag in ['Image Width', 'Image Height']:
            if tag in exif_data:
                width, height = map(int, [tag.value[0], tag.value[1]])
                metadata['width'] = width
                metadata['height'] = height

        # Extract bit depth (assuming all channels have the same bit depth)
        for tag in ['Bits Per Channel']:
            if tag in exif_data:
                channel_depth = exif_data[tag].value[0]
                metadata['bitdepth'] = channel_depth

        # Extract color space
        for tag in ['Color Space']:
            if tag in exif_data:
                color_space = [tag.value[i] for i in range(len(tag.value))]
                if any(c is not None for c in color_space):
                    metadata['colorspace'] = ', '.join(color_space)

        # Extract compression method
        for tag in ['Color Space', 'Compression']:
            if tag in exif_data:
                compress_method = [tag.value[i] for i in range(len(tag.value))]
                if any(c is not None for c in compress_method):
                    metadata['compression'] = ', '.join(compress_method)

        # Extract date/time
        for tag in ['DateTime']:
            if tag in exif_data:
                dt = exif_data[tag].value[0]  # Assuming first value is the datetime
                metadata['datetime'] = dt

        return metadata

    except Exception as e:
        print(f"Error extracting metadata from {image_file}: {str(e)}")
        return None

# Example usage
image_path = "path_to_your_image.jpg"
metadata = extract_image_metadata(image_path)
if metadata:
    print("Extracted Metadata:")
    for key, value in metadata.items():
        print(f"{key}: {value}")

