def check_for_null_pointers(data):
    """
    Checks for null pointers in a data structure.

    Args:
        data: The data structure to check.

    Returns:
        True if there are no null pointers, False otherwise.
    """

    if data is None:
        return False

    # Check for null pointers in nested data structures
    if isinstance(data, (list, tuple, dict)):
        for item in data:
            if check_for_null_pointers(item):
                return False

    return True

def caesar_cipher(text, shift):
    encrypted = []
    for char in text:
        if char.islower():
            # For lowercase letters: 'a'-'z'
            new_char = chr(((ord(char) - ord('a') + shift) % 26) + ord('a'))
            encrypted.append(new_char)
        elif char.isupper():
            # For uppercase letters: 'A'-'Z'
            new_char = chr(((ord(char) - ord('A') + shift) % 26) + ord('A'))
            encrypted.append(new_char)
        else:
            # Non-alphabetic characters remain unchanged
            encrypted.append(char)
    return ''.join(encrypted)

# Example usage:
print(caesar_cipher("Hello!", 2))   # Output: "Jgnnq!"

