import time
from collections import defaultdict, deque

class RateLimiter:
    def __init__(self, max_requests=10, per_seconds=60):
        self.max_requests = max_requests
        self.per_seconds = per_seconds
        self.request_timestamps = defaultdict(deque)

    def is_allowed(self, client_id):
        now = time.time()
        while self.request_timestamps[client_id] and now - self.request_timestamps[client_id][0] > self.per_seconds:
            # remove old requests
            self.request_timestamps[client_id].popleft()

        if len(self.request_timestamps[client_id]) < self.max_requests:
            # add new request and allow it
            self.request_timestamps[client_id].append(now)
            return True
        else:
            # too many requests, reject this one
            return False

# Usage example
limiter = RateLimiter(max_requests=10, per_seconds=60)

def process_request(client_id):
    if limiter.is_allowed(client_id):
        print("Request allowed")
        # Process the request here...
    else:
        print("Too many requests, rejected")

import socket
import threading

class ClientConnection:
    def __init__(self):
        self.sockets = {}

    def accept_connection(self, client_socket):
        try:
            print(f"Client connected from {client_socket.gethostname()}")

            # Accept the connection and create a new thread for handling it
            conn = client_socket.accept()
            conn_thread = threading.Thread(target=self._handle_connection, args=(conn,))
            conn_thread.start()
        except Exception as e:
            print(f"Connection rejected: {str(e)}")

    def _handle_connection(self, conn):
        try:
            print("Handling connection...")

            # Exchange a simple 'hello' to establish a basic connection
            hello = conn.recv(1024)
            if not hello:
                print("Client disconnected by closing the connection.")
                return

            print(f"Received: {hello.decode()}")

            while True:
                data = conn.recv(1024).decode()
                if 'exit' in data.lower():
                    # Send a response back to all connected clients
                    for s in self.sockets.values():
                        if s == conn:
                            s.send(f"Bye from {s.getsockname()}\n".encode())
                            break  # No need to send further to this client
                    break

                print(f"Received from {conn.getpeername()}: {data}")
        except Exception as e:
            self.sockets.pop(conn)
            conn.close()
            print(f"Connection closed by: {str(e)}")

def server():
    port = 8080

    # Create a socket
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
        s.bind(('localhost', port))
        s.listen(5)

        print(f"Server running on localhost at port {port}")

        while True:
            conn, addr = s.accept()
            client_connection = ClientConnection()
            client_connection.accept_connection(conn)

            # Cleanup after the connection
            if not conn:
                break

if __name__ == "__main__":
    server()

