import sys
from pathlib import Path

__all__ = ['main']

sys.path.insert(0, str(Path(__file__).parent))

def get_source_modules(package_name):
    """Returns list of source modules allowed to import from this package."""
    if package_name == 'public':
        return []
    elif package_name == 'protected':
        return [ '__main__' ]
    else:
        # Default for private: only allows imports from public and protected
        return ['public', 'protected']

def accessible_public():
    def wrapper(func):
        try:
            import_module = sys.modules[__name__]
        except ImportError as e:
            raise RuntimeError(f"Access to public functions restricted. {e}") from None

        return func
    return wrapper

def accessible_protected(package_name):
    allowed_source_modules = get_source_modules(package_name)

    def decorator(func):
        try:
            import_module = sys.modules[__name__]
            if any(src in import_module.__dict__ for src in allowed_source_modules):
                return func
        except ImportError as e:
            raise RuntimeError(f"Access to protected functions restricted. {e}") from None

        # Also, check source module's parent package name against allowed ones
        source_path = sys.modules[__name__].__file__
        source_dir = Path(source_path).parent
        if source_dir.name not in ['main', 'public', 'protected']:
            raise RuntimeError(f"Access to protected functions restricted. Invalid import path: {source_dir}")

        return func

    return decorator

def accessible_private():
    allowed_source_modules = ['public', 'protected']

    def decorator(func):
        # Only allow imports from public and protected modules
        source_path = sys.modules[__name__].__file__
        source_dir = Path(source_path).parent.name

        if source_dir not in allowed_source_modules:
            raise RuntimeError(f"Access to private functions restricted. Source module: {source_dir}")

        return func

    return decorator

# Example usage of the wrappers:

def public_add(a, b):
    """Add two integers."""
    return a + b

wrapped_public_add = accessible_public()(public_add)

def protected_square(x):
    """Square an integer if it's positive."""
    if x < 0:
        raise ValueError("Cannot square negative numbers.")
    return x ** 2

wrapped_protected_square = accessible_protected('main')(protected_square)

def private两类的函数:
    # Example of a function that should be in the private level
    def private_private_op(data):
        """Perform an exclusive or operation."""
        if isinstance(data, list):
            return [x ^ y for x, y in data]
        else:
            return 0 ^ data

wrapped_private_op = accessible_private()(private_private_op)

# Accessing functions from public or protected modules
try:
    wrapped_public_add(3, 4)
except RuntimeError as e:
    print(e)  # Output: Access to public functions restricted.

try:
    wrapped_protected_square(-2)
except RuntimeError as e:
    print(e)  # Output: Access to protected functions restricted. {func} cannot be accessed from this module

# Attempting to import from an external module
import os
os.path.dirname(__file__)
wrapped_public_add = accessible_public()(wrapped_public_add)

try:
    wrapped_public_add(3, 4)
except RuntimeError as e:
    print(e)  # Output: Access to public functions restricted.

