import hashlib
import time

class Block:
    def __init__(self, index, previous_hash, timestamp, data):
        self.index = index
        self.previous_hash = previous_hash
        self.timestamp = timestamp
        self.data = data
        self.hash = self.calculate_hash()

    @staticmethod
    def calculate_hash(index, previous_hash, timestamp, data):
        string_to_hash = str(index) + str(previous_hash) + str(timestamp) + str(data)
        return hashlib.sha256(string_to_hash.encode()).hexdigest()


class Blockchain:
    def __init__(self):
        self.chain = [self.create_genesis_block()]

    @staticmethod
    def create_genesis_block():
        return Block(0, "0", int(time.time()), "Genesis Block")

    def add_block(self, new_block_data):
        new_block = Block(len(self.chain), self.get_last_block_hash(), int(time.time()), new_block_data)
        self.chain.append(new_block)

    def get_last_block_hash(self):
        return self.chain[-1].hash

    def validate_chain(self):
        for i in range(1, len(self.chain)):
            current_block = self.chain[i]
            previous_block = self.chain[i - 1]

            if current_block.hash != current_block.calculate_hash():
                print(f"Invalid hash found at index {i}")
                return False
            elif current_block.previous_hash != previous_block.hash:
                print(f"Inconsistent block hashes found at indices {i} and {i-1}")
                return False

        return True


def main():
    blockchain = Blockchain()

    # Transaction data (e.g. sender, recipient, amount)
    transaction_data = {
        "sender": "Alice",
        "recipient": "Bob",
        "amount": 10
    }

    # Add block with transaction data to the blockchain
    blockchain.add_block(transaction_data)

    # Print the chain's integrity validation result
    print("Blockchain Integrity Validation:")
    if blockchain.validate_chain():
        print("Chain is valid.")
    else:
        print("Chain contains errors.")


if __name__ == "__main__":
    main()

def load_config(config_file='default.cfg'):
    config = {}

    # Try to open the specified configuration file
    try:
        with open(config_file, 'r') as f:
            for line in f:
                key, value = line.strip().split('=', 1)
                config[key] = value

    # If the file cannot be opened, load default configurations
    except FileNotFoundError:
        print(f"Configuration file {config_file} not found. Loading default configurations.")
        with open('default.cfg', 'r') as f:
            for line in f:
                key, value = line.strip().split('=', 1)
                config[key] = value
    return config

