def validate_token(auth_header):
    if auth_header:
        try:
            token = auth_header.split(" ")[1]
            # Use jwt to decode the token with the secret key.
            data = jwt.decode(token, SECRET_KEY, algorithms=["HS256"])

            # The token is valid if no exception was thrown and data can be decoded.
            return True, "Valid Token"
        except jwt.ExpiredSignatureError:
            return False, "Token expired. Please log in again."
        except jwt.InvalidTokenError:
            return False, "Invalid token. Please log in again."
    else:
        return False, "No authorization header found"

@app.route('/api', methods=['GET'])
def home():
    auth_header = request.headers.get('Authorization')
    valid, msg = validate_token(auth_header)

    if valid:
        return jsonify({'message': 'Valid Token'}), 200
    else:
        return jsonify({'message': msg}), 401

