import time
from requests import exceptions as exc

def retry_on_exception(max_retries=3):
    """This decorator implements retry mechanism."""

    def wrap(func):
        def wrapped_f(*args, **kwargs):
            for i in range(max_retries):
                try:
                    return func(*args, **kwargs)
                except (exc.Timeout, exc.ConnectionError):
                    if i < max_retries - 1:   # still have some attempts left
                        time.sleep((2**i)*0.5) # exponential back-off
                        continue
                    else:
                        raise
            return func(*args, **kwargs)
        return wrapped_f
    return wrap

@retry_on_exception(max_retries=3)
def make_request():
    pass  # your request here. For instance: requests.get('https://api.github.com')

import time

def process_message(message):
    # Process the message here
    print("Processed message:", message)

def retry_failed_message(message, max_retries=5):
    retries = 0
    while retries < max_retries:
        try:
            process_message(message)
            break
        except Exception as e:
            print("Error processing message:", e)
            time.sleep(10)
            retries += 1
    if retries >= max_retries:
        print("Message processing failed after", retries, "attempts")

