def handle_nested_queries(query):
    # Check if the query is a string or a list
    if isinstance(query, str):
        return query
    elif isinstance(query, list):
        # Recursively call the function on each element of the list
        result = []
        for q in query:
            result.append(handle_nested_queries(q))
        return result

from threading import Thread
from queue import Queue
from collections import deque

class ThreadSafeQueue(Queue):
    def get(self, block=True, timeout=None):
        with self.mutex:
            return super().get(block, timeout)

class ThreadSafeDeque(deque):
    def append(self, x):
        with self.lock:
            super().append(x)

    def popleft(self):
        with self.lock:
            return super().popleft()

class ThreadSafeThread(Thread):
    def run(self):
        with self.lock:
            super().run()

