from cryptography.hazmat.backends import default_backend

class FirmwareServer:
    def __init__(self):
        # Load the public key used for verifying the signature
        with open("public_key.pem", "rb") as key_file:
            self.public_key = serialization.load_pem_public_key(
                key_file.read(),
                backend=default_backend()
            )

    def verify_signature(self, package, signature):
        # Verify the signature on the firmware update package
        try:
            self.public_key.verify(
                signature,
                package,
                padding.PSS(
                    mgf=padding.MGF1(hashes.SHA256()),
                    salt_length=padding.PSS.MAX_LENGTH
                ),
                hashes.SHA256()
            )
        except InvalidSignature:
            print("Error: Signature could not be verified!")
            return False
        else:
            print("The signature is valid.")
            return True

    def verify_integrity(self, package):
        # Verify the integrity of the firmware update package
        hasher = hashlib.sha256()
        hasher.update(package)
        if hasher.hexdigest() == self.expected_hash:
            print("The firmware package is valid.")
            return True
        else:
            print("Error: Firmware package is invalid!")
            return False

    def install_update(self, package):
        # Install the update if it's both signed and hashed correctly.
        if self.verify_signature(package) and self.verify_integrity(package):
