import requests
import time

def retry_webhook(url, payload, max_retries=5):
    retries = 0
    while True:
        try:
            response = requests.post(url, json=payload)
            if response.status_code == 200:
                return response.json()
            else:
                retries += 1
                time.sleep(retries ** 2)
        except requests.exceptions.RequestException as e:
            retries += 1
            time.sleep(retries ** 2)

