from io import BytesIO

def log_parsing_errors(text, expected_lines):
    try:
        # Splitting on newlines to handle multi-line text correctly
        lines = text.split('\n')

        # Log successful parsing of the entire text
        print(f"Successfully parsed {len(lines)} line(s).")

        for i, line in enumerate(lines, 1):
            if not line.strip():  # Check for empty or whitespace-only lines
                print(f"Warning: Line {i} is empty or contains only whitespace.")
            else:
                print(f"Line {i}: {line}")

    except UnicodeDecodeError as e:
        print(f"Error decoding file: {e}", file=sys.stderr)
    except ValueError as e:
        print(f"Invalid split detected: {e}", file=sys.stderr)
    except Exception as e:
        print(f"Unexpected error during parsing: {e}", file=sys.stderr)

