from cryptography.fernet import Fernet
import os

class KeyVault:
    def __init__(self):
        self.key = None

    # Generate and store a new key in a secure location
    def generate_and_store_new_key(self, secure_location='secure_keys.key'):
        self.key = Fernet.generate_key()

        with open(secure_location, 'wb') as key_file:
            key_file.write(self.key)

    # Load the stored key from a secure location
    def load_stored_key(self, secure_location='secure_keys.key'):
        with open(secure_location, 'rb') as key_file:
            self.key = key_file.read()

    # Encrypt data using the stored key
    def encrypt(self, data):
        fernet = Fernet(self.key)
        return fernet.encrypt(data.encode())

    # Decrypt data using the stored key
    def decrypt(self, encrypted_data):
        fernet = Fernet(self.key)
        return fernet.decrypt(encrypted_data).decode()

class Node:
    def __init__(self):
        self.value = None
        self.votes = 0

    def propose(self, value):
        # This is where each node proposes a value
        self.value = value

    def vote(self, nodes):
        # This is where the votes are counted
        for node in nodes:
            if node.value == self.value:
                self.votes += 1

    def consensus_reached(self, nodes):
        # Checks to see if a consensus has been reached
        majority = len(nodes) // 2 + 1
        for node in nodes:
            if node.votes >= majority and node.value is not None:
                return True
        return False

    def validate_consensus(self, nodes):
        # Validates the consensus mechanism
        self.vote(nodes)
        return self.consensus_reached(nodes)

# Example usage
n1 = Node()
n2 = Node()
n3 = Node()
n4 = Node()

n1.propose('apple')
n2.propose('banana')
n3.propose('cherry')
n4.propose('apple') # In this case, a consensus is reached because 'apple' has the most votes.

nodes = [n1, n2, n3, n4]
for node in nodes:
    print(node.validate_consensus(nodes))  # Should return True for all nodes as they agreed on 'apple'.

