from collections import defaultdict

class Configuration:
    def __init__(self):
        # Initialize with default configuration
        self.database = defaultdict(dict)
        self.logging_level = 'INFO'
        self.security_groups = []

    @classmethod
    def from_dict(cls, config_dict):
        """Create a new Configuration instance from a dictionary"""
        return cls(**config_dict)

    @property
    def logging_level(self):
        """Get the logging level"""
        return self._logging_level

    @logging_level.setter
    def logging_level(self, value):
        if not isinstance(value, str) or value.upper() not in ['DEBUG', 'INFO', 'WARNING', 'ERROR', 'CRITICAL']:
            raise ValueError("Invalid logging level")
        self._logging_level = value.upper()

# Create a new Configuration instance with default values
