def get_pkg_license(package):
    try:
        lines = package.get_metadata_lines('METADATA')
    except:
        lines = package.get_metadata_lines('PKG-INFO')

    for line in lines:
        if line.startswith('License:'):
            return line[9:]
    return '(Licence not found)'

