import locale

def get_user_language():
    # Get the preferred language from the browser headers
    lang = request.headers.get('Accept-Language')
    if not lang:
        return None

    # Parse the language header and extract the language code
    try:
        parts = lang.split(',')
        for part in parts:
            lang_code, quality = part.strip().split(';q=')
            if quality == '1':
                return lang_code
        else:
            return None
    except ValueError:
        return None

    # Use the language code to load the appropriate language file
    try:
        translations = gettext.translation(lang, localedir='/path/to/locale')
        return translations.gettext('Hello world!')
    except IOError as e:
        print('Could not open translation file for language', lang)
        return 'Hello world!'

