import re 

def validate_inputs(form):
    # check if form inputs are not None or Empty string
    if all([value for value in form.values() if value is not None and str(value).strip() != '']):

        # Checking email format validity using Regular Expression
        regex = r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'

        if(re.match(regex, form['email'])):
            return True  # Valid inputs
        else:
            print("Invalid email address")
            return False  # Invalid email format
    else:
        print("All fields are required")
        return False  # All fields not filled

class BanManager():
    def __init__(self):
        self.banned_ips = set()  # You could use a database for persistent storage in a real system.

    def ban(self, ip):
        """Bans an IP address."""
        self.banned_ips.add(ip)

    def is_banned(self, ip):
        """Checks if an IP address is banned."""
        return ip in self.banned_ips

import urllib.parse

def validate_url(url):
    try:
        # Parse the URL
        parsed_url = urllib.parse.urlparse(url)

        # Check if the URL is valid
        if not parsed_url.scheme or not parsed_url.netloc:
            return False

        # Check if the scheme is http or https
        if parsed_url.scheme not in ['http', 'https']:
            return False

        # Check if the domain name has at least 2 characters
        if len(parsed_url.netloc.split(':')[0]) < 2:
            return False

        # If all checks pass, the URL is valid
        return True

    except ValueError:
        # If a ValueError occurs, it means the URL was invalid
        return False

# Test the function
url = input("Enter a URL: ")
if validate_url(url):
    print(f"The URL {url} is valid.")
else:
    print(f"The URL {url} is not valid.")

