import logging
from threading import Thread, Lock
import os

class ActivityTracker:
    def __init__(self):
        self.activities = []
        self.logger = logging.getLogger(__name__)

    def enqueue_activity(self, username: str, message: str, action: str, timestamp: int, priority: str):
        activity = {
            'username': username,
            'message': message,
            'action': action,
            'timestamp': timestamp,
            'priority': priority
        }
        self.activities.append(activity)
        self.logger.info(f"[{timestamp}] {priority} - {action}")

    def log_activity(self, handler: Lock):
        try:
            for activity in self.activities:
                with handler:
                    self.logger.info(f"[{activity['timestamp']}] {activity['priority']} - {activity['action']}")
        except Exception as e:
            logging.error("Failed to log activity", exc_info=True)

    def close(self):
        if hasattr(self, 'file_handle'):
            try:
                os.remove(self.file_handle.name)
            except:
                pass

def write_activity(activity: dict, handler: Lock, file_path: str = "queue.log"):
    with open(file_path, "a", encoding="utf-8") as f:
        log_line = "[{timestamp}] {priority} - {action}: {message}\n".format(
            timestamp=activity['timestamp'],
            priority=activity['priority'],
            action=activity['action'],
            message=activity['username'] if activity['username'] else "Anonymous"
        )
        f.write(log_line)

def main():
    tracker = ActivityTracker()

    # Initial activities
    tracker.enqueue_activity("system", "", "started connecting", int(os.timespan(), os.timegm(os.currenttimespan())), "[INFO]")
    tracker.enqueue_activity("", "", "began processing queue", int(os.timespan(), os.timegm(os.currenttimespan())), "[INFO]")

    def activity_logger():
        file_path = "queue.log"
        if os.name == 'nt':
            file_handle = open(file_path, "w+")
            file_handle.seek(0)
            file_handle.write("")
            file_handle.close()
            handler = Lock()
            tracker.logger.info("Started logging queue activities.")

            try:
                while True:
                    activity = tracker.activities.pop(0)
                    if not activity['priority']:
                        continue
                    write_activity(activity, handler)
                    tracker.log_activity(handler)
            except (IndexError, KeyboardInterrupt):
                file_handle = open(file_path, "w+")
                file_handle.write("")
                file_handle.close()
                tracker.logger.info("Queue logging stopped.")

    thread = Thread(target=activity_logger)
    thread.start()

if __name__ == "__main__":
    main()

