class Resource:
    def __init__(self):
        pass

    def get(self, user):
        if not self.__access__(user):
            raise Forbidden("Denied access to resource")
        return True  # Success of the get operation

    def add(self, user, data):
        if not self.__access__(user):
            raise Forbidden("Denied access to resource")
        # Perform addition logic here
        pass

    def delete(self, user):
        if not self.__access__(user):
            raise Forbidden("Denied access to resource")
        # Perform deletion logic here
        pass

    def __access__(self, obj):
        # Policy: Only admins can access the resource
        return isinstance(obj, User) and obj.username == 'admin'

import csv

def read_csv(filename):
    data = []

    try:
        with open(filename, 'r') as file:
            reader = csv.reader(file)

            for row in reader:
                data.append(row)

    except FileNotFoundError:
        print("File not found.")
    except Exception as e:
        print("An error occurred while reading the file: ", str(e))

    return data

