import time

class EventProcessor:
    def __init__(self):
        self.start = 0
        self.end = 0

    def start_timer(self):
        self.start = time.time()

    def end_timer(self):
        self.end = time.time()

    def get_latency(self):
        return self.end - self.start

    def process_event(self, event):
        # Simulate the processing of an event
        print(f"Processing event: {event}")

        self.start_timer()  # Start timer
        time.sleep(1)  # Replace with actual event processing code here
        self.end_timer()   # End timer

        latency = self.get_latency()
        print(f"Event {event} processed in {latency:.6f} seconds")

if __name__ == "__main__":
    processor = EventProcessor()

    for i in range(5):  # Simulate processing of 5 events
        processor.process_event(i)

