class PaymentGateway:
    def __init__(self, secret_key):
        self.secret_key = secret_key

    def verify_payment(self, token):
        # Verify the HMAC token sent with the payment request
        return hmac.compare_digest(token, f"{secret_key}:{payment_hash}")

class OrderItem:
