class OrderPaymentProcessor:
    def __init__(self, order_items: List[OrderItem], payment_gateway: PaymentGateway):
        self.order_items = order_items
        self.payment_gateway = payment_gateway

    def calculate_total(self) -> float:
        # Calculate the total cost of all items in the order
        return sum(item.product_id * item.quantity for item in self.order_items)

    def process_payment(self, customer_info: Dict, payment_method: str) -> bool:
        # Verify customer information and payment method using secure methods (e.g., hashing)
        customer_hash = hmac.new(customer_info["secret_key"].encode(), customer_info["data"].encode(), "sha256").digest()
        if not self.payment_gateway.verify_payment(customer_hash):
            return False

        # Process the payment using a secure gateway
        payment_token = generate_payment_token(payment_method, customer_info)
        if not self.payment_gateway.verify_payment(payment_token):
            raise Exception("Payment verification failed")

        # Update order status to "paid" and update bank account with payment amount
        print(f"Order paid successfully. New balance: ${self.calculate_total()}")

