import os
from PIL import Image
from PyPDF2 import PdfReader
from io import BytesIO

def validate_pdf(file_path):
    # Check if file exists and is a file
    if not os.path.exists(file_path) or not os.path.isfile(file_path):
        return False, "File does not exist or is not a file"

    # Open the PDF file
    try:
        with open(file_path, 'rb') as f:
            pdf_data = f.read()
    except Exception as e:
        return False, str(e)

    # Try to extract text from PDF
    try:
        reader = PdfReader(BytesIO(pdf_data))
        for page in reader.pages:
            text = page.extract_text()
            if not text.strip():
                return False, "PDF contains no visible content"
    except Exception as e:
        return False, str(e)

    # Try to open the PDF using PIL
    try:
        img = Image.open(file_path)
    except Exception as e:
        return False, str(e)

    # Check if image is present in the PDF (i.e., there's been tampering)
    if not img.size:
        return False, "Tampered with"

    return True, ""


# Example usage
file_path = "/path/to/your/pdf/file.pdf"
is_valid, error_message = validate_pdf(file_path)

if not is_valid:
    print("Invalid PDF:", error_message)
else:
    print("Valid PDF")

import time
from functools import wraps
from collections import defaultdict

class EmailRateLimiter:
    def __init__(self, max_requests, time_window):
        self.max_requests = max_requests
        self.time_window = time_window
        self.request_timestamps = defaultdict(list)

    def rate_limited(self, func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            current_time = int(time.time())
            for timestamp in list(self.request_timestamps['email']):
                if current_time - timestamp < self.time_window:
                    return "Email Rate Limit Exceeded"
            if len(self.request_timestamps['email']) >= self.max_requests:
                return "Email Rate Limit Exceeded"
            self.request_timestamps['email'].append(current_time)
            return func(*args, **kwargs)

        return wrapper

# Example usage
@EmailRateLimiter(max_requests=10, time_window=60).rate_limited
def send_email(subject, body):
    print(f"Sending email: {subject} - {body}")
    # Simulate sending an email
    time.sleep(1)  # wait for 1 second

send_email("Test Email", "This is a test email")
send_email("Another Test Email", "Another test email")  # This will be rate limited
time.sleep(60)  # Wait for 1 minute to reset the rate limit
send_email("Another Test Email", "Another test email")  # This should not be rate limited again

