import os
import shutil

def perform_backup(tenant):
    source = f'/path/to/{tenant}'  # Path of the tenant's folder
    destination = f'/path/to/backups/{tenant}'  # Backup path

    if not os.path.exists(destination):  
        shutil.copytree(source, destination)  # Copy entire directory to backup location
    else:  # If the directory already exists in the backup folder
        for file_name in os.listdir(source):
            full_file_name = os.path.join(source, file_name)  
            if os.path.isfile(full_file_name):
                shutil.copy2(full_file_name, destination)  # Copy files from tenant's folder to backup folder

tenants = ['tenant1', 'tenant2', 'tenant3']  # List of tenants
for tenant in tenants:
    perform_backup(tenant)  # Perform backup for each tenant

import requests
import time
import statistics

class ApiResponseTimeMonitor:
    def __init__(self, api_url):
        self.api_url = api_url
        self.response_times = []

    def get_response_time(self):
        start_time = time.time()
        try:
            response = requests.get(self.api_url)
            response.raise_for_status()  # Raise an exception for HTTP errors
        except requests.RequestException as e:
            print(f"Request failed: {e}")
            return None

        end_time = time.time()
        response_time = end_time - start_time
        self.response_times.append(response_time)
        return response_time

    def get_average_response_time(self):
        if not self.response_times:
            return 0.0
        return statistics.mean(self.response_times)

    def get_min_max_response_times(self):
        if not self.response_times:
            return None, None
        return min(self.response_times), max(self.response_times)

def main():
    api_url = "https://api.example.com/endpoint"
    monitor = ApiResponseTimeMonitor(api_url)

    # Test the API 10 times and print response times
    for _ in range(10):
        response_time = monitor.get_response_time()
        if response_time is not None:
            print(f"Response time: {response_time:.2f} seconds")

    average_response_time = monitor.get_average_response_time()
    min_max_response_times = monitor.get_min_max_response_times()

    print(f"\nAverage response time: {average_response_time:.2f} seconds")
    if min_max_response_times:
        print(f"Minimum response time: {min_max_response_times[0]:.2f} seconds")
        print(f"Maximum response time: {min_max_response_times[1]:.2f} seconds")

if __name__ == "__main__":
    main()

import requests
from urllib.parse import urlparse, parse_qs, quote, unquote_plus
from itertools import chain

def get_nesting_data(api_base_url, initial_query_params=None):
    """Fetches all data from an API endpoint with pagination support."""
    params = initial_query_params or {}

    results = []
    total_records = 0
    pages = []

    # Determine if pagination is needed by checking for 'limit' in the response
    has_next = True

    while has_next:
        url = f"{api_base_url}?{quote(params)}"
        response = requests.get(url, timeout=10)

        try:
            data = response.json()
        except ValueError as e:
            # Handle JSON parsing errors
            print(f"Error parsing response: {e}")
            break

        pages.append(data.get('links', {}).get('next', None))

        for item in data['results']:
            results.append(item)
            total_records += 1

    if pages:
        last_page_url = pages[-1]
        has_next = urlparse(last_page_url).query.endswith("next")

    return {'results': results, 'total_records': total_records, 
            'has_next': has_next}

def get_nested_data(nested_params):
    """Fetches nested data using a set of query parameters."""
    try:
        response = requests.get(f"api_base_url?{quote(nested_params)}",
                                timeout=10)

        if response.status_code == 200 and 'data' in response.json():
            return response.json()['data']
        else:
            print(f"Status code {response.status_code}: {response.text}")
            return None
    except requests.exceptions.RequestException as e:
        print(f"Request failed: {str(e)}")
        return None

def main():
    # Initial parameters for the first API call, e.g., page number or filter.
    initial_query_params = {
        'page': 1,
        'size': 10
    }

    main_results = get_nesting_data(api_base_url='https://api.example.com/main',
                                   initial_query_params=initial_query_params)

    # Process each result to fetch nested data if necessary.
    for item in main_results['results']:
        # Extract the nesting parameter, e.g., 'id' or 'key'.
        nesting_param = quote(item.get('nesting_param', ''))

        if nesting_param:
            nested_data = get_nested_data(nesting_param)
            if nested_data:
                print(f"Nested data for item {item}: {nested_data}")

    # Optional: Convert the results to a structured format.
    main_results['data'] = list(chain.from_iterable(main_results['results']))

if __name__ == "__main__":
    import sys
    api_base_url = 'https://api.example.com/main'  # Replace with your API base URL
    main()

import os
import json
from typing import Dict, Optional
from itertools import chain

def secure_load(config_path: str) -> dict:
    """Securely load and return the contents of a configuration file."""

    if not os.path.exists(config_path):
        raise IOError(f"Configuration file not found at {config_path}")

    try:
        with open(config_path, 'r') as f:
            content = json.load(f)

        # Handle sensitive fields
        for key in ['DB_HOST', 'DATABASE_PORT', 'SECRET_KEY']:
            if key in content and isinstance(content[key], str):
                encrypted_value = secure_deserialize(content[key])
                content[key] = encrypted_value

        return content

    except (IOError, PermissionError) as e:
        raise RuntimeError(f"Failed to load configuration file {config_path}: {str(e)}")

    except UnicodeDecodeError:
        raise RuntimeError(f"Corrupted configuration file at {config_path} containing non-ASCII characters")

    except KeyError as ke:
        error_msg = f"Missing key '{ke.args[0].strip("'(')}' if it's a string') in configuration file {os.path.basename(config_path)}"
        raise RuntimeError(error_msg)

def secure_deserialize(sensitive_value: str) -> Optional[str]:
    """Decrypt sensitive values using Triple DES algorithm."""

    from binascii import dht
    from base64 import b64decode, b64encode

    # Decrypt DES cipher by turning it into three 16-byte chunks:
    def triple_des_decrypt(value):
        if len(value) % 3 != 0:
            return None

        parts = [value[i*3:(i+1)*3] for i in range(3)]

        d1 = b'\x00' + binascii.dechex(dht(b64decode(parts[0]))).encode()
        d2 = b'\x00' + binascii.dechex(dht(b64decode(parts[1]))).encode()
        d3 = b'\x00' + binascii.dechex(dht(b64decode(parts[2]))).encode()

        return (d1 + d2 + d3)[:-6].rstrip(b'\x00').decode('utf-8')

    try:
        if sensitive_value.startswith('---'):
            return None
        decrypted = triple_des_decrypt(sensitive_value)

        # If the result is non-null and not empty, return it
        if decrypted and decrypted.strip():
            return decrypted

        raise RuntimeError(f"Decrypted value for key '{sensitive_value}' cannot be empty or None")
    except Exception as e:
        raise RuntimeError(f"Failed to decrypt configuration sensitive value: {e}")

def secure_serialize(sensitive_value: Optional[str]) -> str:
    """Encrypt a plaintext string using Triple DES algorithm."""

    from binascii import dht, pack
    from base64 import b64encode

    def triple_des_encrypt(plaintext):
        key = os.urandom(16)
        ciphertext = encrypt(plaintext, key)

        return (
            b64encode(ciphertext + dht(b'<?>).'.encode()))[0:32]

    def encrypt(value_to_encrypt, encryption_key):
        if isinstance(value_to_encrypt, bytes):
            value_to_encrypt = value_to_encrypt.decode('utf-8')

        # Only encrypt non-empty strings
        if not value_to_encrypt:
            return b'\x00'

        try:
            key = os.urandom(16)
            ciphertext = pack('>I', len(value_to_encrypt)) + dht(
                value_to_encrypt.encode('utf-8') + encryption_key.encode('utf-8')
            )

            return (
                (b64encode(ciphertext).decode('utf-8'),
                 b64encode(dht(b'A?').decode('utf-8')).decode('utf-8'))
            )[0]
        except Exception as e:
            return None

    try:
        if sensitive_value is None or not isinstance(sensitive_value, str):
            raise RuntimeError(f"encrypt requires a string value for key '{sensitive_value}'")

        if sensitive_value.strip() == '':
            return ''

        encrypted, nonce = triple_des_encrypt(sensitive_value)
        return f"{encrypted}{nonce}"

    except Exception as e:
        raise RuntimeError(f"Failed to encrypt configuration sensitive value: {e}")

def read_config(config_path: str) -> Dict[str, Any]:
    """Read and merge all config files in the version-controlled config directory."""

    config_files = tuple(f for f in os.listdir(config_dir)
                        if f.endswith('.yaml') or f.endswith('.yml'))
    merged_config = {}

    for config_file in config_files:
        full_path = os.path.join(config_dir, config_file)
        content = secure_load(full_path)

        if isinstance(content, dict):
