import time
from collections import deque

class MessageProcessorMonitor:
    def __init__(self, window_size):
        self.window_size = window_size
        self.timestamps = deque(maxlen=window_size)

    def process_message(self, message):
        # your message processing logic here
        pass

    def get_processing_rate(self):
        if len(self.timestamps) < 2:
            return None

        time_diff = self.timestamps[-1] - self.timestamps[0]
        messages_processed = len(self.timestamps)
        processing_rate = messages_processed / time_diff if time_diff != 0 else float('inf')
        return processing_rate

    def start_monitoring(self):
        try:
            while True:
                self.timestamps.append(time.time())
                rate = self.get_processing_rate()

                if rate is not None:
                    print('Current processing rate: ', round(rate,2), ' messages/second')

                time.sleep(1) # adjust as needed to control the monitoring frequency
        except KeyboardInterrupt:
            print('Monitoring stopped.')

monitor = MessageProcessorMonitor(window_size=60)
