import datetime
import threading

def make_cron_job(minute, hour, day):
    def schedule():
        while True:
            now = datetime.datetime.now()
            if (now.hour == hour) and (now.minute == minute) and (now.day == day):
                print(f"Running at {minute}:{hour} on {day}")
                time.sleep(60 * minute + hour * 60)
    return schedule

def main():
    jobs = [
        (10, 14, 5),
        (30, 10, 6)
    ]
    for job in jobs:
        minute, hour, day = job
        thread = threading.Thread(target=make_cron_job, args=(minute, hour, day))
        thread.start()

if __name__ == "__main__":
    main()

import http.client
from urllib.parse import quote
import json
import secrets

def send_request(verb, url):
    nonce = secrets.token_hex(32)
    headers = {
        'X-Nonce': nonce,
        'Content-Type': 'application/json',
    }
    params = {'id': nonce}

    http_client = http.client.HTTPClient(url, timeout=10)
    request = f"{verb}(...)"

    try:
        req = getattr(http_client, request)(headers=headers, params=params)
        response = await http_client.send(req)

        while not (response.getcode() == 200 and 'Acknowledged' in response.json()):
            pass

        return json.loads(response.body.decode())

    except Exception as e:
        print(f"Request failed: {e}")
        return None

