class SecureIoTCommunication:
    def __init__(self, device_host, device_port):
        self.device_host = device_host
        self.device_port = device_port
        self aes_key = b'\xdeadbeef'
        self.max rate = 10  # limit requests to 10 per second

    def _encrypt_data(self, data):
        if not isinstance(data, bytes):
            data_bytes = data.encode('utf-8')
        else:
            data_bytes = data
        aes = PyAESEncryption.new(self.aes_key)
        ciphertext = aes.encrypt(data_bytes)
        return bytes.fromhex(hex(ciphertext)[2:-2])

    def _decrypt_data(self, ciphertext):
        aes = PyAESEncryption.new(self.aes_key)
        plaintext = aes.decrypt(ciphertext)
        return plaintext.decode('utf-8', errors='ignore')

    def _connect_to_device(self):
        client = SSHClient()
        client.set_missing_host_key_policy(socket.getdefaultsocket().getselectTimeout(1))

        try:
            client.connect(self.device_host, int(self.device_port), username, password)
            print("Connected to device successfully")
            return client
        except Exception as e:
            raise RuntimeError(f"Failed to connect to device: {e}")

    def _execute_command(self, command):
        if not hasattr(self, 'client'):
            self.client = self._connect_to_device()

        with socket.timeout(10):
            channel = client.invoke("transport")
            try:
                response = channel.run(command + "\n").strip()
                return response
            except timeout as e:
                raise RuntimeError(f"Command execution timed out: {e}")

    def send_command(self, command, data=None):
        if not hasattr(self, 'client'):
            self.client = self._connect_to_device()

        try:
            request = f"{command}\n"
            if data is not None:
                encrypted_data = self._encrypt_data(data)
                request += encrypted_data
            else:
                request += "NoData\r\n"

            queued = False

            while True:
                try:
                    response = self._execute_command(request)
                    return response
                except socket.timeout as e:
                    print(f"Waiting for device response: {e}")
                except Exception as e:
                    if not queued and str(e).lower().find("max requests") >= 0:
                        time.sleep(1)
                        continue
                    else:
                        raise

            # To handle rate limiting, you can implement a queue system here

        except Exception as e:
            print(f"Error sending command: {e}")

