def validate_access_token(token):
    parts = token.split()

    if len(parts) < 4:
        return False

    if parts[0] != 'Bearer':
        return False

    if not (parts[1].startswith('http://') or parts[1].startswith('https://')):
        return False

    try:
        username_part = parts[2]
        password_part = parts[3].split('=')[1]
    except IndexError as e:
        return False

    if not ('=' in username_part):
        return False

    # Check for optional refresh token
    try:
        parts[4]
    except IndexError:
        pass  # No refresh token is allowed

    return True

