import re
from functools import total_ordering
from os.path import basename, isfile, exists, getsize

@total_ordering
class FileName:
    def __init__(self, filename):
        self.filename = filename

    @staticmethod
    def validate_filename(filename):
        # Check if the file already exists
        if exists(filename):
            raise ValueError(f"File {filename} already exists.")

        # Check if the file is a directory
        if isfile(filename) or isdir(filename):
            raise ValueError(f"{filename} is not a valid filename.")

        # Check prohibited characters and special regex patterns
        pattern = r"[^a-zA-Z0-9._\-]"
        if re.search(pattern, filename):
            raise ValueError("Invalid character found in file name.")

    @staticmethod
    def validate_extension(filename):
        extension = basename(filename).split('.')[-1]
        # Check prohibited extensions
        invalid_extensions = ['.exe', '.zip']
        if extension.lower() in invalid_extensions:
            return False

        # Check file size
        if getsize(filename) > 10 * 1024 * 1024:  # 10MB
            return False

        return True

    @staticmethod
    def validate_file_name(filename):
        try:
            FileName.validate_filename(filename)
            if not FileName.validate_extension(filename):
                raise ValueError("Invalid file extension.")
            return True, filename
        except ValueError as e:
            print(f"Validation error: {e}")
            return False, None

def main():
    filename = input("Enter the file name: ")
    valid, filename = FileName.validate_file_name(filename)
    if not valid:
        print("File is invalid or does not exist.")
    else:
        print(f"File '{filename}' is valid.")

