import threading
from queue import Queue

class EventProcessor:
    def __init__(self):
        self.event_queue = Queue()
        self.lock = threading.Lock()

    def add_event(self, event_id):
        with self.lock:
            # Check if there are any events in the queue that haven't been processed yet
            while not self.is_empty():
                event = self.event_queue.get()
                print(f"Processing event {event['id']}")
                self.queue.remove(event)

            # Add our new event to the queue
            self.event_queue.put({'id': event_id})

    def is_empty(self):
        return self.event_queue.empty()

    def process_events(self):
        while not self.is_empty():
            event = self.event_queue.get()
            print(f"Processing event {event['id']}")

# Example usage:
if __name__ == "__main__":
    processor = EventProcessor()

    # Simulate out-of-order events
    import threading
    threads = []
    for i in range(5):
        thread = threading.Thread(target=processor.add_event, args=(i,))
        thread.start()
        threads.append(thread)

    # Wait for all threads to finish
    for thread in threads:
        thread.join()

    # Process the events
    processor.process_events()

