# Set the maximum number of requests per minute
MAX_REQUESTS = 10

# Create a queue to store the current requests
requests = deque(maxlen=MAX_REQUESTS)

def rate_limit(func):
    def wrapper(*args, **kwargs):
        now = time.time()
        requests.append((now, func))
        if len(requests) == MAX_REQUESTS:
            # Block the request if the queue is full
            raise TooManyRequestsError("Rate limit exceeded")
        return func(*args, **kwargs)
    return wrapper

