import psutil
import time

def monitor_pipeline(process_name, threshold=80.0):
    """Monitors a specific process's CPU usage."""
    while True:
        for proc in psutil.process_iter(['pid', 'name', 'cpu_percent']):
            if proc.info['name'] == process_name:
                cpu_usage = proc.info['cpu_percent']
                print(f"{process_name} is using {cpu_usage}% CPU.")
                if cpu_usage > threshold:
                    print(f"Warning: {process_name} exceeded the CPU usage threshold of {threshold}%!")
        time.sleep(5) # wait for 5 seconds before checking again

