import os
import subprocess
from configparser import ConfigParser

class VersionControlledConfig:
    def __init__(self, filename, repo_path=None):
        self.filename = filename

        if not repo_path:
            # Use the directory where the file is located as the default repository path
            self.repo_path = os.path.dirname(os.path.abspath(self.filename))
        else:
            self.repo_path = repo_path

        self.config = ConfigParser()
        self.config.read(self.filename)

    def get(self, section, option):
        return self.config.get(section, option)

    def set(self, section, option, value):
        if not self.config.has_section(section):
            self.config.add_section(section)

        # Modify the configuration and commit the changes
        self.config.set(section, option, value)
        with open(self.filename, 'w') as configfile:
            self.config.write(configfile)

        # Add the modified file to Git's staging area and commit it
        subprocess.run(['git', '-C', self.repo_path, 'add', self.filename])
        subprocess.run(['git', '-C', self.repo_path, 'commit', '-m', f'Set {section}.{option} to {value}'])

    def __str__(self):
        return str(self.config)

import threading
import time
import signal

class TimeoutException(Exception):
    """Raised when a request times out"""
    pass

class TimeoutHandler:
    def __init__(self, timeout):
        self.timeout = timeout
        self.is_running = False

    def handle_timeout(self, func, *args, **kwargs):
        """Run the given function with a specified timeout"""
        thread = threading.Thread(target=self._run_func, args=(func, *args, **kwargs))
        thread.start()
        thread.join(self.timeout)
        if thread.is_alive():
            raise TimeoutException("Function timed out")

    def _run_func(self, func, *args, **kwargs):
        try:
            return func(*args, **kwargs)
        except Exception as e:
            # Log the exception and re-raise it
            print(f"Error in {func.__name__}: {str(e)}")
            raise

def signal_handler(signum, frame):
    """Handle SIGALRM signal to trigger a timeout"""
    raise TimeoutException("Timeout")

