def is_valid_code(code):
    parts = code.split('-')
    # Check for any empty strings in parts
    if any(len(part) == 0 for part in parts):
        return False
    # Check each part based on its position
    for i, part in enumerate(parts):
        if i % 2 == 0:
            if not part.isalpha():
                return False
        else:
            if not part.isdigit():
                return False
    return True

from flask import Flask, jsonify, request, abort
from werkzeug.security import generate_password_hash, check_password_hash
from functools import wraps
import jwt
import datetime

app = Flask(__name__)
app.config['SECRET_KEY'] = 'your-secret-key'  # Change this!

# Dummy user database (replace with a real one)
users = {
    "testuser": generate_password_hash("testpassword")
}

def token_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = None

        if 'x-access-token' in request.headers:
            token = request.headers['x-access-token']

        if not token:
            return jsonify({'message': 'Token is missing!'}), 401

        try:
            jwt.decode(token, app.config['SECRET_KEY'])
        except:
            return jsonify({'message': 'Token is invalid!'}), 401

        return f(*args, **kwargs)
    return decorated

@app.route('/login', methods=['POST'])
def login():
    if not request.json or not 'username' in request.json or not 'password' in request.json:
        abort(400)

    username = request.json['username']
    password = request.json['password']

    if username not in users or not check_password_hash(users[username], password):
        return jsonify({'message': 'Could not verify!'}), 401

    token = jwt.encode({'user': username, 'exp': datetime.datetime.utcnow() + datetime.timedelta(minutes=30)}, app.config['SECRET_KEY'])
    return jsonify({'token': token.decode('UTF-8')})

@app.route('/protected', methods=['GET'])
@token_required
def protected():
    # Your code to retrieve data or perform operations goes here...
    return jsonify({'message': 'You are viewing a protected resource!'})

