import requests
from requests.exceptions import RequestException

def get_data_from_api(url, api_key):
    # Headers including API key
    headers = {'Authorization': 'Bearer %s' % api_key}

    try:
        response = requests.get(url, headers=headers)

        # If the request is successful (status code 200), return the JSON data
        if response.status_code == 200:
            return response.json()
        else:
            print('Request failed with status code', response.status_code)
    except RequestException as e:
        # Catch any errors that occur during the request and print them
        print('Request failed due to an exception: ', str(e))

