from contractlib import Contract

class EscrowContract(Contract):
    def __init__(self, owner):
        super().__init__()
        self.owner = owner

    def __call__(self, buyer, seller, amount):
        # Check if the escrow is already open for this transaction
        if self.get_open_escrows().find((buyer, seller)) != -1:
            raise ValueError("Escrow already exists")

        # Initialize the escrow
        self.add_open_escrow((buyer, seller), amount)

    def get_owner(self):
        return self.owner

    def get_open_escrows(self):
        # Assuming a simple data structure for the open escrows ( buyer, seller, amount )
        return self.data["openEscrows"]

    def add_open_escrow(self, escrow_id, amount):
        # Add a new open escrow
        if not self.data["openEscrows"]:
            self.data["openEscrows"] = []
        self.data["openEscrows"].append((escrow_id[0], escrow_id[1], amount))

import hashlib
import random
import string

class ConsensusMechanism:
    def __init__(self, nodes):
        self.nodes = nodes

    def generate_random_string(self, length=16):
        return ''.join(random.choice(string.ascii_uppercase + string.digits) for _ in range(length))

    def validate_consensus_mechanism(self, proposed_block_hash, expected_block_hash):
        # Hash the proposed block hash using SHA-256
        proposed_block_hash_hex = hashlib.sha256(proposed_block_hash.encode()).hexdigest()

        # Compare the proposed and expected block hashes
        if proposed_block_hash_hex == expected_block_hash:
            return True
        else:
            return False

# Example usage
