class Auth:
    def __init__(self, config):
        self.config = config

    def get_token_for_user(self) -> Optional[Dict[str, Any]]:
        """
        Get token for user.
        """
        params = {
            'grant_type': 'authorization_code',
            'redirect_uri': self.config['RedirectUri'],
            'client_id': self.config['clientId'],
            'client_secret': self.config['ClientSecret']
        }

        response = requests.post(
            'https://api.example.com/oauth2/token',
            params=params,
            auth=base64.b64encode(f"{self.config['ClientId']}:{self.config['ClientSecret']}".encode()).decode()
        )

        if response.status_code == 200:
            return response.json()

        raise ValueError(f"Invalid token. HTTP status: {response.status_code}")

    def refresh_access_token(self, token_data: Dict[str, Any]) -> Optional[Dict[str, Any]]:
        """
        Refresh access token.
        """
        if not token_data.get('access_token'):
            return None

        expires_at = datetime.datetime.fromtimestamp(token_data['expires_in']) + datetime.timedelta(seconds=1)

        params = {
            'new_client_id': self.config['ClientId'],
            'new_client_secret': self.config['ClientSecret'],
            'grant_type': 'refresh_token',
            'token': token_data.get('access_token'),
            'exp': expires_at.timestamp()
        }

        response = requests.post(
            'https://api.example.com/oauth2/token',
            params=params,
            auth=base64.b64encode(f"{self.config['ClientId']}:{self.config['ClientSecret']}".encode()).decode()
        )

        if response.status_code == 200:
            return response.json()

        raise ValueError("Failed to refresh token")

    def get_current_user(self, token_data: Dict[str, Any]) -> Optional[Dict[str, Any]]:
        """
        Validate and return current user.
        """
        self.check_token validity(token_data)
        return {
            'username': 'user',
            'email': 'user@example.com',
            'access_token': token_data.get('access_token'),
            'expires_in': token_data.get('expires_in')
        }

    def check_token_validity(self, token_data: Dict[str, Any]) -> bool:
        """
        Validate access token.
        """
        if not token_data.get('access_token'):
            raise ValueError("Invalid token")

        try:
            decoded_token = self.decode_token(token_data['access_token'])
        except Exception as e:
            raise ValueError(f"Token decoding failed: {e}")

        now = time.time()
        if decoded_token['exp'] < now + 3600:
            raise TokenNotRefreshable()

        return True

    def decode_token(self, token: str) -> Dict[str, Any]:
        """
        Decode JWT token.
        """
        payload = self.decode_base64urlsafe_b64str(token)
        if 'exp' not in payload:
            raise ValueError("Invalid token")

        return {
            'access_token': payload['access_token'],
            'expires_in': int(payload['expires_in'] or 0),
            'user_id': None,
            'username': None
        }

