# Create a new ACL for the bucket
def create_acl(s3, bucket_name):
    response = s3.put_bucket_acl(Bucket=bucket_name,
                                Grantee={
                                    'CanonicalUser': 'authenticated-users',
                                },
                                ACL='bucket-owner-full-control')
    return response

# Update an existing ACL for the bucket
def update_acl(s3, bucket_name, user):
    response = s3.put_bucket_policy(
        Bucket=bucket_name,
        Policy={
            "Version": "2012-10-17",
            "Statement": [
                {
                    "Sid": "",
                    "Effect": "Allow",
                    "Principal": {
                        "AWS": user
                    },
                    "Action": "*",
                    "Resource": bucket_name + "*"
                }
            ]
        }
    )
    return response

# Delete an ACL for the bucket
def delete_acl(s3, bucket_name):
    s3.delete_bucket_policy(Bucket=bucket_name)
    return True

# Get the ACL for the bucket
def get_acl(s3, bucket_name):
    response = s3.get_bucket_acl(Bucket=bucket_name)
    return response

# Main function
