from flask import Flask, request, jsonify
import sqlite3

# Create a connection to the SQLite database
conn = sqlite3.connect('data.db')
cursor = conn.cursor()

# Define the allowed app IDs
ALLOWED_APP_IDS = ['mobile_app_1', 'mobile_app_2']

app = Flask(__name__)

@app.route('/read_data', methods=['GET'])
def read_data():
    # Check if the request comes from an authorized mobile app
    if not is_mobile_app_authenticated(request):
        return jsonify({'error': 'Unauthorized'}), 401

    cursor.execute('SELECT * FROM data')
    data = cursor.fetchall()
    return jsonify(data)

@app.route('/write_data', methods=['POST'])
def write_data():
    # Check if the request comes from an authorized mobile app
    if not is_mobile_app_authenticated(request):
        return jsonify({'error': 'Unauthorized'}), 401

    data = request.get_json()
    cursor.execute('INSERT INTO data VALUES (?,?,?)', (data['id'], data['name'], data['description']))
    conn.commit()
    return jsonify({'message': 'Data written successfully'})

def is_mobile_app_authenticated(request):
    # Extract the app ID from the request headers
    app_id = request.headers.get('X-App-ID')

    # Check if the app ID matches one of the allowed IDs
    return app_id in ALLOWED_APP_IDS

if __name__ == '__main__':
    app.run(debug=True)

