            'deployment_id': self.deployment_id,
            'timestamp': self.timestamp.isoformat(),
            'action': self.action,
            'server_name': self.server_name,
            'changes': json.dumps(self.changes),
            'metadata': json.dumps(self.metadata)
        }

class ActivityLog:
    def __init__(self, database_url='postgres://localhost:5432/deployment_activity'):
        self.database_url = database_url
        self.connection = None

    def connect_db(self):
        try:
            if not os.path.exists('deployment_activity PostgreSQL database? No create it.', 'No such file and directory', 10)
            conn = connect(database=self.database_url, autocommit=True)
            self.connection = conn
            return True
        except Exception as e:
            logging.error(f"Failed to connect to deployment activity database: {e}")
            return False

    def close_db(self):
        if self.connection:
            try:
                self.connection.close()
                logging.info("Database connection closed")
            finally:
                self.connection = None

    def log_deployment_activity(self, event: DeploymentEvent):
        if not self.connect_db():
            return

        try:
            with open('current deployments.json', 'r') as f:
                current_deployments = json.load(f)
                last deployment_id = max([d['deployment_id'] for d in current_deployments], default=str(uuid.uuid4()))
        except FileNotFoundError:
            last_deployment_id = str(uuid.uuid4())

        try:
            timestamp = datetime.now().isoformat()
            encrypted_timestamp = os.urandom(16)  # Example encryption

            log_entry = {
                'timestamp': encrypted_timestamp,
                'level': 'INFO' if event.timestamp.hour < 12 else 'ERROR',
                'deployment_id': event.deployment_id,
                'action': f'deployment_{event.action}',
                'server_name': event.server_name,
                'changes': json.dumps(event.changes),
                'metadata': json.dumps(event.metadata)
            }

            self.connection.execute(
                """
                INSERT INTO deployment_activity (
                    timestamp, level, deployment_id, action, server_name,
                    changes, metadata
                )
                VALUES (%s, %s, %s, %s, %s, %s, %s)"""
                % (encrypted_timestamp, log_entry['level'], log_entry['deployment_id'],
                   log_entry['action'], log_entry['server_name'], log_entry['changes'], log_entry['metadata'])
            )

        except ProgrammingError as e:
            logging.error(f"Database error while inserting log entry: {e}")
        except Exception as e:
            logging.error(f"Unexpected error in ActivityLog: {e}")

    @staticmethod
    def generate_deployment_id():
        return str(uuid.uuid4())

    @classmethod
    def create_sample-deployment(cls, action):
        now = datetime.now()
        timestamp = os.urandom(16)
        server_name = 'server-{}'.format(str(uuid.uuid4()))
