    if not isinstance(data, bytes) or len(data) < 1:
        raise ValueError("Invalid data")

    # Load the data into a new object
    try:
        obj = pickle.loads(data)
    except pickle.UnpicklingError as e:
        raise ValueError("Failed to deserialize object") from e

    # Check if the object is of the expected type
    if not isinstance(obj, ExpectedType):
        raise TypeError("Unexpected type for deserialized object")

