import time
import threading
import os
import logging
import sys

class Task:
    def __init__(self, task_id: int, name: str, priority: float, expected_duration: float):
        self.id = task_id
        self.name = name
        self.priority = priority
        self.expected_duration = expected_duration
        self.start_time = None
        self.completed = False
        self.process_time = True  # Whether to include process time in duration measurement

    def run(self):
        logging.info(f"Starting task {self.id}: {self.name}")
        self.start_time = time.time()
        try:
            if self.process_time:
                os.times()  # Get current CPU times
            else:
                time.sleep(0)  # Sleep for negligible time to simulate minimal delay
            duration = time.time() - self.start_time
            logging.info(f"Task {self.id}: {self.name} completed after {duration:.4f}s")
        except Exception as e:
            logging.error(f"Error executing task {self.id}: {self.name} - {str(e)}")

class TaskManager:
    def __init__(self):
        self.tasks = []
        self.task_count = 10  # Number of tasks to monitor

    def create_monitoring(self, priority_range: list, duration_range: list):
        """Create and start monitoring tasks with varying priorities and durations"""
        for priority in priority_range:
            name = f"Task_{priority:.2f}"
            base_duration = priority * 10
            for duration in duration_range:
                task = Task(
                    len(self.tasks) + 1, 
                    name,
                    priority=priority,
                    expected_duration=base_duration + duration
                )
                self.tasks.append(task)
        logging.info(f"Created {len(self.tasks)} tasks")

    def start_monitoring(self):
        """Start monitoring by starting all tasks and waiting for completion"""
        logging.info("Starting task monitoring")
        try:
            for task in self.tasks:
                logging.info(f"Starting task {task.id}: {task.name}")
                thread = threading.Thread(target=task.run)
                thread.start()

            # Wait for all tasks to complete
            for task in self.tasks:
                if not task.completed or (task.id == 1 and os.getpid() != 0):
                    logging.warning(f"Task {task.id}: {task.name} did NOT complete on time")
                    continue
                else:
                    logging.info(f"Task {task.id}: {task.name} completed on time")

            logging.info("Monitoring completed successfully")
        except Exception as e:
            logging.error(f"Error in monitoring loop: {str(e)}")
            sys.exit(1)

if __name__ == "__main__":
    manager = TaskManager()
    manager.create_monitoring(priority_range=[0.1, 0.2, 0.3], duration_range=[5, 10])
    manager.start_monitoring()

import concurrent.futures
import threading

class ThreadPool:
    def __init__(self, max_workers):
        self.max_workers = max_workers
        self.queue = []

    def worker(self, func, *args, **kwargs):
        try:
            return func(*args, **kwargs)
        except Exception as e:
            print(f"Exception in thread: {e}")

    def submit(self, func, *args, **kwargs):
        if len(self.queue) < self.max_workers:
            threading.Thread(target=self.worker, args=(func, ) + args, kwargs=kwargs).start()
            return
        else:
            self.queue.append((func, args, kwargs))
            # Process the queue

    def process_queue(self):
        for func, args, kwargs in self.queue:
            with concurrent.futures.ThreadPoolExecutor(max_workers=self.max_workers) as executor:
                result = executor.submit(func, *args, **kwargs)
                print(f"Result: {result}")

def example_func(x):
    # Simulate some work
    return x * 2

if __name__ == "__main__":
    pool = ThreadPool(5)

    # Submit tasks to the thread pool
    for i in range(10):
        pool.submit(example_func, i)

    # Process the queue
    while len(pool.queue) > 0:
        pool.process_queue()

    print("Thread Pool: All tasks completed")

