import random

def generate_otp(n=10):
    """Generate an n-digit random OTP."""
    return str(random.randint(0, 10**n - 1))

def verify_otp(otp, generated_otp):
    """Verify if the provided OTP matches the generated one."""
    return otp == generated_otp

def login(username, password):
    failed_attempts = 0
    max_failed_attempts = 5

    # Generate initial OTP and store it
    current_otp = generate_otp()

    while True:
        try:
            if verify_otp(input("Enter OTP: "), current_otp):
                print("Login successful!")
                break

            failed_attempts += 1
            input("Enter the corresponding password for this OTP to reset the counter...")

            if failed_attempts >= max_failed_attempts:
                raise Exception("Account locked due to too many failed attempts.")

            # Reset failed_attempts and generate a new OTP for next attempt
            failed_attempts = 0
            current_otp = generate_otp()
        except Exception as e:
            print(f"Error: {e}. Please try again.")

import time
from datetime import datetime, timedelta

class RateLimiter:
    def __init__(self, limit=100, period=3600): # default to 100 requests/hour
        self.limit = limit
        self.period = period
        self.requests = 0
        self.start_time = datetime.now()

    def is_limited(self):
        if (datetime.now() - self.start_time) > timedelta(seconds=self.period):
            self.reset()

        elif self.requests >= self.limit:
            time.sleep((datetime.now() - self.start_time).total_seconds())
            return self.is_limited()  # try again after sleeping for the difference

        else:
            self.requests += 1
            return False

    def reset(self):
        self.start_time = datetime.now()
        self.requests = 0

import pip
from pip import freeze
import os
import platform

def get_major_version(package):
    """Get the major version of a package."""
    version = freeze(package)
    return int(version.split()[0])

def get unstaged packages():
    """Return list of unstaged packages to update."""
    try:
        # Get all installed packages and their versions
        pip_packages = {}
        for p in dir(pip.__main__):
            if '__version__' in dir(getattr(pip, p)):
                version = getattr(pip, p).__version__
                pip_packages[p] = {
                    'name': p,
                    'version': version[1:-1].split('.')[0],
                    'is_conda': False
                }

        # Get conda packages
        try:
            pipconda = pip._internal.pipCONDA
            for p in dir(pipconda):
                if isinstance(getattr(pipconda, p), str) and not hasattr(getattr(pipconda, p), '__version__'):
                    version = getattr(pipconda, p)
                    pip_packages[p] = {
                        'name': p,
                        'version': version.split()[-1],
                        'is_conda': True
                    }
        except Exception:
            pass

        return list(pip_packages.keys())

    except Exception as e:
        print(f"Error checking packages: {e}")
        return []

def get package versions(package):
    """Get the latest available version of a package."""
    try:
        return pip.download(package, raise_on_missing=True).split()[-1]
    except Exception as e:
        return None

def main():
    # List of packages to consider updating
    packages_to_update = [
        'requests',
        'python-dotenv',
        'pytz',
        'websockets',
        'flask-crypto'
    ]

    # Get latest versions and check for updates
    updated_packages = []
    for package in packages_to_update:
        current_version = get_major_version(package)
        try:
            latest_version = int(get_package_versions(package))
        except Exception as e:
            print(f"Error checking version of {package}: {e}")
            continue

        if latest_version > current_version or not current_version:
            print(f"{package} is out of date (v{current_version} -> v{latest_version}). Updating...")
            updated_packages.append(package)

    # Perform the updates
    try:
        pip.update(updated_packages, force=True)
        print("Dependencies have been successfully updated.")

        # Optional: Use pip freezelock to isolate dependencies
        pipfreeze = os.path.expanduser(os.path.join(os.path.dirname(__file__), 'dependency_freeze.txt'))
        if platform.system().lower() == 'windows':
            pipreeze(' '.join(updated_packages), out=f'{os.path.dirname(os.path.basename(__file__)))}/')
        else:
            pipreeze(' '.join(updated_packages))

    except Exception as e:
        print(f"Error performing updates: {e}")

if __name__ == '__main__':
    main()

