from collections import OrderedDict

class Cache:
    def __init__(self, max_size):
        self.cache = OrderedDict()
        self.max_size = max_size

    def get(self, key):
        try:
            value = self.cache.pop(key)
            self.cache[key] = value # Move the accessed item to the end of the dictionary
            return value
        except KeyError:
            return -1 # or None, or any other sentinel value that makes sense in your context

    def put(self, key, value):
        try:
            self.cache.pop(key)
        except KeyError:
            if len(self.cache) >= self.max_size:
                self.cache.popitem(last=False) # Remove the least recently used item from cache
        self.cache[key] = value

