from urllib.parse import urlparse, parse_qs

def secure_webhook_handler(params, content_type):
    # Rate limiting configuration
    max_requests = 5
    last_request_time = time.time() - 60  # Limit to 1 per minute

    try:
        # Sanitize input parameters
        sanitized_params = {k: html.escape(v) for k, v in params.items()}

        # Determine if it's form data or JSON
        contentType = content_type.strip().lower()
        if contentType == 'form-data':
            formData = parse_qs(urlparse(params).geturl())
            params_list = []
            for key in formData:
                if isinstance(formData[key], str):
                    params_list.extend(formData[key])
                else:
                    try:
                        # Attempt to convert non-string values to string
                        params_list.append(str(formData[key]))
                    except TypeError:
                        pass
        elif contentType == 'application/json':
            json_data = json.loads(params)
        else:
            raise ValueError("Unsupported content type")

        # Now send the request with sanitized data and correct content type
        headers = {
            'Content-Type': f'application/{contentType.lower() if contentType else "html"}',
            'Content-Length': str(len(json.dumps(json_data)) if contentType == 'application/json' else len(params)),
        }

        # Rate limiting logic
        current_time = time.time()
        if (current_time - last_request_time) < max_requests:
            time.sleep(1)
            return f"Request rate-limited. Trying again in 1 second."

        response = f"Request received with {len(json_data)} parameters or {len(params)} query params"
        # Simulate API response
        return f"Webhook Response: {response}"

    except json.JSONDecodeError:
        return "Invalid JSON payload"
    except Exception as e:
        return f"Error processing request: {str(e)}"

