def has_null_or_empty(value):
    # Check for None (null)
    if isinstance(value, type(None)):
        return True

    # Check for strings that are empty
    if isinstance(value, str) and len(value) == 0:
        return True

    # Check for empty lists or tuples
    if isinstance(value, (list, tuple)) and not value:
        return True

    # Check for dictionaries with no keys
    if isinstance(value, dict) and not value:
        return True

    # Check for bytes-like objects that are empty
    if isinstance(value, (bytes, bytearray)) and len(value) == 0:
        return True

    # If none of the above, return False
    return False

import logging
from functools import wraps
from threading import Thread

# Configure logging
logging.basicConfig(level=logging.INFO)

def retry(exceptions, tries=5):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(tries):
                try:
                    return func(*args, **kwargs)
                except exceptions as e:
                    if attempt < tries - 1:
                        logging.warning(f"Attempt {attempt + 1} failed: {e}")
                        time.sleep(0.5)  # wait for half a second before retrying
                    else:
                        raise
        return wrapper
    return decorator

class TaskFailureHandler:
    def __init__(self, task_id):
        self.task_id = task_id
        self.num_attempts = 0

    def handle_failure(self, exception):
        logging.warning(f"Task {self.task_id} failed with exception: {exception}")
        self.num_attempts += 1
        if self.num_attempts < 5:
            self.num_attempts = 0
            # retry the task after a certain delay
            time.sleep(0.5)
        else:
            # log and alert the failure, do not retry
            logging.error(f"Task {self.task_id} failed after 5 attempts")

