class User:
    def __init__(self, username):
        self.username = username
        self.roles = set()

    def add_role(self, role):
        self.roles.add(role)

    def remove_role(self, role):
        self.roles.discard(role)


class Role:
    def __init__(self, name):
        self.name = name

    def get_users(self):
        return [user.username for user in users if self in user.roles]


class RBAC:
    def __init__(self):
        self.users = {}
        self.roles = {}

    def create_user(self, username):
        if username not in self.users:
            self.users[username] = User(username)

    def create_role(self, name):
        if name not in self.roles:
            self.roles[name] = Role(name)

    def add_user_to_role(self, username, role_name):
        if username in self.users and role_name in self.roles:
            self.users[username].add_role(self.roles[role_name])

    def remove_user_from_role(self, username, role_name):
        if username in self.users and role_name in self.roles:
            self.users[username].remove_role(self.roles[role_name])

    def get_users_with_role(self, role_name):
        return self.roles.get(role_name, {}).get_users()


# Example usage
rbac = RBAC()

# Create roles
admin = rbac.create_role("Admin")
moderator = rbac.create_role("Moderator")

# Create users and assign roles
admin_user = rbac.create_user("admin")
admin_user.add_role(admin)
moderator_user = rbac.create_user("moderator")
admin_user.add_role(moderator)

# Get users with a specific role
print(rbac.get_users_with_role("Admin"))  # Output: ["admin"]

