def validate_sender(email_msg):
    try:
        _, from_header = decode_header(email_msg.get_header('From'))
    except ValueError:
        return False  # Invalid format or missing 'From' header

    parts = from_header.split('@')
    if len(parts) != 2:
        return False
    local_part = parts[1].strip()

    try:
        validator = EmailLocalPartValidator()
        valid = validator.validate(EmailAddressValidatorType('address', 'address'))
    except Invalid as e:
        return False

    # Check display name has at least two words (first and last)
    display_name = from_header.strip().lower()
    if not re.match(r'^[a-z][a-z0-9._%+-]+@[a-z._%+]+(\.[a-z]{2,4})+$', display_name):
        return False

    # Split the display name into parts
    name_parts = re.split(r'\s+', display_name)
    if len(name_parts) < 2:
        return False

    return True

import xml.etree.ElementTree as ET

def parse_xml(file):
    # create element tree object 
    tree = ET.parse(file)  

    # get root element 
    root = tree.getroot()

    for book in root:
        print('Book Id:', book.attrib['id'])
        for elem in book:
            if not elem.text:
                text = "None"
            else:
                text = elem.text

            if elem.tag == 'title':
                print('Title:', text)
            elif elem.tag == 'genre':
                print('Genre:', text)
            elif elem.tag == 'author':
                print('Author:', text)
            elif elem.tag == 'price':
                print('Price:', text, '\n') 

