import sqlite3

class DatabaseTransaction:
    def __init__(self, conn):
        self.conn = conn
        self.cursor = conn.cursor()

    def start_transaction(self):
        self.cursor.execute("BEGIN TRANSACTION")

    def commit_transaction(self):
        self.cursor.execute("COMMIT")

    def rollback_transaction(self):
        self.cursor.execute("ROLLBACK")

def search_with_pagination(data, query, page_size=10):
    # Filter data based on query (you can replace this part with any filtering logic)
    filtered_data = [item for item in data if query.lower() in str(item).lower()]

    # Calculate total pages
    total_pages = (len(filtered_data) + page_size - 1) // page_size

    while True:
        try:
            current_page = int(input("Enter the page number (total pages: {}): ".format(total_pages)))
            if 1 <= current_page <= total_pages:
                break
            else:
                print("Invalid page number. Please enter a valid page number.")
        except ValueError:
            print("Please enter a number.")

    # Calculate start and end indices for slicing the data
    start = (current_page - 1) * page_size
    end = current_page * page_size

    return filtered_data[start:end]

import re

class CouponCodeValidator:
    def __init__(self, min_length=5, max_length=20):
        self.min_length = min_length
        self.max_length = max_length
        self.valid_codes = ["COUPON10", "DISCOUNT15"]

    def validate_code(self, code):
        if not isinstance(code, str) or len(code) < self.min_length or len(code) > self.max_length:
            return False

        for char in code:
            if not char.isalnum():
                return False

        if re.match(r"[A-Z]{1,2}", code):
            return True
        else:
            return False

    def check_validity(self, code):
        if code in self.valid_codes:
            return "Valid"
        elif self.validate_code(code):
            return "Valid"
        else:
            return "Invalid"

# Example usage
validator = CouponCodeValidator()

print(validator.check_validity("COUPON10"))  # Output: Valid
print(validator.check_validity("DISCOUNT15"))  # Output: Valid
print(validator.check_validity("notacouponcode"))  # Output: Invalid
print(validator.check_validity(12345))  # Output: Invalid

