# Define decorator to handle logging events
@click.command('log')
@click.argument('event_type', type=click.Choice(['visit', 'pageview', 'purchase', 'error']))
def log_event(event_type):
    # Function to capture and write logs
    def handler(func):
        @flask.route('/')
        def visit():
            flask.request.ip = flask.request.ip  # Get the user's IP address
            flask.session.permanent = True
            flask.permanent_session_lifetime = None

            with open(os.path.join('analytics', 'visits.log'), 'a') as f:
                f.write(f"Visit from {flask.request.ip}\n")

            session.permanent = True  # This is important for cookies
            return redirect(url_for('home'))

        @flask.route('/visit')
        def pageview():
            path = flask.request.path

            with open(os.path.join('analytics', 'pageviews.log'), 'a') as f:
                if not os.path.exists(os.path.join('analytics', 'visits_dict')):
                    visits_dict = {}
                # Get the visit type from URL or cookie
                try:
                    visit_type = path.split('/')[-1]
                except IndexError:
                    visit_type = ''

                visits_dict[visit_type] += 1

            session.permanent = True
            return redirect(url_for('home'))

        @flask.route('/purchase')
        def purchase():
            with open(os.path.join('analytics', 'purchases.log'), 'a') as f:
                f.write(f"Purchase from {flask.request.ip}\n")

            session.permanent = True
            return redirect(url_for('home'))

        if func == visit or func == pageview or func == purchase:
            flask.permanent_session_lifetime = None  # Reset the session timeout

    return handler


# Handle errors and exceptions
@app.errorhandler(Exception)
def error(error):
    stackTrace = flask.request.get_flask_error_exception()
    stackTrace.print_exc()

    if not isinstance(flask.request, flask.requesting.Request):
        return flask.jsonify({'error': 'Request is not a proper Flask request'}), 403

    with open(os.path.join('analytics', 'errors.log'), 'a') as f:
        log_entry = {
            'datetime': flask.request.time(),
            'path': flask.request.path,
            'remote_addr': flask.request.remote_addr,
            'request': flask.request.get_flask_request().method,
            'status': flask.request.status,
            'error': str(error)
        }

        # Write the raw stack trace
        f.write(str(stackTrace))

    return flask.jsonify(log_entry), error_code

