import json

def load_config(filepath):
    try:
        with open(filepath) as f:
            config = json.load(f)
    except (json.JSONDecodeError, IOError) as e:
        print("Error parsing configuration file:", e)
        return None

    # Validate the configuration data
    if not isinstance(config, dict):
        print("Invalid configuration file: expected dictionary")
        return None

    for key, value in config.items():
        if not isinstance(value, str):
            print("Invalid configuration value for", key)
            return None

    # Return the validated configuration data
    return config

class SmartContract(object):
    def __init__(self, owner, arbiter, beneficiary, value):
        self.owner = owner
        self.arbiter = arbiter
        self.beneficiary = beneficiary
        self.value = value
        self.deadline = 0
        self.amountPaid = 0

    def pay(self, amount):
        assert(msg.sender == self.owner)
        self.amountPaid += amount
        return True

    def claimBeneficiary(self):
        if (now > self.deadline and msg.sender == self.arbiter) or (self.amountPaid >= self.value):
            selfdestruct(self.beneficiary)

    def refundOwner(self):
        assert(now > self.deadline and self.amountPaid < self.value)
        selfdestruct(self.owner)

