    cursor = conn.cursor()
    cursor.execute("SELECT name FROM employees")
    rows = cursor.fetchall()
    for row in rows:
        print(f"Employee: {row[0]}")

def main():
    with sqlite3.connect('database.db') as conn:
        # Check if the connection is already in a transaction
        if not conn._connection.is_transactional():
            conn._connection.begin()

        try:
            execute_read_only_query(conn)
        finally:
            pass

        user_action = input("Commit (w) or exit (e)? ").strip().lower()
        if user_action == 'w':
            conn.commit()
        else:
            conn.rollback()

