import os
from PIL import Image

def load_image(filepath):
    if not os.path.isfile(filepath):
        raise ValueError("File does not exist")

    # Check if the file is an image (based on extension)
    valid_extensions = ['.png', '.jpg', '.jpeg', '.bmp', '.gif']
    _, ext = os.path.splitext(filepath)
    if ext.lower() not in valid_extensions:
        raise ValueError("File is not an image")

    try:
        img = Image.open(filepath)
        return img
    except IOError:
        raise ValueError("Unable to open the file as an image")

import hashlib

def validate_backup(backup_file):
    with open(backup_file, 'rb') as f:
        data = f.read()

    expected_hash = calculate_expected_hash(data)

    actual_hash = hashlib.sha256(data).hexdigest()

    if actual_hash == expected_hash:
        print("Backup is valid")
    else:
        print("Backup is invalid")

def calculate_expected_hash(data):
    # Calculate the expected hash of the data using a secure hashing algorithm such as SHA-256
    return hashlib.sha256(data).hexdigest()

import os
from datetime import datetime, timedelta

current_time = datetime.now()
seven_days_ago = current_time - timedelta(days=7)
thirty_days_ago = current_time - timedelta(days=30)

# Function to delete logs older than a certain time
def delete_old_logs(target_time):
    for f in glob.glob("path/to/logfiles/**/*"):
        mtime = os.path.getmtime(f)
        ct = datetime.fromtimestamp(mtime)
        if ct < target_time:
            try:
                os.remove(f)
            except OSError as e:
                pass

# Step 1: Remove logs older than 30 days
delete_old_logs(thirty_days_ago)

# Step 2: Remove logs that are older than seven days from now (within the last 30 days)
for f in glob.glob("path/to/logfiles/**/*"):
    mtime = os.path.getmtime(f)  # Get modified time, but using getctime might be more appropriate
    ct = datetime.fromtimestamp(mtime)
    if current_time - ct > timedelta(days=7):
        try:
            os.remove(f)
        except OSError as e:
            pass

# After these steps, only the logs from the last seven days remain.

