import re

# Safe patterns to match against
safe_patterns = [r'\d+', r'[A-Za-z]+'] # add more patterns as needed

def is_output_safe(parsed):
    for pattern in safe_patterns:
        if re.search(pattern, parsed) is not None:
            return False  # It seems that the output contains harmful data
    return True  # The output seems to be safe

